-- MarketOps baseline 1/4: structure.
-- Schemas, the btree_gist extension, types, functions and tables with their columns,
-- defaults, NOT NULL and CHECK definitions, plus column comments.
--
-- The four baseline files V0001-V0004 run in order and together replace the former
-- migrations V0001-V0124 (consolidated 2026-09-22). New schema changes start at V0005.
--
-- Produced by applying the former migrations with Flyway to an empty database created by
-- infra/compose and dumping it with pg_dump 18.4 (no owners; privileges and seed rows kept),
-- with pg_dump's per-object comment headers removed and seed rows grouped per table.
-- Runs as marketops_migration, which therefore owns every object, exactly as before.
-- Roles, database privileges and the public-schema privileges come from
-- infra/compose/postgres-init, not from these files.

SET LOCAL statement_timeout = 0;
SET LOCAL lock_timeout = 0;
SET LOCAL idle_in_transaction_session_timeout = 0;
SET LOCAL transaction_timeout = 0;
SET LOCAL client_encoding = 'UTF8';
SET LOCAL standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', true);
SET LOCAL check_function_bodies = false;
SET LOCAL xmloption = content;
SET LOCAL client_min_messages = warning;
SET LOCAL row_security = off;

CREATE SCHEMA core;

CREATE SCHEMA iam;

CREATE SCHEMA ledger;

CREATE SCHEMA mart;

CREATE SCHEMA ops;

CREATE SCHEMA platform;

CREATE SCHEMA raw;

CREATE SCHEMA staging;

CREATE EXTENSION IF NOT EXISTS btree_gist WITH SCHEMA public;

CREATE TYPE platform.call_authority_grant AS (
	decision_id uuid,
	job_id uuid,
	run_id uuid,
	fence_token bigint,
	lease_owner text,
	platform_code text,
	endpoint_id uuid,
	credential_id uuid,
	scope_grant_id uuid,
	call_seq integer,
	granted_at timestamp with time zone,
	call_authority_expires_at timestamp with time zone,
	run_lease_expires_at timestamp with time zone,
	server_policy_deadline timestamp with time zone,
	control_epoch_scopes text[],
	control_epoch_values bigint[],
	boundary_set_digest text
);

CREATE TYPE platform.call_control_evaluation AS (
	credential_id uuid,
	valid_until timestamp with time zone,
	boundary_kind_count integer,
	boundary_kind_set text[],
	boundary_set_digest text,
	winning_kind text
);

CREATE TYPE platform.control_boundary_row AS (
	boundary_kind text,
	boundary_at timestamp with time zone,
	source_table text,
	source_column text,
	source_row_id uuid,
	selection_reason text
);

CREATE TYPE platform.control_scope AS (
	scope_kind text,
	scope_id uuid
);

CREATE TYPE platform.control_snapshot_temporal AS (
	valid_until timestamp with time zone,
	boundary_kind_count integer,
	boundary_kind_set text[],
	boundary_set_digest text,
	winning_kind text
);

CREATE FUNCTION core.ad_freshness_purpose_violations(p_organization_id uuid, p_at timestamp with time zone) RETURNS text[]
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'core', 'pg_temp'
    AS $$
    WITH live AS (
        SELECT f.evidence_kind,
               f.decision_purpose,
               coalesce(f.source_max_age_minutes, 2147483647) AS source_age,
               coalesce(f.accepted_fact_max_age_minutes, 2147483647) AS accepted_age,
               f.requires_window_complete::integer AS window_rank,
               f.requires_correction_window_closed::integer AS correction_rank,
               CASE f.minimum_confidence_state
                   WHEN 'UNKNOWN' THEN 1
                   WHEN 'ESTIMATED_EXPLAINED' THEN 2
                   WHEN 'CANONICAL_PENDING_SETTLEMENT' THEN 3
                   ELSE 4
               END AS confidence_rank
          FROM core.ad_freshness_profile AS f
         WHERE f.organization_id = p_organization_id
           AND f.status IN ('ACTIVE', 'RETIRED')
           AND f.effective_from <= p_at
           AND (f.effective_to IS NULL OR f.effective_to > p_at)
    ),
    -- A write purpose and the recommendation purpose that feeds it. The write
    -- side must be at least as strict on every dimension.
    ordered AS (
        SELECT * FROM (VALUES
            ('PROTECTION_RECOMMENDATION', 'PROTECTION_BID_WRITE'),
            ('OPTIMIZATION_RECOMMENDATION', 'OPTIMIZATION_BID_WRITE'),
            ('QUEUE_OBSERVATION', 'TASK_ACTIVATION'),
            ('TASK_ACTIVATION', 'PROTECTION_RECOMMENDATION'),
            ('TASK_ACTIVATION', 'OPTIMIZATION_RECOMMENDATION'),
            ('PROTECTION_BID_WRITE', 'EXACT_COMPENSATION')
        ) AS pairs(weaker_purpose, stronger_purpose)
    )
    SELECT coalesce(
        array_agg(DISTINCT
            ordered.weaker_purpose || '>' || ordered.stronger_purpose
            ORDER BY ordered.weaker_purpose || '>' || ordered.stronger_purpose),
        '{}')
      FROM ordered
      JOIN live AS weaker
        ON weaker.decision_purpose = ordered.weaker_purpose
      JOIN live AS stronger
        ON stronger.decision_purpose = ordered.stronger_purpose
       AND stronger.evidence_kind = weaker.evidence_kind
     WHERE stronger.source_age > weaker.source_age
        OR stronger.accepted_age > weaker.accepted_age
        OR stronger.window_rank < weaker.window_rank
        OR stronger.correction_rank < weaker.correction_rank
        OR stronger.confidence_rank < weaker.confidence_rank
$$;

CREATE FUNCTION core.ad_outcome_bound_policy_resolution(p_organization_id uuid, p_platform_code text, p_store_id uuid, p_direction text, p_cause_code text, p_at timestamp with time zone, p_bound_policy uuid) RETURNS TABLE(state text, policy_id uuid, policy_version integer)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'core', 'pg_temp'
    AS $$
 SELECT CASE WHEN r.state='RESOLVED' AND r.policy_id IS DISTINCT FROM p_bound_policy
     THEN 'OUTCOME_POLICY_UNRESOLVED' ELSE r.state END,
  CASE WHEN r.state='RESOLVED' AND r.policy_id=p_bound_policy THEN r.policy_id END,
  CASE WHEN r.state='RESOLVED' AND r.policy_id=p_bound_policy THEN r.policy_version END
 FROM core.ad_outcome_policy_resolution(p_organization_id,p_platform_code,p_store_id,p_direction,p_cause_code,p_at) r
$$;

CREATE FUNCTION core.ad_outcome_policy_resolution(p_organization_id uuid, p_platform_code text, p_store_id uuid, p_direction text, p_cause_code text, p_at timestamp with time zone) RETURNS TABLE(state text, policy_id uuid, policy_version integer)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'core', 'pg_temp'
    AS $$
 WITH applicable AS MATERIALIZED (
  SELECT p.*,CASE p.scope_kind WHEN 'STORE' THEN 0 WHEN 'PLATFORM' THEN 1 ELSE 2 END geo_rank,
   CASE WHEN p.cause_code IS NULL THEN 1 ELSE 0 END cause_rank
  FROM core.ad_outcome_policy p WHERE p.organization_id=p_organization_id AND p.direction=p_direction
   AND (p.cause_code IS NULL OR p.cause_code=p_cause_code)
   AND p.status IN('ACTIVE','RETIRED') AND p.effective_from<=p_at
   AND (p.effective_to IS NULL OR p.effective_to>p_at)
   AND (p.scope_kind='ORGANIZATION' OR (p.scope_kind='PLATFORM' AND p.platform_code=p_platform_code)
    OR (p.scope_kind='STORE' AND p.platform_code=p_platform_code AND p.store_ref_id=p_store_id))
 ), maxima AS MATERIALIZED (
  SELECT p.* FROM applicable p WHERE NOT EXISTS(SELECT 1 FROM applicable n
   WHERE n.geo_rank<=p.geo_rank AND n.cause_rank<=p.cause_rank
    AND (n.geo_rank<p.geo_rank OR n.cause_rank<p.cause_rank))
 ), resolution AS (
  SELECT CASE WHEN (SELECT count(*) FROM maxima)>1 THEN 'OUTCOME_POLICY_CONFLICTED'
   WHEN (SELECT count(*) FROM maxima)=1 AND EXISTS(SELECT 1 FROM maxima p
    WHERE p.critical_unit_definition_complete
     AND num_nonnulls(p.material_profit_delta,p.material_profit_per_rub_delta,p.sales_preservation_tolerance_ratio,
      p.non_worsening_profit_band,p.non_worsening_per_rub_band,p.minimum_ad_spend_denominator,
      p.comparison_scale,p.comparison_rounding_mode,p.material_boundary_inclusive,p.negative_profit_terminal)=10
     AND p.negative_profit_terminal='KEEP_PROTECTION_OPEN') THEN 'RESOLVED'
   ELSE 'OUTCOME_POLICY_UNRESOLVED' END state
 ) SELECT r.state,CASE WHEN r.state='RESOLVED' THEN p.id END,
     CASE WHEN r.state='RESOLVED' THEN p.policy_version END
 FROM resolution r LEFT JOIN maxima p ON r.state='RESOLVED'
$$;

CREATE FUNCTION core.ad_qualification_tier_is_monotonic(p_organization_id uuid, p_scope_kind text, p_platform_code text, p_store_ref_id uuid, p_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'core', 'pg_temp'
    AS $$
    WITH tiers AS (
        SELECT p.purpose_tier,
               CASE p.purpose_tier
                   WHEN 'WATCH' THEN 1
                   WHEN 'OPTIMIZATION_TASK' THEN 2
                   WHEN 'OPTIMIZATION_RECOMMENDATION' THEN 3
                   ELSE 4
               END AS rank,
               p.minimum_source_coverage_ratio,
               p.minimum_affected_set_coverage_ratio,
               p.minimum_traffic_denominator,
               p.minimum_completed_sale_events,
               p.minimum_retained_sale_events,
               p.minimum_spend_amount,
               p.minimum_sustained_periods,
               p.minimum_recoverable_amount,
               CASE p.minimum_confidence_state
                   WHEN 'UNKNOWN' THEN 1
                   WHEN 'ESTIMATED_EXPLAINED' THEN 2
                   WHEN 'CANONICAL_PENDING_SETTLEMENT' THEN 3
                   ELSE 4
               END AS confidence_rank,
               p.requires_correction_window_closed::integer AS correction_rank,
               p.requires_comparable_baseline::integer AS baseline_rank
          FROM core.ad_optimization_qualification_policy AS p
         WHERE p.organization_id = p_organization_id
           AND p.scope_kind = p_scope_kind
           AND p.platform_code IS NOT DISTINCT FROM p_platform_code
           AND p.store_ref_id IS NOT DISTINCT FROM p_store_ref_id
           AND p.status IN ('ACTIVE', 'RETIRED')
           AND p.effective_from <= p_at
           AND (p.effective_to IS NULL OR p.effective_to > p_at)
    )
    -- Three, not four. The count is over the join below, which yields one row
    -- per adjacent pair, so four present tiers make three pairs and a missing
    -- tier removes the pair that would have named it.
    SELECT count(DISTINCT lower_tier.rank) = 3
       AND bool_and(
               lower_tier.minimum_source_coverage_ratio
                   <= higher_tier.minimum_source_coverage_ratio
           AND lower_tier.minimum_affected_set_coverage_ratio
                   <= higher_tier.minimum_affected_set_coverage_ratio
           AND lower_tier.minimum_traffic_denominator
                   <= higher_tier.minimum_traffic_denominator
           AND lower_tier.minimum_completed_sale_events
                   <= higher_tier.minimum_completed_sale_events
           AND lower_tier.minimum_retained_sale_events
                   <= higher_tier.minimum_retained_sale_events
           AND lower_tier.minimum_spend_amount <= higher_tier.minimum_spend_amount
           AND lower_tier.minimum_sustained_periods
                   <= higher_tier.minimum_sustained_periods
           AND lower_tier.minimum_recoverable_amount
                   <= higher_tier.minimum_recoverable_amount
           AND lower_tier.confidence_rank <= higher_tier.confidence_rank
           AND lower_tier.correction_rank <= higher_tier.correction_rank
           AND lower_tier.baseline_rank <= higher_tier.baseline_rank)
      FROM tiers AS lower_tier
      JOIN tiers AS higher_tier ON higher_tier.rank = lower_tier.rank + 1
$$;

CREATE FUNCTION core.check_ad_human_slo_strength() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'core', 'pg_temp'
    AS $$ BEGIN
 IF EXISTS(SELECT 1 FROM core.ad_human_slo_profile protection JOIN core.ad_human_slo_profile optimization
  ON optimization.organization_id=protection.organization_id
  AND optimization.lane='OPTIMIZATION' AND optimization.status='ACTIVE'
  AND tstzrange(optimization.effective_from,optimization.effective_to,'[)') && tstzrange(protection.effective_from,protection.effective_to,'[)')
  WHERE protection.organization_id=NEW.organization_id AND protection.lane='PROTECTION' AND protection.status='ACTIVE'
  AND (protection.acknowledgement_minutes>optimization.acknowledgement_minutes
    OR protection.action_minutes>optimization.action_minutes OR protection.escalation_minutes>optimization.escalation_minutes
    OR optimization.staffed_coverage_enabled AND (NOT protection.staffed_coverage_enabled
      OR protection.staffed_coverage_timezone<>optimization.staffed_coverage_timezone
      OR EXISTS(SELECT 1 FROM generate_series(0,1439) minute WHERE
       (CASE WHEN optimization.staffed_coverage_start_minute<optimization.staffed_coverage_end_minute
         THEN minute>=optimization.staffed_coverage_start_minute AND minute<optimization.staffed_coverage_end_minute
         ELSE minute>=optimization.staffed_coverage_start_minute OR minute<optimization.staffed_coverage_end_minute END)
       AND NOT(CASE WHEN protection.staffed_coverage_start_minute<protection.staffed_coverage_end_minute
         THEN minute>=protection.staffed_coverage_start_minute AND minute<protection.staffed_coverage_end_minute
         ELSE minute>=protection.staffed_coverage_start_minute OR minute<protection.staffed_coverage_end_minute END))))) THEN
  RAISE EXCEPTION 'Protection response and coverage cannot be weaker than Optimization' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;

SET LOCAL default_tablespace = '';

SET LOCAL default_table_access_method = heap;

CREATE TABLE core.platform_listing_scope_observation (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    platform_listing_id uuid NOT NULL,
    provenance_id uuid NOT NULL,
    scope_kind text NOT NULL,
    native_scope_key text NOT NULL,
    native_variant_keys text[] NOT NULL,
    coverage_state text NOT NULL,
    expected_member_count integer,
    continuation_reference text,
    source_reference text NOT NULL,
    scope_basis_reference text CONSTRAINT platform_listing_scope_observati_scope_basis_reference_not_null NOT NULL,
    observed_at timestamp with time zone NOT NULL,
    recorded_at timestamp with time zone NOT NULL,
    verification_expires_at timestamp with time zone CONSTRAINT platform_listing_scope_observa_verification_expires_at_not_null NOT NULL,
    CONSTRAINT platform_listing_scope_observation_check CHECK (((observed_at <= recorded_at) AND (verification_expires_at > recorded_at))),
    CONSTRAINT platform_listing_scope_observation_check1 CHECK (((coverage_state <> 'COMPLETE'::text) OR ((expected_member_count IS NOT NULL) AND (expected_member_count = cardinality(native_variant_keys)) AND (continuation_reference IS NULL)))),
    CONSTRAINT platform_listing_scope_observation_check2 CHECK (((scope_kind <> 'NATIVE_VARIANT'::text) OR ((cardinality(native_variant_keys) = 1) AND (native_variant_keys[1] = native_scope_key)))),
    CONSTRAINT platform_listing_scope_observation_coverage_state_check CHECK ((coverage_state = ANY (ARRAY['COMPLETE'::text, 'PARTIAL'::text, 'UNKNOWN'::text]))),
    CONSTRAINT platform_listing_scope_observation_expected_member_count_check CHECK (((expected_member_count >= 0) AND (expected_member_count <= 4096))),
    CONSTRAINT platform_listing_scope_observation_native_scope_key_check CHECK (((length(btrim(native_scope_key)) >= 1) AND (length(btrim(native_scope_key)) <= 512))),
    CONSTRAINT platform_listing_scope_observation_native_variant_keys_check CHECK ((cardinality(native_variant_keys) <= 4096)),
    CONSTRAINT platform_listing_scope_observation_scope_basis_reference_check CHECK (((length(btrim(scope_basis_reference)) >= 1) AND (length(btrim(scope_basis_reference)) <= 512))),
    CONSTRAINT platform_listing_scope_observation_scope_kind_check CHECK ((scope_kind = ANY (ARRAY['WHOLE_LISTING'::text, 'NATIVE_VARIANT'::text]))),
    CONSTRAINT platform_listing_scope_observation_source_reference_check CHECK (((length(btrim(source_reference)) >= 1) AND (length(btrim(source_reference)) <= 512)))
);

CREATE FUNCTION core.current_listing_scope_observation(p_listing uuid, p_at timestamp with time zone) RETURNS core.platform_listing_scope_observation
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT s FROM core.platform_listing_scope_observation s
 WHERE s.platform_listing_id=p_listing AND s.scope_kind='WHOLE_LISTING'
   AND s.observed_at<=p_at AND s.recorded_at<=p_at
 ORDER BY s.observed_at DESC,s.recorded_at DESC,s.id DESC LIMIT 1
$$;

CREATE FUNCTION core.enforce_availability_policy_version_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- PostgreSQL presents a stored generated column as NULL in NEW before it
    -- recomputes it. scope_key is derived wholly from immutable columns, so it
    -- is deliberately excluded alongside the two controlled lifecycle fields.
    IF (to_jsonb(NEW) - 'status' - 'effective_to' - 'scope_key')
       IS DISTINCT FROM (to_jsonb(OLD) - 'status' - 'effective_to' - 'scope_key') THEN
        RAISE EXCEPTION 'published availability policy version is immutable'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'availability_policy_version_immutable_ck';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION core.guard_promotion_finance_listing_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NEW.promotion_listing_ref_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM core.platform_listing l
     WHERE l.id=NEW.promotion_listing_ref_id AND l.organization_id=NEW.organization_id AND l.store_id=NEW.store_ref_id) THEN
  RAISE EXCEPTION 'promotion finance input must name its exact Listing Store' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION core.lc_action_calibration_dependencies(p_package uuid, p_kind text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    SET "DateStyle" TO 'ISO, YMD'
    AS $$
 SELECT jsonb_build_object('model','LC_ACTION_RULE_DEPENDENCIES_1','purpose',p.purpose_code,
   'actionKind',p_kind,'values',
   (SELECT jsonb_object_agg(v.category_code,jsonb_build_object('numeric',v.value_numeric,'text',v.value_text,
      'json',CASE WHEN v.category_code='DEMAND_SCENARIO_SET' THEN v.value_json-'supplyScenarios'-'economicScenarioBases' WHEN v.category_code='CRITICAL_GROUP_RULE' THEN v.value_json-'protectionScopeBases' WHEN v.category_code='NON_WORSENING_PROFIT_BOUND' THEN v.value_json-'currentAccountingComparisons' ELSE v.value_json END,'unit',v.unit_code,'windowDays',v.window_days,'evidenceReference',v.evidence_reference)
       ORDER BY v.category_code)
    FROM core.lc_calibration_value v WHERE v.package_id=p.id
      -- A versioned, closed consumer inventory: future categories cannot silently enlarge old dependencies.
      AND v.category_code IN ('MATERIAL_IMPROVEMENT_BOUND','NON_WORSENING_PROFIT_BOUND',
        'NON_WORSENING_RETURN_BOUND','CRITICAL_GROUP_RULE','DEMAND_SCENARIO_SET','FRESHNESS_RULE',
        'RESPONSIBILITY_SLO','RESPONSIBILITY_COVERAGE','ORDINARY_TRIGGER_CONTENT','MATERIAL_TRIGGER_CONTENT',
        'ORDINARY_TRIGGER_EXPOSURE','MATERIAL_TRIGGER_EXPOSURE','APPROVAL_VALIDITY',
        'REPRESENTATION_EQUIVALENCE_RULE','ALLOWANCE_AXES','ALLOWANCE_RESERVE','FORMAL_NODES','STOP_RULE',
        'CROSS_PERIOD_WINDOW','DESCRIPTION_LENGTH_RULE')
      -- Description actions never consume promotion demand scenarios. Promotion actions never
      -- serialize description text or use the description readback representation rule.
      AND NOT (p_kind='LISTING_DESCRIPTION_CHANGE' AND v.category_code='DEMAND_SCENARIO_SET')
      AND NOT (p_kind='LISTING_PROMOTION_ACTION' AND v.category_code IN
           ('DESCRIPTION_LENGTH_RULE','REPRESENTATION_EQUIVALENCE_RULE'))))
 FROM core.lc_calibration_package p WHERE p.id=p_package
  AND p_kind IN ('LISTING_DESCRIPTION_CHANGE','LISTING_PROMOTION_ACTION')
$$;

CREATE FUNCTION core.lc_action_calibration_dependencies(p_package uuid, p_kind text, p_affected_set uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT core.lc_action_calibration_dependencies(p_package,p_kind)||
  CASE WHEN s.items IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('supplyScenarios',s.items) END||
  coalesce((SELECT jsonb_build_object('currentAccountingComparison',v.value_json->'currentAccountingComparisons'->a.platform_listing_id::text)
   FROM core.lc_calibration_value v JOIN core.lc_affected_set a ON a.id=p_affected_set
   WHERE v.package_id=p_package AND v.category_code='NON_WORSENING_PROFIT_BOUND'
    AND v.value_json->'currentAccountingComparisons'->a.platform_listing_id::text IS NOT NULL),'{}'::jsonb)||
  coalesce((SELECT jsonb_build_object('economicScenarioBasis',v.value_json->'economicScenarioBases'->a.platform_listing_id::text)
   FROM core.lc_calibration_value v JOIN core.lc_affected_set a ON a.id=p_affected_set
   WHERE v.package_id=p_package AND v.category_code='DEMAND_SCENARIO_SET' AND p_kind='LISTING_PROMOTION_ACTION'
    AND v.value_json->'economicScenarioBases'->a.platform_listing_id::text IS NOT NULL),'{}'::jsonb)||
  coalesce((SELECT jsonb_build_object('protectionScopeBasis',v.value_json->'protectionScopeBases'->a.platform_listing_id::text)
   FROM core.lc_calibration_value v JOIN core.lc_affected_set a ON a.id=p_affected_set
   WHERE v.package_id=p_package AND v.category_code='CRITICAL_GROUP_RULE'
    AND v.value_json->'protectionScopeBases'->a.platform_listing_id::text IS NOT NULL),'{}'::jsonb)
 FROM (SELECT jsonb_agg(item ORDER BY item->>'productVariantId',item->>'code') AS items
  FROM core.lc_calibration_value v JOIN core.lc_affected_set a ON a.id=p_affected_set
  CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(v.value_json->'supplyScenarios')='array'
    THEN v.value_json->'supplyScenarios' ELSE '[]'::jsonb END) item
  WHERE v.package_id=p_package AND v.category_code='DEMAND_SCENARIO_SET'
    AND item->>'productVariantId'=ANY(SELECT id::text FROM unnest(a.product_variant_ids) id)) s
$$;

CREATE FUNCTION core.lc_affected_set_capture_identity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE snapshot jsonb; variant_ids uuid[]; product_ids uuid[];
BEGIN
 snapshot:=core.lc_listing_identity_snapshot(NEW.platform_listing_id,NEW.resolved_at);
 IF snapshot IS NULL OR (snapshot->>'organizationId')::uuid<>NEW.organization_id
  OR NEW.affected_set_digest<>encode(sha256(convert_to(snapshot::text,'UTF8')),'hex') THEN
  RAISE EXCEPTION 'affected-set identity changed during capture' USING ERRCODE='MO093';
 END IF;
 SELECT coalesce(array_agg((v->>'listingVariantId')::uuid ORDER BY (v->>'listingVariantId')::uuid),'{}')
  INTO variant_ids FROM jsonb_array_elements(snapshot->'members') v;
 SELECT coalesce(array_agg(DISTINCT (m->>'productVariantId')::uuid ORDER BY (m->>'productVariantId')::uuid),'{}')
  INTO product_ids FROM jsonb_array_elements(snapshot->'members') v,jsonb_array_elements(v->'mappings') m
  WHERE jsonb_array_length(v->'openConflicts')=0 AND jsonb_array_length(v->'mappings')=1;
 IF ARRAY(SELECT DISTINCT unnest(NEW.platform_listing_variant_ids) ORDER BY 1)<>variant_ids
  OR ARRAY(SELECT DISTINCT unnest(NEW.product_variant_ids) ORDER BY 1)<>product_ids THEN
  RAISE EXCEPTION 'affected-set members must equal the identity snapshot' USING ERRCODE='MO093';
 END IF;
 IF NEW.resolution_state='COMPLETE' AND (snapshot#>>'{nativeScope,state}'<>'COMPLETE'
   OR cardinality(variant_ids)=0 OR EXISTS(SELECT 1 FROM jsonb_array_elements(snapshot->'members') v
       WHERE jsonb_array_length(v->'mappings')<>1 OR jsonb_array_length(v->'openConflicts')<>0
         OR EXISTS(SELECT 1 FROM jsonb_array_elements(v->'mappings') m
             WHERE m->>'mappingStatus' NOT IN ('ACTIVE','ENDED') OR m->>'productVariantStatus'<>'ACTIVE' OR m->>'productStatus'<>'ACTIVE'))) THEN
  RAISE EXCEPTION 'complete affected set requires complete native scope and active unambiguous identities' USING ERRCODE='MO093';
 END IF;
 NEW.native_scope_observation_id:=(core.current_listing_scope_observation(NEW.platform_listing_id,NEW.resolved_at)).id;
 NEW.identity_lineage:=snapshot;
 RETURN NEW;
END $$;

CREATE FUNCTION core.lc_calibration_package_activates_complete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'core', 'pg_temp'
    AS $$
DECLARE missing text[];
BEGIN
    IF NEW.status = 'ACTIVE' AND (TG_OP = 'INSERT' OR OLD.status <> 'ACTIVE') THEN
        missing := core.lc_calibration_package_failures(NEW.id);
        IF cardinality(missing) > 0 THEN
            RAISE EXCEPTION 'calibration package is incomplete: %', array_to_string(missing, ',')
                USING ERRCODE = 'MO036';
        END IF;
    END IF;
    IF TG_OP = 'UPDATE' AND OLD.status <> 'DRAFT'
        AND (NEW.scope_key <> OLD.scope_key OR NEW.package_code <> OLD.package_code
             OR NEW.package_version <> OLD.package_version OR NEW.effective_from <> OLD.effective_from) THEN
        RAISE EXCEPTION 'an activated calibration package keeps its identity and scope'
            USING ERRCODE = 'MO036';
    END IF;
    IF TG_OP = 'UPDATE' AND OLD.status = 'RETIRED' AND NEW.status <> 'RETIRED' THEN
        RAISE EXCEPTION 'a retired calibration package is not revived' USING ERRCODE = 'MO036';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION core.lc_calibration_package_failures(p_package uuid) RETURNS text[]
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 WITH required AS (SELECT core.lc_calibration_required_categories(p.purpose_code) codes
   FROM core.lc_calibration_package p WHERE p.id=p_package)
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM required WHERE codes IS NOT NULL)
   THEN ARRAY['CALIBRATION_PURPOSE_UNRESOLVED'] ELSE
   ARRAY(SELECT code FROM required,unnest(codes) WITH ORDINALITY c(code,position)
     WHERE NOT EXISTS(SELECT 1 FROM core.lc_calibration_value v WHERE v.package_id=p_package AND v.category_code=c.code)
     ORDER BY position) END
$$;

CREATE FUNCTION core.lc_calibration_required_categories(p_purpose text) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT CASE WHEN p_purpose NOT IN ('LISTING_CONVERSION','DESCRIPTION_CORRECTION','BOUNDED_EXPLORATION','PROMOTION')
   OR p_purpose IS NULL THEN NULL ELSE ARRAY(
 SELECT code FROM unnest(ARRAY[
   'MATERIAL_IMPROVEMENT_BOUND','NON_WORSENING_PROFIT_BOUND','NON_WORSENING_RETURN_BOUND','CRITICAL_GROUP_RULE',
   'DEMAND_SCENARIO_SET','FRESHNESS_RULE','RESPONSIBILITY_SLO','RESPONSIBILITY_COVERAGE',
   'ORDINARY_TRIGGER_CONTENT','MATERIAL_TRIGGER_CONTENT','ORDINARY_TRIGGER_EXPOSURE','MATERIAL_TRIGGER_EXPOSURE',
   'APPROVAL_VALIDITY','REPRESENTATION_EQUIVALENCE_RULE','ALLOWANCE_AXES','ALLOWANCE_RESERVE',
   'FORMAL_NODES','STOP_RULE','CROSS_PERIOD_WINDOW','DESCRIPTION_LENGTH_RULE']) WITH ORDINALITY c(code,position)
 WHERE NOT (p_purpose='LISTING_CONVERSION' AND code='DEMAND_SCENARIO_SET')
   AND NOT (p_purpose='PROMOTION' AND code IN ('REPRESENTATION_EQUIVALENCE_RULE','DESCRIPTION_LENGTH_RULE'))
   AND NOT (p_purpose='DESCRIPTION_CORRECTION' AND code IN
       ('MATERIAL_IMPROVEMENT_BOUND','DEMAND_SCENARIO_SET','FORMAL_NODES','STOP_RULE'))
   AND NOT (p_purpose='BOUNDED_EXPLORATION' AND code IN ('MATERIAL_IMPROVEMENT_BOUND','FORMAL_NODES'))
 ORDER BY position) END
$$;

CREATE FUNCTION core.lc_calibration_value_matches_shape() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'core', 'pg_temp'
    AS $$
DECLARE shape text;
BEGIN
    SELECT value_shape INTO shape FROM core.lc_calibration_category WHERE code = NEW.category_code;
    IF (shape = 'NUMERIC' AND NEW.value_numeric IS NULL)
        OR (shape = 'TEXT' AND NEW.value_text IS NULL)
        OR (shape = 'JSON' AND NEW.value_json IS NULL) THEN
        RAISE EXCEPTION 'calibration value % must carry a % value', NEW.category_code, shape
            USING ERRCODE = 'MO036';
    END IF;
    IF EXISTS (SELECT 1 FROM core.lc_calibration_package p
                WHERE p.id = NEW.package_id AND p.status <> 'DRAFT') THEN
        RAISE EXCEPTION 'a calibration value may only be written while its package is a draft'
            USING ERRCODE = 'MO036';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION core.lc_enqueue_feedback_classification() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'core', 'ops'
    AS $$
DECLARE item core.lc_feedback_item%ROWTYPE;
BEGIN
    SELECT * INTO item FROM core.lc_feedback_item WHERE id=NEW.feedback_item_id;
    PERFORM ops.lc_enqueue_source_recalculation(NEW.organization_id,item.platform_listing_id,'ORDINARY',
        'mart.lc_feedback_classification:'||NEW.id::text,NEW.classified_at);
    RETURN NEW;
END $$;

CREATE FUNCTION core.lc_enqueue_finance_input_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'core', 'ops'
    AS $$
DECLARE listing record; payload jsonb:=to_jsonb(NEW);
BEGIN
    FOR listing IN
      SELECT DISTINCT l.id
      FROM core.platform_listing l LEFT JOIN core.platform_listing_variant v ON v.platform_listing_id=l.id
      LEFT JOIN core.listing_mapping m ON m.platform_listing_variant_id=v.id AND m.status='ACTIVE'
      WHERE l.organization_id=NEW.organization_id AND l.status='OBSERVED'
        AND (NEW.scope_kind='ORGANIZATION'
          OR (NEW.scope_kind='STORE' AND l.store_id=NEW.store_ref_id)
          OR (NEW.scope_kind='PRODUCT_VARIANT' AND m.product_variant_id=NEW.product_variant_ref_id))
    LOOP
      PERFORM ops.lc_enqueue_source_recalculation(NEW.organization_id,listing.id,'RISK',
        'core.finance_input_version:'||NEW.id::text||':v:'||NEW.version::text||':listing:'||listing.id::text,
        NEW.effective_from);
    END LOOP;
    RETURN NEW;
END $$;

CREATE FUNCTION core.lc_enqueue_internal_variant_source_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'core', 'ops'
    AS $$
DECLARE listing record; payload jsonb:=to_jsonb(NEW); source_at timestamptz;
BEGIN
    source_at:=CASE WHEN nullif(payload->>TG_ARGV[1],'') IS NULL THEN NULL
                    ELSE (payload->>TG_ARGV[1])::timestamptz END;
    FOR listing IN SELECT DISTINCT v.platform_listing_id
        FROM core.listing_mapping m JOIN core.platform_listing_variant v
          ON v.id=m.platform_listing_variant_id AND v.organization_id=m.organization_id
        WHERE m.organization_id=NEW.organization_id
          AND m.product_variant_id=(payload->>'product_variant_id')::uuid
          AND m.status='ACTIVE' AND v.status='OBSERVED'
    LOOP
        PERFORM ops.lc_enqueue_source_recalculation(NEW.organization_id,listing.platform_listing_id,TG_ARGV[0],
          TG_TABLE_SCHEMA||'.'||TG_TABLE_NAME||':'||(payload->>'id')||':listing:'||listing.platform_listing_id::text,source_at);
    END LOOP;
    RETURN NEW;
END $$;

CREATE FUNCTION core.lc_enqueue_listing_source_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'core', 'ops'
    AS $$
DECLARE payload jsonb:=to_jsonb(NEW); source_at timestamptz; reference text;
BEGIN
    source_at:=CASE WHEN nullif(payload->>TG_ARGV[1],'') IS NULL THEN NULL
                    ELSE (payload->>TG_ARGV[1])::timestamptz END;
    reference:=TG_TABLE_SCHEMA||'.'||TG_TABLE_NAME||':'||(payload->>'id');
    IF TG_OP='UPDATE' THEN
        reference:=reference||':v:'||coalesce(payload->>'version',payload->>'updated_at',payload->>'status','changed');
    END IF;
    PERFORM ops.lc_enqueue_source_recalculation(NEW.organization_id,
        (payload->>'platform_listing_id')::uuid,TG_ARGV[0],reference,source_at);
    RETURN NEW;
END $$;

CREATE FUNCTION core.lc_enqueue_variant_fact_batch() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'core', 'ops'
    AS $_$
DECLARE table_reference text:=TG_TABLE_SCHEMA||'.'||TG_TABLE_NAME;
BEGIN
    EXECUTE format($statement$
        WITH affected AS (
            SELECT fact.organization_id,listing.id AS platform_listing_id,
                   count(*) AS fact_count,min(fact.id::text) AS first_fact_id,
                   min(fact.%1$I) AS source_time,
                   encode(sha256(convert_to(string_agg(fact.id::text,',' ORDER BY fact.id::text),'UTF8')),'hex')
                       AS fact_digest
            FROM lc_inserted_facts fact
            JOIN core.platform_listing_variant variant
              ON variant.id=fact.platform_listing_variant_id
             AND variant.organization_id=fact.organization_id
            JOIN core.platform_listing listing
              ON listing.id=variant.platform_listing_id
             AND listing.organization_id=fact.organization_id
             AND listing.status='OBSERVED'
            GROUP BY fact.organization_id,listing.id
        ), requests AS (
            SELECT affected.*,
                   CASE WHEN fact_count=1 THEN $1||':'||first_fact_id
                        ELSE $1||':batch:'||fact_count::text||':'||fact_digest END AS trigger_reference
            FROM affected
        )
        INSERT INTO ops.lc_recalculation_queue(id,organization_id,platform_listing_id,trigger_class,target_minutes,
            trigger_reference,source_time,accepted_at,state)
        SELECT gen_random_uuid(),request.organization_id,request.platform_listing_id,$2,
               CASE $2 WHEN 'RISK' THEN 5 ELSE 15 END,left(request.trigger_reference,512),
               request.source_time,clock_timestamp(),'QUEUED'
        FROM requests request
        WHERE NOT EXISTS (
            SELECT 1 FROM ops.lc_recalculation_queue queued
            WHERE queued.organization_id=request.organization_id
              AND queued.platform_listing_id=request.platform_listing_id
              AND queued.trigger_reference=request.trigger_reference)
        $statement$,TG_ARGV[1]) USING table_reference,TG_ARGV[0];
    RETURN NULL;
END $_$;

CREATE FUNCTION core.lc_enqueue_variant_source_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'core', 'ops'
    AS $$
DECLARE payload jsonb:=to_jsonb(NEW); listing_id uuid; source_at timestamptz; reference text;
BEGIN
    SELECT v.platform_listing_id INTO listing_id FROM core.platform_listing_variant v
      WHERE v.id=(payload->>'platform_listing_variant_id')::uuid AND v.organization_id=NEW.organization_id;
    IF listing_id IS NULL THEN RETURN NEW; END IF;
    source_at:=CASE WHEN nullif(payload->>TG_ARGV[1],'') IS NULL THEN NULL
                    ELSE (payload->>TG_ARGV[1])::timestamptz END;
    reference:=TG_TABLE_SCHEMA||'.'||TG_TABLE_NAME||':'||(payload->>'id');
    IF TG_OP='UPDATE' THEN
        reference:=reference||':v:'||coalesce(payload->>'version',payload->>'updated_at',payload->>'status','changed');
    END IF;
    PERFORM ops.lc_enqueue_source_recalculation(NEW.organization_id,listing_id,TG_ARGV[0],reference,source_at);
    RETURN NEW;
END $$;

CREATE FUNCTION core.lc_feedback_classification_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM 1 FROM core.platform_listing
      WHERE id=(SELECT platform_listing_id FROM core.lc_feedback_item
                 WHERE id=NEW.feedback_item_id)
      FOR UPDATE;
    IF NEW.revision_no<>coalesce((SELECT max(revision_no)+1 FROM mart.lc_feedback_classification
        WHERE feedback_item_id=NEW.feedback_item_id),0) THEN
        RAISE EXCEPTION 'feedback classification must append the next revision' USING ERRCODE='23514';
    END IF;
    IF NEW.classified_at<(SELECT linked_at FROM core.lc_feedback_item WHERE id=NEW.feedback_item_id)
       OR NEW.classified_at<coalesce((SELECT max(classified_at) FROM mart.lc_feedback_classification
           WHERE feedback_item_id=NEW.feedback_item_id),NEW.classified_at) THEN
        RAISE EXCEPTION 'feedback classification chronology is invalid' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END $$;

CREATE FUNCTION core.lc_listing_affected_set_digest(p_listing uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT encode(sha256(convert_to(core.lc_listing_identity_snapshot(p_listing,statement_timestamp())::text,'UTF8')),'hex')
$$;

CREATE FUNCTION core.lc_listing_identity_snapshot(p_listing uuid, p_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    SET "DateStyle" TO 'ISO, YMD'
    AS $_$
DECLARE snapshot jsonb; receipt core.platform_listing_scope_observation; qualification text:='INCOMPLETE';
 reasons text[]:='{}'; identity_count integer; divergent integer; members jsonb;
 source_kind text; freshness_rule jsonb; maximum_age_seconds integer;
BEGIN
 snapshot:=core.listing_observed_identity_snapshot(p_listing,p_at);
 IF snapshot IS NULL THEN RETURN NULL; END IF;
 IF snapshot->>'listingStatus'<>'OBSERVED' THEN reasons:=array_append(reasons,'NATIVE_LISTING_NOT_CURRENT'); END IF;
 receipt:=core.current_listing_scope_observation(p_listing,p_at);
 IF receipt.id IS NULL THEN reasons:=array_append(reasons,'NATIVE_SCOPE_UNPROVEN');
 ELSE
   SELECT count(DISTINCT (s.native_variant_keys,s.coverage_state,s.expected_member_count,s.continuation_reference))
    INTO divergent FROM core.platform_listing_scope_observation s
    WHERE s.platform_listing_id=p_listing AND s.scope_kind='WHOLE_LISTING'
     AND s.observed_at=receipt.observed_at AND s.recorded_at<=p_at;
   IF divergent>1 THEN qualification:='CONFLICTED'; reasons:=array_append(reasons,'NATIVE_SCOPE_CONFLICT'); END IF;
   SELECT p.source_kind INTO source_kind FROM core.fact_provenance p WHERE p.id=receipt.provenance_id;
   SELECT v.value_json->'nativeScope'->source_kind INTO freshness_rule
    FROM core.platform_listing l
    CROSS JOIN LATERAL core.lc_resolve_calibration(l.organization_id,l.platform_code,l.store_id,p_at) r
    JOIN core.lc_calibration_value v ON v.package_id=r.package_id AND v.category_code='FRESHNESS_RULE'
    WHERE l.id=p_listing AND r.resolution_state='RESOLVED';
   IF freshness_rule IS NULL OR jsonb_typeof(freshness_rule)<>'object'
      OR coalesce(freshness_rule->>'maximumAgeSeconds','') !~ '^[0-9]{1,10}$' THEN
     reasons:=array_append(reasons,'NATIVE_SCOPE_FRESHNESS_UNQUALIFIED');
   ELSIF (freshness_rule->>'maximumAgeSeconds')::numeric NOT BETWEEN 1 AND 2147483647 THEN
     reasons:=array_append(reasons,'NATIVE_SCOPE_FRESHNESS_UNQUALIFIED');
   ELSE
     maximum_age_seconds:=(freshness_rule->>'maximumAgeSeconds')::integer;
     IF receipt.observed_at+maximum_age_seconds*interval '1 second'<=p_at THEN
       reasons:=array_append(reasons,'NATIVE_SCOPE_SOURCE_STALE');
     END IF;
   END IF;
   IF receipt.coverage_state<>'COMPLETE' THEN reasons:=array_append(reasons,'NATIVE_ENUMERATION_INCOMPLETE'); END IF;
   IF receipt.verification_expires_at<=p_at THEN reasons:=array_append(reasons,'NATIVE_SCOPE_VERIFICATION_EXPIRED'); END IF;
   SELECT count(*) INTO identity_count FROM jsonb_array_elements(snapshot->'members') m
    WHERE m->>'nativeVariantKey'=ANY(receipt.native_variant_keys);
   IF identity_count<>cardinality(receipt.native_variant_keys) THEN reasons:=array_append(reasons,'NATIVE_MEMBER_IDENTITY_MISSING'); END IF;
   IF EXISTS(SELECT 1 FROM core.platform_listing_variant v WHERE v.platform_listing_id=p_listing AND v.status='OBSERVED'
       AND NOT v.native_variant_key=ANY(receipt.native_variant_keys) AND v.last_seen_at>receipt.observed_at) THEN
     reasons:=array_append(reasons,'NATIVE_MEMBER_OUTSIDE_CAPTURED_SCOPE');
   END IF;
   IF cardinality(reasons)=0 THEN
     qualification:='COMPLETE';
     -- A complete later native enumeration may exclude an old observed identity without deleting its history.
     SELECT coalesce(jsonb_agg(m ORDER BY m->>'listingVariantId'),'[]'::jsonb) INTO members
      FROM jsonb_array_elements(snapshot->'members') m WHERE m->>'nativeVariantKey'=ANY(receipt.native_variant_keys);
     snapshot:=jsonb_set(snapshot,'{members}',members);
   END IF;
 END IF;
 RETURN snapshot || jsonb_build_object('schema','listing-identity-snapshot-v3','nativeScope',
   jsonb_build_object('state',qualification,'reasonCodes',to_jsonb(reasons),
     'scopeKind',receipt.scope_kind,'nativeScopeKey',receipt.native_scope_key,'nativeVariantKeys',to_jsonb(receipt.native_variant_keys),
     'sourceKind',source_kind,'maximumAgeSeconds',maximum_age_seconds));
END $_$;

CREATE FUNCTION core.lc_meaning_catalog(p_package uuid, p_kind text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE ordinary jsonb; material jsonb; key text; result jsonb; ordinary_unit text; material_unit text;
BEGIN
 key:=CASE p_kind WHEN 'LISTING_DESCRIPTION_CHANGE' THEN 'description' WHEN 'LISTING_PROMOTION_ACTION' THEN 'promotion' END;
 IF key IS NULL THEN RETURN NULL; END IF;
 SELECT value_json,unit_code INTO ordinary,ordinary_unit FROM core.lc_calibration_value
  WHERE package_id=p_package AND category_code='ORDINARY_TRIGGER_CONTENT';
 SELECT value_json,unit_code INTO material,material_unit FROM core.lc_calibration_value
  WHERE package_id=p_package AND category_code='MATERIAL_TRIGGER_CONTENT';
 IF NOT core.lc_meaning_rule_document_valid(ordinary) OR NOT core.lc_meaning_rule_document_valid(material)
    OR ordinary_unit IS DISTINCT FROM 'CONDITIONS' OR material_unit IS DISTINCT FROM 'CONDITIONS' THEN RETURN NULL; END IF;
 SELECT coalesce(jsonb_agg(rule ORDER BY rule->>'code'),'[]'::jsonb) INTO result FROM (
  SELECT value||jsonb_build_object('axis','ORDINARY') AS rule FROM jsonb_array_elements(coalesce(ordinary->key,'[]'::jsonb))
  UNION ALL
  SELECT value||jsonb_build_object('axis','MATERIAL') FROM jsonb_array_elements(coalesce(material->key,'[]'::jsonb))) selected;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(result) r WHERE r->>'axis'='ORDINARY')
    OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(result) r WHERE r->>'axis'='MATERIAL') OR EXISTS(SELECT 1 FROM jsonb_array_elements(result) r
   GROUP BY r->>'code' HAVING count(*)>1) THEN RETURN NULL; END IF;
 RETURN result;
END $$;

CREATE FUNCTION core.lc_meaning_rule_document_valid(doc jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE kind text; rules jsonb; rule jsonb; codes text[];
BEGIN
 IF jsonb_typeof(doc) IS DISTINCT FROM 'object' THEN RETURN false; END IF;
 IF doc->>'model' IS DISTINCT FROM 'LC_MEANING_CONDITIONS_1'
    OR EXISTS(SELECT 1 FROM jsonb_object_keys(doc) k WHERE k NOT IN ('model','description','promotion'))
    OR NOT (doc ? 'description' OR doc ? 'promotion') THEN RETURN false; END IF;
 FOREACH kind IN ARRAY ARRAY['description','promotion'] LOOP
  IF NOT doc ? kind THEN CONTINUE; END IF;
  rules:=doc->kind; codes:='{}';
  IF jsonb_typeof(rules) IS DISTINCT FROM 'array' THEN RETURN false; END IF;
  IF jsonb_array_length(rules)>16 THEN RETURN false; END IF;
  FOR rule IN SELECT value FROM jsonb_array_elements(rules) LOOP
   IF jsonb_typeof(rule) IS DISTINCT FROM 'object' THEN RETURN false; END IF;
   IF EXISTS(SELECT 1 FROM jsonb_object_keys(rule) k WHERE k NOT IN ('code','condition'))
      OR coalesce(rule->>'code','') !~ '^[A-Z][A-Z0-9_]{1,63}$'
      OR jsonb_typeof(rule->'condition') IS DISTINCT FROM 'string'
      OR length(btrim(rule->>'condition')) NOT BETWEEN 1 AND 2000
      OR (rule->>'code')=ANY(codes) THEN RETURN false; END IF;
   codes:=array_append(codes,rule->>'code');
  END LOOP;
 END LOOP;
 RETURN true;
END $_$;

CREATE FUNCTION core.lc_resolve_calibration(p_org uuid, p_platform text, p_store uuid, p_at timestamp with time zone) RETURNS TABLE(package_id uuid, package_version integer, resolution_state text)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT * FROM core.lc_resolve_calibration_for(p_org,p_platform,p_store,p_at,'LISTING_CONVERSION')
$$;

CREATE FUNCTION core.lc_resolve_calibration_for(p_org uuid, p_platform text, p_store uuid, p_at timestamp with time zone, p_purpose text) RETURNS TABLE(package_id uuid, package_version integer, resolution_state text)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'core', 'pg_temp'
    AS $$
    WITH candidates AS (
        SELECT p.id, p.package_version,
               CASE p.scope_kind WHEN 'STORE' THEN 1 WHEN 'PLATFORM' THEN 2 ELSE 3 END AS precedence
          FROM core.lc_calibration_package p
          JOIN ops.lc_calibration_governance g ON g.package_id=p.id
         WHERE p.organization_id = p_org
           AND p.status = 'ACTIVE' AND p.purpose_code=p_purpose
           AND p.activated_at<=p_at AND g.accepted_at<=p_at
           AND g.accepted_digest=ops.lc_calibration_digest(p.id)
           AND p.effective_from <= p_at
           AND (p.effective_to IS NULL OR p.effective_to > p_at)
           AND (p.scope_kind = 'ORGANIZATION'
                OR (p.scope_kind = 'PLATFORM' AND p.platform_code = p_platform)
                OR (p.scope_kind = 'STORE' AND p.store_ref_id = p_store))),
    best AS (SELECT * FROM candidates WHERE precedence = (SELECT min(precedence) FROM candidates))
    SELECT CASE WHEN (SELECT count(*) FROM best) = 1 THEN (SELECT id FROM best) END,
           CASE WHEN (SELECT count(*) FROM best) = 1 THEN (SELECT package_version FROM best) END,
           CASE (SELECT count(*) FROM best)
               WHEN 0 THEN 'CALIBRATION_UNRESOLVED'
               WHEN 1 THEN 'RESOLVED'
               ELSE 'CALIBRATION_CONFLICTED' END
$$;

CREATE FUNCTION core.lc_validate_measurement_coverage() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NOT EXISTS (SELECT 1 FROM core.fact_provenance p
     WHERE p.id=NEW.provenance_id AND p.organization_id=NEW.organization_id) THEN
   RAISE EXCEPTION 'measurement coverage provenance scope mismatch' USING ERRCODE='23514';
 END IF;
 IF NEW.evidence_path='OFFICIAL_SUMMARY' AND NOT EXISTS (
     SELECT 1 FROM core.lc_official_summary_observation s
      WHERE s.id=NEW.summary_observation_id AND s.organization_id=NEW.organization_id
        AND s.platform_listing_id=NEW.platform_listing_id
        AND s.summary_kind='VISITS_AND_RETAINED_PURCHASES'
        AND s.period_start=NEW.window_start AND s.period_end=NEW.window_end
        AND s.retention_window_days=NEW.retention_window_days
        AND s.acquired_at<=NEW.recorded_at) THEN
   RAISE EXCEPTION 'measurement summary scope or window mismatch' USING ERRCODE='23514';
 END IF;
 IF NEW.equivalence_profile_id IS NOT NULL AND (NEW.evidence_path<>'OFFICIAL_SUMMARY' OR NOT EXISTS (
     SELECT 1 FROM core.lc_summary_equivalence_profile p JOIN core.platform_listing l
        ON l.organization_id=p.organization_id AND l.platform_code=p.platform_code
      WHERE p.id=NEW.equivalence_profile_id AND l.id=NEW.platform_listing_id
        AND p.summary_kind='VISITS_AND_RETAINED_PURCHASES' AND p.status='ACTIVE'
        AND p.effective_from<=NEW.recorded_at AND (p.effective_to IS NULL OR p.effective_to>NEW.recorded_at))) THEN
   RAISE EXCEPTION 'measurement equivalence profile scope mismatch' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION core.lc_validate_promotion_context_observation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'core', 'ops', 'iam', 'pg_temp'
    SET "TimeZone" TO 'UTC'
    SET "DateStyle" TO 'ISO, YMD'
    AS $_$
DECLARE context_item jsonb; demand record; target_found boolean:=false; identity_count integer;
BEGIN
 IF NEW.context_coverage='SINGLE_ACTIVITY_ONLY' THEN RETURN NEW; END IF;
 FOR context_item IN SELECT value FROM jsonb_array_elements(NEW.context_snapshot) LOOP
   IF jsonb_typeof(context_item)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(context_item))<>9
      OR EXISTS(SELECT 1 FROM jsonb_object_keys(context_item) key WHERE key NOT IN
        ('declaration','participationState','effectiveFrom','effectiveTo','newTransactionsState',
         'residualObligationState','originalAuthorityReference','originalAuthorityValidUntil','axisDemands'))
      OR ops.lc_promotion_terms_digest(context_item->'declaration') IS NULL
      OR context_item->>'participationState' NOT IN ('PARTICIPATING','NOT_PARTICIPATING','UNKNOWN')
      OR context_item->>'newTransactionsState' NOT IN ('OPEN','STOPPED','UNKNOWN')
      OR context_item->>'residualObligationState' NOT IN ('OUTSTANDING','CLEARED','UNKNOWN')
      OR coalesce(context_item->>'effectiveFrom','') !~ '^[-+0-9T:. Z]+$'
      OR coalesce(context_item->>'effectiveTo','') !~ '^[-+0-9T:. Z]+$'
      OR (context_item->>'effectiveFrom')::timestamptz >= (context_item->>'effectiveTo')::timestamptz
      OR (context_item->>'participationState'='PARTICIPATING' AND context_item->>'newTransactionsState'<>'OPEN')
      OR (context_item->>'participationState'='NOT_PARTICIPATING' AND context_item->>'newTransactionsState'='OPEN')
      OR (context_item->>'participationState'='UNKNOWN' AND
          (context_item->>'newTransactionsState'<>'UNKNOWN' OR context_item->>'residualObligationState'<>'UNKNOWN'))
      OR (context_item->>'participationState'='PARTICIPATING' AND
          (jsonb_typeof(context_item->'originalAuthorityReference') IS DISTINCT FROM 'string'
           OR length(btrim(coalesce(context_item->>'originalAuthorityReference',''))) NOT BETWEEN 1 AND 512
           OR jsonb_typeof(context_item->'originalAuthorityValidUntil') IS DISTINCT FROM 'string'
           OR coalesce(context_item->>'originalAuthorityValidUntil','') !~ '^[-+0-9T:. Z]+$'
           OR (context_item->>'originalAuthorityValidUntil')::timestamptz<=NEW.acquired_at))
      OR (context_item->>'participationState'<>'PARTICIPATING' AND
          (jsonb_typeof(context_item->'originalAuthorityReference') IS DISTINCT FROM 'null'
           OR jsonb_typeof(context_item->'originalAuthorityValidUntil') IS DISTINCT FROM 'null'))
      OR jsonb_typeof(context_item->'axisDemands') IS DISTINCT FROM 'object'
      OR (SELECT count(*) FROM jsonb_object_keys(context_item->'axisDemands'))>4
      OR EXISTS(SELECT 1 FROM jsonb_object_keys(context_item->'axisDemands') axis
          WHERE axis NOT IN ('CONCURRENT_LISTINGS','AFFECTED_VARIANTS','REVENUE_EXPOSURE','CATEGORY_SHARE')) THEN
     RAISE EXCEPTION 'complete promotion context requires bounded exact activity records' USING ERRCODE='MO092';
   END IF;
   FOR demand IN SELECT key,value FROM jsonb_each(context_item->'axisDemands') LOOP
     IF jsonb_typeof(demand.value)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(demand.value))<>3
        OR EXISTS(SELECT 1 FROM jsonb_object_keys(demand.value) key
             WHERE key NOT IN ('value','unitCode','evidenceReference'))
        OR coalesce(demand.value->>'value','') !~ '^[0-9]+([.][0-9]{1,4})?$'
        OR length(demand.value->>'value')>19
        OR length(btrim(coalesce(demand.value->>'unitCode',''))) NOT BETWEEN 1 AND 32
        OR length(btrim(coalesce(demand.value->>'evidenceReference',''))) NOT BETWEEN 1 AND 512 THEN
       RAISE EXCEPTION 'promotion axis demand requires an exact value, unit and evidence reference' USING ERRCODE='MO092';
     END IF;
   END LOOP;
   IF context_item#>>'{declaration,engagementKind}'=NEW.engagement_kind
      AND context_item#>>'{declaration,nativePromotionKey}'=NEW.native_promotion_key THEN
     target_found:=true;
     IF context_item->>'participationState'<>NEW.participation_state OR NEW.declaration IS NULL
        OR context_item->'declaration' IS DISTINCT FROM NEW.declaration THEN
       RAISE EXCEPTION 'promotion context target contradicts the observed activity fact' USING ERRCODE='MO093';
     END IF;
   END IF;
 END LOOP;
 SELECT count(*) INTO identity_count FROM (
   SELECT context_entry#>>'{declaration,engagementKind}',context_entry#>>'{declaration,nativePromotionKey}'
   FROM jsonb_array_elements(NEW.context_snapshot) context_entry GROUP BY 1,2) identities;
 IF identity_count<>jsonb_array_length(NEW.context_snapshot) OR NOT target_found THEN
   RAISE EXCEPTION 'promotion context identities must be unique and include the observed target' USING ERRCODE='MO092';
 END IF;
 NEW.context_digest:=encode(sha256(convert_to(jsonb_build_object(
   'organizationId',NEW.organization_id,'listingId',NEW.platform_listing_id,
   'observationId',NEW.id,'observedAt',NEW.observed_at,'acquiredAt',NEW.acquired_at,
   'coverageFrom',NEW.coverage_from,'coverageUntil',NEW.coverage_until,
   'verificationExpiresAt',NEW.verification_expires_at,'records',NEW.context_snapshot)::text,'UTF8')),'hex');
 RETURN NEW;
END $_$;

CREATE FUNCTION core.listing_observed_identity_snapshot(p_listing uuid, p_at timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'core', 'pg_temp'
    SET "TimeZone" TO 'UTC'
    SET "DateStyle" TO 'ISO, YMD'
    AS $$
    SELECT jsonb_build_object(
        'schema', 'listing-identity-snapshot-v2',
        'listingId', l.id, 'organizationId', l.organization_id,
        'storeId', l.store_id, 'platformCode', l.platform_code,
        'nativeListingKey', l.native_listing_key, 'listingStatus', l.status,
        'members', coalesce((
            SELECT jsonb_agg(jsonb_build_object(
                'listingVariantId', v.id, 'nativeVariantKey', v.native_variant_key,
                'mappings', coalesce((
                    SELECT jsonb_agg(jsonb_build_object(
                        'mappingId', m.id, 'mappingVersion', m.version,
                        'productVariantId', m.product_variant_id,
                        'effectiveFrom', m.effective_from, 'effectiveTo', m.effective_to,
                        'mappingStatus', m.status, 'productVariantStatus', pv.status,
                        'productStatus', p.status) ORDER BY m.id)
                    FROM core.listing_mapping m
                    JOIN core.product_variant pv ON pv.id = m.product_variant_id
                    JOIN core.product p ON p.id = pv.product_id
                    WHERE m.platform_listing_variant_id = v.id
                      AND m.status IN ('ACTIVE', 'ENDED')
                      AND m.effective_from <= p_at
                      AND (m.effective_to IS NULL OR m.effective_to > p_at)
                ), '[]'::jsonb),
                'openConflicts', coalesce((
                    SELECT jsonb_agg(jsonb_build_object('conflictId', c.id,
                        'version', c.version, 'kind', c.conflict_kind) ORDER BY c.id)
                    FROM core.mapping_conflict c
                    WHERE c.platform_listing_variant_id = v.id AND c.state = 'OPEN'
                ), '[]'::jsonb)
            ) ORDER BY v.id)
            FROM core.platform_listing_variant v
            WHERE v.platform_listing_id = l.id AND v.status = 'OBSERVED'
        ), '[]'::jsonb))
    FROM core.platform_listing l WHERE l.id = p_listing
$$;

CREATE TABLE core.ad_outcome_policy (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    policy_version integer NOT NULL,
    scope_kind text NOT NULL,
    platform_code text,
    store_ref_id uuid,
    direction text NOT NULL,
    observation_starts_minutes integer NOT NULL,
    operational_window_hours integer NOT NULL,
    settlement_window_hours integer NOT NULL,
    completed_sales_guard_hours integer NOT NULL,
    minimum_settled_coverage_ratio numeric(6,5) NOT NULL,
    primary_metric_code text NOT NULL,
    comparison_basis text NOT NULL,
    improvement_threshold_ratio numeric(6,5) NOT NULL,
    regression_threshold_ratio numeric(6,5) NOT NULL,
    minimum_traffic_count bigint NOT NULL,
    owner_user_id uuid NOT NULL,
    reason text NOT NULL,
    evidence_reference text NOT NULL,
    effective_from timestamp with time zone NOT NULL,
    effective_to timestamp with time zone,
    status text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    cause_code text,
    non_worsening_profit_band numeric(18,4),
    non_worsening_per_rub_band numeric(18,6),
    minimum_ad_spend_denominator numeric(18,4),
    comparison_scale integer,
    comparison_rounding_mode text,
    material_boundary_inclusive boolean,
    negative_profit_terminal text,
    critical_unit_definition_complete boolean DEFAULT false NOT NULL,
    retained_window_days integer DEFAULT 30 NOT NULL,
    material_profit_delta numeric(18,4),
    material_profit_per_rub_delta numeric(18,6),
    sales_preservation_tolerance_ratio numeric(6,5),
    CONSTRAINT ad_outcome_policy_basis_ck CHECK ((comparison_basis = ANY (ARRAY['PRE_CHANGE_SAME_OBJECT'::text, 'PRE_CHANGE_SAME_AFFECTED_SET'::text]))),
    CONSTRAINT ad_outcome_policy_cause_ck CHECK (((cause_code IS NULL) OR (cause_code ~ '^[A-Z][A-Z0-9_]{1,62}$'::text))),
    CONSTRAINT ad_outcome_policy_cause_direction_ck CHECK (((cause_code IS NULL) OR (direction = ANY (ARRAY['PROTECTION_DECREASE'::text, 'OPTIMIZATION_INCREASE'::text])))),
    CONSTRAINT ad_outcome_policy_comparison_rounding_mode_check CHECK ((comparison_rounding_mode = ANY (ARRAY['HALF_UP'::text, 'HALF_EVEN'::text, 'DOWN'::text, 'UP'::text]))),
    CONSTRAINT ad_outcome_policy_comparison_scale_check CHECK (((comparison_scale >= 0) AND (comparison_scale <= 8))),
    CONSTRAINT ad_outcome_policy_coverage_ck CHECK (((minimum_settled_coverage_ratio > (0)::numeric) AND (minimum_settled_coverage_ratio <= (1)::numeric))),
    CONSTRAINT ad_outcome_policy_direction_ck CHECK ((direction = ANY (ARRAY['PROTECTION_DECREASE'::text, 'OPTIMIZATION_INCREASE'::text]))),
    CONSTRAINT ad_outcome_policy_evidence_ck CHECK (((length(btrim(evidence_reference)) >= 1) AND (length(btrim(evidence_reference)) <= 512))),
    CONSTRAINT ad_outcome_policy_guard_ck CHECK ((((completed_sales_guard_hours >= 24) AND (completed_sales_guard_hours <= 2160)) AND (completed_sales_guard_hours <= settlement_window_hours))),
    CONSTRAINT ad_outcome_policy_interval_ck CHECK (((effective_to IS NULL) OR (effective_to > effective_from))),
    CONSTRAINT ad_outcome_policy_material_profit_delta_check CHECK ((material_profit_delta >= (0)::numeric)),
    CONSTRAINT ad_outcome_policy_material_profit_per_rub_delta_check CHECK ((material_profit_per_rub_delta >= (0)::numeric)),
    CONSTRAINT ad_outcome_policy_metric_ck CHECK ((primary_metric_code ~ '^[A-Z][A-Z0-9_]{1,62}$'::text)),
    CONSTRAINT ad_outcome_policy_minimum_ad_spend_denominator_check CHECK ((minimum_ad_spend_denominator > (0)::numeric)),
    CONSTRAINT ad_outcome_policy_negative_profit_terminal_check CHECK ((negative_profit_terminal = 'KEEP_PROTECTION_OPEN'::text)),
    CONSTRAINT ad_outcome_policy_non_worsening_per_rub_band_check CHECK ((non_worsening_per_rub_band >= (0)::numeric)),
    CONSTRAINT ad_outcome_policy_non_worsening_profit_band_check CHECK ((non_worsening_profit_band >= (0)::numeric)),
    CONSTRAINT ad_outcome_policy_operational_ck CHECK (((operational_window_hours >= 1) AND (operational_window_hours <= 720))),
    CONSTRAINT ad_outcome_policy_reason_ck CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 1024))),
    CONSTRAINT ad_outcome_policy_retained_window_days_check CHECK ((retained_window_days = 30)),
    CONSTRAINT ad_outcome_policy_sales_preservation_tolerance_ratio_check CHECK (((sales_preservation_tolerance_ratio >= (0)::numeric) AND (sales_preservation_tolerance_ratio < (1)::numeric))),
    CONSTRAINT ad_outcome_policy_scope_ck CHECK ((scope_kind = ANY (ARRAY['ORGANIZATION'::text, 'PLATFORM'::text, 'STORE'::text]))),
    CONSTRAINT ad_outcome_policy_scope_shape_ck CHECK ((((scope_kind = 'ORGANIZATION'::text) AND (platform_code IS NULL) AND (store_ref_id IS NULL)) OR ((scope_kind = 'PLATFORM'::text) AND (platform_code IS NOT NULL) AND (store_ref_id IS NULL)) OR ((scope_kind = 'STORE'::text) AND (platform_code IS NOT NULL) AND (store_ref_id IS NOT NULL)))),
    CONSTRAINT ad_outcome_policy_settlement_ck CHECK (((settlement_window_hours > operational_window_hours) AND (settlement_window_hours <= 2160))),
    CONSTRAINT ad_outcome_policy_start_ck CHECK (((observation_starts_minutes >= 5) AND (observation_starts_minutes <= 1440))),
    CONSTRAINT ad_outcome_policy_status_ck CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'RETIRED'::text]))),
    CONSTRAINT ad_outcome_policy_threshold_ck CHECK (((improvement_threshold_ratio > (0)::numeric) AND (improvement_threshold_ratio <= (1)::numeric) AND (regression_threshold_ratio > (0)::numeric) AND (regression_threshold_ratio <= (1)::numeric))),
    CONSTRAINT ad_outcome_policy_traffic_ck CHECK ((minimum_traffic_count >= 0)),
    CONSTRAINT ad_outcome_policy_version_ck CHECK ((policy_version >= 1))
);

CREATE FUNCTION core.resolve_ad_outcome_policy(p_organization_id uuid, p_platform_code text, p_store_id uuid, p_direction text, p_cause_code text, p_at timestamp with time zone) RETURNS core.ad_outcome_policy
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'core', 'pg_temp'
    AS $$
 SELECT p.* FROM core.ad_outcome_policy_resolution(p_organization_id,p_platform_code,p_store_id,p_direction,p_cause_code,p_at) r
 JOIN core.ad_outcome_policy p ON r.state='RESOLVED' AND p.id=r.policy_id
$$;

CREATE FUNCTION core.validate_platform_listing_scope_observation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE provenance core.fact_provenance; listing core.platform_listing; keys text[];
BEGIN
 SELECT * INTO listing FROM core.platform_listing WHERE id=NEW.platform_listing_id AND organization_id=NEW.organization_id;
 SELECT * INTO provenance FROM core.fact_provenance WHERE id=NEW.provenance_id AND organization_id=NEW.organization_id;
 IF listing.id IS NULL OR provenance.id IS NULL OR provenance.source_time IS DISTINCT FROM NEW.observed_at
   OR provenance.ingestion_time IS DISTINCT FROM NEW.recorded_at
   OR provenance.source_kind NOT IN ('MANUAL_ENTRY','MARKETPLACE_RAW') THEN
   RAISE EXCEPTION 'native enumeration must retain exact source identity and custody times' USING ERRCODE='23514';
 END IF;
 IF NEW.scope_kind='WHOLE_LISTING' AND NEW.native_scope_key<>listing.native_listing_key THEN
   RAISE EXCEPTION 'native listing scope mismatch' USING ERRCODE='23514';
 END IF;
 IF EXISTS(SELECT 1 FROM unnest(NEW.native_variant_keys) k WHERE k IS NULL OR length(btrim(k))=0 OR length(k)>512) THEN
   RAISE EXCEPTION 'exact bounded native member keys required' USING ERRCODE='23514';
 END IF;
 SELECT ARRAY(SELECT DISTINCT k FROM unnest(NEW.native_variant_keys) k ORDER BY k) INTO keys;
 IF cardinality(keys)<>cardinality(NEW.native_variant_keys) THEN
   RAISE EXCEPTION 'duplicate native member does not enlarge coverage' USING ERRCODE='23514';
 END IF;
 NEW.native_variant_keys:=keys;
 RETURN NEW;
END $$;

CREATE FUNCTION iam.diagnostic_export_allowed(p_actor uuid, p_store uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
 SELECT EXISTS (
   SELECT 1 FROM core.store s JOIN core.marketplace_account a ON a.id=s.marketplace_account_id
   JOIN core.legal_entity e ON e.id=a.legal_entity_id JOIN core.organization o ON o.id=s.organization_id
   JOIN iam.user_account u ON u.organization_id=o.id
   JOIN iam.identity_provider ip ON ip.id=u.identity_provider_id
   WHERE s.id=p_store AND u.id=p_actor AND u.status='ACTIVE' AND ip.status='ACTIVE'
     AND ip.verification_state='VERIFIED' AND s.status='ACTIVE' AND a.status='ACTIVE'
     AND e.status='ACTIVE' AND o.status='ACTIVE'
     AND NOT EXISTS (SELECT 1 FROM (VALUES ('DIAGNOSTIC_VIEW'),('EVIDENCE_VIEW')) actions(code)
       WHERE NOT EXISTS (SELECT 1 FROM iam.user_role_assignment r
         JOIN iam.business_role_action_scope m ON m.role_code=r.role_code
         WHERE r.user_id=u.id AND m.action_code=actions.code AND r.status='ACTIVE'
           AND r.effective_from<=statement_timestamp() AND (r.effective_to IS NULL OR r.effective_to>statement_timestamp()))
       OR NOT EXISTS (SELECT 1 FROM iam.user_scope_grant g WHERE g.user_id=u.id
         AND g.action_code=actions.code AND g.status='ACTIVE'
         AND g.effective_from<=statement_timestamp() AND (g.effective_to IS NULL OR g.effective_to>statement_timestamp())
         AND (g.organization_ref_id=o.id OR g.legal_entity_ref_id=e.id
           OR g.marketplace_account_ref_id=a.id OR g.store_ref_id=s.id))))
$$;

CREATE FUNCTION iam.issue_ad_control_invocation_grant(p_purpose text, p_proof_hash text, p_actor uuid, p_org uuid, p_provider uuid, p_subject text, p_session text, p_authenticated timestamp with time zone, p_step_up_until timestamp with time zone, p_target uuid, p_version uuid, p_backend integer, p_transaction bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'iam', 'pg_temp'
    AS $$ BEGIN
 IF p_purpose NOT IN ('COMPENSATION_PREVIEW','COMPENSATION_ENDORSE','COMPENSATION_APPROVE',
 'BUNDLE_DRAFT','BUNDLE_ENDORSE','BUNDLE_APPROVE','CONTAINMENT_STOP','AUTHORITY_VERSION_STOP','CONTAINMENT_REENABLE',
 'CONTAINMENT_ATTEST','CONTAINMENT_ENDORSE','MANUAL_POLICY_PUBLISH','MANUAL_PACKET_SELECT',
 'MANUAL_PACKET_ENDORSE','MANUAL_PACKET_APPROVE','MANUAL_EXECUTION_REPORT','MANUAL_EXECUTION_START','MANUAL_INDEPENDENT_VERIFY',
 'LISTING_ACTION_LAUNCH','LISTING_ACTION_REVIEW','LISTING_ACTION_APPROVE','LISTING_MANUAL_VERIFY',
 'LISTING_OCCUPATION_RELEASE','LISTING_CONTAINMENT_STOP','LISTING_CONTAINMENT_ATTEST',
 'LISTING_CONTAINMENT_CONSENT','LISTING_CONTAINMENT_REENABLE','LISTING_PROMOTION_EXIT',
 'LISTING_ISOLATION_DEPENDENCY_RECORD','LISTING_CALIBRATION_PREPARE','LISTING_CALIBRATION_VALIDATE',
 'LISTING_CALIBRATION_ACCEPT','LISTING_CALIBRATION_ACTIVATE') THEN
  RAISE EXCEPTION 'unknown control invocation purpose' USING ERRCODE='MO092'; END IF;
 PERFORM iam.issue_ad_invocation_grant(p_proof_hash,p_actor,p_org,p_provider,p_subject,p_session,
 p_authenticated,p_step_up_until,p_target,p_version,p_backend,p_transaction);
 UPDATE iam.ad_invocation_grant SET purpose=p_purpose WHERE proof_hash=p_proof_hash;
END $$;

CREATE FUNCTION iam.issue_ad_invocation_grant(p_proof_hash text, p_actor uuid, p_org uuid, p_provider uuid, p_subject text, p_session text, p_authenticated timestamp with time zone, p_step_up_until timestamp with time zone, p_recommendation uuid, p_approval uuid, p_backend integer, p_transaction bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'iam', 'pg_temp'
    AS $_$
BEGIN
    IF session_user = 'marketops_app' OR p_step_up_until <= clock_timestamp()
       OR p_authenticated > clock_timestamp() OR p_subject !~ '^[0-9a-f]{64}$'
       OR p_session !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION 'trusted current authentication required' USING ERRCODE = 'MO092';
    END IF;
    INSERT INTO iam.ad_invocation_grant(proof_hash,actor_user_id,organization_id,
        identity_provider_id,subject_digest,session_digest,authenticated_at,
        step_up_valid_until,recommendation_id,approval_decision_id,backend_pid,
        transaction_id,expires_at)
    VALUES(p_proof_hash,p_actor,p_org,p_provider,p_subject,p_session,p_authenticated,
        p_step_up_until,p_recommendation,p_approval,p_backend,p_transaction,
        least(clock_timestamp()+interval '25 seconds',p_step_up_until));
END $_$;

CREATE FUNCTION ledger.enforce_internal_stock_return_reentry() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    linked_transition ledger.return_inventory_transition%ROWTYPE;
BEGIN
    IF NEW.return_reentry_id IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT *
      INTO linked_transition
      FROM ledger.return_inventory_transition
     WHERE id = NEW.return_reentry_id
       AND organization_id = NEW.organization_id;

    IF NOT FOUND
       OR linked_transition.state <> 'REENTERED_AVAILABLE'
       OR linked_transition.quality_disposition <> 'RESELLABLE'
       OR linked_transition.warehouse_id <> NEW.warehouse_id
       OR linked_transition.product_variant_id <> NEW.product_variant_id
       OR NEW.observed_at < linked_transition.occurred_at THEN
        RAISE EXCEPTION 'invalid returned-inventory re-entry link'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'internal_stock_snapshot_return_reentry_state_ck';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ledger.enforce_return_inventory_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    prior ledger.return_inventory_transition%ROWTYPE;
    source_return ledger.return_fact%ROWTYPE;
    mapped_variant_id uuid;
BEGIN
    SELECT * INTO source_return FROM ledger.return_fact WHERE id = NEW.return_fact_id;
    SELECT mapping.product_variant_id
      INTO mapped_variant_id
      FROM core.listing_mapping AS mapping
     WHERE mapping.organization_id = source_return.organization_id
       AND mapping.platform_listing_variant_id = source_return.platform_listing_variant_id
       AND mapping.status = 'ACTIVE'
       AND mapping.effective_from <= NEW.occurred_at
       AND (mapping.effective_to IS NULL OR mapping.effective_to > NEW.occurred_at)
     ORDER BY mapping.effective_from DESC
     LIMIT 1;
    IF NOT FOUND
       OR source_return.organization_id <> NEW.organization_id
       OR source_return.return_kind = 'CANCELLATION'
       OR NEW.quantity > source_return.quantity
       OR NEW.occurred_at < source_return.occurred_at
       OR mapped_variant_id IS NULL
       OR mapped_variant_id <> NEW.product_variant_id THEN
        RAISE EXCEPTION 'invalid return source for inventory transition'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'return_inventory_transition_source_ck';
    END IF;

    IF NEW.supersedes_transition_id IS NULL THEN
        IF NEW.state NOT IN ('IN_TRANSIT', 'AWAITING_QC') THEN
            RAISE EXCEPTION 'invalid initial returned-inventory state'
                USING ERRCODE = '23514',
                      CONSTRAINT = 'return_inventory_transition_sequence_ck';
        END IF;
        RETURN NEW;
    END IF;

    SELECT * INTO prior
      FROM ledger.return_inventory_transition
     WHERE id = NEW.supersedes_transition_id
       AND organization_id = NEW.organization_id;
    IF NOT FOUND
       OR prior.return_fact_id <> NEW.return_fact_id
       OR prior.product_variant_id <> NEW.product_variant_id
       OR prior.quantity <> NEW.quantity
       OR NEW.occurred_at < prior.occurred_at
       OR NOT (CASE prior.state
            WHEN 'IN_TRANSIT' THEN NEW.state IN ('AWAITING_QC', 'WRITTEN_OFF')
            WHEN 'AWAITING_QC' THEN NEW.state IN
                ('QC_REJECTED', 'WRITTEN_OFF', 'REENTERED_AVAILABLE')
            ELSE false
          END) THEN
        RAISE EXCEPTION 'invalid returned-inventory state transition'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'return_inventory_transition_sequence_ck';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ledger.enforce_return_quality_evidence_successor() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    prior ledger.return_quality_evidence_snapshot%ROWTYPE;
BEGIN
    IF NEW.supersedes_snapshot_id IS NULL THEN
        RETURN NEW;
    END IF;
    SELECT * INTO prior
      FROM ledger.return_quality_evidence_snapshot
     WHERE id = NEW.supersedes_snapshot_id
       AND organization_id = NEW.organization_id
     FOR UPDATE;
    IF NOT FOUND
       OR prior.platform_listing_variant_id <> NEW.platform_listing_variant_id
       OR prior.report_window_start <> NEW.report_window_start
       OR prior.report_window_end <> NEW.report_window_end
       OR prior.accepted_at >= NEW.accepted_at THEN
        RAISE EXCEPTION 'return-quality evidence successor changes identity or time order'
            USING ERRCODE = '23514',
                  CONSTRAINT = 'return_quality_evidence_snapshot_successor_ck';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ledger.validate_ad_settlement_attribution() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM ledger.sales_fact financial JOIN ledger.ad_linked_sale_event linked
        ON linked.id=NEW.ad_linked_sale_event_id
        WHERE financial.id=NEW.settled_sales_fact_id AND financial.organization_id=NEW.organization_id
          AND linked.organization_id=NEW.organization_id
          AND financial.platform_listing_variant_id=linked.platform_listing_variant_id
          AND financial.sale_stage='SETTLED' AND financial.quantity>0
          AND linked.sale_stage='CANONICAL_AD_LINKED_RETAINED_SALE'
          AND financial.currency_code=linked.currency_code) THEN
        RAISE EXCEPTION 'settlement attribution must bind the same canonical unit and stage' USING ERRCODE='MO099';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION mart.lc_measurement_lineage_scope_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'mart', 'core', 'pg_temp'
    AS $$
DECLARE
    measurement mart.lc_conversion_measurement%ROWTYPE;
    coverage core.lc_measurement_coverage%ROWTYPE;
BEGIN
    IF NEW.canonical_input_digest IS NOT NULL AND NEW.canonical_input_digest <>
            encode(sha256(convert_to(NEW.inputs::text,'UTF8')),'hex') THEN
        RAISE EXCEPTION 'measurement canonical input digest does not match retained inputs' USING ERRCODE='MO093';
    END IF;
    NEW.canonical_input_digest:=encode(sha256(convert_to(NEW.inputs::text,'UTF8')),'hex');
    SELECT * INTO STRICT measurement FROM mart.lc_conversion_measurement WHERE id=NEW.measurement_id;
    IF NEW.coverage_id IS NULL THEN
        IF measurement.path_qualified THEN
            RAISE EXCEPTION 'qualified measurement lineage requires its exact source coverage' USING ERRCODE='MO093';
        END IF;
    ELSE
        SELECT * INTO STRICT coverage FROM core.lc_measurement_coverage WHERE id=NEW.coverage_id;
        IF coverage.organization_id<>measurement.organization_id
            OR coverage.platform_listing_id<>measurement.platform_listing_id
            OR coverage.evidence_path<>measurement.evidence_path
            OR coverage.window_start<>measurement.window_start
            OR coverage.window_end<>measurement.window_end
            OR coverage.retention_window_days<>measurement.retention_window_days
            OR coverage.recorded_at>measurement.computed_at THEN
            RAISE EXCEPTION 'measurement lineage coverage identity, period or maturity definition mismatch' USING ERRCODE='MO092';
        END IF;
    END IF;
    IF NEW.recorded_at<measurement.computed_at THEN
        RAISE EXCEPTION 'measurement lineage cannot precede its computation' USING ERRCODE='MO093';
    END IF;
    RETURN NEW;
END
$$;

CREATE FUNCTION mart.metric_value_verification(p_value uuid, p_at timestamp with time zone) RETURNS TABLE(verified_at timestamp with time zone, verification_run_id uuid)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'mart', 'pg_temp'
    AS $$
 SELECT coalesce(proof.evaluated_at,initial.computed_at),coalesce(proof.calculation_run_id,initial.calculation_run_id)
 FROM mart.metric_value v
 LEFT JOIN LATERAL (
  SELECT v.computed_at,v.calculation_run_id FROM mart.calculation_run original
  WHERE original.id=v.calculation_run_id AND original.state='SUCCEEDED'
   AND original.organization_id=v.organization_id AND original.window_code=v.window_code
   AND original.period_start=v.period_start AND original.period_end=v.period_end
   AND original.started_at<=v.computed_at AND v.period_end<=v.computed_at
   AND v.computed_at<=original.completed_at
   AND original.completed_at<=coalesce(p_at,statement_timestamp())
 ) initial ON true
 LEFT JOIN LATERAL (
  SELECT e.evaluated_at,e.calculation_run_id FROM mart.metric_value_evaluation e
  JOIN mart.calculation_run r ON r.id=e.calculation_run_id
  JOIN mart.calculation_run original ON original.id=v.calculation_run_id
  WHERE e.metric_value_id=v.id AND r.state='SUCCEEDED'
   AND r.organization_id=v.organization_id AND original.organization_id=v.organization_id
   AND r.scope_kind=original.scope_kind AND r.store_ref_id IS NOT DISTINCT FROM original.store_ref_id
   AND r.window_code=v.window_code AND r.period_start=v.period_start AND r.period_end=v.period_end
   AND r.started_at<=e.evaluated_at AND v.computed_at<=e.evaluated_at
   AND r.period_end<=e.evaluated_at AND e.evaluated_at<=r.completed_at
   AND e.evaluated_at<=coalesce(p_at,statement_timestamp()) AND r.completed_at<=coalesce(p_at,statement_timestamp())
  ORDER BY e.evaluated_at DESC,e.calculation_run_id DESC LIMIT 1
 ) proof ON true WHERE v.id=p_value
$$;

CREATE FUNCTION mart.validate_metric_value_evaluation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'mart', 'pg_temp'
    AS $$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'metric evaluation history is immutable' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM mart.metric_value v
  JOIN mart.calculation_run original ON original.id=v.calculation_run_id
  JOIN mart.calculation_run r ON r.id=NEW.calculation_run_id
  WHERE v.id=NEW.metric_value_id AND r.state='RUNNING'
   AND r.organization_id=v.organization_id AND original.organization_id=v.organization_id
   AND r.scope_kind=original.scope_kind AND r.store_ref_id IS NOT DISTINCT FROM original.store_ref_id
   AND r.window_code=v.window_code AND r.period_start=v.period_start AND r.period_end=v.period_end
   AND NEW.evaluated_at>=r.started_at AND NEW.evaluated_at>=v.computed_at
   AND r.period_end<=NEW.evaluated_at)
 THEN RAISE EXCEPTION 'metric evaluation must match an active canonical computation' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION ops.accept_lc_calibration(p_id uuid, p_proof text, p_digest text, p_reference text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE g iam.ad_invocation_grant%ROWTYPE; p core.lc_calibration_package%ROWTYPE; v ops.lc_calibration_governance%ROWTYPE;
BEGIN
 SELECT * INTO p FROM core.lc_calibration_package WHERE id=p_id FOR UPDATE;
 SELECT * INTO v FROM ops.lc_calibration_governance WHERE package_id=p_id FOR UPDATE;
 IF NOT FOUND OR p.status<>'DRAFT' OR v.validated_at IS NULL OR v.accepted_at IS NOT NULL THEN
  RAISE EXCEPTION 'calibration needs professional validation and a new exact acceptance' USING ERRCODE='MO036';
 END IF;
 g:=ops.consume_ad_control_invocation(p_proof,'LISTING_CALIBRATION_ACCEPT',p_id,p_id);
 IF g.organization_id<>p.organization_id OR NOT ops.lc_calibration_actor_scope(g.actor_user_id,p.organization_id,
      p.scope_kind,p.store_ref_id,'LISTING_CALIBRATION_ACCEPT')
    OR g.actor_user_id=v.drafted_by_user_id OR g.actor_user_id=v.validated_by_user_id THEN
  RAISE EXCEPTION 'independent current Owner acceptance required' USING ERRCODE='MO092';
 END IF;
 IF p_digest IS NULL OR p_reference IS NULL OR length(btrim(p_reference)) NOT BETWEEN 1 AND 512
    OR p_digest<>v.validated_digest OR p_digest<>ops.lc_calibration_digest(p_id)
    OR (p.effective_to IS NOT NULL AND p.effective_to<=clock_timestamp()) THEN
  RAISE EXCEPTION 'calibration validation is changed or expired' USING ERRCODE='MO036';
 END IF;
 UPDATE ops.lc_calibration_governance SET accepted_by_user_id=g.actor_user_id,accepted_at=clock_timestamp(),
   acceptance_reference=p_reference,accepted_digest=p_digest WHERE package_id=p_id;
 UPDATE core.lc_calibration_package SET published_by_user_id=g.actor_user_id,published_at=clock_timestamp() WHERE id=p_id;
 INSERT INTO ops.lc_calibration_event VALUES(gen_random_uuid(),p_id,'ACCEPTED',g.actor_user_id,p_digest,p_reference,clock_timestamp());
END $$;

CREATE FUNCTION ops.acknowledge_checkpoint(p_run_id uuid, p_expected_fence bigint, p_expected_lease_owner text, p_observation_id uuid, p_expected_version bigint, p_position_value text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    target_job  uuid;
    new_version bigint;
BEGIN
    -- Lock the run and hold the lock through the checkpoint write.
    SELECT run.job_id INTO target_job
      FROM ops.ingestion_run AS run
     WHERE run.id = p_run_id
       AND run.fence_token = p_expected_fence
       AND run.lease_owner = p_expected_lease_owner
       AND run.state = 'RUNNING'
       AND run.lease_expires_at > clock_timestamp()
       FOR UPDATE OF run;

    IF target_job IS NULL THEN
        RAISE EXCEPTION
            'run % is not held by % at fence % with a live lease',
            p_run_id, p_expected_lease_owner, p_expected_fence
            USING ERRCODE = 'MO008';
    END IF;

    -- The evidence must exist, belong to this run, and be durable content.
    PERFORM 1
      FROM raw.raw_acquisition_observation AS observation
      JOIN raw.raw_logical_unit AS unit ON unit.id = observation.logical_unit_id
      JOIN raw.raw_content AS content ON content.id = observation.content_id
     WHERE observation.id = p_observation_id
       AND observation.run_id = p_run_id
       AND observation.response_complete AND observation.outcome_class='SUCCESS_BYTES'
       AND observation.pagination_outcome IN ('END','NEXT')
       AND unit.job_id = target_job;
    IF NOT FOUND THEN
        RAISE EXCEPTION
            'checkpoint for run % has no committed observation %', p_run_id, p_observation_id
            USING ERRCODE = 'MO009',
                  HINT = 'store and hash the returned bytes before acknowledging a cursor';
    END IF;

    -- Lock the exact checkpoint row after the run. A concurrent holder may
    -- delay this acquisition past the lease deadline; after the row is obtained
    -- the final UPDATE below therefore rechecks wall-clock lease truth.
    PERFORM 1
      FROM ops.ingestion_checkpoint AS checkpoint
     WHERE checkpoint.job_id = target_job
       AND checkpoint.checkpoint_version = p_expected_version
       FOR UPDATE OF checkpoint;
    IF NOT FOUND THEN
        RAISE EXCEPTION
            'checkpoint for job % is not at expected version %', target_job, p_expected_version
            USING ERRCODE = 'MO008';
    END IF;

    UPDATE ops.ingestion_checkpoint AS checkpoint
       SET position_value     = p_position_value,
           checkpoint_version = checkpoint.checkpoint_version + 1,
           updated_at         = clock_timestamp()
      FROM ops.ingestion_run AS run
     WHERE checkpoint.job_id = target_job
       AND checkpoint.checkpoint_version = p_expected_version
       AND run.id = p_run_id
       AND run.job_id = checkpoint.job_id
       AND run.state = 'RUNNING'
       AND run.fence_token = p_expected_fence
       AND run.lease_owner = p_expected_lease_owner
       AND run.lease_expires_at > clock_timestamp()
       AND EXISTS (
           SELECT 1
             FROM raw.raw_acquisition_observation AS observation
             JOIN raw.raw_logical_unit AS unit
               ON unit.id = observation.logical_unit_id
             JOIN raw.raw_content AS content
               ON content.id = observation.content_id
            WHERE observation.id = p_observation_id
              AND observation.run_id = run.id
              AND observation.response_complete AND observation.outcome_class='SUCCESS_BYTES'
              AND observation.pagination_outcome IN ('END','NEXT')
              AND unit.job_id = run.job_id)
    RETURNING checkpoint.checkpoint_version INTO new_version;

    IF new_version IS NULL THEN
        RAISE EXCEPTION
            'checkpoint authority for run % was lost before version % could advance',
            p_run_id, p_expected_version
            USING ERRCODE = 'MO008';
    END IF;

    RETURN new_version;
END;
$$;

CREATE FUNCTION ops.acknowledge_lc_execution_delivery(p_receipt uuid, p_event uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE receipt ops.lc_execution_receipt%ROWTYPE;
BEGIN
    SELECT * INTO receipt FROM ops.lc_execution_receipt WHERE id=p_receipt FOR UPDATE;
    IF receipt.id IS NULL OR NOT EXISTS (SELECT 1 FROM ops.work_task_event e
        WHERE e.id=p_event AND e.execution_receipt_id=receipt.id AND e.event_kind='EXECUTION_OBSERVED') THEN
        RAISE EXCEPTION 'delivery acknowledgement needs its exact journal event' USING ERRCODE='MO093';
    END IF;
    IF receipt.task_event_id IS NOT NULL THEN RETURN receipt.task_event_id=p_event; END IF;
    UPDATE ops.lc_execution_receipt SET task_event_id=p_event,task_recorded_at=clock_timestamp() WHERE id=receipt.id;
    RETURN true;
END;
$$;

CREATE FUNCTION ops.acquire_lc_launch_allowance(p_launch_id uuid, p_action uuid, p_actor uuid, p_proof text, p_requested jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'iam', 'pg_temp'
    AS $$
DECLARE
    action      ops.lc_action%ROWTYPE;
    binding     ops.lc_action_binding%ROWTYPE;
    plan_row    ops.lc_evaluation_plan%ROWTYPE;
    grant_row   iam.ad_invocation_grant%ROWTYPE;
    gaps        text[];
    projection jsonb;
    axis_row jsonb;
    short       text[] := '{}';
    occupations uuid[] := '{}';
    occupation_id uuid;
    command_id uuid;
    now_at      timestamptz := clock_timestamp();
BEGIN
    SELECT * INTO action FROM ops.lc_action WHERE id = p_action FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'action does not exist' USING ERRCODE = 'MO090'; END IF;
    SELECT * INTO binding FROM ops.lc_action_binding WHERE action_id = p_action;
    IF NOT FOUND THEN RAISE EXCEPTION 'the action has no binding' USING ERRCODE = 'MO092'; END IF;
    grant_row := ops.consume_ad_control_invocation(p_proof, 'LISTING_ACTION_LAUNCH',
        action.recommendation_id, binding.approval_decision_id);
    IF grant_row.actor_user_id <> p_actor OR grant_row.organization_id <> action.organization_id THEN
        RAISE EXCEPTION 'the invocation proof belongs to another person' USING ERRCODE = 'MO092';
    END IF;
    IF NOT ops.lc_actor_holds_action(p_actor, action.organization_id, action.store_id, 'LISTING_ACTION_LAUNCH') THEN
        RAISE EXCEPTION 'the actor cannot launch a listing action here' USING ERRCODE = 'MO092';
    END IF;
    IF action.state NOT IN ('APPROVED', 'APPROVED_NOT_LAUNCHABLE') THEN
        RAISE EXCEPTION 'only an approved action is launched' USING ERRCODE = 'MO091';
    END IF;
    -- Stable authority spans manual/API, batches and every allowance configuration version.
    PERFORM pg_advisory_xact_lock(hashtext('lc_exposure_organization'),hashtext(action.organization_id::text));
    now_at:=clock_timestamp();
    -- Concurrent publication cannot change the evaluated constraints before this launch commits.
    -- SHARE allows other launch readers; only allowance configuration writes wait.
    LOCK TABLE ops.lc_exposure_allowance IN SHARE MODE;
    now_at:=clock_timestamp();
    gaps := ops.lc_binding_gaps(p_action);
    IF cardinality(gaps) > 0 THEN
        RAISE EXCEPTION 'the binding no longer applies: %', array_to_string(gaps, ',') USING ERRCODE = 'MO092';
    END IF;
    SELECT * INTO plan_row FROM ops.lc_evaluation_plan WHERE action_id = p_action;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'an evaluation plan is frozen before launch' USING ERRCODE = 'MO092';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM mart.lc_listing_health h
                    WHERE h.platform_listing_id = action.platform_listing_id
                      AND h.health_version = (SELECT max(latest.health_version) FROM mart.lc_listing_health latest
                                              WHERE latest.platform_listing_id = action.platform_listing_id)
                      AND h.necessary_state = 'PASS') THEN
        RAISE EXCEPTION 'Listing Health necessary conditions are not passed' USING ERRCODE = 'MO092';
    END IF;
    IF ops.lc_scope_contained(action.organization_id, action.platform_listing_id) THEN
        RAISE EXCEPTION 'the scope is contained' USING ERRCODE = 'MO092';
    END IF;

    projection:=ops.lc_allowance_projection(p_action,now_at);
    SELECT coalesce(array_agg(value),'{}') INTO short FROM jsonb_array_elements_text(projection->'gaps');
    FOR axis_row IN SELECT value FROM jsonb_array_elements(projection->'axes') LOOP
      IF NOT (axis_row->>'sufficient')::boolean AND NOT EXISTS(
          SELECT 1 FROM unnest(short) gap WHERE gap LIKE (axis_row->>'axisCode')||':%') THEN
        short:=array_append(short,axis_row->>'axisCode');
      END IF;
    END LOOP;
    IF cardinality(short) > 0 THEN
        UPDATE ops.lc_action SET state = 'APPROVED_NOT_LAUNCHABLE', updated_at = now_at, version = version + 1
         WHERE id = p_action AND state = 'APPROVED';
        RETURN jsonb_build_object('launched', false, 'insufficientAxes', to_jsonb(short));
    END IF;

    -- One occupation per Action/axis; every applicable constraint is retained in its evidence.
    FOR axis_row IN SELECT DISTINCT ON (value->>'axisCode') value
        FROM jsonb_array_elements(projection->'axes') ORDER BY value->>'axisCode',value->>'scopeKey' LOOP
        occupation_id:=gen_random_uuid();
        INSERT INTO ops.lc_exposure_occupation(id,organization_id,allowance_id,action_id,axis_code,
          requested_value,occupied_value,state,acquired_at,demand_evidence)
        VALUES(occupation_id,action.organization_id,(axis_row->>'allowanceId')::uuid,p_action,axis_row->>'axisCode',
          (axis_row->>'canonicalDemand')::numeric,(axis_row->>'canonicalDemand')::numeric,'ACQUIRED',now_at,projection);
        occupations:=array_append(occupations,occupation_id);
    END LOOP;

    INSERT INTO ops.lc_launch (id, organization_id, action_id, binding_id, plan_id, launched_by_user_id,
        launched_at, proof_hash)
    VALUES (p_launch_id, action.organization_id, p_action, binding.id, plan_row.id, p_actor, now_at,
        grant_row.proof_hash);
    UPDATE ops.lc_action SET state = 'LAUNCHED', updated_at = now_at, version = version + 1
     WHERE id = p_action;
    IF action.execution_path='API' THEN
        command_id:=ops.create_lc_description_command(p_action,p_actor,action.version+1,'lc-launch:'||p_launch_id::text);
    END IF;
    RETURN jsonb_build_object('launched', true, 'launchId', p_launch_id,
        'occupationIds', to_jsonb(occupations),'commandId',command_id);
END;
$$;

CREATE FUNCTION ops.acquire_lc_launch_allowance(p_launch_id uuid, p_action uuid, p_actor uuid, p_proof text, p_requested jsonb, p_execution_evaluation uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'iam', 'pg_temp'
    AS $$
DECLARE
    action      ops.lc_action%ROWTYPE;
    binding     ops.lc_action_binding%ROWTYPE;
    plan_row    ops.lc_evaluation_plan%ROWTYPE;
    grant_row   iam.ad_invocation_grant%ROWTYPE;
    gaps        text[];
    projection jsonb;
    declared_purpose text;
    axis_row jsonb;
    short       text[] := '{}';
    occupations uuid[] := '{}';
    occupation_id uuid;
    command_id uuid;
    execution_evaluation uuid;
    now_at      timestamptz := clock_timestamp();
BEGIN
    SELECT * INTO action FROM ops.lc_action WHERE id = p_action FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'action does not exist' USING ERRCODE = 'MO090'; END IF;
    SELECT * INTO binding FROM ops.lc_action_binding WHERE action_id = p_action;
    IF NOT FOUND THEN RAISE EXCEPTION 'the action has no binding' USING ERRCODE = 'MO092'; END IF;
    IF action.state NOT IN ('APPROVED', 'APPROVED_NOT_LAUNCHABLE') THEN
        RAISE EXCEPTION 'only an approved action is launched' USING ERRCODE = 'MO091';
    END IF;
    -- Stable authority spans manual/API, batches and every allowance configuration version.
    PERFORM ops.lock_lc_launch_evaluation(p_action);
    now_at:=clock_timestamp();
    -- Consume only after all allowance lock waits: proof and step-up expiry use wall time.
    grant_row := ops.consume_ad_control_invocation(p_proof, 'LISTING_ACTION_LAUNCH',
        action.recommendation_id, binding.approval_decision_id);
    IF grant_row.actor_user_id <> p_actor OR grant_row.organization_id <> action.organization_id THEN
        RAISE EXCEPTION 'the invocation proof belongs to another person' USING ERRCODE = 'MO092';
    END IF;
    IF NOT ops.lc_actor_holds_action(p_actor, action.organization_id, action.store_id, 'LISTING_ACTION_LAUNCH') THEN
        RAISE EXCEPTION 'the actor cannot launch a listing action here' USING ERRCODE = 'MO092';
    END IF;
    gaps := ops.lc_binding_gaps(p_action);
    IF cardinality(gaps) > 0 THEN
        RAISE EXCEPTION 'the binding no longer applies: %', array_to_string(gaps, ',') USING ERRCODE = 'MO092';
    END IF;
    SELECT r.proposed_parameters->>'purposeCode' INTO declared_purpose FROM ops.recommendation r
      WHERE r.id=action.recommendation_id AND r.organization_id=action.organization_id;
    SELECT * INTO plan_row FROM ops.lc_evaluation_plan WHERE action_id = p_action;
    IF declared_purpose IN ('LISTING_CONVERSION','PROMOTION') THEN
        IF plan_row.id IS NULL THEN
            RAISE EXCEPTION 'formal evaluation plan must be frozen before launch' USING ERRCODE='MO092';
        END IF;
    ELSIF declared_purpose IN ('DESCRIPTION_CORRECTION','BOUNDED_EXPLORATION') THEN
        IF plan_row.id IS NOT NULL OR ops.lc_purpose_basis_digest(declared_purpose,action.purpose_basis) IS NULL
           OR (declared_purpose='BOUNDED_EXPLORATION' AND action.execution_path<>'MANUAL') THEN
            RAISE EXCEPTION 'nonformal launch requires its reviewed use basis and execution path' USING ERRCODE='MO092';
        END IF;
    ELSE
        RAISE EXCEPTION 'launch purpose is unresolved' USING ERRCODE='MO092';
    END IF;
    IF declared_purpose<>'DESCRIPTION_CORRECTION' AND NOT EXISTS (SELECT 1 FROM mart.lc_listing_health h
                    WHERE h.platform_listing_id = action.platform_listing_id
                      AND h.health_version = (SELECT max(latest.health_version) FROM mart.lc_listing_health latest
                                              WHERE latest.platform_listing_id = action.platform_listing_id)
                      AND h.necessary_state = 'PASS') THEN
        RAISE EXCEPTION 'Listing Health necessary conditions are not passed' USING ERRCODE = 'MO092';
    END IF;
    IF ops.lc_scope_contained(action.organization_id, action.platform_listing_id) THEN
        RAISE EXCEPTION 'the scope is contained' USING ERRCODE = 'MO092';
    END IF;

    SELECT e.id INTO execution_evaluation FROM ops.guardrail_evaluation e
      WHERE e.id=p_execution_evaluation AND e.organization_id=action.organization_id AND e.recommendation_id=action.recommendation_id
        AND e.purpose='EXECUTION' AND e.outcome='PASS' AND cardinality(e.reason_codes)=0
        AND e.listing_transaction_id=txid_current()
        AND e.detail->>'actionId'=action.id::text
        AND e.detail->>'actionVersion'=action.version::text
        AND e.detail->>'actionState'=action.state
        AND e.detail->>'executionPath'=action.execution_path
        AND e.detail->>'affectedSetDigest'=action.affected_set_digest
        AND e.detail->>'purposeCode'=declared_purpose
        AND e.detail->>'targetTextDigest'=coalesce(action.target_text_digest,'null')
        AND e.lc_calibration_package_id=action.calibration_package_id
        AND e.lc_calibration_version=action.calibration_version
        AND e.detail->>'reviewAttested'='true'
        AND e.detail->>'materialityRecheck.state'='CURRENT'
        AND (declared_purpose IN ('LISTING_CONVERSION','PROMOTION')
          OR e.detail->>'purposeBasisDigest'=ops.lc_purpose_basis_digest(declared_purpose,action.purpose_basis))
        AND e.detail->>'calibrationPackageId'=action.calibration_package_id::text
        AND e.detail->>'calibrationVersion'=action.calibration_version::text
        AND (declared_purpose='DESCRIPTION_CORRECTION' OR (
          e.detail->>'protectionRecheck.financialInputState'='CANONICAL_INPUT_AVAILABLE'
          AND e.detail->>'protectionRecheck.currentProfitVerdict'='PASS'
          AND e.detail->>'protectionRecheck.currentReturnVerdict'='PASS'
          AND e.detail->>'protectionRecheck.unitProfitFloorVerdict'='PASS'
          AND e.detail->>'protectionRecheck.supplyVerdict'='PASS'
          AND (action.action_kind<>'LISTING_PROMOTION_ACTION'
            OR e.detail->>'protectionRecheck.selectedSimulationInputState'='QUALIFIED_CURRENT')))
        AND e.evaluated_at<=now_at
      ORDER BY e.evaluated_at DESC,e.id LIMIT 1;
    IF execution_evaluation IS NULL THEN
      RAISE EXCEPTION 'this transaction requires the exact current protected execution evaluation' USING ERRCODE='MO092';
    END IF;

    projection:=ops.lc_allowance_projection(p_action,now_at);
    SELECT coalesce(array_agg(value),'{}') INTO short FROM jsonb_array_elements_text(projection->'gaps');
    FOR axis_row IN SELECT value FROM jsonb_array_elements(projection->'axes') LOOP
      IF NOT (axis_row->>'sufficient')::boolean AND NOT EXISTS(
          SELECT 1 FROM unnest(short) gap WHERE gap LIKE (axis_row->>'axisCode')||':%') THEN
        short:=array_append(short,axis_row->>'axisCode');
      END IF;
    END LOOP;
    IF cardinality(short) > 0 THEN
        UPDATE ops.lc_action SET state = 'APPROVED_NOT_LAUNCHABLE', updated_at = now_at, version = version + 1
         WHERE id = p_action AND state = 'APPROVED';
        RETURN jsonb_build_object('launched', false, 'insufficientAxes', to_jsonb(short));
    END IF;

    -- One occupation per Action/axis; every applicable constraint is retained in its evidence.
    FOR axis_row IN SELECT DISTINCT ON (value->>'axisCode') value
        FROM jsonb_array_elements(projection->'axes') ORDER BY value->>'axisCode',value->>'scopeKey' LOOP
        occupation_id:=gen_random_uuid();
        INSERT INTO ops.lc_exposure_occupation(id,organization_id,allowance_id,action_id,axis_code,
          requested_value,occupied_value,state,acquired_at,demand_evidence)
        VALUES(occupation_id,action.organization_id,(axis_row->>'allowanceId')::uuid,p_action,axis_row->>'axisCode',
          (axis_row->>'canonicalDemand')::numeric,(axis_row->>'canonicalDemand')::numeric,'ACQUIRED',now_at,projection);
        occupations:=array_append(occupations,occupation_id);
    END LOOP;

    INSERT INTO ops.lc_launch (id, organization_id, action_id, binding_id, plan_id, launched_by_user_id,
        launched_at, proof_hash, execution_guardrail_id)
    VALUES (p_launch_id, action.organization_id, p_action, binding.id, plan_row.id, p_actor, now_at,
        grant_row.proof_hash, execution_evaluation);
    UPDATE ops.lc_action SET state = 'LAUNCHED', updated_at = now_at, version = version + 1
     WHERE id = p_action;
    IF action.execution_path='API' THEN
        command_id:=ops.create_lc_description_command(p_action,p_actor,action.version+1,'lc-launch:'||p_launch_id::text);
    END IF;
    RETURN jsonb_build_object('launched', true, 'launchId', p_launch_id,
        'occupationIds', to_jsonb(occupations),'commandId',command_id);
END;
$$;

CREATE FUNCTION ops.activate_ad_authority_version_containment(p_id uuid, p_authority uuid, p_review_owner uuid, p_reason text, p_evidence text, p_proof text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'iam', 'pg_temp'
    AS $$
DECLARE g iam.ad_invocation_grant%ROWTYPE; required_actor uuid; allowed_roles text[]; authority_index integer;
BEGIN
 g:=ops.consume_ad_control_invocation(p_proof,'AUTHORITY_VERSION_STOP',p_authority,p_id);
 PERFORM pg_advisory_xact_lock(hashtext('ad_action_reservation'),hashtext(g.organization_id::text));
 IF p_authority IS NULL OR p_review_owner IS NULL OR nullif(btrim(p_reason),'') IS NULL
 OR nullif(btrim(p_evidence),'') IS NULL THEN
  RAISE EXCEPTION 'exact authority version and closure review metadata required' USING ERRCODE='MO036'; END IF;
 FOR authority_index IN 1..2 LOOP
  required_actor:=CASE authority_index WHEN 1 THEN g.actor_user_id ELSE p_review_owner END;
  allowed_roles:=CASE authority_index WHEN 1 THEN ARRAY['OWNER','OPS_LEAD'] ELSE ARRAY['OPS_LEAD'] END;
  IF NOT EXISTS(SELECT 1 FROM unnest(allowed_roles) required_role
    WHERE ops.ad_actor_has_organization_role_scope(required_actor,g.organization_id,required_role,'ADVERTISING_POLICY_MANAGE')) THEN
   RAISE EXCEPTION 'organization-wide policy control and review-owner scope required' USING ERRCODE='MO064'; END IF;
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM ops.ad_decision_policy_bundle b WHERE b.organization_id=g.organization_id
   AND ops.ad_bundle_consumes_authority_version(b.id,p_authority))
 AND NOT EXISTS(SELECT 1 FROM ops.ad_manual_execution_packet packet WHERE packet.organization_id=g.organization_id
   AND p_authority::text=ANY(ARRAY[packet.semantic_profile_id::text,to_jsonb(packet)#>>'{authority_snapshot,policy,id}',
     to_jsonb(packet)#>>'{authority_snapshot,outcomePolicy,id}'])) THEN
  RAISE EXCEPTION 'authority version is not consumed by this organization' USING ERRCODE='MO064'; END IF;
 INSERT INTO ops.ad_containment(id,organization_id,containment_kind,scope_kind,authority_version_reference,
  cause_class,reason,evidence_reference,activated_by_user_id,activated_at,state,correlation_id,
  created_at,updated_at,review_owner_user_id)
 VALUES(p_id,g.organization_id,'AUTHORITY_VERSION_QUARANTINE','AUTHORITY_VERSION',p_authority::text,
  'AUTHORITY_VERSION_INVALID',p_reason,p_evidence,g.actor_user_id,clock_timestamp(),'ACTIVE',
  'ad-authority-version-stop',clock_timestamp(),clock_timestamp(),p_review_owner);
 RETURN p_id;
END $$;

CREATE FUNCTION ops.activate_ad_bundle(p_bundle uuid, p_gate uuid, p_proof text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'iam', 'pg_temp'
    AS $$
DECLARE b ops.ad_decision_policy_bundle%ROWTYPE; e ops.ad_bundle_endorsement%ROWTYPE;
 g iam.ad_invocation_grant%ROWTYPE; gate ops.ad_gate_authority%ROWTYPE; failures text[];
BEGIN
 g:=ops.consume_ad_control_invocation(p_proof,'BUNDLE_APPROVE',p_bundle,p_gate);
 SELECT * INTO b FROM ops.ad_decision_policy_bundle WHERE id=p_bundle FOR UPDATE;
 PERFORM pg_advisory_xact_lock(hashtext('ad_action_reservation'),hashtext(b.organization_id::text));
 SELECT * INTO e FROM ops.ad_bundle_endorsement WHERE bundle_id=b.id;
 SELECT * INTO gate FROM ops.ad_gate_authority WHERE id=p_gate;
 IF b.status<>'DRAFT' OR e.bundle_id IS NULL OR g.actor_user_id IN(b.activated_by_user_id,e.endorser_user_id)
 OR NOT ops.ad_actor_has_role_scope(g.actor_user_id,b.organization_id,b.store_id,'OWNER','ADVERTISING_POLICY_MANAGE')
 OR e.authority_snapshot IS DISTINCT FROM (ops.ad_bundle_authority_snapshot(b.id)||jsonb_build_object('proposedGate',to_jsonb(gate)))
 OR gate.id IS NULL OR gate.status<>'ACTIVE' OR gate.bundle_id<>b.id OR gate.store_id<>b.store_id
 OR b.gate_scope_reference IS DISTINCT FROM p_gate::text
 OR gate.organization_id<>b.organization_id OR gate.platform_code<>b.platform_code OR gate.marketplace_account_id<>b.marketplace_account_id
 OR gate.direction<>b.direction OR gate.candidate_basis<>b.candidate_basis
 OR gate.valid_from>clock_timestamp() OR gate.valid_until<=clock_timestamp() THEN
  RAISE EXCEPTION 'complete endorsed Bundle and exact scoped Owner Gate authority required' USING ERRCODE='MO092'; END IF;
 failures:=ops.ad_bundle_validation_failures(b.id);
 IF cardinality(failures)>0 THEN RAISE EXCEPTION 'whole Bundle validation failed: %',array_to_string(failures,',') USING ERRCODE='MO092'; END IF;
 UPDATE ops.ad_decision_policy_bundle SET status='SUPERSEDED',effective_to=clock_timestamp(),updated_at=clock_timestamp(),version=version+1
 WHERE organization_id=b.organization_id AND store_id=b.store_id AND direction=b.direction
 AND candidate_basis=b.candidate_basis AND native_object_kind=b.native_object_kind
 AND lifecycle_scope=b.lifecycle_scope AND status='ACTIVE';
 UPDATE ops.ad_decision_policy_bundle SET status='ACTIVE',validation_state='VALIDATED',validation_failure_codes='{}',
 endorsed_by_user_id=e.endorser_user_id,approved_by_user_id=g.actor_user_id,gate_authority_id=p_gate,
 updated_at=clock_timestamp(),version=version+1 WHERE id=b.id;
END $$;

CREATE FUNCTION ops.activate_ad_human_containment(p_id uuid, p_object uuid, p_scope text, p_kind text, p_cause text, p_review_owner uuid, p_reason text, p_evidence text, p_proof text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'iam', 'pg_temp'
    AS $$
DECLARE g iam.ad_invocation_grant%ROWTYPE; object_row core.ad_native_object%ROWTYPE; affected core.ad_affected_set%ROWTYPE;
 account_id uuid; permitted boolean:=false;
BEGIN
 g:=ops.consume_ad_control_invocation(p_proof,'CONTAINMENT_STOP',p_object,p_id);
 SELECT * INTO object_row FROM core.ad_native_object WHERE id=p_object;
 SELECT * INTO affected FROM core.ad_affected_set a WHERE a.ad_native_object_id=p_object
 ORDER BY a.resolved_at DESC,a.id DESC LIMIT 1;
 SELECT marketplace_account_id INTO account_id FROM core.store WHERE id=object_row.store_id;
 IF object_row.organization_id<>g.organization_id OR p_scope='AFFECTED_SET' AND affected.resolution_state IS DISTINCT FROM 'COMPLETE'
 OR p_reason IS NULL OR p_evidence IS NULL THEN RAISE EXCEPTION 'exact stop scope and evidence required' USING ERRCODE='MO097'; END IF;
 IF p_scope IN ('ENTITY','AFFECTED_SET') AND p_kind='EMERGENCY_ENTITY_HOLD' THEN
  permitted:=ops.ad_actor_has_role_scope(g.actor_user_id,g.organization_id,object_row.store_id,
   'MARKETPLACE_OPERATOR','ADVERTISING_TASK_ACT'); END IF;
 IF p_scope IN ('ENTITY','AFFECTED_SET','PLATFORM_STORE_CAPABILITY')
 AND p_cause IN ('BUSINESS_HARM','EXECUTION_INTEGRITY','OUTCOME_REGRESSION') THEN
  permitted:=permitted OR ops.ad_actor_has_role_scope(g.actor_user_id,g.organization_id,object_row.store_id,
   'OPS_LEAD','ADVERTISING_POLICY_MANAGE'); END IF;
 IF p_scope IN ('PLATFORM_STORE_CAPABILITY','PLATFORM_ACCOUNT_CAPABILITY')
 AND p_cause IN ('CREDENTIAL_OR_SECURITY','PROVIDER_OR_READBACK_DEFECT','EXECUTION_INTEGRITY') THEN
  permitted:=permitted OR ops.ad_actor_has_role_scope(g.actor_user_id,g.organization_id,object_row.store_id,
   'TECH_DATA','ADVERTISING_TECHNICAL_STOP');
  IF p_scope='PLATFORM_ACCOUNT_CAPABILITY' AND NOT EXISTS(SELECT 1 FROM iam.user_scope_grant sg
   WHERE sg.user_id=g.actor_user_id AND sg.action_code='ADVERTISING_TECHNICAL_STOP'
   AND sg.status='ACTIVE' AND sg.effective_from<=clock_timestamp() AND (sg.effective_to IS NULL OR sg.effective_to>clock_timestamp())
   AND (sg.organization_ref_id=g.organization_id OR sg.marketplace_account_ref_id=account_id)) THEN permitted:=false; END IF;
 END IF;
 IF NOT permitted OR NOT ops.ad_actor_has_role_scope(p_review_owner,g.organization_id,object_row.store_id,
 'OPS_LEAD','ADVERTISING_POLICY_MANAGE') THEN RAISE EXCEPTION 'stop exceeds actor scope or review owner is absent' USING ERRCODE='MO097'; END IF;
 INSERT INTO ops.ad_containment(id,organization_id,containment_kind,scope_kind,platform_code,marketplace_account_id,
 store_id,ad_native_object_id,affected_set_digest,capability_code,cause_class,reason,evidence_reference,activated_by_user_id,
 activated_at,state,correlation_id,created_at,updated_at,review_owner_user_id,action_command_id)
 VALUES(p_id,g.organization_id,p_kind,p_scope,object_row.platform_code,account_id,object_row.store_id,p_object,
 affected.affected_set_digest,'ad-bid-change',p_cause,p_reason,p_evidence,g.actor_user_id,clock_timestamp(),'ACTIVE',
 'ad-human-containment',clock_timestamp(),clock_timestamp(),p_review_owner,
 (SELECT c.id FROM ops.ad_bid_command c JOIN ops.ad_action_reservation held ON held.id=c.reservation_id
  WHERE c.ad_native_object_id=p_object AND c.organization_id=g.organization_id
  AND c.state='READBACK_MATCHED' AND held.state='ACTIVE' AND p_kind='EMERGENCY_ENTITY_HOLD'
  AND p_scope IN('ENTITY','AFFECTED_SET') AND p_cause='BUSINESS_HARM'
  AND EXISTS(SELECT 1 FROM ops.ad_bid_command_readback proof WHERE proof.command_id=c.id
    AND proof.match_state='MATCHES_TARGET' AND proof.observed_bid=c.target_bid_amount
    AND proof.currency_code=c.currency_code AND proof.bid_unit_code=c.bid_unit_code)
  ORDER BY c.created_at DESC,c.id DESC LIMIT 1));
 RETURN p_id;
END $$;

CREATE FUNCTION ops.activate_ad_regression_containment(p_observation uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'pg_temp'
    AS $$
DECLARE outcome ops.ad_outcome_observation%ROWTYPE; c ops.ad_bid_command%ROWTYPE;
 a ops.ad_action_authorization%ROWTYPE; packet ops.ad_manual_execution_packet%ROWTYPE; identity uuid;
BEGIN
 SELECT * INTO outcome FROM ops.ad_outcome_observation WHERE id=p_observation AND (verdict='REGRESSED' OR ops.ad_protection_outcome_invalidated(id));
 IF NOT FOUND THEN RAISE EXCEPTION 'canonical financial/sales regression or invalidated Protection terminal required' USING ERRCODE='MO097'; END IF;
 SELECT * INTO c FROM ops.ad_bid_command WHERE id=outcome.command_id;
 SELECT * INTO a FROM ops.ad_action_authorization WHERE recommendation_id=c.recommendation_id;
 IF c.id IS NULL THEN
  SELECT * INTO packet FROM ops.ad_manual_execution_packet WHERE id=outcome.manual_packet_id;
  c.organization_id:=packet.organization_id;c.store_id:=packet.store_id;c.platform_code:=packet.platform_code;
  c.ad_native_object_id:=packet.ad_native_object_id;c.affected_set_digest:=packet.affected_set_digest;
  c.reservation_id:=packet.reservation_id;a.endorser_user_id:=packet.endorser_user_id;
 END IF;
 IF a.endorser_user_id IS NULL THEN RAISE EXCEPTION 'accountable regression review owner absent' USING ERRCODE='MO097'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext('ad_action_reservation'),hashtext(c.organization_id::text));
 SELECT id INTO identity FROM ops.ad_containment WHERE evidence_reference='ad-outcome:'||p_observation;
 IF identity IS NOT NULL THEN RETURN identity; END IF;
 identity:=gen_random_uuid();
 INSERT INTO ops.ad_containment(id,organization_id,containment_kind,scope_kind,platform_code,store_id,
 ad_native_object_id,affected_set_digest,capability_code,cause_class,reason,evidence_reference,
 activated_by_trigger,activated_at,state,correlation_id,created_at,updated_at,review_owner_user_id)
 VALUES(identity,c.organization_id,'ACTION_OUTCOME_QUARANTINE','AFFECTED_SET',c.platform_code,c.store_id,
 c.ad_native_object_id,c.affected_set_digest,'ad-bid-change','OUTCOME_REGRESSION',
 'Canonical action-bound safety result regressed or its Protection terminal was invalidated','ad-outcome:'||p_observation,'AD_OUTCOME_REGRESSION',
 clock_timestamp(),'ACTIVE',outcome.correlation_id,clock_timestamp(),clock_timestamp(),a.endorser_user_id);
 UPDATE ops.ad_action_reservation SET regression_open=true,version=version+1 WHERE id=c.reservation_id AND state='ACTIVE';
 -- A late correction may arrive after a legitimate release. Reacquire only
 -- if no newer intervention holds the scope; the quarantine itself always
 -- persists and blocks execution, even when another reservation must settle.
 UPDATE ops.ad_action_reservation r SET state='ACTIVE',released_at=NULL,release_reason=NULL,
 regression_open=true,version=version+1 WHERE r.id=c.reservation_id AND r.state='RELEASED'
 AND NOT EXISTS(SELECT 1 FROM ops.ad_action_reservation other WHERE other.organization_id=r.organization_id
 AND other.state='ACTIVE' AND other.id<>r.id
 AND (other.ad_native_object_id=r.ad_native_object_id OR other.product_variant_ids && r.product_variant_ids));
 RETURN identity;
END $$;

CREATE FUNCTION ops.activate_lc_calibration(p_id uuid, p_proof text, p_digest text, p_reference text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE g iam.ad_invocation_grant%ROWTYPE; p core.lc_calibration_package%ROWTYPE;
 v ops.lc_calibration_governance%ROWTYPE; previous uuid; overlap_count integer; now_at timestamptz:=clock_timestamp();
BEGIN
 SELECT * INTO p FROM core.lc_calibration_package WHERE id=p_id FOR UPDATE;
 SELECT * INTO v FROM ops.lc_calibration_governance WHERE package_id=p_id FOR UPDATE;
 IF NOT FOUND OR p.status<>'DRAFT' OR v.accepted_at IS NULL THEN
  RAISE EXCEPTION 'exact accepted draft required for activation' USING ERRCODE='MO036';
 END IF;
 g:=ops.consume_ad_control_invocation(p_proof,'LISTING_CALIBRATION_ACTIVATE',p_id,p_id);
 IF g.organization_id<>p.organization_id OR NOT ops.lc_calibration_actor_scope(g.actor_user_id,p.organization_id,
      p.scope_kind,p.store_ref_id,'LISTING_CALIBRATION_ACCEPT') THEN
  RAISE EXCEPTION 'current calibration activation authority required' USING ERRCODE='MO092';
 END IF;
 IF p_digest IS NULL OR p_reference IS NULL OR length(btrim(p_reference)) NOT BETWEEN 1 AND 512
    OR p_digest<>v.accepted_digest OR p_digest<>ops.lc_calibration_digest(p_id)
    OR cardinality(ops.lc_calibration_combination_failures(p_id))<>0
    OR p.effective_from>now_at OR (p.effective_to IS NOT NULL AND p.effective_to<=now_at) THEN
  RAISE EXCEPTION 'accepted calibration is changed or outside its effective period' USING ERRCODE='MO036';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p.organization_id::text||':'||p.scope_key||':'||p.purpose_code,0));
 SELECT count(*),min(id::text)::uuid INTO overlap_count,previous FROM core.lc_calibration_package
   WHERE organization_id=p.organization_id AND scope_key=p.scope_key AND purpose_code=p.purpose_code
     AND status='ACTIVE' AND tstzrange(effective_from,effective_to,'[)') && tstzrange(p.effective_from,p.effective_to,'[)');
 IF overlap_count>1 THEN
  RAISE EXCEPTION 'multiple calibration ranges conflict with this exact replacement' USING ERRCODE='MO036';
 END IF;
 IF previous IS DISTINCT FROM v.replaces_package_id THEN
  RAISE EXCEPTION 'current calibration replacement differs from exact acceptance' USING ERRCODE='MO036';
 END IF;
 IF previous IS NOT NULL THEN
  UPDATE core.lc_calibration_package SET status='RETIRED',retired_at=now_at WHERE id=previous;
  INSERT INTO ops.lc_calibration_event VALUES(gen_random_uuid(),previous,'RETIRED',g.actor_user_id,
    ops.lc_calibration_digest(previous),p_reference,now_at);
 END IF;
 UPDATE core.lc_calibration_package SET status='ACTIVE',activated_at=now_at WHERE id=p_id;
 INSERT INTO ops.lc_calibration_event VALUES(gen_random_uuid(),p_id,'ACTIVATED',g.actor_user_id,p_digest,p_reference,now_at);
END $$;

CREATE FUNCTION ops.ad_action_blockers(p_basis text, p_cause text, p_blockers text[]) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
 SELECT CASE WHEN p_basis='CAUSE_BOUND_PROTECTION_STEP'
   AND ops.ad_required_action_evidence_kinds(p_basis,p_cause) IS NULL
   THEN coalesce(p_blockers,ARRAY['BLOCKER_PROJECTION_MISSING'])||ARRAY['CAUSE_BOUND_CAUSE_UNSUPPORTED']
 ELSE ARRAY(SELECT blocker FROM unnest(coalesce(p_blockers,ARRAY['BLOCKER_PROJECTION_MISSING'])) blocker
 WHERE NOT coalesce((p_basis='CAUSE_BOUND_PROTECTION_STEP' AND (
   p_cause='PROVEN_ADVERTISING_LOSS' AND blocker='AD_LINKED_CONVERSION_NOT_WRITE_GRADE'
   OR p_cause IN('PROMOTED_VARIANT_NOT_SELLABLE','PROMOTED_VARIANT_UNAVAILABLE')
   AND (blocker=ANY(ARRAY['AD_LINKED_QUANTITY_LINEAGE_UNAVAILABLE','MIXED_OR_UNRESOLVED_SALES_CURRENCY',
     'AD_LINKED_CONVERSION_NOT_WRITE_GRADE','PROVIDER_TO_CANONICAL_ATTRIBUTION_GAP_MATERIAL'])
   OR blocker~'^(LINE_ECONOMICS_OR_MAPPING_UNRESOLVED|LINE_COST_COMPONENT_UNAVAILABLE):[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'))),false)) END
$_$;

CREATE FUNCTION ops.ad_action_isolation_failures(p_set uuid, p_baseline uuid, p_at timestamp with time zone) RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'pg_temp'
    AS $$
BEGIN RETURN ARRAY(SELECT jsonb_array_elements_text(ops.ad_action_isolation_snapshot(p_set,p_baseline,p_at)->'failures')); END $$;

CREATE FUNCTION ops.ad_action_isolation_snapshot(p_set uuid, p_baseline uuid, p_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'mart', 'pg_temp'
    AS $$
DECLARE a record; b record; item record; before_context jsonb; after_context jsonb; factor text;
 failures text[]:=ARRAY[]::text[]; uncertainties text[]:=ARRAY[]::text[];
 commands jsonb:='[]'::jsonb; contexts jsonb:='[]'::jsonb; listings uuid[];
BEGIN
 SELECT * INTO a FROM core.ad_affected_set WHERE id=p_set;
 IF p_at IS NULL OR a.id IS NULL OR a.resolution_state<>'COMPLETE' OR a.resolved_at>p_at OR cardinality(a.product_variant_ids)=0 THEN
  RETURN jsonb_build_object('state','UNRESOLVED','failures','[]'::jsonb,
   'uncertainties',jsonb_build_array('CROSS_DOMAIN_CONTEXT_UNRESOLVED'),
   'knownPriceCommands','[]'::jsonb,'contexts','[]'::jsonb,'affectedSetId',p_set,'asOf',p_at);
 END IF;
 -- Internal Variant overlap includes listings in other stores/platforms, while retaining
 -- the exact frozen listing scope even if its current mapping has since ended.
 SELECT array_agg(DISTINCT id ORDER BY id) INTO listings FROM (
   SELECT unnest(a.platform_listing_variant_ids) id
   UNION SELECT m.platform_listing_variant_id FROM core.listing_mapping m
    WHERE m.organization_id=a.organization_id AND m.product_variant_id=ANY(a.product_variant_ids)
      AND m.status IN('ACTIVE','ENDED') AND m.effective_from<=p_at
      AND (m.effective_to IS NULL OR m.effective_to>p_at)) scoped;
 IF cardinality(listings)=0 OR listings IS NULL THEN
  uncertainties:=array_append(uncertainties,'CROSS_DOMAIN_CONTEXT_UNRESOLVED');
 END IF;
 -- A real command is already bound to the Shared approval/authority snapshot. An
 -- unexecuted recommendation or Task is deliberately absent from this predicate.
 SELECT coalesce(jsonb_agg(jsonb_build_object('commandId',c.id,'listingVariantId',c.platform_listing_variant_id,
    'state',c.state,'priorPrice',c.prior_price,'targetPrice',c.target_price,'currency',c.currency_code)
    ORDER BY c.id),'[]'::jsonb) INTO commands FROM ops.price_command c
 WHERE c.organization_id=a.organization_id AND c.platform_listing_variant_id=ANY(listings)
  AND c.created_at<=p_at AND c.state NOT IN('SUCCEEDED','FAILED_FINAL','COMPENSATED','COMPENSATION_FAILED')
  AND c.target_price<>c.prior_price;
 IF jsonb_array_length(commands)>0 THEN failures:=array_append(failures,'KNOWN_CROSS_DOMAIN_INTERVENTION'); END IF;
 IF p_baseline IS NULL THEN
  uncertainties:=array_append(uncertainties,'CROSS_DOMAIN_CONTEXT_UNRESOLVED');
 ELSE
  SELECT * INTO b FROM ops.ad_outcome_baseline WHERE id=p_baseline;
  IF b.id IS NULL OR b.organization_id<>a.organization_id OR b.affected_set_id<>a.id
   OR b.ad_native_object_id<>a.ad_native_object_id OR b.affected_set_digest<>a.affected_set_digest
   OR b.prepared_at>p_at THEN failures:=array_append(failures,'CROSS_DOMAIN_BASELINE_IDENTITY_MISMATCH');
  ELSE
   IF cardinality(b.listing_variant_ids)=0 THEN uncertainties:=array_append(uncertainties,'CROSS_DOMAIN_CONTEXT_UNRESOLVED'); END IF;
   FOR item IN SELECT unnest(b.listing_variant_ids) id LOOP
    before_context:=ops.ad_listing_isolation_context(item.id,b.prepared_at);
    after_context:=ops.ad_listing_isolation_context(item.id,p_at);
    contexts:=contexts||jsonb_build_array(jsonb_build_object('listingVariantId',item.id,
          'frozenAt',b.prepared_at,'before',before_context,'current',after_context));
    -- Known-to-known change is non-comparable. One unknown factor does not hide a
    -- different known factor, and unknown itself is not invented material change.
    FOREACH factor IN ARRAY ARRAY['price','currency','promotion','sellable','availability'] LOOP
     IF before_context->>factor IS NULL OR after_context->>factor IS NULL
       OR before_context->>factor='UNKNOWN' OR after_context->>factor='UNKNOWN' THEN
      uncertainties:=array_append(uncertainties,'CROSS_DOMAIN_CONTEXT_UNRESOLVED');
     ELSIF before_context->factor IS DISTINCT FROM after_context->factor THEN
      failures:=array_append(failures,'CROSS_DOMAIN_BASELINE_NOT_COMPARABLE');
     END IF;
    END LOOP;
   END LOOP;
  END IF;
 END IF;
 SELECT coalesce(array_agg(DISTINCT reason ORDER BY reason),ARRAY[]::text[]) INTO failures FROM unnest(failures) reason;
 SELECT coalesce(array_agg(DISTINCT reason ORDER BY reason),ARRAY[]::text[]) INTO uncertainties FROM unnest(uncertainties) reason;
 RETURN jsonb_build_object('state',CASE WHEN cardinality(failures)>0 THEN 'UNAVAILABLE'
    WHEN cardinality(uncertainties)>0 THEN 'UNRESOLVED' ELSE 'ISOLATED' END,
    'failures',to_jsonb(failures),'uncertainties',to_jsonb(uncertainties),
    'knownPriceCommands',commands,'contexts',contexts,
    'comparisonBasis','EXACT_ACCEPTED_PRE_ACTION_CONTEXT','affectedSetId',a.id,'asOf',p_at,
    'concurrencyBoundary','Committed known changes rechecked before transmission; no shared PriceCommand serialization claimed');
END $$;

CREATE FUNCTION ops.ad_active_containment(p_organization_id uuid, p_object_id uuid, p_store_id uuid, p_platform_code text, p_capability_code text, p_affected_digest text) RETURNS text[]
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'core', 'pg_temp'
    AS $_$
 SELECT coalesce(array_agg(DISTINCT CASE WHEN q.containment_kind='KILL_SWITCH_ACTIVE'
       THEN 'KILL_SWITCH_ACTIVE' ELSE q.containment_kind END),'{}'::text[])
 FROM ops.ad_containment q WHERE q.organization_id=p_organization_id
 AND (q.state<>'REENABLED' OR q.scope_kind='AUTHORITY_VERSION')
 AND (q.scope_kind='ENTITY' AND q.ad_native_object_id=p_object_id
 OR q.scope_kind='AFFECTED_SET' AND EXISTS(SELECT 1 FROM core.ad_affected_set held
   JOIN core.ad_affected_set subject ON subject.organization_id=held.organization_id
    AND subject.ad_native_object_id=p_object_id AND subject.affected_set_digest=p_affected_digest
   WHERE held.organization_id=q.organization_id AND held.affected_set_digest=q.affected_set_digest
    AND held.product_variant_ids && subject.product_variant_ids)
 OR q.scope_kind='PLATFORM_STORE_CAPABILITY' AND q.platform_code=p_platform_code
   AND q.store_id=p_store_id AND q.capability_code=p_capability_code
 OR q.scope_kind='PLATFORM_ACCOUNT_CAPABILITY' AND q.platform_code=p_platform_code AND q.capability_code=p_capability_code
   AND q.marketplace_account_id=(SELECT marketplace_account_id FROM core.store WHERE id=p_store_id)
 OR q.scope_kind='AUTHORITY_VERSION' AND EXISTS(SELECT 1 FROM ops.ad_decision_policy_bundle b
   WHERE b.organization_id=p_organization_id AND b.store_id=p_store_id
   AND (q.state<>'REENABLED' OR b.status='ACTIVE')
   AND (EXISTS(SELECT 1 FROM ops.ad_gate_authority gate WHERE gate.id=b.gate_authority_id
       AND p_object_id=ANY(gate.native_object_ids))
     OR EXISTS(SELECT 1 FROM ops.ad_action_authorization sealed JOIN ops.ad_bid_candidate candidate
       ON candidate.id=sealed.candidate_id WHERE sealed.bundle_id=b.id AND candidate.ad_native_object_id=p_object_id)
     OR EXISTS(SELECT 1 FROM ops.ad_manual_execution_packet packet
       WHERE packet.bundle_id=b.id AND packet.ad_native_object_id=p_object_id))
   AND ops.ad_bundle_consumes_authority_version(b.id,
     CASE WHEN q.authority_version_reference ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
       THEN q.authority_version_reference::uuid ELSE NULL END))
 OR q.scope_kind='AUTHORITY_VERSION' AND EXISTS(SELECT 1 FROM ops.ad_manual_execution_packet packet
   WHERE packet.organization_id=p_organization_id AND packet.store_id=p_store_id
   AND packet.ad_native_object_id=p_object_id
   AND (q.state<>'REENABLED' OR packet.state IN ('MANUAL_PACKET_DRAFT','MANUAL_PACKET_ENDORSED',
    'MANUAL_PACKET_ISSUED','MANUAL_EXECUTION_IN_PROGRESS','ACTION_REPORTED_CONFIGURATION_UNVERIFIED','MANUAL_EXECUTION_UNCERTAIN'))
   AND q.authority_version_reference=ANY(ARRAY[
     packet.semantic_profile_id::text,to_jsonb(packet)#>>'{authority_snapshot,policy,id}',
     to_jsonb(packet)#>>'{authority_snapshot,outcomePolicy,id}'])))
$_$;

CREATE FUNCTION ops.ad_actor_covers_affected_set(p_actor uuid, p_org uuid, p_set uuid, p_action text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'core', 'iam', 'pg_temp'
    AS $$
 SELECT EXISTS(SELECT 1 FROM core.ad_affected_set affected
 WHERE affected.id=p_set AND affected.organization_id=p_org AND affected.resolution_state='COMPLETE'
 AND cardinality(affected.product_variant_ids)>0 AND NOT EXISTS(
  SELECT 1 FROM unnest(affected.product_variant_ids) member WHERE NOT EXISTS(
   SELECT 1 FROM iam.user_scope_grant grant_row WHERE grant_row.user_id=p_actor
   AND grant_row.organization_id=p_org AND grant_row.action_code=p_action AND grant_row.status='ACTIVE'
   AND grant_row.effective_from<=statement_timestamp()
   AND (grant_row.effective_to IS NULL OR grant_row.effective_to>statement_timestamp())
   AND (grant_row.organization_ref_id=p_org OR grant_row.product_variant_ref_id=member))))
$$;

CREATE FUNCTION ops.ad_actor_has_organization_role_scope(p_actor uuid, p_org uuid, p_role text, p_action text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'iam', 'pg_temp'
    AS $$
 SELECT EXISTS(SELECT 1 FROM iam.user_account actor JOIN iam.identity_provider provider ON provider.id=actor.identity_provider_id
 JOIN iam.user_role_assignment role ON role.user_id=actor.id AND role.organization_id=actor.organization_id
 JOIN iam.business_role_action_scope capability ON capability.role_code=role.role_code
 JOIN iam.user_scope_grant scope ON scope.user_id=actor.id AND scope.organization_id=actor.organization_id
   AND scope.action_code=capability.action_code
 WHERE actor.id=p_actor AND actor.organization_id=p_org AND actor.status='ACTIVE'
 AND provider.status='ACTIVE' AND provider.verification_state='VERIFIED'
 AND role.role_code=p_role AND capability.action_code=p_action
 AND role.status='ACTIVE' AND role.effective_from<=clock_timestamp() AND (role.effective_to IS NULL OR role.effective_to>clock_timestamp())
 AND scope.organization_ref_id=p_org AND scope.status='ACTIVE' AND scope.effective_from<=clock_timestamp()
 AND (scope.effective_to IS NULL OR scope.effective_to>clock_timestamp()))
$$;

CREATE FUNCTION ops.ad_actor_has_role_scope(p_actor uuid, p_org uuid, p_store uuid, p_role text, p_action text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'iam', 'core', 'pg_temp'
    AS $$
 SELECT EXISTS(SELECT 1 FROM iam.user_role_assignment r JOIN iam.business_role_action_scope m ON m.role_code=r.role_code
 JOIN iam.user_scope_grant s ON s.user_id=r.user_id AND s.action_code=m.action_code
 JOIN core.store st ON st.id=p_store JOIN core.marketplace_account account ON account.id=st.marketplace_account_id
 WHERE r.user_id=p_actor AND r.organization_id=p_org AND s.organization_id=p_org AND st.organization_id=p_org
 AND EXISTS(SELECT 1 FROM iam.user_account actor JOIN iam.identity_provider provider ON provider.id=actor.identity_provider_id
   WHERE actor.id=p_actor AND actor.organization_id=p_org AND actor.status='ACTIVE' AND provider.status='ACTIVE')
 AND r.role_code=p_role AND r.status='ACTIVE' AND m.action_code=p_action
 AND r.effective_from<=statement_timestamp() AND (r.effective_to IS NULL OR r.effective_to>statement_timestamp())
 AND s.status='ACTIVE' AND s.effective_from<=statement_timestamp() AND (s.effective_to IS NULL OR s.effective_to>statement_timestamp())
 AND (s.organization_ref_id=p_org OR s.store_ref_id=p_store OR s.marketplace_account_ref_id=account.id
      OR s.legal_entity_ref_id=account.legal_entity_id))
$$;

CREATE FUNCTION ops.ad_bid_attempt_completes_once() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
    IF OLD.outcome_class <> 'IN_FLIGHT' THEN
        RAISE EXCEPTION 'a completed attempt is a permanent record' USING ERRCODE = 'MO096';
    END IF;
    IF NEW.id <> OLD.id OR NEW.command_id <> OLD.command_id
        OR NEW.attempt_no <> OLD.attempt_no OR NEW.purpose <> OLD.purpose
        OR NEW.fence_token <> OLD.fence_token OR NEW.lease_owner <> OLD.lease_owner
        OR NEW.started_at <> OLD.started_at OR NEW.correlation_id <> OLD.correlation_id
        OR NEW.request_digest <> OLD.request_digest
        OR NEW.operation_snapshot <> OLD.operation_snapshot
        OR NEW.expected_version_token IS DISTINCT FROM OLD.expected_version_token THEN
        RAISE EXCEPTION 'the identity of an attempt cannot be edited' USING ERRCODE = 'MO096';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.ad_bid_authority_snapshot(p_recommendation_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'core', 'platform', 'mart', 'pg_temp'
    AS $$
    SELECT jsonb_build_object(
        'proposal', jsonb_build_object(
            'id', r.id, 'organizationId', r.organization_id, 'storeId', r.store_id,
            'subjectKind', r.subject_kind, 'subjectId', r.subject_id,
            'actionKind', r.action_kind, 'parameters', r.proposed_parameters,
            'risk', r.risk_label, 'window', r.window_code,
            'validUntil', r.valid_until, 'entityDigest', r.entity_version_digest),
        'platformCode', obj.platform_code,
        'nativeObjectKey', obj.native_object_key,
        'nativeCampaignKey', obj.native_campaign_key,
        'nativeObjectKind', obj.native_object_kind,
        'lineageKey', obj.lineage_key,
        'lineageGeneration', obj.lineage_generation,
        'controlGranularityState', obj.control_granularity_state,
        'biddingMode', obj.bidding_mode,
        'semanticProfileId', obj.semantic_profile_id,
        'currentEntityDigest', ops.ad_entity_version_digest(obj.id, cd_id.value),
        'affectedSet', affected.item,
        'currentConfiguration', config.item,
        'candidate', candidate.item)
      FROM ops.recommendation r
      LEFT JOIN LATERAL (
          SELECT CASE WHEN ops.ad_bid_parameter_contract_is_valid(r.proposed_parameters)
                      THEN (r.proposed_parameters ->> 'candidateId')::uuid END AS value
      ) cd_id ON true
      LEFT JOIN core.ad_native_object obj
        ON obj.id = r.subject_id AND obj.organization_id = r.organization_id
       AND r.subject_kind = 'AD_NATIVE_OBJECT'
      LEFT JOIN LATERAL (
          SELECT jsonb_build_object('id', a.id, 'digest', a.affected_set_digest,
                     'resolution', a.resolution_state,
                     'variantIds', to_jsonb(a.product_variant_ids)) AS item
            FROM core.ad_affected_set a
           WHERE a.ad_native_object_id = obj.id AND a.organization_id = r.organization_id
           ORDER BY a.resolved_at DESC, a.id DESC LIMIT 1
      ) affected ON true
      LEFT JOIN LATERAL (
          SELECT jsonb_build_object('id', c.id, 'bid', c.observed_bid_amount,
                     'currency', c.bid_currency_code, 'unit', c.bid_unit_code,
                     'status', c.observed_status, 'grade', c.evidence_grade,
                     'generation', c.lineage_generation,
                     'observedAt', c.observed_at) AS item
            FROM core.ad_object_configuration_observation c
           WHERE c.ad_native_object_id = obj.id AND c.organization_id = r.organization_id
             AND NOT EXISTS (SELECT 1 FROM core.ad_object_configuration_observation later
                              WHERE later.supersedes_observation_id = c.id)
           ORDER BY c.observed_at DESC, c.id DESC LIMIT 1
      ) config ON true
      LEFT JOIN LATERAL (
          SELECT jsonb_build_object('id', cd.id, 'direction', cd.direction,
                     'basis', cd.candidate_basis, 'target', cd.provider_normalized_amount,
                     'currency', cd.currency_code, 'unit', cd.bid_unit_code,
                     'digest', cd.affected_set_digest,
                     'targetPolicyId', cd.target_policy_id,
                     'maxCpc', cd.max_cpc_amount) AS item
            FROM ops.ad_bid_candidate cd
           WHERE cd.organization_id = r.organization_id
             AND cd.id = CASE WHEN ops.ad_bid_parameter_contract_is_valid(r.proposed_parameters)
                              THEN (r.proposed_parameters ->> 'candidateId')::uuid END
      ) candidate ON true
     WHERE r.id = p_recommendation_id
$$;

CREATE FUNCTION ops.ad_bid_command_authority_matches(p_command_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'core', 'platform', 'pg_temp'
    AS $$
    SELECT coalesce(bool_and(
        c.authority_snapshot = ops.ad_bid_authority_snapshot(r.id)
        AND a.recommendation_id = r.id AND a.organization_id = c.organization_id
        AND r.organization_id = c.organization_id AND r.store_id = c.store_id
        AND r.subject_kind = 'AD_NATIVE_OBJECT'
        AND r.subject_id = c.ad_native_object_id
        AND r.action_kind = 'AD_BID_CHANGE'
        AND r.valid_until > statement_timestamp()
        AND c.approval_expires_at > statement_timestamp()
        AND c.entity_version_digest = r.entity_version_digest
        AND ops.ad_bid_parameter_contract_is_valid(r.proposed_parameters)
        AND c.idempotency_key = 'abc-' || r.id::text
        AND c.candidate_id = (r.proposed_parameters ->> 'candidateId')::uuid
        AND c.direction = (r.proposed_parameters ->> 'direction')
        AND c.target_bid_amount = (r.proposed_parameters ->> 'targetBid')::numeric
        -- The transmitted number is the generated, provider-normalized one. If
        -- these ever differ, something rounded after the approval.
        AND c.target_bid_amount = cd.provider_normalized_amount
        AND c.currency_code = cd.currency_code
        AND c.bid_unit_code = cd.bid_unit_code
        AND c.candidate_basis = cd.candidate_basis
        AND c.direction = cd.direction
        AND c.affected_set_digest = cd.affected_set_digest
        -- The affected set has not changed since the candidate was generated.
        AND c.affected_set_digest = (c.authority_snapshot #>> '{affectedSet,digest}')
        AND (c.authority_snapshot #>> '{affectedSet,resolution}') = 'COMPLETE'
        -- The object is the same generation, and still independently controllable.
        AND c.lineage_generation = obj.lineage_generation
        AND obj.control_granularity_state = 'PROVEN_INDEPENDENT'
        AND obj.status = 'ACTIVE'
        -- The prior bid the command captured is still the observed one.
        AND c.prior_configuration_id::text = (c.authority_snapshot #>> '{currentConfiguration,id}')
        AND c.prior_bid_amount = (c.authority_snapshot #>> '{currentConfiguration,bid}')::numeric
        AND c.currency_code = (c.authority_snapshot #>> '{currentConfiguration,currency}')
        -- The capability is the advertising one, verified and live.
        AND cap.capability_code = 'ad-bid-change'
        AND cap.read_write_class = 'WRITE'
        AND cap.verification_state = 'VERIFIED'
        AND cap.status = 'ACTIVE'
        AND cap.deprecated_at IS NULL
        AND cap.platform_code = c.platform_code
        -- The bundle is the unique complete active one for this exact scope.
        AND b.status = 'ACTIVE'
        AND b.validation_state = 'VALIDATED'
        AND b.organization_id = c.organization_id
        AND b.store_id = c.store_id
        AND b.direction = c.direction
        AND b.candidate_basis = c.candidate_basis
        AND b.native_object_kind = obj.native_object_kind
        AND b.effective_from <= statement_timestamp()
        AND (b.effective_to IS NULL OR b.effective_to > statement_timestamp())
        -- The reservation is this command's, and still held.
        AND res.state = 'ACTIVE'
        AND res.ad_native_object_id = c.ad_native_object_id
        AND res.affected_set_digest = c.affected_set_digest), false)
      FROM ops.ad_bid_command c
      JOIN ops.recommendation r
        ON r.id = c.recommendation_id AND r.organization_id = c.organization_id
      JOIN ops.approval_decision a ON a.id = c.approval_decision_id
      JOIN ops.ad_bid_candidate cd
        ON cd.id = c.candidate_id AND cd.organization_id = c.organization_id
      JOIN core.ad_native_object obj
        ON obj.id = c.ad_native_object_id AND obj.organization_id = c.organization_id
      JOIN platform.platform_capability cap ON cap.id = c.capability_id
      JOIN ops.ad_decision_policy_bundle b
        ON b.id = c.bundle_id AND b.organization_id = c.organization_id
      JOIN ops.ad_action_reservation res
        ON res.id = c.reservation_id AND res.organization_id = c.organization_id
     WHERE c.id = p_command_id
$$;

CREATE FUNCTION ops.ad_bid_compensation_is_observed() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
BEGIN
    IF NEW.state <> 'COMPENSATED' OR OLD.state = 'COMPENSATED' THEN
        RETURN NEW;
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM ops.ad_bid_command_readback rb
          JOIN ops.ad_bid_command_attempt at ON at.id = rb.attempt_id
         WHERE rb.command_id = NEW.id
           AND rb.match_state = 'MATCHES_PRIOR'
           AND rb.observed_bid = NEW.prior_bid_amount
           AND rb.currency_code = NEW.currency_code
           AND rb.bid_unit_code = NEW.bid_unit_code
           AND at.fence_token = NEW.fence_token
           AND at.raw_observation_id IS NOT NULL)
        OR NOT EXISTS (
        SELECT 1 FROM ops.ad_bid_command_attempt at
         WHERE at.command_id = NEW.id AND at.purpose = 'RESTORE'
           AND at.outcome_class = 'ACCEPTED'
           AND at.raw_observation_id IS NOT NULL
           AND at.completed_at < (SELECT max(rb.observed_at) FROM ops.ad_bid_command_readback rb
              JOIN ops.ad_bid_command_attempt current_read ON current_read.id=rb.attempt_id
              WHERE rb.command_id=NEW.id AND current_read.fence_token=NEW.fence_token)) THEN
        RAISE EXCEPTION 'a compensation is complete only when the prior bid was observed'
            USING ERRCODE = 'MO094';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.ad_bid_execution_pass_matches_bundle(p_command_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
    SELECT EXISTS (
        SELECT 1
          FROM ops.ad_bid_command c
          JOIN ops.guardrail_evaluation g
            ON g.recommendation_id = c.recommendation_id
           AND g.organization_id = c.organization_id
         WHERE c.id = p_command_id
           AND g.purpose = 'EXECUTION'
           AND g.outcome = 'PASS'
           AND g.ad_decision_bundle_id = c.bundle_id)
$$;

CREATE FUNCTION ops.ad_bid_parameter_contract_is_valid(p_parameters jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
    SELECT p_parameters IS NOT NULL
       AND jsonb_typeof(p_parameters) = 'object'
       AND (p_parameters - 'candidateId' - 'direction' - 'targetBid') = '{}'::jsonb
       AND p_parameters ? 'candidateId'
       AND p_parameters ? 'direction'
       AND p_parameters ? 'targetBid'
       AND (p_parameters ->> 'candidateId') ~
           '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       AND (p_parameters ->> 'direction') IN
           ('PROTECTION_DECREASE', 'OPTIMIZATION_INCREASE', 'EXACT_PRIOR_BID_COMPENSATION')
       AND (p_parameters ->> 'targetBid') ~ '^[0-9]{1,14}([.][0-9]{1,4})?$'
       AND (p_parameters ->> 'targetBid')::numeric > 0
$_$;

CREATE FUNCTION ops.ad_bid_retry_is_proven(p_command uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
 SELECT EXISTS(SELECT 1 FROM ops.ad_bid_command c
 JOIN ops.ad_bid_command_readback rb ON rb.command_id=c.id
 JOIN ops.ad_bid_command_attempt read_attempt ON read_attempt.id=rb.attempt_id
 WHERE c.id=p_command AND c.retry_budget_remaining>0 AND rb.match_state='MATCHES_PRIOR'
 AND rb.bid_unit_code=c.bid_unit_code AND rb.currency_code=c.currency_code
 AND read_attempt.fence_token=c.fence_token AND rb.observed_at>statement_timestamp()-interval '30 seconds'
 AND rb.id=(SELECT latest.id FROM ops.ad_bid_command_readback latest WHERE latest.command_id=c.id
  ORDER BY latest.observed_at DESC,latest.id DESC LIMIT 1)
 AND EXISTS(SELECT 1 FROM ops.ad_bid_command_attempt proof WHERE proof.command_id=c.id
  AND proof.completed_at<=rb.observed_at AND proof.raw_observation_id IS NOT NULL
  AND (proof.error_code='provider_explicit_not_applied'
   OR proof.purpose='STATUS_ENQUIRY' AND proof.outcome_class IN ('REJECTED','ACCEPTED')
    AND proof.operation_snapshot#>>'{adSemanticProfile,idempotency_semantics}'='VERIFIED_NATIVE_KEY'))
 AND NOT EXISTS(SELECT 1 FROM ops.ad_bid_command_attempt pending WHERE pending.command_id=c.id
  AND pending.outcome_class='IN_FLIGHT') AND cardinality(ops.evaluate_ad_bid_write_gate(c.id))=0)
$$;

CREATE FUNCTION ops.ad_brief_publication_is_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
BEGIN
    -- A published report is what somebody read on the day. Editing it would
    -- rewrite the basis of a decision already taken; a later reading is a new
    -- publication that says what changed.
    RAISE EXCEPTION 'a published brief is a permanent record'
        USING ERRCODE = 'MO044';
END;
$$;

CREATE FUNCTION ops.ad_bundle_activation_is_validated() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'core', 'platform', 'pg_temp'
    AS $$
DECLARE failures text[];
BEGIN
    IF NEW.status <> 'ACTIVE' THEN
        RETURN NEW;
    END IF;
    failures := ops.ad_bundle_validation_failures(NEW.id);
    IF cardinality(failures) > 0 THEN
        RAISE EXCEPTION 'advertising decision policy bundle is not coherent: %',
            array_to_string(failures, ',') USING ERRCODE = 'MO099';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.ad_bundle_authority_snapshot(p_bundle uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'core', 'platform', 'pg_temp'
    AS $$
 SELECT jsonb_build_object('bundle',to_jsonb(b),'semantic',(SELECT to_jsonb(x) FROM platform.ad_semantic_profile x WHERE x.id=b.semantic_profile_id),
 'conversion',(SELECT to_jsonb(x) FROM core.ad_conversion_definition x WHERE x.id=b.conversion_definition_id),
 'allowableCpa',(SELECT to_jsonb(x) FROM core.ad_allowable_cpa_definition x WHERE x.id=b.allowable_cpa_definition_id),
 'qualification',(SELECT to_jsonb(x) FROM core.ad_optimization_qualification_policy x WHERE x.id=b.qualification_policy_id),
 'target',(SELECT to_jsonb(x) FROM core.ad_bid_target_policy x WHERE x.id=b.target_policy_id),
 'outcome',(SELECT to_jsonb(x) FROM core.ad_outcome_policy x WHERE x.id=b.outcome_policy_id),
 'priority',(SELECT to_jsonb(x) FROM core.ad_priority_policy x WHERE x.id=b.priority_policy_id),
 'humanSlo',(SELECT to_jsonb(x) FROM core.ad_human_slo_profile x WHERE x.id=b.human_slo_profile_id),
 'lease',(SELECT to_jsonb(x) FROM core.ad_approval_lease_policy x WHERE x.id=b.approval_lease_policy_id),
 'exposure',(SELECT to_jsonb(x) FROM core.ad_exposure_envelope x WHERE x.id=b.exposure_envelope_id),
 'materiality',(SELECT to_jsonb(x) FROM core.ad_materiality_policy x WHERE x.id=b.materiality_policy_id),
 'freshness',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.id),'[]'::jsonb)
   FROM core.ad_freshness_profile x WHERE x.organization_id=b.organization_id AND x.status='ACTIVE'
   AND (x.scope_kind='ORGANIZATION' OR x.scope_kind='PLATFORM' AND x.platform_code=b.platform_code
        OR x.scope_kind='STORE' AND x.store_ref_id=b.store_id)
   AND (x.semantic_profile_id IS NULL OR x.semantic_profile_id=b.semantic_profile_id)),
 'gate',(SELECT to_jsonb(x) FROM ops.ad_gate_authority x WHERE x.id=b.gate_authority_id),
 'promotion',(SELECT to_jsonb(x) FROM ops.ad_ordinary_promotion x WHERE x.id=b.ordinary_promotion_id))
 FROM ops.ad_decision_policy_bundle b WHERE b.id=p_bundle
$$;

CREATE FUNCTION ops.ad_bundle_consumes_authority_version(p_bundle uuid, p_authority uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'core', 'pg_temp'
    AS $$
 SELECT EXISTS(SELECT 1 FROM ops.ad_decision_policy_bundle b WHERE b.id=p_bundle AND (
  p_authority=ANY(ARRAY[b.id,b.semantic_profile_id,b.conversion_definition_id,b.allowable_cpa_definition_id,
   b.qualification_policy_id,b.target_policy_id,b.outcome_policy_id,b.priority_policy_id,b.human_slo_profile_id,
   b.approval_lease_policy_id,b.exposure_envelope_id,b.materiality_policy_id,b.ordinary_promotion_id])
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(ops.ad_bundle_authority_snapshot(b.id)->'freshness') profile
    WHERE profile->>'id'=p_authority::text)
  OR EXISTS(SELECT 1 FROM ops.ad_action_authorization sealed
    CROSS JOIN LATERAL jsonb_array_elements(coalesce(sealed.authority_snapshot->'freshness','[]'::jsonb)) profile
    WHERE sealed.bundle_id=b.id AND profile->>'id'=p_authority::text)))
$$;

CREATE FUNCTION ops.ad_bundle_content_is_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$ BEGIN
 IF OLD.status IN ('SUPERSEDED','REVOKED') OR
 (to_jsonb(OLD)-ARRAY['status','effective_to','validation_state','validation_failure_codes',
  'activated_by_user_id','endorsed_by_user_id','approved_by_user_id','gate_authority_id','updated_at','version'])
 IS DISTINCT FROM
 (to_jsonb(NEW)-ARRAY['status','effective_to','validation_state','validation_failure_codes',
  'activated_by_user_id','endorsed_by_user_id','approved_by_user_id','gate_authority_id','updated_at','version']) THEN
  RAISE EXCEPTION 'new Bundle content requires a new immutable version' USING ERRCODE='MO096'; END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION ops.ad_bundle_validation_failures(p_bundle_id uuid) RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'platform', 'pg_temp'
    AS $_$
DECLARE failures text[]; snapshot jsonb; component record; b ops.ad_decision_policy_bundle%ROWTYPE;
BEGIN
 failures:=ops.ad_bundle_validation_failures_base(p_bundle_id);
 SELECT * INTO b FROM ops.ad_decision_policy_bundle WHERE id=p_bundle_id;
 IF NOT FOUND THEN RETURN failures; END IF;
 snapshot:=ops.ad_bundle_authority_snapshot(p_bundle_id);
 FOR component IN SELECT key,value FROM jsonb_each(snapshot)
 WHERE key IN ('conversion','allowableCpa','qualification','target','outcome','priority','humanSlo','lease','exposure','materiality') LOOP
  IF component.value IS NULL OR component.value='null'::jsonb
   OR component.value->>'status'<>'ACTIVE'
   OR (component.value->>'effective_from')::timestamptz>statement_timestamp()
   OR (component.value->>'effective_to')::timestamptz<=statement_timestamp()
   OR component.value->>'organization_id'<>b.organization_id::text
   OR component.value->>'scope_kind'='STORE' AND component.value->>'store_ref_id'<>b.store_id::text
   OR component.value->>'scope_kind'='PLATFORM' AND component.value->>'platform_code'<>b.platform_code THEN
   failures:=array_append(failures,upper(component.key)||'_AUTHORITY_NOT_CURRENT'); END IF;
 END LOOP;
 IF snapshot#>>'{semantic,status}' IS DISTINCT FROM 'ACTIVE'
 OR (snapshot#>>'{semantic,effective_to}')::timestamptz<=statement_timestamp() THEN
  failures:=array_append(failures,'SEMANTIC_AUTHORITY_NOT_CURRENT'); END IF;
 IF jsonb_array_length(snapshot->'freshness')=0 THEN failures:=array_append(failures,'FRESHNESS_AUTHORITY_MISSING'); END IF;
 -- Recovery authorizes replacement versions; the rejected immutable reference
 -- never becomes valid again, including after the review itself is closed.
 IF EXISTS(SELECT 1 FROM ops.ad_containment q WHERE q.organization_id=b.organization_id
   AND q.scope_kind='AUTHORITY_VERSION' AND ops.ad_bundle_consumes_authority_version(b.id,
   CASE WHEN q.authority_version_reference ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
    THEN q.authority_version_reference::uuid ELSE NULL END)) THEN
  failures:=array_append(failures,'AUTHORITY_VERSION_QUARANTINED'); END IF;
 RETURN ARRAY(SELECT DISTINCT failure FROM unnest(failures) failure ORDER BY failure);
END $_$;

CREATE FUNCTION ops.ad_bundle_validation_failures_base(p_bundle_id uuid) RETURNS text[]
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'core', 'platform', 'pg_temp'
    AS $$
DECLARE
    bundle            ops.ad_decision_policy_bundle%ROWTYPE;
    conversion        core.ad_conversion_definition%ROWTYPE;
    cpa               core.ad_allowable_cpa_definition%ROWTYPE;
    target            core.ad_bid_target_policy%ROWTYPE;
    profile           platform.ad_semantic_profile%ROWTYPE;
    qualification     core.ad_optimization_qualification_policy%ROWTYPE;
    failures          text[] := '{}';
    freshness_gaps    text[];
BEGIN
    SELECT * INTO bundle FROM ops.ad_decision_policy_bundle WHERE id = p_bundle_id;
    IF NOT FOUND THEN
        RETURN ARRAY['BUNDLE_NOT_FOUND'];
    END IF;

    SELECT * INTO conversion FROM core.ad_conversion_definition
        WHERE id = bundle.conversion_definition_id;
    SELECT * INTO cpa FROM core.ad_allowable_cpa_definition
        WHERE id = bundle.allowable_cpa_definition_id;
    SELECT * INTO target FROM core.ad_bid_target_policy
        WHERE id = bundle.target_policy_id;
    SELECT * INTO profile FROM platform.ad_semantic_profile
        WHERE id = bundle.semantic_profile_id;
    SELECT * INTO qualification FROM core.ad_optimization_qualification_policy
        WHERE id = bundle.qualification_policy_id;

    -- Every referenced version must still be in force at the bundle's own start.
    IF conversion.status NOT IN ('ACTIVE', 'RETIRED')
        OR conversion.effective_from > bundle.effective_from
        OR (conversion.effective_to IS NOT NULL
            AND conversion.effective_to <= bundle.effective_from) THEN
        failures := array_append(failures, 'CONVERSION_DEFINITION_NOT_IN_FORCE');
    END IF;
    IF cpa.status NOT IN ('ACTIVE', 'RETIRED')
        OR cpa.effective_from > bundle.effective_from
        OR (cpa.effective_to IS NOT NULL AND cpa.effective_to <= bundle.effective_from) THEN
        failures := array_append(failures, 'ALLOWABLE_CPA_DEFINITION_NOT_IN_FORCE');
    END IF;
    IF target.status NOT IN ('ACTIVE', 'RETIRED')
        OR target.effective_from > bundle.effective_from
        OR (target.effective_to IS NOT NULL AND target.effective_to <= bundle.effective_from) THEN
        failures := array_append(failures, 'TARGET_POLICY_NOT_IN_FORCE');
    END IF;

    -- The stage rule, checked where the two definitions meet. This is the
    -- combination that produces a Max CPC, and a mismatch here is the one the
    -- Contract cares most about.
    IF conversion.sale_stage IS DISTINCT FROM cpa.sale_stage THEN
        failures := array_append(failures, 'CONVERSION_AND_ALLOWABLE_CPA_STAGE_MISMATCH');
    END IF;
    IF conversion.sale_stage = 'PROVIDER_NATIVE_OBSERVATION' THEN
        failures := array_append(failures, 'CONVERSION_STAGE_IS_PROVIDER_OBSERVATION');
    END IF;

    -- The target policy must be the one this bundle's scope actually describes.
    IF target.direction IS DISTINCT FROM bundle.direction
        OR target.candidate_basis IS DISTINCT FROM bundle.candidate_basis
        OR target.native_object_kind IS DISTINCT FROM bundle.native_object_kind THEN
        failures := array_append(failures, 'TARGET_POLICY_SCOPE_MISMATCH');
    END IF;

    -- Provider semantics must be able to express an exact bid at all. An
    -- unverified profile is permitted for Shadow and diagnosis; a bundle that
    -- authorizes a write is not one of those.
    IF profile.verification_state <> 'VERIFIED'
        OR profile.source_maturity = 'SYNTHETIC_FIXTURE'
        OR NOT profile.bid_field_present
        OR profile.bid_step IS NULL
        OR profile.bid_precision IS NULL
        OR profile.readback_semantics IN ('NOT_AVAILABLE', 'UNKNOWN') THEN
        failures := array_append(failures, 'SEMANTIC_PROFILE_NOT_WRITE_CAPABLE');
    END IF;

    -- Purpose monotonicity, delegated to the authority that owns it.
    freshness_gaps := core.ad_freshness_purpose_violations(
        bundle.organization_id, bundle.effective_from);
    IF cardinality(freshness_gaps) > 0 THEN
        failures := array_append(failures, 'FRESHNESS_PURPOSE_MONOTONICITY_VIOLATED');
    END IF;
    IF NOT core.ad_qualification_tier_is_monotonic(
            bundle.organization_id, qualification.scope_kind, qualification.platform_code,
            qualification.store_ref_id, bundle.effective_from) THEN
        failures := array_append(failures, 'QUALIFICATION_TIER_MONOTONICITY_VIOLATED');
    END IF;

    -- An ordinary route only exists where a promotion record says it does. This
    -- Slice creates no promotion record, so a bundle claiming one fails here.
    IF bundle.ordinary_promotion_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM ops.ad_ordinary_promotion promotion JOIN ops.ad_gate_authority gate
        ON gate.id=promotion.gate_authority_id WHERE promotion.id=bundle.ordinary_promotion_id
        AND promotion.bundle_id=bundle.id AND promotion.status='ACTIVE'
        AND gate.gate_kind='GATE_E' AND gate.status='ACTIVE'
        AND promotion.valid_until>statement_timestamp() AND gate.valid_until>statement_timestamp()) THEN
        failures := array_append(failures, 'ORDINARY_ROUTE_PROMOTION_NOT_RECOGNISED');
    END IF;

    RETURN failures;
END;
$$;

CREATE FUNCTION ops.ad_change_to_targeted_request() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'ledger', 'platform'
    AS $$
DECLARE
    data jsonb; versions jsonb[];
    v_organization uuid; v_object_id uuid; v_store_id uuid; v_account_id uuid;
    v_variant_id uuid; v_listing_id uuid; v_platform_code text; v_dependent_variants uuid[];
    source_reference text;
    accepted timestamptz:=clock_timestamp();
    due timestamptz; object_row record; field text; provenance core.fact_provenance;
BEGIN
    IF TG_OP='UPDATE' AND NEW IS NOT DISTINCT FROM OLD THEN RETURN NEW; END IF;
    versions:=CASE WHEN TG_OP='UPDATE' THEN ARRAY[to_jsonb(OLD),to_jsonb(NEW)]
        WHEN TG_OP='DELETE' THEN ARRAY[to_jsonb(OLD)] ELSE ARRAY[to_jsonb(NEW)] END;
    -- Both sides of a remapping/status/scope change must wake their prior dependants.
    FOREACH data IN ARRAY versions LOOP
    v_organization:=nullif(data->>'organization_id','')::uuid;
    v_object_id:=nullif(data->>'ad_native_object_id','')::uuid;
    v_store_id:=nullif(coalesce(data->>'store_id',data->>'store_ref_id'),'')::uuid;
    v_account_id:=nullif(data->>'marketplace_account_id','')::uuid;
    v_variant_id:=nullif(data->>'product_variant_id','')::uuid;
    v_listing_id:=nullif(coalesce(data->>'platform_listing_variant_id',data->>'listing_variant_id'),'')::uuid;
    v_platform_code:=data->>'platform_code';
    source_reference:=TG_TABLE_SCHEMA||'.'||TG_TABLE_NAME||':'||coalesce(data->>'id','version');
    provenance:=NULL;
    IF data->>'provenance_id' IS NOT NULL THEN
        SELECT * INTO provenance FROM core.fact_provenance WHERE id=(data->>'provenance_id')::uuid AND organization_id=v_organization;
    END IF;
    v_dependent_variants:=NULL;
    IF TG_TABLE_NAME='listing_mapping' THEN
        v_dependent_variants:=ARRAY[v_variant_id];v_variant_id:=NULL;
        v_store_id:=NULL;v_account_id:=NULL;v_platform_code:=NULL;
    ELSIF TG_TABLE_SCHEMA='ledger' AND TG_TABLE_NAME IN ('sales_fact','return_fact','settlement_fact','finance_fee_fact','return_quality_evidence_snapshot') THEN
        -- Company economics includes every channel of each affected ProductVariant.
        -- A sale in another store therefore wakes the same product's advertising,
        -- while a different product or organization remains outside that fanout.
        SELECT array_agg(DISTINCT mapping.product_variant_id) INTO v_dependent_variants
          FROM core.listing_mapping mapping WHERE mapping.organization_id=v_organization
            AND mapping.platform_listing_variant_id=v_listing_id;
        v_store_id:=NULL;v_account_id:=NULL;v_platform_code:=NULL;
    END IF;
    IF TG_TABLE_NAME='ad_native_object' THEN v_object_id:=(data->>'id')::uuid; END IF;
    IF TG_TABLE_NAME='ad_object_relationship' THEN v_object_id:=nullif(data->>'parent_object_id','')::uuid; END IF;
    IF v_object_id IS NULL AND data->>'case_id' IS NOT NULL THEN
        SELECT ad_native_object_id INTO v_object_id FROM mart.ad_case WHERE id=(data->>'case_id')::uuid;
    END IF;
    IF v_object_id IS NULL AND data->>'command_id' IS NOT NULL THEN
        SELECT ad_native_object_id INTO v_object_id FROM ops.ad_bid_command WHERE id=(data->>'command_id')::uuid;
    END IF;
    IF v_object_id IS NULL AND data->>'packet_id' IS NOT NULL THEN
        SELECT ad_native_object_id INTO v_object_id FROM ops.ad_manual_execution_packet WHERE id=(data->>'packet_id')::uuid;
    END IF;
    FOR object_row IN SELECT obj.id,obj.organization_id FROM core.ad_native_object obj
        WHERE (v_organization IS NULL OR obj.organization_id=v_organization)
          AND (v_platform_code IS NULL OR obj.platform_code=v_platform_code)
          AND (v_object_id IS NULL OR obj.id=v_object_id)
          AND (v_store_id IS NULL OR obj.store_id=v_store_id)
          AND (v_account_id IS NULL OR EXISTS(SELECT 1 FROM core.store object_store
                WHERE object_store.id=obj.store_id AND object_store.marketplace_account_id=v_account_id))
          AND (v_variant_id IS NULL OR EXISTS(SELECT 1 FROM core.ad_affected_set affected
                WHERE affected.ad_native_object_id=obj.id AND v_variant_id=ANY(affected.product_variant_ids)))
          AND ((v_listing_id IS NULL AND v_dependent_variants IS NULL) OR EXISTS(SELECT 1 FROM core.ad_affected_set affected
                WHERE affected.ad_native_object_id=obj.id AND (v_listing_id=ANY(affected.platform_listing_variant_ids)
                    OR affected.product_variant_ids && v_dependent_variants))
                OR EXISTS(SELECT 1 FROM core.ad_object_relationship rel
                    WHERE rel.parent_object_id=obj.id AND rel.platform_listing_variant_id=v_listing_id))
    LOOP
        PERFORM ops.enqueue_ad_change(object_row.organization_id,object_row.id,TG_ARGV[0],source_reference,accepted);
        INSERT INTO ops.ad_trace_event(id,organization_id,ad_native_object_id,path_kind,stage_code,status,
            correlation_id,subject_reference,detail,occurred_at)
        VALUES(gen_random_uuid(),object_row.organization_id,object_row.id,'TARGETED','FACT_ACCEPTED','OBSERVED',
            'ad-fact:'||gen_random_uuid(),source_reference,jsonb_build_object('triggerClass',TG_ARGV[0],
              'sourceEventTime',coalesce(data->'occurred_at',data->'source_time',to_jsonb(provenance.source_time)),
              'sourceUpdatedAt',data->'source_updated_at',
              'ingestedAt',coalesce(data->'ingested_at',to_jsonb(provenance.ingestion_time)),
              'factAcceptedAt',accepted),accepted);
        FOREACH field IN ARRAY ARRAY['expires_at','valid_until','effective_from','effective_to','review_due_at',
                'early_observation_due_at','operational_observation_due_at','settled_observation_due_at']
        LOOP
            due:=nullif(data->>field,'')::timestamptz;
            IF due IS NOT NULL AND due>accepted THEN
                INSERT INTO ops.ad_recalculation_due(organization_id,ad_native_object_id,trigger_class,source_reference,due_at)
                VALUES(object_row.organization_id,object_row.id,TG_ARGV[0],source_reference||':'||field,due)
                ON CONFLICT DO NOTHING;
            END IF;
        END LOOP;
    END LOOP;
    END LOOP;
    RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;

CREATE FUNCTION ops.ad_completed_sales_guard_state(p_command_id uuid, p_coverage numeric) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'core', 'pg_temp'
    AS $$
DECLARE
    command  ops.ad_bid_command%ROWTYPE;
    policy   core.ad_outcome_policy%ROWTYPE;
    landed   timestamptz;
BEGIN
    SELECT * INTO command FROM ops.ad_bid_command WHERE id = p_command_id;
    IF NOT FOUND THEN
        RETURN 'SALES_TOO_RECENT';
    END IF;

    SELECT p.* INTO policy
      FROM ops.ad_decision_policy_bundle b
      JOIN core.ad_outcome_policy p ON p.id = b.outcome_policy_id
     WHERE b.id = command.bundle_id;
    IF NOT FOUND THEN
        RETURN 'SALES_TOO_RECENT';
    END IF;

    -- The clock starts when the write was proven to have landed, which is the
    -- first readback that matched the target. Not when the command was
    -- created, and not when somebody approved it.
    SELECT min(rb.observed_at) INTO landed
      FROM ops.ad_bid_command_readback rb
     WHERE rb.command_id = p_command_id AND rb.match_state = 'MATCHES_TARGET';
    IF landed IS NULL THEN
        RETURN 'SALES_TOO_RECENT';
    END IF;

    IF clock_timestamp() < landed + make_interval(hours => policy.completed_sales_guard_hours) THEN
        RETURN 'SALES_TOO_RECENT';
    END IF;
    IF p_coverage IS NULL OR p_coverage < policy.minimum_settled_coverage_ratio THEN
        RETURN 'COVERAGE_INSUFFICIENT';
    END IF;
    RETURN 'SATISFIED';
END;
$$;

CREATE FUNCTION ops.ad_control_history_is_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$ BEGIN
 RAISE EXCEPTION 'advertising authority history is immutable' USING ERRCODE='MO096';
END $$;

CREATE FUNCTION ops.ad_credential_authority_expiry(p_credential uuid, p_store uuid) RETURNS timestamp with time zone
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'platform', 'core', 'pg_temp'
    AS $$
 SELECT min(least(e.valid_until,c.expires_at)) FROM platform.credential_metadata c
 JOIN platform.ad_write_credential_attestation e ON e.credential_id=c.id
 JOIN core.store st ON st.id=p_store AND st.organization_id=c.organization_id
 WHERE c.id=p_credential AND c.status='ACTIVE' AND c.purpose_code='ADS_WRITE'
 AND c.effective_from<=statement_timestamp() AND c.expires_at>statement_timestamp()
 AND e.organization_id=c.organization_id AND e.marketplace_account_id=c.marketplace_account_id
 AND st.marketplace_account_id=c.marketplace_account_id AND p_store=ANY(e.store_ids)
 AND e.status='VERIFIED' AND e.verified_at<=statement_timestamp() AND e.valid_until>statement_timestamp()
 AND (c.scope_mode='ACCOUNT' OR EXISTS(SELECT 1 FROM platform.credential_store_scope cs
 WHERE cs.credential_id=c.id AND cs.store_id=p_store))
$$;

CREATE FUNCTION ops.ad_economic_cause_bound_failures(p_candidate uuid, p_at timestamp with time zone) RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'mart', 'pg_temp'
    AS $$
DECLARE candidate ops.ad_bid_candidate%ROWTYPE; kase mart.ad_case%ROWTYPE;
 required text[]; reasons text[]:=ARRAY[]::text[];
BEGIN
 SELECT * INTO candidate FROM ops.ad_bid_candidate WHERE id=p_candidate;
 IF NOT FOUND THEN RETURN ARRAY['CANDIDATE_UNRESOLVED']; END IF;
 IF candidate.candidate_basis<>'CAUSE_BOUND_PROTECTION_STEP' OR candidate.cause_code<>'PROVEN_ADVERTISING_LOSS'
 THEN RETURN reasons; END IF;
 SELECT * INTO kase FROM mart.ad_case WHERE id=candidate.case_id AND organization_id=candidate.organization_id;
 IF NOT FOUND OR kase.superseded_at IS NOT NULL OR kase.lane<>'PROTECTION'
 OR kase.cause_code<>candidate.cause_code OR candidate.direction<>'PROTECTION_DECREASE'
 OR candidate.max_cpc_amount IS NOT NULL OR kase.max_cpc_state='AVAILABLE'
 OR kase.contribution_profit_state<>'AVAILABLE' OR kase.contribution_profit_amount IS NULL
 OR kase.contribution_profit_amount>=0 OR kase.official_spend_state<>'AVAILABLE'
 OR kase.official_spend_amount IS NULL OR kase.official_spend_amount<=0
 OR kase.current_bid_state<>'AVAILABLE' OR kase.current_bid_amount IS NULL
 OR kase.current_bid_amount<>candidate.current_bid_amount
 OR NOT EXISTS(SELECT 1 FROM core.ad_affected_set a WHERE a.id=kase.affected_set_id
   AND a.organization_id=candidate.organization_id AND a.resolution_state='COMPLETE'
   AND a.affected_set_digest=candidate.affected_set_digest AND cardinality(a.product_variant_ids)>0)
 THEN reasons:=array_append(reasons,'ECONOMIC_CAUSE_PROOF_UNRESOLVED'); END IF;
 reasons:=reasons||ops.ad_action_blockers(candidate.candidate_basis,candidate.cause_code,kase.blocker_codes);
 IF NOT EXISTS(SELECT 1 FROM core.ad_bid_target_policy p WHERE p.id=candidate.target_policy_id
   AND p.organization_id=candidate.organization_id AND p.policy_version=candidate.target_policy_version
   AND p.status='ACTIVE' AND p.effective_from<=p_at AND (p.effective_to IS NULL OR p.effective_to>p_at)
   AND p.direction=candidate.direction AND p.candidate_basis=candidate.candidate_basis
   AND p.cause_bound_step_enabled AND candidate.cause_code=ANY(p.cause_bound_causes))
 THEN reasons:=array_append(reasons,'ECONOMIC_CAUSE_TARGET_POLICY_NOT_ACCEPTED'); END IF;
 required:=ops.ad_required_action_evidence_kinds(candidate.candidate_basis,candidate.cause_code);
 IF (SELECT count(*) FROM mart.ad_case_purpose_evidence e
   JOIN core.ad_freshness_profile f ON f.id=e.freshness_profile_id
   WHERE e.case_id=kase.id AND e.calculation_id=kase.calculation_id
     AND e.evidence_kind=ANY(required) AND e.decision_purpose='PROTECTION_BID_WRITE'
     AND e.eligible AND e.expires_at>p_at
     AND f.organization_id=candidate.organization_id AND f.evidence_kind=e.evidence_kind
     AND f.decision_purpose=e.decision_purpose
     AND f.status='ACTIVE' AND f.effective_from<=p_at AND (f.effective_to IS NULL OR f.effective_to>p_at))
   <>cardinality(required)
 THEN reasons:=array_append(reasons,'ECONOMIC_CAUSE_PURPOSE_EVIDENCE_UNRESOLVED'); END IF;
 RETURN reasons;
END $$;

CREATE FUNCTION ops.ad_entity_version_digest(p_ad_native_object_id uuid, p_candidate_id uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'core', 'pg_temp'
    AS $$
    SELECT encode(sha256(convert_to(concat_ws(chr(31),
        obj.id::text,
        obj.lineage_key,
        obj.lineage_generation::text,
        obj.control_granularity_state,
        obj.semantic_profile_id::text,
        obj.status,
        coalesce(conf.id::text, ''),
        coalesce(conf.observed_bid_amount::text, ''),
        coalesce(conf.bid_currency_code, ''),
        coalesce(conf.bid_unit_code, ''),
        coalesce(conf.observed_status, ''),
        coalesce(cand.id::text, ''),
        coalesce(cand.affected_set_digest, ''),
        coalesce(cand.direction, ''),
        coalesce(cand.candidate_basis, ''),
        coalesce(cand.current_bid_amount::text, ''),
        coalesce(cand.provider_normalized_amount::text, ''),
        coalesce(cand.target_policy_id::text, ''),
        coalesce(cand.target_policy_version::text, '')), 'UTF8')), 'hex')
      FROM core.ad_native_object obj
      LEFT JOIN LATERAL (
            SELECT c.* FROM core.ad_object_configuration_observation c
             WHERE c.ad_native_object_id = obj.id
               AND c.organization_id = obj.organization_id
               AND NOT EXISTS (SELECT 1 FROM core.ad_object_configuration_observation later
                                WHERE later.supersedes_observation_id = c.id)
             ORDER BY c.observed_at DESC, c.id DESC LIMIT 1) conf ON true
      LEFT JOIN ops.ad_bid_candidate cand
        ON cand.id = p_candidate_id AND cand.organization_id = obj.organization_id
     WHERE obj.id = p_ad_native_object_id
$$;

CREATE FUNCTION ops.ad_exception_authority_only_tightens() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$ BEGIN
 IF NEW.authority_valid_until>OLD.authority_valid_until THEN
  RAISE EXCEPTION 'risk acceptance authority cannot be extended' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION ops.ad_exception_risk_snapshot(p_case uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'core', 'mart', 'ops', 'ledger', 'platform', 'pg_temp'
    AS $$
 SELECT jsonb_build_object(
  'platform',c.platform_code,'account',s.marketplace_account_id,'store',c.store_id,
  'object',c.ad_native_object_id,'nativeObjectKey',obj.native_object_key,
  'semanticProfile',c.semantic_profile_id,'affectedSet',a.affected_set_digest,
  'productVariantIds',a.product_variant_ids,'calculation',c.calculation_id,
  'lane',c.lane,'cause',c.cause_code,'evidenceState',c.evidence_state,
  'confidenceState',c.confidence_state,'blockers',c.blocker_codes,
  'officialSpend',jsonb_build_object('state',c.official_spend_state,'amount',c.official_spend_amount,'currency',c.profit_currency_code),
  'absoluteProfit',jsonb_build_object('state',c.contribution_profit_state,'amount',c.contribution_profit_amount,'currency',c.profit_currency_code),
  'profitPerAdRub',jsonb_build_object('state',c.profit_per_ad_rub_state,'value',c.profit_per_ad_rub_value),
  'conversion',jsonb_build_object('state',c.ad_linked_conversion_state,'value',c.ad_linked_conversion_value,'stage',c.ad_linked_conversion_stage),
  'diagnostics',coalesce((SELECT jsonb_agg(jsonb_build_object('productVariantId',d.product_variant_id,
      'listingVariantId',d.platform_listing_variant_id,'basis',d.basis,'confidence',d.confidence_state,
      'spend',d.spend_amount,'profit',d.contribution_profit_amount,'currency',d.currency_code,
      'sellability',d.sellability_state,'availability',d.availability_state,'criticalSalesUnit',d.is_critical_sales_unit)
      ORDER BY d.product_variant_id,d.platform_listing_variant_id)
      FROM mart.ad_case_variant_diagnostic d WHERE d.case_id=c.id AND d.calculation_id=c.calculation_id),'[]'::jsonb),
  'salesEvidence',coalesce((SELECT jsonb_agg(jsonb_build_object('id',f.id,'stage',f.sale_stage,
      'sales',f.net_sales_amount,'currency',f.currency_code,'occurredAt',f.occurred_at) ORDER BY f.id)
      FROM ledger.ad_linked_sale_event f WHERE f.id IN(SELECT e.ad_linked_sale_event_id
          FROM mart.ad_case_evidence e WHERE e.case_id=c.id AND e.calculation_id=c.calculation_id)),'[]'::jsonb),
  'purposeEvidence',coalesce((SELECT jsonb_agg(jsonb_build_object('purpose',e.decision_purpose,
      'kind',e.evidence_kind,'profile',e.freshness_profile_id,'eligible',e.eligible,
      'expiresAt',e.expires_at,'reasons',e.reason_codes) ORDER BY e.decision_purpose,e.evidence_kind)
      FROM mart.ad_case_purpose_evidence e WHERE e.case_id=c.id AND e.calculation_id=c.calculation_id),'[]'::jsonb),
  'containment',ops.ad_active_containment(c.organization_id,c.ad_native_object_id,c.store_id,c.platform_code,'AD_BID_CHANGE',a.affected_set_digest),
  'policyDigest',c.policy_version_digest,'bundleId',c.bundle_id)
 FROM mart.ad_case c JOIN core.store s ON s.id=c.store_id JOIN core.ad_native_object obj ON obj.id=c.ad_native_object_id
 JOIN core.ad_affected_set a ON a.id=c.affected_set_id WHERE c.id=p_case
$$;

CREATE FUNCTION ops.ad_exposure_failures(p_org uuid, p_store uuid, p_direction text) RETURNS text[]
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
 SELECT ARRAY(SELECT jsonb_array_elements_text(ops.ad_exposure_snapshot(p_org,p_store,p_direction)->'reasons'))
$$;

CREATE FUNCTION ops.ad_exposure_snapshot(p_org uuid, p_store uuid, p_direction text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'core', 'ledger', 'pg_temp'
    AS $_$
DECLARE e core.ad_exposure_envelope%ROWTYPE; reasons text[]:='{}'; all_reasons text[]:='{}'; found_envelope boolean:=false;
 envelopes jsonb:='[]';
 active_count integer; unresolved integer; cumulative numeric; associated numeric; associated_boundary_reports integer;
 sales_total numeric; affected_sales numeric; sales_known boolean; variants uuid[]; stores uuid[]; objects uuid[];
BEGIN
 FOR e IN SELECT env.* FROM core.ad_exposure_envelope env
 JOIN core.store subject_store ON subject_store.id=p_store
 JOIN core.marketplace_account acc ON acc.id=subject_store.marketplace_account_id
 WHERE env.organization_id=p_org AND env.status='ACTIVE'
 AND env.effective_from<=statement_timestamp() AND (env.effective_to IS NULL OR env.effective_to>statement_timestamp())
 AND (env.scope_kind='ORGANIZATION' OR env.scope_kind='PLATFORM' AND env.platform_code=acc.platform_code
      OR env.scope_kind='STORE' AND env.store_ref_id=p_store)
 LOOP
  found_envelope:=true; reasons:='{}'; associated:=NULL; associated_boundary_reports:=NULL; sales_total:=NULL; affected_sales:=NULL;
  SELECT array_agg(st.id) INTO stores FROM core.store st
   JOIN core.marketplace_account account ON account.id=st.marketplace_account_id
   WHERE st.organization_id=p_org AND (e.scope_kind='ORGANIZATION'
    OR e.scope_kind='PLATFORM' AND account.platform_code=e.platform_code
    OR e.scope_kind='STORE' AND st.id=e.store_ref_id);
  SELECT count(*),array_agg(DISTINCT r.ad_native_object_id) INTO active_count,objects
   FROM ops.ad_action_reservation r WHERE r.organization_id=p_org AND r.state='ACTIVE' AND r.store_id=ANY(stores);
  SELECT array_agg(DISTINCT v) INTO variants FROM ops.ad_action_reservation r
   CROSS JOIN LATERAL unnest(r.product_variant_ids) v
   WHERE r.organization_id=p_org AND r.state='ACTIVE' AND r.store_id=ANY(stores);
  IF active_count>e.max_active_interventions THEN reasons:=array_append(reasons,'ACTIVE_INTERVENTIONS'); END IF;
  IF p_direction<>'EXACT_PRIOR_BID_COMPENSATION' AND active_count>e.max_active_interventions-e.reserved_recovery_headroom_count
   THEN reasons:=array_append(reasons,'RECOVERY_HEADROOM'); END IF;
  SELECT count(*) INTO unresolved FROM ops.ad_action_reservation r
   WHERE r.organization_id=p_org AND r.store_id=ANY(stores) AND r.state='ACTIVE'
   AND (r.unknown_or_mismatch_open OR EXISTS(SELECT 1 FROM ops.ad_bid_command c
     WHERE c.reservation_id=r.id AND c.state IN ('EXECUTING','PLATFORM_PENDING','READBACK_PENDING',
       'UNKNOWN_REQUIRES_READBACK','READBACK_MISMATCH','LATER_CHANGE_OR_MISMATCH_INVESTIGATION','MANUAL_RESOLUTION','COMPENSATION_PENDING'))
    OR EXISTS(SELECT 1 FROM ops.ad_manual_execution_packet packet WHERE packet.id=r.intervention_reference_id
     AND r.intervention_kind='CONFIRMED_MANUAL_PACKET' AND (packet.state IN('MANUAL_PACKET_ISSUED',
      'MANUAL_EXECUTION_IN_PROGRESS','ACTION_REPORTED_CONFIGURATION_UNVERIFIED','MANUAL_EXECUTION_UNCERTAIN')
      OR NOT ops.ad_manual_observation_is_qualified(packet.current_proof_id))));
  IF unresolved>e.max_unresolved_transmitted_writes THEN reasons:=array_append(reasons,'UNRESOLVED_TRANSMITTED_WRITES'); END IF;
  IF EXISTS(SELECT 1 FROM ops.ad_action_reservation r JOIN ops.ad_bid_candidate c ON c.id=r.intervention_reference_id
    WHERE r.organization_id=p_org AND r.store_id=ANY(stores)
    AND r.reserved_at>statement_timestamp()-make_interval(hours=>e.cumulative_window_hours)
    AND (c.currency_code<>e.currency_code OR c.bid_unit_code NOT IN ('CURRENCY_MAJOR','CURRENCY_MINOR'))) THEN
   reasons:=array_append(reasons,'CUMULATIVE_BID_CHANGE_UNRESOLVED'); END IF;
  -- Count each intervention once, whether or not its command has been created.
  SELECT coalesce(sum(abs(c.provider_normalized_amount-c.current_bid_amount) / CASE c.bid_unit_code WHEN 'CURRENCY_MINOR' THEN 100 ELSE 1 END),0) INTO cumulative
   FROM ops.ad_action_reservation r JOIN ops.ad_bid_candidate c ON c.id=r.intervention_reference_id
   WHERE r.organization_id=p_org AND r.store_id=ANY(stores)
   AND r.reserved_at>statement_timestamp()-make_interval(hours=>e.cumulative_window_hours);
  SELECT cumulative+coalesce(sum(abs((p.intended_state->>'targetBid')::numeric-c.observed_bid_amount) / CASE c.bid_unit_code WHEN 'CURRENCY_MINOR' THEN 100 ELSE 1 END),0)
   INTO cumulative FROM ops.ad_action_reservation r
   JOIN ops.ad_manual_execution_packet p ON p.id=r.intervention_reference_id
   JOIN core.ad_object_configuration_observation c ON c.id=p.observed_configuration_id
   WHERE r.organization_id=p_org AND r.store_id=ANY(stores)
   AND r.reserved_at>statement_timestamp()-make_interval(hours=>e.cumulative_window_hours)
   AND p.intended_state->>'targetBid' ~ '^[0-9]+(\.[0-9]+)?$';
  -- Exact restoration is another bid change inside the same reservation.
  -- Count it once across approval and dispatch, including a completed restore.
  SELECT cumulative+coalesce(sum(abs(c.target_bid_amount-c.prior_bid_amount)
    /CASE c.bid_unit_code WHEN 'CURRENCY_MINOR' THEN 100 ELSE 1 END),0) INTO cumulative
   FROM ops.ad_bid_command c WHERE c.organization_id=p_org AND c.store_id=ANY(stores)
   AND (EXISTS(SELECT 1 FROM ops.ad_compensation_authorization approved WHERE approved.command_id=c.id
     AND approved.approved_at>statement_timestamp()-make_interval(hours=>e.cumulative_window_hours))
    OR EXISTS(SELECT 1 FROM ops.ad_bid_command_attempt restore WHERE restore.command_id=c.id AND restore.purpose='RESTORE'
      AND restore.started_at>statement_timestamp()-make_interval(hours=>e.cumulative_window_hours)));
  IF cumulative>e.max_cumulative_bid_change_amount THEN reasons:=array_append(reasons,'CUMULATIVE_BID_CHANGE'); END IF;
  IF e.retained_window_days IS NULL OR e.measurement_window_hours IS NULL THEN
   reasons:=array_append(reasons,'EXPOSURE_MEASUREMENT_POLICY_ABSENT'); END IF;
  -- Official spend uses complete intersecting accepted reports once per native
  -- row. A report crossing the left measurement boundary contributes its whole
  -- amount conservatively: no prorating or subtraction invents a smaller spend.
  -- A period reaching into the future cannot prove a current official amount.
  IF EXISTS(SELECT 1 FROM ledger.ad_object_fact f WHERE f.ad_native_object_id=ANY(objects)
     AND f.recorded_at<=statement_timestamp() AND f.source_time<=statement_timestamp()
     AND f.period_start<statement_timestamp()
     AND f.period_end>statement_timestamp()-make_interval(hours=>e.measurement_window_hours)
     AND NOT EXISTS(SELECT 1 FROM ledger.ad_object_fact n WHERE n.supersedes_fact_id=f.id AND n.recorded_at<=statement_timestamp())
     AND (f.spend_amount IS NULL OR f.currency_code<>e.currency_code OR NOT f.report_window_complete OR f.correction_window_open
      OR f.period_end>statement_timestamp()))
   OR EXISTS(SELECT 1 FROM ledger.ad_object_fact first JOIN ledger.ad_object_fact second
     ON second.ad_native_object_id=first.ad_native_object_id AND second.id>first.id
     AND tstzrange(first.period_start,first.period_end,'[)') && tstzrange(second.period_start,second.period_end,'[)')
     WHERE first.ad_native_object_id=ANY(objects)
     AND first.recorded_at<=statement_timestamp() AND first.source_time<=statement_timestamp()
     AND second.recorded_at<=statement_timestamp() AND second.source_time<=statement_timestamp()
     AND first.period_start<statement_timestamp() AND second.period_start<statement_timestamp()
     AND first.period_end>statement_timestamp()-make_interval(hours=>e.measurement_window_hours)
     AND second.period_end>statement_timestamp()-make_interval(hours=>e.measurement_window_hours)
     AND NOT EXISTS(SELECT 1 FROM ledger.ad_object_fact n WHERE n.supersedes_fact_id IN(first.id,second.id) AND n.recorded_at<=statement_timestamp()))
   OR EXISTS(SELECT 1 FROM unnest(objects) object_id WHERE NOT EXISTS(
    SELECT 1 FROM ledger.ad_object_fact f WHERE f.ad_native_object_id=object_id
    AND f.recorded_at<=statement_timestamp() AND f.source_time<=statement_timestamp()
    AND f.period_start<statement_timestamp()
     AND f.period_end>statement_timestamp()-make_interval(hours=>e.measurement_window_hours))) THEN
    reasons:=array_append(reasons,'ASSOCIATED_SPEND_UNRESOLVED');
  ELSE
   SELECT coalesce(sum(f.spend_amount),0),count(*) FILTER(WHERE
      f.period_start<statement_timestamp()-make_interval(hours=>e.measurement_window_hours))
     INTO associated,associated_boundary_reports FROM ledger.ad_object_fact f
    WHERE f.organization_id=p_org AND f.ad_native_object_id=ANY(objects)
    AND f.recorded_at<=statement_timestamp() AND f.source_time<=statement_timestamp()
    AND f.period_start<statement_timestamp()
     AND f.period_end>statement_timestamp()-make_interval(hours=>e.measurement_window_hours)
    AND NOT EXISTS(SELECT 1 FROM ledger.ad_object_fact n WHERE n.supersedes_fact_id=f.id AND n.recorded_at<=statement_timestamp());
   IF associated>e.max_associated_spend_amount THEN reasons:=array_append(reasons,'ASSOCIATED_SPEND'); END IF;
  END IF;
  -- The envelope's company denominator and affected numerator use the same
  -- accepted Retained cohort and one exact measurement window. Coverage is
  -- required for every known company listing, including units without facts.
  WITH scope_units AS (
   SELECT variant.id listing_id,listing.store_id,listing.platform_code
   FROM core.platform_listing_variant variant
   JOIN core.platform_listing listing ON listing.id=variant.platform_listing_id
   WHERE variant.organization_id=p_org AND listing.store_id=ANY(stores)
    AND variant.first_seen_at<=statement_timestamp()
    AND (variant.status='OBSERVED' OR EXISTS(SELECT 1 FROM ledger.sales_fact fact
     WHERE fact.platform_listing_variant_id=variant.id AND fact.sale_stage='RETAINED'
      AND fact.occurred_at>=statement_timestamp()-make_interval(hours=>e.measurement_window_hours)
      AND fact.occurred_at<statement_timestamp()))
  ), current_facts AS (
   SELECT fact.* FROM ledger.sales_fact fact
   JOIN core.fact_provenance accepted ON accepted.id=fact.provenance_id
   WHERE fact.organization_id=p_org AND fact.store_id=ANY(stores)
    AND fact.sale_stage='RETAINED' AND fact.retention_window_days=e.retained_window_days
    AND fact.occurred_at>=statement_timestamp()-make_interval(hours=>e.measurement_window_hours)
    AND fact.occurred_at<statement_timestamp() AND accepted.ingestion_time<=statement_timestamp()
    AND (accepted.source_time IS NULL OR accepted.source_time<=statement_timestamp())
    AND NOT EXISTS(SELECT 1 FROM ledger.sales_fact successor
     JOIN core.fact_provenance accepted_successor ON accepted_successor.id=successor.provenance_id
     WHERE successor.supersedes_fact_id=fact.id AND accepted_successor.ingestion_time<=statement_timestamp()
      AND (accepted_successor.source_time IS NULL OR accepted_successor.source_time<=statement_timestamp()))
  ), per_unit AS (
   SELECT unit.listing_id,profile.id profile_id,coverage.id coverage_id,
    profile.source_max_age_minutes,profile.accepted_fact_max_age_minutes,
    coverage.completed_coverage,coverage.retained_coverage,coverage.return_coverage,coverage.qc_coverage,
    coverage.completed_source_updated_at,coverage.retained_source_updated_at,
    coverage.return_source_updated_at,coverage.qc_source_updated_at,coverage.accepted_at,
    fact.count,fact.amount,fact.affected_amount,fact.valid,
    profile.provider_incident_blocks AND EXISTS(SELECT 1 FROM platform.ad_provider_incident incident
      WHERE incident.organization_id=p_org AND incident.platform_code=unit.platform_code
       AND (incident.store_id IS NULL OR incident.store_id=unit.store_id)
       AND incident.incident_open AND incident.observed_at<=statement_timestamp()
       AND (incident.valid_until IS NULL OR incident.valid_until>statement_timestamp())) incident_blocks
   FROM scope_units unit
   LEFT JOIN LATERAL (
    SELECT eligible.* FROM core.ad_freshness_profile eligible
    WHERE eligible.organization_id=p_org AND eligible.evidence_kind='COMPANY_RETAINED_SALE'
     AND eligible.decision_purpose='FINAL_RETAINED_SALES_OUTCOME' AND eligible.status='ACTIVE'
     AND eligible.effective_from<=statement_timestamp()
     AND (eligible.effective_to IS NULL OR eligible.effective_to>statement_timestamp())
     AND (eligible.scope_kind='ORGANIZATION' OR eligible.scope_kind='PLATFORM' AND eligible.platform_code=unit.platform_code
       OR eligible.scope_kind='STORE' AND eligible.store_ref_id=unit.store_id)
     AND NOT EXISTS(SELECT 1 FROM core.ad_freshness_profile other WHERE other.id<>eligible.id
      AND other.organization_id=p_org AND other.evidence_kind=eligible.evidence_kind AND other.decision_purpose=eligible.decision_purpose
      AND other.status='ACTIVE' AND other.effective_from<=statement_timestamp()
      AND (other.effective_to IS NULL OR other.effective_to>statement_timestamp())
      AND (other.scope_kind='ORGANIZATION' OR other.scope_kind='PLATFORM' AND other.platform_code=unit.platform_code
        OR other.scope_kind='STORE' AND other.store_ref_id=unit.store_id)
      AND CASE other.scope_kind WHEN 'STORE' THEN 0 WHEN 'PLATFORM' THEN 1 ELSE 2 END
       <=CASE eligible.scope_kind WHEN 'STORE' THEN 0 WHEN 'PLATFORM' THEN 1 ELSE 2 END)
   ) profile ON true
   LEFT JOIN LATERAL (
    SELECT report.* FROM ledger.return_quality_evidence_snapshot report
    WHERE report.organization_id=p_org AND report.platform_listing_variant_id=unit.listing_id
     AND report.report_window_start<=statement_timestamp()-make_interval(hours=>e.measurement_window_hours)
     AND report.report_window_end>=statement_timestamp() AND report.accepted_at<=statement_timestamp()
     AND NOT EXISTS(SELECT 1 FROM ledger.return_quality_evidence_snapshot successor
      WHERE successor.supersedes_snapshot_id=report.id AND successor.accepted_at<=statement_timestamp())
    ORDER BY report.accepted_at DESC,report.id DESC LIMIT 1
   ) coverage ON true
   LEFT JOIN LATERAL (
    SELECT count(*) count,sum(f.net_amount) amount,
     sum(f.net_amount) FILTER(WHERE EXISTS(SELECT 1 FROM core.listing_mapping mapping
      WHERE mapping.platform_listing_variant_id=f.platform_listing_variant_id AND mapping.product_variant_id=ANY(variants)
       AND mapping.status IN('ACTIVE','ENDED') AND mapping.effective_from<=f.occurred_at
       AND (mapping.effective_to IS NULL OR mapping.effective_to>f.occurred_at))) affected_amount,
     bool_and(f.net_amount IS NOT NULL AND f.net_amount>=0 AND f.currency_code=e.currency_code
      AND (SELECT count(*) FROM current_facts duplicate WHERE duplicate.platform_listing_variant_id=f.platform_listing_variant_id
       AND duplicate.native_order_key=f.native_order_key AND duplicate.native_line_key IS NOT DISTINCT FROM f.native_line_key)=1
      AND (SELECT count(*) FROM core.listing_mapping mapping WHERE mapping.platform_listing_variant_id=f.platform_listing_variant_id
       AND mapping.status IN('ACTIVE','ENDED') AND mapping.effective_from<=f.occurred_at
       AND (mapping.effective_to IS NULL OR mapping.effective_to>f.occurred_at))=1) valid
    FROM current_facts f WHERE f.platform_listing_variant_id=unit.listing_id
   ) fact ON true
  ), complete_units AS (
   SELECT *, profile_id IS NOT NULL AND coverage_id IS NOT NULL AND NOT incident_blocks
    AND completed_coverage='COMPLETE' AND retained_coverage='COMPLETE' AND qc_coverage='COMPLETE'
    AND return_coverage IN('COMPLETE_ZERO','COMPLETE_OBSERVED')
    AND accepted_at<=statement_timestamp()
    AND (accepted_fact_max_age_minutes IS NULL OR accepted_at>=statement_timestamp()-make_interval(mins=>accepted_fact_max_age_minutes))
    AND NOT EXISTS(SELECT 1 FROM unnest(ARRAY[completed_source_updated_at,retained_source_updated_at,
     return_source_updated_at,qc_source_updated_at]) updated WHERE updated IS NULL OR updated>statement_timestamp()
      OR source_max_age_minutes IS NOT NULL AND updated<statement_timestamp()-make_interval(mins=>source_max_age_minutes))
    AND (count=0 OR valid) complete
   FROM per_unit
  )
  SELECT count(*)>0 AND bool_and(complete)
    AND NOT EXISTS(SELECT 1 FROM unnest(stores) scope_store WHERE NOT EXISTS(SELECT 1 FROM scope_units unit WHERE unit.store_id=scope_store)),
   CASE WHEN count(*)>0 AND bool_and(complete) THEN sum(coalesce(amount,0)) END,
   CASE WHEN count(*)>0 AND bool_and(complete) THEN sum(coalesce(affected_amount,0)) END
  INTO sales_known,sales_total,affected_sales FROM complete_units;
  IF sales_known IS NOT TRUE THEN sales_total:=NULL; affected_sales:=NULL; END IF;
  IF sales_known IS NOT TRUE OR sales_total IS NULL OR sales_total<=0
   OR EXISTS(SELECT 1 FROM unnest(variants) member WHERE NOT EXISTS(SELECT 1 FROM core.listing_mapping mapping
     JOIN core.platform_listing_variant variant ON variant.id=mapping.platform_listing_variant_id
     JOIN core.platform_listing listing ON listing.id=variant.platform_listing_id
     WHERE mapping.product_variant_id=member AND mapping.organization_id=p_org AND listing.store_id=ANY(stores)
      AND mapping.status='ACTIVE' AND mapping.effective_from<=statement_timestamp()
      AND (mapping.effective_to IS NULL OR mapping.effective_to>statement_timestamp()))) THEN
   reasons:=array_append(reasons,'RETAINED_SALES_SHARE_UNRESOLVED');
  ELSIF affected_sales/sales_total>e.max_affected_retained_sales_share THEN
   reasons:=array_append(reasons,'AFFECTED_RETAINED_SALES_SHARE'); END IF;
  envelopes:=envelopes || jsonb_build_array(jsonb_build_object('envelopeId',e.id,'policyVersion',e.policy_version,
   'scopeKind',e.scope_kind,'platformCode',e.platform_code,'storeId',e.store_ref_id,'currencyCode',e.currency_code,
   'measurementWindowHours',e.measurement_window_hours,'retainedWindowDays',e.retained_window_days,
   'axes',jsonb_build_object(
    'activeInterventions',jsonb_build_object('usage',active_count,'limit',e.max_active_interventions,'state',CASE WHEN 'ACTIVE_INTERVENTIONS'=ANY(reasons) THEN 'EXCEEDED' ELSE 'AVAILABLE' END),
    'associatedOfficialSpend',jsonb_build_object('usage',CASE WHEN 'ASSOCIATED_SPEND_UNRESOLVED'=ANY(reasons) THEN NULL ELSE associated END,'limit',e.max_associated_spend_amount,'aggregationBasis','COMPLETE_INTERSECTING_OFFICIAL_REPORT_AMOUNTS','conservativeBoundaryReportCount',associated_boundary_reports,'unit',e.currency_code||'_MAJOR','state',CASE WHEN 'ASSOCIATED_SPEND_UNRESOLVED'=ANY(reasons) THEN 'UNKNOWN' WHEN 'ASSOCIATED_SPEND'=ANY(reasons) THEN 'EXCEEDED' ELSE 'AVAILABLE' END),
    'affectedRetainedSalesShare',jsonb_build_object('usage',CASE WHEN sales_total>0 AND NOT 'RETAINED_SALES_SHARE_UNRESOLVED'=ANY(reasons) THEN affected_sales/sales_total END,'companySales',sales_total,'affectedSales',affected_sales,'limit',e.max_affected_retained_sales_share,'state',CASE WHEN 'RETAINED_SALES_SHARE_UNRESOLVED'=ANY(reasons) THEN 'UNKNOWN' WHEN 'AFFECTED_RETAINED_SALES_SHARE'=ANY(reasons) THEN 'EXCEEDED' ELSE 'AVAILABLE' END),
    'cumulativeBidChangeMajor',jsonb_build_object('usage',CASE WHEN 'CUMULATIVE_BID_CHANGE_UNRESOLVED'=ANY(reasons) THEN NULL ELSE cumulative END,'limit',e.max_cumulative_bid_change_amount,'windowHours',e.cumulative_window_hours,'unit',e.currency_code||'_MAJOR','state',CASE WHEN 'CUMULATIVE_BID_CHANGE_UNRESOLVED'=ANY(reasons) THEN 'UNKNOWN' WHEN 'CUMULATIVE_BID_CHANGE'=ANY(reasons) THEN 'EXCEEDED' ELSE 'AVAILABLE' END),
    'unresolvedTransmittedWrites',jsonb_build_object('usage',unresolved,'limit',e.max_unresolved_transmitted_writes,'state',CASE WHEN 'UNRESOLVED_TRANSMITTED_WRITES'=ANY(reasons) THEN 'EXCEEDED' ELSE 'AVAILABLE' END),
    'reservedRecoveryHeadroom',jsonb_build_object('available',e.max_active_interventions-active_count,'reserved',e.reserved_recovery_headroom_count,'state',CASE WHEN 'RECOVERY_HEADROOM'=ANY(reasons) THEN 'EXCEEDED' ELSE 'AVAILABLE' END)),
   'reasons',to_jsonb(reasons)));
  all_reasons:=all_reasons || reasons;
 END LOOP;
 reasons:=all_reasons;
 IF NOT found_envelope THEN reasons:=array_append(reasons,'AGGREGATE_ENVELOPE_UNRESOLVED'); END IF;
 IF cardinality(reasons)>0 AND NOT 'AGGREGATE_ENVELOPE_UNRESOLVED'=ANY(reasons) THEN
  reasons:=array_append(reasons,'AGGREGATE_ENVELOPE_BLOCKED'); END IF;
 RETURN jsonb_build_object('envelopes',envelopes,'reasons',to_jsonb(ARRAY(SELECT DISTINCT reason FROM unnest(reasons) reason ORDER BY reason)));
END $_$;

CREATE FUNCTION ops.ad_gate_scope_is_monotonic() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $_$
DECLARE prior ops.ad_gate_authority%ROWTYPE; object_id uuid; value jsonb;
 prior_exposure core.ad_exposure_envelope%ROWTYPE; current_exposure core.ad_exposure_envelope%ROWTYPE;
BEGIN
 IF NEW.status<>'ACTIVE' THEN RETURN NEW; END IF;
 FOREACH object_id IN ARRAY NEW.native_object_ids LOOP
  value:=NEW.exact_object_values->object_id::text;
  IF value IS NULL OR jsonb_typeof(value)<>'object'
  OR coalesce(value->>'currentBid','')!~'^[0-9]+(\.[0-9]+)?$'
  OR coalesce(value->>'targetBid','')!~'^[0-9]+(\.[0-9]+)?$'
  OR value->>'currencyCode' IS DISTINCT FROM NEW.currency_code
  OR coalesce(value->>'bidUnitCode','') NOT IN ('CURRENCY_MAJOR','CURRENCY_MINOR') THEN
   RAISE EXCEPTION 'exact native object current/target/unit/currency scope required' USING ERRCODE='MO092'; END IF;
 END LOOP;
 IF NEW.gate_kind='GATE_E' THEN
  SELECT * INTO prior FROM ops.ad_gate_authority WHERE id=NEW.predecessor_gate_ev_id;
  IF prior.id IS NULL OR prior.gate_kind<>'GATE_EV' OR prior.status NOT IN ('ACTIVE','EXPIRED')
  OR prior.organization_id<>NEW.organization_id OR prior.platform_code<>NEW.platform_code
  OR prior.marketplace_account_id<>NEW.marketplace_account_id OR prior.store_id<>NEW.store_id
  OR prior.direction<>NEW.direction OR prior.candidate_basis<>NEW.candidate_basis
  OR prior.currency_code<>NEW.currency_code OR NEW.max_bid_change_amount>prior.max_bid_change_amount
  OR NOT NEW.native_object_ids <@ prior.demonstrated_object_ids THEN
   RAISE EXCEPTION 'Gate E cannot exceed demonstrated Gate EV scope' USING ERRCODE='MO092'; END IF;
  -- This authority model represents demonstrated exact native value pairs, not
  -- an inferred numerical range. A different pair requires new accepted evidence.
  FOREACH object_id IN ARRAY NEW.native_object_ids LOOP
   IF NEW.exact_object_values->object_id::text IS DISTINCT FROM prior.exact_object_values->object_id::text THEN
    RAISE EXCEPTION 'Gate E native values must be demonstrated by its exact predecessor' USING ERRCODE='MO092'; END IF;
  END LOOP;
  SELECT e.* INTO prior_exposure FROM core.ad_exposure_envelope e
   JOIN ops.ad_decision_policy_bundle b ON b.exposure_envelope_id=e.id WHERE b.id=prior.bundle_id;
  SELECT e.* INTO current_exposure FROM core.ad_exposure_envelope e
   JOIN ops.ad_decision_policy_bundle b ON b.exposure_envelope_id=e.id WHERE b.id=NEW.bundle_id;
  IF prior_exposure.id IS NULL OR current_exposure.id IS NULL
   OR current_exposure.status<>'ACTIVE'
   OR current_exposure.organization_id<>NEW.organization_id OR prior_exposure.organization_id<>NEW.organization_id
   OR current_exposure.currency_code<>prior_exposure.currency_code
   OR current_exposure.scope_kind<>prior_exposure.scope_kind
   OR current_exposure.platform_code IS DISTINCT FROM prior_exposure.platform_code
   OR current_exposure.store_ref_id IS DISTINCT FROM prior_exposure.store_ref_id
   OR current_exposure.retained_window_days IS DISTINCT FROM prior_exposure.retained_window_days
   OR current_exposure.measurement_window_hours IS DISTINCT FROM prior_exposure.measurement_window_hours
   OR current_exposure.cumulative_window_hours IS DISTINCT FROM prior_exposure.cumulative_window_hours
   OR current_exposure.max_active_interventions>prior_exposure.max_active_interventions
   OR current_exposure.max_affected_retained_sales_share>prior_exposure.max_affected_retained_sales_share
   OR current_exposure.max_associated_spend_amount>prior_exposure.max_associated_spend_amount
   OR current_exposure.max_cumulative_bid_change_amount>prior_exposure.max_cumulative_bid_change_amount
   OR current_exposure.max_unresolved_transmitted_writes>prior_exposure.max_unresolved_transmitted_writes
   OR current_exposure.reserved_recovery_headroom_count<prior_exposure.reserved_recovery_headroom_count THEN
    RAISE EXCEPTION 'Gate E cannot broaden the demonstrated aggregate exposure authority' USING ERRCODE='MO092'; END IF;
  -- Gate EV's historical evidence window is not the new Pilot window. The new
  -- Owner Gate has its own bounded window; actual sealing and admission still
  -- intersect it with every current Profile, Bundle, Envelope and actor expiry.
  -- Likewise EV's one-time command count is not an ongoing aggregate limit:
  -- the exact current Gate count and all six Envelope axes remain independent.
 END IF;
 RETURN NEW;
END $_$;

CREATE FUNCTION ops.ad_json_pointer(p_document jsonb, p_pointer text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
    SELECT p_document #>> array_agg(replace(replace(component, '~1', '/'), '~0', '~') ORDER BY ordinal)
      FROM unnest(string_to_array(substring(p_pointer FROM 2), '/'))
           WITH ORDINALITY part(component, ordinal)
$$;

CREATE FUNCTION ops.ad_json_value(p_document jsonb, p_pointer text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
    SELECT p_document #> array_agg(replace(replace(component, '~1', '/'), '~0', '~') ORDER BY ordinal)
      FROM unnest(string_to_array(substring(p_pointer FROM 2), '/'))
           WITH ORDINALITY part(component, ordinal)
$$;

CREATE FUNCTION ops.ad_listing_isolation_context(p_listing uuid, p_at timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'core', 'ops', 'pg_temp'
    AS $$
 WITH price AS (
  SELECT p.*,v.ingestion_time,v.source_time FROM core.listing_price_observation p
  JOIN core.fact_provenance v ON v.id=p.provenance_id
  WHERE p.platform_listing_variant_id=p_listing AND p.observed_at<p_at
   AND coalesce(v.ingestion_time,v.source_time)<=p_at AND (v.source_time IS NULL OR v.source_time<=p_at)
   AND NOT EXISTS(SELECT 1 FROM core.listing_price_observation n JOIN core.fact_provenance nv ON nv.id=n.provenance_id
     WHERE n.supersedes_fact_id=p.id AND n.observed_at<p_at
      AND coalesce(nv.ingestion_time,nv.source_time)<=p_at AND (nv.source_time IS NULL OR nv.source_time<=p_at))
  ORDER BY p.observed_at DESC,p.id DESC LIMIT 1
 ), health AS (
  SELECT h.* FROM core.listing_health_observation h JOIN core.fact_provenance v ON v.id=h.provenance_id
  WHERE h.platform_listing_variant_id=p_listing AND h.observed_at<p_at
   AND coalesce(v.ingestion_time,v.source_time)<=p_at AND (v.source_time IS NULL OR v.source_time<=p_at)
   AND NOT EXISTS(SELECT 1 FROM core.listing_health_observation n JOIN core.fact_provenance nv ON nv.id=n.provenance_id
     WHERE n.supersedes_fact_id=h.id AND n.observed_at<p_at
      AND coalesce(nv.ingestion_time,nv.source_time)<=p_at AND (nv.source_time IS NULL OR nv.source_time<=p_at))
  ORDER BY h.observed_at DESC,h.id DESC LIMIT 1
 ), stock AS (
  SELECT DISTINCT ON(s.fulfillment_mode_code) s.* FROM core.listing_stock_observation s
  JOIN core.fact_provenance v ON v.id=s.provenance_id
  WHERE s.platform_listing_variant_id=p_listing AND s.observed_at<p_at
   AND coalesce(v.ingestion_time,v.source_time)<=p_at AND (v.source_time IS NULL OR v.source_time<=p_at)
   AND NOT EXISTS(SELECT 1 FROM core.listing_stock_observation n JOIN core.fact_provenance nv ON nv.id=n.provenance_id
     WHERE n.supersedes_fact_id=s.id AND n.observed_at<p_at
      AND coalesce(nv.ingestion_time,nv.source_time)<=p_at AND (nv.source_time IS NULL OR nv.source_time<=p_at))
  ORDER BY s.fulfillment_mode_code,s.observed_at DESC,s.id DESC
 )
 SELECT jsonb_build_object(
  'listingVariantId',p_listing,'price',(SELECT coalesce(discount_price,selling_price,list_price) FROM price),
  'currency',(SELECT currency_code FROM price),'promotion',(SELECT promotion_active FROM price),
  'sellable',(SELECT sellable FROM health),'nativeStatus',(SELECT native_status FROM health),
  'contentCompleteness',(SELECT content_completeness FROM health),
  'availability',(SELECT CASE WHEN count(*)=0 OR bool_or(available_quantity IS NULL) THEN NULL
                     WHEN sum(available_quantity)>0 THEN 'POSITIVE' ELSE 'ZERO' END FROM stock),
  'evidence',jsonb_build_object('price',(SELECT id FROM price),'health',(SELECT id FROM health),
                     'stock',(SELECT coalesce(jsonb_agg(id ORDER BY id),'[]'::jsonb) FROM stock)))
$$;

CREATE FUNCTION ops.ad_manual_actor_scoped(p_actor uuid, p_org uuid, p_store uuid, p_set uuid, p_role text, p_action text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'core', 'iam', 'pg_temp'
    AS $$
 SELECT EXISTS(SELECT 1 FROM iam.user_account u WHERE u.id=p_actor AND u.organization_id=p_org AND u.status='ACTIVE')
 AND ops.ad_actor_has_role_scope(p_actor,p_org,p_store,p_role,p_action)
 AND (p_set IS NULL OR NOT EXISTS(
   SELECT 1 FROM core.ad_affected_set a CROSS JOIN LATERAL unnest(a.product_variant_ids) member
   WHERE a.id=p_set AND NOT EXISTS(SELECT 1 FROM iam.user_scope_grant g
     WHERE g.user_id=p_actor AND g.organization_id=p_org AND g.action_code=p_action AND g.status='ACTIVE'
     AND g.effective_from<=statement_timestamp() AND (g.effective_to IS NULL OR g.effective_to>statement_timestamp())
     AND (g.organization_ref_id=p_org OR g.product_variant_ref_id=member))))
$$;

CREATE FUNCTION ops.ad_manual_has_later_unresolved(p_packet uuid, p_observed timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'core', 'pg_temp'
    AS $$
 SELECT EXISTS(SELECT 1 FROM ops.ad_manual_execution_packet packet
 WHERE packet.id=p_packet AND (
   EXISTS(SELECT 1 FROM core.ad_object_configuration_observation c
    WHERE c.organization_id=packet.organization_id AND c.ad_native_object_id=packet.ad_native_object_id
     AND c.observed_at>=p_observed AND (c.semantic_profile_id<>packet.semantic_profile_id
      OR CASE packet.action_kind WHEN 'AD_BID_CHANGE' THEN c.observed_bid_amount::text
        WHEN 'AD_BUDGET_CHANGE' THEN c.observed_budget_amount::text ELSE c.native_status_raw END IS NULL
      OR CASE WHEN packet.action_kind IN ('AD_BID_CHANGE','AD_BUDGET_CHANGE')
        THEN CASE packet.action_kind WHEN 'AD_BID_CHANGE' THEN c.observed_bid_amount ELSE c.observed_budget_amount END
          <>(packet.intended_state->>CASE packet.action_kind WHEN 'AD_BID_CHANGE' THEN 'targetBid' ELSE 'targetBudget' END)::numeric
        ELSE c.native_status_raw<>packet.intended_state->>'targetStatus' END))
   OR EXISTS(SELECT 1 FROM ops.ad_manual_configuration_verification v WHERE v.packet_id=packet.id
     AND v.evidence_grade<>'EXECUTOR_SELF_REPORT' AND v.observed_at>=p_observed
     AND (v.conflict_state<>'NONE' OR NOT ops.ad_manual_observation_is_qualified(v.id))
     AND NOT (v.evidence_grade='UNVERIFIED_MANUAL_EVIDENCE' AND EXISTS(
       SELECT 1 FROM ops.ad_manual_configuration_verification current
       WHERE current.id=packet.current_proof_id AND ops.ad_manual_observation_is_qualified(current.id)
        AND current.observed_at>=v.observed_at)))))
$$;

CREATE FUNCTION ops.ad_manual_observation_is_qualified(p_observation uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'core', 'pg_temp'
    AS $$
 SELECT coalesce((SELECT v.proves_configuration AND v.conflict_state='NONE'
   AND v.observed_at>=packet.execution_started_at AND v.recorded_at>=v.observed_at
   AND (v.evidence_grade IN ('OFFICIAL_API_READBACK','OFFICIAL_CONFIGURATION_EXPORT')
       AND v.configuration_observation_id IS NOT NULL
     OR v.evidence_grade='INDEPENDENT_MANUAL_VERIFICATION'
       AND v.verifier_user_id IS NOT NULL AND v.verifier_user_id<>v.executor_user_id
       AND v.independent_observation->>'evidenceSource'='DIRECT_OFFICIAL_CONSOLE'
       AND v.independent_observation->>'completeness'='COMPLETE'
       AND v.independent_observation->'directObservationAttested'='true'::jsonb
       AND v.independent_observation->>'observedAt'=to_char(v.observed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
       AND v.independent_observation->>'observedValue'=v.observed_value
       AND v.independent_observation->>'exactNativeObjectId'=packet.ad_native_object_id::text
       AND v.independent_observation->>'semanticProfileId'=packet.semantic_profile_id::text
       AND v.independent_observation->>'exactFieldPath'=v.observed_field_path
       AND v.observed_field_path=CASE packet.action_kind WHEN 'AD_BID_CHANGE' THEN 'targetBid'
         WHEN 'AD_BUDGET_CHANGE' THEN 'targetBudget' ELSE 'targetStatus' END
       AND v.independent_observation->>'evidenceReference'=v.evidence_reference
       AND length(btrim(v.evidence_reference)) BETWEEN 1 AND 512
       AND policy.organization_id=packet.organization_id AND policy.store_id=packet.store_id
       AND policy.semantic_profile_id=packet.semantic_profile_id AND policy.action_kind=packet.action_kind
       AND policy.verification_mode='INDEPENDENT_OR_OFFICIAL'
       AND packet.verification_plan->>'policyId'=policy.id::text
       AND packet.verification_plan->>'policyVersion'=policy.policy_version::text
       AND packet.authority_snapshot->'policy'=to_jsonb(policy)
       AND policy.approved_at<=v.observed_at AND policy.effective_from<=v.observed_at
       AND v.recorded_at<policy.effective_to
       AND v.recorded_at-v.observed_at<=make_interval(secs=>policy.configuration_max_age_seconds))
 FROM ops.ad_manual_configuration_verification v
 JOIN ops.ad_manual_execution_packet packet ON packet.id=v.packet_id AND packet.organization_id=v.organization_id
 LEFT JOIN core.ad_manual_policy policy ON policy.id=packet.manual_policy_id
 WHERE v.id=p_observation),false)
$$;

CREATE FUNCTION ops.ad_manual_proposal_current(p_proposal uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'mart', 'pg_temp'
    AS $$
 SELECT p.expires_at>statement_timestamp() AND p.authority_snapshot=ops.ad_manual_snapshot(p.case_id,p.policy_id,p.observed_configuration_id)
 AND cardinality(ops.ad_action_isolation_failures(p.affected_set_id,NULL,statement_timestamp()))=0
 AND EXISTS(SELECT 1 FROM mart.ad_case c WHERE c.id=p.case_id AND c.superseded_at IS NULL)
 AND EXISTS(SELECT 1 FROM ops.recommendation r WHERE r.id=p.responsibility_recommendation_id AND r.state='TASK_ONLY' AND r.valid_until>statement_timestamp())
 AND NOT EXISTS(SELECT 1 FROM core.ad_object_configuration_observation n WHERE n.ad_native_object_id=p.ad_native_object_id
   AND n.observed_at>(SELECT observed_at FROM core.ad_object_configuration_observation WHERE id=p.observed_configuration_id))
 AND NOT EXISTS(SELECT 1 FROM core.ad_affected_set n WHERE n.ad_native_object_id=p.ad_native_object_id
   AND n.resolved_at>(SELECT resolved_at FROM core.ad_affected_set WHERE id=p.affected_set_id))
 FROM ops.ad_manual_proposal p WHERE p.id=p_proposal
$$;

CREATE FUNCTION ops.ad_manual_snapshot(p_case uuid, p_policy uuid, p_configuration uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'core', 'mart', 'platform', 'pg_temp'
    AS $$
 SELECT jsonb_build_object('policy',to_jsonb(p),'caseId',c.id,'calculationId',c.calculation_id,
   'causeCode',c.cause_code,'policyVersionDigest',c.policy_version_digest,'affectedSet',to_jsonb(a),
   'object',to_jsonb(o),'semanticProfile',to_jsonb(s),'configuration',to_jsonb(cfg),
   'outcomePolicy',(SELECT to_jsonb(outcome) FROM core.ad_outcome_policy outcome WHERE outcome.id=p.outcome_policy_id))
 FROM mart.ad_case c JOIN core.ad_native_object o ON o.id=c.ad_native_object_id
 JOIN core.ad_affected_set a ON a.id=c.affected_set_id JOIN core.ad_manual_policy p ON p.id=p_policy
 JOIN platform.ad_semantic_profile s ON s.id=o.semantic_profile_id
 JOIN core.ad_object_configuration_observation cfg ON cfg.id=p_configuration
 WHERE c.id=p_case
$$;

CREATE FUNCTION ops.ad_materiality_assessment(p_bundle uuid, p_candidate uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'core', 'mart', 'platform', 'pg_temp'
    AS $_$
DECLARE b ops.ad_decision_policy_bundle%ROWTYPE; c ops.ad_bid_candidate%ROWTYPE;
 k mart.ad_case%ROWTYPE; m core.ad_materiality_policy%ROWTYPE; affected core.ad_affected_set%ROWTYPE;
 baseline_id uuid; delta numeric; relative_delta numeric; cumulative numeric; critical_amount numeric;
 critical_count integer; critical_complete boolean; stores uuid[]; reasons text[]:='{}'; axes jsonb;
 lifecycle_ok boolean; eligible_promotion boolean; unresolved_intervention boolean;
BEGIN
 SELECT * INTO b FROM ops.ad_decision_policy_bundle WHERE id=p_bundle;
 SELECT * INTO c FROM ops.ad_bid_candidate WHERE id=p_candidate;
 SELECT * INTO k FROM mart.ad_case WHERE id=c.case_id;
 SELECT * INTO m FROM core.ad_materiality_policy WHERE id=b.materiality_policy_id;
 SELECT * INTO affected FROM core.ad_affected_set WHERE id=k.affected_set_id;
 IF b.id IS NULL OR c.id IS NULL OR k.id IS NULL OR m.id IS NULL OR m.status<>'ACTIVE'
  OR m.effective_from>statement_timestamp() OR m.effective_to<=statement_timestamp()
  OR b.organization_id<>c.organization_id OR b.store_id<>k.store_id OR b.direction<>c.direction
  OR b.candidate_basis<>c.candidate_basis OR b.semantic_profile_id<>c.semantic_profile_id
  OR m.organization_id<>c.organization_id OR m.currency_code<>c.currency_code
  OR NOT (m.scope_kind='ORGANIZATION' OR m.scope_kind='PLATFORM' AND m.platform_code=b.platform_code
    OR m.scope_kind='STORE' AND m.store_ref_id=k.store_id AND m.platform_code=b.platform_code)
  OR c.bid_unit_code NOT IN('CURRENCY_MAJOR','CURRENCY_MINOR') OR c.current_bid_amount<=0
  OR affected.id IS NULL OR affected.resolution_state<>'COMPLETE'
  OR affected.affected_set_digest<>c.affected_set_digest THEN
  RETURN jsonb_build_object('route','MATERIALITY_UNRESOLVED','reasons',jsonb_build_array('MATERIALITY_AUTHORITY_OR_SCOPE_UNRESOLVED'));
 END IF;
 delta:=abs(c.provider_normalized_amount-c.current_bid_amount)/CASE c.bid_unit_code WHEN 'CURRENCY_MINOR' THEN 100 ELSE 1 END;
 relative_delta:=abs(c.provider_normalized_amount-c.current_bid_amount)/c.current_bid_amount;
 SELECT array_agg(store.id) INTO stores FROM core.store store
 JOIN core.marketplace_account account ON account.id=store.marketplace_account_id
 WHERE store.organization_id=c.organization_id AND (m.scope_kind='ORGANIZATION'
  OR m.scope_kind='PLATFORM' AND account.platform_code=m.platform_code
  OR m.scope_kind='STORE' AND store.id=m.store_ref_id);
 WITH changes AS (
  SELECT abs(candidate.provider_normalized_amount-candidate.current_bid_amount)
    /CASE candidate.bid_unit_code WHEN 'CURRENCY_MINOR' THEN 100 ELSE 1 END AS amount,
    candidate.currency_code=m.currency_code AND candidate.bid_unit_code IN('CURRENCY_MAJOR','CURRENCY_MINOR') AS known
  FROM ops.ad_action_reservation r JOIN ops.ad_bid_candidate candidate ON candidate.id=r.intervention_reference_id
  WHERE r.organization_id=c.organization_id AND r.store_id=ANY(stores) AND candidate.id<>c.id
    AND r.reserved_at>statement_timestamp()-make_interval(hours=>m.material_cumulative_window_hours)
  UNION ALL
  SELECT CASE WHEN packet.intended_state->>'targetBid' ~ '^[0-9]+(\.[0-9]+)?$'
    THEN abs((packet.intended_state->>'targetBid')::numeric-configuration.observed_bid_amount)
      /CASE configuration.bid_unit_code WHEN 'CURRENCY_MINOR' THEN 100 ELSE 1 END END,
    configuration.bid_currency_code=m.currency_code AND configuration.bid_unit_code IN('CURRENCY_MAJOR','CURRENCY_MINOR')
      AND packet.intended_state->>'targetBid' ~ '^[0-9]+(\.[0-9]+)?$'
  FROM ops.ad_action_reservation r JOIN ops.ad_manual_execution_packet packet ON packet.id=r.intervention_reference_id
  JOIN core.ad_object_configuration_observation configuration ON configuration.id=packet.observed_configuration_id
  WHERE r.organization_id=c.organization_id AND r.store_id=ANY(stores)
    AND r.reserved_at>statement_timestamp()-make_interval(hours=>m.material_cumulative_window_hours)
  UNION ALL
  SELECT abs(command.target_bid_amount-command.prior_bid_amount)/CASE command.bid_unit_code WHEN 'CURRENCY_MINOR' THEN 100 ELSE 1 END,
    command.currency_code=m.currency_code AND command.bid_unit_code IN('CURRENCY_MAJOR','CURRENCY_MINOR')
  FROM ops.ad_bid_command command WHERE command.organization_id=c.organization_id AND command.store_id=ANY(stores)
   AND (EXISTS(SELECT 1 FROM ops.ad_compensation_authorization approval WHERE approval.command_id=command.id
      AND approval.approved_at>statement_timestamp()-make_interval(hours=>m.material_cumulative_window_hours))
    OR EXISTS(SELECT 1 FROM ops.ad_bid_command_attempt attempt WHERE attempt.command_id=command.id AND attempt.purpose='RESTORE'
      AND attempt.started_at>statement_timestamp()-make_interval(hours=>m.material_cumulative_window_hours)))
 ) SELECT delta+coalesce(sum(amount),0),coalesce(bool_or(known IS NOT TRUE OR amount IS NULL),false)
 INTO cumulative,unresolved_intervention FROM changes;
 SELECT selected.outcome_baseline_id INTO baseline_id FROM ops.ad_candidate_selection selected WHERE selected.candidate_id=c.id;
 SELECT count(*) INTO critical_count FROM core.ad_outcome_critical_unit_rule rule
 WHERE rule.outcome_policy_id=b.outcome_policy_id AND rule.product_variant_id=ANY(affected.product_variant_ids)
   AND (rule.store_id IS NULL OR rule.store_id=k.store_id);
 SELECT policy.critical_unit_definition_complete INTO critical_complete FROM core.ad_outcome_policy policy WHERE policy.id=b.outcome_policy_id;
 IF critical_count=0 AND critical_complete IS TRUE THEN critical_amount:=0;
 ELSE
  SELECT sum((unit#>>'{sales,value}')::numeric) INTO critical_amount
  FROM ops.ad_outcome_stage_baseline stage CROSS JOIN LATERAL jsonb_array_elements(stage.snapshot->'units') unit
  WHERE stage.outcome_baseline_id=baseline_id AND stage.stage='OPERATIONAL'
    AND unit#>>'{unit,ruleId}' IS NOT NULL
  HAVING count(*)=critical_count AND bool_and(unit#>>'{sales,value}' IS NOT NULL);
 END IF;
 -- Each variant uses the existing scoped commercial-policy lifecycle authority.
 SELECT bool_and(choices.n=1 AND (b.lifecycle_scope='ALL' OR choices.lifecycle=b.lifecycle_scope)) INTO lifecycle_ok
 FROM unnest(affected.product_variant_ids) variant CROSS JOIN LATERAL (
  WITH applicable AS (SELECT policy.*,dense_rank() OVER(ORDER BY CASE policy.scope_kind
    WHEN 'PRODUCT_VARIANT' THEN 1 WHEN 'STORE' THEN 2 WHEN 'PLATFORM' THEN 3 ELSE 4 END) precedence
    FROM ops.commercial_policy policy WHERE policy.organization_id=c.organization_id AND policy.status='ACTIVE'
     AND policy.effective_from<=statement_timestamp() AND (policy.effective_to IS NULL OR policy.effective_to>statement_timestamp())
     AND (policy.scope_kind='ORGANIZATION' OR policy.scope_kind='PLATFORM' AND policy.platform_code=b.platform_code
      OR policy.scope_kind='STORE' AND policy.store_ref_id=k.store_id
      OR policy.scope_kind='PRODUCT_VARIANT' AND policy.product_variant_ref_id=variant))
  SELECT count(*) n,min(lifecycle_objective) lifecycle FROM applicable WHERE precedence=1
 ) choices;
 IF delta>m.ordinary_nonzero_envelope_amount OR relative_delta>m.ordinary_relative_envelope_ratio THEN reasons:=array_append(reasons,'ORDINARY_ENVELOPE_EXCEEDED'); END IF;
 IF delta>=m.material_absolute_change_amount THEN reasons:=array_append(reasons,'ABSOLUTE_BID_CHANGE'); END IF;
 IF relative_delta>=m.material_relative_change_ratio THEN reasons:=array_append(reasons,'RELATIVE_BID_CHANGE'); END IF;
 IF k.official_spend_amount IS NULL OR k.official_spend_state<>'AVAILABLE' THEN reasons:=array_append(reasons,'OFFICIAL_SPEND_UNKNOWN');
 ELSIF k.official_spend_amount>=m.material_spend_exposure_amount THEN reasons:=array_append(reasons,'OFFICIAL_SPEND_EXPOSURE'); END IF;
 IF cardinality(affected.product_variant_ids)>=m.material_affected_variant_count THEN reasons:=array_append(reasons,'AFFECTED_VARIANT_EXPOSURE'); END IF;
 IF critical_count>0 THEN reasons:=array_append(reasons,'FIXED_CRITICAL_PROTECTED_SALES_EXPOSURE'); END IF;
 IF critical_complete IS NOT TRUE OR critical_amount IS NULL THEN reasons:=array_append(reasons,'CRITICAL_SALES_EXPOSURE_UNKNOWN');
 ELSIF critical_amount>=m.material_critical_sales_amount THEN reasons:=array_append(reasons,'CRITICAL_SALES_AMOUNT'); END IF;
 IF unresolved_intervention THEN reasons:=array_append(reasons,'CUMULATIVE_CHANGE_UNKNOWN');
 ELSIF cumulative>=m.material_cumulative_change_amount THEN reasons:=array_append(reasons,'CUMULATIVE_BID_CHANGE'); END IF;
 IF lifecycle_ok IS NOT TRUE THEN reasons:=array_append(reasons,'LIFECYCLE_OR_GOVERNED_COHORT_UNRESOLVED'); END IF;
 IF c.direction='EXACT_PRIOR_BID_COMPENSATION' THEN reasons:=array_append(reasons,'FIXED_COMPENSATION'); END IF;
 IF EXISTS(SELECT 1 FROM mart.ad_case current_case WHERE current_case.ad_native_object_id=c.ad_native_object_id
    AND current_case.superseded_at IS NULL AND (current_case.protection_tier='P0' OR current_case.cause_code='ACTION_OUTCOME_REGRESSION'))
  THEN reasons:=array_append(reasons,'FIXED_REGRESSION_OR_UNKNOWN_EXECUTION'); END IF;
 IF EXISTS(SELECT 1 FROM ops.ad_containment hold WHERE hold.organization_id=c.organization_id AND hold.state='ACTIVE'
    AND (hold.platform_code IS NULL OR hold.platform_code=b.platform_code)
    AND (hold.marketplace_account_id IS NULL OR hold.marketplace_account_id=b.marketplace_account_id)
    AND (hold.store_id IS NULL OR hold.store_id=b.store_id)
    AND (hold.ad_native_object_id IS NULL OR hold.ad_native_object_id=c.ad_native_object_id)
    AND (hold.capability_code IS NULL OR hold.capability_code=b.capability_code))
  THEN reasons:=array_append(reasons,'FIXED_QUARANTINE_OR_KILL'); END IF;
 IF k.evidence_state NOT IN('CANONICAL_CONFIRMED','OPERATIONAL') OR cardinality(k.blocker_codes)>0
  THEN reasons:=array_append(reasons,'FIXED_UNKNOWN_DECISION_EVIDENCE'); END IF;
 eligible_promotion:=ops.ad_ordinary_promotion_covers(b.id,c.ad_native_object_id,delta);
 IF NOT eligible_promotion THEN reasons:=array_append(reasons,'EXACT_ORDINARY_PROMOTION_ABSENT'); END IF;
 axes:=jsonb_build_object('absoluteBidChange',jsonb_build_object('value',delta,'threshold',m.material_absolute_change_amount,'unit',m.currency_code||'_MAJOR'),
  'relativeBidChange',jsonb_build_object('value',relative_delta,'threshold',m.material_relative_change_ratio),
  'officialSpendExposure',jsonb_build_object('value',k.official_spend_amount,'threshold',m.material_spend_exposure_amount),
  'affectedVariants',jsonb_build_object('value',cardinality(affected.product_variant_ids),'threshold',m.material_affected_variant_count),
  'criticalSalesExposure',jsonb_build_object('value',critical_amount,'requiredUnitCount',critical_count,'threshold',m.material_critical_sales_amount),
  'cumulativeBidChange',jsonb_build_object('value',CASE WHEN unresolved_intervention THEN NULL ELSE cumulative END,'threshold',m.material_cumulative_change_amount,'windowHours',m.material_cumulative_window_hours),
  'lifecycleAndCohort',jsonb_build_object('scope',b.lifecycle_scope,'complete',lifecycle_ok,'exactPromotionCovered',eligible_promotion),
  'direction',c.direction);
 RETURN jsonb_build_object('route',CASE WHEN cardinality(reasons)=0 THEN 'ORDINARY_IMPACT' ELSE 'MATERIAL_IMPACT' END,
  'policyId',m.id,'policyVersion',m.policy_version,'candidateId',c.id,'bundleId',b.id,
  'ordinaryEnvelope',jsonb_build_object('absolute',m.ordinary_nonzero_envelope_amount,'relative',m.ordinary_relative_envelope_ratio),
  'axes',axes,'reasons',to_jsonb(reasons));
END $_$;

CREATE FUNCTION ops.ad_nonnegative_numeric(p_value text) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
 SELECT CASE WHEN p_value ~ '^[0-9]+(\.[0-9]+)?$' AND length(p_value)<=40 THEN p_value::numeric END
$_$;

CREATE FUNCTION ops.ad_ordinary_promotion_covers(p_bundle uuid, p_object uuid, p_change numeric) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
 SELECT EXISTS(SELECT 1 FROM ops.ad_decision_policy_bundle b
 JOIN ops.ad_ordinary_promotion p ON p.id=b.ordinary_promotion_id AND p.bundle_id=b.id
 JOIN ops.ad_gate_authority g ON g.id=p.gate_authority_id AND g.bundle_id=b.id
 WHERE b.id=p_bundle AND b.status='ACTIVE' AND p.status='ACTIVE' AND g.status='ACTIVE'
 AND g.gate_kind='GATE_E' AND p_object=ANY(g.native_object_ids)
 AND p_change<=p.material_envelope_amount AND p_change<=g.max_bid_change_amount
 AND statement_timestamp()>=greatest(p.valid_from,g.valid_from)
 AND statement_timestamp()<least(p.valid_until,g.valid_until))
$$;

CREATE FUNCTION ops.ad_outcome_action_anchor_is_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
    IF NEW.outcome_baseline_id IS DISTINCT FROM OLD.outcome_baseline_id THEN
        RAISE EXCEPTION 'a reviewed action cannot replace its frozen baseline' USING ERRCODE='MO099';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.ad_outcome_baseline_is_attested(p_baseline uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
 SELECT EXISTS(SELECT 1 FROM ops.ad_outcome_baseline b JOIN ops.ad_outcome_baseline_attestation a
  ON a.outcome_baseline_id=b.id AND a.organization_id=b.organization_id
  WHERE b.id=p_baseline AND a.planner_authority='CANONICAL_OUTCOME_PLANNER_V1'
    AND a.payload_digest=ops.ad_outcome_stored_payload_digest(b.id))
$$;

CREATE FUNCTION ops.ad_outcome_baseline_is_canonical(p_baseline uuid, p_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'platform', 'mart', 'pg_temp'
    AS $$
DECLARE b ops.ad_outcome_baseline%ROWTYPE; p core.ad_outcome_policy%ROWTYPE; a core.ad_affected_set%ROWTYPE;
 obj core.ad_native_object%ROWTYPE; st record; snap jsonb; item jsonb; units jsonb; expected_units jsonb;
 expected_critical jsonb; actual_critical jsonb; hours integer; policy_json jsonb; fresh core.ad_freshness_profile%ROWTYPE;
 direction_code text; original_cause text; original_semantic uuid; original_generation integer;
 purpose_code text; kind_code text; calc uuid; digest text; company numeric; total numeric;
BEGIN
 SELECT * INTO b FROM ops.ad_outcome_baseline WHERE id=p_baseline;
 IF NOT FOUND OR b.state<>'COMPLETE' OR cardinality(b.blocker_codes)<>0 OR b.prepared_at>p_at OR b.valid_until<=p_at
   OR NOT ops.ad_outcome_baseline_is_attested(b.id) THEN RETURN false; END IF;
 SELECT * INTO p FROM core.ad_outcome_policy WHERE id=b.outcome_policy_id AND organization_id=b.organization_id;
 SELECT * INTO a FROM core.ad_affected_set WHERE id=b.affected_set_id AND organization_id=b.organization_id;
 SELECT * INTO obj FROM core.ad_native_object WHERE id=b.ad_native_object_id AND organization_id=b.organization_id;
 IF p.id IS NULL OR a.id IS NULL OR obj.id IS NULL OR p.policy_version<>b.outcome_policy_version
   OR p.status NOT IN('ACTIVE','RETIRED') OR p.effective_from>b.prepared_at OR p.effective_from>p_at
   OR (p.effective_to IS NOT NULL AND (p.effective_to<=p_at OR b.valid_until>p.effective_to))
   OR a.resolution_state<>'COMPLETE' OR a.ad_native_object_id<>b.ad_native_object_id OR a.resolved_at>b.prepared_at
   OR a.affected_set_digest<>b.affected_set_digest OR NOT(a.product_variant_ids @> b.product_variant_ids AND a.product_variant_ids <@ b.product_variant_ids)
   OR NOT p.critical_unit_definition_complete
   OR num_nonnulls(p.material_profit_delta,p.material_profit_per_rub_delta,p.sales_preservation_tolerance_ratio,
      p.non_worsening_profit_band,p.non_worsening_per_rub_band,p.minimum_ad_spend_denominator,p.comparison_scale,
      p.comparison_rounding_mode,p.material_boundary_inclusive,p.negative_profit_terminal)<>10
 THEN RETURN false; END IF;
 policy_json:=ops.ad_outcome_plan_snapshot(p.id);
 IF b.plan_snapshot IS DISTINCT FROM policy_json THEN RETURN false; END IF;
 IF b.candidate_id IS NOT NULL THEN
  SELECT k.calculation_id,k.policy_version_digest,c.direction,c.cause_code,c.semantic_profile_id,k.lineage_generation
    INTO calc,digest,direction_code,original_cause,original_semantic,original_generation
  FROM ops.ad_bid_candidate c JOIN mart.ad_case k ON k.id=c.case_id
  WHERE c.id=b.candidate_id AND c.organization_id=b.organization_id AND k.ad_native_object_id=b.ad_native_object_id
    AND k.affected_set_id=b.affected_set_id AND k.superseded_at IS NULL;
 ELSE
  SELECT k.calculation_id,k.policy_version_digest,m.intended_state->>'direction',k.cause_code,k.semantic_profile_id,k.lineage_generation
    INTO calc,digest,direction_code,original_cause,original_semantic,original_generation
  FROM ops.ad_manual_proposal m JOIN mart.ad_case k ON k.id=m.case_id
  WHERE m.id=b.manual_proposal_id AND m.organization_id=b.organization_id AND k.ad_native_object_id=b.ad_native_object_id
    AND k.affected_set_id=b.affected_set_id AND k.superseded_at IS NULL;
 END IF;
 IF calc IS DISTINCT FROM b.case_calculation_id OR digest IS DISTINCT FROM b.policy_version_digest
   OR direction_code IS DISTINCT FROM p.direction OR original_semantic IS DISTINCT FROM obj.semantic_profile_id
   OR original_generation IS DISTINCT FROM obj.lineage_generation THEN RETURN false; END IF;
 -- This check authorizes only a new/current action against its exact bound policy.
 -- Completed-action Outcome evaluation never calls this current resolver.
 IF NOT EXISTS(SELECT 1 FROM core.ad_outcome_bound_policy_resolution(b.organization_id,obj.platform_code,obj.store_id,
    direction_code,original_cause,p_at,b.outcome_policy_id) r
    WHERE r.state='RESOLVED' AND r.policy_version=b.outcome_policy_version) THEN RETURN false; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('productVariantId',m.product_variant_id,'listingVariantId',m.platform_listing_variant_id,
    'storeId',listing.store_id,'ruleId',(SELECT r.id FROM core.ad_outcome_critical_unit_rule r
      WHERE r.organization_id=b.organization_id AND r.outcome_policy_id=p.id AND r.product_variant_id=m.product_variant_id
        AND (r.store_id IS NULL OR r.store_id=listing.store_id) ORDER BY r.store_id NULLS LAST LIMIT 1))
    ORDER BY m.product_variant_id,m.platform_listing_variant_id),'[]') INTO expected_units
 FROM core.listing_mapping m JOIN core.platform_listing_variant variant ON variant.id=m.platform_listing_variant_id
 JOIN core.platform_listing listing ON listing.id=variant.platform_listing_id
 WHERE m.organization_id=b.organization_id AND m.product_variant_id=ANY(b.product_variant_ids)
   AND m.status IN('ACTIVE','ENDED') AND m.effective_from<=b.prepared_at AND (m.effective_to IS NULL OR m.effective_to>b.prepared_at);
 IF jsonb_array_length(expected_units)=0 OR EXISTS(SELECT 1 FROM unnest(b.product_variant_ids) product
      WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(expected_units) unit WHERE (unit->>'productVariantId')::uuid=product))
    OR (SELECT array_agg((unit->>'listingVariantId')::uuid ORDER BY unit->>'listingVariantId') FROM jsonb_array_elements(expected_units) unit)
      IS DISTINCT FROM (SELECT array_agg(listing ORDER BY listing::text) FROM unnest(b.listing_variant_ids) listing) THEN RETURN false; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('productVariantId',unit->'productVariantId','listingVariantId',unit->'listingVariantId','ruleId',unit->'ruleId')
   ORDER BY unit->>'productVariantId',unit->>'listingVariantId'),'[]') INTO expected_critical
 FROM jsonb_array_elements(expected_units) unit WHERE unit->>'ruleId' IS NOT NULL;
 SELECT coalesce(jsonb_agg(jsonb_build_object('productVariantId',u.product_variant_id,'listingVariantId',u.listing_variant_id,'ruleId',u.rule_id)
   ORDER BY u.product_variant_id,u.listing_variant_id),'[]') INTO actual_critical
 FROM ops.ad_outcome_critical_unit u WHERE u.outcome_baseline_id=b.id;
 IF expected_critical IS DISTINCT FROM actual_critical OR (SELECT count(*) FROM ops.ad_outcome_stage_baseline WHERE outcome_baseline_id=b.id)<>3 THEN RETURN false; END IF;
 FOR st IN SELECT * FROM ops.ad_outcome_stage_baseline WHERE outcome_baseline_id=b.id LOOP
  snap:=st.snapshot;
  hours:=CASE st.stage WHEN 'OPERATIONAL' THEN p.completed_sales_guard_hours WHEN 'RETAINED' THEN 720 ELSE greatest(720,p.settlement_window_hours) END;
  purpose_code:=CASE st.stage WHEN 'OPERATIONAL' THEN 'EARLY_COMPLETED_SALES_OUTCOME' WHEN 'RETAINED' THEN 'FINAL_RETAINED_SALES_OUTCOME' ELSE 'SETTLED_FINANCIAL_OUTCOME' END;
  kind_code:=CASE st.stage WHEN 'OPERATIONAL' THEN 'COMPANY_COMPLETED_SALE' WHEN 'RETAINED' THEN 'COMPANY_RETAINED_SALE' ELSE 'SETTLEMENT' END;
  IF st.window_hours<>hours OR snap->>'stage' IS DISTINCT FROM st.stage
    OR snap->'originalIdentity' IS DISTINCT FROM jsonb_build_object('semanticProfileId',original_semantic,'lineageGeneration',original_generation)
    OR (snap->>'from')::timestamptz IS DISTINCT FROM b.prepared_at-make_interval(hours=>hours)
    OR (snap->>'to')::timestamptz IS DISTINCT FROM b.prepared_at
    OR jsonb_typeof(snap->'units') IS DISTINCT FROM 'array' OR jsonb_typeof(snap->'evidenceIds') IS DISTINCT FROM 'array'
    OR jsonb_typeof(snap->'blockers') IS DISTINCT FROM 'array' OR jsonb_typeof(snap->'profit') IS DISTINCT FROM 'object'
    OR jsonb_typeof(snap->'companySales') IS DISTINCT FROM 'object' OR jsonb_typeof(snap->'officialSpend') IS DISTINCT FROM 'object'
    OR snap->>'confounderDigest' IS NULL OR original_cause IS NULL
    OR snap->>'originalCause' IS DISTINCT FROM original_cause THEN RETURN false; END IF;
  IF NOT ops.ad_outcome_input_profiles_are_canonical(snap,b.organization_id,b.ad_native_object_id,st.stage,
    direction_code,b.prepared_at,b.valid_until,p_at) THEN RETURN false; END IF;
  SELECT jsonb_agg(unit->'unit' ORDER BY unit#>>'{unit,productVariantId}',unit#>>'{unit,listingVariantId}') INTO units
   FROM jsonb_array_elements(snap->'units') unit;
  IF units IS DISTINCT FROM expected_units THEN RETURN false; END IF;
  SELECT * INTO fresh FROM core.ad_freshness_profile WHERE id=(snap#>>'{freshnessProfile,id}')::uuid
    AND organization_id=b.organization_id AND status IN('ACTIVE','RETIRED') AND effective_from<=b.prepared_at
    AND (effective_to IS NULL OR (effective_to>p_at AND b.valid_until<=effective_to))
    AND effective_from<=p_at AND decision_purpose=purpose_code AND evidence_kind=kind_code
    AND (scope_kind='ORGANIZATION' OR (scope_kind='PLATFORM' AND platform_code=obj.platform_code)
      OR (scope_kind='STORE' AND platform_code=obj.platform_code AND store_ref_id=obj.store_id)
      OR (scope_kind='SEMANTIC_PROFILE' AND platform_code=obj.platform_code AND semantic_profile_id=obj.semantic_profile_id
         AND (store_ref_id IS NULL OR store_ref_id=obj.store_id)));
  IF NOT FOUND OR ((snap->'freshnessProfile')-'effectiveTo') IS DISTINCT FROM (ops.ad_outcome_freshness_snapshot(fresh.id)-'effectiveTo')
    OR (snap#>>'{freshnessProfile,effectiveTo}')::timestamptz IS DISTINCT FROM fresh.effective_to THEN RETURN false; END IF;
  IF EXISTS(SELECT 1 FROM core.ad_freshness_profile other WHERE other.organization_id=b.organization_id
    AND other.id<>fresh.id AND other.evidence_kind=kind_code AND other.decision_purpose=purpose_code
    AND other.status IN('ACTIVE','RETIRED') AND other.effective_from<=p_at AND (other.effective_to IS NULL OR other.effective_to>p_at)
    AND (other.scope_kind='ORGANIZATION' OR (other.scope_kind='PLATFORM' AND other.platform_code=obj.platform_code)
      OR (other.scope_kind='STORE' AND other.platform_code=obj.platform_code AND other.store_ref_id=obj.store_id)
      OR (other.scope_kind='SEMANTIC_PROFILE' AND other.platform_code=obj.platform_code AND other.semantic_profile_id=obj.semantic_profile_id
         AND (other.store_ref_id IS NULL OR other.store_ref_id=obj.store_id)))
    AND CASE other.scope_kind WHEN 'SEMANTIC_PROFILE' THEN 0 WHEN 'STORE' THEN 1 WHEN 'PLATFORM' THEN 2 ELSE 3 END
      <=CASE fresh.scope_kind WHEN 'SEMANTIC_PROFILE' THEN 0 WHEN 'STORE' THEN 1 WHEN 'PLATFORM' THEN 2 ELSE 3 END) THEN RETURN false; END IF;
  total:=0;
  FOR item IN SELECT value FROM jsonb_array_elements(snap->'units') LOOP
   IF st.stage='OPERATIONAL' AND (item#>>'{sales,valueState}' IS DISTINCT FROM 'AVAILABLE'
      OR item#>>'{sales,evidenceState}' NOT IN('CANONICAL_CONFIRMED','OPERATIONAL')
      OR jsonb_typeof(item#>'{sales,value}') IS DISTINCT FROM 'number') THEN RETURN false; END IF;
   total:=total+(item#>>'{sales,value}')::numeric;
  END LOOP;
  IF st.stage='OPERATIONAL' AND (snap#>>'{companySales,valueState}' IS DISTINCT FROM 'AVAILABLE'
     OR snap#>>'{companySales,evidenceState}' NOT IN('CANONICAL_CONFIRMED','OPERATIONAL')
     OR (snap#>>'{companySales,value}')::numeric IS DISTINCT FROM total) THEN RETURN false; END IF;
  IF direction_code='OPTIMIZATION_INCREASE' AND st.stage='RETAINED' AND
    (snap#>>'{companySales,valueState}' IS DISTINCT FROM 'AVAILABLE'
     OR snap#>>'{profit,absoluteProfit,valueState}' IS DISTINCT FROM 'AVAILABLE'
     OR snap#>>'{profit,profitPerAdRub,valueState}' IS DISTINCT FROM 'AVAILABLE'
     OR snap#>>'{profit,absoluteProfit,evidenceState}' NOT IN('CANONICAL_CONFIRMED','OPERATIONAL')
     OR snap#>>'{profit,profitPerAdRub,evidenceState}' NOT IN('CANONICAL_CONFIRMED','OPERATIONAL')) THEN RETURN false; END IF;
 END LOOP;
 RETURN true;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR invalid_datetime_format THEN RETURN false;
END $$;

CREATE FUNCTION ops.ad_outcome_candidate_policy_resolution(p_candidate uuid, p_at timestamp with time zone) RETURNS TABLE(state text, policy_id uuid, policy_version integer)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'core', 'mart', 'pg_temp'
    AS $$
 WITH result AS (
  SELECT r.* FROM ops.ad_bid_candidate c JOIN mart.ad_case k ON k.id=c.case_id AND k.organization_id=c.organization_id
  LEFT JOIN LATERAL (SELECT CASE WHEN count(*)=1 THEN (array_agg(b.outcome_policy_id))[1] END policy_id
   FROM ops.ad_decision_policy_bundle b WHERE b.organization_id=c.organization_id AND b.store_id=k.store_id
    AND b.semantic_profile_id=c.semantic_profile_id AND b.target_policy_id=c.target_policy_id
    AND b.direction=c.direction AND b.candidate_basis=c.candidate_basis
    AND b.status='ACTIVE' AND b.validation_state='VALIDATED' AND b.effective_from<=p_at
    AND (b.effective_to IS NULL OR b.effective_to>p_at)) bound ON true
  CROSS JOIN LATERAL core.ad_outcome_bound_policy_resolution(c.organization_id,k.platform_code,k.store_id,
   c.direction,c.cause_code,p_at,bound.policy_id) r
  WHERE c.id=p_candidate AND k.superseded_at IS NULL
 ) SELECT * FROM result
 UNION ALL SELECT 'OUTCOME_POLICY_UNRESOLVED',NULL::uuid,NULL::integer WHERE NOT EXISTS(SELECT 1 FROM result)
$$;

CREATE FUNCTION ops.ad_outcome_freshness_snapshot(p_profile uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'core', 'pg_temp'
    AS $$
 SELECT jsonb_build_object('id',f.id,'version',f.profile_version,'evidenceKind',f.evidence_kind,'decisionPurpose',f.decision_purpose,
  'sourceMaxAgeMinutes',f.source_max_age_minutes,'acceptedFactMaxAgeMinutes',f.accepted_fact_max_age_minutes,
  'expectedPublicationLagMinutes',f.expected_publication_lag_minutes,'correctionWindowMinutes',f.correction_window_minutes,
  'requiresWindowComplete',f.requires_window_complete,'requiresCorrectionWindowClosed',f.requires_correction_window_closed,
  'minimumCoverageRatio',f.minimum_coverage_ratio,'minimumConfidenceState',f.minimum_confidence_state,
  'providerIncidentBlocks',f.provider_incident_blocks,'effectiveTo',f.effective_to,
  'authorityDigest',encode(sha256(convert_to(jsonb_build_object(
    'organizationId',f.organization_id,'scopeKind',f.scope_kind,'platformCode',f.platform_code,
    'storeRefId',f.store_ref_id,'semanticProfileId',f.semantic_profile_id,
    'effectiveFromEpoch',extract(epoch FROM f.effective_from))::text,'UTF8')),'hex'))
 FROM core.ad_freshness_profile f WHERE f.id=p_profile
$$;

CREATE FUNCTION ops.ad_outcome_frozen_profile_is_valid(p_snapshot jsonb, p_organization uuid, p_object uuid, p_kind text, p_purpose text, p_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'pg_temp'
    AS $$
DECLARE f core.ad_freshness_profile%ROWTYPE; o core.ad_native_object%ROWTYPE; exact jsonb;
BEGIN
 IF p_at IS NULL OR jsonb_typeof(p_snapshot) IS DISTINCT FROM 'object'
   OR p_snapshot->>'evidenceKind' IS DISTINCT FROM p_kind
   OR p_snapshot->>'decisionPurpose' IS DISTINCT FROM p_purpose THEN RETURN false; END IF;
 SELECT * INTO o FROM core.ad_native_object WHERE id=p_object AND organization_id=p_organization;
 SELECT * INTO f FROM core.ad_freshness_profile WHERE id=(p_snapshot->>'id')::uuid
  AND organization_id=p_organization AND evidence_kind=p_kind AND decision_purpose=p_purpose
  AND status IN('ACTIVE','RETIRED') AND effective_from<=p_at
  AND (effective_to IS NULL OR effective_to>p_at);
 IF o.id IS NULL OR f.id IS NULL OR NOT (f.scope_kind='ORGANIZATION'
   OR (f.scope_kind='PLATFORM' AND f.platform_code=o.platform_code)
   OR (f.scope_kind='STORE' AND f.platform_code=o.platform_code AND f.store_ref_id=o.store_id)
   OR (f.scope_kind='SEMANTIC_PROFILE' AND f.platform_code=o.platform_code AND f.semantic_profile_id=o.semantic_profile_id
      AND (f.store_ref_id IS NULL OR f.store_ref_id=o.store_id))) THEN RETURN false; END IF;
 exact:=ops.ad_outcome_freshness_snapshot(f.id);
 IF (p_snapshot-'effectiveTo') IS DISTINCT FROM (exact-'effectiveTo')
   OR (p_snapshot->>'effectiveTo')::timestamptz IS DISTINCT FROM f.effective_to THEN RETURN false; END IF;
 RETURN true;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR invalid_datetime_format
 OR datetime_field_overflow THEN RETURN false;
END $$;

CREATE FUNCTION ops.ad_outcome_input_profiles_are_canonical(p_snapshot jsonb, p_organization uuid, p_object uuid, p_stage text, p_direction text, p_prepared timestamp with time zone, p_valid_until timestamp with time zone, p_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'pg_temp'
    AS $$
DECLARE o core.ad_native_object%ROWTYPE; f core.ad_freshness_profile%ROWTYPE;
 profiles jsonb; entry record; proof jsonb; purpose text; company_kind text; required text[]; allowed text[];
BEGIN
 IF p_prepared IS NULL OR p_valid_until IS NULL OR p_at IS NULL OR p_prepared>p_at OR p_valid_until<=p_at
   OR p_stage IS NULL OR p_stage NOT IN('OPERATIONAL','RETAINED','SETTLED')
   OR p_direction IS NULL OR p_direction NOT IN('PROTECTION_DECREASE','OPTIMIZATION_INCREASE') THEN RETURN false; END IF;
 purpose:=CASE p_stage WHEN 'OPERATIONAL' THEN 'EARLY_COMPLETED_SALES_OUTCOME'
  WHEN 'RETAINED' THEN 'FINAL_RETAINED_SALES_OUTCOME' ELSE 'SETTLED_FINANCIAL_OUTCOME' END;
 company_kind:=CASE p_stage WHEN 'OPERATIONAL' THEN 'COMPANY_COMPLETED_SALE'
  WHEN 'RETAINED' THEN 'COMPANY_RETAINED_SALE' ELSE 'SETTLEMENT' END;
 allowed:=ARRAY[company_kind,'OFFICIAL_AD_SPEND','OFFICIAL_AD_TRAFFIC','AD_LINKED_SALE_EVENT','COST_AND_FEE',
  'AD_OBJECT_CONFIGURATION','AFFECTED_SET','SELLABILITY','AVAILABILITY','PRICE_AND_PROMOTION'];
 profiles:=p_snapshot->'freshnessProfiles';
 IF jsonb_typeof(profiles) IS DISTINCT FROM 'object' OR NOT profiles ? company_kind
   OR profiles->company_kind IS DISTINCT FROM p_snapshot->'freshnessProfile' THEN RETURN false; END IF;
 SELECT * INTO o FROM core.ad_native_object WHERE id=p_object AND organization_id=p_organization;
 IF NOT FOUND THEN RETURN false; END IF;
 FOR entry IN SELECT key,value FROM jsonb_each(profiles) LOOP
  IF NOT entry.key=ANY(allowed) OR NOT ops.ad_outcome_frozen_profile_is_valid(entry.value,p_organization,p_object,entry.key,purpose,p_at)
    THEN RETURN false; END IF;
  SELECT * INTO f FROM core.ad_freshness_profile WHERE id=(entry.value->>'id')::uuid;
  IF f.effective_from>p_prepared OR (f.effective_to IS NOT NULL AND p_valid_until>f.effective_to) THEN RETURN false; END IF;
  -- A planning/seal decision must resolve the unique applicable Profile. This
  -- check is absent from frozen observation validation above.
  IF EXISTS(SELECT 1 FROM core.ad_freshness_profile other WHERE other.organization_id=p_organization
    AND other.id<>f.id AND other.evidence_kind=entry.key AND other.decision_purpose=purpose
    AND other.status IN('ACTIVE','RETIRED') AND other.effective_from<=p_at AND (other.effective_to IS NULL OR other.effective_to>p_at)
    AND (other.scope_kind='ORGANIZATION' OR (other.scope_kind='PLATFORM' AND other.platform_code=o.platform_code)
      OR (other.scope_kind='STORE' AND other.platform_code=o.platform_code AND other.store_ref_id=o.store_id)
      OR (other.scope_kind='SEMANTIC_PROFILE' AND other.platform_code=o.platform_code AND other.semantic_profile_id=o.semantic_profile_id
         AND (other.store_ref_id IS NULL OR other.store_ref_id=o.store_id)))
    AND CASE other.scope_kind WHEN 'SEMANTIC_PROFILE' THEN 0 WHEN 'STORE' THEN 1 WHEN 'PLATFORM' THEN 2 ELSE 3 END
      <=CASE f.scope_kind WHEN 'SEMANTIC_PROFILE' THEN 0 WHEN 'STORE' THEN 1 WHEN 'PLATFORM' THEN 2 ELSE 3 END) THEN RETURN false; END IF;
 END LOOP;
 -- Physical Protection requires company safety; absent unrelated economics
 -- remain unresolved. A Profile becomes mandatory when its value is consumed.
 required:=ARRAY[company_kind];
 IF p_snapshot#>>'{officialSpend,valueState}'='AVAILABLE'
   AND p_snapshot#>>'{officialSpend,evidenceState}' IN('CANONICAL_CONFIRMED','OPERATIONAL') THEN
  required:=required||ARRAY['OFFICIAL_AD_SPEND']; END IF;
 IF jsonb_typeof(p_snapshot->'traffic')='number' THEN required:=required||ARRAY['OFFICIAL_AD_TRAFFIC']; END IF;
 IF (p_snapshot#>>'{profit,absoluteProfit,valueState}'='AVAILABLE'
     AND p_snapshot#>>'{profit,absoluteProfit,evidenceState}' IN('CANONICAL_CONFIRMED','OPERATIONAL'))
   OR (p_snapshot#>>'{profit,profitPerAdRub,valueState}'='AVAILABLE'
     AND p_snapshot#>>'{profit,profitPerAdRub,evidenceState}' IN('CANONICAL_CONFIRMED','OPERATIONAL')) THEN
  required:=required||ARRAY['OFFICIAL_AD_SPEND','AD_LINKED_SALE_EVENT','COST_AND_FEE']; END IF;
 IF p_snapshot#>>'{protectionEvidence,exactAffectedScope}'='true' THEN required:=required||ARRAY['AFFECTED_SET']; END IF;
 IF p_snapshot#>>'{protectionEvidence,configurationVerified}'='true' THEN required:=required||ARRAY['AD_OBJECT_CONFIGURATION']; END IF;
 IF p_snapshot#>>'{protectionEvidence,sellabilityCleared}'='true' THEN required:=required||ARRAY['SELLABILITY']; END IF;
 IF p_snapshot#>>'{protectionEvidence,availabilityCleared}'='true' THEN required:=required||ARRAY['AVAILABILITY']; END IF;
 IF p_snapshot ? 'purposeEvidence' THEN
  IF jsonb_typeof(p_snapshot->'purposeEvidence') IS DISTINCT FROM 'array' THEN RETURN false; END IF;
  FOR proof IN SELECT value FROM jsonb_array_elements(p_snapshot->'purposeEvidence') LOOP
   IF proof->>'eligible'='true' THEN
    IF proof->>'purpose' IS DISTINCT FROM purpose OR NOT coalesce((proof->>'kind')=ANY(allowed),false)
      OR proof->>'profileId' IS DISTINCT FROM profiles#>>ARRAY[proof->>'kind','id'] THEN RETURN false; END IF;
    required:=required||ARRAY[proof->>'kind'];
   END IF;
  END LOOP;
 END IF;
 IF p_direction='OPTIMIZATION_INCREASE' THEN
  required:=required||ARRAY['OFFICIAL_AD_SPEND','OFFICIAL_AD_TRAFFIC','AD_LINKED_SALE_EVENT','COST_AND_FEE','AFFECTED_SET'];
 END IF;
 IF EXISTS(SELECT 1 FROM unnest(required) kind WHERE NOT profiles ? kind) THEN RETURN false; END IF;
 RETURN true;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR invalid_datetime_format
 OR datetime_field_overflow THEN RETURN false;
END $$;

CREATE FUNCTION ops.ad_outcome_input_state_digest(p_observation uuid, p_input jsonb, p_at timestamp with time zone) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'ledger', 'mart', 'platform', 'pg_temp'
    SET "TimeZone" TO 'UTC'
    AS $$
 WITH scope AS (
  SELECT o.*,b.listing_variant_ids,b.product_variant_ids,b.affected_set_id,
    replace(o.outcome_stage,'_REVISED','') stage,
    CASE WHEN o.window_ends_at-o.window_starts_at=interval '7 days' THEN 'D7'
      WHEN o.window_ends_at-o.window_starts_at=interval '14 days' THEN 'D14' ELSE 'D30' END metric_window
  FROM ops.ad_outcome_observation o JOIN ops.ad_outcome_baseline b ON b.id=(
    SELECT s.outcome_baseline_id FROM ops.ad_outcome_stage_baseline s
    WHERE s.outcome_baseline_id=coalesce(
      (SELECT c.outcome_baseline_id FROM ops.ad_bid_command c WHERE c.id=o.command_id),
      (SELECT m.outcome_baseline_id FROM ops.ad_manual_execution_packet m WHERE m.id=o.manual_packet_id))
      AND s.stage=replace(o.outcome_stage,'_REVISED',''))
  WHERE o.id=p_observation AND o.evaluated_at<=p_at
 ), selected_sales AS (
  SELECT f.*,source.source_time provenance_source,source.ingestion_time provenance_accepted
  FROM scope s JOIN ledger.sales_fact f ON f.organization_id=s.organization_id
    AND f.platform_listing_variant_id=ANY(s.listing_variant_ids)
  JOIN core.fact_provenance source ON source.id=f.provenance_id AND source.ingestion_time<=p_at
  WHERE f.occurred_at>=s.window_starts_at AND f.occurred_at<s.window_ends_at
    AND f.sale_stage=CASE s.stage WHEN 'OPERATIONAL' THEN 'COMPLETED' ELSE 'RETAINED' END
    AND (f.sale_stage<>'RETAINED' OR f.retention_window_days=30)
    AND NOT EXISTS(SELECT 1 FROM ledger.sales_fact newer JOIN core.fact_provenance provenance ON provenance.id=newer.provenance_id
      WHERE newer.supersedes_fact_id=f.id AND provenance.ingestion_time<=p_at)
 ), selected_linked AS (
  SELECT e.*,coalesce(e.source_time<=p_at,false) source_time_admissible FROM scope s JOIN ledger.ad_linked_sale_event e ON e.organization_id=s.organization_id
    AND e.ad_native_object_id=s.ad_native_object_id AND e.occurred_at>=s.window_starts_at
    AND e.occurred_at<s.window_ends_at AND e.recorded_at<=p_at
    AND e.sale_stage=CASE s.stage WHEN 'OPERATIONAL' THEN 'CANONICAL_AD_LINKED_COMPLETED_SALE' ELSE 'CANONICAL_AD_LINKED_RETAINED_SALE' END
    AND NOT EXISTS(SELECT 1 FROM ledger.ad_linked_sale_event newer WHERE newer.supersedes_event_id=e.id AND newer.recorded_at<=p_at)
 ), cost_cohorts AS (
  SELECT e.platform_listing_variant_id,min(e.period_start) cohort_from,max(e.period_end) cohort_to
  FROM selected_linked e WHERE e.platform_listing_variant_id IS NOT NULL
  GROUP BY e.platform_listing_variant_id
 ), health AS (
  SELECT h.*,p.source_time provenance_source,p.ingestion_time provenance_accepted,coalesce(p.source_time<=p_at,false) source_time_admissible
  FROM scope s JOIN core.listing_health_observation h ON h.organization_id=s.organization_id
    AND h.platform_listing_variant_id=ANY(s.listing_variant_ids) AND h.observed_at<=p_at
  JOIN core.fact_provenance p ON p.id=h.provenance_id AND p.ingestion_time<=p_at
 ), stock AS (
  SELECT h.*,p.source_time provenance_source,p.ingestion_time provenance_accepted,coalesce(p.source_time<=p_at,false) source_time_admissible
  FROM scope s JOIN core.listing_stock_observation h ON h.organization_id=s.organization_id
    AND h.platform_listing_variant_id=ANY(s.listing_variant_ids) AND h.observed_at<=p_at
  JOIN core.fact_provenance p ON p.id=h.provenance_id AND p.ingestion_time<=p_at
 ), price AS (
  SELECT h.*,p.source_time provenance_source,p.ingestion_time provenance_accepted,coalesce(p.source_time<=p_at,false) source_time_admissible
  FROM scope s JOIN core.listing_price_observation h ON h.organization_id=s.organization_id
    AND h.platform_listing_variant_id=ANY(s.listing_variant_ids) AND h.observed_at<=p_at
  JOIN core.fact_provenance p ON p.id=h.provenance_id AND p.ingestion_time<=p_at
 ), config AS (
  SELECT c.*,p.ingestion_time provenance_accepted FROM scope s
  JOIN core.ad_object_configuration_observation c ON c.organization_id=s.organization_id
    AND c.ad_native_object_id=s.ad_native_object_id AND c.observed_at<=p_at AND c.source_time<=p_at
  JOIN core.fact_provenance p ON p.id=c.provenance_id AND p.ingestion_time<=p_at
 ), proof_states AS (
  SELECT proof->>'kind' kind,proof->>'profileId' profile_id,
    ops.ad_outcome_frozen_profile_is_valid(p_input#>ARRAY['observation','freshnessProfiles',proof->>'kind'],s.organization_id,
      s.ad_native_object_id,proof->>'kind',proof->>'purpose',p_at) exact_profile_valid,
    coalesce((proof->>'expiresAt')::timestamptz<=p_at,false) expiry_crossed,
    coalesce((proof->>'sourceTime')::timestamptz<=p_at,false) source_time_admissible,
    coalesce((proof->>'acceptedAt')::timestamptz<=p_at,false) accepted_time_admissible,
    coalesce(p_at>=s.window_ends_at+make_interval(mins=>greatest(
      (p_input#>>ARRAY['observation','freshnessProfiles',proof->>'kind','expectedPublicationLagMinutes'])::integer,
      CASE WHEN p_input#>>ARRAY['observation','freshnessProfiles',proof->>'kind','requiresCorrectionWindowClosed']='true'
        THEN (p_input#>>ARRAY['observation','freshnessProfiles',proof->>'kind','correctionWindowMinutes'])::integer ELSE 0 END)),false) publication_mature,
    coalesce((p_input#>>ARRAY['observation','freshnessProfiles',proof->>'kind','providerIncidentBlocks'])::boolean,false)
      AND EXISTS(SELECT 1 FROM platform.ad_provider_incident i JOIN core.fact_provenance provenance
        ON provenance.id=i.provenance_id AND provenance.ingestion_time<=p_at
        JOIN core.ad_native_object obj ON obj.id=s.ad_native_object_id AND obj.organization_id=s.organization_id
        WHERE i.organization_id=s.organization_id AND i.platform_code=obj.platform_code
          AND (i.store_id IS NULL OR i.store_id=obj.store_id) AND i.incident_open AND i.observed_at<=p_at AND i.valid_until>p_at) incident_blocks
  FROM scope s CROSS JOIN LATERAL jsonb_array_elements(coalesce(p_input#>'{observation,purposeEvidence}','[]'::jsonb)) proof
 ), states AS (
  SELECT jsonb_build_object(
   'object',(SELECT to_jsonb(obj) FROM core.ad_native_object obj WHERE obj.id=s.ad_native_object_id AND obj.organization_id=s.organization_id),
   'semanticProfile',(SELECT to_jsonb(profile) FROM platform.ad_semantic_profile profile JOIN core.ad_native_object obj
     ON obj.semantic_profile_id=profile.id WHERE obj.id=s.ad_native_object_id AND obj.organization_id=s.organization_id),
   'adFacts',(SELECT coalesce(jsonb_agg(to_jsonb(f)||jsonb_build_object('sourceTimeAdmissible',coalesce(f.source_time<=p_at,false)) ORDER BY f.id),'[]') FROM ledger.ad_object_fact f
     WHERE f.organization_id=s.organization_id AND f.ad_native_object_id=s.ad_native_object_id AND f.recorded_at<=p_at
       AND f.period_start<s.window_ends_at AND f.period_end>s.window_starts_at
       AND NOT EXISTS(SELECT 1 FROM ledger.ad_object_fact newer WHERE newer.supersedes_fact_id=f.id AND newer.recorded_at<=p_at)),
   'linkedSales',(SELECT coalesce(jsonb_agg(to_jsonb(e) ORDER BY e.id),'[]') FROM selected_linked e),
   'companySales',(SELECT coalesce(jsonb_agg(to_jsonb(f) ORDER BY f.id),'[]') FROM selected_sales f),
   'companySettlement',(SELECT coalesce(jsonb_agg(to_jsonb(f) ORDER BY f.id),'[]') FROM ledger.sales_fact f
     JOIN core.fact_provenance provenance ON provenance.id=f.provenance_id AND provenance.ingestion_time<=p_at
     WHERE s.stage='SETTLED' AND f.organization_id=s.organization_id AND f.sale_stage='SETTLED'
       AND NOT EXISTS(SELECT 1 FROM ledger.sales_fact newer JOIN core.fact_provenance source ON source.id=newer.provenance_id
         WHERE newer.supersedes_fact_id=f.id AND source.ingestion_time<=p_at)
       AND EXISTS(SELECT 1 FROM selected_sales r WHERE r.platform_listing_variant_id=f.platform_listing_variant_id
         AND r.native_order_key=f.native_order_key AND r.native_line_key IS NOT DISTINCT FROM f.native_line_key)),
   'attribution',(SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.id),'[]') FROM ledger.ad_settlement_attribution a
     WHERE s.stage='SETTLED' AND a.organization_id=s.organization_id AND a.accepted_at<=p_at
       AND a.ad_linked_sale_event_id IN(SELECT id FROM selected_linked)),
   'companyCoverage',(SELECT coalesce(jsonb_agg(to_jsonb(q)||jsonb_build_object('consumedSourcesAdmissible',
     CASE s.stage WHEN 'OPERATIONAL' THEN coalesce(q.completed_source_updated_at<=p_at,false)
       WHEN 'RETAINED' THEN coalesce(q.retained_source_updated_at<=p_at,false) AND coalesce(q.return_source_updated_at<=p_at,false)
       ELSE coalesce(q.retained_source_updated_at<=p_at,false) AND coalesce(q.return_source_updated_at<=p_at,false)
         AND coalesce(q.qc_source_updated_at<=p_at,false) END) ORDER BY q.id),'[]') FROM ledger.return_quality_evidence_snapshot q
     WHERE q.organization_id=s.organization_id AND q.platform_listing_variant_id=ANY(s.listing_variant_ids)
       AND q.accepted_at<=p_at AND q.report_window_start<=s.window_starts_at AND q.report_window_end>=s.window_ends_at
       AND NOT EXISTS(SELECT 1 FROM ledger.return_quality_evidence_snapshot newer WHERE newer.supersedes_snapshot_id=q.id AND newer.accepted_at<=p_at)),
   'health',(SELECT coalesce(jsonb_agg(to_jsonb(h) ORDER BY h.id),'[]') FROM health h
     WHERE h.observed_at BETWEEN s.window_starts_at AND s.window_ends_at
       OR h.observed_at=(SELECT max(prior.observed_at) FROM health prior WHERE prior.platform_listing_variant_id=h.platform_listing_variant_id AND prior.observed_at<=s.window_starts_at)
       OR h.observed_at=(SELECT max(present.observed_at) FROM health present WHERE present.platform_listing_variant_id=h.platform_listing_variant_id)),
   'stock',(SELECT coalesce(jsonb_agg(to_jsonb(h) ORDER BY h.id),'[]') FROM stock h
     WHERE h.observed_at BETWEEN s.window_starts_at AND s.window_ends_at
       OR h.observed_at=(SELECT max(prior.observed_at) FROM stock prior WHERE prior.platform_listing_variant_id=h.platform_listing_variant_id AND prior.fulfillment_mode_code=h.fulfillment_mode_code AND prior.observed_at<=s.window_starts_at)
       OR h.observed_at=(SELECT max(present.observed_at) FROM stock present WHERE present.platform_listing_variant_id=h.platform_listing_variant_id AND present.fulfillment_mode_code=h.fulfillment_mode_code)),
   'price',(SELECT coalesce(jsonb_agg(to_jsonb(h) ORDER BY h.id),'[]') FROM price h
     WHERE h.observed_at BETWEEN s.window_starts_at AND s.window_ends_at
       OR h.observed_at=(SELECT max(prior.observed_at) FROM price prior WHERE prior.platform_listing_variant_id=h.platform_listing_variant_id AND prior.observed_at<=s.window_starts_at)
       OR h.observed_at=(SELECT max(present.observed_at) FROM price present WHERE present.platform_listing_variant_id=h.platform_listing_variant_id)),
   'configuration',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.id),'[]') FROM config c
     WHERE c.observed_at BETWEEN s.window_starts_at AND s.window_ends_at
       OR c.observed_at=(SELECT max(prior.observed_at) FROM config prior WHERE prior.observed_at<=s.window_starts_at)
       OR c.observed_at=(SELECT max(present.observed_at) FROM config present)),
   'affectedSets',(SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.id),'[]') FROM core.ad_affected_set a
     WHERE a.organization_id=s.organization_id AND a.ad_native_object_id=s.ad_native_object_id AND a.resolved_at<=p_at AND a.created_at<=p_at
       AND (a.resolved_at>=s.window_starts_at OR a.id=s.affected_set_id
         OR a.resolved_at=(SELECT max(prior.resolved_at) FROM core.ad_affected_set prior
           WHERE prior.organization_id=s.organization_id AND prior.ad_native_object_id=s.ad_native_object_id AND prior.resolved_at<=s.window_starts_at AND prior.created_at<=p_at))),
   'mappings',(SELECT coalesce(jsonb_agg(to_jsonb(m) ORDER BY m.id),'[]') FROM core.listing_mapping m
     WHERE m.organization_id=s.organization_id AND m.platform_listing_variant_id=ANY(s.listing_variant_ids)
       AND m.created_at<=p_at AND m.effective_from<s.window_ends_at AND (m.effective_to IS NULL OR m.effective_to>s.window_starts_at)),
   'mappingConflicts',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.id),'[]') FROM core.mapping_conflict c
     WHERE c.organization_id=s.organization_id AND c.platform_listing_variant_id=ANY(s.listing_variant_ids)
       AND c.detected_at<=least(s.window_ends_at,p_at) AND (c.resolved_at IS NULL OR c.resolved_at>s.window_starts_at)),
   'metrics',(SELECT coalesce(jsonb_agg(to_jsonb(m)||jsonb_build_object('evaluationProof',to_jsonb(proof),'inputReferences',(
       SELECT coalesce(jsonb_agg(to_jsonb(ref) ORDER BY ref.id),'[]')
       FROM mart.metric_input_reference ref WHERE ref.metric_value_id=m.id)) ORDER BY m.id),'[]')
     FROM mart.metric_value m JOIN cost_cohorts cohort ON cohort.platform_listing_variant_id=m.subject_id
     CROSS JOIN LATERAL mart.metric_value_verification(m.id,p_at) proof
     WHERE m.organization_id=s.organization_id AND m.subject_kind='PLATFORM_LISTING_VARIANT'
       AND m.subject_id=ANY(s.listing_variant_ids) AND m.window_code=s.metric_window
       AND m.metric_code IN('UNIT_COST','PLATFORM_FEES_PER_UNIT','RETURN_LOSS_PER_UNIT','VARIABLE_TAX_PER_UNIT')
       AND m.computed_at<=p_at AND m.period_start<=cohort.cohort_from AND m.period_end>=cohort.cohort_to
       AND m.period_end<=p_at
       AND NOT EXISTS(SELECT 1 FROM mart.metric_value newer
         CROSS JOIN LATERAL mart.metric_value_verification(newer.id,p_at) newer_proof
         WHERE newer.organization_id=m.organization_id
         AND newer.subject_kind=m.subject_kind AND newer.subject_id=m.subject_id AND newer.window_code=m.window_code
         AND newer.metric_code=m.metric_code AND newer.computed_at<=p_at
         AND newer.period_start<=cohort.cohort_from AND newer.period_end>=cohort.cohort_to AND newer.period_end<=p_at
         AND (greatest(newer.computed_at,newer_proof.verified_at),newer.computed_at,newer.id)
             >(greatest(m.computed_at,proof.verified_at),m.computed_at,m.id))),
   'freshnessStates',(SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY to_jsonb(p)::text),'[]') FROM proof_states p)
  ) value FROM scope s
 ) SELECT encode(sha256(convert_to(value::text,'UTF8')),'hex') FROM states
$$;

CREATE FUNCTION ops.ad_outcome_manual_policy_resolution(p_proposal uuid, p_at timestamp with time zone) RETURNS TABLE(state text, policy_id uuid, policy_version integer)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'core', 'mart', 'pg_temp'
    AS $$
 WITH result AS (
  SELECT r.* FROM ops.ad_manual_proposal m JOIN mart.ad_case k ON k.id=m.case_id AND k.organization_id=m.organization_id
  JOIN core.ad_manual_policy p ON p.id=m.policy_id AND p.organization_id=m.organization_id
  CROSS JOIN LATERAL core.ad_outcome_bound_policy_resolution(m.organization_id,k.platform_code,k.store_id,
   m.intended_state->>'direction',k.cause_code,p_at,p.outcome_policy_id) r
  WHERE m.id=p_proposal AND k.superseded_at IS NULL
 ) SELECT * FROM result
 UNION ALL SELECT 'OUTCOME_POLICY_UNRESOLVED',NULL::uuid,NULL::integer WHERE NOT EXISTS(SELECT 1 FROM result)
$$;

CREATE FUNCTION ops.ad_outcome_observation_is_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
    RAISE EXCEPTION 'an outcome observation is a permanent record' USING ERRCODE = 'MO098';
END;
$$;

CREATE FUNCTION ops.ad_outcome_payload_digest(p_baseline jsonb, p_stages jsonb, p_units jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    SET "TimeZone" TO 'UTC'
    AS $$
 SELECT encode(sha256(convert_to(jsonb_build_object(
  'baseline',to_jsonb(jsonb_populate_record(NULL::ops.ad_outcome_baseline,p_baseline)),
  'stages',(SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY s.stage),'[]') FROM jsonb_populate_recordset(NULL::ops.ad_outcome_stage_baseline,p_stages) s),
  'units',(SELECT coalesce(jsonb_agg(to_jsonb(u) ORDER BY u.product_variant_id,u.listing_variant_id),'[]') FROM jsonb_populate_recordset(NULL::ops.ad_outcome_critical_unit,p_units) u)
 )::text,'UTF8')),'hex')
$$;

CREATE FUNCTION ops.ad_outcome_plan_snapshot(p_policy uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'core', 'pg_temp'
    AS $$
 SELECT jsonb_build_object('id',p.id,'version',p.policy_version,'operationalHours',p.completed_sales_guard_hours,
  'settledHours',greatest(720,p.settlement_window_hours),'observationStartsMinutes',p.observation_starts_minutes,
  'absoluteDelta',p.material_profit_delta,'perRubDelta',p.material_profit_per_rub_delta,
  'salesTolerance',p.sales_preservation_tolerance_ratio,'minimumCoverage',p.minimum_settled_coverage_ratio,
  'minimumTraffic',p.minimum_traffic_count,'criticalDefinitionComplete',p.critical_unit_definition_complete,
  'absoluteNonWorseningBand',p.non_worsening_profit_band,'perRubNonWorseningBand',p.non_worsening_per_rub_band,
  'minimumAdSpend',p.minimum_ad_spend_denominator,'comparisonScale',p.comparison_scale,
  'roundingMode',p.comparison_rounding_mode,'boundaryInclusive',p.material_boundary_inclusive,
  'negativeProfitTerminal',p.negative_profit_terminal)
 FROM core.ad_outcome_policy p WHERE p.id=p_policy
$$;

CREATE FUNCTION ops.ad_outcome_stored_payload_digest(p_baseline uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    SET "TimeZone" TO 'UTC'
    AS $$
 SELECT ops.ad_outcome_payload_digest(to_jsonb(b),
  (SELECT coalesce(jsonb_agg(to_jsonb(s)),'[]') FROM ops.ad_outcome_stage_baseline s WHERE s.outcome_baseline_id=b.id),
  (SELECT coalesce(jsonb_agg(to_jsonb(u)),'[]') FROM ops.ad_outcome_critical_unit u WHERE u.outcome_baseline_id=b.id))
 FROM ops.ad_outcome_baseline b WHERE b.id=p_baseline
$$;

CREATE FUNCTION ops.ad_overlapping_reservation(p_organization_id uuid, p_variant_ids uuid[], p_exclude_object uuid) RETURNS TABLE(reservation_id uuid, lane text, intervention_kind text)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
    SELECT r.id, r.lane, r.intervention_kind
      FROM ops.ad_action_reservation AS r
     WHERE r.organization_id = p_organization_id
       AND r.state = 'ACTIVE'
       AND (p_exclude_object IS NULL OR r.ad_native_object_id <> p_exclude_object)
       AND r.product_variant_ids && p_variant_ids
     ORDER BY CASE r.lane WHEN 'PROTECTION' THEN 0 WHEN 'DATA_REPAIR' THEN 1
                          WHEN 'OPTIMIZATION' THEN 2 ELSE 3 END,
              r.reserved_at
$$;

CREATE FUNCTION ops.ad_protection_outcome_invalidated(p_observation uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
 SELECT EXISTS(SELECT 1 FROM ops.ad_outcome_observation o JOIN ops.ad_outcome_axes current ON current.observation_id=o.id
   JOIN LATERAL (
     -- The immediately preceding applicable result can be a revision of this
     -- stage or a completed shorter stage of the same frozen action window.
     -- Selecting before testing terminal state prevents repeated reopenings
     -- from an older terminal after responsibility is already active again.
     SELECT prior.business_outcome,previous.id=o.supersedes_observation_id same_window_revision
     FROM ops.ad_outcome_observation previous
     JOIN ops.ad_outcome_axes prior ON prior.observation_id=previous.id
       AND prior.outcome_baseline_id=current.outcome_baseline_id
     WHERE previous.id<>o.id AND previous.command_id IS NOT DISTINCT FROM o.command_id
       AND previous.manual_packet_id IS NOT DISTINCT FROM o.manual_packet_id
       AND previous.ad_native_object_id=o.ad_native_object_id AND previous.affected_set_digest=o.affected_set_digest
       AND previous.window_starts_at=o.window_starts_at AND previous.window_ends_at<=o.window_ends_at
       AND previous.evaluated_at<=o.evaluated_at
       AND NOT EXISTS(SELECT 1 FROM ops.ad_outcome_observation newer
         WHERE newer.supersedes_observation_id=previous.id AND newer.id<>o.id)
     ORDER BY previous.evaluated_at DESC,previous.window_ends_at DESC,previous.revision_no DESC,previous.id DESC LIMIT 1
   ) prior ON true
   WHERE o.id=p_observation
     AND prior.business_outcome IN('VERIFIED_AD_RISK_CLEARED','VERIFIED_AD_EXPOSURE_STOPPED')
     AND current.business_outcome IN('PROTECTION_IN_PROGRESS','OUTCOME_PENDING','OUTCOME_CONFOUNDED','IMPROVED_NOT_HEALTHY')
     AND (prior.same_window_revision OR (
       -- A longer stage with unknown inputs cannot invalidate a lawful result
       -- for the earlier window. Cross-stage recurrence needs observed harm.
       current.input_snapshot#>>'{observation,protectionEvidence,exactAffectedScope}'='true'
       AND ((prior.business_outcome='VERIFIED_AD_EXPOSURE_STOPPED'
         AND current.input_snapshot#>>'{observation,officialSpend,valueState}'='AVAILABLE'
         AND current.input_snapshot#>>'{observation,officialSpend,evidenceState}'='CANONICAL_CONFIRMED'
         AND (current.input_snapshot#>>'{observation,officialSpend,value}')::numeric>0)
       OR (prior.business_outcome='VERIFIED_AD_RISK_CLEARED' AND (
         (current.input_snapshot#>>'{baseline,originalCause}' IN('PROMOTED_VARIANT_NOT_SELLABLE','PROMOTED_VARIANT_UNAVAILABLE')
          AND current.input_snapshot#>>ARRAY['observation','protectionEvidence',
             CASE current.input_snapshot#>>'{baseline,originalCause}' WHEN 'PROMOTED_VARIANT_NOT_SELLABLE' THEN 'sellabilityCleared' ELSE 'availabilityCleared' END]='false'
          AND current.input_snapshot#>>ARRAY['observation','protectionEvidence',
             CASE current.input_snapshot#>>'{baseline,originalCause}' WHEN 'PROMOTED_VARIANT_NOT_SELLABLE' THEN 'sellabilityWindowComplete' ELSE 'availabilityWindowComplete' END]='true'
          AND EXISTS(SELECT 1 FROM jsonb_array_elements(current.input_snapshot#>'{observation,purposeEvidence}') proof
            WHERE proof->>'eligible'='true' AND proof->>'kind'=CASE current.input_snapshot#>>'{baseline,originalCause}'
              WHEN 'PROMOTED_VARIANT_NOT_SELLABLE' THEN 'SELLABILITY' ELSE 'AVAILABILITY' END))
         OR (current.input_snapshot#>>'{baseline,originalCause}'='PROVEN_ADVERTISING_LOSS'
          AND current.input_snapshot#>>'{observation,profit,absoluteProfit,valueState}'='AVAILABLE'
          AND current.input_snapshot#>>'{observation,profit,absoluteProfit,evidenceState}'='CANONICAL_CONFIRMED'
          AND (current.input_snapshot#>>'{observation,profit,absoluteProfit,value}')::numeric<0))))))
     AND NOT EXISTS(SELECT 1 FROM ops.ad_outcome_observation next WHERE next.supersedes_observation_id=o.id))
$$;

CREATE FUNCTION ops.ad_request_acceptance_bounds() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN
    NEW.latest_fact_accepted_at:=coalesce(NEW.latest_fact_accepted_at,NEW.fact_accepted_at);RETURN NEW;
END $$;

CREATE FUNCTION ops.ad_required_action_evidence_kinds(p_basis text, p_cause text) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
 SELECT CASE WHEN p_basis='MAX_CPC_BOUNDED' THEN ARRAY['OFFICIAL_AD_SPEND','OFFICIAL_AD_TRAFFIC',
   'AD_LINKED_SALE_EVENT','COST_AND_FEE','AD_OBJECT_CONFIGURATION','AFFECTED_SET']
 WHEN p_basis='CAUSE_BOUND_PROTECTION_STEP' AND p_cause='PROMOTED_VARIANT_NOT_SELLABLE'
 THEN ARRAY['OFFICIAL_AD_SPEND','AD_OBJECT_CONFIGURATION','AFFECTED_SET','SELLABILITY']
 WHEN p_basis='CAUSE_BOUND_PROTECTION_STEP' AND p_cause='PROMOTED_VARIANT_UNAVAILABLE'
 THEN ARRAY['OFFICIAL_AD_SPEND','AD_OBJECT_CONFIGURATION','AFFECTED_SET','AVAILABILITY']
 WHEN p_basis='CAUSE_BOUND_PROTECTION_STEP' AND p_cause='PROVEN_ADVERTISING_LOSS'
 THEN ARRAY['OFFICIAL_AD_SPEND','AD_OBJECT_CONFIGURATION','AFFECTED_SET','AD_LINKED_SALE_EVENT','COST_AND_FEE','SELLABILITY','AVAILABILITY'] END
$$;

CREATE FUNCTION ops.ad_settled_review_context(p_observation uuid) RETURNS TABLE(organization_id uuid, case_id uuid, ad_native_object_id uuid, store_id uuid, outcome_baseline_id uuid, affected_set_digest text, product_variant_ids uuid[], action_id uuid, action_kind text, primary_task_id uuid, recommendation_id uuid, observed_at timestamp with time zone, reason_code text, correlation_id text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'mart', 'pg_temp'
    AS $$
 SELECT o.organization_id,k.id,k.ad_native_object_id,k.store_id,b.id,b.affected_set_digest,b.product_variant_ids,
    coalesce(o.command_id,o.manual_packet_id),CASE WHEN o.command_id IS NULL THEN 'MANUAL_PACKET' ELSE 'COMMAND' END,
    responsibility.task_id,responsibility.recommendation_id,o.evaluated_at,
    CASE WHEN o.verdict='REGRESSED' THEN 'SETTLED_REGRESSION' ELSE 'SETTLED_CONTRADICTS_OPERATIONAL_SUCCESS' END,
    o.correlation_id
 FROM ops.ad_outcome_observation o JOIN ops.ad_outcome_axes axes ON axes.observation_id=o.id
 JOIN ops.ad_outcome_baseline b ON b.id=axes.outcome_baseline_id AND b.organization_id=o.organization_id
 LEFT JOIN ops.ad_bid_command command ON command.id=o.command_id AND command.outcome_baseline_id=b.id
 LEFT JOIN ops.ad_manual_execution_packet packet ON packet.id=o.manual_packet_id AND packet.outcome_baseline_id=b.id
 LEFT JOIN ops.ad_bid_candidate candidate ON candidate.id=b.candidate_id
 LEFT JOIN ops.ad_manual_proposal proposal ON proposal.id=b.manual_proposal_id
 JOIN mart.ad_case k ON k.id=coalesce(candidate.case_id,proposal.case_id) AND k.organization_id=o.organization_id
 JOIN ops.ad_case_responsibility responsibility ON responsibility.case_id=k.id
 WHERE o.id=p_observation AND o.outcome_stage IN('SETTLED','SETTLED_REVISED')
   AND (command.id IS NOT NULL OR packet.id IS NOT NULL)
   AND b.ad_native_object_id=o.ad_native_object_id AND b.affected_set_digest=o.affected_set_digest
   AND ops.ad_outcome_baseline_is_attested(b.id)
   AND NOT EXISTS(SELECT 1 FROM ops.ad_outcome_observation next WHERE next.supersedes_observation_id=o.id)
   AND (o.verdict='REGRESSED' OR (
      o.verdict='UNCHANGED' AND axes.dual_axis_verdict='NO_MATERIAL_IMPROVEMENT'
      AND EXISTS(SELECT 1 FROM ops.ad_outcome_observation operational
       JOIN ops.ad_outcome_axes operational_axes ON operational_axes.observation_id=operational.id
       WHERE operational.command_id IS NOT DISTINCT FROM o.command_id
         AND operational.manual_packet_id IS NOT DISTINCT FROM o.manual_packet_id
         AND operational_axes.outcome_baseline_id=b.id
         AND operational.outcome_stage IN('RETAINED','RETAINED_REVISED')
         AND operational.evaluated_at<=o.evaluated_at AND operational.verdict='IMPROVED'
         AND operational_axes.dual_axis_verdict='VERIFIED_EFFICIENCY_SUCCESS'
         AND NOT EXISTS(SELECT 1 FROM ops.ad_outcome_observation next WHERE next.supersedes_observation_id=operational.id))))
$$;

CREATE FUNCTION ops.apply_ad_manual_observation(p_observation uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE packet ops.ad_manual_execution_packet%ROWTYPE; evidence ops.ad_manual_configuration_verification%ROWTYPE;
 current ops.ad_manual_configuration_verification%ROWTYPE; proven boolean;
BEGIN
 SELECT * INTO evidence FROM ops.ad_manual_configuration_verification WHERE id=p_observation;
 SELECT * INTO packet FROM ops.ad_manual_execution_packet WHERE id=evidence.packet_id;
 PERFORM pg_advisory_xact_lock(hashtext('ad_action_reservation'),hashtext(packet.organization_id::text));
 SELECT * INTO packet FROM ops.ad_manual_execution_packet WHERE id=evidence.packet_id FOR UPDATE;
 SELECT * INTO current FROM ops.ad_manual_configuration_verification WHERE id=packet.current_proof_id
   AND ops.ad_manual_observation_is_qualified(id);
 IF current.id IS NOT NULL AND (evidence.observed_at<current.observed_at
   OR evidence.observed_at=current.observed_at AND evidence.evidence_grade='UNVERIFIED_MANUAL_EVIDENCE') THEN
  -- The new row is retained, with its true weaker grade. Only revision metadata
  -- advances; the newer current proof and reservation remain unchanged.
  UPDATE ops.ad_manual_execution_packet SET updated_at=evidence.recorded_at,version=version+1 WHERE id=packet.id;
  RETURN;
 END IF;
 proven:=ops.ad_manual_observation_is_qualified(evidence.id);
 UPDATE ops.ad_manual_execution_packet SET state=CASE WHEN proven THEN 'MANUAL_CONFIGURATION_VERIFIED'
   WHEN evidence.conflict_state<>'NONE' THEN 'MANUAL_EXECUTION_UNCERTAIN' ELSE 'ACTION_REPORTED_CONFIGURATION_UNVERIFIED' END,
   current_proof_id=CASE WHEN proven THEN evidence.id ELSE NULL END,updated_at=evidence.recorded_at,version=version+1
   WHERE id=packet.id;
 PERFORM ops.reconcile_ad_manual_configuration_reservation(packet.id,'manual-observation:'||evidence.id);
END $$;

CREATE FUNCTION ops.approve_ad_compensation(p_preview uuid, p_proof text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'iam', 'pg_temp'
    AS $$
DECLARE a ops.ad_compensation_authorization%ROWTYPE; c ops.ad_bid_command%ROWTYPE; g iam.ad_invocation_grant%ROWTYPE;
 b ops.ad_decision_policy_bundle%ROWTYPE; lifetime integer; authority_end timestamptz; credential_end timestamptz;
BEGIN
 SELECT * INTO a FROM ops.ad_compensation_authorization WHERE id=p_preview FOR UPDATE;
 g:=ops.consume_ad_control_invocation(p_proof,'COMPENSATION_APPROVE',a.command_id,p_preview);
 SELECT * INTO c FROM ops.ad_bid_command WHERE id=a.command_id;
 SELECT * INTO b FROM ops.ad_decision_policy_bundle WHERE id=a.bundle_id;
 SELECT material_lease_seconds INTO lifetime FROM core.ad_approval_lease_policy WHERE id=b.approval_lease_policy_id;
 IF a.owner_user_id IS NOT NULL OR a.endorser_user_id IS NULL OR a.preview_expires_at<=clock_timestamp()
 OR g.actor_user_id IN(a.maker_user_id,a.endorser_user_id)
 OR NOT ops.ad_actor_has_role_scope(g.actor_user_id,a.organization_id,c.store_id,'OWNER','AD_BID_CHANGE_APPROVE')
 OR NOT ops.ad_actor_covers_affected_set(g.actor_user_id,c.organization_id,
   (SELECT affected_set_id FROM ops.ad_action_reservation WHERE id=c.reservation_id),'AD_BID_CHANGE_APPROVE')
 OR NOT ops.ad_actor_has_role_scope(a.endorser_user_id,a.organization_id,c.store_id,'OPS_LEAD','AD_BID_CHANGE_ENDORSE')
 OR NOT ops.ad_actor_covers_affected_set(a.endorser_user_id,c.organization_id,
   (SELECT affected_set_id FROM ops.ad_action_reservation WHERE id=c.reservation_id),'AD_BID_CHANGE_ENDORSE')
 OR a.preview_snapshot IS DISTINCT FROM ops.ad_bundle_authority_snapshot(a.bundle_id) THEN
  RAISE EXCEPTION 'new distinct scoped Owner approval required' USING ERRCODE='MO094'; END IF;
 SELECT min((value->>'effective_to')::timestamptz) INTO authority_end
 FROM jsonb_each(a.preview_snapshot) WHERE jsonb_typeof(value)='object';
 SELECT min(ops.ad_credential_authority_expiry(credential.id,c.store_id)) INTO credential_end
 FROM platform.credential_metadata credential WHERE credential.marketplace_account_id=b.marketplace_account_id
 AND credential.organization_id=c.organization_id AND credential.purpose_code='ADS_WRITE' AND credential.status='ACTIVE';
 IF credential_end IS NULL OR credential_end<=clock_timestamp() OR lifetime IS NULL THEN
  RAISE EXCEPTION 'finite current compensation authorities required' USING ERRCODE='MO094'; END IF;
 UPDATE ops.ad_compensation_authorization SET owner_user_id=g.actor_user_id,approved_at=clock_timestamp(),
 expires_at=least(a.preview_expires_at,clock_timestamp()+make_interval(secs=>lifetime),
   authority_end,credential_end,
   (SELECT min(effective_to) FROM iam.user_scope_grant WHERE user_id IN(g.actor_user_id,a.endorser_user_id)
    AND action_code IN('AD_BID_CHANGE_APPROVE','AD_BID_CHANGE_ENDORSE') AND status='ACTIVE'),
   (SELECT valid_until FROM ops.ad_gate_authority WHERE id=b.gate_authority_id)) WHERE id=p_preview;
 IF cardinality(ops.evaluate_ad_bid_compensation_gate(c.id))>0 THEN
  RAISE EXCEPTION 'exact compensation gate refuses' USING ERRCODE='MO094'; END IF;
 UPDATE ops.ad_bid_command SET state='COMPENSATION_PENDING',terminal_at=NULL,lease_owner=NULL,
 lease_expires_at=NULL,updated_at=clock_timestamp() WHERE id=c.id;
END $$;

CREATE FUNCTION ops.attest_ad_containment(p_id uuid, p_condition text, p_evidence text, p_proof text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'iam', 'pg_temp'
    AS $$
DECLARE q ops.ad_containment%ROWTYPE; g iam.ad_invocation_grant%ROWTYPE; permitted boolean;
BEGIN
 SELECT * INTO q FROM ops.ad_containment WHERE id=p_id FOR UPDATE;
 g:=ops.consume_ad_control_invocation(p_proof,
 CASE WHEN p_condition='OPERATIONS_ENDORSEMENT' THEN 'CONTAINMENT_ENDORSE' ELSE 'CONTAINMENT_ATTEST' END,p_id,p_id);
 permitted:=CASE WHEN q.scope_kind='AUTHORITY_VERSION' THEN
 ops.ad_actor_has_organization_role_scope(g.actor_user_id,q.organization_id,
   CASE WHEN p_condition='SECURITY_ATTESTATION_PRESENT' THEN 'TECH_DATA' ELSE 'OPS_LEAD' END,
   CASE WHEN p_condition='SECURITY_ATTESTATION_PRESENT' THEN 'ADVERTISING_TECHNICAL_ATTEST' ELSE 'ADVERTISING_POLICY_MANAGE' END)
 WHEN p_condition='SECURITY_ATTESTATION_PRESENT' THEN
 ops.ad_actor_has_role_scope(g.actor_user_id,q.organization_id,q.store_id,'TECH_DATA','ADVERTISING_TECHNICAL_ATTEST')
 ELSE ops.ad_actor_has_role_scope(g.actor_user_id,q.organization_id,q.store_id,'OPS_LEAD','ADVERTISING_POLICY_MANAGE') END;
 IF q.id IS NULL OR g.organization_id<>q.organization_id OR q.state='REENABLED' OR NOT permitted OR p_evidence IS NULL OR length(btrim(p_evidence))<1
 OR p_condition='OPERATIONS_ENDORSEMENT' AND g.actor_user_id=q.activated_by_user_id THEN
  RAISE EXCEPTION 'independent scoped evidence attestation required' USING ERRCODE='MO097'; END IF;
 INSERT INTO ops.ad_containment_attestation(containment_id,condition,actor_user_id,evidence_reference)
 VALUES(p_id,p_condition,g.actor_user_id,p_evidence);
 UPDATE ops.ad_containment SET state='REENABLEMENT_REVIEW',updated_at=clock_timestamp(),version=version+1 WHERE id=p_id;
END $$;

CREATE FUNCTION ops.attest_lc_containment(p_id uuid, p_containment uuid, p_actor uuid, p_proof text, p_kind text, p_evidence text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'iam', 'pg_temp'
    AS $$
DECLARE containment ops.lc_containment%ROWTYPE; purpose text; action text; grant_row iam.ad_invocation_grant%ROWTYPE; scope_store uuid;
BEGIN
    SELECT * INTO containment FROM ops.lc_containment WHERE id = p_containment FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'containment does not exist' USING ERRCODE = 'MO090'; END IF;
    IF containment.state <> 'ACTIVE' THEN
        RAISE EXCEPTION 'only an active containment is attested' USING ERRCODE = 'MO091';
    END IF;
    IF p_kind = 'REPAIR_ATTESTATION' THEN
        purpose := 'LISTING_CONTAINMENT_ATTEST'; action := 'LISTING_CONTAINMENT_ATTEST';
    ELSIF p_kind = 'BUSINESS_CONSENT' THEN
        purpose := 'LISTING_CONTAINMENT_CONSENT'; action := 'LISTING_CONTAINMENT_CONSENT';
    ELSE
        RAISE EXCEPTION 'unknown attestation kind' USING ERRCODE = 'MO092';
    END IF;
    grant_row:=ops.consume_ad_control_invocation(p_proof, purpose, p_containment, p_containment);
    IF grant_row.actor_user_id<>p_actor OR grant_row.organization_id<>containment.organization_id THEN
        RAISE EXCEPTION 'attester must match the authenticated invocation' USING ERRCODE='MO092';
    END IF;
    scope_store:=coalesce(containment.store_id,
        (SELECT store_id FROM core.platform_listing WHERE id=containment.platform_listing_id),
        (SELECT store_id FROM ops.lc_batch WHERE id=containment.batch_id));
    IF NOT ops.lc_current_containment_authority(p_actor,containment.organization_id,scope_store,action) THEN
        RAISE EXCEPTION 'current attestation authority required' USING ERRCODE='MO092';
    END IF;
    -- The repair attestation comes from the cause owner's role; the consent
    -- from the business owner. One person cannot give both.
    IF p_kind = 'REPAIR_ATTESTATION' AND NOT EXISTS (
        SELECT 1 FROM iam.user_role_assignment r
         WHERE r.user_id = p_actor AND r.organization_id=containment.organization_id AND r.role_code = containment.cause_owner_role_code AND r.status = 'ACTIVE'
           AND r.effective_from<=statement_timestamp() AND (r.effective_to IS NULL OR r.effective_to>statement_timestamp())) THEN
        RAISE EXCEPTION 'the repair attestation comes from the cause owner role' USING ERRCODE = 'MO092';
    END IF;
    IF EXISTS (SELECT 1 FROM ops.lc_containment_attestation a
                WHERE a.containment_id = p_containment AND a.actor_user_id = p_actor) THEN
        RAISE EXCEPTION 'one person cannot give both halves of a reenablement' USING ERRCODE = 'MO092';
    END IF;
    INSERT INTO ops.lc_containment_attestation (id, containment_id, attestation_kind, actor_user_id,
        evidence_reference, attested_at)
    VALUES (p_id, p_containment, p_kind, p_actor, p_evidence, clock_timestamp());
    RETURN p_id;
END;
$$;

CREATE TABLE ops.diagnostic_export (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    store_id uuid NOT NULL,
    requester_id uuid NOT NULL,
    window_code text NOT NULL,
    request_key_hash text NOT NULL,
    state text NOT NULL,
    created_at timestamp with time zone DEFAULT statement_timestamp() NOT NULL,
    deadline_at timestamp with time zone DEFAULT (statement_timestamp() + '00:15:00'::interval) NOT NULL,
    next_attempt_at timestamp with time zone DEFAULT statement_timestamp() NOT NULL,
    snapshot_at timestamp with time zone,
    expires_at timestamp with time zone,
    lease_token uuid,
    lease_until timestamp with time zone,
    attempt_count integer DEFAULT 0 NOT NULL,
    row_count integer DEFAULT 0 NOT NULL,
    byte_length bigint DEFAULT 0 NOT NULL,
    manifest jsonb,
    manifest_sha256 text,
    failure_code text,
    CONSTRAINT diagnostic_export_attempt_count_check CHECK (((attempt_count >= 0) AND (attempt_count <= 5))),
    CONSTRAINT diagnostic_export_byte_length_check CHECK (((byte_length >= 0) AND (byte_length <= 268435456))),
    CONSTRAINT diagnostic_export_check CHECK (((state = 'RUNNING'::text) = ((lease_token IS NOT NULL) AND (lease_until IS NOT NULL)))),
    CONSTRAINT diagnostic_export_check1 CHECK (((state = ANY (ARRAY['SUCCEEDED'::text, 'EXPIRED'::text])) = ((manifest IS NOT NULL) AND (manifest_sha256 IS NOT NULL) AND (expires_at IS NOT NULL)))),
    CONSTRAINT diagnostic_export_failure_code_check CHECK ((failure_code = ANY (ARRAY['AUTHORIZATION_REVOKED'::text, 'LIMIT_EXCEEDED'::text, 'STORAGE_UNAVAILABLE'::text, 'DATABASE_UNAVAILABLE'::text, 'INVALID_SNAPSHOT'::text, 'DEADLINE_EXCEEDED'::text, 'RETRY_EXHAUSTED'::text]))),
    CONSTRAINT diagnostic_export_manifest_sha256_check CHECK ((manifest_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT diagnostic_export_request_key_hash_check CHECK ((request_key_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT diagnostic_export_row_count_check CHECK (((row_count >= 0) AND (row_count <= 1000000))),
    CONSTRAINT diagnostic_export_state_check CHECK ((state = ANY (ARRAY['QUEUED'::text, 'RUNNING'::text, 'SUCCEEDED'::text, 'FAILED'::text, 'EXPIRED'::text]))),
    CONSTRAINT diagnostic_export_window_code_check CHECK ((window_code = ANY (ARRAY['D7'::text, 'D14'::text, 'D30'::text])))
);

CREATE FUNCTION ops.audit_diagnostic_export(p_job ops.diagnostic_export, p_event text) RETURNS void
    LANGUAGE sql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
 INSERT INTO ops.metadata_audit_event(id,actor_type,actor_id,source_domain,action,entity_type,entity_id,change_summary,correlation_id)
 VALUES(gen_random_uuid(),'SYSTEM','diagnostic-export','analyticsdecision','STATUS_CHANGE','diagnostic-export',p_job.id,
   jsonb_build_object('event',p_event,'requesterId',p_job.requester_id,'state',p_job.state,
     'rowCount',p_job.row_count,'byteLength',p_job.byte_length,'failureCode',p_job.failure_code),p_job.id::text)
$$;

CREATE FUNCTION ops.authorize_diagnostic_export_read(p_id uuid, p_actor uuid, p_part integer, p_verified boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE j ops.diagnostic_export;
BEGIN
 SELECT * INTO j FROM ops.diagnostic_export WHERE id=p_id;
 IF NOT FOUND OR j.requester_id IS DISTINCT FROM p_actor OR NOT iam.diagnostic_export_allowed(p_actor,j.store_id) THEN
   RAISE EXCEPTION 'export scope denied' USING ERRCODE='MO064'; END IF;
 IF j.state<>'SUCCEEDED' OR j.expires_at<=statement_timestamp() THEN
   RAISE EXCEPTION 'export unavailable' USING ERRCODE='MO084'; END IF;
 IF p_part IS NULL OR p_part<0 OR p_verified IS NULL OR (p_part<>0 AND NOT EXISTS
   (SELECT 1 FROM ops.diagnostic_export_part WHERE export_id=p_id AND part_number=p_part)) THEN
   RAISE EXCEPTION 'invalid export part' USING ERRCODE='MO039'; END IF;
 PERFORM ops.audit_diagnostic_export(j,CASE WHEN p_part=0 THEN 'MANIFEST_AUTHORIZED'
   WHEN p_verified THEN 'PART_VERIFIED' ELSE 'PART_AUTHORIZED' END);
END $$;

CREATE FUNCTION ops.authorize_lc_promotion_exit(p_engagement uuid, p_actor uuid, p_proof text, p_reason_code text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'iam', 'pg_temp'
    AS $$
DECLARE engagement ops.lc_promotion_engagement%ROWTYPE;
BEGIN
    SELECT * INTO engagement FROM ops.lc_promotion_engagement WHERE id = p_engagement FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'engagement does not exist' USING ERRCODE = 'MO090'; END IF;
    IF engagement.state <> 'ACTIVE' THEN
        RAISE EXCEPTION 'only an active engagement is exited' USING ERRCODE = 'MO091';
    END IF;
    PERFORM ops.consume_ad_control_invocation(p_proof, 'LISTING_PROMOTION_EXIT', p_engagement, p_engagement);
    IF NOT ops.lc_actor_holds_action(p_actor, engagement.organization_id, engagement.store_id,
                                     'LISTING_PROMOTION_MANAGE') THEN
        RAISE EXCEPTION 'the actor cannot exit a promotion here' USING ERRCODE = 'MO092';
    END IF;
    UPDATE ops.lc_promotion_engagement
       SET exit_reason_code = p_reason_code, exit_authorized_by_user_id = p_actor,
           exit_authorized_at = clock_timestamp(), state = 'EXITING',
           updated_at = clock_timestamp(), version = version + 1
     WHERE id = p_engagement;
END;
$$;

CREATE FUNCTION ops.authorize_lc_promotion_exit(p_engagement uuid, p_actor uuid, p_proof text, p_reason_code text, p_authority_reference text, p_evidence_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'iam', 'pg_temp'
    AS $$
DECLARE engagement ops.lc_promotion_engagement%ROWTYPE; action ops.lc_action%ROWTYPE;
 grant_row iam.ad_invocation_grant%ROWTYPE; evidence jsonb; now_at timestamptz;
BEGIN
 SELECT * INTO engagement FROM ops.lc_promotion_engagement WHERE id=p_engagement FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'engagement does not exist' USING ERRCODE='MO090'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext('lc_exposure_organization'),hashtext(engagement.organization_id::text));
 now_at:=clock_timestamp();
 IF engagement.state<>'ACTIVE' THEN RAISE EXCEPTION 'only an active engagement is exited' USING ERRCODE='MO091'; END IF;
 IF p_reason_code NOT IN ('MARGIN_BELOW_BOUND','RETURN_RATE_ABOVE_BOUND','SUPPLY_COVERAGE_LOST',
      'PLATFORM_TERMS_CHANGED','OWNER_DECISION')
    OR length(btrim(coalesce(p_authority_reference,''))) NOT BETWEEN 1 AND 512
    OR engagement.obligations->>('exit.'||p_reason_code) IS DISTINCT FROM p_authority_reference THEN
   RAISE EXCEPTION 'exact reason-bound prior exit authority is required' USING ERRCODE='MO092';
 END IF;
 IF engagement.action_id IS NOT NULL THEN SELECT * INTO STRICT action FROM ops.lc_action WHERE id=engagement.action_id; END IF;
 IF p_reason_code='PLATFORM_TERMS_CHANGED' THEN
   SELECT jsonb_build_object('kind','COMPLETE_PROMOTION_CONTEXT','observationId',o.id,
      'contextDigest',o.context_digest,'observedTermsDigest',
      ops.lc_promotion_terms_digest(item.value->'declaration')) INTO evidence
   FROM core.lc_promotion_observation o
   JOIN core.fact_provenance provenance ON provenance.id=o.provenance_id
   CROSS JOIN LATERAL jsonb_array_elements(o.context_snapshot) item
   WHERE o.id=p_evidence_id AND o.organization_id=engagement.organization_id
     AND o.platform_listing_id=engagement.platform_listing_id
     AND ops.lc_promotion_observation_is_independent_current(o.id,now_at)
     AND o.coverage_from<=o.observed_at AND o.coverage_until>o.observed_at
     AND (provenance.source_kind<>'MANUAL_ENTRY' OR provenance.recorded_by_user_id<>p_actor)
     AND o.observed_at>=engagement.created_at
     AND item.value#>>'{declaration,engagementKind}'=engagement.engagement_kind
     AND item.value#>>'{declaration,nativePromotionKey}'=engagement.native_promotion_key
     AND ops.lc_promotion_terms_digest(item.value->'declaration')<>engagement.terms_digest;
 ELSIF p_reason_code='OWNER_DECISION' THEN
   IF NOT EXISTS(SELECT 1 FROM iam.user_role_assignment r WHERE r.user_id=p_actor
       AND r.organization_id=engagement.organization_id AND r.role_code='OWNER' AND r.status='ACTIVE'
       AND r.effective_from<=now_at AND (r.effective_to IS NULL OR r.effective_to>now_at)) THEN
     RAISE EXCEPTION 'current Owner authority is required for the frozen Owner exit option' USING ERRCODE='MO092';
   END IF;
   IF engagement.action_id IS NULL THEN
     IF engagement.adoption_qualification_state<>'QUALIFIED_CURRENT_STEWARDSHIP'
        OR engagement.original_authority_valid_until<=now_at OR p_evidence_id<>engagement.source_context_observation_id
        OR NOT ops.lc_actor_holds_action(engagement.responsible_user_id,engagement.organization_id,
             engagement.store_id,'LISTING_PROMOTION_MANAGE') THEN
       RAISE EXCEPTION 'adopted activity exit requires its still-applicable original authority' USING ERRCODE='MO092';
     END IF;
     evidence:=jsonb_build_object('kind','ADOPTED_ORIGINAL_AUTHORITY','observationId',p_evidence_id,
       'originalAuthorityReference',engagement.original_authority_reference);
   ELSE
     SELECT jsonb_build_object('kind','FROZEN_ACTION_APPROVAL','approvalDecisionId',d.id,
       'actionId',action.id,'promotionTermsDigest',action.promotion_terms_digest) INTO evidence
     FROM ops.lc_action_binding b JOIN ops.approval_decision d ON d.id=b.approval_decision_id
     WHERE b.action_id=action.id AND d.id=p_evidence_id AND d.decision='APPROVED'
       AND d.decided_at<=engagement.created_at AND action.promotion_terms_digest=engagement.terms_digest;
   END IF;
 ELSE
   IF engagement.action_id IS NULL THEN
     RAISE EXCEPTION 'adopted margin, return or supply deviation needs a governed forward Action' USING ERRCODE='MO092';
   END IF;
   SELECT jsonb_build_object('kind','CURRENT_GUARDRAIL_FAILURE','guardrailEvaluationId',g.id,
      'actionId',action.id,'reasonCode',p_reason_code,'evaluatedAt',g.evaluated_at) INTO evidence
   FROM ops.guardrail_evaluation g
   WHERE g.id=p_evidence_id AND g.organization_id=engagement.organization_id
     AND g.recommendation_id=action.recommendation_id AND g.evaluated_at>=engagement.created_at
     AND g.detail->>'actionId'=action.id::text AND CASE p_reason_code
       WHEN 'MARGIN_BELOW_BOUND' THEN g.detail->>'protectionRecheck.currentProfitVerdict'='FAIL'
       WHEN 'RETURN_RATE_ABOVE_BOUND' THEN g.detail->>'protectionRecheck.currentReturnVerdict'='FAIL'
       WHEN 'SUPPLY_COVERAGE_LOST' THEN g.detail->>'protectionRecheck.supplyVerdict'='FAIL' END;
 END IF;
 IF evidence IS NULL THEN RAISE EXCEPTION 'exit reason is not proven by the named exact evidence' USING ERRCODE='MO092'; END IF;
 IF NOT ops.lc_actor_holds_action(p_actor,engagement.organization_id,engagement.store_id,'LISTING_PROMOTION_MANAGE') THEN
   RAISE EXCEPTION 'current promotion management authority required' USING ERRCODE='MO092';
 END IF;
 grant_row:=ops.consume_ad_control_invocation(p_proof,'LISTING_PROMOTION_EXIT',p_engagement,p_engagement);
 IF grant_row.actor_user_id<>p_actor OR grant_row.organization_id<>engagement.organization_id THEN
   RAISE EXCEPTION 'exit actor must match the authenticated invocation' USING ERRCODE='MO092';
 END IF;
 UPDATE ops.lc_promotion_engagement SET exit_reason_code=p_reason_code,exit_authority_reference=p_authority_reference,
   exit_evidence_id=p_evidence_id,exit_evidence=evidence,exit_authorized_by_user_id=p_actor,
   exit_authorized_at=now_at,state='EXITING',updated_at=now_at,version=version+1 WHERE id=p_engagement;
END $$;

CREATE FUNCTION ops.bind_ad_bid_authority_snapshot() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'platform', 'pg_temp'
    AS $$
DECLARE snapshot jsonb;
BEGIN
    SELECT ops.ad_bid_authority_snapshot(NEW.recommendation_id) INTO snapshot;
    IF snapshot IS NULL OR snapshot #>> '{proposal,organizationId}'
            IS DISTINCT FROM NEW.organization_id::text THEN
        RAISE EXCEPTION 'recommendation ownership does not match' USING ERRCODE = 'MO092';
    END IF;
    NEW.authority_snapshot := snapshot;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.bind_ad_outcome_baseline() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
    IF NEW.direction = 'EXACT_PRIOR_BID_COMPENSATION' THEN RETURN NEW; END IF;
    SELECT p.id INTO NEW.outcome_baseline_id FROM ops.ad_outcome_baseline p
      JOIN ops.ad_action_authorization authority ON authority.outcome_baseline_id=p.id
        AND authority.recommendation_id=NEW.recommendation_id AND authority.candidate_id=NEW.candidate_id
        AND authority.expires_at>NEW.created_at
      JOIN ops.ad_bid_candidate candidate ON candidate.id = p.candidate_id
      JOIN mart.ad_case c ON c.id = candidate.case_id
      WHERE p.candidate_id = NEW.candidate_id AND p.organization_id = NEW.organization_id
        AND p.affected_set_digest = NEW.affected_set_digest AND p.state = 'COMPLETE'
        AND p.case_calculation_id = c.calculation_id AND p.policy_version_digest = c.policy_version_digest
        AND p.prepared_at <= NEW.created_at AND p.valid_until > NEW.created_at
        AND ops.ad_outcome_baseline_is_canonical(p.id,NEW.created_at)
;
    IF NEW.outcome_baseline_id IS NULL THEN
        RAISE EXCEPTION 'an exact complete frozen outcome baseline is required' USING ERRCODE = 'MO099';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.bind_lc_execution_task_event() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE receipt ops.lc_execution_receipt%ROWTYPE; recommendation uuid;
BEGIN
    IF NEW.event_kind<>'EXECUTION_OBSERVED' THEN RETURN NEW; END IF;
    SELECT * INTO receipt FROM ops.lc_execution_receipt
     WHERE 'lc-execution:'||id::text=NEW.evidence_reference;
    SELECT recommendation_id INTO recommendation FROM ops.lc_action WHERE id=receipt.action_id;
    IF receipt.id IS NULL OR receipt.organization_id IS DISTINCT FROM NEW.organization_id
        OR receipt.task_event_id IS NOT NULL OR NEW.occurred_at IS DISTINCT FROM receipt.recorded_at
        OR NEW.lineage_key IS DISTINCT FROM 'recommendation:'||recommendation::text
        OR NEW.reason IS DISTINCT FROM receipt.execution_state
        OR NOT EXISTS (SELECT 1 FROM ops.work_task t WHERE t.id=NEW.task_id
            AND t.organization_id=receipt.organization_id AND t.recommendation_id=recommendation) THEN
        RAISE EXCEPTION 'execution journal needs the exact receipt and responsibility Task' USING ERRCODE='MO093';
    END IF;
    NEW.execution_receipt_id:=receipt.id;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.bind_price_authority_snapshot() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE snapshot jsonb;
        evaluated_snapshot jsonb;
        decided_action text;
BEGIN
    SELECT r.action_kind INTO decided_action
      FROM ops.recommendation r WHERE r.id = NEW.recommendation_id;
    IF decided_action IS NULL THEN
        RAISE EXCEPTION 'decision names no recommendation' USING ERRCODE = 'MO032';
    END IF;

    IF decided_action IN ('LISTING_DESCRIPTION_CHANGE', 'LISTING_PROMOTION_ACTION') THEN
        SELECT ops.lc_authority_snapshot(NEW.recommendation_id) INTO snapshot;
        IF snapshot IS NULL OR snapshot #>> '{proposal,organizationId}'
                IS DISTINCT FROM NEW.organization_id::text THEN
            RAISE EXCEPTION 'recommendation ownership does not match' USING ERRCODE = 'MO032';
        END IF;
        IF TG_TABLE_NAME = 'guardrail_evaluation' THEN
            IF NEW.authority_snapshot IS DISTINCT FROM snapshot THEN
                RAISE EXCEPTION 'guardrail inputs changed' USING ERRCODE = 'MO032';
            END IF;
            IF NEW.outcome = 'PASS' AND (snapshot -> 'action') IS NULL THEN
                RAISE EXCEPTION 'a listing PASS names an exact action' USING ERRCODE = 'MO032';
            END IF;
        ELSIF TG_TABLE_NAME = 'approval_decision' THEN
            IF NEW.decision IN ('APPROVED', 'POLICY_AUTHORIZED') THEN
                IF NEW.decision = 'POLICY_AUTHORIZED' THEN
                    RAISE EXCEPTION 'a listing action is approved by a person' USING ERRCODE = 'MO032';
                END IF;
                IF NEW.entity_version_digest IS DISTINCT FROM snapshot ->> 'currentEntityDigest'
                   OR NOT EXISTS (
                       SELECT 1 FROM ops.guardrail_evaluation g
                        WHERE g.recommendation_id = NEW.recommendation_id
                          AND g.organization_id = NEW.organization_id
                          AND g.purpose = 'APPROVAL' AND g.outcome = 'PASS'
                          AND g.authority_snapshot = snapshot) THEN
                    RAISE EXCEPTION 'approval has no matching current guardrail authority'
                        USING ERRCODE = 'MO032';
                END IF;
                -- The person approving is not the person who wrote the action.
                IF NEW.decided_by_user_id IS NOT DISTINCT FROM (snapshot #>> '{action,authorUserId}')::uuid THEN
                    RAISE EXCEPTION 'the author of a listing action does not approve it'
                        USING ERRCODE = 'MO032';
                END IF;
            END IF;
            NEW.authority_snapshot := snapshot;
        ELSE
            NEW.authority_snapshot := snapshot;
        END IF;
        RETURN NEW;
    END IF;

    IF decided_action = 'AD_BID_CHANGE' THEN
        SELECT ops.ad_bid_authority_snapshot(NEW.recommendation_id) INTO snapshot;
        IF snapshot IS NULL OR snapshot #>> '{proposal,organizationId}'
                IS DISTINCT FROM NEW.organization_id::text THEN
            RAISE EXCEPTION 'recommendation ownership does not match' USING ERRCODE = 'MO032';
        END IF;
        IF TG_TABLE_NAME = 'guardrail_evaluation' THEN
            IF NEW.authority_snapshot IS DISTINCT FROM snapshot THEN
                RAISE EXCEPTION 'guardrail inputs changed' USING ERRCODE = 'MO032';
            END IF;
        ELSIF TG_TABLE_NAME = 'approval_decision' THEN
            IF NEW.decision IN ('APPROVED', 'POLICY_AUTHORIZED') THEN
                IF NEW.entity_version_digest IS DISTINCT FROM snapshot ->> 'currentEntityDigest'
                   OR NEW.entity_version_digest
                       IS DISTINCT FROM snapshot #>> '{proposal,entityDigest}'
                   OR NOT EXISTS (
                       SELECT 1 FROM ops.guardrail_evaluation g
                        WHERE g.recommendation_id = NEW.recommendation_id
                          AND g.organization_id = NEW.organization_id
                          AND g.purpose = 'APPROVAL' AND g.outcome = 'PASS'
                          AND g.authority_snapshot = snapshot) THEN
                    RAISE EXCEPTION 'approval has no matching current guardrail authority'
                        USING ERRCODE = 'MO032';
                END IF;
            END IF;
            NEW.authority_snapshot := snapshot;
        ELSE
            NEW.authority_snapshot := snapshot;
        END IF;
        RETURN NEW;
    END IF;

    SELECT ops.price_authority_snapshot(NEW.recommendation_id) INTO snapshot;
    IF snapshot IS NULL OR snapshot #>> '{proposal,organizationId}'
            IS DISTINCT FROM NEW.organization_id::text THEN
        RAISE EXCEPTION 'recommendation ownership does not match' USING ERRCODE = 'MO032';
    END IF;
    IF TG_TABLE_NAME = 'guardrail_evaluation' THEN
        SELECT ops.price_authority_snapshot(NEW.recommendation_id, NEW.evaluated_at)
          INTO evaluated_snapshot;
        IF NEW.authority_snapshot IS DISTINCT FROM evaluated_snapshot THEN
            RAISE EXCEPTION 'guardrail inputs do not match evaluation as-of authority'
                USING ERRCODE = 'MO032';
        END IF;
        IF NEW.outcome = 'PASS'
           AND (NEW.authority_snapshot IS DISTINCT FROM snapshot
                OR NOT ops.r2_price_authority_is_current(
                    NEW.authority_snapshot, statement_timestamp())) THEN
            RAISE EXCEPTION 'guardrail authority is stale or incomplete'
                USING ERRCODE = 'MO032';
        END IF;
    ELSIF TG_TABLE_NAME = 'approval_decision' THEN
        IF NEW.decision IN ('APPROVED', 'POLICY_AUTHORIZED') THEN
            IF NOT ops.r2_price_authority_is_current(snapshot, statement_timestamp())
               OR NEW.entity_version_digest IS DISTINCT FROM snapshot ->> 'currentEntityDigest'
               OR NEW.entity_version_digest IS DISTINCT FROM snapshot #>> '{proposal,entityDigest}'
               OR NOT EXISTS (
                   SELECT 1 FROM ops.guardrail_evaluation g
                    WHERE g.recommendation_id = NEW.recommendation_id
                      AND g.organization_id = NEW.organization_id
                      AND g.purpose = 'APPROVAL' AND g.outcome = 'PASS'
                      AND g.authority_snapshot = snapshot) THEN
                RAISE EXCEPTION 'approval has no matching current guardrail authority'
                    USING ERRCODE = 'MO032';
            END IF;
        END IF;
        NEW.authority_snapshot := snapshot;
    ELSE
        IF NOT ops.r2_price_authority_is_current(snapshot, statement_timestamp()) THEN
            RAISE EXCEPTION 'command authority is stale or incomplete'
                USING ERRCODE = 'MO032';
        END IF;
        NEW.authority_snapshot := snapshot;
        NEW.fulfillment_mode_code := snapshot #>> '{economics,fulfillmentModeCode}';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.capture_ad_bid_authority_snapshot(p_recommendation_id uuid) RETURNS TABLE(evaluation_as_of timestamp with time zone, authority_snapshot jsonb)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
    SELECT captured.at, ops.ad_bid_authority_snapshot(p_recommendation_id)
      FROM (SELECT statement_timestamp() AS at) captured
$$;

CREATE FUNCTION ops.capture_lc_action_calibration_dependencies() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='UPDATE' THEN
   IF NEW.calibration_dependencies IS DISTINCT FROM OLD.calibration_dependencies
     OR NEW.calibration_package_id IS DISTINCT FROM OLD.calibration_package_id
     OR NEW.calibration_version IS DISTINCT FROM OLD.calibration_version THEN
     RAISE EXCEPTION 'prepared rule dependencies and authority are immutable' USING ERRCODE='MO090';
   END IF;
 ELSE
   NEW.calibration_dependencies:=core.lc_action_calibration_dependencies(NEW.calibration_package_id,NEW.action_kind,NEW.affected_set_id);
 END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION ops.capture_price_authority_snapshot(p_recommendation_id uuid) RETURNS TABLE(evaluation_as_of timestamp with time zone, authority_snapshot jsonb)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
    SELECT captured.at,
           ops.price_authority_snapshot(p_recommendation_id, captured.at)
      FROM (SELECT statement_timestamp() AS at) captured
$$;

CREATE FUNCTION ops.claim_diagnostic_export() RETURNS SETOF ops.diagnostic_export
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE j ops.diagnostic_export;
BEGIN
 SELECT * INTO j FROM ops.diagnostic_export WHERE
   (state='QUEUED' OR (state='RUNNING' AND lease_until<=statement_timestamp()))
   AND next_attempt_at<=statement_timestamp() AND deadline_at>statement_timestamp() AND attempt_count<5
   ORDER BY created_at,id FOR UPDATE SKIP LOCKED LIMIT 1;
 IF NOT FOUND THEN RETURN; END IF;
 IF NOT iam.diagnostic_export_allowed(j.requester_id,j.store_id) THEN
   UPDATE ops.diagnostic_export SET state='FAILED',failure_code='AUTHORIZATION_REVOKED',lease_token=NULL,lease_until=NULL
     WHERE id=j.id RETURNING * INTO j;
   PERFORM ops.audit_diagnostic_export(j,'FAILED'); RETURN;
 END IF;
 UPDATE ops.diagnostic_export SET state='RUNNING',lease_token=gen_random_uuid(),
   lease_until=least(deadline_at,statement_timestamp()+interval '2 minutes'),attempt_count=attempt_count+1,failure_code=NULL
   WHERE id=j.id RETURNING * INTO j;
 PERFORM ops.audit_diagnostic_export(j,'CLAIMED'); RETURN NEXT j;
END $$;

CREATE FUNCTION ops.claim_ingestion_run(p_run_id uuid, p_lease_owner text, p_lease_seconds integer) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    run_row   record;
    new_fence bigint;
BEGIN
    IF p_lease_owner IS NULL OR length(btrim(p_lease_owner)) = 0 THEN
        RAISE EXCEPTION 'a lease owner is required' USING ERRCODE = 'MO040';
    END IF;
    IF p_lease_seconds IS NULL OR p_lease_seconds <= 0 OR p_lease_seconds > 3600 THEN
        RAISE EXCEPTION 'lease duration must be between 1 and 3600 seconds'
            USING ERRCODE = 'MO040';
    END IF;

    SELECT run.id, run.state, run.lease_expires_at, run.next_attempt_at, run.attempt_no, run.max_claims
      INTO run_row
      FROM ops.ingestion_run AS run
     WHERE run.id = p_run_id
       FOR UPDATE OF run;

    IF run_row.id IS NULL THEN
        RAISE EXCEPTION 'run % does not exist', p_run_id USING ERRCODE = 'MO040';
    END IF;

    IF NOT (run_row.state='QUEUED' OR (run_row.state='RETRY_WAIT' AND run_row.next_attempt_at <= clock_timestamp())
            OR (run_row.state IN ('LEASED', 'RUNNING')
                AND run_row.lease_expires_at <= clock_timestamp()))
    THEN
        RAISE EXCEPTION 'run % is not claimable from state %', p_run_id, run_row.state
            USING ERRCODE = 'MO040';
    END IF;

    -- A stopped worker consumes a claim too. Persist exhaustion without raising
    -- an exception, which would roll back the terminal recovery transition.
    IF run_row.attempt_no >= run_row.max_claims THEN
        UPDATE ops.ingestion_run SET state='FAILED_TERMINAL', failure_code='RETRY_BUDGET_EXHAUSTED',
            lease_owner=NULL, lease_expires_at=NULL, next_attempt_at=NULL, updated_at=clock_timestamp()
         WHERE id=p_run_id;
        RETURN NULL;
    END IF;

    UPDATE ops.ingestion_run AS run
       SET state = 'LEASED', next_attempt_at = NULL,
           fence_token = run.fence_token + 1,
           attempt_no = run.attempt_no + 1,
           lease_owner = p_lease_owner,
           lease_expires_at = clock_timestamp() + make_interval(secs => p_lease_seconds),
           updated_at = clock_timestamp()
     WHERE run.id = p_run_id
       AND run.state = run_row.state
    RETURNING run.fence_token INTO new_fence;

    IF new_fence IS NULL THEN
        RAISE EXCEPTION 'run % changed while being claimed', p_run_id
            USING ERRCODE = 'MO040';
    END IF;
    RETURN new_fence;
END;
$$;

CREATE FUNCTION ops.close_lc_late_association(p_association uuid, p_actor uuid, p_proof text, p_verification uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE association ops.lc_late_association%ROWTYPE; verification ops.lc_manual_verification%ROWTYPE;
 packet ops.lc_manual_packet%ROWTYPE; action ops.lc_action%ROWTYPE; observed core.lc_description_observation%ROWTYPE;
 management core.lc_description_observation%ROWTYPE; approval ops.approval_decision%ROWTYPE;
 grant_row iam.ad_invocation_grant%ROWTYPE; listing core.platform_listing%ROWTYPE; launch_at timestamptz;
 assessment jsonb; event_at timestamptz;
BEGIN
 SELECT * INTO association FROM ops.lc_late_association WHERE id=p_association FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'late association does not exist' USING ERRCODE='MO090'; END IF;
 IF association.state NOT IN ('OPEN','UNDER_VERIFICATION') THEN
   RAISE EXCEPTION 'only unresolved or unauthorised work is closed' USING ERRCODE='MO091';
 END IF;
 SELECT * INTO STRICT listing FROM core.platform_listing WHERE id=association.platform_listing_id
   AND organization_id=association.organization_id;
 grant_row:=ops.consume_ad_control_invocation(p_proof,'LISTING_MANUAL_VERIFY',p_association,p_association);
 IF grant_row.actor_user_id<>p_actor OR grant_row.organization_id<>association.organization_id
    OR NOT ops.lc_actor_holds_action(p_actor,association.organization_id,listing.store_id,'LISTING_MANUAL_VERIFY') THEN
   RAISE EXCEPTION 'closure actor must match a current exact-scope verifier invocation' USING ERRCODE='MO092';
 END IF;
 SELECT * INTO verification FROM ops.lc_manual_verification WHERE id=p_verification FOR UPDATE;
 IF verification.id IS NULL OR verification.organization_id<>association.organization_id
    OR verification.qualification_state<>'QUALIFIED' OR verification.management_match<>'MATCHED_TARGET'
    OR verification.verified_at<association.recorded_at THEN
   RAISE EXCEPTION 'a current qualified later verification is required' USING ERRCODE='MO092';
 END IF;
 SELECT * INTO STRICT packet FROM ops.lc_manual_packet WHERE id=verification.packet_id;
 SELECT * INTO STRICT action FROM ops.lc_action WHERE id=packet.action_id;
 SELECT * INTO STRICT observed FROM core.lc_description_observation WHERE id=association.observation_id;
 SELECT * INTO management FROM core.lc_description_observation WHERE id=verification.management_observation_id;
 IF action.organization_id<>association.organization_id OR action.platform_listing_id<>association.platform_listing_id
    OR action.action_kind<>'LISTING_DESCRIPTION_CHANGE' OR management.id IS NULL
    OR management.platform_listing_id<>association.platform_listing_id
    OR management.text_digest IS DISTINCT FROM observed.text_digest
    OR action.target_text_digest IS DISTINCT FROM observed.text_digest
    OR verification.observation_binding->>'actionId' IS DISTINCT FROM action.id::text
    OR verification.observation_binding->>'managementObservationId' IS DISTINCT FROM management.id::text THEN
   RAISE EXCEPTION 'verification does not resolve this exact Listing event and target' USING ERRCODE='MO092';
 END IF;
 event_at:=coalesce(association.operation_time,observed.observed_at);
 IF association.association_kind='UNAUTHORISED_DEVIATION' THEN
   SELECT d.* INTO approval FROM ops.lc_action_binding b JOIN ops.approval_decision d ON d.id=b.approval_decision_id
    WHERE b.action_id=action.id AND d.decision='APPROVED';
   SELECT l.launched_at INTO launch_at FROM ops.lc_launch l WHERE l.action_id=action.id;
   IF action.id IS NOT DISTINCT FROM association.action_id OR action.created_at<=event_at
      OR approval.id IS NULL OR approval.decided_at<=event_at OR launch_at IS NULL OR launch_at<=event_at THEN
     RAISE EXCEPTION 'an unauthorised deviation needs a distinct forward Action and approval' USING ERRCODE='MO092';
   END IF;
 ELSIF association.association_kind='UNRESOLVED_CHANGE' THEN
   IF association.action_id IS NOT NULL AND action.id<>association.action_id THEN
     RAISE EXCEPTION 'the verification belongs to another proposed association' USING ERRCODE='MO092';
   ELSIF association.action_id IS NULL AND action.created_at<=event_at THEN
     RAISE EXCEPTION 'an unassociated change needs a forward governed Action' USING ERRCODE='MO092';
   END IF;
 ELSE
   RAISE EXCEPTION 'a lawful late report is already linked and is not closed here' USING ERRCODE='MO091';
 END IF;
 assessment:=jsonb_build_object('qualification','QUALIFIED','associationId',association.id,
   'associationKind',association.association_kind,'eventObservationId',observed.id,
   'eventTextDigest',observed.text_digest,'resolutionActionId',action.id,
   'resolutionApprovalId',approval.id,'verificationId',verification.id,
   'managementObservationId',management.id,'verifiedAt',verification.verified_at,
   'resolvedAt',clock_timestamp());
 UPDATE ops.lc_late_association SET state='CLOSED',closure_verification_id=verification.id,
   closure_assessment=assessment,updated_at=clock_timestamp(),version=version+1 WHERE id=association.id;
END $$;

CREATE FUNCTION ops.complete_ad_bid_command_attempt(p_id uuid, p_fence bigint, p_owner text, p_outcome text, p_native_status text, p_task text, p_error text, p_content uuid, p_body bytea, p_http_status integer, p_headers jsonb, p_evidence_class text, p_request_digest text, p_response_complete boolean DEFAULT true) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'platform', 'raw', 'pg_temp'
    AS $_$
DECLARE
    attempt   ops.ad_bid_command_attempt%ROWTYPE;
    operation platform.capability_operation%ROWTYPE;
    document  jsonb;
    resolved  text;
    failure   text;
    observation_id uuid;
    observed_bid numeric(18, 4);
    observed_currency text;
    observed_unit text;
    native_task text;
BEGIN
    SELECT * INTO attempt FROM ops.ad_bid_command_attempt WHERE id = p_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'attempt does not exist' USING ERRCODE = 'MO090';
    END IF;
    IF attempt.fence_token <> p_fence OR attempt.lease_owner IS DISTINCT FROM p_owner
        OR attempt.request_digest IS DISTINCT FROM p_request_digest THEN
        RAISE EXCEPTION 'this attempt does not belong to the caller' USING ERRCODE = 'MO090';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM ops.ad_bid_command c WHERE c.id = attempt.command_id
        AND c.fence_token = p_fence AND c.lease_owner = p_owner
        AND c.lease_expires_at > clock_timestamp()) THEN
        RAISE EXCEPTION 'stale completion fence' USING ERRCODE = 'MO090';
    END IF;
    IF attempt.outcome_class <> 'IN_FLIGHT' THEN
        RAISE EXCEPTION 'this attempt is already complete' USING ERRCODE = 'MO096';
    END IF;

    IF p_content IS NULL THEN
        -- No bytes came back. That is only ever a non-accepted outcome, and on a
        -- mutating operation it is upgraded to unknown, because a closed socket
        -- is not evidence that the marketplace left the bid alone.
        IF p_outcome = 'ACCEPTED' OR p_http_status IS NOT NULL OR p_error IS NULL
            OR (p_body IS NOT NULL AND length(p_body) > 0) THEN
            RAISE EXCEPTION 'an answer with no recorded bytes cannot be an acceptance'
                USING ERRCODE = 'MO093';
        END IF;
        IF attempt.purpose IN ('APPLY', 'RESTORE')
            AND p_outcome IN ('RETRIABLE_ERROR', 'TIMEOUT') THEN
            resolved := 'UNKNOWN_STATE';
            failure := 'write_dispatch_not_proven_absent';
        ELSE
            resolved := p_outcome;
            failure := p_error;
        END IF;
    ELSE
        -- Selected from the function, not into a row variable from a single
        -- expression: PL/pgSQL assigns a select list to a row variable field by
        -- field, so the composite would land in the first field and fail.
        SELECT * INTO operation
          FROM jsonb_populate_record(NULL::platform.capability_operation,
                                     attempt.operation_snapshot -> 'operation');
        IF NOT EXISTS (SELECT 1 FROM raw.raw_content rc
                        WHERE rc.id = p_content
                          AND rc.hash_value = encode(sha256(p_body), 'hex')) THEN
            RAISE EXCEPTION 'the recorded bytes do not match their custody hash'
                USING ERRCODE = 'MO093';
        END IF;
        IF p_evidence_class NOT IN ('PROTOCOL_FIXTURE', 'PROVIDER_RESPONSE') THEN
            RAISE EXCEPTION 'an evidence class is required' USING ERRCODE = 'MO093';
        END IF;

        BEGIN
            document := convert_from(p_body, 'UTF8')::jsonb;
        EXCEPTION WHEN invalid_text_representation OR character_not_in_repertoire THEN
            document := NULL;
        END;

        IF document IS NULL THEN
            resolved := 'UNKNOWN_STATE';
            failure := 'response_semantics_unknown';
        ELSIF NOT p_response_complete OR p_http_status IN (408, 429) OR p_http_status >= 500 THEN
            resolved := CASE WHEN attempt.purpose IN ('APPLY', 'RESTORE')
                             THEN 'UNKNOWN_STATE' ELSE 'RETRIABLE_ERROR' END;
            failure := 'provider_response_inconclusive';
        ELSIF attempt.purpose IN ('APPLY', 'RESTORE', 'STATUS_ENQUIRY')
            AND operation.ad_not_applied_pointer IS NOT NULL
            AND ops.ad_json_value(document, operation.ad_not_applied_pointer)
                  = operation.ad_not_applied_value THEN
            resolved := 'RETRIABLE_ERROR';
            failure := 'provider_explicit_not_applied';
        ELSIF p_http_status >= 300 THEN
            resolved := 'REJECTED';
            failure := 'platform_rejected';
        ELSIF attempt.purpose IN ('APPLY', 'RESTORE') THEN
            IF ops.ad_json_value(document, operation.accepted_pointer)
                    IS NOT DISTINCT FROM operation.accepted_value THEN
                IF attempt.operation_snapshot ->> 'writeResultModel' = 'ASYNCHRONOUS_TASK' THEN
                    native_task := ops.ad_json_pointer(document, operation.task_key_pointer);
                    IF native_task IS NOT NULL AND length(native_task) BETWEEN 1 AND 256
                        AND native_task !~ '[[:cntrl:]]' THEN
                        resolved := 'ACCEPTED';
                    ELSE
                        resolved := 'UNKNOWN_STATE';
                        failure := 'asynchronous_accept_without_task_key';
                    END IF;
                ELSE
                    resolved := 'ACCEPTED';
                END IF;
            ELSE
                resolved := 'UNKNOWN_STATE';
                failure := 'response_semantics_unknown';
            END IF;
        ELSIF attempt.purpose = 'READBACK' THEN
            observed_bid := nullif(ops.ad_json_pointer(document, operation.observed_price_pointer), '')::numeric;
            observed_currency := ops.ad_json_pointer(document, operation.observed_currency_pointer);
            observed_unit := ops.ad_json_pointer(document, operation.ad_observed_unit_pointer);
            IF observed_bid IS NOT NULL AND observed_bid >= 0
                AND observed_currency ~ '^[A-Z]{3}$'
                AND observed_unit IN ('CURRENCY_MAJOR', 'CURRENCY_MINOR') THEN
                resolved := 'ACCEPTED';
            ELSE
                resolved := 'UNKNOWN_STATE';
                failure := 'readback_value_unreadable';
            END IF;
        ELSE
            IF ops.ad_json_pointer(document, operation.task_status_pointer)
                    = operation.task_success_value THEN
                resolved := 'ACCEPTED';
            ELSIF ops.ad_json_pointer(document, operation.task_status_pointer)
                    = operation.task_failure_value THEN
                resolved := 'REJECTED';
                failure := 'platform_task_rejected';
            ELSIF ops.ad_json_pointer(document, operation.task_status_pointer)
                    = ANY(operation.task_pending_values) THEN
                resolved := 'RETRIABLE_ERROR';
                failure := 'platform_task_pending';
            ELSE
                resolved := 'UNKNOWN_STATE';
                failure := 'response_semantics_unknown';
            END IF;
        END IF;

        observation_id := gen_random_uuid();
        INSERT INTO raw.ad_bid_response_observation (
            id, command_id, attempt_id, raw_content_id, request_digest, http_status,
            response_headers, evidence_class, response_complete, operation_id,
            operation_version, observed_bid, observed_currency, observed_unit,
            version_token, observed_at, correlation_id)
        VALUES (observation_id, attempt.command_id, attempt.id, p_content, p_request_digest,
            p_http_status, coalesce(p_headers, '{}'::jsonb), p_evidence_class,
            p_response_complete, operation.id, operation.version,
            observed_bid, observed_currency, observed_unit,
            p_headers ->> coalesce(operation.version_token_header, 'etag'),
            clock_timestamp(), attempt.correlation_id);
    END IF;

    UPDATE ops.ad_bid_command_attempt
       SET completed_at = clock_timestamp(), outcome_class = resolved,
           native_status = p_native_status, native_task_key = native_task,
           error_code = failure, raw_observation_id = observation_id
     WHERE id = p_id;

    RETURN observation_id;
END;
$_$;

CREATE FUNCTION ops.complete_diagnostic_export(p_id uuid, p_token uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE j ops.diagnostic_export; document jsonb; n bigint; bytes bigint;
BEGIN
 j:=ops.require_diagnostic_export_lease(p_id,p_token);
 SELECT coalesce(sum(row_count),0),coalesce(sum(byte_length),0) INTO n,bytes FROM ops.diagnostic_export_part WHERE export_id=p_id;
 IF j.snapshot_at IS NULL OR n<>j.row_count OR bytes<>j.byte_length THEN
   RAISE EXCEPTION 'incomplete export' USING ERRCODE='MO083'; END IF;
 SELECT jsonb_build_object('schemaVersion',1,'format','marketops-diagnostic-ndjson-v1','exportId',j.id,
   'storeId',j.store_id,'window',j.window_code,'snapshotAt',j.snapshot_at,'rowCount',j.row_count,'byteLength',j.byte_length,
   'parts',coalesce(jsonb_agg(jsonb_build_object('partNumber',part_number,'firstOrdinal',first_ordinal,
     'lastOrdinal',last_ordinal,'rowCount',row_count,'byteLength',byte_length,'sha256',sha256) ORDER BY part_number),'[]'::jsonb))
   INTO document FROM ops.diagnostic_export_part WHERE export_id=p_id;
 UPDATE ops.diagnostic_export SET state='SUCCEEDED',manifest=document,manifest_sha256=encode(sha256(convert_to(document::text,'UTF8')),'hex'),
   expires_at=statement_timestamp()+interval '1 hour',lease_token=NULL,lease_until=NULL,failure_code=NULL WHERE id=p_id RETURNING * INTO j;
 PERFORM ops.audit_diagnostic_export(j,'COMPLETED');
END $$;

CREATE FUNCTION ops.complete_lc_description_command_attempt(p_id uuid, p_fence bigint, p_owner text, p_outcome text, p_native_status text, p_task text, p_error text, p_content uuid, p_body bytea, p_http_status integer, p_headers jsonb, p_evidence_class text, p_request_digest text, p_response_complete boolean DEFAULT true) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'platform', 'raw', 'pg_temp'
    AS $$
DECLARE
    attempt   ops.lc_description_command_attempt%ROWTYPE;
    command   ops.lc_description_command%ROWTYPE;
    operation platform.capability_operation%ROWTYPE;
    document  jsonb;
    resolved  text;
    failure   text;
    observation_id uuid;
    observed_text text;
    observed_digest text;
    observed_kiz boolean;
    native_task text;
    selection jsonb; selected_document jsonb; typed_value jsonb;
BEGIN
    SELECT * INTO attempt FROM ops.lc_description_command_attempt WHERE id = p_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'attempt does not exist' USING ERRCODE = 'MO090'; END IF;
    IF attempt.fence_token <> p_fence OR attempt.lease_owner IS DISTINCT FROM p_owner
        OR attempt.request_digest IS DISTINCT FROM p_request_digest THEN
        RAISE EXCEPTION 'this attempt does not belong to the caller' USING ERRCODE = 'MO090';
    END IF;
    SELECT * INTO command FROM ops.lc_description_command c WHERE c.id = attempt.command_id;
    IF command.fence_token <> p_fence OR command.lease_owner IS DISTINCT FROM p_owner
        OR command.lease_expires_at <= clock_timestamp() THEN
        RAISE EXCEPTION 'stale completion fence' USING ERRCODE = 'MO090';
    END IF;
    IF attempt.outcome_class <> 'IN_FLIGHT' THEN
        RAISE EXCEPTION 'this attempt is already complete' USING ERRCODE = 'MO096';
    END IF;

    IF p_content IS NULL THEN
        IF p_outcome = 'ACCEPTED' OR p_http_status IS NOT NULL OR p_error IS NULL
            OR (p_body IS NOT NULL AND length(p_body) > 0) THEN
            RAISE EXCEPTION 'an answer with no recorded bytes cannot be an acceptance' USING ERRCODE = 'MO093';
        END IF;
        IF attempt.purpose IN ('APPLY', 'RESTORE') THEN
            resolved := 'UNKNOWN_STATE';
            failure := 'write_dispatch_not_proven_absent';
        ELSE
            resolved := 'UNKNOWN_STATE';
            failure := coalesce(p_error,'response_evidence_absent');
        END IF;
    ELSE
        SELECT * INTO operation
          FROM jsonb_populate_record(NULL::platform.capability_operation, attempt.operation_snapshot -> 'operation');
        IF NOT EXISTS (SELECT 1 FROM raw.raw_content rc
                        WHERE rc.id = p_content AND rc.hash_value = encode(sha256(p_body), 'hex')) THEN
            RAISE EXCEPTION 'the recorded bytes do not match their custody hash' USING ERRCODE = 'MO093';
        END IF;
        IF p_evidence_class NOT IN ('PROTOCOL_FIXTURE', 'PROVIDER_RESPONSE') THEN
            RAISE EXCEPTION 'an evidence class is required' USING ERRCODE = 'MO093';
        END IF;
        BEGIN
            IF convert_from(p_body, 'UTF8') IS JSON WITH UNIQUE KEYS THEN
                document := convert_from(p_body, 'UTF8')::jsonb;
            ELSE document := NULL; END IF;
        EXCEPTION WHEN invalid_text_representation OR character_not_in_repertoire THEN
            document := NULL;
        END;
        selection := ops.lc_select_description_response(document,attempt.operation_snapshot ||
            CASE WHEN attempt.query_identity IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('queryIdentity',attempt.query_identity) END,attempt.purpose);
        selected_document := selection->'payload';
        IF document IS NULL THEN
            resolved := 'UNKNOWN_STATE'; failure := 'response_semantics_unknown';
        ELSIF p_response_complete IS NOT TRUE OR p_http_status IS NULL OR p_http_status IN (408, 409, 429) OR p_http_status >= 500 THEN
            resolved := CASE WHEN attempt.purpose IN ('APPLY', 'RESTORE') THEN 'UNKNOWN_STATE' ELSE 'RETRIABLE_ERROR' END;
            failure := 'provider_response_inconclusive';
        ELSIF selection->>'qualified' IS DISTINCT FROM 'true' THEN
            resolved := 'UNKNOWN_STATE'; failure := coalesce(selection->>'gap','response_semantics_unknown');
        ELSIF attempt.purpose IN ('APPLY', 'RESTORE', 'STATUS_ENQUIRY')
            AND selection->>'extent'='EXACT_NATIVE_OBJECT'
            AND operation.ad_not_applied_pointer IS NOT NULL AND operation.ad_not_applied_value IS NOT NULL
            AND operation.ad_not_applied_value <> 'null'::jsonb
            AND ops.lc_response_value(selected_document, operation.ad_not_applied_pointer) = operation.ad_not_applied_value THEN
            resolved := 'RETRIABLE_ERROR'; failure := 'provider_explicit_not_applied';
        ELSIF p_http_status >= 300 THEN
            resolved := CASE WHEN attempt.purpose IN ('APPLY','RESTORE') THEN 'UNKNOWN_STATE' ELSE 'RETRIABLE_ERROR' END;
            failure := 'http_status_does_not_prove_business_rejection';
        ELSIF attempt.purpose IN ('APPLY', 'RESTORE') THEN
            IF operation.accepted_pointer IS NOT NULL AND operation.accepted_value IS NOT NULL
                AND operation.accepted_value <> 'null'::jsonb
                AND ops.lc_response_value(selected_document, operation.accepted_pointer) = operation.accepted_value THEN
                IF attempt.operation_snapshot ->> 'writeResultModel' = 'ASYNCHRONOUS_TASK' THEN
                    typed_value := ops.lc_response_value(selected_document, operation.task_key_pointer);
                    native_task := CASE WHEN jsonb_typeof(typed_value) IN ('string','number') THEN typed_value #>> '{}' END;
                    IF native_task IS NOT NULL AND length(native_task) BETWEEN 1 AND 256
                        AND native_task !~ '[[:cntrl:]]' THEN
                        resolved := 'ACCEPTED';
                    ELSE
                        resolved := 'UNKNOWN_STATE'; failure := 'asynchronous_accept_without_task_key';
                    END IF;
                ELSE
                    resolved := 'ACCEPTED';
                END IF;
            ELSE
                resolved := 'UNKNOWN_STATE'; failure := 'response_semantics_unknown';
            END IF;
        ELSIF attempt.purpose = 'READBACK' THEN
            typed_value := ops.lc_response_value(selected_document, operation.description_observed_text_pointer);
            IF jsonb_typeof(typed_value)='string' THEN observed_text := typed_value #>> '{}'; END IF;
            IF operation.description_kiz_marked_pointer IS NOT NULL THEN
                typed_value := ops.lc_response_value(selected_document, operation.description_kiz_marked_pointer);
                IF jsonb_typeof(typed_value)='boolean' THEN observed_kiz := (typed_value #>> '{}')::boolean; END IF;
            END IF;
            IF observed_text IS NOT NULL AND (operation.description_kiz_marked_pointer IS NULL OR observed_kiz IS NOT NULL) THEN
                observed_digest := ops.lc_description_digest_under_rule(observed_text, command.equivalence_rule);
                resolved := 'ACCEPTED';
            ELSE
                resolved := 'UNKNOWN_STATE'; failure := 'readback_value_unreadable';
            END IF;
        ELSE
            typed_value := ops.lc_response_value(selected_document, operation.task_status_pointer);
            IF jsonb_typeof(typed_value) IS DISTINCT FROM operation.description_response_binding->>'statusValueType' THEN
                resolved := 'UNKNOWN_STATE'; failure := 'task_status_type_unknown';
            ELSIF typed_value #>> '{}' = operation.task_success_value THEN
                resolved := 'ACCEPTED';
            ELSIF (typed_value #>> '{}') = operation.task_failure_value THEN
                resolved := 'REJECTED'; failure := 'platform_task_rejected';
            ELSIF (typed_value #>> '{}') = ANY(operation.task_pending_values) THEN
                resolved := 'RETRIABLE_ERROR'; failure := 'platform_task_pending';
            ELSE
                resolved := 'UNKNOWN_STATE'; failure := 'response_semantics_unknown';
            END IF;
        END IF;

        observation_id := gen_random_uuid();
        INSERT INTO raw.lc_description_response_observation (
            id, command_id, attempt_id, raw_content_id, request_digest, http_status, response_headers,
            evidence_class, response_complete, operation_id, operation_version, observed_text_digest,
            observed_kiz_marked, version_token, observed_at, correlation_id, identity_binding)
        VALUES (observation_id, attempt.command_id, attempt.id, p_content, p_request_digest, p_http_status,
            coalesce(p_headers, '{}'::jsonb), p_evidence_class, p_response_complete, operation.id,
            operation.version, observed_digest, observed_kiz,
            p_headers ->> coalesce(operation.version_token_header, 'etag'), clock_timestamp(),
            attempt.correlation_id, (selection-'payload') || jsonb_build_object(
                'responseIdentity',attempt.operation_snapshot->'responseIdentity',
                'descriptorDigest',encode(sha256(convert_to(operation.description_response_binding::text,'UTF8')),'hex')));
    END IF;

    UPDATE ops.lc_description_command_attempt
       SET completed_at = clock_timestamp(), outcome_class = resolved,
           native_status = CASE WHEN attempt.purpose='STATUS_ENQUIRY'
               AND jsonb_typeof(typed_value)=operation.description_response_binding->>'statusValueType'
               THEN typed_value #>> '{}' ELSE p_http_status::text END,
           native_task_key = native_task, error_code = failure, raw_observation_id = observation_id
     WHERE id = p_id;
    RETURN observation_id;
END;
$$;

CREATE FUNCTION ops.complete_price_command_attempt(p_id uuid, p_fence bigint, p_owner text, p_outcome text, p_native_status text, p_task text, p_error text, p_content uuid, p_body bytea, p_http_status integer, p_headers jsonb, p_evidence_class text, p_request_digest text, p_response_complete boolean DEFAULT true) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE
    a ops.price_command_attempt%ROWTYPE;
    operation platform.capability_operation%ROWTYPE;
    observation uuid;
    document jsonb;
    price_text text;
    currency text;
    price numeric;
    response_text text;
    response_task text;
    response_state text;
    resolved_outcome text;
    resolved_error text;
BEGIN
    SELECT * INTO a FROM ops.price_command_attempt WHERE id = p_id FOR UPDATE;
    IF a.id IS NULL OR a.fence_token IS DISTINCT FROM p_fence
       OR a.lease_owner IS DISTINCT FROM p_owner OR a.request_digest IS DISTINCT FROM p_request_digest THEN
        RAISE EXCEPTION 'attempt identity does not match response' USING ERRCODE = 'MO030';
    END IF;
    IF a.outcome_class <> 'IN_FLIGHT' THEN
        RAISE EXCEPTION 'attempt is already complete' USING ERRCODE = 'MO037';
    END IF;
    resolved_outcome := p_outcome;
    resolved_error := p_error;
    IF p_response_complete IS NULL OR (NOT p_response_complete AND p_outcome='ACCEPTED') THEN
        RAISE EXCEPTION 'incomplete response cannot be accepted' USING ERRCODE='MO033';
    END IF;
    IF p_content IS NULL THEN
        IF p_outcome = 'ACCEPTED' OR p_http_status IS NOT NULL OR p_error IS NULL
           OR coalesce(octet_length(p_body), 0) <> 0 THEN
            RAISE EXCEPTION 'a response requires immutable custody' USING ERRCODE = 'MO033';
        END IF;
        IF a.purpose IN ('APPLY','RESTORE') AND p_outcome IN ('RETRIABLE_ERROR','TIMEOUT') THEN
            resolved_outcome:='UNKNOWN_STATE'; resolved_error:='write_dispatch_not_proven_absent';
        END IF;
    ELSE
        PERFORM 1 FROM raw.raw_content content WHERE content.id = p_content
            AND content.hash_value = encode(sha256(p_body), 'hex')
            AND content.byte_length = octet_length(p_body);
        IF NOT FOUND THEN
            RAISE EXCEPTION 'response bytes do not match custody' USING ERRCODE = 'MO033';
        END IF;
        IF p_headers IS NULL OR EXISTS (SELECT 1 FROM jsonb_each_text(p_headers) header
            WHERE header.key NOT IN ('content-type', 'retry-after', 'x-request-id', 'etag', 'x-version-id')
               OR length(header.value) > 256 OR header.value ~ '[[:cntrl:]]') THEN
            RAISE EXCEPTION 'unsafe response header metadata' USING ERRCODE = 'MO033';
        END IF;
        SELECT * INTO operation FROM jsonb_populate_record(NULL::platform.capability_operation,a.operation_snapshot->'operation');
        IF operation.id IS NULL THEN
            RAISE EXCEPTION 'response operation is not verified' USING ERRCODE = 'MO033';
        END IF;
        IF p_response_complete AND p_http_status BETWEEN 200 AND 299 THEN
            BEGIN
                response_text := convert_from(p_body, 'UTF8');
                IF response_text IS JSON OBJECT WITH UNIQUE KEYS THEN
                    document := response_text::jsonb;
                END IF;
                IF a.purpose='READBACK' THEN
                price_text := ops.price_json_pointer(document, operation.observed_price_pointer);
                currency := ops.price_json_pointer(document, operation.observed_currency_pointer);
                IF price_text ~ '^[0-9]{1,14}([.][0-9]{1,4})?$' AND currency ~ '^[A-Z]{3}$'
                   AND price_text::numeric > 0 THEN price := price_text::numeric;
                ELSE price := NULL; currency := NULL;
                END IF;
                END IF;
            EXCEPTION WHEN invalid_text_representation OR character_not_in_repertoire
                OR numeric_value_out_of_range THEN price := NULL; currency := NULL;
            END;
        END IF;
        resolved_outcome := 'UNKNOWN_STATE'; resolved_error := 'response_semantics_unknown';
        IF NOT p_response_complete OR p_http_status IN (408,429) OR p_http_status >= 500 THEN
            resolved_outcome := CASE WHEN a.purpose IN ('APPLY','RESTORE') THEN 'UNKNOWN_STATE' ELSE 'RETRIABLE_ERROR' END;
            resolved_error := 'provider_response_inconclusive';
        ELSIF p_http_status NOT BETWEEN 200 AND 299 THEN
            resolved_outcome := 'REJECTED'; resolved_error := 'platform_rejected';
        ELSIF document IS NOT NULL THEN
            IF a.purpose IN ('APPLY','RESTORE') AND operation.accepted_value IS NOT NULL
                AND ops.price_json_value(document,operation.accepted_pointer)=operation.accepted_value THEN
                IF a.operation_snapshot->>'writeResultModel'='ASYNCHRONOUS_TASK' THEN
                    IF jsonb_typeof(ops.price_json_value(document,operation.task_key_pointer))='string' THEN
                        response_task := ops.price_json_pointer(document,operation.task_key_pointer);
                        IF length(response_task) NOT BETWEEN 1 AND 256 OR response_task ~ '[[:cntrl:]]'
                            OR length(btrim(response_task))=0 THEN response_task:=NULL; END IF;
                    END IF;
                    IF response_task IS NOT NULL THEN resolved_outcome:='ACCEPTED'; END IF;
                ELSIF a.operation_snapshot->>'writeResultModel'='SYNCHRONOUS' THEN resolved_outcome:='ACCEPTED';
                END IF;
            ELSIF a.purpose='READBACK' AND price IS NOT NULL AND currency IS NOT NULL THEN
                resolved_outcome:='ACCEPTED';
            ELSIF a.purpose='STATUS_ENQUIRY'
                AND jsonb_typeof(ops.price_json_value(document,operation.task_status_pointer))='string' THEN
                response_state:=ops.price_json_pointer(document,operation.task_status_pointer);
                IF response_state=operation.task_success_value THEN resolved_outcome:='ACCEPTED';
                ELSIF response_state=operation.task_failure_value THEN resolved_outcome:='REJECTED'; resolved_error:='platform_task_rejected';
                ELSIF response_state=ANY(operation.task_pending_values) THEN
                    resolved_outcome:='RETRIABLE_ERROR'; resolved_error:='platform_task_in_progress';
                END IF;
            END IF;
        END IF;
        IF resolved_outcome='ACCEPTED' THEN resolved_error:=NULL; END IF;
        PERFORM platform.defer_endpoint_quota(operation.endpoint_id,p_http_status,p_headers);
        observation := gen_random_uuid();
        INSERT INTO raw.price_response_observation (id, command_id, attempt_id, raw_content_id,
            request_digest, http_status, response_headers, evidence_class, operation_id,
            operation_version, observed_price, observed_currency, version_token, observed_at,
            correlation_id, response_complete)
        VALUES (observation, a.command_id, a.id, p_content, a.request_digest, p_http_status,
            p_headers, p_evidence_class, operation.id, operation.version, price, currency,
            CASE WHEN p_response_complete THEN p_headers ->> operation.version_token_header END,
            clock_timestamp(), a.correlation_id, p_response_complete);
    END IF;
    UPDATE ops.price_command_attempt SET completed_at = clock_timestamp(), outcome_class = resolved_outcome,
        native_status = CASE WHEN p_content IS NULL THEN p_native_status
            ELSE coalesce(response_state,'HTTP '||p_http_status) END,
        native_task_key = response_task, error_code = resolved_error,
        raw_observation_id = observation WHERE id = a.id;
    RETURN observation;
END;
$_$;

CREATE TABLE iam.ad_invocation_grant (
    proof_hash text NOT NULL,
    actor_user_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    identity_provider_id uuid NOT NULL,
    subject_digest text NOT NULL,
    session_digest text NOT NULL,
    authenticated_at timestamp with time zone NOT NULL,
    step_up_valid_until timestamp with time zone NOT NULL,
    recommendation_id uuid NOT NULL,
    approval_decision_id uuid NOT NULL,
    backend_pid integer NOT NULL,
    transaction_id bigint NOT NULL,
    issued_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    consumed_at timestamp with time zone,
    purpose text DEFAULT 'FINAL_APPROVAL'::text NOT NULL,
    CONSTRAINT ad_invocation_grant_check CHECK (((expires_at > issued_at) AND (expires_at <= (issued_at + '00:00:30'::interval)))),
    CONSTRAINT ad_invocation_grant_proof_hash_check CHECK ((proof_hash ~ '^[0-9a-f]{64}$'::text))
);

CREATE FUNCTION ops.consume_ad_control_invocation(p_proof text, p_purpose text, p_target uuid, p_version uuid) RETURNS iam.ad_invocation_grant
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'iam', 'pg_temp'
    AS $$
DECLARE g iam.ad_invocation_grant%ROWTYPE; BEGIN
 SELECT * INTO g FROM iam.ad_invocation_grant WHERE proof_hash=encode(sha256(convert_to(p_proof,'UTF8')),'hex') FOR UPDATE;
 IF NOT FOUND OR g.consumed_at IS NOT NULL OR g.expires_at<=clock_timestamp() OR g.purpose<>p_purpose
 OR g.recommendation_id<>p_target OR g.approval_decision_id<>p_version
 OR g.backend_pid<>pg_backend_pid() OR g.transaction_id<>txid_current()
 OR g.step_up_valid_until<=clock_timestamp()
 OR NOT EXISTS(SELECT 1 FROM iam.user_account actor JOIN iam.identity_provider provider ON provider.id=actor.identity_provider_id
 WHERE actor.id=g.actor_user_id AND actor.organization_id=g.organization_id AND actor.identity_provider_id=g.identity_provider_id
 AND actor.status='ACTIVE' AND actor.credentials_valid_from<=g.authenticated_at
 AND provider.status='ACTIVE' AND provider.verification_state='VERIFIED') THEN
  RAISE EXCEPTION 'exact one-use authenticated control invocation required' USING ERRCODE='MO092'; END IF;
 UPDATE iam.ad_invocation_grant SET consumed_at=clock_timestamp() WHERE proof_hash=g.proof_hash;
 RETURN g;
END $$;

CREATE FUNCTION ops.consume_policy_authorization(p_authorization_id uuid, p_change_rate numeric, p_store_id uuid, p_variant_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    authorization_row record;
    remaining_uses    integer;
BEGIN
    SELECT grant_row.id, grant_row.status, grant_row.max_change_rate,
           grant_row.max_uses, grant_row.used_count, grant_row.valid_from,
           grant_row.valid_until, grant_row.scope_kind, grant_row.store_ref_id,
           grant_row.product_variant_ref_id
      INTO authorization_row
      FROM ops.policy_authorization AS grant_row
     WHERE grant_row.id = p_authorization_id
       FOR UPDATE OF grant_row;

    IF authorization_row.id IS NULL THEN
        RAISE EXCEPTION 'policy authorization % does not exist', p_authorization_id
            USING ERRCODE = 'MO020';
    END IF;

    IF authorization_row.status <> 'ACTIVE' THEN
        RAISE EXCEPTION 'policy authorization % is %',
            p_authorization_id, authorization_row.status
            USING ERRCODE = 'MO021';
    END IF;

    IF clock_timestamp() < authorization_row.valid_from
        OR clock_timestamp() >= authorization_row.valid_until THEN
        RAISE EXCEPTION 'policy authorization % is outside its validity window',
            p_authorization_id
            USING ERRCODE = 'MO021';
    END IF;

    IF p_change_rate IS NULL OR p_change_rate > authorization_row.max_change_rate THEN
        RAISE EXCEPTION
            'requested change exceeds the bound of policy authorization %',
            p_authorization_id
            USING ERRCODE = 'MO022';
    END IF;

    IF authorization_row.scope_kind = 'STORE'
        AND authorization_row.store_ref_id IS DISTINCT FROM p_store_id THEN
        RAISE EXCEPTION 'policy authorization % does not cover this store',
            p_authorization_id
            USING ERRCODE = 'MO023';
    END IF;

    IF authorization_row.scope_kind = 'PRODUCT_VARIANT'
        AND authorization_row.product_variant_ref_id IS DISTINCT FROM p_variant_id THEN
        RAISE EXCEPTION 'policy authorization % does not cover this variant',
            p_authorization_id
            USING ERRCODE = 'MO023';
    END IF;

    IF authorization_row.used_count >= authorization_row.max_uses THEN
        RAISE EXCEPTION 'policy authorization % has no remaining uses',
            p_authorization_id
            USING ERRCODE = 'MO024';
    END IF;

    UPDATE ops.policy_authorization AS grant_row
       SET used_count = grant_row.used_count + 1,
           status = CASE
                        WHEN grant_row.used_count + 1 >= grant_row.max_uses
                            THEN 'EXHAUSTED'
                        ELSE grant_row.status
                    END,
           updated_at = clock_timestamp(),
           version = grant_row.version + 1
     WHERE grant_row.id = p_authorization_id
       AND grant_row.used_count = authorization_row.used_count
    RETURNING grant_row.max_uses - grant_row.used_count INTO remaining_uses;

    IF remaining_uses IS NULL THEN
        RAISE EXCEPTION 'policy authorization % changed while being consumed',
            p_authorization_id
            USING ERRCODE = 'MO024';
    END IF;

    RETURN remaining_uses;
END;
$$;

CREATE FUNCTION ops.create_ad_bid_command(p_recommendation uuid, p_version bigint, p_reservation uuid, p_correlation text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE candidate uuid;
BEGIN
 SELECT candidate_id INTO candidate FROM ops.ad_action_authorization WHERE recommendation_id=p_recommendation;
 IF candidate IS NOT NULL AND cardinality(ops.ad_economic_cause_bound_failures(candidate,clock_timestamp()))>0 THEN
   RAISE EXCEPTION 'economic cause-specific action proof remains unresolved' USING ERRCODE='MO092'; END IF;
 RETURN ops.create_ad_bid_command_before_economic_cause(p_recommendation,p_version,p_reservation,p_correlation);
END $$;

CREATE FUNCTION ops.create_ad_bid_command_before_economic_cause(p_recommendation uuid, p_version bigint, p_reservation uuid, p_correlation text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE a ops.ad_action_authorization%ROWTYPE; command_id uuid;
BEGIN
 SELECT * INTO a FROM ops.ad_action_authorization WHERE recommendation_id=p_recommendation;
 IF NOT FOUND OR a.expires_at<=clock_timestamp()
 OR EXISTS(SELECT 1 FROM ops.ad_authority_invalidation i WHERE i.authorization_id=a.id)
 OR a.authority_snapshot-'decisionEvidence' IS DISTINCT FROM ops.ad_bundle_authority_snapshot(a.bundle_id) THEN
  RAISE EXCEPTION 'current immutable approval authority required' USING ERRCODE='MO092'; END IF;
 IF ops.ad_outcome_baseline_is_canonical(a.outcome_baseline_id,clock_timestamp()) IS NOT TRUE THEN
  RAISE EXCEPTION 'canonical frozen Outcome authority required at command creation' USING ERRCODE='MO099'; END IF;
 IF cardinality(ops.ad_action_isolation_failures(
  (SELECT affected_set_id FROM ops.ad_outcome_baseline WHERE id=a.outcome_baseline_id),a.outcome_baseline_id,clock_timestamp()))>0 THEN
  RAISE EXCEPTION 'known cross-domain intervention prevents isolated command creation' USING ERRCODE='MO099'; END IF;
 IF ops.ad_materiality_assessment(a.bundle_id,a.candidate_id)->>'route' IS DISTINCT FROM a.materiality_route THEN
  RAISE EXCEPTION 'sealed materiality route no longer matches current independent axes' USING ERRCODE='MO092'; END IF;
 IF EXISTS(SELECT 1 FROM ops.ad_accepted_exception exception
 JOIN ops.ad_bid_candidate candidate ON candidate.id=a.candidate_id
 WHERE exception.case_id=candidate.case_id AND exception.state='ACTIVE' AND exception.ended_at IS NULL) THEN
  RAISE EXCEPTION 'ACCEPTED_EXCEPTION_ACTIVE' USING ERRCODE='MO092'; END IF;
 IF EXISTS(SELECT 1 FROM ops.ad_bid_command c JOIN ops.recommendation r ON r.id=p_recommendation
    WHERE c.ad_native_object_id=r.subject_id AND c.recommendation_id<>r.id) THEN
  RAISE EXCEPTION 'general same-object reentry is disabled pending accepted calibration' USING ERRCODE='MO092'; END IF;
 command_id:=ops.create_ad_bid_command_from_sealed_authority(p_recommendation,p_version,
   a.final_approver_user_id,p_reservation,a.bundle_id,a.expires_at,p_correlation);
 RETURN command_id;
END $$;

CREATE FUNCTION ops.create_ad_bid_command_from_sealed_authority(p_recommendation_id uuid, p_expected_version bigint, p_actor_id uuid, p_reservation_id uuid, p_bundle_id uuid, p_approval_expires_at timestamp with time zone, p_correlation_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'platform', 'iam', 'pg_temp'
    AS $$
DECLARE
    recommendation ops.recommendation%ROWTYPE;
    candidate      ops.ad_bid_candidate%ROWTYPE;
    object_row     core.ad_native_object%ROWTYPE;
    configuration  core.ad_object_configuration_observation%ROWTYPE;
    capability_id  uuid;
    approval_id    uuid;
    existing_id    uuid;
    command_id     uuid;
    materiality    text;
    envelope       core.ad_materiality_policy%ROWTYPE;
    change_amount  numeric(18, 4);
BEGIN
    IF p_correlation_id IS NULL
        OR length(btrim(p_correlation_id)) NOT BETWEEN 1 AND 128 THEN
        RAISE EXCEPTION 'a correlation identifier is required' USING ERRCODE = 'MO092';
    END IF;

    SELECT * INTO recommendation FROM ops.recommendation
     WHERE id = p_recommendation_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'recommendation does not exist' USING ERRCODE = 'MO090';
    END IF;
    IF recommendation.version <> p_expected_version THEN
        RAISE EXCEPTION 'the recommendation changed since it was read'
            USING ERRCODE = 'MO090';
    END IF;

    -- Idempotent on the recommendation. One approval, one command, however many
    -- times the button is pressed.
    SELECT id INTO existing_id FROM ops.ad_bid_command
     WHERE recommendation_id = recommendation.id;
    IF existing_id IS NOT NULL THEN
        RETURN existing_id;
    END IF;

    IF recommendation.action_kind <> 'AD_BID_CHANGE'
        OR recommendation.subject_kind <> 'AD_NATIVE_OBJECT'
        OR recommendation.state NOT IN ('APPROVED', 'POLICY_AUTHORIZED')
        OR recommendation.valid_until <= statement_timestamp()
        OR NOT ops.ad_bid_parameter_contract_is_valid(recommendation.proposed_parameters) THEN
        RAISE EXCEPTION 'the recommendation is not an approved, current bid change'
            USING ERRCODE = 'MO092';
    END IF;

    -- The person creating the command must be able to approve one. A command
    -- created by somebody who could not approve it would carry an approval
    -- nobody with the authority gave.
    IF NOT EXISTS (
        SELECT 1
          FROM iam.user_role_assignment role
          JOIN iam.business_role_action_scope matrix ON matrix.role_code = role.role_code
          JOIN iam.user_scope_grant grant_row
            ON grant_row.user_id = role.user_id
           AND grant_row.action_code = 'AD_BID_CHANGE_APPROVE'
          JOIN core.store store ON store.id = recommendation.store_id
          JOIN core.marketplace_account account ON account.id = store.marketplace_account_id
         WHERE role.user_id = p_actor_id
           AND role.status = 'ACTIVE'
           AND role.effective_from <= statement_timestamp()
           AND (role.effective_to IS NULL OR role.effective_to > statement_timestamp())
           AND matrix.action_code = 'AD_BID_CHANGE_APPROVE'
           AND grant_row.status = 'ACTIVE'
           AND grant_row.effective_from <= statement_timestamp()
           AND (grant_row.effective_to IS NULL OR grant_row.effective_to > statement_timestamp())
           AND (grant_row.organization_ref_id = recommendation.organization_id
                OR grant_row.store_ref_id = store.id
                OR grant_row.marketplace_account_ref_id = account.id
                OR grant_row.legal_entity_ref_id = account.legal_entity_id)) THEN
        RAISE EXCEPTION 'the actor cannot approve an advertising bid change here'
            USING ERRCODE = 'MO092';
    END IF;

    SELECT * INTO candidate FROM ops.ad_bid_candidate
     WHERE id = (recommendation.proposed_parameters ->> 'candidateId')::uuid
       AND organization_id = recommendation.organization_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'the approved candidate does not exist' USING ERRCODE = 'MO092';
    END IF;
    IF cardinality(ops.ad_action_blockers(candidate.candidate_basis,candidate.cause_code,
        (SELECT blocker_codes FROM mart.ad_case WHERE id=candidate.case_id)))>0 THEN
        RAISE EXCEPTION 'current action-specific evidence blockers remain unresolved' USING ERRCODE='MO092';
    END IF;
    IF candidate.direction <> (recommendation.proposed_parameters ->> 'direction')
        OR candidate.provider_normalized_amount
            <> (recommendation.proposed_parameters ->> 'targetBid')::numeric THEN
        RAISE EXCEPTION 'the approval does not describe the candidate it names'
            USING ERRCODE = 'MO092';
    END IF;

    SELECT * INTO object_row FROM core.ad_native_object
     WHERE id = recommendation.subject_id AND organization_id = recommendation.organization_id;
    IF NOT FOUND OR object_row.control_granularity_state <> 'PROVEN_INDEPENDENT'
        OR object_row.status <> 'ACTIVE' THEN
        RAISE EXCEPTION 'the advertising object is not independently controllable'
            USING ERRCODE = 'MO092';
    END IF;

    IF NOT EXISTS(SELECT 1 FROM core.ad_bid_target_policy policy
        JOIN platform.ad_semantic_profile profile ON profile.id=candidate.semantic_profile_id
        WHERE policy.id=candidate.target_policy_id AND policy.policy_version=candidate.target_policy_version
        AND policy.status='ACTIVE' AND policy.effective_from<=statement_timestamp()
        AND (policy.effective_to IS NULL OR policy.effective_to>statement_timestamp())
        AND profile.id=object_row.semantic_profile_id AND profile.status='ACTIVE'
        AND profile.verification_state='VERIFIED' AND profile.bid_currency_code=candidate.currency_code
        AND profile.bid_unit_code=candidate.bid_unit_code
        AND candidate.provider_normalized_amount BETWEEN profile.bid_minimum AND profile.bid_maximum
        AND mod(candidate.provider_normalized_amount,profile.bid_step)=0
        AND round(candidate.provider_normalized_amount,profile.bid_precision)=candidate.provider_normalized_amount
        AND abs(candidate.provider_normalized_amount-candidate.current_bid_amount)
            <=least(policy.max_absolute_change_amount * CASE candidate.bid_unit_code WHEN 'CURRENCY_MINOR' THEN 100 ELSE 1 END,candidate.current_bid_amount*policy.max_relative_change_ratio)
        AND policy.direction=candidate.direction AND policy.candidate_basis=candidate.candidate_basis
        AND (candidate.candidate_basis='MAX_CPC_BOUNDED' AND candidate.max_cpc_amount IS NOT NULL
             AND (candidate.provider_normalized_amount<=candidate.max_cpc_amount*(1-policy.ceiling_headroom_ratio)
                 OR candidate.direction='PROTECTION_DECREASE' AND policy.allow_protection_intermediate_target)
          OR candidate.candidate_basis='CAUSE_BOUND_PROTECTION_STEP'
             AND candidate.direction='PROTECTION_DECREASE' AND policy.cause_bound_step_enabled
             AND policy.cause_bound_step_ratio IS NOT NULL
             AND abs(candidate.provider_normalized_amount-candidate.current_bid_amount)
                 <=candidate.current_bid_amount*policy.cause_bound_step_ratio
             AND candidate.cause_code=ANY(policy.cause_bound_causes))) THEN
        RAISE EXCEPTION 'candidate no longer satisfies exact target and Provider policy' USING ERRCODE='MO092';
    END IF;

    SELECT * INTO configuration FROM core.ad_object_configuration_observation c
     WHERE c.ad_native_object_id = object_row.id
       AND c.organization_id = object_row.organization_id
       AND NOT EXISTS (SELECT 1 FROM core.ad_object_configuration_observation later
                        WHERE later.supersedes_observation_id = c.id)
     ORDER BY c.observed_at DESC, c.id DESC LIMIT 1;
    IF NOT FOUND OR configuration.observed_bid_amount IS NULL THEN
        RAISE EXCEPTION 'the current bid is not observed, so no change can be exact'
            USING ERRCODE = 'MO092';
    END IF;
    IF configuration.observed_bid_amount <> candidate.current_bid_amount THEN
        RAISE EXCEPTION 'the bid moved since the candidate was generated'
            USING ERRCODE = 'MO090';
    END IF;

    -- The reservation must already be held by this object. A command without one
    -- could execute beside another action on the same variants.
    IF NOT EXISTS (
        SELECT 1 FROM ops.ad_action_reservation r
         WHERE r.id = p_reservation_id
           AND r.organization_id = recommendation.organization_id
           AND r.ad_native_object_id = object_row.id
           AND r.state = 'ACTIVE'
           AND r.affected_set_digest = candidate.affected_set_digest) THEN
        RAISE EXCEPTION 'no active reservation is held for this affected set'
            USING ERRCODE = 'MO097';
    END IF;

    SELECT a.id INTO approval_id FROM ops.approval_decision a
     WHERE a.recommendation_id = recommendation.id
       AND a.decision IN ('APPROVED', 'POLICY_AUTHORIZED')
       AND a.scope_expires_at > statement_timestamp()
     ORDER BY a.decided_at DESC LIMIT 1;
    IF approval_id IS NULL THEN
        RAISE EXCEPTION 'no current approval covers this recommendation'
            USING ERRCODE = 'MO092';
    END IF;

    SELECT c.id INTO capability_id FROM platform.platform_capability c
     WHERE c.platform_code = object_row.platform_code
       AND c.capability_code = 'ad-bid-change'
       AND c.read_write_class = 'WRITE'
       AND c.status = 'ACTIVE'
       AND c.verification_state = 'VERIFIED'
       AND c.deprecated_at IS NULL;
    IF capability_id IS NULL THEN
        -- This is the structural refusal. Until an advertising capability is
        -- independently verified for this platform, no command can exist at all,
        -- which is a stronger statement than a gate that would have refused it.
        RAISE EXCEPTION 'no verified advertising write capability exists for this platform'
            USING ERRCODE = 'MO092';
    END IF;

    -- Materiality. The initial ordinary envelope is zero, so every nonzero
    -- change is Material; the policy is read rather than assumed so widening it
    -- later stays a reviewed data change.
    change_amount := abs(candidate.provider_normalized_amount - candidate.current_bid_amount)
        / CASE candidate.bid_unit_code WHEN 'CURRENCY_MINOR' THEN 100 ELSE 1 END;
    SELECT * INTO envelope FROM core.ad_materiality_policy m
     WHERE m.organization_id = recommendation.organization_id
       AND m.status = 'ACTIVE'
       AND (m.scope_kind='ORGANIZATION'
         OR m.scope_kind='PLATFORM' AND m.platform_code=object_row.platform_code
         OR m.scope_kind='STORE' AND m.store_ref_id=recommendation.store_id)
       AND m.effective_from <= statement_timestamp()
       AND (m.effective_to IS NULL OR m.effective_to > statement_timestamp())
     ORDER BY CASE m.scope_kind WHEN 'STORE' THEN 1 WHEN 'PLATFORM' THEN 2 ELSE 3 END,
              m.effective_from DESC
     LIMIT 1;
    IF NOT FOUND THEN
        materiality := 'MATERIALITY_UNRESOLVED';
    ELSIF change_amount > envelope.ordinary_nonzero_envelope_amount THEN
        materiality := 'MATERIAL_IMPACT';
    ELSE
        materiality := CASE WHEN ops.ad_ordinary_promotion_covers(p_bundle_id,
            object_row.id, change_amount) THEN 'ORDINARY_IMPACT' ELSE 'MATERIAL_IMPACT' END;
    END IF;
    IF materiality = 'MATERIALITY_UNRESOLVED' THEN
        RAISE EXCEPTION 'materiality cannot be resolved, so no command may be created'
            USING ERRCODE = 'MO092';
    END IF;

    command_id := gen_random_uuid();
    INSERT INTO ops.ad_bid_command (
        id, organization_id, recommendation_id, approval_decision_id, store_id,
        ad_native_object_id, platform_code, capability_id, semantic_profile_id,
        candidate_id, bundle_id, reservation_id, idempotency_key, currency_code,
        bid_unit_code, direction, candidate_basis, materiality_route,
        prior_bid_amount, target_bid_amount, prior_configuration_id, affected_set_digest,
        lineage_generation, entity_version_digest, authority_snapshot,
        approval_expires_at, state, retry_budget_remaining, next_attempt_at,
        created_at, updated_at)
    VALUES (
        command_id, recommendation.organization_id, recommendation.id, approval_id,
        recommendation.store_id, object_row.id, object_row.platform_code, capability_id,
        object_row.semantic_profile_id, candidate.id, p_bundle_id, p_reservation_id,
        'abc-' || recommendation.id::text, candidate.currency_code, candidate.bid_unit_code,
        candidate.direction, candidate.candidate_basis, materiality,
        candidate.current_bid_amount, candidate.provider_normalized_amount,
        configuration.id, candidate.affected_set_digest, object_row.lineage_generation,
        recommendation.entity_version_digest, '{}'::jsonb,
        p_approval_expires_at, 'PENDING', 3, clock_timestamp(),
        clock_timestamp(), clock_timestamp());

    -- The authority snapshot is stamped by the bind trigger. Re-deriving it here
    -- and comparing is what proves nothing moved between the checks above and
    -- the row that was written.
    IF NOT ops.ad_bid_command_authority_matches(command_id) THEN
        RAISE EXCEPTION 'the command does not describe the decision it was approved for'
            USING ERRCODE = 'MO092';
    END IF;

    INSERT INTO ops.metadata_audit_event (
        id, actor_type, actor_id, source_domain, action, entity_type, entity_id,
        change_summary, reason, correlation_id)
    VALUES (gen_random_uuid(), 'OPERATOR', p_actor_id::text, 'marketplaceintegration',
        'COMMAND_TRANSITION', 'ad-bid-command', command_id,
        jsonb_build_object('direction', jsonb_build_object('previous', NULL,
            'current', candidate.direction)),
        'advertising bid command created from an approved candidate', p_correlation_id);

    RETURN command_id;
END;
$$;

CREATE FUNCTION ops.create_ad_bundle_draft(p_content jsonb, p_proof text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'iam', 'pg_temp'
    AS $$
DECLARE b ops.ad_decision_policy_bundle%ROWTYPE; g iam.ad_invocation_grant%ROWTYPE;
BEGIN
 SELECT * INTO b FROM jsonb_populate_record(NULL::ops.ad_decision_policy_bundle,p_content);
 g:=ops.consume_ad_control_invocation(p_proof,'BUNDLE_DRAFT',b.id,(p_content->>'gate_scope_reference')::uuid);
 IF b.organization_id<>g.organization_id OR NOT ops.ad_actor_has_role_scope(g.actor_user_id,b.organization_id,
 b.store_id,'OPS_LEAD','ADVERTISING_POLICY_MANAGE') THEN
  RAISE EXCEPTION 'scoped Bundle policy publisher required' USING ERRCODE='MO092'; END IF;
 b.status:='DRAFT'; b.validation_state:='PENDING'; b.validation_failure_codes:=ARRAY['NOT_VALIDATED'];
 b.activated_by_user_id:=g.actor_user_id;b.endorsed_by_user_id:=NULL;b.approved_by_user_id:=NULL;
 b.gate_authority_id:=NULL;b.security_attestation_present:=coalesce(b.security_attestation_present,false);b.version:=0;b.created_at:=clock_timestamp();b.updated_at:=clock_timestamp();
 INSERT INTO ops.ad_decision_policy_bundle SELECT b.*;
 RETURN b.id;
END $$;

CREATE FUNCTION ops.create_lc_description_command(p_action_id uuid, p_actor_id uuid, p_expected_version bigint, p_correlation_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'platform', 'iam', 'pg_temp'
    AS $$
DECLARE
    action      ops.lc_action%ROWTYPE;
    binding     ops.lc_action_binding%ROWTYPE;
    launch      ops.lc_launch%ROWTYPE;
    approval    ops.approval_decision%ROWTYPE;
    listing     core.platform_listing%ROWTYPE;
    observation core.lc_description_observation%ROWTYPE;
    capability  uuid;
    existing    uuid;
    command_id  uuid;
    rule        text;
    bounds      jsonb;
    gaps        text[];
BEGIN
    IF p_correlation_id IS NULL OR length(btrim(p_correlation_id)) NOT BETWEEN 1 AND 128 THEN
        RAISE EXCEPTION 'a correlation identifier is required' USING ERRCODE = 'MO092';
    END IF;
    SELECT * INTO action FROM ops.lc_action WHERE id = p_action_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'action does not exist' USING ERRCODE = 'MO090'; END IF;
    IF action.version <> p_expected_version THEN
        RAISE EXCEPTION 'the action changed since it was read' USING ERRCODE = 'MO090';
    END IF;
    IF NOT ops.lc_actor_holds_action(p_actor_id, action.organization_id, action.store_id, 'LISTING_ACTION_LAUNCH') THEN
        RAISE EXCEPTION 'the actor cannot access the description execution here' USING ERRCODE = 'MO092';
    END IF;
    SELECT id INTO existing FROM ops.lc_description_command WHERE action_id = p_action_id;
    IF existing IS NOT NULL THEN RETURN existing; END IF;
    SELECT * INTO launch FROM ops.lc_launch WHERE action_id=p_action_id;
    IF NOT FOUND OR launch.created_transaction_id IS DISTINCT FROM txid_current()
        OR launch.launched_by_user_id<>p_actor_id THEN
        RAISE EXCEPTION 'a new description command is created only in its authenticated launch transaction'
            USING ERRCODE='MO092';
    END IF;

    IF action.action_kind <> 'LISTING_DESCRIPTION_CHANGE' OR action.execution_path <> 'API'
        OR action.state <> 'LAUNCHED' THEN
        RAISE EXCEPTION 'only a launched description change on the API path becomes a command'
            USING ERRCODE = 'MO092';
    END IF;
    IF NOT ops.lc_actor_holds_action(p_actor_id, action.organization_id, action.store_id, 'LISTING_ACTION_LAUNCH') THEN
        RAISE EXCEPTION 'the actor cannot create a description command here' USING ERRCODE = 'MO092';
    END IF;
    IF action.kiz_marked_declared IS NULL THEN
        RAISE EXCEPTION 'the marking declaration is stated before a description is written'
            USING ERRCODE = 'MO092';
    END IF;
    gaps := ops.lc_binding_gaps(p_action_id);
    IF cardinality(gaps) > 0 THEN
        RAISE EXCEPTION 'the binding no longer applies: %', array_to_string(gaps, ',') USING ERRCODE = 'MO092';
    END IF;
    SELECT * INTO binding FROM ops.lc_action_binding WHERE action_id = p_action_id;
    SELECT * INTO launch FROM ops.lc_launch WHERE action_id = p_action_id;
    SELECT * INTO approval FROM ops.approval_decision WHERE id = binding.approval_decision_id;
    SELECT * INTO listing FROM core.platform_listing WHERE id = action.platform_listing_id;
    SELECT * INTO observation FROM core.lc_description_observation
     WHERE id = action.current_description_observation_id;
    IF observation.text_digest IS DISTINCT FROM binding.current_text_digest THEN
        RAISE EXCEPTION 'the captured prior text is not the bound current text' USING ERRCODE = 'MO092';
    END IF;

    -- The capability must be described. Being verified is the gate's question,
    -- asked at lease and again before any socket; here a command that could
    -- never name a capability is refused rather than created.
    SELECT cap.id INTO capability FROM platform.platform_capability cap
     WHERE cap.platform_code = listing.platform_code AND cap.capability_code = 'listing-description-change';
    IF capability IS NULL THEN
        RAISE EXCEPTION 'no description write capability is described for this platform'
            USING ERRCODE = 'MO092';
    END IF;

    SELECT v.value_text INTO rule FROM core.lc_calibration_value v
     WHERE v.package_id = binding.calibration_package_id AND v.category_code = 'REPRESENTATION_EQUIVALENCE_RULE';
    SELECT v.value_json INTO bounds FROM core.lc_calibration_value v
     WHERE v.package_id = binding.calibration_package_id AND v.category_code = 'DESCRIPTION_LENGTH_RULE';
    IF rule IS NULL OR bounds IS NULL OR (bounds ->> 'min') IS NULL OR (bounds ->> 'max') IS NULL THEN
        RAISE EXCEPTION 'the calibration package does not state the equivalence rule and length bound'
            USING ERRCODE = 'MO092';
    END IF;

    command_id := gen_random_uuid();
    INSERT INTO ops.lc_description_command (
        id, organization_id, recommendation_id, approval_decision_id, action_id, launch_id, binding_id,
        store_id, platform_listing_id, platform_code, capability_id, idempotency_key,
        prior_text, prior_text_digest, target_text, target_text_digest, kiz_marked_declared,
        equivalence_rule, length_bound_min, length_bound_max, affected_set_digest,
        approval_expires_at, state, retry_budget_remaining, created_at, updated_at)
    VALUES (command_id, action.organization_id, action.recommendation_id, approval.id, action.id,
        launch.id, binding.id, action.store_id, action.platform_listing_id, listing.platform_code,
        capability, 'lcd-' || replace(action.id::text, '-', ''),
        nullif(observation.description_text, ''), observation.text_digest,
        action.target_text, action.target_text_digest, action.kiz_marked_declared,
        rule, (bounds ->> 'min')::integer, (bounds ->> 'max')::integer, action.affected_set_digest,
        binding.expires_at, 'PENDING', 3, clock_timestamp(), clock_timestamp());
    RETURN command_id;
END;
$$;

CREATE FUNCTION ops.create_price_command(p_recommendation_id uuid, p_expected_version bigint, p_actor_id uuid, p_correlation_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    r ops.recommendation%ROWTYPE;
    a ops.approval_decision%ROWTYPE;
    snapshot jsonb;
    capability uuid;
    command_id uuid;
    target numeric;
    fulfillment_mode text;
BEGIN
    SELECT * INTO r FROM ops.recommendation WHERE id = p_recommendation_id FOR UPDATE;
    IF r.id IS NULL OR r.version IS DISTINCT FROM p_expected_version
       OR p_correlation_id IS NULL OR length(btrim(p_correlation_id)) NOT BETWEEN 1 AND 128
       OR NOT EXISTS (
           SELECT 1 FROM iam.user_account u
           JOIN iam.user_role_assignment role ON role.user_id = u.id AND role.status = 'ACTIVE'
           JOIN iam.business_role_action_scope action ON action.role_code = role.role_code
           JOIN iam.user_scope_grant grant_row ON grant_row.user_id = u.id
           JOIN core.store s ON s.id = r.store_id AND s.organization_id = u.organization_id
           JOIN core.marketplace_account account ON account.id = s.marketplace_account_id
            WHERE u.id = p_actor_id AND u.status = 'ACTIVE'
              AND u.organization_id = r.organization_id
              AND action.action_code = 'PRICE_CHANGE_APPROVE'
              AND role.effective_from <= clock_timestamp()
              AND (role.effective_to IS NULL OR role.effective_to > clock_timestamp())
              AND grant_row.action_code = action.action_code AND grant_row.status = 'ACTIVE'
              AND grant_row.effective_from <= clock_timestamp()
              AND (grant_row.effective_to IS NULL OR grant_row.effective_to > clock_timestamp())
              AND (grant_row.organization_ref_id = r.organization_id
                   OR grant_row.store_ref_id = r.store_id
                   OR grant_row.marketplace_account_ref_id = account.id
                   OR grant_row.legal_entity_ref_id = account.legal_entity_id)) THEN
        RAISE EXCEPTION 'command actor, scope or version invalid' USING ERRCODE = 'MO032';
    END IF;
    SELECT id INTO command_id FROM ops.price_command WHERE recommendation_id = r.id;
    IF command_id IS NOT NULL THEN RETURN command_id; END IF;
    IF r.state NOT IN ('APPROVED', 'POLICY_AUTHORIZED')
       OR r.action_kind <> 'PRICE_CHANGE'
       OR r.subject_kind <> 'PLATFORM_LISTING_VARIANT'
       OR r.valid_until <= clock_timestamp()
       OR NOT ops.price_change_parameter_contract_is_valid(r.proposed_parameters) THEN
        RAISE EXCEPTION 'proposal is not an executable price change' USING ERRCODE = 'MO032';
    END IF;
    snapshot := ops.price_authority_snapshot(r.id);
    SELECT * INTO a FROM ops.approval_decision
     WHERE recommendation_id = r.id AND decision IN ('APPROVED', 'POLICY_AUTHORIZED')
       AND scope_expires_at > clock_timestamp() AND authority_snapshot = snapshot;
    SELECT id INTO capability FROM platform.platform_capability
     WHERE platform_code = snapshot ->> 'platformCode' AND capability_code = 'price-change'
       AND read_write_class = 'WRITE' AND verification_state = 'VERIFIED'
       AND status = 'ACTIVE' AND deprecated_at IS NULL;
    fulfillment_mode := snapshot #>> '{economics,fulfillmentModeCode}';
    IF a.id IS NULL OR capability IS NULL OR snapshot #>> '{prior,id}' IS NULL
       OR snapshot #>> '{mapping,id}' IS NULL OR snapshot #>> '{policy,id}' IS NULL
       OR fulfillment_mode IS NULL OR fulfillment_mode = 'UNKNOWN'
       OR snapshot ->> 'currentEntityDigest' IS DISTINCT FROM r.entity_version_digest
       OR NOT ops.r2_price_authority_is_current(snapshot, statement_timestamp()) THEN
        RAISE EXCEPTION 'current authorization or canonical facts missing'
            USING ERRCODE = 'MO032';
    END IF;
    target := (r.proposed_parameters ->> 'targetPrice')::numeric;
    command_id := gen_random_uuid();
    INSERT INTO ops.price_command (
        id, organization_id, recommendation_id, approval_decision_id,
        store_id, platform_listing_variant_id, platform_code, capability_id,
        idempotency_key, currency_code, prior_price, target_price,
        prior_price_observation_id, entity_version_digest, fulfillment_mode_code,
        state, retry_budget_remaining, next_attempt_at, created_at, updated_at)
    VALUES (command_id, r.organization_id, r.id, a.id, r.store_id, r.subject_id,
        snapshot ->> 'platformCode', capability, 'pc-' || r.id::text,
        snapshot #>> '{prior,currency}', (snapshot #>> '{prior,price}')::numeric, target,
        (snapshot #>> '{prior,id}')::uuid, r.entity_version_digest, fulfillment_mode,
        'PENDING', 3, clock_timestamp(), clock_timestamp(), clock_timestamp());
    IF NOT ops.price_command_authority_matches(command_id) THEN
        RAISE EXCEPTION 'command inputs do not match approved authority' USING ERRCODE = 'MO032';
    END IF;
    INSERT INTO ops.metadata_audit_event (
        id,actor_type,actor_id,source_domain,action,entity_type,entity_id,
        entity_code,change_summary,correlation_id)
    VALUES (gen_random_uuid(),'OPERATOR',p_actor_id::text,'marketplaceintegration',
        'COMMAND_TRANSITION','price-command',command_id,'pc-'||r.id::text,
        jsonb_build_object('recommendationId',jsonb_build_object(
            'oldValue',NULL,'newValue',r.id::text)),p_correlation_id);
    RETURN command_id;
END;
$$;

CREATE FUNCTION ops.decide_ad_manual_packet(p_packet uuid, p_expected bigint, p_approve boolean, p_proof text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'iam', 'pg_temp'
    AS $$
DECLARE packet ops.ad_manual_execution_packet%ROWTYPE; g iam.ad_invocation_grant%ROWTYPE; role_code text; action_code text;
BEGIN
 SELECT * INTO packet FROM ops.ad_manual_execution_packet WHERE id=p_packet FOR UPDATE;
 g:=ops.consume_ad_control_invocation(p_proof,CASE WHEN p_approve THEN 'MANUAL_PACKET_APPROVE' ELSE 'MANUAL_PACKET_ENDORSE' END,p_packet,p_packet);
 role_code:=CASE WHEN p_approve THEN 'OWNER' ELSE 'OPS_LEAD' END;
 action_code:=CASE WHEN p_approve THEN 'ADVERTISING_MANUAL_APPROVE' ELSE 'ADVERTISING_MANUAL_ENDORSE' END;
 IF packet.id IS NULL OR packet.version<>p_expected OR g.organization_id<>packet.organization_id
 OR g.actor_user_id=packet.maker_user_id OR (p_approve AND g.actor_user_id=packet.endorser_user_id)
 OR packet.state<>(CASE WHEN p_approve THEN 'MANUAL_PACKET_ENDORSED' ELSE 'MANUAL_PACKET_DRAFT' END)
 OR NOT coalesce(ops.ad_manual_proposal_current(packet.proposal_id),false)
 OR NOT EXISTS(SELECT 1 FROM ops.ad_outcome_baseline b WHERE b.id=packet.outcome_baseline_id AND b.manual_proposal_id=packet.proposal_id AND b.state='COMPLETE' AND b.valid_until>clock_timestamp()
   AND ops.ad_outcome_baseline_is_canonical(b.id,clock_timestamp()) IS TRUE
   AND cardinality(ops.ad_action_isolation_failures(b.affected_set_id,b.id,clock_timestamp()))=0)
 OR NOT ops.ad_manual_actor_scoped(g.actor_user_id,packet.organization_id,packet.store_id,packet.affected_set_id,role_code,action_code)
 OR NOT ops.ad_manual_actor_scoped(g.actor_user_id,packet.organization_id,packet.store_id,packet.affected_set_id,
   role_code,'ADVERTISING_DECISION_EVIDENCE_VIEW') THEN RAISE EXCEPTION 'manual approval scope, independence or authority denied' USING ERRCODE='MO064'; END IF;
 UPDATE ops.ad_manual_execution_packet SET state=CASE WHEN p_approve THEN 'MANUAL_PACKET_ISSUED' ELSE 'MANUAL_PACKET_ENDORSED' END,
   endorser_user_id=CASE WHEN p_approve THEN endorser_user_id ELSE g.actor_user_id END,
   approver_user_id=CASE WHEN p_approve THEN g.actor_user_id ELSE NULL END,
   updated_at=clock_timestamp(),version=version+1 WHERE id=p_packet;
END $$;

CREATE FUNCTION ops.default_availability_case_original_action_due_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.original_action_due_at IS NULL THEN
        NEW.original_action_due_at := NEW.action_due_at;
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.defer_ad_bid_observation(p_command uuid, p_fence bigint, p_owner text, p_seconds integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$ BEGIN
 UPDATE ops.ad_bid_command SET lease_owner=NULL,lease_expires_at=NULL,
 next_attempt_at=clock_timestamp()+make_interval(secs=>greatest(1,least(p_seconds,900))),updated_at=clock_timestamp()
 WHERE id=p_command AND fence_token=p_fence AND lease_owner=p_owner
 AND lease_expires_at>clock_timestamp() AND state IN ('PLATFORM_PENDING','COMPENSATION_PENDING')
 AND NOT EXISTS(SELECT 1 FROM ops.ad_bid_command_attempt pending_attempt
  WHERE pending_attempt.command_id=p_command AND pending_attempt.fence_token=p_fence
   AND pending_attempt.outcome_class='IN_FLIGHT');
 IF NOT FOUND THEN RAISE EXCEPTION 'current observation lease required' USING ERRCODE='MO090'; END IF;
END $$;

CREATE FUNCTION ops.defer_lc_description_observation(p_command_id uuid, p_expected_fence bigint, p_owner text, p_seconds integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE command ops.lc_description_command%ROWTYPE;
BEGIN
    SELECT * INTO command FROM ops.lc_description_command WHERE id=p_command_id FOR UPDATE;
    IF command.id IS NULL OR command.fence_token<>p_expected_fence
        OR command.lease_owner IS DISTINCT FROM p_owner
        OR command.lease_expires_at IS NULL OR command.lease_expires_at<=clock_timestamp()
        OR command.state NOT IN ('PLATFORM_PENDING','COMPENSATION_PENDING','READBACK_PENDING') THEN
        RAISE EXCEPTION 'the observation lease that would be deferred is not current' USING ERRCODE='MO090';
    END IF;
    IF p_seconds IS NULL OR p_seconds<1 THEN
        RAISE EXCEPTION 'observation delay must be positive' USING ERRCODE='MO093';
    END IF;
    IF command.state='READBACK_PENDING' THEN
        PERFORM ops.transition_lc_description_command(p_command_id,p_expected_fence,p_owner,
            'UNKNOWN_REQUIRES_READBACK',NULL,NULL,NULL);
    END IF;
    UPDATE ops.lc_description_command
       SET lease_owner=NULL,lease_expires_at=NULL,
           requested_operation=CASE WHEN command.state='READBACK_PENDING' THEN 'READBACK' ELSE requested_operation END,
           next_attempt_at=greatest(provider_not_before,clock_timestamp()+make_interval(secs=>p_seconds)),
           updated_at=clock_timestamp()
     WHERE id=p_command_id;
END;
$$;

CREATE FUNCTION ops.deliver_due_ad_recalculations(p_now timestamp with time zone, p_limit integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
DECLARE row ops.ad_recalculation_due; delivered integer:=0;
BEGIN
    FOR row IN SELECT * FROM ops.ad_recalculation_due WHERE delivered_at IS NULL AND due_at<=p_now
        ORDER BY due_at,id LIMIT greatest(1,least(p_limit,10000)) FOR UPDATE SKIP LOCKED
    LOOP
        PERFORM ops.enqueue_ad_change(row.organization_id,row.ad_native_object_id,row.trigger_class,row.source_reference,row.due_at);
        UPDATE ops.ad_recalculation_due SET delivered_at=clock_timestamp() WHERE id=row.id;
        delivered:=delivered+1;
    END LOOP;
    RETURN delivered;
END $$;

CREATE FUNCTION ops.endorse_ad_bundle(p_bundle uuid, p_gate uuid, p_proof text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'iam', 'pg_temp'
    AS $$
DECLARE b ops.ad_decision_policy_bundle%ROWTYPE; g iam.ad_invocation_grant%ROWTYPE;
BEGIN
 g:=ops.consume_ad_control_invocation(p_proof,'BUNDLE_ENDORSE',p_bundle,p_gate);
 SELECT * INTO b FROM ops.ad_decision_policy_bundle WHERE id=p_bundle FOR UPDATE;
 IF b.status<>'DRAFT' OR b.activated_by_user_id=g.actor_user_id OR NOT ops.ad_actor_has_role_scope(g.actor_user_id,
 b.organization_id,b.store_id,'OPS_LEAD','ADVERTISING_POLICY_MANAGE')
 OR b.gate_scope_reference IS DISTINCT FROM p_gate::text
 OR NOT EXISTS(SELECT 1 FROM ops.ad_gate_authority gate WHERE gate.id=p_gate AND gate.bundle_id=b.id
   AND gate.organization_id=b.organization_id AND gate.status='ACTIVE') THEN
  RAISE EXCEPTION 'distinct scoped Bundle endorsement required' USING ERRCODE='MO092'; END IF;
 INSERT INTO ops.ad_bundle_endorsement VALUES(b.id,g.actor_user_id,clock_timestamp(),ops.ad_bundle_authority_snapshot(b.id)
   ||jsonb_build_object('proposedGate',(SELECT to_jsonb(gate) FROM ops.ad_gate_authority gate WHERE gate.id=p_gate)));
END $$;

CREATE FUNCTION ops.endorse_ad_compensation(p_preview uuid, p_proof text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'iam', 'pg_temp'
    AS $$
DECLARE a ops.ad_compensation_authorization%ROWTYPE; c ops.ad_bid_command%ROWTYPE; g iam.ad_invocation_grant%ROWTYPE;
BEGIN
 SELECT * INTO a FROM ops.ad_compensation_authorization WHERE id=p_preview FOR UPDATE;
 g:=ops.consume_ad_control_invocation(p_proof,'COMPENSATION_ENDORSE',a.command_id,p_preview);
 SELECT * INTO c FROM ops.ad_bid_command WHERE id=a.command_id;
 IF a.endorser_user_id IS NOT NULL OR a.preview_expires_at<=clock_timestamp() OR g.actor_user_id=a.maker_user_id
 OR NOT ops.ad_actor_has_role_scope(g.actor_user_id,a.organization_id,c.store_id,'OPS_LEAD','AD_BID_CHANGE_ENDORSE')
 OR NOT ops.ad_actor_covers_affected_set(g.actor_user_id,c.organization_id,
   (SELECT affected_set_id FROM ops.ad_action_reservation WHERE id=c.reservation_id),'AD_BID_CHANGE_ENDORSE') THEN
  RAISE EXCEPTION 'distinct scoped Operations Lead endorsement required' USING ERRCODE='MO094'; END IF;
 UPDATE ops.ad_compensation_authorization SET endorser_user_id=g.actor_user_id,endorsed_at=clock_timestamp() WHERE id=p_preview;
END $$;

CREATE FUNCTION ops.enforce_availability_exception_delegation_revocation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.revoked_at IS NOT NULL THEN
        RAISE EXCEPTION 'availability exception delegation is already revoked';
    END IF;
    IF NEW.id IS DISTINCT FROM OLD.id
       OR NEW.organization_id IS DISTINCT FROM OLD.organization_id
       OR NEW.delegation_reference IS DISTINCT FROM OLD.delegation_reference
       OR NEW.delegate_user_id IS DISTINCT FROM OLD.delegate_user_id
       OR NEW.delegated_role_code IS DISTINCT FROM OLD.delegated_role_code
       OR NEW.granted_by_user_id IS DISTINCT FROM OLD.granted_by_user_id
       OR NEW.granted_by_role_code IS DISTINCT FROM OLD.granted_by_role_code
       OR NEW.effective_from IS DISTINCT FROM OLD.effective_from
       OR NEW.effective_to IS DISTINCT FROM OLD.effective_to
       OR NEW.evidence_reference IS DISTINCT FROM OLD.evidence_reference
       OR NEW.granted_at IS DISTINCT FROM OLD.granted_at
       OR NEW.correlation_id IS DISTINCT FROM OLD.correlation_id THEN
        RAISE EXCEPTION 'availability exception delegation grant is immutable';
    END IF;
    IF NEW.revoked_at IS NULL OR NEW.revoked_by_user_id IS NULL
       OR NEW.revocation_reason IS NULL THEN
        RAISE EXCEPTION 'availability exception delegation update must be a revocation';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.enqueue_ad_change(p_org uuid, p_object uuid, p_class text, p_reference text, p_accepted timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
BEGIN
    INSERT INTO ops.ad_recalculation_request(id,organization_id,ad_native_object_id,trigger_class,
        trigger_reference,fact_accepted_at,requested_at,state,correlation_id)
    VALUES(gen_random_uuid(),p_org,p_object,p_class,left(p_reference,240),p_accepted,clock_timestamp(),'PENDING',
        'ad-change:'||gen_random_uuid())
    ON CONFLICT(organization_id,ad_native_object_id) WHERE state IN ('PENDING','LEASED')
    DO UPDATE SET fact_accepted_at=least(ops.ad_recalculation_request.fact_accepted_at,EXCLUDED.fact_accepted_at),
        latest_fact_accepted_at=greatest(ops.ad_recalculation_request.latest_fact_accepted_at,EXCLUDED.fact_accepted_at),
        next_fact_accepted_at=CASE WHEN ops.ad_recalculation_request.state='LEASED'
            AND EXCLUDED.fact_accepted_at>ops.ad_recalculation_request.calculation_as_of
            THEN least(coalesce(ops.ad_recalculation_request.next_fact_accepted_at,EXCLUDED.fact_accepted_at),EXCLUDED.fact_accepted_at)
            ELSE ops.ad_recalculation_request.next_fact_accepted_at END,
        version=ops.ad_recalculation_request.version+1;
END $$;

CREATE FUNCTION ops.enqueue_ingestion_run(p_run_id uuid, p_job_id uuid, p_run_kind text, p_window_from timestamp with time zone, p_window_to timestamp with time zone, p_max_claims integer DEFAULT 4) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    job_state text;
BEGIN
    SELECT job.status INTO job_state
      FROM platform.ingestion_job AS job
     WHERE job.id = p_job_id;

    IF job_state IS DISTINCT FROM 'ACTIVE' THEN
        RAISE EXCEPTION 'job % is not active', p_job_id
            USING ERRCODE = 'MO043';
    END IF;

    BEGIN
        INSERT INTO ops.ingestion_run (
            id, job_id, state, fence_token, lease_owner, lease_expires_at,
            attempt_no, last_call_seq, run_kind, window_from, window_to, max_claims,
            created_at, updated_at)
        VALUES (p_run_id, p_job_id, 'QUEUED', 1, NULL, NULL,
            0, 0, p_run_kind, p_window_from, p_window_to, p_max_claims,
            clock_timestamp(), clock_timestamp());
    EXCEPTION WHEN unique_violation THEN
        RAISE EXCEPTION 'job % already has a live run', p_job_id
            USING ERRCODE = 'MO040';
    END;

    -- A job acquires nothing until it has a cursor to advance, so the
    -- checkpoint is created with the run rather than by a separate step that
    -- could be forgotten.
    INSERT INTO ops.ingestion_checkpoint (job_id, strategy, position_value,
                                          checkpoint_version, updated_at)
    SELECT p_job_id, endpoint.pagination_model, NULL, 0, clock_timestamp()
      FROM platform.ingestion_job AS job
      JOIN platform.platform_endpoint AS endpoint ON endpoint.id = job.endpoint_id
     WHERE job.id = p_job_id
    ON CONFLICT (job_id) DO NOTHING;

    RETURN p_run_id;
END;
$$;

CREATE FUNCTION ops.evaluate_ad_bid_compensation_gate(p_command uuid) RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'platform', 'pg_temp'
    AS $$
DECLARE a ops.ad_compensation_authorization%ROWTYPE; c ops.ad_bid_command%ROWTYPE; g ops.ad_gate_authority%ROWTYPE;
 reasons text[]:='{}';
BEGIN
 SELECT * INTO c FROM ops.ad_bid_command WHERE id=p_command;
 SELECT * INTO a FROM ops.ad_compensation_authorization WHERE command_id=p_command
 ORDER BY approved_at DESC NULLS LAST,previewed_at DESC,id DESC LIMIT 1;
 SELECT gate.* INTO g FROM ops.ad_gate_authority gate JOIN ops.ad_decision_policy_bundle b
 ON b.gate_authority_id=gate.id WHERE b.id=a.bundle_id;
 IF a.id IS NULL OR a.owner_user_id IS NULL OR a.expires_at<=statement_timestamp()
 OR EXISTS(SELECT 1 FROM ops.ad_compensation_invalidation invalidated WHERE invalidated.compensation_id=a.id)
 OR a.preview_snapshot IS DISTINCT FROM ops.ad_bundle_authority_snapshot(a.bundle_id)
 OR a.captured_prior_bid<>c.prior_bid_amount OR a.current_owner_bid<>c.target_bid_amount
 OR a.reservation_id<>c.reservation_id OR a.affected_set_digest<>c.affected_set_digest THEN
  reasons:=array_append(reasons,'EXACT_COMPENSATION_APPROVAL_ABSENT_OR_STALE'); END IF;
 IF g.id IS NULL OR g.status<>'ACTIVE' OR g.direction<>'EXACT_PRIOR_BID_COMPENSATION'
 OR g.store_id<>c.store_id OR NOT c.ad_native_object_id=ANY(g.native_object_ids)
 OR ops.ad_nonnegative_numeric(g.exact_object_values#>>ARRAY[c.ad_native_object_id::text,'currentBid']) IS DISTINCT FROM c.target_bid_amount
 OR ops.ad_nonnegative_numeric(g.exact_object_values#>>ARRAY[c.ad_native_object_id::text,'targetBid']) IS DISTINCT FROM c.prior_bid_amount
 OR (g.exact_object_values#>>ARRAY[c.ad_native_object_id::text,'bidUnitCode']) IS DISTINCT FROM c.bid_unit_code
 OR (g.exact_object_values#>>ARRAY[c.ad_native_object_id::text,'currencyCode']) IS DISTINCT FROM c.currency_code
 OR abs(c.target_bid_amount-c.prior_bid_amount)/(CASE c.bid_unit_code WHEN 'CURRENCY_MINOR' THEN 100 ELSE 1 END)>g.max_bid_change_amount
 OR (SELECT count(*) FROM ops.ad_compensation_authorization accepted WHERE accepted.bundle_id=a.bundle_id
      AND accepted.approved_at IS NOT NULL)>g.max_commands
 OR g.valid_from>statement_timestamp() OR g.valid_until<=statement_timestamp() THEN
  reasons:=array_append(reasons,'COMPENSATION_GATE_SCOPE_ABSENT'); END IF;
 IF NOT EXISTS(SELECT 1 FROM platform.platform_capability cap WHERE cap.id=c.capability_id
 AND cap.status='ACTIVE' AND cap.verification_state='VERIFIED' AND cap.deprecated_at IS NULL)
 OR NOT EXISTS(SELECT 1 FROM ops.ad_action_reservation r WHERE r.id=c.reservation_id AND r.state='ACTIVE') THEN
  reasons:=array_append(reasons,'COMPENSATION_HARD_AUTHORITY_INVALID'); END IF;
 IF NOT ops.ad_actor_has_role_scope(a.owner_user_id,c.organization_id,c.store_id,'OWNER','AD_BID_CHANGE_APPROVE') THEN
  reasons:=array_append(reasons,'COMPENSATION_OWNER_AUTHORITY_EXPIRED'); END IF;
 IF NOT ops.ad_actor_covers_affected_set(a.owner_user_id,c.organization_id,
   (SELECT affected_set_id FROM ops.ad_action_reservation WHERE id=c.reservation_id),'AD_BID_CHANGE_APPROVE')
 OR NOT ops.ad_actor_has_role_scope(a.endorser_user_id,c.organization_id,c.store_id,'OPS_LEAD','AD_BID_CHANGE_ENDORSE')
 OR NOT ops.ad_actor_covers_affected_set(a.endorser_user_id,c.organization_id,
   (SELECT affected_set_id FROM ops.ad_action_reservation WHERE id=c.reservation_id),'AD_BID_CHANGE_ENDORSE') THEN
  reasons:=array_append(reasons,'COMPENSATION_AFFECTED_SCOPE_EXPIRED'); END IF;
 IF ops.ad_active_containment(c.organization_id,c.ad_native_object_id,c.store_id,c.platform_code,
  'ad-bid-change',c.affected_set_digest) && ARRAY['KILL_SWITCH_ACTIVE','CAPABILITY_QUARANTINED','AUTHORITY_VERSION_QUARANTINE'] THEN
  reasons:=array_append(reasons,'COMPENSATION_HARD_STOP_ACTIVE'); END IF;
 -- Only original business approval/bundle/outcome refusal is replaced by the
 -- new compensation approval. Every current platform and control stop remains.
 reasons:=reasons || ARRAY(SELECT reason FROM unnest(ops.evaluate_ad_bid_write_gate_base(c.id)) reason
 WHERE reason=ANY(ARRAY['CAPABILITY_NOT_VERIFIED','CAPABILITY_NOT_AVAILABLE_FOR_STORE','CAPABILITY_SWITCH_DISABLED',
 'GLOBAL_SWITCH_DISABLED','SCOPED_SWITCH_DISABLED','ENTITY_NOT_ALLOWLISTED','AFFECTED_SET_INCOMPLETE',
 'AFFECTED_SET_DIGEST_CHANGED','MAPPING_UNRESOLVED','MAPPING_CONFLICT_OPEN','RESERVATION_CONFLICT']));
 IF NOT EXISTS(SELECT 1 FROM platform.credential_metadata credential
 WHERE credential.marketplace_account_id=g.marketplace_account_id
 AND ops.ad_credential_authority_expiry(credential.id,c.store_id)>statement_timestamp()) THEN
  reasons:=array_append(reasons,'ADS_WRITE_CREDENTIAL_AUTHORITY_INVALID'); END IF;
 RETURN reasons || ops.ad_exposure_failures(c.organization_id,c.store_id,'EXACT_PRIOR_BID_COMPENSATION');
END $$;

CREATE FUNCTION ops.evaluate_ad_bid_write_gate(p_command uuid) RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE candidate uuid; reasons text[];
BEGIN
 reasons:=ops.evaluate_ad_bid_write_gate_before_economic_cause(p_command);
 SELECT candidate_id INTO candidate FROM ops.ad_bid_command WHERE id=p_command;
 IF NOT FOUND THEN RETURN reasons; END IF;
 RETURN reasons||ops.ad_economic_cause_bound_failures(candidate,statement_timestamp());
END $$;

CREATE FUNCTION ops.evaluate_ad_bid_write_gate_base(p_command_id uuid) RETURNS text[]
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'core', 'platform', 'iam', 'pg_temp'
    AS $$
DECLARE
    command      ops.ad_bid_command%ROWTYPE;
    envelope     core.ad_exposure_envelope%ROWTYPE;
    reasons      text[] := '{}';
    containment  text[];
    overlapping  uuid;
    active_count integer;
    unresolved   integer;
    cumulative   numeric;
BEGIN
    SELECT * INTO command FROM ops.ad_bid_command WHERE id = p_command_id;
    IF NOT FOUND THEN
        RETURN ARRAY['COMMAND_NOT_FOUND'];
    END IF;

    IF NOT ops.ad_bid_command_authority_matches(p_command_id) THEN
        reasons := array_append(reasons, 'COMMAND_AUTHORITY_MISMATCH');
    END IF;

    -- Capability verification, per platform and per store. Ozon evidence never
    -- authorizes Wildberries, which is why the subject status is checked for
    -- this store rather than for the platform.
    IF NOT EXISTS (
        SELECT 1 FROM platform.platform_capability cap
         WHERE cap.id = command.capability_id
           AND cap.capability_code = 'ad-bid-change'
           AND cap.read_write_class = 'WRITE'
           AND cap.verification_state = 'VERIFIED'
           AND cap.status = 'ACTIVE'
           AND cap.deprecated_at IS NULL) THEN
        reasons := array_append(reasons, 'CAPABILITY_NOT_VERIFIED');
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM platform.capability_subject_status s
         WHERE s.capability_id = command.capability_id
           AND s.store_id = command.store_id
           AND s.availability = 'AVAILABLE') THEN
        reasons := array_append(reasons, 'CAPABILITY_NOT_AVAILABLE_FOR_STORE');
    END IF;

    -- The feature flag, at its own scopes. Missing is off, at every scope.
    IF NOT EXISTS (
        SELECT 1 FROM platform.feature_flag f
         WHERE f.flag_code = 'ad-bid-change-write'
           AND f.scope_kind = 'CAPABILITY' AND f.capability_id=command.capability_id
           AND f.status='ACTIVE' AND f.state = 'ENABLED') THEN
        reasons := array_append(reasons, 'CAPABILITY_SWITCH_DISABLED');
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM platform.feature_flag f
         WHERE f.flag_code = 'ad-bid-change-write'
           AND f.scope_kind = 'GLOBAL' AND f.status='ACTIVE' AND f.state = 'ENABLED') THEN
        reasons := array_append(reasons, 'GLOBAL_SWITCH_DISABLED');
    END IF;
    IF EXISTS (
        SELECT 1 FROM platform.feature_flag f
         WHERE f.flag_code = 'ad-bid-change-write'
           AND f.status='ACTIVE' AND f.state = 'DISABLED'
           AND (f.scope_kind='PLATFORM' AND f.platform_code=command.platform_code
             OR f.scope_kind='STORE' AND f.store_id=command.store_id
             OR f.scope_kind='MARKETPLACE_ACCOUNT' AND f.marketplace_account_id=
                 (SELECT marketplace_account_id FROM core.store WHERE id=command.store_id))) THEN
        reasons := array_append(reasons, 'SCOPED_SWITCH_DISABLED');
    END IF;

    -- The entity allowlist. A Pilot that enabled a capability without naming the
    -- objects it may touch would be an unbounded Pilot.
    IF NOT EXISTS (
        SELECT 1 FROM ops.pilot_allowlist_entry entry
         WHERE entry.organization_id = command.organization_id
           AND entry.action_kind = 'AD_BID_CHANGE'
           AND entry.ad_native_object_id = command.ad_native_object_id
           AND entry.status = 'ACTIVE'
           AND entry.valid_from <= statement_timestamp()
           AND (entry.valid_until IS NULL OR entry.valid_until > statement_timestamp())) THEN
        reasons := array_append(reasons, 'ENTITY_NOT_ALLOWLISTED');
    END IF;

    -- Approval and its lease. Expiry is checked here and again at every later
    -- point, because waiting never extends it.
    IF NOT EXISTS (
        SELECT 1 FROM ops.approval_decision a
         WHERE a.id = command.approval_decision_id
           AND a.recommendation_id = command.recommendation_id
           AND a.decision IN ('APPROVED', 'POLICY_AUTHORIZED')
           AND a.scope_expires_at > statement_timestamp()) THEN
        reasons := array_append(reasons, 'AUTHORIZATION_INVALID_OR_EXPIRED');
    END IF;
    IF command.approval_expires_at <= statement_timestamp() THEN
        reasons := array_append(reasons, 'APPROVAL_LEASE_EXPIRED');
    END IF;

    -- The recommendation must still be the live one for this object and action.
    IF NOT EXISTS (
        SELECT 1 FROM ops.recommendation r
         WHERE r.id = command.recommendation_id
           AND r.state IN ('APPROVED', 'POLICY_AUTHORIZED', 'COMMAND_CREATED',
                           'EXECUTION_TRACKING')
           AND r.valid_until > statement_timestamp()) THEN
        reasons := array_append(reasons, 'RECOMMENDATION_STALE');
    END IF;

    -- The affected set has not moved under the approval.
    IF NOT EXISTS (
        SELECT 1 FROM core.ad_affected_set a
         WHERE a.organization_id = command.organization_id
           AND a.ad_native_object_id = command.ad_native_object_id
           AND a.affected_set_digest = command.affected_set_digest
           AND a.resolution_state = 'COMPLETE') THEN
        reasons := array_append(reasons, 'AFFECTED_SET_DIGEST_CHANGED');
    END IF;

    -- Mapping health for every variant this object promotes. An unresolved or
    -- conflicted mapping means we do not know whose sales this bid affects.
    IF EXISTS (
        SELECT 1 FROM core.ad_affected_set a
         CROSS JOIN LATERAL unnest(a.product_variant_ids) AS variant(id)
         WHERE a.organization_id = command.organization_id
           AND a.ad_native_object_id = command.ad_native_object_id
           AND a.affected_set_digest = command.affected_set_digest
           AND NOT EXISTS (
               SELECT 1 FROM core.listing_mapping m
                WHERE m.organization_id = a.organization_id
                  AND m.product_variant_id = variant.id
                  AND m.status = 'ACTIVE'
                  AND m.effective_from <= statement_timestamp()
                  AND (m.effective_to IS NULL OR m.effective_to > statement_timestamp()))) THEN
        reasons := array_append(reasons, 'MAPPING_UNRESOLVED');
    END IF;
    IF EXISTS (
        SELECT 1 FROM core.ad_affected_set a
         CROSS JOIN LATERAL unnest(a.product_variant_ids) AS variant(id)
          JOIN core.listing_mapping m
            ON m.organization_id = a.organization_id
           AND m.product_variant_id = variant.id
          JOIN core.mapping_conflict conflict
            ON conflict.platform_listing_variant_id = m.platform_listing_variant_id
           AND conflict.state = 'OPEN'
         WHERE a.organization_id = command.organization_id
           AND a.ad_native_object_id = command.ad_native_object_id
           AND a.affected_set_digest = command.affected_set_digest) THEN
        reasons := array_append(reasons, 'MAPPING_CONFLICT_OPEN');
    END IF;

    -- A passing execution guardrail bound to the same authority snapshot.
    IF NOT EXISTS (
        SELECT 1 FROM ops.guardrail_evaluation g
         WHERE g.recommendation_id = command.recommendation_id
           AND g.organization_id = command.organization_id
           AND g.purpose = 'EXECUTION'
           AND g.outcome = 'PASS') THEN
        reasons := array_append(reasons, 'GUARDRAIL_NOT_PASSED');
    END IF;

    -- The bundle: unique, complete, active, validated and covering this scope.
    IF NOT EXISTS (
        SELECT 1 FROM ops.ad_decision_policy_bundle b
         WHERE b.id = command.bundle_id
           AND b.status = 'ACTIVE'
           AND b.validation_state = 'VALIDATED'
           AND b.effective_from <= statement_timestamp()
           AND (b.effective_to IS NULL OR b.effective_to > statement_timestamp())) THEN
        reasons := array_append(reasons, 'BUNDLE_UNRESOLVED');
    ELSIF NOT EXISTS (
        SELECT 1 FROM ops.ad_decision_policy_bundle b
          JOIN core.ad_native_object obj
            ON obj.id = command.ad_native_object_id
           AND obj.organization_id = command.organization_id
         WHERE b.id = command.bundle_id
           AND b.store_id = command.store_id
           AND b.direction = command.direction
           AND b.candidate_basis = command.candidate_basis
           AND b.native_object_kind = obj.native_object_kind
           AND b.capability_code = 'ad-bid-change') THEN
        reasons := array_append(reasons, 'BUNDLE_SCOPE_EXCEEDED');
    END IF;

    -- Direction and candidate basis have to be the ones the bundle enabled.
    IF NOT EXISTS (
        SELECT 1 FROM ops.ad_decision_policy_bundle b
         WHERE b.id = command.bundle_id AND b.direction = command.direction) THEN
        reasons := array_append(reasons, 'DIRECTION_NOT_ENABLED');
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM ops.ad_decision_policy_bundle b
         WHERE b.id = command.bundle_id AND b.candidate_basis = command.candidate_basis) THEN
        reasons := array_append(reasons, 'CANDIDATE_BASIS_NOT_ENABLED');
    END IF;

    -- The Ordinary route exists only where a promotion record says so, and this
    -- Slice creates none. An ordinary-routed command therefore always refuses.
    IF command.materiality_route = 'ORDINARY_IMPACT' AND NOT ops.ad_ordinary_promotion_covers(
        command.bundle_id,command.ad_native_object_id,abs(command.target_bid_amount-command.prior_bid_amount) / CASE command.bid_unit_code WHEN 'CURRENCY_MINOR' THEN 100 ELSE 1 END) THEN
        reasons := array_append(reasons, 'ORDINARY_ROUTE_NOT_PROMOTED');
    END IF;
    IF command.materiality_route = 'MATERIALITY_UNRESOLVED' THEN
        reasons := array_append(reasons, 'MATERIALITY_UNRESOLVED');
    END IF;

    -- Containment, at every scope it can be held at.
    containment := ops.ad_active_containment(
        command.organization_id, command.ad_native_object_id, command.store_id,
        command.platform_code, 'ad-bid-change', command.affected_set_digest);
    IF 'KILL_SWITCH_ACTIVE' = ANY(containment) THEN
        reasons := array_append(reasons, 'KILL_SWITCH_ACTIVE');
    END IF;
    IF cardinality(containment) > 0
        AND NOT (containment = ARRAY['KILL_SWITCH_ACTIVE']) THEN
        reasons := array_append(reasons, 'QUARANTINE_ACTIVE');
    END IF;

    -- Reservation: this command must hold one, and nothing else may overlap it.
    IF NOT EXISTS (
        SELECT 1 FROM ops.ad_action_reservation res
         WHERE res.id = command.reservation_id
           AND res.state = 'ACTIVE'
           AND res.ad_native_object_id = command.ad_native_object_id) THEN
        reasons := array_append(reasons, 'RESERVATION_CONFLICT');
    ELSE
        SELECT o.reservation_id INTO overlapping
          FROM ops.ad_action_reservation res
         CROSS JOIN LATERAL ops.ad_overlapping_reservation(
             command.organization_id, res.product_variant_ids, command.ad_native_object_id) AS o
         WHERE res.id = command.reservation_id
         LIMIT 1;
        IF overlapping IS NOT NULL THEN
            reasons := array_append(reasons, 'RESERVATION_CONFLICT');
        END IF;
    END IF;

    -- Reservation admission and the gate share the same six independent axes.
    reasons := reasons || ops.ad_exposure_failures(command.organization_id,
        command.store_id, command.direction);

    RETURN reasons;
END;
$$;

CREATE FUNCTION ops.evaluate_ad_bid_write_gate_before_economic_cause(p_command uuid) RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'platform', 'iam', 'pg_temp'
    AS $$
DECLARE c ops.ad_bid_command%ROWTYPE; a ops.ad_action_authorization%ROWTYPE;
 g ops.ad_gate_authority%ROWTYPE; b ops.ad_decision_policy_bundle%ROWTYPE; reasons text[];
BEGIN
 SELECT * INTO c FROM ops.ad_bid_command WHERE id=p_command;
 IF NOT FOUND THEN RETURN ARRAY['COMMAND_NOT_FOUND']; END IF;
 reasons:=ops.evaluate_ad_bid_write_gate_base(p_command);
 IF EXISTS(SELECT 1 FROM ops.ad_accepted_exception exception JOIN ops.ad_bid_candidate candidate
 ON candidate.id=c.candidate_id WHERE exception.case_id=candidate.case_id
 AND exception.state='ACTIVE' AND exception.ended_at IS NULL) THEN
  reasons:=array_append(reasons,'ACCEPTED_EXCEPTION_ACTIVE'); END IF;
 SELECT * INTO a FROM ops.ad_action_authorization WHERE recommendation_id=c.recommendation_id;
 SELECT * INTO b FROM ops.ad_decision_policy_bundle WHERE id=c.bundle_id;
 SELECT * INTO g FROM ops.ad_gate_authority WHERE id=b.gate_authority_id;
 IF EXISTS(SELECT 1 FROM ops.ad_bid_candidate candidate JOIN mart.ad_case kase ON kase.id=candidate.case_id
 WHERE candidate.id=c.candidate_id
 AND cardinality(ops.ad_action_blockers(candidate.candidate_basis,candidate.cause_code,kase.blocker_codes))>0) THEN
  reasons:=array_append(reasons,'ACTION_EVIDENCE_BLOCKERS_UNRESOLVED'); END IF;
 IF a.id IS NULL OR a.expires_at<>c.approval_expires_at OR a.expires_at<=statement_timestamp()
 OR a.bundle_id<>c.bundle_id OR a.candidate_id<>c.candidate_id
 OR a.approval_decision_id<>c.approval_decision_id THEN
  reasons:=array_append(reasons,'SEALED_AUTHORIZATION_MISSING_OR_EXPIRED'); END IF;
 IF a.id IS NOT NULL AND (
  NOT ops.ad_actor_has_role_scope(a.final_approver_user_id,c.organization_id,c.store_id,
    CASE WHEN a.materiality_route='ORDINARY_IMPACT' THEN 'OPS_LEAD' ELSE 'OWNER' END,'AD_BID_CHANGE_APPROVE')
  OR NOT ops.ad_actor_has_role_scope(a.endorser_user_id,c.organization_id,c.store_id,'OPS_LEAD','AD_BID_CHANGE_ENDORSE')
  OR NOT ops.ad_actor_has_role_scope(a.maker_user_id,c.organization_id,c.store_id,'MARKETPLACE_OPERATOR','ADVERTISING_TASK_ACT')
  OR NOT ops.ad_actor_covers_affected_set(a.final_approver_user_id,c.organization_id,
    (SELECT affected_set_id FROM ops.ad_outcome_baseline WHERE id=a.outcome_baseline_id),'AD_BID_CHANGE_APPROVE')
  OR NOT ops.ad_actor_covers_affected_set(a.endorser_user_id,c.organization_id,
    (SELECT affected_set_id FROM ops.ad_outcome_baseline WHERE id=a.outcome_baseline_id),'AD_BID_CHANGE_ENDORSE')
  OR NOT ops.ad_actor_covers_affected_set(a.maker_user_id,c.organization_id,
    (SELECT affected_set_id FROM ops.ad_outcome_baseline WHERE id=a.outcome_baseline_id),'ADVERTISING_TASK_ACT')) THEN
  reasons:=array_append(reasons,'CURRENT_HUMAN_AUTHORITY_REVOKED'); END IF;
 IF c.outcome_baseline_id IS DISTINCT FROM a.outcome_baseline_id
 OR ops.ad_outcome_baseline_is_canonical(a.outcome_baseline_id,statement_timestamp()) IS NOT TRUE THEN
  reasons:=array_append(reasons,'CANONICAL_OUTCOME_BASELINE_AUTHORITY_INVALID'); END IF;
 reasons:=reasons||ops.ad_action_isolation_failures(
  (SELECT affected_set_id FROM ops.ad_outcome_baseline WHERE id=a.outcome_baseline_id),a.outcome_baseline_id,statement_timestamp());
 IF ops.ad_materiality_assessment(c.bundle_id,c.candidate_id)->>'route' IS DISTINCT FROM a.materiality_route THEN
  reasons:=array_append(reasons,'SEALED_MATERIALITY_ROUTE_CHANGED_OR_UNRESOLVED'); END IF;
 IF EXISTS(SELECT 1 FROM ops.ad_authority_invalidation i WHERE i.authorization_id=a.id) THEN
  reasons:=array_append(reasons,'AUTHORITY_PERMANENTLY_INVALIDATED'); END IF;
 IF a.authority_snapshot-'decisionEvidence' IS DISTINCT FROM ops.ad_bundle_authority_snapshot(c.bundle_id) THEN
  reasons:=array_append(reasons,'COMPLETE_AUTHORITY_SNAPSHOT_CHANGED'); END IF;
 IF a.authority_snapshot->'decisionEvidence' IS DISTINCT FROM (
  SELECT jsonb_agg(to_jsonb(evidence) ORDER BY evidence.evidence_kind)
  FROM ops.ad_bid_candidate candidate JOIN mart.ad_case kase ON kase.id=candidate.case_id
  JOIN mart.ad_case_purpose_evidence evidence ON evidence.case_id=kase.id AND evidence.calculation_id=kase.calculation_id
  WHERE candidate.id=c.candidate_id AND evidence.evidence_kind=ANY(
    ops.ad_required_action_evidence_kinds(candidate.candidate_basis,candidate.cause_code))
  AND evidence.decision_purpose=CASE WHEN c.direction='OPTIMIZATION_INCREASE'
    THEN 'OPTIMIZATION_BID_WRITE' ELSE 'PROTECTION_BID_WRITE' END) THEN
  reasons:=array_append(reasons,'ACTION_EVIDENCE_AUTHORITY_CHANGED'); END IF;
 IF NOT ops.ad_bid_execution_pass_matches_bundle(p_command) THEN
  reasons:=array_append(reasons,'GUARDRAIL_BUNDLE_MISMATCH'); END IF;
 IF g.id IS NULL OR g.status<>'ACTIVE' OR g.valid_from>statement_timestamp() OR g.valid_until<=statement_timestamp()
 OR g.organization_id<>c.organization_id OR g.store_id<>c.store_id OR g.platform_code<>c.platform_code
 OR g.capability_code<>'ad-bid-change' OR NOT c.ad_native_object_id=ANY(g.native_object_ids)
 OR g.bundle_id<>c.bundle_id OR g.direction<>c.direction OR g.candidate_basis<>c.candidate_basis
 OR g.currency_code<>c.currency_code
 OR NOT g.exact_object_values ? c.ad_native_object_id::text
 OR ops.ad_nonnegative_numeric(g.exact_object_values#>>ARRAY[c.ad_native_object_id::text,'currentBid']) IS DISTINCT FROM c.prior_bid_amount
 OR ops.ad_nonnegative_numeric(g.exact_object_values#>>ARRAY[c.ad_native_object_id::text,'targetBid']) IS DISTINCT FROM c.target_bid_amount
 OR (g.exact_object_values#>>ARRAY[c.ad_native_object_id::text,'currencyCode']) IS DISTINCT FROM c.currency_code
 OR (g.exact_object_values#>>ARRAY[c.ad_native_object_id::text,'bidUnitCode']) IS DISTINCT FROM c.bid_unit_code
 OR abs(c.target_bid_amount-c.prior_bid_amount) / (CASE c.bid_unit_code WHEN 'CURRENCY_MINOR' THEN 100 ELSE 1 END) >g.max_bid_change_amount
 OR (SELECT count(*) FROM ops.ad_bid_command other WHERE other.bundle_id=c.bundle_id)>g.max_commands THEN
  reasons:=array_append(reasons,'EXACT_GATE_AUTHORITY_ABSENT_OR_EXCEEDED'); END IF;
 IF NOT EXISTS(SELECT 1 FROM platform.credential_metadata cm
  WHERE cm.marketplace_account_id=g.marketplace_account_id AND cm.organization_id=c.organization_id
  AND cm.purpose_code='ADS_WRITE' AND cm.status='ACTIVE'
  AND ops.ad_credential_authority_expiry(cm.id,c.store_id)>statement_timestamp()
  AND (cm.scope_mode='ACCOUNT' OR EXISTS(SELECT 1 FROM platform.credential_store_scope cs
    WHERE cs.credential_id=cm.id AND cs.store_id=c.store_id))) THEN
  reasons:=array_append(reasons,'ADS_WRITE_CREDENTIAL_AUTHORITY_INVALID'); END IF;
 RETURN ARRAY(SELECT DISTINCT reason FROM unnest(reasons) reason ORDER BY reason);
END $$;

CREATE FUNCTION ops.evaluate_lc_description_write_gate(p_command_id uuid) RETURNS text[]
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'core', 'platform', 'iam', 'pg_temp'
    AS $$
DECLARE
    command ops.lc_description_command%ROWTYPE;
    reasons text[] := '{}';
    gaps    text[];
    latest  text;
    mutation_purpose text; shape jsonb;
BEGIN
    SELECT * INTO command FROM ops.lc_description_command WHERE id = p_command_id;
    IF NOT FOUND THEN RETURN ARRAY['COMMAND_NOT_FOUND']; END IF;

    IF NOT EXISTS (SELECT 1 FROM platform.platform_capability cap
                    WHERE cap.id = command.capability_id
                      AND cap.capability_code = 'listing-description-change'
                      AND cap.read_write_class = 'WRITE'
                      AND cap.verification_state = 'VERIFIED'
                      AND cap.status = 'ACTIVE' AND cap.deprecated_at IS NULL) THEN
        reasons := array_append(reasons, 'CAPABILITY_NOT_VERIFIED');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM platform.capability_subject_status s
                    WHERE s.capability_id = command.capability_id
                      AND s.store_id = command.store_id AND s.availability = 'AVAILABLE') THEN
        reasons := array_append(reasons, 'CAPABILITY_NOT_AVAILABLE_FOR_STORE');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM platform.feature_flag f
                    WHERE f.flag_code = 'listing-description-write'
                      AND f.scope_kind = 'CAPABILITY' AND f.capability_id = command.capability_id
                      AND f.flag_kind = 'WRITE_CAPABILITY' AND f.status = 'ACTIVE' AND f.state = 'ENABLED') THEN
        reasons := array_append(reasons, 'CAPABILITY_SWITCH_DISABLED');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM platform.feature_flag f
                    WHERE f.flag_code = 'listing-description-write'
                      AND f.scope_kind = 'GLOBAL' AND f.flag_kind = 'WRITE_CAPABILITY'
                      AND f.status = 'ACTIVE' AND f.state = 'ENABLED') THEN
        reasons := array_append(reasons, 'GLOBAL_SWITCH_DISABLED');
    END IF;
    IF EXISTS (SELECT 1 FROM platform.feature_flag f
                WHERE f.flag_code = 'listing-description-write'
                  AND f.status = 'ACTIVE' AND f.state = 'DISABLED'
                  AND ((f.scope_kind = 'PLATFORM' AND f.platform_code = command.platform_code)
                    OR (f.scope_kind = 'MARKETPLACE_ACCOUNT' AND f.marketplace_account_id =
                        (SELECT st.marketplace_account_id FROM core.store st WHERE st.id = command.store_id))
                    OR (f.scope_kind = 'STORE' AND f.store_id = command.store_id))) THEN
        reasons := array_append(reasons, 'SCOPED_SWITCH_DISABLED');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM ops.pilot_allowlist_entry entry
                    WHERE entry.organization_id = command.organization_id
                      AND entry.action_kind = 'LISTING_DESCRIPTION_CHANGE'
                      AND entry.platform_listing_id = command.platform_listing_id
                      AND entry.status = 'ACTIVE'
                      AND entry.valid_from <= statement_timestamp()
                      AND (entry.valid_until IS NULL OR entry.valid_until > statement_timestamp())) THEN
        reasons := array_append(reasons, 'ENTITY_NOT_ALLOWLISTED');
    END IF;
    -- A real write needs an active, exact-head-bound gate authority that names
    -- this listing and has production writes enabled. None exists.
    IF NOT EXISTS (SELECT 1 FROM ops.lc_gate_authority g
                    WHERE g.organization_id = command.organization_id
                      AND g.store_id = command.store_id
                      AND g.status = 'ACTIVE' AND g.production_write_enabled
                      AND command.platform_listing_id = ANY (g.platform_listing_ids)
                      AND g.valid_from <= statement_timestamp()
                      AND g.valid_until > statement_timestamp()) THEN
        reasons := array_append(reasons, 'PRODUCTION_WRITE_DISABLED');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM ops.approval_decision a
                    WHERE a.id = command.approval_decision_id
                      AND a.recommendation_id = command.recommendation_id
                      AND a.decision = 'APPROVED'
                      AND a.scope_expires_at > statement_timestamp()) THEN
        reasons := array_append(reasons, 'AUTHORIZATION_INVALID_OR_EXPIRED');
    END IF;
    IF command.approval_expires_at <= statement_timestamp() THEN
        reasons := array_append(reasons, 'APPROVAL_LEASE_EXPIRED');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM ops.lc_action a
                    WHERE a.id = command.action_id AND a.state = 'LAUNCHED') THEN
        reasons := array_append(reasons, 'ACTION_NOT_LAUNCHED');
    END IF;
    gaps := ops.lc_binding_gaps(command.action_id);
    IF cardinality(gaps) > 0 THEN
        reasons := reasons || gaps;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM ops.lc_exposure_occupation o
                    WHERE o.action_id = command.action_id AND o.state <> 'RELEASED') THEN
        reasons := array_append(reasons, 'ALLOWANCE_NOT_OCCUPIED');
    END IF;
    IF ops.lc_scope_contained(command.organization_id, command.platform_listing_id) THEN
        reasons := array_append(reasons, 'SCOPE_CONTAINED');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM ops.guardrail_evaluation g
                    JOIN ops.lc_action_binding b ON b.action_id = command.action_id
                   WHERE g.recommendation_id = command.recommendation_id
                     AND g.purpose = 'EXECUTION' AND g.outcome = 'PASS'
                     AND g.lc_calibration_package_id = b.calibration_package_id
                     AND g.lc_calibration_version = b.calibration_version) THEN
        reasons := array_append(reasons, 'EXECUTION_PASS_MISSING');
    END IF;
    SELECT CASE WHEN restores_command_id IS NULL THEN 'APPLY' ELSE 'RESTORE' END INTO mutation_purpose
      FROM ops.lc_action WHERE id=command.action_id;
    -- The verified operation names the description attribute it changes, so
    -- the request cannot be a whole-card import. Without it, nothing is sent.
    IF mutation_purpose='APPLY' AND NOT EXISTS (SELECT 1 FROM platform.capability_operation o
                    JOIN platform.platform_endpoint e ON e.id = o.endpoint_id
                   WHERE o.capability_id = command.capability_id AND o.operation = mutation_purpose
                     AND o.status = 'ACTIVE' AND o.verification_state = 'VERIFIED'
                     AND (coalesce(e.path_template, '') || coalesce(e.query_template, '')
                          || o.request_template) LIKE '%{descriptionAttributeKey}%') THEN
        reasons := array_append(reasons, 'NON_TARGET_FIELD_RISK');
    END IF;
    IF mutation_purpose='RESTORE' THEN
        shape:=platform.lc_description_operation_snapshot(command.capability_id,'RESTORE');
        IF shape IS NULL OR NOT platform.lc_description_request_guard_valid(
                shape #> '{operation,description_request_guard}',shape #>> '{operation,description_attribute_key}')
            OR shape #>> '{operation,description_request_guard,evidenceRef}' IS DISTINCT FROM shape #>> '{operation,evidence_ref}'
            OR nullif(shape #>> '{operation,conditional_write_header}','') IS NULL
            OR NOT EXISTS (SELECT 1 FROM platform.capability_operation readback
                WHERE readback.capability_id=command.capability_id AND readback.operation='READBACK'
                  AND readback.status='ACTIVE' AND readback.verification_state='VERIFIED'
                  AND nullif(readback.version_token_header,'') IS NOT NULL) THEN
            reasons:=array_append(reasons,'RESTORE_UNSUPPORTED');
        END IF;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM ops.lc_action a
                    WHERE a.id = command.action_id AND a.kiz_marked_declared IS NOT NULL) THEN
        reasons := array_append(reasons, 'KIZ_MARKED_UNDECLARED');
    END IF;
    IF length(command.target_text) NOT BETWEEN command.length_bound_min AND command.length_bound_max THEN
        reasons := array_append(reasons, 'TEXT_LENGTH_OUT_OF_BOUNDS');
    END IF;
    SELECT o.text_digest INTO latest FROM core.lc_description_observation o
     WHERE o.platform_listing_id = command.platform_listing_id
     ORDER BY o.observed_at DESC, o.acquired_at DESC LIMIT 1;
    IF latest IS DISTINCT FROM command.prior_text_digest
        AND command.state IN ('PENDING', 'LEASED', 'RETRY_WAIT') THEN
        reasons := array_append(reasons, 'PRIOR_TEXT_MOVED');
    END IF;
    RETURN reasons;
END;
$$;

CREATE FUNCTION ops.evaluate_price_write_gate(p_command_id uuid) RETURNS text[]
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    command_row   record;
    reasons       text[] := ARRAY[]::text[];
    now_instant   timestamptz := clock_timestamp();
BEGIN
    SELECT command.id, command.organization_id, command.store_id,
           command.platform_code, command.capability_id,
           command.platform_listing_variant_id, command.recommendation_id,
           command.approval_decision_id, command.target_price, command.prior_price,
           store.marketplace_account_id
      INTO command_row
      FROM ops.price_command AS command
      JOIN core.store AS store ON store.id = command.store_id
     WHERE command.id = p_command_id;

    IF command_row.id IS NULL THEN
        RETURN ARRAY['COMMAND_NOT_FOUND'];
    END IF;

    IF NOT ops.price_command_authority_matches(p_command_id) THEN
        reasons := array_append(reasons, 'COMMAND_AUTHORITY_MISMATCH');
    END IF;

    -- The capability itself must be verified against recorded evidence and
    -- available for this exact store.
    PERFORM 1
      FROM platform.platform_capability AS capability
     WHERE capability.id = command_row.capability_id
       AND capability.status = 'ACTIVE'
       AND capability.deprecated_at IS NULL
       AND capability.verification_state = 'VERIFIED';
    IF NOT FOUND
    THEN
        reasons := array_append(reasons, 'CAPABILITY_NOT_VERIFIED');
    END IF;

    PERFORM 1
      FROM platform.capability_subject_status AS subject
     WHERE subject.capability_id = command_row.capability_id
       AND subject.store_id = command_row.store_id
       AND subject.availability = 'AVAILABLE';
    IF NOT FOUND
    THEN
        reasons := array_append(reasons, 'CAPABILITY_NOT_AVAILABLE_FOR_STORE');
    END IF;

    -- The capability switch must be explicitly on, and no wider scope may be
    -- switched off. A missing flag is off, so an unconfigured scope blocks.
    PERFORM 1
      FROM platform.feature_flag AS flag
     WHERE flag.flag_code = 'price-change-write'
       AND flag.scope_kind = 'CAPABILITY'
       AND flag.capability_id = command_row.capability_id
       AND flag.status = 'ACTIVE'
       AND flag.state = 'ENABLED';
    IF NOT FOUND
    THEN
        reasons := array_append(reasons, 'CAPABILITY_SWITCH_DISABLED');
    END IF;

    PERFORM 1
      FROM platform.feature_flag AS flag
     WHERE flag.flag_code = 'price-change-write'
       AND flag.scope_kind = 'GLOBAL'
       AND flag.status = 'ACTIVE'
       AND flag.state = 'ENABLED';
    IF NOT FOUND
    THEN
        reasons := array_append(reasons, 'GLOBAL_SWITCH_DISABLED');
    END IF;

    IF EXISTS (
        SELECT 1
          FROM platform.feature_flag AS flag
         WHERE flag.flag_code = 'price-change-write'
           AND flag.status = 'ACTIVE'
           AND flag.state = 'DISABLED'
           AND ((flag.scope_kind = 'PLATFORM'
                    AND flag.platform_code = command_row.platform_code)
                OR (flag.scope_kind = 'MARKETPLACE_ACCOUNT'
                    AND flag.marketplace_account_id = command_row.marketplace_account_id)
                OR (flag.scope_kind = 'STORE'
                    AND flag.store_id = command_row.store_id)))
    THEN
        reasons := array_append(reasons, 'SCOPED_SWITCH_DISABLED');
    END IF;

    -- The entity must be on the positive allowlist at this instant.
    PERFORM 1
      FROM ops.pilot_allowlist_entry AS entry
     WHERE entry.action_kind = 'PRICE_CHANGE'
       AND entry.status = 'ACTIVE'
       AND entry.store_id = command_row.store_id
       AND (entry.platform_listing_variant_id IS NULL
            OR entry.platform_listing_variant_id
                = command_row.platform_listing_variant_id)
       AND entry.valid_from <= now_instant
       AND entry.valid_until > now_instant;
    IF NOT FOUND
    THEN
        reasons := array_append(reasons, 'ENTITY_NOT_ALLOWLISTED');
    END IF;

    -- The authorization must still stand and still cover this exact proposal.
    PERFORM 1
      FROM ops.approval_decision AS decision
      JOIN ops.recommendation AS proposal ON proposal.id = decision.recommendation_id
     WHERE decision.id = command_row.approval_decision_id
       AND decision.recommendation_id = command_row.recommendation_id
       AND decision.decision IN ('APPROVED', 'POLICY_AUTHORIZED')
       AND decision.scope_expires_at > now_instant
       AND decision.entity_version_digest = proposal.entity_version_digest;
    IF NOT FOUND
    THEN
        reasons := array_append(reasons, 'AUTHORIZATION_INVALID_OR_EXPIRED');
    END IF;

    PERFORM 1
      FROM ops.recommendation AS proposal
     WHERE proposal.id = command_row.recommendation_id
       AND proposal.state IN ('APPROVED', 'POLICY_AUTHORIZED',
                              'COMMAND_CREATED', 'EXECUTION_TRACKING')
       AND proposal.valid_until > now_instant;
    IF NOT FOUND
    THEN
        reasons := array_append(reasons, 'RECOMMENDATION_STALE');
    END IF;

    -- The mapping the profit case rests on must still resolve.
    PERFORM 1
      FROM core.listing_mapping AS mapping
     WHERE mapping.platform_listing_variant_id
               = command_row.platform_listing_variant_id
       AND mapping.status = 'ACTIVE'
       AND mapping.effective_from <= now_instant
       AND (mapping.effective_to IS NULL OR mapping.effective_to > now_instant);
    IF NOT FOUND
    THEN
        reasons := array_append(reasons, 'MAPPING_UNRESOLVED');
    END IF;

    IF EXISTS (
        SELECT 1
          FROM core.mapping_conflict AS conflict
         WHERE conflict.platform_listing_variant_id
                   = command_row.platform_listing_variant_id
           AND conflict.state = 'OPEN')
    THEN
        reasons := array_append(reasons, 'MAPPING_CONFLICT_OPEN');
    END IF;

    -- The deterministic guardrail must have passed for execution specifically.
    PERFORM 1
      FROM ops.guardrail_evaluation AS evaluation
     WHERE evaluation.recommendation_id = command_row.recommendation_id
       AND evaluation.purpose = 'EXECUTION'
       AND evaluation.outcome = 'PASS';
    IF NOT FOUND
    THEN
        reasons := array_append(reasons, 'GUARDRAIL_NOT_PASSED');
    END IF;

    RETURN reasons;
END;
$$;

CREATE FUNCTION ops.expire_ad_action_authority(p_organization uuid, p_as_of timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE changed integer;
BEGIN
 IF p_as_of IS NULL OR p_as_of>clock_timestamp() THEN
  RAISE EXCEPTION 'expiry reconciliation requires a current or past observation' USING ERRCODE='MO092';
 END IF;
 INSERT INTO ops.ad_authority_invalidation(organization_id,authorization_id,cause_reference,cause_code,invalidated_at)
 SELECT a.organization_id,a.id,a.id,'SEALED_AUTHORIZATION_EXPIRED',p_as_of
 FROM ops.ad_action_authorization a
 WHERE a.organization_id=p_organization AND a.expires_at<=p_as_of
  AND NOT EXISTS(SELECT 1 FROM ops.ad_authority_invalidation i WHERE i.authorization_id=a.id)
 ON CONFLICT DO NOTHING;
 GET DIAGNOSTICS changed=ROW_COUNT;
 RETURN changed;
END $$;

CREATE FUNCTION ops.expire_ad_manual_packets() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'pg_temp'
    AS $$
DECLARE changed integer;
BEGIN
 UPDATE ops.ad_manual_execution_packet SET state='MANUAL_PACKET_EXPIRED',updated_at=clock_timestamp(),version=version+1
 WHERE state IN ('MANUAL_PACKET_DRAFT','MANUAL_PACKET_ENDORSED','MANUAL_PACKET_ISSUED') AND expires_at<=clock_timestamp();
 GET DIAGNOSTICS changed=ROW_COUNT; RETURN changed;
END $$;

CREATE FUNCTION ops.expire_diagnostic_exports() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE j ops.diagnostic_export;
BEGIN
 FOR j IN SELECT * FROM ops.diagnostic_export WHERE
   (state='SUCCEEDED' AND expires_at<=statement_timestamp()) OR
   (state IN ('QUEUED','RUNNING') AND (deadline_at<=statement_timestamp() OR
     (attempt_count>=5 AND (lease_until IS NULL OR lease_until<=statement_timestamp()))))
   ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT 100 LOOP
   UPDATE ops.diagnostic_export SET state=CASE WHEN j.state='SUCCEEDED' THEN 'EXPIRED' ELSE 'FAILED' END,
     failure_code=CASE WHEN j.state='SUCCEEDED' THEN NULL WHEN j.deadline_at<=statement_timestamp()
       THEN 'DEADLINE_EXCEEDED' ELSE 'RETRY_EXHAUSTED' END,lease_token=NULL,lease_until=NULL
     WHERE id=j.id RETURNING * INTO j;
   PERFORM ops.audit_diagnostic_export(j,j.state);
 END LOOP;
END $$;

CREATE FUNCTION ops.fail_diagnostic_export(p_id uuid, p_token uuid, p_code text, p_retry boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE j ops.diagnostic_export;
BEGIN
 SELECT * INTO j FROM ops.diagnostic_export WHERE id=p_id FOR UPDATE;
 IF NOT FOUND OR j.state<>'RUNNING' OR p_token IS NULL OR j.lease_token IS DISTINCT FROM p_token
   OR j.lease_until<=clock_timestamp() THEN RAISE EXCEPTION 'export lease lost' USING ERRCODE='MO081'; END IF;
 IF p_code IS NULL OR p_code NOT IN ('AUTHORIZATION_REVOKED','LIMIT_EXCEEDED','STORAGE_UNAVAILABLE','DATABASE_UNAVAILABLE','INVALID_SNAPSHOT')
   OR p_retry IS NULL OR (p_retry AND p_code NOT IN ('STORAGE_UNAVAILABLE','DATABASE_UNAVAILABLE')) THEN
   RAISE EXCEPTION 'invalid export failure' USING ERRCODE='MO039'; END IF;
 UPDATE ops.diagnostic_export SET state=CASE WHEN p_retry AND attempt_count<5 AND deadline_at>statement_timestamp() THEN 'QUEUED' ELSE 'FAILED' END,
   failure_code=p_code,lease_token=NULL,lease_until=NULL,next_attempt_at=statement_timestamp()+interval '5 seconds'
   WHERE id=p_id RETURNING * INTO j;
 PERFORM ops.audit_diagnostic_export(j,'ATTEMPT_FAILED');
END $$;

CREATE FUNCTION ops.freeze_ad_outcome_baseline(p_baseline jsonb, p_stages jsonb, p_units jsonb, p_proof text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE b ops.ad_outcome_baseline%ROWTYPE; g ops.ad_outcome_plan_grant%ROWTYPE; digest text;
BEGIN
 b:=jsonb_populate_record(NULL::ops.ad_outcome_baseline,p_baseline);
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_stages||p_units) entry WHERE (entry->>'outcome_baseline_id')::uuid IS DISTINCT FROM b.id) THEN
   RAISE EXCEPTION 'frozen rows must belong to the exact attested baseline' USING ERRCODE='MO099'; END IF;
 digest:=ops.ad_outcome_payload_digest(p_baseline,p_stages,p_units);
 SELECT * INTO g FROM ops.ad_outcome_plan_grant WHERE proof_digest=encode(sha256(convert_to(p_proof,'UTF8')),'hex') FOR UPDATE;
 IF NOT FOUND OR g.baseline_id IS DISTINCT FROM b.id OR g.organization_id IS DISTINCT FROM b.organization_id
    OR g.payload_digest IS DISTINCT FROM digest OR g.application_backend_pid<>pg_backend_pid()
    OR g.application_transaction_id<>txid_current() OR g.expires_at<=clock_timestamp() OR g.consumed_at IS NOT NULL THEN
   RAISE EXCEPTION 'exact canonical planner proof required' USING ERRCODE='MO099'; END IF;
 UPDATE ops.ad_outcome_plan_grant SET consumed_at=clock_timestamp() WHERE proof_digest=g.proof_digest;
 INSERT INTO ops.ad_outcome_baseline SELECT b.*;
 INSERT INTO ops.ad_outcome_stage_baseline SELECT * FROM jsonb_populate_recordset(NULL::ops.ad_outcome_stage_baseline,p_stages);
 INSERT INTO ops.ad_outcome_critical_unit SELECT * FROM jsonb_populate_recordset(NULL::ops.ad_outcome_critical_unit,p_units);
 INSERT INTO ops.ad_outcome_baseline_attestation VALUES(b.id,b.organization_id,digest,clock_timestamp(),'CANONICAL_OUTCOME_PLANNER_V1');
 IF b.state='COMPLETE' AND NOT ops.ad_outcome_baseline_is_canonical(b.id,b.prepared_at) THEN
   RAISE EXCEPTION 'canonical baseline shape, policy, membership or stage is unresolved' USING ERRCODE='MO099'; END IF;
 RETURN b.id;
END $$;

CREATE FUNCTION ops.generate_ad_manual_proposal(p_id uuid, p_case uuid, p_policy uuid, p_candidate uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'mart', 'platform', 'pg_temp'
    AS $$
DECLARE kase mart.ad_case%ROWTYPE; policy core.ad_manual_policy%ROWTYPE;
 cfg core.ad_object_configuration_observation%ROWTYPE; candidate ops.ad_bid_candidate%ROWTYPE;
 task_recommendation ops.recommendation%ROWTYPE; target jsonb; deadline timestamptz;
BEGIN
 SELECT * INTO kase FROM mart.ad_case WHERE id=p_case AND superseded_at IS NULL FOR SHARE;
 SELECT * INTO policy FROM core.ad_manual_policy WHERE id=p_policy;
 IF kase.id IS NULL OR policy.id IS NULL OR policy.organization_id<>kase.organization_id
 OR policy.store_id<>kase.store_id OR policy.semantic_profile_id<>kase.semantic_profile_id
 OR policy.cause_code<>kase.cause_code OR clock_timestamp()<policy.effective_from OR clock_timestamp()>=policy.effective_to
 OR NOT EXISTS(SELECT 1 FROM core.ad_affected_set a WHERE a.id=kase.affected_set_id AND a.resolution_state='COMPLETE'
   AND cardinality(a.product_variant_ids)>0 AND NOT EXISTS(SELECT 1 FROM core.ad_affected_set n
     WHERE n.ad_native_object_id=a.ad_native_object_id AND n.resolved_at>a.resolved_at)) THEN
   RAISE EXCEPTION 'manual proposal policy or complete current case is unresolved' USING ERRCODE='MO097'; END IF;
 SELECT r.* INTO task_recommendation FROM ops.recommendation r WHERE r.organization_id=kase.organization_id
 AND r.action_kind='ADVERTISING_REVIEW' AND r.subject_kind='AD_NATIVE_OBJECT' AND r.subject_id=kase.ad_native_object_id
 AND r.proposed_parameters->>'caseId'=kase.id::text AND r.state='TASK_ONLY' ORDER BY r.created_at DESC LIMIT 1;
 IF task_recommendation.id IS NULL THEN RAISE EXCEPTION 'canonical responsibility recommendation required' USING ERRCODE='MO097'; END IF;
 SELECT * INTO cfg FROM core.ad_object_configuration_observation c WHERE c.organization_id=kase.organization_id
 AND c.ad_native_object_id=kase.ad_native_object_id AND c.semantic_profile_id=kase.semantic_profile_id
 AND c.evidence_grade IN ('OFFICIAL_API_READBACK','OFFICIAL_CONFIGURATION_EXPORT')
 AND EXISTS(SELECT 1 FROM core.fact_provenance provenance
   JOIN raw.raw_acquisition_observation observation ON observation.id=provenance.raw_observation_id AND observation.outcome_class='SUCCESS_BYTES'
   JOIN raw.raw_logical_unit unit ON unit.id=observation.logical_unit_id
   JOIN platform.ingestion_job job ON job.id=unit.job_id AND job.organization_id=c.organization_id
   JOIN core.store st ON st.id=kase.store_id AND st.marketplace_account_id=job.marketplace_account_id
   WHERE provenance.id=c.provenance_id AND provenance.organization_id=c.organization_id
     AND provenance.source_kind='MARKETPLACE_RAW' AND provenance.source_time IS NOT NULL
     AND job.platform_code=(SELECT platform_code FROM core.ad_native_object WHERE id=c.ad_native_object_id))
 AND c.observed_at<=clock_timestamp() AND c.observed_at>clock_timestamp()-make_interval(secs=>policy.configuration_max_age_seconds)
 AND NOT EXISTS(SELECT 1 FROM core.ad_object_configuration_observation n WHERE n.supersedes_observation_id=c.id)
 ORDER BY c.observed_at DESC,c.id LIMIT 1;
 IF cfg.id IS NULL THEN RAISE EXCEPTION 'current observed configuration required' USING ERRCODE='MO097'; END IF;
 IF policy.action_kind='AD_BID_CHANGE' THEN
   SELECT * INTO candidate FROM ops.ad_bid_candidate WHERE id=p_candidate AND case_id=kase.id
   AND organization_id=kase.organization_id AND candidate_basis=policy.candidate_basis
   AND current_bid_amount=cfg.observed_bid_amount AND bid_unit_code=cfg.bid_unit_code AND currency_code=cfg.bid_currency_code
   AND affected_set_digest=(SELECT affected_set_digest FROM core.ad_affected_set WHERE id=kase.affected_set_id);
   IF candidate.id IS NULL THEN RAISE EXCEPTION 'exact finite system bid candidate required' USING ERRCODE='MO097'; END IF;
   target:=jsonb_build_object('targetBid',candidate.provider_normalized_amount,'currentBid',cfg.observed_bid_amount,
     'currencyCode',candidate.currency_code,'bidUnitCode',candidate.bid_unit_code,'candidateId',candidate.id,'direction',candidate.direction);
 ELSIF policy.action_kind='AD_BUDGET_CHANGE' THEN
   IF p_candidate IS NOT NULL OR cfg.observed_budget_amount IS NULL THEN RAISE EXCEPTION 'budget proposal requires exact observed budget and no bid candidate' USING ERRCODE='MO097'; END IF;
   target:=jsonb_build_object('targetBudget',policy.target_budget,'currentBudget',cfg.observed_budget_amount,'currencyCode',policy.currency_code,
     'direction',CASE WHEN policy.target_budget<cfg.observed_budget_amount THEN 'PROTECTION_DECREASE' ELSE 'OPTIMIZATION_INCREASE' END);
 ELSE
   IF p_candidate IS NOT NULL THEN RAISE EXCEPTION 'status proposal has no bid candidate' USING ERRCODE='MO097'; END IF;
   IF cfg.native_status_raw IS NULL OR cfg.observed_status='UNKNOWN' THEN
     RAISE EXCEPTION 'current native status is unresolved' USING ERRCODE='MO097'; END IF;
   target:=jsonb_build_object('targetStatus',policy.target_status,'currentStatus',cfg.native_status_raw,
     'direction',CASE WHEN (SELECT status_semantics->>policy.target_status FROM platform.ad_semantic_profile WHERE id=policy.semantic_profile_id)
       IN ('PAUSED','STOPPED') THEN 'PROTECTION_DECREASE' ELSE 'OPTIMIZATION_INCREASE' END);
 END IF;
 deadline:=least(policy.effective_to,task_recommendation.valid_until,
   (SELECT effective_to FROM platform.ad_semantic_profile WHERE id=policy.semantic_profile_id),
   cfg.observed_at+make_interval(secs=>policy.configuration_max_age_seconds),clock_timestamp()+make_interval(secs=>policy.packet_lease_seconds));
 INSERT INTO ops.ad_manual_proposal(id,organization_id,case_id,responsibility_recommendation_id,policy_id,candidate_id,
   ad_native_object_id,store_id,affected_set_id,affected_set_digest,observed_configuration_id,action_kind,intended_state,
   authority_snapshot,generated_at,expires_at)
 VALUES(p_id,kase.organization_id,kase.id,task_recommendation.id,policy.id,p_candidate,kase.ad_native_object_id,kase.store_id,
   kase.affected_set_id,(SELECT affected_set_digest FROM core.ad_affected_set WHERE id=kase.affected_set_id),cfg.id,policy.action_kind,
   target,ops.ad_manual_snapshot(kase.id,policy.id,cfg.id),clock_timestamp(),deadline);
 RETURN p_id;
END $$;

CREATE FUNCTION ops.guard_ad_exception_transition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'iam', 'pg_temp'
    AS $$
BEGIN
    IF TG_OP='UPDATE' THEN
        IF NEW.version<>OLD.version+1 OR NOT
            ((OLD.state='REQUESTED' AND NEW.state IN('ENDORSED','ENDED','INVALIDATED','EXPIRED'))
             OR (OLD.state='ENDORSED' AND NEW.state IN('ACTIVE','ENDED','INVALIDATED','EXPIRED'))
             OR (OLD.state='ACTIVE' AND NEW.state IN('ENDED','INVALIDATED','EXPIRED'))) THEN
            RAISE EXCEPTION 'Exception transitions never renew or resurrect a risk disposition' USING ERRCODE='23514';
        END IF;
    ELSIF NEW.state<>'REQUESTED' THEN
        RAISE EXCEPTION 'An Exception starts as a request, not an approval' USING ERRCODE='23514';
    END IF;
    IF NEW.state IN('ENDORSED','ACTIVE') AND NOT EXISTS(
        SELECT 1 FROM iam.user_role_assignment r JOIN iam.user_account u ON u.id=r.user_id
        WHERE r.user_id=NEW.endorser_user_id AND r.role_code='OPS_LEAD' AND r.status='ACTIVE'
          AND u.status='ACTIVE' AND u.organization_id=NEW.organization_id
          AND r.effective_from<=clock_timestamp() AND (r.effective_to IS NULL OR r.effective_to>clock_timestamp())) THEN
        RAISE EXCEPTION 'Exception requires live independent Operations endorsement' USING ERRCODE='23514';
    END IF;
    IF NEW.state='ACTIVE' AND NOT EXISTS(
        SELECT 1 FROM iam.user_role_assignment r JOIN iam.user_account u ON u.id=r.user_id
        WHERE r.user_id=NEW.approver_user_id AND r.role_code='OWNER' AND r.status='ACTIVE'
          AND u.status='ACTIVE' AND u.organization_id=NEW.organization_id
          AND r.effective_from<=clock_timestamp() AND (r.effective_to IS NULL OR r.effective_to>clock_timestamp())) THEN
        RAISE EXCEPTION 'Only a live Owner approval pauses advertising Action SLO' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END $$;

CREATE FUNCTION ops.guard_ad_manual_packet_issue() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
BEGIN
 IF NEW.state='MANUAL_PACKET_ISSUED' AND NEW.execution_started_at IS NULL THEN
  PERFORM pg_advisory_xact_lock(hashtext('ad_action_reservation'),hashtext(NEW.organization_id::text));
  IF EXISTS(SELECT 1 FROM ops.ad_manual_execution_packet other
    WHERE other.ad_native_object_id=NEW.ad_native_object_id AND other.id<>NEW.id
     AND other.state IN('MANUAL_PACKET_ISSUED','ACTION_REPORTED_CONFIGURATION_UNVERIFIED','MANUAL_EXECUTION_UNCERTAIN')) THEN
   RAISE EXCEPTION 'another issued or unresolved manual packet prevents a new instruction' USING ERRCODE='23505';
  END IF;
 END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION ops.guard_ai_claim() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE invocation_state text; deadline timestamptz;
BEGIN
    SELECT state,execution_deadline_at INTO invocation_state,deadline FROM ops.ai_invocation
        WHERE id=NEW.invocation_id FOR UPDATE;
    IF invocation_state IS DISTINCT FROM 'DISPATCHED' OR deadline <= clock_timestamp() THEN
        RAISE EXCEPTION 'AI response is late or already closed' USING ERRCODE='MO065';
    END IF;
    RETURN NEW;
END $$;

CREATE FUNCTION ops.guard_ai_invocation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE accepted_count integer; rejected_count integer;
BEGIN
    IF TG_OP='INSERT' AND NEW.state NOT IN ('PREPARED','DISPATCHED') THEN
        RAISE EXCEPTION 'AI invocation must begin with a durable intent' USING ERRCODE='MO065';
    END IF;
    IF (NEW.subject_kind='PLATFORM_LISTING_VARIANT' AND NOT EXISTS (
           SELECT 1 FROM core.platform_listing_variant WHERE id=NEW.subject_id AND organization_id=NEW.organization_id))
       OR (NEW.subject_kind='PRODUCT_VARIANT' AND NOT EXISTS (
           SELECT 1 FROM core.product_variant WHERE id=NEW.subject_id AND organization_id=NEW.organization_id))
       OR (NEW.subject_kind='STORE' AND NOT EXISTS (
           SELECT 1 FROM core.store WHERE id=NEW.subject_id AND organization_id=NEW.organization_id))
       OR (NEW.requested_by_user_id IS NOT NULL AND NOT EXISTS (
           SELECT 1 FROM iam.user_account WHERE id=NEW.requested_by_user_id AND organization_id=NEW.organization_id)) THEN
        RAISE EXCEPTION 'AI subject ownership mismatch' USING ERRCODE='MO064';
    END IF;
    IF TG_OP='UPDATE' THEN
        IF OLD.state NOT IN ('PREPARED','DISPATCHED')
           OR NEW.state IN ('PREPARED','DISPATCHED')
           OR (NEW.organization_id,NEW.subject_kind,NEW.subject_id,NEW.model_id,NEW.request_digest,
               NEW.projection_code,NEW.projection_version,NEW.prompt_template_code,NEW.prompt_version,
               NEW.output_schema_version,NEW.requested_by_user_id,NEW.started_at,NEW.execution_deadline_at)
             IS DISTINCT FROM
              (OLD.organization_id,OLD.subject_kind,OLD.subject_id,OLD.model_id,OLD.request_digest,
               OLD.projection_code,OLD.projection_version,OLD.prompt_template_code,OLD.prompt_version,
               OLD.output_schema_version,OLD.requested_by_user_id,OLD.started_at,OLD.execution_deadline_at) THEN
            RAISE EXCEPTION 'AI invocation is already closed or its intent changed' USING ERRCODE='MO065';
        END IF;
        SELECT count(*) FILTER(WHERE validation_state='ACCEPTED'),
               count(*) FILTER(WHERE validation_state='REJECTED')
          INTO accepted_count,rejected_count FROM ops.ai_output_claim WHERE invocation_id=OLD.id;
        IF (OLD.state='PREPARED' AND NEW.state<>'REFUSED')
           OR (OLD.state='DISPATCHED' AND NEW.state='REFUSED')
           OR (NEW.state='SUCCEEDED' AND (accepted_count=0 OR rejected_count>0 OR NEW.degraded))
           OR (NEW.state='OUTPUT_REJECTED' AND accepted_count>0)
           OR (NEW.state='PARTIAL_OUTPUT_REJECTED' AND (accepted_count=0 OR rejected_count=0))
           OR (NEW.state IN ('REFUSED','PROVIDER_FAILED','PROVIDER_OUTCOME_UNKNOWN') AND accepted_count+rejected_count>0)
           OR (NEW.state<>'SUCCEEDED' AND NOT NEW.degraded)
           OR (OLD.state='DISPATCHED' AND NEW.state<>'PROVIDER_OUTCOME_UNKNOWN'
               AND OLD.execution_deadline_at <= clock_timestamp()) THEN
            RAISE EXCEPTION 'AI final state does not match its claims or deadline' USING ERRCODE='MO065';
        END IF;
    END IF;
    RETURN NEW;
END $$;

CREATE FUNCTION ops.guard_lc_declared_purpose() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'core'
    AS $$
DECLARE purpose text; package_purpose text;
BEGIN
 IF TG_TABLE_NAME='recommendation' THEN
   IF TG_OP='UPDATE' AND NEW.proposed_parameters->'purposeCode' IS DISTINCT FROM OLD.proposed_parameters->'purposeCode' THEN
     RAISE EXCEPTION 'Listing purpose cannot change after proposal' USING ERRCODE='MO090';
   END IF;
   purpose:=NEW.proposed_parameters->>'purposeCode';
   IF (TG_OP='INSERT' AND purpose IS NULL)
     OR (purpose IS NOT NULL AND (jsonb_typeof(NEW.proposed_parameters->'purposeCode')<>'string'
     OR purpose NOT IN ('LISTING_CONVERSION','DESCRIPTION_CORRECTION','BOUNDED_EXPLORATION','PROMOTION')
     OR (NEW.action_kind='LISTING_DESCRIPTION_CHANGE' AND purpose='PROMOTION')
     OR (NEW.action_kind='LISTING_PROMOTION_ACTION' AND purpose NOT IN ('PROMOTION','BOUNDED_EXPLORATION'))
     OR (NEW.proposed_parameters ? 'restoresCommandId' AND purpose IS DISTINCT FROM 'DESCRIPTION_CORRECTION')
     OR (purpose='BOUNDED_EXPLORATION' AND NEW.proposed_parameters->>'executionPath' IS DISTINCT FROM 'MANUAL'))) THEN
     RAISE EXCEPTION 'Listing purpose does not match its declared path and action' USING ERRCODE='23514';
   END IF;
 ELSE
   SELECT r.proposed_parameters->>'purposeCode' INTO purpose FROM ops.recommendation r WHERE r.id=NEW.recommendation_id;
   SELECT p.purpose_code INTO package_purpose FROM core.lc_calibration_package p WHERE p.id=NEW.calibration_package_id;
   IF purpose IS NOT NULL AND NEW.calibration_package_id IS NOT NULL AND purpose IS DISTINCT FROM package_purpose THEN
     RAISE EXCEPTION 'Listing Action must use its declared purpose calibration' USING ERRCODE='23514';
   END IF;
   IF NEW.restores_command_id IS NOT NULL AND purpose IS DISTINCT FROM 'DESCRIPTION_CORRECTION' THEN
     RAISE EXCEPTION 'an exact restoration is a new description-correction action' USING ERRCODE='MO094';
   END IF;
 END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION ops.guard_lc_purpose_use_basis() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE proposal ops.recommendation%ROWTYPE; purpose text; item jsonb; until_at timestamptz;
BEGIN
 IF TG_TABLE_NAME='recommendation' THEN
   IF TG_OP='UPDATE' AND NEW.proposed_parameters->'purposeBasisDigest' IS DISTINCT FROM OLD.proposed_parameters->'purposeBasisDigest' THEN
     RAISE EXCEPTION 'Proposed purpose evidence digest cannot change' USING ERRCODE='MO090';
   END IF;
   RETURN NEW;
 END IF;
 IF TG_OP='UPDATE' THEN
   IF NEW.purpose_basis IS DISTINCT FROM OLD.purpose_basis THEN
     RAISE EXCEPTION 'Prepared purpose evidence and use boundaries are immutable' USING ERRCODE='MO090';
   END IF;
   RETURN NEW;
 END IF;
 SELECT * INTO proposal FROM ops.recommendation WHERE id=NEW.recommendation_id;
 purpose:=proposal.proposed_parameters->>'purposeCode';
 IF purpose IN ('DESCRIPTION_CORRECTION','BOUNDED_EXPLORATION') AND NEW.purpose_basis IS NULL THEN
   RAISE EXCEPTION 'Nonformal purpose requires its explicit proposed use basis' USING ERRCODE='23514';
 END IF;
 IF NEW.purpose_basis IS NULL THEN RETURN NEW; END IF;
 IF purpose IS NULL OR jsonb_typeof(NEW.purpose_basis) IS DISTINCT FROM 'object'
    OR jsonb_typeof(NEW.purpose_basis->'evidenceReference') IS DISTINCT FROM 'string'
    OR length(btrim(NEW.purpose_basis->>'evidenceReference')) NOT BETWEEN 1 AND 512
    OR jsonb_typeof(NEW.purpose_basis->'useConditions') IS DISTINCT FROM 'array'
    OR jsonb_typeof(NEW.purpose_basis->'endConditions') IS DISTINCT FROM 'array'
    OR EXISTS(SELECT 1 FROM jsonb_object_keys(NEW.purpose_basis) k
         WHERE k NOT IN ('evidenceReference','useConditions','endConditions','useUntil'))
    OR proposal.proposed_parameters->>'purposeBasisDigest' IS DISTINCT FROM ops.lc_purpose_basis_digest(purpose,NEW.purpose_basis) THEN
   RAISE EXCEPTION 'Purpose basis must match the exact proposed evidence and boundaries' USING ERRCODE='23514';
 END IF;
 IF jsonb_array_length(NEW.purpose_basis->'useConditions')=0 OR jsonb_array_length(NEW.purpose_basis->'endConditions')=0 THEN
   RAISE EXCEPTION 'Purpose use and ending conditions must be explicit' USING ERRCODE='23514';
 END IF;
 FOR item IN SELECT value FROM jsonb_array_elements((NEW.purpose_basis->'useConditions')||(NEW.purpose_basis->'endConditions')) LOOP
   IF jsonb_typeof(item) IS DISTINCT FROM 'string' OR length(btrim(item#>>'{}')) NOT BETWEEN 1 AND 512 THEN
     RAISE EXCEPTION 'Purpose conditions must be nonempty statements' USING ERRCODE='23514';
   END IF;
 END LOOP;
 IF NEW.purpose_basis->>'useUntil' IS NOT NULL THEN
   until_at:=(NEW.purpose_basis->>'useUntil')::timestamptz;
   IF NOT isfinite(until_at) OR until_at<=NEW.created_at OR until_at<=statement_timestamp() THEN
     RAISE EXCEPTION 'Purpose use deadline must be finite and future at preparation' USING ERRCODE='23514';
   END IF;
 END IF;
 IF purpose='BOUNDED_EXPLORATION' AND until_at IS NULL THEN
   RAISE EXCEPTION 'Bounded exploration requires its explicit finite use deadline' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION ops.hold_work_task_first_raised_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
BEGIN
    -- Set once, from the row's own creation, and never moved afterwards. A
    -- caller that tried would be told rather than silently obeyed, because a
    -- task whose age could be edited is a service level nobody can audit.
    IF TG_OP = 'INSERT' THEN
        NEW.first_raised_at := coalesce(NEW.first_raised_at, NEW.created_at);
        RETURN NEW;
    END IF;
    IF NEW.first_raised_at IS DISTINCT FROM OLD.first_raised_at THEN
        RAISE EXCEPTION 'a task keeps the instant it was raised'
            USING ERRCODE = 'MO018';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.ingestion_run_fence_monotonic() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.fence_token < OLD.fence_token THEN
        RAISE EXCEPTION 'run % fence token may not move backwards: % -> %',
            OLD.id, OLD.fence_token, NEW.fence_token
            USING ERRCODE = 'MO007';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.invalidate_ad_assets_on_credential_authority_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'platform', 'pg_temp'
    AS $$
DECLARE credential uuid; organization uuid; account uuid;
BEGIN
 IF TG_TABLE_NAME='credential_metadata' THEN
  credential:=OLD.id;organization:=OLD.organization_id;account:=OLD.marketplace_account_id;
 ELSIF TG_TABLE_NAME='ad_write_credential_attestation' THEN
  credential:=OLD.credential_id;organization:=OLD.organization_id;account:=OLD.marketplace_account_id;
 ELSE
  credential:=OLD.credential_id;
  SELECT organization_id,marketplace_account_id INTO organization,account FROM platform.credential_metadata WHERE id=credential;
 END IF;
 INSERT INTO ops.ad_authority_invalidation(organization_id,authorization_id,cause_reference,cause_code)
 SELECT a.organization_id,a.id,credential,'CREDENTIAL_AUTHORITY_CHANGED' FROM ops.ad_action_authorization a
 JOIN ops.ad_decision_policy_bundle b ON b.id=a.bundle_id
 WHERE a.organization_id=organization AND b.marketplace_account_id=account ON CONFLICT DO NOTHING;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;

CREATE FUNCTION ops.invalidate_ad_assets_on_human_authority_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'iam', 'pg_temp'
    AS $$
DECLARE actors uuid[];
BEGIN
 IF TG_TABLE_NAME='user_account' THEN
  IF TG_OP='UPDATE' AND ROW(OLD.status,OLD.identity_provider_id,OLD.external_subject,OLD.credentials_valid_from)
    IS NOT DISTINCT FROM ROW(NEW.status,NEW.identity_provider_id,NEW.external_subject,NEW.credentials_valid_from) THEN RETURN NEW; END IF;
  actors:=ARRAY[OLD.id];
 ELSIF TG_TABLE_NAME='identity_provider' THEN
  IF TG_OP='UPDATE' AND to_jsonb(OLD)-ARRAY['display_name','updated_at','version']
    IS NOT DISTINCT FROM to_jsonb(NEW)-ARRAY['display_name','updated_at','version'] THEN RETURN NEW; END IF;
  SELECT array_agg(id) INTO actors FROM iam.user_account WHERE identity_provider_id=OLD.id;
 ELSE
  IF TG_OP='UPDATE' AND to_jsonb(OLD)-ARRAY['reason','updated_at','version']
    IS NOT DISTINCT FROM to_jsonb(NEW)-ARRAY['reason','updated_at','version'] THEN RETURN NEW; END IF;
  actors:=ARRAY[OLD.user_id];
 END IF;
 INSERT INTO ops.ad_authority_invalidation(organization_id,authorization_id,cause_reference,cause_code)
 SELECT a.organization_id,a.id,OLD.id,'HUMAN_AUTHORITY_CHANGED' FROM ops.ad_action_authorization a
 WHERE a.maker_user_id=ANY(actors) OR a.endorser_user_id=ANY(actors) OR a.final_approver_user_id=ANY(actors)
 ON CONFLICT DO NOTHING;
 UPDATE ops.ad_manual_execution_packet packet SET state='MANUAL_PACKET_REVOKED',revoked_at=clock_timestamp(),
   revoked_reason='HUMAN_AUTHORITY_CHANGED',updated_at=clock_timestamp(),version=version+1
 WHERE packet.state IN('MANUAL_PACKET_DRAFT','MANUAL_PACKET_ENDORSED','MANUAL_PACKET_ISSUED')
 AND (packet.maker_user_id=ANY(actors) OR packet.endorser_user_id=ANY(actors) OR packet.approver_user_id=ANY(actors));
 UPDATE ops.ad_manual_execution_packet packet SET state='MANUAL_EXECUTION_UNCERTAIN',current_proof_id=NULL,
   updated_at=clock_timestamp(),version=version+1
 WHERE packet.execution_started_at IS NOT NULL AND packet.state IN('MANUAL_EXECUTION_IN_PROGRESS',
  'ACTION_REPORTED_CONFIGURATION_UNVERIFIED','MANUAL_CONFIGURATION_VERIFIED','MANUAL_EXECUTION_UNCERTAIN')
 AND (packet.maker_user_id=ANY(actors) OR packet.endorser_user_id=ANY(actors)
   OR packet.approver_user_id=ANY(actors) OR packet.executor_user_id=ANY(actors));
 UPDATE ops.ad_action_reservation held SET configuration_resolved=false,unknown_or_mismatch_open=true,version=held.version+1
 FROM ops.ad_manual_execution_packet packet WHERE packet.reservation_id=held.id AND held.state='ACTIVE'
 AND packet.execution_started_at IS NOT NULL AND packet.state='MANUAL_EXECUTION_UNCERTAIN'
 AND (packet.maker_user_id=ANY(actors) OR packet.endorser_user_id=ANY(actors)
   OR packet.approver_user_id=ANY(actors) OR packet.executor_user_id=ANY(actors));
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;

CREATE FUNCTION ops.invalidate_ad_assets_on_referenced_authority_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $_$ BEGIN
 IF to_jsonb(OLD) IS DISTINCT FROM to_jsonb(NEW) THEN
 INSERT INTO ops.ad_authority_invalidation(organization_id,authorization_id,cause_reference,cause_code)
 SELECT a.organization_id,a.id,OLD.id,'REFERENCED_AUTHORITY_CHANGED' FROM ops.ad_action_authorization a
 WHERE jsonb_path_exists(a.authority_snapshot,'$.**.id ? (@ == $id)',jsonb_build_object('id',OLD.id::text))
 ON CONFLICT DO NOTHING;
 END IF; RETURN NEW;
END $_$;

CREATE FUNCTION ops.invalidate_ad_assets_on_switch_stop() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'platform', 'pg_temp'
    AS $$ BEGIN
 IF NEW.flag_code='ad-bid-change-write' AND NEW.state='DISABLED' AND (TG_OP='INSERT' OR OLD.state<>'DISABLED') THEN
 INSERT INTO ops.ad_authority_invalidation(organization_id,authorization_id,cause_reference,cause_code)
 SELECT a.organization_id,a.id,NEW.id,'WRITE_SWITCH_STOPPED' FROM ops.ad_action_authorization a
 JOIN ops.recommendation r ON r.id=a.recommendation_id JOIN ops.ad_decision_policy_bundle b ON b.id=a.bundle_id
 WHERE NEW.scope_kind='GLOBAL' OR NEW.scope_kind='STORE' AND NEW.store_id=r.store_id
 OR NEW.scope_kind='PLATFORM' AND NEW.platform_code=b.platform_code
 OR NEW.scope_kind='MARKETPLACE_ACCOUNT' AND NEW.marketplace_account_id=b.marketplace_account_id
 OR NEW.scope_kind='CAPABILITY' AND NEW.capability_id=(SELECT id FROM platform.platform_capability cap
 WHERE cap.platform_code=b.platform_code AND cap.capability_code='ad-bid-change')
 ON CONFLICT DO NOTHING;
 END IF; RETURN NEW;
END $$;

CREATE FUNCTION ops.invalidate_ad_authority_on_bundle_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
BEGIN
 IF OLD.status='ACTIVE' AND NEW.status<>'ACTIVE' THEN
  INSERT INTO ops.ad_authority_invalidation(organization_id,authorization_id,cause_reference,cause_code)
  SELECT a.organization_id,a.id,OLD.id,'BUNDLE_REPLACED_OR_REVOKED' FROM ops.ad_action_authorization a
   WHERE a.bundle_id=OLD.id ON CONFLICT DO NOTHING;
 END IF; RETURN NEW;
END $$;

CREATE FUNCTION ops.invalidate_ad_authority_on_containment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'pg_temp'
    AS $_$
BEGIN
 IF NEW.state<>'ACTIVE' OR TG_OP='UPDATE' AND OLD.state='ACTIVE' THEN RETURN NEW; END IF;
 PERFORM pg_advisory_xact_lock(hashtext('ad_action_reservation'),hashtext(NEW.organization_id::text));
 INSERT INTO ops.ad_authority_invalidation(organization_id,authorization_id,cause_reference,cause_code)
 SELECT a.organization_id,a.id,NEW.id,'CONTAINMENT_ACTIVATED' FROM ops.ad_action_authorization a
 JOIN ops.recommendation r ON r.id=a.recommendation_id JOIN core.ad_native_object obj ON obj.id=r.subject_id
 JOIN ops.ad_bid_candidate candidate ON candidate.id=a.candidate_id
 WHERE a.organization_id=NEW.organization_id
 AND (NEW.scope_kind<>'AUTHORITY_VERSION' OR ops.ad_bundle_consumes_authority_version(a.bundle_id,
  CASE WHEN NEW.authority_version_reference ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN NEW.authority_version_reference::uuid ELSE NULL END))
 AND cardinality(ops.ad_active_containment(a.organization_id,
  obj.id,r.store_id,obj.platform_code,'ad-bid-change',candidate.affected_set_digest))>0 ON CONFLICT DO NOTHING;
 UPDATE ops.ad_manual_execution_packet packet SET state='MANUAL_PACKET_REVOKED',revoked_at=clock_timestamp(),
  revoked_reason='CONTAINMENT_ACTIVATED',updated_at=clock_timestamp(),version=version+1
 WHERE packet.organization_id=NEW.organization_id AND packet.state IN ('MANUAL_PACKET_DRAFT','MANUAL_PACKET_ENDORSED','MANUAL_PACKET_ISSUED')
 AND (NEW.scope_kind<>'AUTHORITY_VERSION' OR ops.ad_bundle_consumes_authority_version(packet.bundle_id,
  CASE WHEN NEW.authority_version_reference ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN NEW.authority_version_reference::uuid ELSE NULL END) OR NEW.authority_version_reference=ANY(ARRAY[packet.semantic_profile_id::text,
   to_jsonb(packet)#>>'{authority_snapshot,policy,id}',to_jsonb(packet)#>>'{authority_snapshot,outcomePolicy,id}']))
 AND cardinality(ops.ad_active_containment(packet.organization_id,packet.ad_native_object_id,packet.store_id,
 packet.platform_code,'ad-bid-change',packet.affected_set_digest))>0;
 -- Once execution has begun, a stop cannot assert what actually landed. Keep
 -- every observation and the hold, invalidate the current proof, and permit
 -- only the existing factual report / independent verification path.
 UPDATE ops.ad_manual_execution_packet packet SET state='MANUAL_EXECUTION_UNCERTAIN',
  current_proof_id=NULL,updated_at=clock_timestamp(),version=version+1
 WHERE packet.organization_id=NEW.organization_id AND packet.execution_started_at IS NOT NULL
 AND packet.state IN ('MANUAL_EXECUTION_IN_PROGRESS','ACTION_REPORTED_CONFIGURATION_UNVERIFIED',
  'MANUAL_CONFIGURATION_VERIFIED','MANUAL_EXECUTION_UNCERTAIN')
 AND (NEW.scope_kind<>'AUTHORITY_VERSION' OR ops.ad_bundle_consumes_authority_version(packet.bundle_id,
  CASE WHEN NEW.authority_version_reference ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN NEW.authority_version_reference::uuid ELSE NULL END) OR NEW.authority_version_reference=ANY(ARRAY[packet.semantic_profile_id::text,
   to_jsonb(packet)#>>'{authority_snapshot,policy,id}',to_jsonb(packet)#>>'{authority_snapshot,outcomePolicy,id}']))
 AND cardinality(ops.ad_active_containment(packet.organization_id,packet.ad_native_object_id,packet.store_id,
  packet.platform_code,'ad-bid-change',packet.affected_set_digest))>0;
 UPDATE ops.ad_action_reservation held SET configuration_resolved=false,
  unknown_or_mismatch_open=true,version=held.version+1
 FROM ops.ad_manual_execution_packet packet WHERE packet.reservation_id=held.id
 AND held.state='ACTIVE' AND packet.organization_id=NEW.organization_id
 AND packet.execution_started_at IS NOT NULL AND packet.state='MANUAL_EXECUTION_UNCERTAIN'
 AND (NEW.scope_kind<>'AUTHORITY_VERSION' OR ops.ad_bundle_consumes_authority_version(packet.bundle_id,
  CASE WHEN NEW.authority_version_reference ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN NEW.authority_version_reference::uuid ELSE NULL END) OR NEW.authority_version_reference=ANY(ARRAY[packet.semantic_profile_id::text,
   to_jsonb(packet)#>>'{authority_snapshot,policy,id}',to_jsonb(packet)#>>'{authority_snapshot,outcomePolicy,id}']))
 AND cardinality(ops.ad_active_containment(packet.organization_id,packet.ad_native_object_id,packet.store_id,
  packet.platform_code,'ad-bid-change',packet.affected_set_digest))>0;
 RETURN NEW;
END $_$;

CREATE FUNCTION ops.invalidate_ad_compensation_on_authority_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'platform', 'pg_temp'
    AS $$
DECLARE changed jsonb; reference uuid; actor uuid; credential uuid; account uuid;
BEGIN
 IF TG_OP='INSERT' THEN changed:=to_jsonb(NEW); ELSE changed:=to_jsonb(OLD); END IF;
 reference:=nullif(changed->>'id','')::uuid;
 IF TG_TABLE_NAME='credential_store_scope' THEN reference:=(changed->>'credential_id')::uuid; END IF;
 IF TG_TABLE_SCHEMA='iam' THEN
  actor:=CASE WHEN TG_TABLE_NAME='user_account' THEN reference ELSE (changed->>'user_id')::uuid END;
 END IF;
 IF TG_TABLE_NAME IN('credential_metadata','credential_store_scope','ad_write_credential_attestation') THEN
  credential:=CASE WHEN TG_TABLE_NAME='credential_metadata' THEN reference ELSE (changed->>'credential_id')::uuid END;
  account:=(changed->>'marketplace_account_id')::uuid;
  IF account IS NULL THEN SELECT marketplace_account_id INTO account FROM platform.credential_metadata WHERE id=credential; END IF;
 END IF;
 IF TG_TABLE_NAME='feature_flag' AND (changed->>'flag_code'<>'ad-bid-change-write'
   OR TG_OP='UPDATE' AND to_jsonb(NEW)->>'state'<>'DISABLED') THEN RETURN NEW; END IF;
 INSERT INTO ops.ad_compensation_invalidation(compensation_id,cause_reference,cause_code)
 SELECT a.id,reference,'REFERENCED_'||upper(TG_TABLE_NAME)||'_CHANGED' FROM ops.ad_compensation_authorization a
 JOIN ops.ad_bid_command c ON c.id=a.command_id JOIN ops.ad_decision_policy_bundle b ON b.id=a.bundle_id
 WHERE (actor IN(a.maker_user_id,a.endorser_user_id,a.owner_user_id)
  OR account=b.marketplace_account_id
  OR a.preview_snapshot::text LIKE '%'||reference::text||'%'
  OR TG_TABLE_NAME='feature_flag' AND (changed->>'scope_kind'='GLOBAL'
    OR changed->>'capability_id'=c.capability_id::text OR changed->>'store_id'=c.store_id::text
    OR changed->>'marketplace_account_id'=b.marketplace_account_id::text OR changed->>'platform_code'=c.platform_code)
  OR TG_TABLE_NAME='ad_containment' AND cardinality(ops.ad_active_containment(c.organization_id,c.ad_native_object_id,
    c.store_id,c.platform_code,'ad-bid-change',c.affected_set_digest))>0)
 ON CONFLICT DO NOTHING;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;

CREATE FUNCTION ops.invalidate_manual_proof_on_later_configuration() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'pg_temp'
    AS $$
DECLARE packet ops.ad_manual_execution_packet%ROWTYPE; actual text; expected text;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('ad_action_reservation'),hashtext(NEW.organization_id::text));
 FOR packet IN SELECT p.* FROM ops.ad_manual_execution_packet p
   LEFT JOIN ops.ad_manual_configuration_verification proof ON proof.id=p.current_proof_id
   WHERE p.organization_id=NEW.organization_id AND p.ad_native_object_id=NEW.ad_native_object_id
    AND p.execution_started_at IS NOT NULL AND p.state='MANUAL_CONFIGURATION_VERIFIED'
    AND NEW.observed_at>=coalesce(proof.observed_at,p.execution_started_at) FOR UPDATE OF p
 LOOP
  actual:=CASE packet.action_kind WHEN 'AD_BID_CHANGE' THEN NEW.observed_bid_amount::text
    WHEN 'AD_BUDGET_CHANGE' THEN NEW.observed_budget_amount::text ELSE NEW.native_status_raw END;
  expected:=packet.intended_state->>CASE packet.action_kind WHEN 'AD_BID_CHANGE' THEN 'targetBid'
    WHEN 'AD_BUDGET_CHANGE' THEN 'targetBudget' ELSE 'targetStatus' END;
  IF NEW.semantic_profile_id IS DISTINCT FROM packet.semantic_profile_id OR actual IS NULL
    OR (CASE WHEN packet.action_kind IN ('AD_BID_CHANGE','AD_BUDGET_CHANGE')
      THEN actual::numeric<>expected::numeric ELSE actual<>expected END) THEN
   UPDATE ops.ad_manual_execution_packet SET state='MANUAL_EXECUTION_UNCERTAIN',current_proof_id=NULL,
     updated_at=clock_timestamp(),version=version+1 WHERE id=packet.id;
   PERFORM ops.reconcile_ad_manual_configuration_reservation(packet.id,'configuration-observation:'||NEW.id);
  END IF;
 END LOOP;
 RETURN NEW;
END $$;

CREATE FUNCTION ops.issue_ad_outcome_plan_grant(p_proof_digest text, p_baseline uuid, p_organization uuid, p_payload_digest text, p_backend integer, p_transaction bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $_$
BEGIN
 IF p_proof_digest !~ '^[0-9a-f]{64}$' OR p_payload_digest !~ '^[0-9a-f]{64}$' OR p_backend<=0 OR p_transaction<=0 THEN
   RAISE EXCEPTION 'canonical planner proof is malformed' USING ERRCODE='MO099'; END IF;
 INSERT INTO ops.ad_outcome_plan_grant VALUES(p_proof_digest,p_baseline,p_organization,p_payload_digest,
   p_backend,p_transaction,clock_timestamp(),clock_timestamp()+interval '30 seconds',NULL);
END $_$;

CREATE FUNCTION ops.lc_action_binding_matches_action() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE action ops.lc_action%ROWTYPE; approval ops.approval_decision%ROWTYPE;
BEGIN
    SELECT * INTO action FROM ops.lc_action WHERE id = NEW.action_id;
    IF NOT FOUND OR action.organization_id <> NEW.organization_id THEN
        RAISE EXCEPTION 'binding names an unknown action' USING ERRCODE = 'MO090';
    END IF;
    IF action.state <> 'REVIEWED' THEN
        RAISE EXCEPTION 'only a reviewed action is bound' USING ERRCODE = 'MO091';
    END IF;
    IF NEW.affected_set_digest <> action.affected_set_digest
        OR NEW.target_text_digest IS DISTINCT FROM action.target_text_digest
        OR NEW.current_text_digest IS DISTINCT FROM action.current_text_digest
        OR NEW.execution_path <> action.execution_path
        OR NEW.calibration_package_id IS DISTINCT FROM action.calibration_package_id
        OR NEW.calibration_version IS DISTINCT FROM action.calibration_version THEN
        RAISE EXCEPTION 'a binding freezes exactly what the action carries' USING ERRCODE = 'MO092';
    END IF;
    SELECT * INTO approval FROM ops.approval_decision WHERE id = NEW.approval_decision_id;
    IF NOT FOUND OR approval.recommendation_id <> action.recommendation_id
        OR approval.decision <> 'APPROVED' OR NEW.expires_at > approval.scope_expires_at THEN
        RAISE EXCEPTION 'a binding rests on the standing approval of its own action'
            USING ERRCODE = 'MO092';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM ops.guardrail_evaluation g
                    WHERE g.id = NEW.guardrail_evaluation_id
                      AND g.recommendation_id = action.recommendation_id
                      AND g.purpose = 'APPROVAL' AND g.outcome = 'PASS'
                      AND g.lc_calibration_package_id = NEW.calibration_package_id
                      AND g.lc_calibration_version = NEW.calibration_version) THEN
        RAISE EXCEPTION 'a binding rests on an approval PASS naming its calibration package'
            USING ERRCODE = 'MO092';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.lc_action_binds_promotion_terms() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE digest text; candidate_kind text;
BEGIN
 IF TG_OP='UPDATE' AND NEW.promotion_terms IS DISTINCT FROM OLD.promotion_terms THEN
   RAISE EXCEPTION 'promotion declaration is immutable; prepare a new exact action' USING ERRCODE='MO092';
 END IF;
 IF NEW.action_kind<>'LISTING_PROMOTION_ACTION' THEN
   IF NEW.promotion_terms IS NOT NULL THEN
     RAISE EXCEPTION 'a description action cannot carry promotion terms' USING ERRCODE='MO092';
   END IF;
   RETURN NEW;
 END IF;
 -- Old NULL is historical evidence, never silently backfilled. Closing remains possible.
 IF TG_OP='INSERT' OR (TG_OP='UPDATE' AND NEW.state IS DISTINCT FROM OLD.state
       AND NEW.state IN ('REVIEWED','APPROVED','LAUNCHED')) THEN
   IF NEW.promotion_terms IS NULL OR NEW.execution_path<>'MANUAL' THEN
     RAISE EXCEPTION 'promotion declaration is frozen before review and manual launch' USING ERRCODE='MO092';
   END IF;
   digest:=ops.lc_promotion_terms_digest(NEW.promotion_terms);
   SELECT c.candidate_kind INTO candidate_kind FROM ops.lc_candidate c WHERE c.id=NEW.candidate_id;
   IF candidate_kind IS DISTINCT FROM NEW.promotion_terms->>'engagementKind'
     OR NOT EXISTS(SELECT 1 FROM ops.recommendation rec WHERE rec.id=NEW.recommendation_id
        AND rec.organization_id=NEW.organization_id AND rec.proposed_parameters->>'promotionTermsDigest'=digest) THEN
     RAISE EXCEPTION 'promotion candidate, declaration and recommendation identity disagree' USING ERRCODE='MO092';
   END IF;
 END IF;
 RETURN NEW;
END
$$;

CREATE FUNCTION ops.lc_action_binds_selected_simulation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE parameters jsonb;
BEGIN
 SELECT proposed_parameters INTO parameters FROM ops.recommendation
  WHERE id=NEW.recommendation_id AND organization_id=NEW.organization_id;

 IF TG_OP='INSERT' AND NEW.action_kind='LISTING_PROMOTION_ACTION'
    AND (coalesce(parameters->>'purposeCode','') NOT IN ('PROMOTION','BOUNDED_EXPLORATION')
      OR NOT COALESCE(parameters ? 'simulationId' AND parameters ? 'simulationInputsDigest',false)) THEN
  RAISE EXCEPTION 'a new promotion action requires one exact qualified simulation' USING ERRCODE='MO092';
 END IF;
 IF NEW.action_kind<>'LISTING_PROMOTION_ACTION'
    AND (parameters ? 'simulationId' OR parameters ? 'simulationInputsDigest') THEN
  RAISE EXCEPTION 'only a promotion action may bind promotion simulation evidence' USING ERRCODE='MO092';
 END IF;

 IF parameters ? 'simulationId' OR parameters ? 'simulationInputsDigest' THEN
  IF NOT (parameters ? 'simulationId' AND parameters ? 'simulationInputsDigest') OR NOT EXISTS(
   SELECT 1 FROM ops.lc_simulation s
   CROSS JOIN LATERAL (SELECT ops.lc_current_promotion_context(NEW.organization_id,NEW.platform_listing_id,
     (s.input_snapshot#>>'{context,periodStart}')::timestamptz,
     (s.input_snapshot#>>'{context,periodEnd}')::timestamptz,NEW.created_at) AS value) current_context
   WHERE s.id::text=parameters->>'simulationId'
    AND s.inputs_digest=parameters->>'simulationInputsDigest'
    AND s.organization_id=NEW.organization_id AND s.candidate_id=NEW.candidate_id
    AND s.computed_at<=NEW.created_at
    AND s.input_snapshot->>'nativeIdentityDigest'=NEW.affected_set_digest
    AND s.input_snapshot->>'promotionTermsDigest'=ops.lc_promotion_terms_digest(NEW.promotion_terms)
    AND s.input_snapshot->>'promotionTermsDigest'=ops.lc_promotion_terms_digest(s.input_snapshot->'context'->'commercialDeclaration')
    AND s.input_snapshot->>'qualificationState'='QUALIFIED_CONDITIONAL_ECONOMICS'
    AND s.input_snapshot->>'sourceKind'='QUALIFIED_MATCHED_INPUTS'
    AND s.input_snapshot->>'purposeCode'=parameters->>'purposeCode'
    AND s.input_snapshot#>>'{demandEvidence,packageId}'=NEW.calibration_package_id::text
    AND s.input_snapshot#>>'{demandEvidence,packageVersion}'=NEW.calibration_version::text
    AND s.input_snapshot#>>'{profitReferenceEvidence,packageId}'=NEW.calibration_package_id::text
    AND s.input_snapshot#>>'{profitReferenceEvidence,packageVersion}'=NEW.calibration_version::text
    AND s.input_snapshot#>>'{knownPromotionContext,coverage}'='QUALIFIED_COMPLETE'
    -- Review, approval and launch still require the prepared context to be current. A terminal
    -- move must retain every exact frozen binding but cannot be blocked by facts created by execution.
    AND (NEW.state IN ('VERIFIED','CLOSED','CANCELLED','CONTAINED') OR (
      current_context.value->>'coverage'='QUALIFIED_COMPLETE'
      AND s.input_snapshot#>>'{knownPromotionContext,digest}'=current_context.value->>'digest'))
    AND s.inputs_digest=encode(sha256(convert_to(s.input_snapshot::text,'UTF8')),'hex')) THEN
   RAISE EXCEPTION 'selected simulation must bind qualified exact scope, terms, period, context and immutable inputs'
     USING ERRCODE='MO092';
  END IF;
 END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION ops.lc_action_calibration_recheck(p_action uuid, p_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE action ops.lc_action; listing core.platform_listing; bound core.lc_calibration_package;
 current_id uuid; current_version integer; resolution text; projection jsonb; state text;
BEGIN
 SELECT * INTO action FROM ops.lc_action WHERE id=p_action;
 SELECT * INTO listing FROM core.platform_listing WHERE id=action.platform_listing_id;
 SELECT * INTO bound FROM core.lc_calibration_package WHERE id=action.calibration_package_id
  AND organization_id=action.organization_id AND package_version=action.calibration_version
  AND (scope_kind='ORGANIZATION' OR (scope_kind='PLATFORM' AND platform_code=listing.platform_code)
       OR (scope_kind='STORE' AND store_ref_id=action.store_id));
 IF bound.id IS NULL THEN RETURN jsonb_build_object('state','CALIBRATION_UNRESOLVED'); END IF;
 SELECT r.package_id,r.package_version,r.resolution_state INTO current_id,current_version,resolution
  FROM core.lc_resolve_calibration_for(action.organization_id,listing.platform_code,action.store_id,p_at,bound.purpose_code) r;
 state:='CALIBRATION_UNRESOLVED';
 IF resolution='RESOLVED' THEN
   projection:=core.lc_action_calibration_dependencies(current_id,action.action_kind,action.affected_set_id);
   IF current_id=bound.id THEN state:='CURRENT';
   ELSIF action.calibration_dependencies IS NULL THEN state:='CALIBRATION_DEPENDENCIES_UNPROVEN';
   ELSIF NOT EXISTS(SELECT 1 FROM ops.lc_calibration_governance g WHERE g.package_id=bound.id
       AND g.accepted_at<=action.created_at AND g.accepted_digest=ops.lc_calibration_digest(bound.id))
       OR bound.activated_at IS NULL OR bound.activated_at>action.created_at
       OR (bound.retired_at IS NOT NULL AND bound.retired_at<=action.created_at)
       OR bound.effective_from>action.created_at OR (bound.effective_to IS NOT NULL AND bound.effective_to<=action.created_at)
       OR action.calibration_dependencies IS DISTINCT FROM core.lc_action_calibration_dependencies(bound.id,action.action_kind,action.affected_set_id)
       THEN state:='CALIBRATION_DEPENDENCIES_UNPROVEN';
   ELSIF projection IS DISTINCT FROM action.calibration_dependencies THEN state:='CALIBRATION_DEPENDENCIES_CHANGED';
   ELSE state:='UNCHANGED_DEPENDENCIES'; END IF;
 END IF;
 RETURN jsonb_build_object('state',state,'purpose',bound.purpose_code,'boundPackageId',bound.id,
   'currentPackageId',current_id,'currentVersion',current_version,
   'dependencyDigest',CASE WHEN projection IS NULL THEN NULL ELSE encode(sha256(convert_to(projection::text,'UTF8')),'hex') END);
END $$;

CREATE FUNCTION ops.lc_action_has_meaning_review(p_action uuid, p_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT 1 FROM ops.lc_action a JOIN ops.lc_action_review r ON r.action_id=a.id
  WHERE a.id=p_action AND r.verdict='ATTESTED' AND r.reviewed_at<=p_at
    AND r.content_axis_material=ops.lc_review_meaning_axis(a.id,r.meaning_assessment)
    AND r.content_axis_material=a.content_axis_material AND r.exposure_axis_material=a.exposure_axis_material
    AND r.materiality_route=a.materiality_route AND r.exposure_evidence->>'state'='QUALIFIED'
    AND r.attested_current_text_digest IS NOT DISTINCT FROM a.current_text_digest
    AND r.attested_target_text_digest IS NOT DISTINCT FROM a.target_text_digest
    AND r.attested_affected_set_digest=a.affected_set_digest
    AND r.reviewer_user_id<>a.author_user_id)
$$;

CREATE FUNCTION ops.lc_action_moves_lawfully() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
BEGIN
    IF NEW.state = OLD.state THEN
        IF OLD.state NOT IN ('DRAFT') AND (
            NEW.target_text_digest IS DISTINCT FROM OLD.target_text_digest
            OR NEW.current_text_digest IS DISTINCT FROM OLD.current_text_digest
            OR NEW.affected_set_digest <> OLD.affected_set_digest
            OR NEW.execution_path <> OLD.execution_path
            OR NEW.materiality_route <> OLD.materiality_route) THEN
            RAISE EXCEPTION 'a reviewed action does not change what was reviewed' USING ERRCODE = 'MO092';
        END IF;
        RETURN NEW;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM ops.lc_action_transition t
                    WHERE t.from_state = OLD.state AND t.to_state = NEW.state) THEN
        RAISE EXCEPTION 'transition % -> % is not in the reviewed set', OLD.state, NEW.state
            USING ERRCODE = 'MO091';
    END IF;
    IF NEW.state = 'REVIEWED' AND NOT EXISTS (
        SELECT 1 FROM ops.lc_action_review r
         WHERE r.action_id = NEW.id AND r.verdict = 'ATTESTED'
           AND r.attested_affected_set_digest = NEW.affected_set_digest
           AND r.attested_target_text_digest IS NOT DISTINCT FROM NEW.target_text_digest) THEN
        RAISE EXCEPTION 'REVIEWED needs an attestation of the exact action' USING ERRCODE = 'MO092';
    END IF;
    IF NEW.state = 'APPROVED' AND NOT EXISTS (
        SELECT 1 FROM ops.lc_action_binding b WHERE b.action_id = NEW.id AND b.state = 'BOUND') THEN
        RAISE EXCEPTION 'APPROVED needs a frozen binding' USING ERRCODE = 'MO092';
    END IF;
    IF NEW.state = 'LAUNCHED' AND NOT EXISTS (SELECT 1 FROM ops.lc_launch l WHERE l.action_id = NEW.id) THEN
        RAISE EXCEPTION 'LAUNCHED is reached only through the launch function' USING ERRCODE = 'MO092';
    END IF;
    IF NEW.state = 'VERIFIED' AND NOT EXISTS (
        SELECT 1 FROM ops.lc_manual_verification v
          JOIN ops.lc_manual_packet p ON p.id = v.packet_id
         WHERE p.action_id = NEW.id AND v.management_match = 'MATCHED_TARGET')
       AND NOT EXISTS (
        SELECT 1 FROM ops.lc_description_command c
         WHERE c.action_id = NEW.id AND c.state = 'READBACK_MATCHED') THEN
        RAISE EXCEPTION 'VERIFIED needs a matched verification or a matched readback' USING ERRCODE = 'MO092';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.lc_action_review_is_independent() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE action ops.lc_action%ROWTYPE;
BEGIN
    SELECT * INTO action FROM ops.lc_action WHERE id = NEW.action_id;
    IF NOT FOUND OR action.organization_id <> NEW.organization_id THEN
        RAISE EXCEPTION 'review names an unknown action' USING ERRCODE = 'MO090';
    END IF;
    IF action.author_user_id = NEW.reviewer_user_id THEN
        RAISE EXCEPTION 'the author of an action cannot review it' USING ERRCODE = 'MO092';
    END IF;
    IF action.state <> 'DRAFT' THEN
        RAISE EXCEPTION 'only a draft action is reviewed' USING ERRCODE = 'MO091';
    END IF;
    IF NEW.verdict = 'ATTESTED' AND (
        NEW.attested_affected_set_digest <> action.affected_set_digest
        OR NEW.attested_target_text_digest IS DISTINCT FROM action.target_text_digest
        OR NEW.attested_current_text_digest IS DISTINCT FROM action.current_text_digest) THEN
        RAISE EXCEPTION 'an attestation names the exact digests of the action' USING ERRCODE = 'MO092';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.lc_actor_holds_action(p_actor uuid, p_org uuid, p_store uuid, p_action text) RETURNS boolean
    LANGUAGE sql
    SET search_path TO 'pg_catalog', 'iam', 'core', 'pg_temp'
    AS $$
 SELECT EXISTS (
   SELECT 1
     FROM iam.user_role_assignment r
     JOIN iam.business_role_action_scope m ON m.role_code = r.role_code
     JOIN iam.user_scope_grant s ON s.user_id = r.user_id AND s.action_code = m.action_code
     JOIN core.store st ON st.id = p_store
     JOIN core.marketplace_account account ON account.id = st.marketplace_account_id
    WHERE r.user_id = p_actor AND r.organization_id = p_org AND s.organization_id = p_org
      AND st.organization_id = p_org
      AND EXISTS (SELECT 1 FROM iam.user_account actor
                    JOIN iam.identity_provider provider ON provider.id = actor.identity_provider_id
                   WHERE actor.id = p_actor AND actor.organization_id = p_org
                     AND actor.status = 'ACTIVE' AND provider.status = 'ACTIVE')
      AND r.status = 'ACTIVE' AND m.action_code = p_action
      AND r.effective_from <= clock_timestamp()
      AND (r.effective_to IS NULL OR r.effective_to > clock_timestamp())
      AND s.status = 'ACTIVE' AND s.effective_from <= clock_timestamp()
      AND (s.effective_to IS NULL OR s.effective_to > clock_timestamp())
      AND (s.organization_ref_id = p_org OR s.store_ref_id = p_store
           OR s.marketplace_account_ref_id = account.id
           OR s.legal_entity_ref_id = account.legal_entity_id))
$$;

CREATE FUNCTION ops.lc_allowance_projection(p_action uuid, p_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'core', 'pg_temp'
    SET "TimeZone" TO 'UTC'
    SET "DateStyle" TO 'ISO, YMD'
    AS $_$
DECLARE
 action ops.lc_action%ROWTYPE; listing core.platform_listing%ROWTYPE; simulation ops.lc_simulation%ROWTYPE;
 allowance ops.lc_exposure_allowance%ROWTYPE; engagement ops.lc_promotion_engagement%ROWTYPE;
 resolved_package uuid; policy jsonb; reserves jsonb; required_axes jsonb; axis text;
 composition text; gaps text[]:='{}'; axes jsonb:='[]'; scoped_ids uuid[];
 occupied numeric; requested numeric; canonical numeric; reserve numeric; headroom numeric;
 variants uuid[]; members uuid[]; unresolved boolean; snapshot jsonb; member jsonb; demand jsonb;
 promotion_context jsonb; promotion_revenue numeric; promotion_fixed numeric; promotion_currency text;
 material_revenue numeric; material_currency text; material_share numeric; currency_count integer;
 demand_source jsonb;
BEGIN
 SELECT * INTO action FROM ops.lc_action WHERE id=p_action;
 IF NOT FOUND THEN RAISE EXCEPTION 'action does not exist' USING ERRCODE='MO090'; END IF;
 SELECT * INTO STRICT listing FROM core.platform_listing WHERE id=action.platform_listing_id;
 SELECT (r.value->>'currentPackageId')::uuid INTO resolved_package
   FROM (SELECT ops.lc_action_calibration_recheck(action.id,p_at) AS value) r
   WHERE r.value->>'state' IN ('CURRENT','UNCHANGED_DEPENDENCIES');
 IF resolved_package IS NULL THEN gaps:=array_append(gaps,'ALLOWANCE_POLICY_UNRESOLVED');
 ELSE
   SELECT value_json INTO policy FROM core.lc_calibration_value v
     WHERE v.package_id=resolved_package AND category_code='ALLOWANCE_AXES';
   SELECT value_json INTO reserves FROM core.lc_calibration_value v
     WHERE v.package_id=resolved_package AND category_code='ALLOWANCE_RESERVE';
 END IF;
 IF jsonb_typeof(policy)='array' THEN required_axes:=policy; composition:='SINGLE_SCOPE';
 ELSIF jsonb_typeof(policy)='object' AND policy->>'scopeComposition'='ALL_APPLICABLE'
    AND NOT EXISTS(SELECT 1 FROM jsonb_object_keys(policy) k WHERE k NOT IN ('axes','scopeComposition')) THEN
   required_axes:=policy->'axes'; composition:='ALL_APPLICABLE';
 END IF;
 IF jsonb_typeof(required_axes) IS DISTINCT FROM 'array' THEN
   required_axes:='[]'; gaps:=array_append(gaps,'ALLOWANCE_AXES_UNRESOLVED');
 END IF;
 IF jsonb_array_length(required_axes)=0 OR jsonb_array_length(required_axes)>4
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(required_axes) x WHERE jsonb_typeof(x)<>'string'
     OR x#>>'{}' NOT IN ('CONCURRENT_LISTINGS','AFFECTED_VARIANTS','REVENUE_EXPOSURE','CATEGORY_SHARE'))
   OR (SELECT count(*)<>count(DISTINCT x) FROM jsonb_array_elements(required_axes) x) THEN
   required_axes:='[]'; gaps:=array_append(gaps,'ALLOWANCE_AXES_UNRESOLVED');
 END IF;
 SELECT array_agg(DISTINCT value ORDER BY value) INTO variants FROM core.lc_affected_set s,
   unnest(s.platform_listing_variant_ids) value WHERE s.id=action.affected_set_id
     AND s.resolution_state='COMPLETE' AND s.identity_lineage IS NOT NULL;

 -- Current retained-sales evidence is the canonical category share and, for
 -- non-promotion actions, the exact monetary exposure of the affected members.
 IF action.materiality_evidence->>'state'='QUALIFIED'
    AND jsonb_typeof(action.materiality_evidence#>'{projection,memberValues}')='array'
    AND coalesce(action.materiality_evidence#>>'{projection,share}','') ~ '^[0-9]+([.][0-9]+)?$' THEN
   material_share:=(action.materiality_evidence#>>'{projection,share}')::numeric;
   SELECT sum((value->>'numericValue')::numeric),min(value->>'currencyCode'),count(DISTINCT value->>'currencyCode')
     INTO material_revenue,material_currency,currency_count
   FROM jsonb_array_elements(action.materiality_evidence#>'{projection,memberValues}')
   WHERE coalesce(value->>'numericValue','') ~ '^[0-9]+([.][0-9]+)?$';
   IF currency_count<>1 OR material_revenue IS NULL THEN material_revenue:=NULL; material_currency:=NULL; END IF;
 END IF;

 IF action.action_kind='LISTING_PROMOTION_ACTION' THEN
   SELECT s.* INTO simulation FROM ops.recommendation r JOIN ops.lc_simulation s
     ON s.id::text=r.proposed_parameters->>'simulationId'
      AND s.inputs_digest=r.proposed_parameters->>'simulationInputsDigest'
    WHERE r.id=action.recommendation_id AND s.organization_id=action.organization_id
      AND s.candidate_id=action.candidate_id AND s.computed_at<=action.created_at
      AND s.input_snapshot->>'qualificationState'='QUALIFIED_CONDITIONAL_ECONOMICS'
      AND s.input_snapshot->>'nativeIdentityDigest'=action.affected_set_digest
      AND s.input_snapshot->>'promotionTermsDigest'=action.promotion_terms_digest;
   IF simulation.id IS NOT NULL
      AND coalesce(simulation.input_snapshot#>>'{context,periodStart}','') ~ '^[-+0-9T:. Z]+$'
      AND coalesce(simulation.input_snapshot#>>'{context,periodEnd}','') ~ '^[-+0-9T:. Z]+$' THEN
     promotion_context:=ops.lc_current_promotion_context(action.organization_id,action.platform_listing_id,
       (simulation.input_snapshot#>>'{context,periodStart}')::timestamptz,
       (simulation.input_snapshot#>>'{context,periodEnd}')::timestamptz,p_at);
     IF promotion_context->>'coverage'='QUALIFIED_COMPLETE'
        AND promotion_context->>'digest'=simulation.input_snapshot#>>'{knownPromotionContext,digest}'
        AND simulation.input_snapshot#>>'{revenueEvidence,state}'='COMMERCIAL_REVENUE_MATCH'
        AND simulation.input_snapshot#>>'{fixedFeeEvidence,state}'='ACTIVITY_FIXED_FEE_MATCH'
        AND coalesce(simulation.input_snapshot#>>'{inputs,expenses,fixedPromotionFee,amount}','') ~ '^[0-9]+([.][0-9]+)?$' THEN
       SELECT max((result->>'netRevenue')::numeric) INTO promotion_revenue
       FROM jsonb_array_elements(simulation.results) result
       JOIN jsonb_array_elements(simulation.scenario_set) scenario ON scenario->>'code'=result->>'code'
       WHERE scenario->>'necessary'='true' AND result->>'state'='COMPUTED'
         AND coalesce(result->>'netRevenue','') ~ '^[0-9]+([.][0-9]+)?$';
       promotion_fixed:=(simulation.input_snapshot#>>'{inputs,expenses,fixedPromotionFee,amount}')::numeric;
       promotion_currency:=simulation.input_snapshot#>>'{inputs,currencyCode}';
       IF promotion_revenue IS NOT NULL THEN promotion_revenue:=promotion_revenue+promotion_fixed; END IF;
     END IF;
   END IF;
 END IF;

 FOR axis IN SELECT jsonb_array_elements_text(required_axes) ORDER BY 1 LOOP
   IF coalesce(reserves->>axis,'') !~ '^[0-9]+([.][0-9]{1,4})?$' OR length(reserves->>axis)>19 THEN
     gaps:=array_append(gaps,axis||':RESERVE_UNRESOLVED'); CONTINUE;
   END IF;
   reserve:=(reserves->>axis)::numeric;
   SELECT array_agg(a.id ORDER BY a.scope_key,a.id) INTO scoped_ids
     FROM ops.lc_allowances_for(action.organization_id,action.platform_listing_id,p_at) a WHERE a.axis_code=axis;
   IF coalesce(cardinality(scoped_ids),0)=0 THEN gaps:=array_append(gaps,axis||':ALLOWANCE_MISSING'); CONTINUE; END IF;
   IF composition='SINGLE_SCOPE' AND cardinality(scoped_ids)<>1 THEN
     gaps:=array_append(gaps,axis||':SCOPE_COMPOSITION_UNRESOLVED'); CONTINUE;
   END IF;
   FOR allowance IN SELECT a.* FROM ops.lc_exposure_allowance a WHERE a.id=ANY(scoped_ids)
       ORDER BY a.scope_key,a.id LOOP
     members:='{}'; unresolved:=false; occupied:=0; requested:=NULL; canonical:=NULL; demand_source:=NULL;
     IF axis IN ('CONCURRENT_LISTINGS','AFFECTED_VARIANTS') THEN
       WITH outstanding AS (
         SELECT a.platform_listing_id,a.affected_set_id FROM ops.lc_exposure_occupation o
         JOIN ops.lc_action a ON a.id=o.action_id JOIN core.platform_listing l ON l.id=a.platform_listing_id
         WHERE o.organization_id=action.organization_id AND o.axis_code=axis AND o.state<>'RELEASED'
           AND (allowance.scope_kind='ORGANIZATION'
             OR (allowance.scope_kind='PLATFORM' AND allowance.platform_code=l.platform_code)
             OR (allowance.scope_kind='STORE' AND allowance.store_ref_id=a.store_id)))
       SELECT CASE WHEN axis='CONCURRENT_LISTINGS' THEN
          (SELECT array_agg(DISTINCT platform_listing_id) FROM outstanding)
        ELSE (SELECT array_agg(DISTINCT value) FROM outstanding o JOIN core.lc_affected_set s ON s.id=o.affected_set_id,
          unnest(s.platform_listing_variant_ids) value) END,
        EXISTS(SELECT 1 FROM outstanding o LEFT JOIN core.lc_affected_set s ON s.id=o.affected_set_id
          WHERE axis='AFFECTED_VARIANTS' AND (s.id IS NULL OR s.resolution_state<>'COMPLETE'
            OR s.identity_lineage IS NULL OR coalesce(cardinality(s.platform_listing_variant_ids),0)=0))
        INTO members,unresolved;
       FOR engagement IN SELECT e.* FROM ops.lc_promotion_engagement e JOIN core.platform_listing l
          ON l.id=e.platform_listing_id AND l.organization_id=e.organization_id
         WHERE e.organization_id=action.organization_id AND e.state IN ('ACTIVE','EXITING')
           AND NOT EXISTS(SELECT 1 FROM ops.lc_exposure_occupation o
             WHERE o.action_id=e.action_id AND o.axis_code=axis AND o.state<>'RELEASED')
           AND (allowance.scope_kind='ORGANIZATION'
             OR (allowance.scope_kind='PLATFORM' AND allowance.platform_code=l.platform_code)
             OR (allowance.scope_kind='STORE' AND allowance.store_ref_id=e.store_id)) LOOP
         IF axis='CONCURRENT_LISTINGS' THEN members:=array_append(coalesce(members,'{}'),engagement.platform_listing_id);
         ELSE
           snapshot:=core.lc_listing_identity_snapshot(engagement.platform_listing_id,p_at);
           IF snapshot#>>'{nativeScope,state}'<>'COMPLETE' THEN unresolved:=true;
           ELSE
             FOR member IN SELECT value FROM jsonb_array_elements(snapshot->'members') LOOP
               members:=array_append(coalesce(members,'{}'),(member->>'listingVariantId')::uuid);
             END LOOP;
           END IF;
         END IF;
       END LOOP;
       SELECT array_agg(DISTINCT value ORDER BY value) INTO members FROM unnest(coalesce(members,'{}')) value;
       occupied:=coalesce(cardinality(members),0);
       IF axis='CONCURRENT_LISTINGS' AND allowance.unit_code='COUNT' THEN
         canonical:=1; requested:=CASE WHEN action.platform_listing_id=ANY(coalesce(members,'{}')) THEN 0 ELSE 1 END;
       ELSIF axis='AFFECTED_VARIANTS' AND allowance.unit_code='COUNT' AND cardinality(variants)>0 THEN
         canonical:=cardinality(variants);
         SELECT count(*) INTO requested FROM unnest(variants) value WHERE NOT(value=ANY(coalesce(members,'{}')));
       END IF;
       demand_source:=jsonb_build_object('kind','FROZEN_AFFECTED_IDENTITY','affectedSetId',action.affected_set_id,
          'affectedSetDigest',action.affected_set_digest);
     ELSE
       SELECT coalesce(sum(o.occupied_value),0),coalesce(bool_or(o.state='UNKNOWN'
           AND (o.demand_evidence IS NULL OR o.occupied_value<=0)),false)
         INTO occupied,unresolved
       FROM ops.lc_exposure_occupation o JOIN ops.lc_action occupied_action ON occupied_action.id=o.action_id
       JOIN core.platform_listing l ON l.id=occupied_action.platform_listing_id
       WHERE o.organization_id=action.organization_id AND o.axis_code=axis AND o.state<>'RELEASED'
         AND (allowance.scope_kind='ORGANIZATION'
           OR (allowance.scope_kind='PLATFORM' AND allowance.platform_code=l.platform_code)
           OR (allowance.scope_kind='STORE' AND allowance.store_ref_id=occupied_action.store_id));
       FOR engagement IN SELECT e.* FROM ops.lc_promotion_engagement e JOIN core.platform_listing l
          ON l.id=e.platform_listing_id AND l.organization_id=e.organization_id
         WHERE e.organization_id=action.organization_id
           AND ((axis='REVENUE_EXPOSURE' AND e.state<>'CLEARED')
             OR (axis='CATEGORY_SHARE' AND e.state IN ('ACTIVE','EXITING')))
           AND NOT EXISTS(SELECT 1 FROM ops.lc_exposure_occupation o
             WHERE o.action_id=e.action_id AND o.axis_code=axis AND o.state<>'RELEASED')
           AND (allowance.scope_kind='ORGANIZATION'
             OR (allowance.scope_kind='PLATFORM' AND allowance.platform_code=l.platform_code)
             OR (allowance.scope_kind='STORE' AND allowance.store_ref_id=e.store_id)) LOOP
         demand:=engagement.axis_demands->axis;
         IF jsonb_typeof(demand) IS DISTINCT FROM 'object' OR demand->>'unitCode' IS DISTINCT FROM allowance.unit_code
            OR coalesce(demand->>'value','') !~ '^[0-9]+([.][0-9]{1,4})?$' THEN unresolved:=true;
         ELSE occupied:=occupied+(demand->>'value')::numeric; END IF;
       END LOOP;
       IF axis='REVENUE_EXPOSURE' THEN
         IF action.action_kind='LISTING_PROMOTION_ACTION' AND promotion_revenue IS NOT NULL
            AND allowance.unit_code=promotion_currency THEN
           canonical:=ceil(promotion_revenue*10000)/10000;
           demand_source:=jsonb_build_object('kind','SELECTED_QUALIFIED_SIMULATION','simulationId',simulation.id,
             'inputsDigest',simulation.inputs_digest,'contextDigest',promotion_context->>'digest',
             'maximumNecessaryRevenue',promotion_revenue-promotion_fixed,'fixedCommitment',promotion_fixed);
         ELSIF action.action_kind<>'LISTING_PROMOTION_ACTION' AND material_revenue IS NOT NULL
            AND allowance.unit_code=material_currency THEN
           canonical:=ceil(material_revenue*10000)/10000;
           demand_source:=jsonb_build_object('kind','CANONICAL_RETAINED_SALES_EXPOSURE',
             'materialityEvidence',action.materiality_evidence);
         END IF;
       ELSIF axis='CATEGORY_SHARE' AND allowance.unit_code='RATIO' AND material_share IS NOT NULL THEN
         canonical:=ceil(material_share*10000)/10000;
         demand_source:=jsonb_build_object('kind','CANONICAL_RETAINED_SALES_SHARE',
           'materialityEvidence',action.materiality_evidence);
       END IF;
       requested:=CASE WHEN EXISTS(SELECT 1 FROM ops.lc_exposure_occupation o
          WHERE o.action_id=action.id AND o.axis_code=axis AND o.state<>'RELEASED') THEN 0 ELSE canonical END;
     END IF;
     IF unresolved OR requested IS NULL THEN gaps:=array_append(gaps,axis||':CANONICAL_DEMAND_UNRESOLVED'); requested:=NULL; END IF;
     IF allowance.reserve_value<reserve THEN gaps:=array_append(gaps,axis||':RESERVE_BELOW_ACCEPTED_POLICY'); END IF;
     headroom:=allowance.limit_value-allowance.reserve_value-occupied;
     axes:=axes||jsonb_build_array(jsonb_build_object('allowanceId',allowance.id,'axisCode',axis,
       'scopeKind',allowance.scope_kind,'limitValue',allowance.limit_value,'reserveValue',allowance.reserve_value,
       'occupiedValue',occupied,'requestedValue',requested,'canonicalDemand',canonical,'demandSource',demand_source,
       'headroom',headroom,'sufficient',requested IS NOT NULL AND requested<=headroom,
       'unitCode',allowance.unit_code,'scopeKey',allowance.scope_key,'allowanceVersion',allowance.allowance_version));
   END LOOP;
 END LOOP;
 RETURN jsonb_build_object('platformListingId',action.platform_listing_id,'actionId',action.id,
   'affectedSetId',action.affected_set_id,'affectedSetDigest',action.affected_set_digest,
   'calibrationPackageId',resolved_package,'policy',policy,'evaluatedAt',p_at,
   'axes',axes,'resolved',cardinality(gaps)=0,'gaps',to_jsonb(gaps));
END $_$;

CREATE TABLE ops.lc_exposure_allowance (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    allowance_version integer NOT NULL,
    scope_kind text NOT NULL,
    platform_code text,
    store_ref_id uuid,
    scope_key text GENERATED ALWAYS AS (((((scope_kind || ':'::text) || COALESCE(platform_code, ''::text)) || ':'::text) || COALESCE((store_ref_id)::text, ''::text))) STORED,
    axis_code text NOT NULL,
    limit_value numeric(18,4) NOT NULL,
    reserve_value numeric(18,4) NOT NULL,
    unit_code text NOT NULL,
    published_by_user_id uuid NOT NULL,
    published_at timestamp with time zone NOT NULL,
    evidence_reference text NOT NULL,
    effective_from timestamp with time zone NOT NULL,
    effective_to timestamp with time zone,
    status text NOT NULL,
    CONSTRAINT lc_exposure_allowance_axis_ck CHECK ((axis_code = ANY (ARRAY['CONCURRENT_LISTINGS'::text, 'AFFECTED_VARIANTS'::text, 'REVENUE_EXPOSURE'::text, 'CATEGORY_SHARE'::text]))),
    CONSTRAINT lc_exposure_allowance_bounds_ck CHECK (((limit_value > (0)::numeric) AND (reserve_value >= (0)::numeric) AND (reserve_value < limit_value))),
    CONSTRAINT lc_exposure_allowance_range_ck CHECK (((effective_to IS NULL) OR (effective_to > effective_from))),
    CONSTRAINT lc_exposure_allowance_reference_ck CHECK (((length(btrim(evidence_reference)) >= 1) AND (length(btrim(evidence_reference)) <= 512))),
    CONSTRAINT lc_exposure_allowance_scope_ck CHECK ((scope_kind = ANY (ARRAY['ORGANIZATION'::text, 'PLATFORM'::text, 'STORE'::text]))),
    CONSTRAINT lc_exposure_allowance_scope_shape_ck CHECK ((((scope_kind = 'ORGANIZATION'::text) AND (platform_code IS NULL) AND (store_ref_id IS NULL)) OR ((scope_kind = 'PLATFORM'::text) AND (platform_code IS NOT NULL) AND (store_ref_id IS NULL)) OR ((scope_kind = 'STORE'::text) AND (platform_code IS NULL) AND (store_ref_id IS NOT NULL)))),
    CONSTRAINT lc_exposure_allowance_status_ck CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'RETIRED'::text]))),
    CONSTRAINT lc_exposure_allowance_unit_ck CHECK ((unit_code ~ '^[A-Z][A-Z0-9_]{0,31}$'::text)),
    CONSTRAINT lc_exposure_allowance_version_ck CHECK ((allowance_version >= 1))
);

CREATE FUNCTION ops.lc_allowances_for(p_org uuid, p_listing uuid, p_at timestamp with time zone) RETURNS SETOF ops.lc_exposure_allowance
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'core', 'pg_temp'
    AS $$
 SELECT a.* FROM ops.lc_exposure_allowance a
 JOIN core.platform_listing l ON l.id=p_listing AND l.organization_id=p_org
 WHERE a.organization_id=p_org AND a.status='ACTIVE'
   AND a.published_at<=p_at AND a.effective_from<=p_at AND (a.effective_to IS NULL OR a.effective_to>p_at)
   AND (a.scope_kind='ORGANIZATION' OR (a.scope_kind='PLATFORM' AND a.platform_code=l.platform_code)
        OR (a.scope_kind='STORE' AND a.store_ref_id=l.store_id))
$$;

CREATE FUNCTION ops.lc_api_verified_requires_execution_receipt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
BEGIN
    IF NEW.execution_path='API' AND NEW.state='VERIFIED' AND OLD.state<>NEW.state AND NOT EXISTS (
        SELECT 1 FROM ops.lc_execution_receipt r WHERE r.action_id=NEW.id AND r.organization_id=NEW.organization_id
          AND r.execution_state='MANAGEMENT_VERIFIED' AND r.evidence->>'targetTextDigest'=NEW.target_text_digest
          AND r.evidence->>'affectedSetDigest'=NEW.affected_set_digest) THEN
        RAISE EXCEPTION 'API verification needs exact native completion and management evidence' USING ERRCODE='MO093';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.lc_approval_binds_reviewed_plan() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE plan ops.lc_evaluation_plan%ROWTYPE; approval ops.approval_decision%ROWTYPE;
 action ops.lc_action%ROWTYPE; purpose text; expected_digest text; until_at timestamptz;
BEGIN
 SELECT * INTO STRICT action FROM ops.lc_action WHERE id=NEW.action_id;
 SELECT * INTO STRICT approval FROM ops.approval_decision WHERE id=NEW.approval_decision_id;
 SELECT r.proposed_parameters->>'purposeCode' INTO purpose FROM ops.recommendation r WHERE r.id=action.recommendation_id;
 expected_digest:=ops.lc_purpose_basis_digest(purpose,action.purpose_basis);
 until_at:=(action.purpose_basis->>'useUntil')::timestamptz;
 IF approval.decided_at>NEW.bound_at OR approval.decided_at<action.created_at
    OR action.organization_id<>NEW.organization_id
    OR (until_at IS NOT NULL AND (until_at<=statement_timestamp() OR NEW.expires_at>until_at))
    OR (NEW.purpose_basis_digest IS NOT NULL AND NEW.purpose_basis_digest IS DISTINCT FROM expected_digest) THEN
   RAISE EXCEPTION 'Approval must bind the exact current purpose within its use deadline' USING ERRCODE='MO092';
 END IF;
 NEW.purpose_basis_digest:=expected_digest;
 IF purpose IN ('DESCRIPTION_CORRECTION','BOUNDED_EXPLORATION') THEN
   IF expected_digest IS NULL OR NEW.evaluation_plan_digest IS NOT NULL
      OR NOT EXISTS(SELECT 1 FROM ops.lc_action_review r WHERE r.action_id=action.id
          AND r.verdict='ATTESTED' AND r.purpose_basis_digest=expected_digest
          AND r.evaluation_plan_digest IS NULL AND r.reviewed_at<=approval.decided_at
          AND r.attested_target_text_digest IS NOT DISTINCT FROM NEW.target_text_digest
          AND r.attested_current_text_digest IS NOT DISTINCT FROM NEW.current_text_digest
          AND r.attested_affected_set_digest=NEW.affected_set_digest) THEN
     RAISE EXCEPTION 'Approval requires the exact independently reviewed nonformal use basis' USING ERRCODE='MO092';
   END IF;
   RETURN NEW;
 END IF;
 SELECT * INTO plan FROM ops.lc_evaluation_plan WHERE action_id=NEW.action_id;
 IF NOT FOUND THEN
   RAISE EXCEPTION 'approval cannot acquire an evaluation plan after its decision' USING ERRCODE='MO092';
 END IF;
 IF plan.organization_id<>NEW.organization_id OR plan.frozen_at>approval.decided_at
    OR (NEW.evaluation_plan_digest IS NOT NULL AND NEW.evaluation_plan_digest<>plan.plan_digest)
    OR NOT EXISTS (SELECT 1 FROM ops.lc_action_review r WHERE r.action_id=NEW.action_id
        AND r.verdict='ATTESTED' AND r.evaluation_plan_digest=plan.plan_digest
        AND r.attested_target_text_digest IS NOT DISTINCT FROM NEW.target_text_digest
        AND r.attested_current_text_digest IS NOT DISTINCT FROM NEW.current_text_digest
        AND r.attested_affected_set_digest=NEW.affected_set_digest
        AND r.reviewed_at<=approval.decided_at) THEN
   RAISE EXCEPTION 'approval requires the exact pre-existing, independently reviewed plan' USING ERRCODE='MO092';
 END IF;
 NEW.evaluation_plan_digest:=plan.plan_digest;
 RETURN NEW;
END $$;

CREATE FUNCTION ops.lc_authority_snapshot(p_recommendation_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'core', 'pg_temp'
    AS $$
    SELECT jsonb_build_object(
        'proposal', jsonb_build_object(
            'id', r.id, 'organizationId', r.organization_id, 'storeId', r.store_id,
            'subjectKind', r.subject_kind, 'subjectId', r.subject_id,
            'actionKind', r.action_kind, 'parameters', r.proposed_parameters,
            'risk', r.risk_label, 'window', r.window_code,
            'validUntil', r.valid_until, 'entityDigest', r.entity_version_digest),
        'currentEntityDigest', r.entity_version_digest,
        'action', CASE WHEN a.id IS NULL THEN NULL ELSE jsonb_build_object(
            'id', a.id, 'version', a.version, 'state', a.state,
            'executionPath', a.execution_path, 'materialityRoute', a.materiality_route,
            'contentAxisMaterial', a.content_axis_material,
            'exposureAxisMaterial', a.exposure_axis_material,
            'affectedSetDigest', a.affected_set_digest,
            'targetTextDigest', a.target_text_digest,
            'currentTextDigest', a.current_text_digest,
            'kizMarkedDeclared', a.kiz_marked_declared,
            'authorUserId', a.author_user_id) END,
        'review', review.item,
        'calibrationPackageId', a.calibration_package_id,
        'calibrationVersion', a.calibration_version)
      FROM ops.recommendation r
      LEFT JOIN ops.lc_action a ON a.recommendation_id = r.id AND a.organization_id = r.organization_id
      LEFT JOIN LATERAL (
          SELECT jsonb_build_object('id', v.id, 'reviewerUserId', v.reviewer_user_id,
                     'verdict', v.verdict, 'reviewedAt', v.reviewed_at) AS item
            FROM ops.lc_action_review v
           WHERE v.action_id = a.id
           ORDER BY v.reviewed_at DESC, v.id DESC LIMIT 1
      ) review ON true
     WHERE r.id = p_recommendation_id
$$;

CREATE TABLE ops.lc_manual_verification (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    packet_id uuid NOT NULL,
    verifier_user_id uuid,
    verification_basis text NOT NULL,
    management_match text NOT NULL,
    management_observation_id uuid,
    display_observation_id uuid,
    display_state text NOT NULL,
    verified_at timestamp with time zone NOT NULL,
    note text NOT NULL,
    observation_binding jsonb,
    promotion_observation_id uuid,
    qualification_state text DEFAULT 'HISTORICAL_UNQUALIFIED'::text NOT NULL,
    CONSTRAINT lc_manual_verification_basis_ck CHECK ((verification_basis = ANY (ARRAY['INDEPENDENT_HUMAN'::text, 'OFFICIAL_EVIDENCE'::text]))),
    CONSTRAINT lc_manual_verification_display_ck CHECK ((display_state = ANY (ARRAY['DISPLAYED'::text, 'NOT_DISPLAYED'::text, 'UNKNOWN'::text]))),
    CONSTRAINT lc_manual_verification_display_evidence_ck CHECK (((display_state = 'UNKNOWN'::text) OR (display_observation_id IS NOT NULL))),
    CONSTRAINT lc_manual_verification_management_evidence_ck CHECK ((((management_observation_id IS NULL) OR (promotion_observation_id IS NULL)) AND ((management_match = 'UNKNOWN'::text) OR (management_observation_id IS NOT NULL) OR (promotion_observation_id IS NOT NULL)))),
    CONSTRAINT lc_manual_verification_match_ck CHECK ((management_match = ANY (ARRAY['MATCHED_TARGET'::text, 'MATCHED_PRIOR'::text, 'DIFFERENT'::text, 'UNKNOWN'::text]))),
    CONSTRAINT lc_manual_verification_note_ck CHECK (((length(btrim(note)) >= 1) AND (length(btrim(note)) <= 2000))),
    CONSTRAINT lc_manual_verification_observation_binding_check CHECK (((observation_binding IS NULL) OR (jsonb_typeof(observation_binding) = 'object'::text))),
    CONSTRAINT lc_manual_verification_qualification_ck CHECK ((qualification_state = ANY (ARRAY['HISTORICAL_UNQUALIFIED'::text, 'QUALIFIED'::text, 'UNQUALIFIED'::text, 'DEVIATION_RETAINED'::text, 'CURRENTLY_CONTAINED'::text]))),
    CONSTRAINT lc_manual_verification_verifier_ck CHECK (((verification_basis = 'INDEPENDENT_HUMAN'::text) = (verifier_user_id IS NOT NULL)))
);

CREATE FUNCTION ops.lc_bind_promotion_participation(p_verification ops.lc_manual_verification) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'core', 'pg_temp'
    SET "TimeZone" TO 'UTC'
    SET "DateStyle" TO 'ISO, YMD'
    AS $$
DECLARE packet ops.lc_manual_packet%ROWTYPE; action ops.lc_action%ROWTYPE;
 observed core.lc_promotion_observation%ROWTYPE; provenance core.fact_provenance%ROWTYPE;
 operation_at timestamptz; matches_target boolean;
BEGIN
 SELECT * INTO STRICT packet FROM ops.lc_manual_packet WHERE id=p_verification.packet_id;
 SELECT * INTO STRICT action FROM ops.lc_action WHERE id=packet.action_id;
 IF action.action_kind<>'LISTING_PROMOTION_ACTION' OR action.promotion_terms_digest IS NULL
   OR packet.promotion_terms_digest IS DISTINCT FROM action.promotion_terms_digest
   OR packet.organization_id<>p_verification.organization_id OR p_verification.management_observation_id IS NOT NULL
   OR p_verification.display_observation_id IS NOT NULL OR p_verification.display_state<>'UNKNOWN'
   OR p_verification.management_match='MATCHED_PRIOR' THEN
   RAISE EXCEPTION 'promotion participation uses its own exact evidence, not description or release inference' USING ERRCODE='MO092';
 END IF;
 SELECT max(operation_time) INTO operation_at FROM ops.lc_manual_report
   WHERE packet_id=packet.id AND reporter_user_id=packet.executor_user_id AND reported_at<=p_verification.verified_at;
 IF operation_at IS NULL OR operation_at<packet.issued_at OR operation_at>packet.expires_at THEN
   RAISE EXCEPTION 'promotion participation needs the reported operation within the exact packet authority' USING ERRCODE='MO092';
 END IF;
 IF p_verification.promotion_observation_id IS NULL THEN
   IF p_verification.management_match<>'UNKNOWN' THEN
     RAISE EXCEPTION 'participation qualification needs an observation' USING ERRCODE='MO093';
   END IF;
   RETURN jsonb_build_object('actionId',action.id,'packetId',packet.id,'promotionTermsDigest',action.promotion_terms_digest,
     'purpose','PARTICIPATION','claimExtent','UNKNOWN');
 END IF;
 SELECT * INTO STRICT observed FROM core.lc_promotion_observation WHERE id=p_verification.promotion_observation_id;
 SELECT * INTO STRICT provenance FROM core.fact_provenance WHERE id=observed.provenance_id;
 IF observed.organization_id<>action.organization_id OR provenance.organization_id<>action.organization_id
   OR observed.platform_listing_id<>action.platform_listing_id OR observed.observed_at<operation_at
   OR observed.acquired_at>p_verification.verified_at
   OR provenance.source_time IS DISTINCT FROM observed.observed_at
   OR provenance.ingestion_time IS DISTINCT FROM observed.acquired_at
   OR observed.native_promotion_key IS DISTINCT FROM action.promotion_terms->>'nativePromotionKey'
   OR observed.engagement_kind IS DISTINCT FROM action.promotion_terms->>'engagementKind' THEN
   RAISE EXCEPTION 'promotion observation is outside exact native identity, operation or custody time' USING ERRCODE='MO092';
 END IF;
 IF provenance.source_kind='MANUAL_ENTRY' THEN
   IF p_verification.verification_basis<>'INDEPENDENT_HUMAN' OR p_verification.verifier_user_id IS NULL
     OR NOT ops.lc_actor_holds_action(p_verification.verifier_user_id,action.organization_id,action.store_id,'LISTING_MANUAL_VERIFY')
     OR provenance.recorded_by_user_id IS NULL
     OR provenance.recorded_by_user_id=packet.executor_user_id
     OR EXISTS(SELECT 1 FROM ops.lc_manual_report r WHERE r.packet_id=packet.id
          AND r.reporter_user_id=provenance.recorded_by_user_id) THEN
     RAISE EXCEPTION 'executor reports cannot become independent promotion evidence' USING ERRCODE='MO092';
   END IF;
 ELSIF provenance.source_kind<>'MARKETPLACE_RAW' OR provenance.raw_observation_id IS NULL
   OR p_verification.verification_basis<>'OFFICIAL_EVIDENCE' THEN
   RAISE EXCEPTION 'official participation needs retained marketplace raw custody' USING ERRCODE='MO092';
 END IF;
 matches_target:=coalesce(observed.participation_state='PARTICIPATING' AND observed.declaration_digest=action.promotion_terms_digest,false);
 IF (p_verification.management_match='MATCHED_TARGET' AND NOT matches_target)
   OR (p_verification.management_match='DIFFERENT' AND (matches_target OR observed.participation_state='UNKNOWN'
       OR (observed.participation_state='PARTICIPATING' AND observed.declaration_digest IS NULL))) THEN
   RAISE EXCEPTION 'participation claim contradicts the exact observation' USING ERRCODE='MO093';
 END IF;
 RETURN jsonb_build_object('actionId',action.id,'listingId',action.platform_listing_id,'packetId',packet.id,
   'promotionTermsDigest',action.promotion_terms_digest,'promotionObservationId',observed.id,
   'observedDeclarationDigest',observed.declaration_digest,'participationState',observed.participation_state,
   'observationDigest',encode(sha256(convert_to(to_jsonb(observed)::text,'UTF8')),'hex'),
   'operationAt',operation_at,'observedAt',observed.observed_at,'verifiedAt',p_verification.verified_at,
   'purpose','PARTICIPATION','claimExtent','OBSERVED_INSTANT_ONLY');
END
$$;

CREATE FUNCTION ops.lc_binding_gaps(p_action uuid) RETURNS text[]
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE reasons text[]; action ops.lc_action%ROWTYPE; binding ops.lc_action_binding%ROWTYPE;
 purpose text; expected_digest text; nonformal boolean;
BEGIN
 reasons:=ops.lc_binding_gaps_v0107(p_action);
 SELECT * INTO action FROM ops.lc_action WHERE id=p_action;
 IF NOT FOUND THEN RETURN reasons; END IF;
 SELECT * INTO binding FROM ops.lc_action_binding WHERE action_id=p_action;
 IF NOT FOUND THEN RETURN reasons; END IF;
 SELECT r.proposed_parameters->>'purposeCode' INTO purpose FROM ops.recommendation r WHERE r.id=action.recommendation_id;
 nonformal:=purpose IN ('DESCRIPTION_CORRECTION','BOUNDED_EXPLORATION');
 IF nonformal THEN reasons:=array_remove(reasons,'EVALUATION_PLAN_BINDING_MISSING_OR_CHANGED'); END IF;
 IF nonformal OR action.purpose_basis IS NOT NULL THEN
   expected_digest:=ops.lc_purpose_basis_digest(purpose,action.purpose_basis);
   IF expected_digest IS NULL OR binding.purpose_basis_digest IS DISTINCT FROM expected_digest
      OR (nonformal AND (binding.evaluation_plan_digest IS NOT NULL OR NOT EXISTS(
          SELECT 1 FROM ops.lc_action_review r JOIN ops.approval_decision d ON d.id=binding.approval_decision_id
           WHERE r.action_id=action.id AND r.verdict='ATTESTED' AND r.purpose_basis_digest=expected_digest
             AND r.evaluation_plan_digest IS NULL AND r.reviewed_at<=d.decided_at AND d.decided_at<=binding.bound_at))) THEN
     reasons:=array_append(reasons,'PURPOSE_USE_BASIS_MISSING_OR_CHANGED');
   END IF;
   IF (action.purpose_basis->>'useUntil')::timestamptz<=statement_timestamp() THEN
     reasons:=array_append(reasons,'PURPOSE_USE_EXPIRED');
   END IF;
   IF binding.expires_at>(action.purpose_basis->>'useUntil')::timestamptz THEN
     reasons:=array_append(reasons,'PURPOSE_USE_BINDING_OUTLIVES_USE');
   END IF;
 END IF;
 RETURN reasons;
END $$;

CREATE FUNCTION ops.lc_binding_gaps_v0107(p_action uuid) RETURNS text[]
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'core', 'pg_temp'
    AS $$
DECLARE
    action  ops.lc_action%ROWTYPE;
    binding ops.lc_action_binding%ROWTYPE;
    reasons text[] := '{}';
    latest_digest text;
BEGIN
    SELECT * INTO action FROM ops.lc_action WHERE id = p_action;
    IF NOT FOUND THEN RETURN ARRAY['ACTION_NOT_FOUND']; END IF;
    SELECT * INTO binding FROM ops.lc_action_binding WHERE action_id = p_action;
    IF NOT FOUND THEN RETURN ARRAY['BINDING_MISSING']; END IF;
    IF NOT EXISTS (SELECT 1 FROM ops.lc_evaluation_plan p
        WHERE p.action_id=action.id AND p.organization_id=action.organization_id
          AND p.plan_digest=binding.evaluation_plan_digest AND p.frozen_at<=binding.bound_at) THEN
        reasons:=array_append(reasons,'EVALUATION_PLAN_BINDING_MISSING_OR_CHANGED');
    END IF;
    IF NOT ops.lc_action_has_meaning_review(action.id,binding.bound_at) THEN
        reasons:=array_append(reasons,'MEANING_REVIEW_UNQUALIFIED');
    END IF;
    IF binding.state <> 'BOUND' THEN
        reasons := array_append(reasons, 'BINDING_INAPPLICABLE');
    END IF;
    IF binding.expires_at <= statement_timestamp() THEN
        reasons := array_append(reasons, 'BINDING_EXPIRED');
    END IF;
    IF core.lc_listing_affected_set_digest(action.platform_listing_id) <> binding.affected_set_digest THEN
        reasons := array_append(reasons, 'AFFECTED_SET_DIGEST_CHANGED');
    END IF;
    IF action.action_kind = 'LISTING_DESCRIPTION_CHANGE' THEN
        SELECT o.text_digest INTO latest_digest
          FROM core.lc_description_observation o
         WHERE o.platform_listing_id = action.platform_listing_id
         ORDER BY o.observed_at DESC, o.acquired_at DESC LIMIT 1;
        IF latest_digest IS DISTINCT FROM binding.current_text_digest THEN
            reasons := array_append(reasons, 'CURRENT_TEXT_MOVED');
        END IF;
    END IF;
    IF (ops.lc_action_calibration_recheck(action.id,statement_timestamp())->>'state')
         NOT IN ('CURRENT','UNCHANGED_DEPENDENCIES') THEN
        reasons := array_append(reasons, 'CALIBRATION_NOT_CURRENT');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM ops.approval_decision a
                    WHERE a.id = binding.approval_decision_id
                      AND a.decision = 'APPROVED'
                      AND a.scope_expires_at > statement_timestamp()) THEN
        reasons := array_append(reasons, 'AUTHORIZATION_INVALID_OR_EXPIRED');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM ops.recommendation r
                    WHERE r.id = action.recommendation_id
                      AND r.state IN ('APPROVED', 'COMMAND_CREATED', 'EXECUTION_TRACKING')
                      AND r.valid_until > statement_timestamp()) THEN
        reasons := array_append(reasons, 'RECOMMENDATION_STALE');
    END IF;
    RETURN reasons;
END;
$$;

CREATE FUNCTION ops.lc_binding_requires_meaning_review() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NOT ops.lc_action_has_meaning_review(NEW.action_id,NEW.bound_at) THEN
  RAISE EXCEPTION 'binding requires exact qualified meaning review' USING ERRCODE='MO107';
 END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION ops.lc_calibration_actor_scope(p_actor uuid, p_org uuid, p_scope text, p_store uuid, p_action text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT CASE WHEN p_scope='STORE' THEN ops.lc_actor_holds_action(p_actor,p_org,p_store,p_action)
 ELSE EXISTS (
  SELECT 1 FROM iam.user_role_assignment r
   JOIN iam.business_role_action_scope m ON m.role_code=r.role_code
   JOIN iam.user_scope_grant s ON s.user_id=r.user_id AND s.organization_id=r.organization_id AND s.action_code=m.action_code
  WHERE r.user_id=p_actor AND r.organization_id=p_org AND r.status='ACTIVE' AND m.action_code=p_action
   AND r.effective_from<=statement_timestamp() AND (r.effective_to IS NULL OR r.effective_to>statement_timestamp())
   AND s.organization_ref_id=p_org AND s.status='ACTIVE' AND s.effective_from<=statement_timestamp()
   AND (s.effective_to IS NULL OR s.effective_to>statement_timestamp())) END
$$;

CREATE FUNCTION ops.lc_calibration_combination_failures(p_id uuid) RETURNS text[]
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE failures text[]; nodes jsonb; node jsonb; comparison jsonb; reference_from timestamptz; reference_to timestamptz; scenarios jsonb; item jsonb; financial_freshness jsonb; scope_bases jsonb; scope_item record; linked jsonb; member jsonb; codes text[]; member_ids text[]; age_key text; organization uuid; identities text[]:='{}'; identity text;
BEGIN
 failures:=ops.lc_calibration_combination_failures_v0107(p_id);
 SELECT organization_id INTO organization FROM core.lc_calibration_package WHERE id=p_id;
 -- Validate supplied current-financial freshness limits in the existing accepted package.
 -- Absence remains unresolved at the consumer; it does not invent a production duration.
 SELECT value_json->'businessProtection' INTO financial_freshness FROM core.lc_calibration_value
  WHERE package_id=p_id AND category_code='FRESHNESS_RULE';
 IF financial_freshness IS NOT NULL THEN
   IF jsonb_typeof(financial_freshness) IS DISTINCT FROM 'object' THEN
     failures:=array_append(failures,'CURRENT_FINANCIAL_FRESHNESS_INVALID');
   ELSE
     FOREACH age_key IN ARRAY ARRAY['maximumVerificationAgeSeconds','maximumPeriodEndAgeSeconds'] LOOP
       IF jsonb_typeof(financial_freshness->age_key) IS DISTINCT FROM 'number' THEN
         failures:=array_append(failures,'CURRENT_FINANCIAL_FRESHNESS_INVALID');
       ELSIF (financial_freshness->>age_key)::numeric<=0
           OR (financial_freshness->>age_key)::numeric>9223372036854775807
           OR trunc((financial_freshness->>age_key)::numeric)<>(financial_freshness->>age_key)::numeric THEN
         failures:=array_append(failures,'CURRENT_FINANCIAL_FRESHNESS_INVALID');
       END IF;
     END LOOP;
   END IF;
 END IF;
 SELECT value_json->'protectionScopeBases' INTO scope_bases FROM core.lc_calibration_value
  WHERE package_id=p_id AND category_code='CRITICAL_GROUP_RULE';
 IF scope_bases IS NOT NULL THEN
   IF jsonb_typeof(scope_bases) IS DISTINCT FROM 'object' THEN
     failures:=array_append(failures,'PROTECTION_SCOPE_BASES_INVALID');
   ELSE
     FOR scope_item IN SELECT key,value FROM jsonb_each(scope_bases) LOOP
       IF NOT EXISTS(SELECT 1 FROM core.platform_listing l WHERE l.id::text=scope_item.key AND l.organization_id=organization)
          OR jsonb_typeof(scope_item.value) IS DISTINCT FROM 'object'
          OR jsonb_typeof(scope_item.value->'evidenceReference') IS DISTINCT FROM 'string'
          OR length(btrim(scope_item.value->>'evidenceReference')) NOT BETWEEN 1 AND 512
          OR jsonb_typeof(scope_item.value->'linkedProfitScopes') IS DISTINCT FROM 'array'
          OR jsonb_typeof(scope_item.value->'criticalReturnVariantIds') IS DISTINCT FROM 'array' THEN
         failures:=array_append(failures,'PROTECTION_SCOPE_BASIS_INVALID'); CONTINUE;
       END IF;
       codes:='{}';
       FOR linked IN SELECT value FROM jsonb_array_elements(scope_item.value->'linkedProfitScopes') LOOP
         IF jsonb_typeof(linked) IS DISTINCT FROM 'object'
            OR jsonb_typeof(linked->'code') IS DISTINCT FROM 'string'
            OR (linked->>'code') !~ '^[A-Z][A-Z0-9_]{0,63}$'
            OR (linked->>'code')=ANY(codes)
            OR jsonb_typeof(linked->'listingVariantIds') IS DISTINCT FROM 'array'
            OR jsonb_typeof(linked->'evidenceReference') IS DISTINCT FROM 'string'
            OR length(btrim(linked->>'evidenceReference')) NOT BETWEEN 1 AND 512 THEN
           failures:=array_append(failures,'LINKED_PROFIT_SCOPE_INVALID'); CONTINUE;
         END IF;
         codes:=array_append(codes,linked->>'code'); member_ids:='{}';
         IF jsonb_array_length(linked->'listingVariantIds')=0 THEN
           failures:=array_append(failures,'LINKED_PROFIT_SCOPE_EMPTY');
         END IF;
         FOR member IN SELECT value FROM jsonb_array_elements(linked->'listingVariantIds') LOOP
           IF jsonb_typeof(member) IS DISTINCT FROM 'string' OR (member#>>'{}')=ANY(member_ids)
              OR NOT EXISTS(SELECT 1 FROM core.platform_listing_variant v JOIN core.platform_listing l ON l.id=v.platform_listing_id
                WHERE v.id::text=member#>>'{}' AND v.organization_id=organization AND l.store_id::text=linked->>'storeId') THEN
             failures:=array_append(failures,'LINKED_PROFIT_MEMBER_INVALID');
           END IF;
           member_ids:=array_append(member_ids,member#>>'{}');
         END LOOP;
       END LOOP;
       member_ids:='{}';
       FOR member IN SELECT value FROM jsonb_array_elements(scope_item.value->'criticalReturnVariantIds') LOOP
         IF jsonb_typeof(member) IS DISTINCT FROM 'string' OR (member#>>'{}')=ANY(member_ids)
            OR NOT EXISTS(SELECT 1 FROM core.platform_listing_variant v WHERE v.id::text=member#>>'{}'
                AND v.organization_id=organization AND v.platform_listing_id::text=scope_item.key) THEN
           failures:=array_append(failures,'CRITICAL_RETURN_MEMBER_INVALID');
         END IF;
         member_ids:=array_append(member_ids,member#>>'{}');
       END LOOP;
     END LOOP;
   END IF;
 END IF;
 SELECT value_json INTO nodes FROM core.lc_calibration_value WHERE package_id=p_id AND category_code='FORMAL_NODES';
 IF jsonb_typeof(nodes)='array' THEN
   FOR node IN SELECT value FROM jsonb_array_elements(nodes) LOOP
     comparison:=node->'protectionComparison';
     IF comparison IS NULL THEN CONTINUE; END IF;
     IF jsonb_typeof(comparison) IS DISTINCT FROM 'object'
        OR comparison->>'method' IS DISTINCT FROM 'CANONICAL_ACCOUNTING_CHANGE_V1'
        OR jsonb_typeof(comparison->'qualificationRef') IS DISTINCT FROM 'string'
        OR length(btrim(comparison->>'qualificationRef')) NOT BETWEEN 1 AND 512
        OR jsonb_typeof(comparison->'referencePeriodStart') IS DISTINCT FROM 'string'
        OR jsonb_typeof(comparison->'referencePeriodEnd') IS DISTINCT FROM 'string'
        OR (comparison->>'referencePeriodStart') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T.*(Z|[+-][0-9]{2}:[0-9]{2})$'
        OR (comparison->>'referencePeriodEnd') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T.*(Z|[+-][0-9]{2}:[0-9]{2})$' THEN
       failures:=array_append(failures,'ACCOUNTING_COMPARISON_METHOD_INVALID'); CONTINUE;
     END IF;
     BEGIN
       reference_from:=(comparison->>'referencePeriodStart')::timestamptz;
       reference_to:=(comparison->>'referencePeriodEnd')::timestamptz;
       IF reference_from>=reference_to OR reference_to>statement_timestamp()
          OR jsonb_typeof(node#>'{schedule,windowStartOffsetDays}') IS DISTINCT FROM 'number'
          OR jsonb_typeof(node#>'{schedule,windowEndOffsetDays}') IS DISTINCT FROM 'number' THEN
         failures:=array_append(failures,'ACCOUNTING_COMPARISON_PERIOD_INVALID');
       ELSIF extract(epoch FROM reference_to-reference_from) IS DISTINCT FROM
          ((node#>>'{schedule,windowEndOffsetDays}')::numeric-(node#>>'{schedule,windowStartOffsetDays}')::numeric)*86400 THEN
         failures:=array_append(failures,'ACCOUNTING_COMPARISON_PERIOD_LENGTH_MISMATCH');
       END IF;
     EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
       failures:=array_append(failures,'ACCOUNTING_COMPARISON_PERIOD_INVALID');
     END;
     IF (SELECT count(*) FROM core.lc_calibration_value v WHERE v.package_id=p_id
         AND v.category_code IN ('NON_WORSENING_PROFIT_BOUND','NON_WORSENING_RETURN_BOUND')
         AND v.unit_code='RATIO' AND v.value_numeric BETWEEN 0 AND 1)<>2 THEN
       failures:=array_append(failures,'ACCOUNTING_COMPARISON_BOUNDS_INVALID');
     END IF;
   END LOOP;
 END IF;
 -- Exact accepted accounting reference; no automatic previous-period selection.
 SELECT value_json->'currentAccountingComparisons' INTO scope_bases FROM core.lc_calibration_value
  WHERE package_id=p_id AND category_code='NON_WORSENING_PROFIT_BOUND';
 IF scope_bases IS NOT NULL THEN
  IF jsonb_typeof(scope_bases) IS DISTINCT FROM 'object' THEN
   failures:=array_append(failures,'CURRENT_ACCOUNTING_REFERENCES_INVALID');
  ELSE
   FOR scope_item IN SELECT key,value FROM jsonb_each(scope_bases) LOOP
    IF NOT EXISTS(SELECT 1 FROM core.platform_listing l WHERE l.organization_id=organization AND l.id::text=scope_item.key)
      OR jsonb_typeof(scope_item.value) IS DISTINCT FROM 'object'
      OR jsonb_typeof(scope_item.value->'evidenceReference') IS DISTINCT FROM 'string'
      OR length(btrim(scope_item.value->>'evidenceReference')) NOT BETWEEN 1 AND 512
      OR jsonb_typeof(scope_item.value->'periodStart') IS DISTINCT FROM 'string'
      OR jsonb_typeof(scope_item.value->'periodEnd') IS DISTINCT FROM 'string' THEN
     failures:=array_append(failures,'CURRENT_ACCOUNTING_REFERENCE_INVALID'); CONTINUE;
    END IF;
    IF (scope_item.value->>'periodStart') !~ 'T.*(Z|[+-][0-9]{2}:[0-9]{2})$'
      OR (scope_item.value->>'periodEnd') !~ 'T.*(Z|[+-][0-9]{2}:[0-9]{2})$' THEN
     failures:=array_append(failures,'CURRENT_ACCOUNTING_REFERENCE_PERIOD_INVALID'); CONTINUE;
    END IF;
    BEGIN
     reference_from:=(scope_item.value->>'periodStart')::timestamptz;
     reference_to:=(scope_item.value->>'periodEnd')::timestamptz;
     IF NOT isfinite(reference_from) OR NOT isfinite(reference_to) OR reference_from>=reference_to THEN
      failures:=array_append(failures,'CURRENT_ACCOUNTING_REFERENCE_PERIOD_INVALID');
     END IF;
    EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
     failures:=array_append(failures,'CURRENT_ACCOUNTING_REFERENCE_PERIOD_INVALID');
    END;
   END LOOP;
   IF (SELECT count(*) FROM core.lc_calibration_value v WHERE v.package_id=p_id
       AND v.category_code IN ('NON_WORSENING_PROFIT_BOUND','NON_WORSENING_RETURN_BOUND')
       AND v.unit_code='RATIO' AND v.value_numeric BETWEEN 0 AND 1)<>2
      OR (SELECT count(DISTINCT window_days) FROM core.lc_calibration_value WHERE package_id=p_id
       AND category_code IN ('NON_WORSENING_PROFIT_BOUND','NON_WORSENING_RETURN_BOUND'))<>1 THEN
    failures:=array_append(failures,'CURRENT_ACCOUNTING_REFERENCE_BOUNDS_INVALID');
   END IF;
  END IF;
 END IF;
 -- Listing-specific accepted downside scenarios; supplied caller flags are not authority.
 SELECT value_json->'economicScenarioBases' INTO scope_bases FROM core.lc_calibration_value
  WHERE package_id=p_id AND category_code='DEMAND_SCENARIO_SET';
 IF scope_bases IS NOT NULL THEN
  IF jsonb_typeof(scope_bases) IS DISTINCT FROM 'object' THEN
   failures:=array_append(failures,'ECONOMIC_SCENARIO_BASES_INVALID');
  ELSE
   FOR scope_item IN SELECT key,value FROM jsonb_each(scope_bases) LOOP
    IF NOT EXISTS(SELECT 1 FROM core.platform_listing l WHERE l.organization_id=organization AND l.id::text=scope_item.key)
      OR jsonb_typeof(scope_item.value) IS DISTINCT FROM 'object'
      OR jsonb_typeof(scope_item.value->'evidenceReference') IS DISTINCT FROM 'string'
      OR length(btrim(scope_item.value->>'evidenceReference')) NOT BETWEEN 1 AND 512
      OR jsonb_typeof(scope_item.value->'minimumContributionProfit') IS DISTINCT FROM 'number'
      OR (scope_item.value->>'minimumContributionProfit')::numeric NOT BETWEEN 0 AND 99999999999999
      OR jsonb_typeof(scope_item.value->'currencyCode') IS DISTINCT FROM 'string'
      OR (scope_item.value->>'currencyCode') !~ '^[A-Z]{3}$'
      OR jsonb_typeof(scope_item.value->'profitEvidenceReference') IS DISTINCT FROM 'string'
      OR length(btrim(scope_item.value->>'profitEvidenceReference')) NOT BETWEEN 1 AND 512
      OR jsonb_typeof(scope_item.value->'necessaryScenarios') IS DISTINCT FROM 'array' THEN
     failures:=array_append(failures,'ECONOMIC_SCENARIO_BASIS_INVALID'); CONTINUE;
    END IF;
    BEGIN
     IF coalesce(scope_item.value->>'periodStart','') !~ '^\d{4}-\d{2}-\d{2}T.*(Z|[+-]\d{2}:\d{2})$'
       OR coalesce(scope_item.value->>'periodEnd','') !~ '^\d{4}-\d{2}-\d{2}T.*(Z|[+-]\d{2}:\d{2})$' THEN
      failures:=array_append(failures,'ECONOMIC_SCENARIO_PERIOD_INVALID'); CONTINUE;
     END IF;
     reference_from:=(scope_item.value->>'periodStart')::timestamptz;
     reference_to:=(scope_item.value->>'periodEnd')::timestamptz;
     -- Activation reruns this package-wide validator. Clock expiry belongs to the exact consumer.
     IF reference_from>=reference_to THEN
      failures:=array_append(failures,'ECONOMIC_SCENARIO_PERIOD_INVALID');
     END IF;
    EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
     failures:=array_append(failures,'ECONOMIC_SCENARIO_PERIOD_INVALID');
    END;
    scenarios:=scope_item.value->'necessaryScenarios'; codes:='{}';
    IF jsonb_array_length(scenarios) NOT BETWEEN 1 AND 64 THEN
     failures:=array_append(failures,'NECESSARY_DEMAND_SCENARIOS_INVALID');
    END IF;
    FOR item IN SELECT value FROM jsonb_array_elements(scenarios) LOOP
     IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR jsonb_typeof(item->'code') IS DISTINCT FROM 'string'
       OR length(btrim(item->>'code')) NOT BETWEEN 1 AND 64 OR (item->>'code')=ANY(codes)
       OR item->'conservative' IS DISTINCT FROM 'true'::jsonb
       OR jsonb_typeof(item->'evidenceReference') IS DISTINCT FROM 'string'
       OR length(btrim(item->>'evidenceReference')) NOT BETWEEN 1 AND 512
       OR jsonb_typeof(item->'quantity') IS DISTINCT FROM 'number' THEN
      failures:=array_append(failures,'NECESSARY_DEMAND_SCENARIO_INVALID'); CONTINUE;
     END IF;
     codes:=array_append(codes,item->>'code');
     IF (item->>'quantity')::numeric NOT BETWEEN 0 AND 99999999999999
       OR trunc((item->>'quantity')::numeric)<>(item->>'quantity')::numeric THEN
      failures:=array_append(failures,'NECESSARY_DEMAND_QUANTITY_INVALID');
     END IF;
    END LOOP;
   END LOOP;
  END IF;
 END IF;
 SELECT value_json->'supplyScenarios' INTO scenarios FROM core.lc_calibration_value
  WHERE package_id=p_id AND category_code='DEMAND_SCENARIO_SET';
 IF scenarios IS NULL THEN RETURN failures; END IF;
 IF jsonb_typeof(scenarios)<>'array' THEN RETURN array_append(failures,'SUPPLY_SCENARIOS_INVALID'); END IF;
 IF jsonb_array_length(scenarios)=0 THEN RETURN array_append(failures,'SUPPLY_SCENARIOS_EMPTY'); END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(scenarios) LOOP
  IF jsonb_typeof(item)<>'object' OR jsonb_typeof(item->'code') IS DISTINCT FROM 'string'
     OR length(btrim(item->>'code')) NOT BETWEEN 1 AND 512
     OR jsonb_typeof(item->'productVariantId') IS DISTINCT FROM 'string'
     OR NOT EXISTS(SELECT 1 FROM core.product_variant v WHERE v.organization_id=organization AND v.id::text=item->>'productVariantId')
     OR jsonb_typeof(item->'evidenceReference') IS DISTINCT FROM 'string'
     OR length(btrim(item->>'evidenceReference')) NOT BETWEEN 1 AND 512
     OR jsonb_typeof(item->'companyDailyFulfillmentUnits') IS DISTINCT FROM 'number'
     OR jsonb_typeof(item->'coverageDays') IS DISTINCT FROM 'number' THEN
   failures:=array_append(failures,'SUPPLY_SCENARIO_INVALID');CONTINUE;
  END IF;
  IF (item->>'companyDailyFulfillmentUnits')::numeric<0
     OR (item->>'coverageDays')::numeric<=0 OR (item->>'coverageDays')::numeric>2147483647
     OR trunc((item->>'coverageDays')::numeric)<>(item->>'coverageDays')::numeric THEN
   failures:=array_append(failures,'SUPPLY_SCENARIO_UNITS_OR_HORIZON_INVALID');
  END IF;
  identity:=jsonb_build_array(item->>'productVariantId',item->>'code')::text;
  IF identity=ANY(identities) THEN failures:=array_append(failures,'SUPPLY_SCENARIO_DUPLICATE'); END IF;
  identities:=array_append(identities,identity);
 END LOOP;
 RETURN ARRAY(SELECT DISTINCT reason FROM unnest(failures) reason ORDER BY reason);
END $_$;

CREATE FUNCTION ops.lc_calibration_combination_failures_v0107(p_id uuid) RETURNS text[]
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE failures text[]:=core.lc_calibration_package_failures(p_id); v record;
 ordinary numeric; material numeric; node jsonb; codes text[]:='{}';
BEGIN
 FOR v IN SELECT * FROM core.lc_calibration_value WHERE package_id=p_id LOOP
  IF v.category_code IN ('MATERIAL_IMPROVEMENT_BOUND','NON_WORSENING_RETURN_BOUND',
       'ORDINARY_TRIGGER_EXPOSURE','MATERIAL_TRIGGER_EXPOSURE')
     AND (v.unit_code<>'RATIO' OR v.value_numeric<0 OR v.value_numeric>1) THEN
   failures:=array_append(failures,v.category_code||'_RATIO_INVALID');
  END IF;
  IF v.category_code='NON_WORSENING_PROFIT_BOUND' AND v.value_numeric<0 THEN
   failures:=array_append(failures,'NON_WORSENING_PROFIT_BOUND_INVALID');
  END IF;
  IF v.category_code='APPROVAL_VALIDITY' AND (v.value_numeric<=0 OR v.value_numeric<>trunc(v.value_numeric)
       OR v.unit_code NOT IN ('MINUTES','HOURS','DAYS')) THEN
   failures:=array_append(failures,'APPROVAL_VALIDITY_INVALID');
  END IF;
  IF v.category_code='CROSS_PERIOD_WINDOW' AND (v.value_numeric<0 OR v.value_numeric>3660
       OR v.value_numeric<>trunc(v.value_numeric) OR v.unit_code<>'DAYS') THEN
   failures:=array_append(failures,'CROSS_PERIOD_WINDOW_INVALID');
  END IF;
  IF v.category_code='STOP_RULE' AND jsonb_typeof(v.value_json)<>'object' THEN
   failures:=array_append(failures,'STOP_RULE_INVALID');
  END IF;
  IF v.category_code='FORMAL_NODES' THEN
   IF jsonb_typeof(v.value_json)<>'array' THEN
    failures:=array_append(failures,'FORMAL_NODES_INVALID');
   ELSE
    IF jsonb_array_length(v.value_json) NOT BETWEEN 1 AND 8 THEN failures:=array_append(failures,'FORMAL_NODE_COUNT_INVALID'); END IF;
    FOR node IN SELECT value FROM jsonb_array_elements(v.value_json) LOOP
     IF coalesce(node->>'nodeCode','') !~ '^[A-Z][A-Z0-9_]{1,62}$' OR (node->>'nodeCode')=ANY(codes)
       OR coalesce(node->>'maturityDays','') NOT IN ('7','14','30')
       OR length(btrim(coalesce(node->>'method','')))=0
       OR coalesce(node->>'threshold','') !~ '^[0-9]+([.][0-9]+)?$' THEN
      failures:=array_append(failures,'FORMAL_NODE_INVALID');
     END IF;
     codes:=array_append(codes,node->>'nodeCode');
    END LOOP;
   END IF;
  END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM core.lc_calibration_value WHERE package_id=p_id
    AND category_code IN ('ORDINARY_TRIGGER_CONTENT','MATERIAL_TRIGGER_CONTENT')
    AND (unit_code<>'CONDITIONS' OR NOT core.lc_meaning_rule_document_valid(value_json))) THEN
  failures:=array_append(failures,'MEANING_RULE_DOCUMENT_INVALID');
 END IF;
 IF core.lc_meaning_catalog(p_id,CASE (SELECT purpose_code FROM core.lc_calibration_package WHERE id=p_id)
      WHEN 'PROMOTION' THEN 'LISTING_PROMOTION_ACTION' ELSE 'LISTING_DESCRIPTION_CHANGE' END) IS NULL THEN
  failures:=array_append(failures,'MEANING_RULE_COMBINATION_UNRESOLVED');
 END IF;
 SELECT value_numeric INTO ordinary FROM core.lc_calibration_value WHERE package_id=p_id AND category_code='ORDINARY_TRIGGER_EXPOSURE';
 SELECT value_numeric INTO material FROM core.lc_calibration_value WHERE package_id=p_id AND category_code='MATERIAL_TRIGGER_EXPOSURE';
 IF ordinary>material THEN failures:=array_append(failures,'EXPOSURE_TRIGGER_ORDER_INVALID'); END IF;
 RETURN failures;
END $_$;

CREATE FUNCTION ops.lc_calibration_digest(p_package uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    SET "DateStyle" TO 'ISO, YMD'
    AS $$
 SELECT encode(sha256(convert_to(jsonb_build_object(
  'id',p.id,'organizationId',p.organization_id,'code',p.package_code,'version',p.package_version,
  'scopeKind',p.scope_kind,'platformCode',p.platform_code,'storeId',p.store_ref_id,
  'effectiveFrom',p.effective_from,'effectiveTo',p.effective_to,'evidence',p.evidence_reference,
  'replacesPackageId',g.replaces_package_id,'purpose',p.purpose_code,'rationale',g.rationale,'impact',g.impact,'differences',g.differences,
  'values',(SELECT jsonb_agg(to_jsonb(v)-'id'-'package_id' ORDER BY v.category_code)
            FROM core.lc_calibration_value v WHERE v.package_id=p.id))::text,'UTF8')),'hex')
 FROM core.lc_calibration_package p LEFT JOIN ops.lc_calibration_governance g ON g.package_id=p.id WHERE p.id=p_package
$$;

CREATE FUNCTION ops.lc_capture_attempt_response_identity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE command ops.lc_description_command%ROWTYPE; task jsonb;
BEGIN
    SELECT * INTO command FROM ops.lc_description_command WHERE id=NEW.command_id;
    IF NEW.purpose = 'STATUS_ENQUIRY' THEN
        SELECT CASE WHEN a.outcome_class='ACCEPTED' AND a.native_task_key IS NOT NULL
                THEN jsonb_build_object('attemptId',a.id,'nativeTaskKey',a.native_task_key) END
          INTO task FROM ops.lc_description_command_attempt a
         WHERE a.command_id=NEW.command_id AND a.purpose IN ('APPLY','RESTORE')
           AND a.started_at <= NEW.started_at
         ORDER BY a.attempt_no DESC LIMIT 1;
    END IF;
    NEW.operation_snapshot := NEW.operation_snapshot || jsonb_build_object('responseIdentity',
        jsonb_build_object('commandId',command.id,'listingId',command.platform_listing_id,
            'nativeListingKey',command.native_listing_key,'task',task));
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.lc_capture_command_native_identity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'core', 'pg_temp'
    AS $$
DECLARE identity jsonb;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        IF NEW.native_listing_key IS DISTINCT FROM OLD.native_listing_key THEN
            RAISE EXCEPTION 'command native identity is immutable' USING ERRCODE = 'MO093';
        END IF;
        RETURN NEW;
    END IF;
    SELECT s.identity_lineage INTO identity FROM ops.lc_action a
      JOIN core.lc_affected_set s ON s.id=a.affected_set_id AND s.organization_id=a.organization_id
     WHERE a.id=NEW.action_id AND a.organization_id=NEW.organization_id
       AND s.affected_set_digest=NEW.affected_set_digest;
    IF identity->>'nativeListingKey' IS NULL
        OR identity->>'listingId' IS DISTINCT FROM NEW.platform_listing_id::text THEN
        RAISE EXCEPTION 'command requires the approved frozen native identity' USING ERRCODE = 'MO093';
    END IF;
    NEW.native_listing_key := identity->>'nativeListingKey';
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.lc_capture_description_retry_timing() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE platform_code text;
BEGIN
    SELECT c.platform_code INTO platform_code FROM ops.lc_description_command c WHERE c.id=NEW.command_id;
    NEW.retry_timing := ops.lc_description_retry_timing(platform_code,NEW.response_headers,NEW.observed_at);
    UPDATE ops.lc_description_command
       SET provider_retry_timing_unknown = provider_retry_timing_unknown OR NEW.retry_timing->>'state'='UNKNOWN',
           provider_not_before = CASE WHEN NEW.retry_timing->>'state'='KNOWN'
               THEN greatest(provider_not_before,
                   NEW.observed_at + make_interval(secs => (NEW.retry_timing->>'seconds')::integer))
               ELSE provider_not_before END
     WHERE id=NEW.command_id;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.lc_classify_manual_report_operation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE packet ops.lc_manual_packet%ROWTYPE;
BEGIN
 SELECT * INTO STRICT packet FROM ops.lc_manual_packet WHERE id=NEW.packet_id;
 IF NEW.reported_at<NEW.operation_time OR NEW.organization_id<>packet.organization_id
    OR NEW.reporter_user_id<>packet.executor_user_id THEN
   RAISE EXCEPTION 'manual report chronology and executor must match the exact packet' USING ERRCODE='MO092';
 END IF;
 IF NEW.operation_time<packet.issued_at THEN
   NEW.operation_qualification:='UNAUTHORISED_DEVIATION'; NEW.deviation_reason:='OPERATION_BEFORE_PACKET_AUTHORITY';
 ELSIF NEW.operation_time>packet.expires_at THEN
   NEW.operation_qualification:='UNAUTHORISED_DEVIATION'; NEW.deviation_reason:='OPERATION_AFTER_PACKET_AUTHORITY';
 ELSIF NEW.reported_at>packet.expires_at THEN
   NEW.operation_qualification:='LAWFUL_LATE_REPORT'; NEW.deviation_reason:=NULL;
 ELSE
   NEW.operation_qualification:='WITHIN_PACKET_AUTHORITY'; NEW.deviation_reason:=NULL;
 END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION ops.lc_classify_manual_verification() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE packet ops.lc_manual_packet%ROWTYPE; action ops.lc_action%ROWTYPE;
BEGIN
 SELECT * INTO STRICT packet FROM ops.lc_manual_packet WHERE id=NEW.packet_id;
 SELECT * INTO STRICT action FROM ops.lc_action WHERE id=packet.action_id;
 NEW.qualification_state:='UNQUALIFIED';
 IF EXISTS(SELECT 1 FROM ops.lc_manual_report r WHERE r.packet_id=packet.id
      AND r.operation_qualification='UNAUTHORISED_DEVIATION') THEN
   NEW.qualification_state:='DEVIATION_RETAINED'; RETURN NEW;
 END IF;
 IF ops.lc_scope_contained(action.organization_id,action.platform_listing_id) THEN
   NEW.qualification_state:='CURRENTLY_CONTAINED'; RETURN NEW;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM ops.lc_manual_report r WHERE r.packet_id=packet.id
      AND r.report_state='APPLIED'
      AND r.operation_qualification IN ('WITHIN_PACKET_AUTHORITY','LAWFUL_LATE_REPORT')
      AND r.operation_time=coalesce((NEW.observation_binding->>'operationAt')::timestamptz,
                                    (NEW.observation_binding->>'afterOperation')::timestamptz)) THEN RETURN NEW; END IF;
 IF NEW.management_match='MATCHED_TARGET'
    AND NEW.observation_binding->>'actionId'=action.id::text
    AND ((action.action_kind='LISTING_PROMOTION_ACTION'
          AND NEW.observation_binding->>'purpose'='PARTICIPATION'
          AND NEW.observation_binding->>'participationState'='PARTICIPATING'
          AND NEW.observation_binding->>'promotionTermsDigest'=action.promotion_terms_digest)
      OR (action.action_kind='LISTING_DESCRIPTION_CHANGE'
          AND NEW.management_observation_id IS NOT NULL
          AND NEW.display_observation_id IS NOT NULL AND NEW.display_state='DISPLAYED'
          AND NEW.observation_binding->>'targetTextDigest'=action.target_text_digest)) THEN
   NEW.qualification_state:='QUALIFIED';
 END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION ops.lc_current_containment_authority(p_actor uuid, p_org uuid, p_store uuid, p_action text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT CASE WHEN p_store IS NOT NULL THEN ops.lc_actor_holds_action(p_actor,p_org,p_store,p_action)
 ELSE EXISTS(SELECT 1 FROM iam.user_account actor JOIN iam.identity_provider provider ON provider.id=actor.identity_provider_id
   JOIN iam.user_role_assignment r ON r.user_id=actor.id JOIN iam.business_role_action_scope m ON m.role_code=r.role_code
   JOIN iam.user_scope_grant g ON g.user_id=actor.id AND g.action_code=m.action_code
   WHERE actor.id=p_actor AND actor.organization_id=p_org AND actor.status='ACTIVE' AND provider.status='ACTIVE'
     AND r.organization_id=p_org AND r.status='ACTIVE' AND r.effective_from<=statement_timestamp()
     AND (r.effective_to IS NULL OR r.effective_to>statement_timestamp())
     AND m.action_code=p_action AND g.organization_id=p_org AND g.organization_ref_id=p_org AND g.status='ACTIVE'
     AND g.effective_from<=statement_timestamp() AND (g.effective_to IS NULL OR g.effective_to>statement_timestamp())) END
$$;

CREATE FUNCTION ops.lc_current_isolation_scope(p_org uuid, p_source uuid) RETURNS TABLE(platform_listing_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 WITH RECURSIVE walk(platform_listing_id,dependency_kind,proof_reference) AS (
   SELECT d.from_listing_id,d.dependency_kind,d.proof_reference
     FROM ops.lc_isolation_dependency d
    WHERE d.organization_id=p_org AND d.from_listing_id=p_source
      AND ops.lc_listing_uses_isolation_dependency(p_org,d.from_listing_id,d.dependency_kind,
            d.proof_reference,statement_timestamp())
   UNION
   SELECT d.to_listing_id,walk.dependency_kind,walk.proof_reference
     FROM walk JOIN ops.lc_isolation_dependency d ON d.organization_id=p_org
       AND d.from_listing_id=walk.platform_listing_id
       AND d.dependency_kind=walk.dependency_kind AND d.proof_reference=walk.proof_reference
    WHERE ops.lc_listing_uses_isolation_dependency(p_org,d.to_listing_id,d.dependency_kind,
            d.proof_reference,statement_timestamp())
 )
 SELECT p_source WHERE EXISTS(SELECT 1 FROM core.platform_listing l WHERE l.id=p_source AND l.organization_id=p_org)
 UNION SELECT platform_listing_id FROM walk
$$;

CREATE FUNCTION ops.lc_current_promotion_context(p_org uuid, p_listing uuid, p_period_start timestamp with time zone, p_period_end timestamp with time zone, p_as_of timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    SET "DateStyle" TO 'ISO, YMD'
    AS $$
DECLARE latest core.lc_promotion_observation%ROWTYPE; known jsonb; records jsonb:='[]';
 gaps text[]:='{}'; coverage text; material jsonb; local_conflict boolean:=false;
BEGIN
 known:=ops.lc_known_promotion_context(p_org,p_listing);
 IF p_period_start IS NULL OR p_period_end IS NULL OR p_as_of IS NULL
    OR p_period_start>=p_period_end OR p_as_of>statement_timestamp()
    OR NOT EXISTS(SELECT 1 FROM core.platform_listing l WHERE l.id=p_listing AND l.organization_id=p_org) THEN
   material:=jsonb_build_object('coverage','UNQUALIFIED','listingId',p_listing,
     'periodStart',p_period_start,'periodEnd',p_period_end,'records',coalesce(known->'records','[]'::jsonb),
     'gaps',jsonb_build_array('INVALID_CONTEXT_QUERY'));
   RETURN material||jsonb_build_object('digest',encode(sha256(convert_to(material::text,'UTF8')),'hex'));
 END IF;
 SELECT * INTO latest FROM core.lc_promotion_observation o
  WHERE o.organization_id=p_org AND o.platform_listing_id=p_listing
    AND o.observed_at<=p_as_of AND o.acquired_at<=p_as_of
  ORDER BY o.observed_at DESC,o.acquired_at DESC,o.id DESC LIMIT 1;
 IF latest.id IS NULL OR latest.context_coverage<>'COMPLETE_ENUMERATION' THEN
   material:=jsonb_build_object('coverage','KNOWN_RECORDS_ONLY','listingId',p_listing,
     'periodStart',p_period_start,'periodEnd',p_period_end,'records',coalesce(known->'records','[]'::jsonb),
     'gaps',jsonb_build_array('COMPLETE_ENUMERATION_MISSING'),'knownRecordsDigest',known->>'digest');
   RETURN material||jsonb_build_object('digest',encode(sha256(convert_to(material::text,'UTF8')),'hex'));
 END IF;
 IF latest.coverage_from>p_period_start OR latest.coverage_until<p_period_end THEN
   gaps:=array_append(gaps,'ENUMERATION_PERIOD_UNCOVERED');
 END IF;
 IF NOT ops.lc_promotion_observation_is_independent_current(latest.id,p_as_of) THEN
   gaps:=array_append(gaps,'ENUMERATION_NOT_CURRENT_OR_INDEPENDENT');
 END IF;
 SELECT EXISTS(
   SELECT 1 FROM ops.lc_promotion_engagement e
   WHERE e.organization_id=p_org AND e.platform_listing_id=p_listing AND e.state<>'CLEARED'
     AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(latest.context_snapshot) item
       WHERE item#>>'{declaration,engagementKind}'=e.engagement_kind
         AND item#>>'{declaration,nativePromotionKey}'=e.native_promotion_key
         AND ops.lc_promotion_terms_digest(item->'declaration')=ops.lc_promotion_terms_digest(jsonb_build_object(
           'engagementKind',e.engagement_kind,'nativePromotionKey',e.native_promotion_key,'terms',e.terms,
           'priceFreeze',e.price_freeze,'autoParticipation',e.auto_participation,
           'termsEvidenceReference',e.terms_evidence_reference,'obligations',e.obligations))
         AND CASE e.state WHEN 'ACTIVE' THEN item->>'participationState'='PARTICIPATING'
              WHEN 'EXITING' THEN item->>'participationState'='PARTICIPATING'
              WHEN 'STOPPED' THEN item->>'newTransactionsState'='STOPPED'
              ELSE false END)) INTO local_conflict;
 IF local_conflict THEN gaps:=array_append(gaps,'KNOWN_RECORD_CONFLICT_OR_OMISSION'); END IF;
 SELECT coalesce(jsonb_agg(item||jsonb_build_object(
     'promotionTermsDigest',ops.lc_promotion_terms_digest(item->'declaration'),
     'commonApplicableFrom',CASE WHEN (item->>'effectiveTo')::timestamptz>p_period_start
       AND (item->>'effectiveFrom')::timestamptz<p_period_end
       THEN greatest((item->>'effectiveFrom')::timestamptz,p_period_start) END,
     'commonApplicableUntil',CASE WHEN (item->>'effectiveTo')::timestamptz>p_period_start
       AND (item->>'effectiveFrom')::timestamptz<p_period_end
       THEN least((item->>'effectiveTo')::timestamptz,p_period_end) END,
     'localEngagementId',local.id,'localEngagementState',local.state,
     'localEngagementCreatedAt',local.created_at,'localExitAuthorizedAt',local.exit_authorized_at,
     'localNewTransactionsStoppedAt',local.new_transactions_stopped_at,
     'localObligationsClearedAt',local.obligations_cleared_at)
     ORDER BY item#>>'{declaration,engagementKind}',item#>>'{declaration,nativePromotionKey}'),'[]'::jsonb)
   INTO records
 FROM jsonb_array_elements(latest.context_snapshot) item
 LEFT JOIN LATERAL (SELECT e.id,e.state,e.created_at,e.exit_authorized_at,
      e.new_transactions_stopped_at,e.obligations_cleared_at FROM ops.lc_promotion_engagement e
   WHERE e.organization_id=p_org AND e.platform_listing_id=p_listing
     AND e.engagement_kind=item#>>'{declaration,engagementKind}'
     AND e.native_promotion_key=item#>>'{declaration,nativePromotionKey}'
   ORDER BY e.created_at DESC,e.id DESC LIMIT 1) local ON true;
 coverage:=CASE WHEN cardinality(gaps)=0 THEN 'QUALIFIED_COMPLETE' ELSE 'UNQUALIFIED' END;
 material:=jsonb_build_object('coverage',coverage,'organizationId',p_org,'listingId',p_listing,
   'periodStart',p_period_start,'periodEnd',p_period_end,'observationId',latest.id,
   'observedAt',latest.observed_at,'acquiredAt',latest.acquired_at,
   'coverageFrom',latest.coverage_from,'coverageUntil',latest.coverage_until,
   'verificationExpiresAt',latest.verification_expires_at,'contextDigest',latest.context_digest,
   'records',records,'gaps',to_jsonb(gaps),'knownRecordsDigest',known->>'digest');
 RETURN material||jsonb_build_object('digest',encode(sha256(convert_to(material::text,'UTF8')),'hex'));
END $$;

CREATE FUNCTION ops.lc_description_compensation_is_observed() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
BEGIN
    IF NEW.state <> 'COMPENSATED' OR OLD.state = 'COMPENSATED' THEN RETURN NEW; END IF;
    IF NOT EXISTS (
        SELECT 1 FROM ops.lc_description_command_readback rb
          JOIN ops.lc_description_command_attempt at ON at.id = rb.attempt_id
         WHERE rb.command_id = NEW.id AND rb.match_state = 'MATCHES_PRIOR' AND at.fence_token = NEW.fence_token
           AND EXISTS (SELECT 1 FROM ops.lc_description_command_attempt restore
                        WHERE restore.command_id = NEW.id AND restore.purpose = 'RESTORE'
                          AND restore.outcome_class = 'ACCEPTED' AND restore.raw_observation_id IS NOT NULL
                          AND restore.started_at <= at.started_at)) THEN
        RAISE EXCEPTION 'COMPENSATED needs an accepted restore followed by a prior-matching readback'
            USING ERRCODE = 'MO093';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.lc_description_digest_under_rule(p_text text, p_rule text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
    SELECT CASE
        WHEN p_text IS NULL THEN NULL
        WHEN p_rule = 'WHITESPACE_NORMALIZED' THEN
            encode(sha256(convert_to(btrim(regexp_replace(p_text, '\s+', ' ', 'g')), 'UTF8')), 'hex')
        ELSE encode(sha256(convert_to(p_text, 'UTF8')), 'hex')
    END
$$;

CREATE FUNCTION ops.lc_description_execution_evidence(p_command uuid, p_readback uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'raw', 'pg_temp'
    AS $$
DECLARE c ops.lc_description_command%ROWTYPE; rb ops.lc_description_command_readback%ROWTYPE;
    read_attempt ops.lc_description_command_attempt%ROWTYPE; mutation ops.lc_description_command_attempt%ROWTYPE;
    final_status ops.lc_description_command_attempt%ROWTYPE; ro raw.lc_description_response_observation%ROWTYPE;
    mo raw.lc_description_response_observation%ROWTYPE; gaps text[]:='{}'; model text; expected_purpose text;
BEGIN
    SELECT * INTO c FROM ops.lc_description_command WHERE id=p_command;
    SELECT CASE WHEN restores_command_id IS NULL THEN 'APPLY' ELSE 'RESTORE' END INTO expected_purpose
      FROM ops.lc_action WHERE id=c.action_id;
    SELECT * INTO rb FROM ops.lc_description_command_readback WHERE id=p_readback AND command_id=c.id;
    SELECT * INTO read_attempt FROM ops.lc_description_command_attempt WHERE id=rb.attempt_id AND command_id=c.id;
    SELECT * INTO ro FROM raw.lc_description_response_observation WHERE id=rb.raw_observation_id AND attempt_id=read_attempt.id;
    IF c.id IS NULL OR rb.id IS NULL OR read_attempt.purpose IS DISTINCT FROM 'READBACK'
        OR rb.match_state IS DISTINCT FROM 'MATCHES_TARGET' OR read_attempt.outcome_class IS DISTINCT FROM 'ACCEPTED'
        OR ro.response_complete IS NOT TRUE OR ro.identity_binding->>'qualified' IS DISTINCT FROM 'true'
        OR ro.identity_binding->>'extent' IS DISTINCT FROM 'EXACT_NATIVE_OBJECT'
        OR ro.identity_binding->>'nativeListingKey' IS DISTINCT FROM c.native_listing_key
        OR read_attempt.raw_observation_id IS DISTINCT FROM ro.id
        OR rb.observed_text_digest IS DISTINCT FROM ops.lc_description_digest_under_rule(c.target_text,c.equivalence_rule) THEN
        gaps:=array_append(gaps,'EXACT_MANAGEMENT_READBACK_UNPROVEN');
    END IF;
    SELECT * INTO mutation FROM ops.lc_description_command_attempt WHERE command_id=c.id AND purpose IN ('APPLY','RESTORE')
        ORDER BY attempt_no DESC LIMIT 1;
    SELECT * INTO mo FROM raw.lc_description_response_observation WHERE id=mutation.raw_observation_id AND attempt_id=mutation.id;
    model:=mutation.operation_snapshot->>'writeResultModel';
    IF NOT platform.lc_description_request_guard_valid(
            mutation.operation_snapshot #> '{operation,description_request_guard}',
            mutation.operation_snapshot #>> '{operation,description_attribute_key}')
        OR mutation.operation_snapshot #>> '{operation,description_request_guard,evidenceRef}' IS DISTINCT FROM
            mutation.operation_snapshot #>> '{operation,evidence_ref}'
        OR mutation.operation_snapshot #>> '{responseIdentity,commandId}' IS DISTINCT FROM c.id::text
        OR mutation.operation_snapshot #>> '{responseIdentity,nativeListingKey}' IS DISTINCT FROM c.native_listing_key THEN
        gaps:=array_append(gaps,'EXACT_MUTATION_REQUEST_UNQUALIFIED');
    END IF;
    IF mutation.id IS NULL OR mutation.purpose IS DISTINCT FROM expected_purpose OR mutation.outcome_class IS DISTINCT FROM 'ACCEPTED'
        OR mutation.completed_at IS NULL OR mutation.completed_at>read_attempt.started_at
        OR mo.response_complete IS NOT TRUE OR mo.identity_binding->>'qualified' IS DISTINCT FROM 'true' THEN
        gaps:=array_append(gaps,'LATEST_APPLY_COMPLETION_UNPROVEN');
    ELSIF model='ASYNCHRONOUS_TASK' THEN
        SELECT a.* INTO final_status FROM ops.lc_description_command_attempt a
          JOIN raw.lc_description_response_observation r ON r.id=a.raw_observation_id AND r.attempt_id=a.id
         WHERE a.command_id=c.id AND a.purpose='STATUS_ENQUIRY' AND a.outcome_class='ACCEPTED'
           AND a.attempt_no>mutation.attempt_no AND a.completed_at<=read_attempt.started_at
           AND r.response_complete AND r.identity_binding->>'qualified'='true'
           AND r.identity_binding->>'extent'='EXACT_NATIVE_OBJECT'
           AND r.identity_binding->>'nativeListingKey'=c.native_listing_key
           AND r.identity_binding #>> '{task,attemptId}'=mutation.id::text
           AND r.identity_binding #>> '{task,nativeTaskKey}'=mutation.native_task_key
         ORDER BY a.attempt_no DESC LIMIT 1;
        IF final_status.id IS NULL OR mutation.native_task_key IS NULL THEN
            gaps:=array_append(gaps,'ACCEPTED_TASK_COMPLETION_UNPROVEN');
        END IF;
        IF EXISTS (SELECT 1 FROM ops.lc_description_command_attempt a
            JOIN raw.lc_description_response_observation r ON r.id=a.raw_observation_id AND r.attempt_id=a.id
            WHERE a.command_id=c.id AND a.purpose='STATUS_ENQUIRY' AND a.completed_at<=read_attempt.started_at
              AND (a.outcome_class='REJECTED' OR a.error_code='provider_explicit_not_applied')
              AND r.identity_binding->>'qualified'='true'
              AND r.identity_binding #>> '{task,attemptId}'=mutation.id::text
              AND r.identity_binding #>> '{task,nativeTaskKey}'=mutation.native_task_key) THEN
            gaps:=array_append(gaps,'CONTRADICTORY_NATIVE_TASK_RESULT');
        END IF;
    ELSIF model IS DISTINCT FROM 'SYNCHRONOUS' OR mo.identity_binding->>'extent' IS DISTINCT FROM 'EXACT_NATIVE_OBJECT'
        OR mo.identity_binding->>'nativeListingKey' IS DISTINCT FROM c.native_listing_key THEN
        gaps:=array_append(gaps,'SYNCHRONOUS_NATIVE_COMPLETION_UNPROVEN');
    END IF;
    RETURN jsonb_build_object('schema','DESCRIPTION_EXECUTION_V1','commandId',c.id,'actionId',c.action_id,
        'listingId',c.platform_listing_id,'nativeListingKey',c.native_listing_key,'targetTextDigest',c.target_text_digest,
        'affectedSetDigest',c.affected_set_digest,'approvalDecisionId',c.approval_decision_id,
        'readbackId',rb.id,'readbackAttemptId',read_attempt.id,'readbackRawId',ro.id,
        'mutationAttemptId',mutation.id,'mutationRawId',mo.id,'nativeStatusAttemptId',final_status.id,
        'nativeTaskKey',mutation.native_task_key,'mutationPurpose',expected_purpose,'managementObservedAt',ro.observed_at,
        'customerDisplay','UNKNOWN','businessEffect','NOT_EVALUATED','gaps',to_jsonb(gaps),
        'executionState',CASE WHEN cardinality(gaps)=0 THEN 'MANAGEMENT_VERIFIED' ELSE 'NATIVE_COMPLETION_UNPROVEN' END);
END;
$$;

CREATE FUNCTION ops.lc_description_query_is_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
    IF OLD.query_identity IS NOT NULL AND (NEW.query_identity IS DISTINCT FROM OLD.query_identity
        OR NEW.query_body IS DISTINCT FROM OLD.query_body OR NEW.query_recorded_at IS DISTINCT FROM OLD.query_recorded_at) THEN
        RAISE EXCEPTION 'retained task query is immutable' USING ERRCODE='MO093';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.lc_description_render_task_query(p_template text, p_values jsonb) RETURNS bytea
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE parts text[]; token text[]; position integer:=1; rendered text; value text; quoted text;
BEGIN
    IF p_template IS NULL THEN RETURN NULL; END IF;
    parts:=regexp_split_to_array(p_template,'\{[a-zA-Z][a-zA-Z0-9]{0,31}\}');
    rendered:=parts[1];
    FOR token IN SELECT regexp_matches(p_template,'\{([a-zA-Z][a-zA-Z0-9]{0,31})\}','g') LOOP
        IF token[1] NOT IN ('nativeTaskKey','nativeListingKey','idempotencyKey') THEN RETURN NULL; END IF;
        value:=p_values->>token[1];
        IF value IS NULL THEN RETURN NULL; END IF;
        quoted:=to_json(value)::text;
        position:=position+1;
        rendered:=rendered||substring(quoted,2,length(quoted)-2)||parts[position];
    END LOOP;
    RETURN convert_to(rendered,'UTF8');
END;
$$;

CREATE FUNCTION ops.lc_description_retry_is_proven(p_command_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'platform', 'raw', 'pg_temp'
    AS $$
    SELECT EXISTS (
        SELECT 1 FROM ops.lc_description_command c JOIN ops.lc_action action ON action.id=c.action_id
          JOIN LATERAL (SELECT a.* FROM ops.lc_description_command_attempt a
              WHERE a.command_id=c.id AND a.purpose IN ('APPLY','RESTORE') ORDER BY a.attempt_no DESC LIMIT 1) mutation ON true
          JOIN LATERAL (SELECT a.* FROM ops.lc_description_command_attempt a
              WHERE a.command_id=c.id AND a.purpose='READBACK' ORDER BY a.attempt_no DESC LIMIT 1) read_attempt ON true
          JOIN ops.lc_description_command_readback rb ON rb.attempt_id=read_attempt.id AND rb.command_id=c.id
          JOIN raw.lc_description_response_observation ro ON ro.id=rb.raw_observation_id AND ro.id=read_attempt.raw_observation_id
         WHERE c.id=p_command_id AND cardinality(ops.evaluate_lc_description_write_gate(c.id))=0
           AND mutation.purpose=CASE WHEN action.restores_command_id IS NULL THEN 'APPLY' ELSE 'RESTORE' END
           AND read_attempt.attempt_no>mutation.attempt_no AND read_attempt.fence_token=c.fence_token
           AND read_attempt.outcome_class='ACCEPTED' AND rb.match_state='MATCHES_PRIOR'
           AND ro.response_complete AND ro.identity_binding->>'qualified'='true'
           AND ro.identity_binding->>'extent'='EXACT_NATIVE_OBJECT'
           AND ro.identity_binding->>'nativeListingKey'=c.native_listing_key
           AND (EXISTS (SELECT 1 FROM ops.lc_description_command_attempt proof
                 JOIN raw.lc_description_response_observation evidence ON evidence.id=proof.raw_observation_id AND evidence.attempt_id=proof.id
                WHERE proof.command_id=c.id AND proof.error_code='provider_explicit_not_applied'
                  AND proof.outcome_class='RETRIABLE_ERROR' AND proof.attempt_no<read_attempt.attempt_no
                  AND (proof.id=mutation.id OR (proof.purpose='STATUS_ENQUIRY' AND proof.attempt_no>mutation.attempt_no
                    AND evidence.identity_binding #>> '{task,attemptId}'=mutation.id::text
                    AND evidence.identity_binding #>> '{task,nativeTaskKey}'=mutation.native_task_key))
                  AND evidence.response_complete AND evidence.identity_binding->>'qualified'='true'
                  AND evidence.identity_binding->>'extent'='EXACT_NATIVE_OBJECT'
                  AND evidence.identity_binding->>'nativeListingKey'=c.native_listing_key)
             OR (mutation.operation_snapshot->>'writeResultModel'='SYNCHRONOUS'
                 AND mutation.outcome_class IN ('UNKNOWN_STATE','TIMEOUT','RETRIABLE_ERROR')
                 AND mutation.operation_snapshot #>> '{endpoint,idempotency_support}'='YES'
                 AND (mutation.operation_snapshot-'responseIdentity')=platform.lc_description_operation_snapshot(c.capability_id,mutation.purpose)))
    );
$$;

CREATE FUNCTION ops.lc_description_retry_timing(p_platform text, p_headers jsonb, p_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET "TimeZone" TO 'UTC'
    SET "DateStyle" TO 'ISO, YMD'
    AS $_$
DECLARE
    header record; name text; value text; delay numeric; latest numeric := 0;
    found_timing boolean := false; deadline timestamptz;
BEGIN
    IF p_headers IS NULL OR jsonb_typeof(p_headers) <> 'object' OR p_at IS NULL THEN
        RETURN jsonb_build_object('state','UNKNOWN','reason','RETRY_TIMING_SHAPE_UNKNOWN');
    END IF;
    IF EXISTS (SELECT 1 FROM jsonb_each(p_headers) e
        WHERE lower(e.key) IN ('retry-after','item-retry-after','x-ratelimit-retry')
        GROUP BY lower(e.key) HAVING count(*) > 1) THEN
        RETURN jsonb_build_object('state','UNKNOWN','reason','DUPLICATE_RETRY_HEADER');
    END IF;
    FOR header IN SELECT * FROM jsonb_each(p_headers) LOOP
        name := lower(header.key);
        IF name NOT IN ('retry-after','item-retry-after','x-ratelimit-retry') THEN CONTINUE; END IF;
        found_timing := true;
        IF jsonb_typeof(header.value) <> 'string'
            OR (name = 'item-retry-after' AND upper(p_platform) IS DISTINCT FROM 'OZON')
            OR (name = 'x-ratelimit-retry' AND upper(p_platform) IS DISTINCT FROM 'WILDBERRIES') THEN
            RETURN jsonb_build_object('state','UNKNOWN','reason','RETRY_HEADER_UNIT_UNKNOWN');
        END IF;
        value := btrim(header.value #>> '{}');
        IF value ~ '^[0-9]{1,10}$' THEN
            delay := value::numeric * CASE WHEN name='item-retry-after' THEN 60 ELSE 1 END;
        ELSIF name='retry-after' AND value ~ '^[A-Z][a-z]{2}, [0-9]{2} [A-Z][a-z]{2} [0-9]{4} [0-9]{2}:[0-9]{2}:[0-9]{2} GMT$' THEN
            BEGIN
                deadline := value::timestamptz;
                IF to_char(deadline, 'Dy, DD Mon YYYY HH24:MI:SS "GMT"') <> value THEN
                    RETURN jsonb_build_object('state','UNKNOWN','reason','RETRY_DATE_INVALID');
                END IF;
                delay := greatest(0, ceil(extract(epoch FROM deadline-p_at)));
            EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
                RETURN jsonb_build_object('state','UNKNOWN','reason','RETRY_DATE_INVALID');
            END;
        ELSE
            RETURN jsonb_build_object('state','UNKNOWN','reason','RETRY_VALUE_UNRESOLVED');
        END IF;
        -- The command protocol uses signed integer seconds. Overflow is a
        -- hold requiring resolution, never a cap that authorizes an early call.
        IF delay > 2147483647 THEN
            RETURN jsonb_build_object('state','UNKNOWN','reason','RETRY_DELAY_UNREPRESENTABLE');
        END IF;
        latest := greatest(latest,delay);
    END LOOP;
    RETURN CASE WHEN found_timing
        THEN jsonb_build_object('state','KNOWN','seconds',latest)
        ELSE jsonb_build_object('state','ABSENT') END;
END;
$_$;

CREATE FUNCTION ops.lc_description_timing_before_attempt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE command ops.lc_description_command%ROWTYPE;
BEGIN
    SELECT * INTO command FROM ops.lc_description_command WHERE id=NEW.command_id FOR UPDATE;
    IF command.provider_retry_timing_unknown OR command.provider_not_before > clock_timestamp() THEN
        RAISE EXCEPTION 'provider wait also applies to calls at an existing lease fence' USING ERRCODE='MO092';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.lc_description_timing_before_lease() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
BEGIN
    IF NEW.fence_token > OLD.fence_token AND
       (OLD.provider_retry_timing_unknown OR OLD.provider_not_before > clock_timestamp()
        OR OLD.next_attempt_at > clock_timestamp()) THEN
        RAISE EXCEPTION 'provider observation wait has not elapsed or is unknown' USING ERRCODE='MO092';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.lc_diagnostic_task_reference_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
BEGIN
    IF EXISTS(SELECT 1 FROM ops.work_task t WHERE t.id=NEW.id AND t.recommendation_id IS NULL)
       AND NOT EXISTS(SELECT 1 FROM ops.lc_task_responsibility b WHERE b.task_id=NEW.id
         AND b.source_health_id IS NOT NULL) THEN
        RAISE EXCEPTION 'Task requires its proposal or exact retained Listing diagnosis' USING ERRCODE='23514';
    END IF;
    RETURN NULL;
END $$;

CREATE FUNCTION ops.lc_enqueue_source_recalculation(p_org uuid, p_listing uuid, p_class text, p_reference text, p_source_time timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'core', 'mart'
    AS $$
DECLARE queued uuid;
BEGIN
    IF p_class NOT IN ('RISK','ORDINARY') OR NOT EXISTS (
        SELECT 1 FROM core.platform_listing l
        WHERE l.id=p_listing AND l.organization_id=p_org AND l.status='OBSERVED') THEN
        RETURN NULL;
    END IF;
    SELECT q.id INTO queued FROM ops.lc_recalculation_queue q
      WHERE q.organization_id=p_org AND q.platform_listing_id=p_listing
        AND q.trigger_reference=p_reference LIMIT 1;
    IF queued IS NOT NULL THEN RETURN queued; END IF;
    queued:=gen_random_uuid();
    INSERT INTO ops.lc_recalculation_queue(id,organization_id,platform_listing_id,trigger_class,target_minutes,
        trigger_reference,source_time,accepted_at,state)
    VALUES(queued,p_org,p_listing,p_class,CASE p_class WHEN 'RISK' THEN 5 ELSE 15 END,
        left(p_reference,512),p_source_time,clock_timestamp(),'QUEUED');
    RETURN queued;
END $$;

CREATE FUNCTION ops.lc_execution_receipt_is_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
    IF (to_jsonb(NEW)-ARRAY['task_event_id','task_recorded_at']) IS DISTINCT FROM
        (to_jsonb(OLD)-ARRAY['task_event_id','task_recorded_at'])
        OR (OLD.task_event_id IS NOT NULL AND (NEW.task_event_id IS DISTINCT FROM OLD.task_event_id
            OR NEW.task_recorded_at IS DISTINCT FROM OLD.task_recorded_at)) THEN
        RAISE EXCEPTION 'execution evidence and completed delivery are immutable' USING ERRCODE='MO093';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.lc_experience_application_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'core', 'mart'
    AS $$
BEGIN
    IF TG_OP<>'INSERT' THEN
        RAISE EXCEPTION 'experience application evidence is append-only' USING ERRCODE='23514';
    END IF;
    IF NOT EXISTS(SELECT 1 FROM ops.lc_action a JOIN ops.lc_evaluation_plan p ON p.action_id=a.id
        JOIN ops.lc_node_result r ON r.plan_id=p.id
        WHERE a.id=NEW.source_action_id AND r.id=NEW.source_result_id
          AND a.organization_id=NEW.organization_id AND r.organization_id=NEW.organization_id)
       OR NOT EXISTS(SELECT 1 FROM mart.lc_listing_health h JOIN core.lc_affected_set s ON s.id=h.affected_set_id
          WHERE h.platform_listing_id=NEW.target_listing_id AND s.affected_set_digest=NEW.target_affected_set_digest
            AND h.health_version=(SELECT max(x.health_version) FROM mart.lc_listing_health x
                                  WHERE x.platform_listing_id=NEW.target_listing_id)) THEN
        RAISE EXCEPTION 'experience application requires exact source result and current target scope' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END $$;

CREATE FUNCTION ops.lc_fence_promotion_context_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE org uuid;
BEGIN
 IF TG_OP='UPDATE' THEN
   FOR org IN SELECT DISTINCT id FROM (VALUES(OLD.organization_id),(NEW.organization_id)) AS x(id) ORDER BY id LOOP
     PERFORM pg_advisory_xact_lock(hashtext('lc_exposure_organization'),hashtext(org::text));
   END LOOP;
 ELSE
   PERFORM pg_advisory_xact_lock(hashtext('lc_exposure_organization'),hashtext(NEW.organization_id::text));
 END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION ops.lc_freeze_selected_simulation_reference() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF (OLD.action_kind IN ('LISTING_DESCRIPTION_CHANGE','LISTING_PROMOTION_ACTION')
      OR NEW.action_kind IN ('LISTING_DESCRIPTION_CHANGE','LISTING_PROMOTION_ACTION'))
   AND (NEW.proposed_parameters->'simulationId' IS DISTINCT FROM OLD.proposed_parameters->'simulationId'
     OR NEW.proposed_parameters->'simulationInputsDigest' IS DISTINCT FROM OLD.proposed_parameters->'simulationInputsDigest') THEN
  RAISE EXCEPTION 'prepared simulation reference is immutable; prepare a new proposal' USING ERRCODE='MO092';
 END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION ops.lc_known_promotion_context(p_org uuid, p_listing uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 WITH records AS (
   SELECT coalesce(jsonb_agg(jsonb_build_object(
       'id',e.id,'version',e.version,'state',e.state,'engagementKind',e.engagement_kind,
       'nativePromotionKey',e.native_promotion_key,'actionId',e.action_id,'adopted',e.adopted,
       'terms',e.terms,'priceFreeze',e.price_freeze,'autoParticipation',e.auto_participation,
       'termsEvidenceReference',e.terms_evidence_reference,'obligations',e.obligations,
       'newTransactionsStoppedAt',e.new_transactions_stopped_at)
       ORDER BY e.id),'[]'::jsonb) AS material
     FROM ops.lc_promotion_engagement e
    WHERE e.organization_id=p_org AND e.platform_listing_id=p_listing AND e.state<>'CLEARED'
 ) SELECT jsonb_build_object('coverage','KNOWN_RECORDS_ONLY','records',material,
       'digest',encode(sha256(convert_to(material::text,'UTF8')),'hex')) FROM records
$$;

CREATE FUNCTION ops.lc_late_association_is_lawful() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE action ops.lc_action%ROWTYPE; observed core.lc_description_observation%ROWTYPE;
 provenance core.fact_provenance%ROWTYPE; packet ops.lc_manual_packet%ROWTYPE;
 report ops.lc_manual_report%ROWTYPE; listing core.platform_listing%ROWTYPE;
BEGIN
 SELECT * INTO STRICT listing FROM core.platform_listing WHERE id=NEW.platform_listing_id
   AND organization_id=NEW.organization_id;
 SELECT * INTO STRICT observed FROM core.lc_description_observation WHERE id=NEW.observation_id
   AND organization_id=NEW.organization_id AND platform_listing_id=NEW.platform_listing_id;
 SELECT * INTO STRICT provenance FROM core.fact_provenance WHERE id=observed.provenance_id
   AND organization_id=NEW.organization_id;
 IF NEW.recorded_at<observed.acquired_at OR observed.observed_at>NEW.recorded_at
    OR NOT ops.lc_actor_holds_action(NEW.recorded_by_user_id,NEW.organization_id,listing.store_id,
         'LISTING_MANUAL_VERIFY') THEN
   RAISE EXCEPTION 'late association needs the retained event and current verifier authority' USING ERRCODE='MO092';
 END IF;
 IF NEW.action_id IS NOT NULL THEN
   SELECT * INTO action FROM ops.lc_action WHERE id=NEW.action_id;
   IF action.id IS NULL OR action.organization_id<>NEW.organization_id
      OR action.platform_listing_id<>NEW.platform_listing_id THEN
     RAISE EXCEPTION 'late association action must belong to the exact Listing' USING ERRCODE='MO092';
   END IF;
 END IF;
 IF NEW.state IS DISTINCT FROM (CASE NEW.association_kind WHEN 'LAWFUL_LATE_REPORT' THEN 'LINKED'
      WHEN 'UNAUTHORISED_DEVIATION' THEN 'OPEN' ELSE 'UNDER_VERIFICATION' END)
    OR NEW.closure_verification_id IS NOT NULL THEN
   RAISE EXCEPTION 'a new late association starts in its exact unresolved state' USING ERRCODE='MO092';
 END IF;
 IF NEW.association_kind='LAWFUL_LATE_REPORT' THEN
   SELECT p.* INTO packet FROM ops.lc_manual_packet p JOIN ops.lc_manual_report r ON r.packet_id=p.id
    WHERE p.action_id=action.id AND p.organization_id=NEW.organization_id
      AND r.operation_time=NEW.operation_time AND r.reported_at=NEW.report_time
      AND r.report_state='APPLIED' AND r.operation_qualification='LAWFUL_LATE_REPORT'
    ORDER BY r.id LIMIT 1;
   SELECT r.* INTO report FROM ops.lc_manual_report r WHERE r.packet_id=packet.id
      AND r.operation_time=NEW.operation_time AND r.reported_at=NEW.report_time
      AND r.report_state='APPLIED' AND r.operation_qualification='LAWFUL_LATE_REPORT' LIMIT 1;
   IF action.id IS NULL OR packet.id IS NULL OR report.id IS NULL OR action.execution_path<>'MANUAL'
      OR report.reporter_user_id<>packet.executor_user_id
      OR observed.text_digest IS DISTINCT FROM action.target_text_digest
      OR observed.observed_at<NEW.operation_time OR observed.acquired_at>NEW.recorded_at
      OR NOT EXISTS(SELECT 1 FROM ops.lc_launch l WHERE l.action_id=action.id
           AND l.id=packet.launch_id AND l.launched_at<=NEW.operation_time)
      OR (provenance.source_kind='MANUAL_ENTRY' AND
          (provenance.recorded_by_user_id IS NULL OR provenance.recorded_by_user_id=packet.executor_user_id))
      OR (provenance.source_kind='MARKETPLACE_RAW' AND provenance.raw_observation_id IS NULL)
      OR provenance.source_kind NOT IN ('MANUAL_ENTRY','MARKETPLACE_RAW') THEN
     RAISE EXCEPTION 'lawful late reporting must reproduce the exact authorised operation and independent result'
       USING ERRCODE='MO092';
   END IF;
 ELSIF NEW.association_kind='UNAUTHORISED_DEVIATION' THEN
   IF NEW.operation_time IS NULL OR NEW.operation_time>NEW.recorded_at
      OR NEW.report_time IS NULL OR NEW.report_time<NEW.operation_time
      OR length(btrim(coalesce(NEW.authority_gap,'')))=0
      OR length(btrim(coalesce(NEW.forward_disposition,'')))=0 THEN
     RAISE EXCEPTION 'deviation chronology, authority gap and forward disposition are retained' USING ERRCODE='MO092';
   END IF;
 END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION ops.lc_launch_and_command_are_atomic() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE action ops.lc_action%ROWTYPE; commands integer;
BEGIN
    SELECT * INTO STRICT action FROM ops.lc_action WHERE id=NEW.action_id;
    SELECT count(*) INTO commands FROM ops.lc_description_command c
        WHERE c.action_id=action.id AND c.launch_id=NEW.id AND c.binding_id=NEW.binding_id
          AND c.organization_id=NEW.organization_id;
    IF NEW.created_transaction_id IS DISTINCT FROM txid_current()
        OR (action.execution_path='API' AND commands<>1)
        OR (action.execution_path='MANUAL' AND EXISTS(SELECT 1 FROM ops.lc_description_command c WHERE c.action_id=action.id)) THEN
        RAISE EXCEPTION 'launch and its exact API command must commit together; manual launches create none'
            USING ERRCODE='MO092';
    END IF;
    RETURN NEW;
END
$$;

CREATE FUNCTION ops.lc_launch_plan_matches_purpose() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE action ops.lc_action%ROWTYPE; purpose text;
BEGIN
 SELECT * INTO STRICT action FROM ops.lc_action WHERE id=NEW.action_id;
 SELECT r.proposed_parameters->>'purposeCode' INTO purpose FROM ops.recommendation r
  WHERE r.id=action.recommendation_id AND r.organization_id=action.organization_id;
 IF NEW.organization_id<>action.organization_id THEN
  RAISE EXCEPTION 'launch organization does not match its action' USING ERRCODE='MO092';
 END IF;
 IF purpose IN ('LISTING_CONVERSION','PROMOTION') THEN
  IF NOT EXISTS(SELECT 1 FROM ops.lc_evaluation_plan p WHERE p.id=NEW.plan_id AND p.action_id=action.id
      AND p.organization_id=action.organization_id AND p.frozen_at<=NEW.launched_at) THEN
   RAISE EXCEPTION 'formal launch requires its exact previously frozen plan' USING ERRCODE='MO092';
  END IF;
 ELSIF purpose IN ('DESCRIPTION_CORRECTION','BOUNDED_EXPLORATION') THEN
  IF NEW.plan_id IS NOT NULL OR ops.lc_purpose_basis_digest(purpose,action.purpose_basis) IS NULL
    OR (purpose='BOUNDED_EXPLORATION' AND action.execution_path<>'MANUAL') THEN
   RAISE EXCEPTION 'nonformal launch binds its declared use rather than a formal result plan' USING ERRCODE='MO092';
  END IF;
 ELSE
  RAISE EXCEPTION 'launch purpose is unresolved' USING ERRCODE='MO092';
 END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION ops.lc_listing_uses_isolation_dependency(p_org uuid, p_listing uuid, p_kind text, p_reference text, p_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $_$
 SELECT CASE p_kind
  WHEN 'SHARED_TEMPLATE' THEN EXISTS(
    SELECT 1 FROM ops.lc_action a CROSS JOIN LATERAL jsonb_each(a.calibration_dependencies->'values') dependency
     WHERE a.organization_id=p_org AND a.platform_listing_id=p_listing
       AND a.state NOT IN ('CLOSED','CANCELLED')
       AND (ops.lc_action_calibration_recheck(a.id,p_at)->>'state') IN ('CURRENT','UNCHANGED_DEPENDENCIES')
       AND p_reference='lc-calibration-value:'||dependency.key||':'||
         encode(sha256(convert_to(dependency.value::text,'UTF8')),'hex'))
  WHEN 'SHARED_CAMPAIGN' THEN EXISTS(
    SELECT 1 FROM ops.lc_promotion_engagement e WHERE e.organization_id=p_org
      AND e.platform_listing_id=p_listing AND e.state<>'CLEARED' AND e.terms_digest IS NOT NULL
      AND p_reference='lc-promotion-terms:'||e.terms_digest)
  WHEN 'SHARED_VARIANT_SET' THEN EXISTS(
    SELECT 1 FROM core.lc_affected_set s WHERE s.organization_id=p_org
      AND s.platform_listing_id=p_listing AND s.resolution_state='COMPLETE'
      AND s.affected_set_digest=core.lc_listing_affected_set_digest(p_listing)
      AND p_reference ~ '^lc-product-variant:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      AND substring(p_reference from 20)::uuid=ANY(s.product_variant_ids))
  ELSE false END
$_$;

CREATE FUNCTION ops.lc_manual_packet_binds_promotion_terms() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE action ops.lc_action%ROWTYPE;
BEGIN
 SELECT * INTO STRICT action FROM ops.lc_action WHERE id=NEW.action_id;
 IF action.action_kind='LISTING_PROMOTION_ACTION' THEN
   IF action.promotion_terms_digest IS NULL THEN
     RAISE EXCEPTION 'historical unbound promotion cannot acquire a new execution packet' USING ERRCODE='MO092';
   END IF;
   IF NEW.promotion_terms_digest IS NOT NULL AND NEW.promotion_terms_digest<>action.promotion_terms_digest THEN
     RAISE EXCEPTION 'packet names different promotion terms' USING ERRCODE='MO092';
   END IF;
   NEW.promotion_terms_digest:=action.promotion_terms_digest;
 END IF;
 RETURN NEW;
END
$$;

CREATE FUNCTION ops.lc_manual_packet_requires_current_authority() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE action ops.lc_action%ROWTYPE; binding ops.lc_action_binding%ROWTYPE; now_at timestamptz:=clock_timestamp();
BEGIN
 SELECT * INTO action FROM ops.lc_action WHERE id=NEW.action_id;
 SELECT * INTO binding FROM ops.lc_action_binding WHERE action_id=NEW.action_id;
 IF action.id IS NULL OR binding.id IS NULL OR action.organization_id<>NEW.organization_id
    OR action.state<>'LAUNCHED' OR action.execution_path<>'MANUAL'
    OR NEW.launch_id IS DISTINCT FROM (SELECT id FROM ops.lc_launch WHERE action_id=action.id)
    OR NEW.issued_at>now_at OR NEW.expires_at<=now_at OR NEW.expires_at>binding.expires_at
    OR cardinality(ops.lc_binding_gaps(action.id))>0
    OR ops.lc_scope_contained(action.organization_id,action.platform_listing_id)
    OR NOT ops.lc_actor_holds_action(NEW.issued_by_user_id,action.organization_id,action.store_id,'LISTING_ACTION_LAUNCH')
    OR NOT ops.lc_actor_holds_action(NEW.executor_user_id,action.organization_id,action.store_id,'LISTING_MANUAL_EXECUTE') THEN
   RAISE EXCEPTION 'manual packet requires the exact current launch, binding, scope and people' USING ERRCODE='MO092';
 END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION ops.lc_manual_packet_requires_launch() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE action ops.lc_action%ROWTYPE; launch ops.lc_launch%ROWTYPE; binding ops.lc_action_binding%ROWTYPE;
BEGIN
    SELECT * INTO action FROM ops.lc_action WHERE id = NEW.action_id;
    SELECT * INTO launch FROM ops.lc_launch WHERE id = NEW.launch_id;
    IF action.id IS NULL OR launch.id IS NULL OR launch.action_id <> action.id THEN
        RAISE EXCEPTION 'a packet is issued from its own launch' USING ERRCODE = 'MO090';
    END IF;
    IF action.state <> 'LAUNCHED' OR action.execution_path <> 'MANUAL' THEN
        RAISE EXCEPTION 'a packet is issued only from a launched manual action' USING ERRCODE = 'MO091';
    END IF;
    SELECT * INTO binding FROM ops.lc_action_binding WHERE id = launch.binding_id;
    IF NEW.affected_set_digest <> action.affected_set_digest
        OR NEW.target_text IS DISTINCT FROM action.target_text
        OR NEW.expires_at > binding.expires_at THEN
        RAISE EXCEPTION 'a packet carries the exact bound material and never outlives the binding'
            USING ERRCODE = 'MO092';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.lc_manual_report_by_executor() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE packet ops.lc_manual_packet%ROWTYPE;
BEGIN
    SELECT * INTO packet FROM ops.lc_manual_packet WHERE id = NEW.packet_id;
    IF NOT FOUND OR packet.executor_user_id <> NEW.reporter_user_id THEN
        RAISE EXCEPTION 'a manual report comes from the packet executor' USING ERRCODE = 'MO092';
    END IF;
    IF packet.state NOT IN ('ISSUED', 'REPORTED') THEN
        RAISE EXCEPTION 'the packet is not open for a report' USING ERRCODE = 'MO091';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.lc_manual_verification_binds_observations() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'core', 'pg_temp'
    SET "TimeZone" TO 'UTC'
    SET "DateStyle" TO 'ISO, YMD'
    AS $$
DECLARE
    packet ops.lc_manual_packet%ROWTYPE;
    action ops.lc_action%ROWTYPE;
    management core.lc_description_observation%ROWTYPE;
    display core.lc_display_observation%ROWTYPE;
    provenance core.fact_provenance%ROWTYPE;
    after_operation timestamptz;
BEGIN
    SELECT * INTO STRICT packet FROM ops.lc_manual_packet WHERE id=NEW.packet_id;
    SELECT * INTO STRICT action FROM ops.lc_action WHERE id=packet.action_id;
    IF action.action_kind='LISTING_PROMOTION_ACTION' THEN
        NEW.observation_binding:=ops.lc_bind_promotion_participation(NEW);
        RETURN NEW;
    ELSIF NEW.promotion_observation_id IS NOT NULL THEN
        RAISE EXCEPTION 'description verification cannot borrow promotion evidence' USING ERRCODE='MO092';
    END IF;
    SELECT greatest(packet.issued_at,coalesce(max(r.operation_time),packet.issued_at))
        INTO after_operation FROM ops.lc_manual_report r WHERE r.packet_id=packet.id AND r.reported_at<=NEW.verified_at;
    IF packet.organization_id<>NEW.organization_id OR NEW.verified_at<after_operation THEN
        RAISE EXCEPTION 'verification belongs to the exact packet after its recorded operation' USING ERRCODE='MO092';
    END IF;
    IF NEW.management_observation_id IS NOT NULL THEN
        SELECT * INTO STRICT management FROM core.lc_description_observation WHERE id=NEW.management_observation_id;
        SELECT * INTO STRICT provenance FROM core.fact_provenance WHERE id=management.provenance_id;
        IF management.organization_id<>NEW.organization_id OR provenance.organization_id<>NEW.organization_id
            OR management.platform_listing_id<>action.platform_listing_id
            OR management.observed_at<after_operation OR management.acquired_at>NEW.verified_at THEN
            RAISE EXCEPTION 'management observation is outside the exact operation identity or evidence time' USING ERRCODE='MO092';
        END IF;
        IF provenance.source_kind='MANUAL_ENTRY' AND (provenance.recorded_by_user_id=packet.executor_user_id
            OR EXISTS(SELECT 1 FROM ops.lc_manual_report r WHERE r.packet_id=packet.id AND r.reporter_user_id=provenance.recorded_by_user_id)) THEN
            RAISE EXCEPTION 'executor-entered management text is not independent verification evidence' USING ERRCODE='MO092';
        END IF;
    END IF;
    IF NEW.display_observation_id IS NOT NULL THEN
        SELECT * INTO STRICT display FROM core.lc_display_observation WHERE id=NEW.display_observation_id;
        SELECT * INTO STRICT provenance FROM core.fact_provenance WHERE id=display.provenance_id;
        IF display.organization_id<>NEW.organization_id OR provenance.organization_id<>NEW.organization_id
            OR display.platform_listing_id<>action.platform_listing_id
            OR display.observed_at<after_operation OR display.acquired_at>NEW.verified_at THEN
            RAISE EXCEPTION 'customer display observation is outside the exact operation identity or evidence time' USING ERRCODE='MO092';
        END IF;
        IF display.display_state<>NEW.display_state OR
            (NEW.display_state='DISPLAYED' AND display.displayed_text_digest IS DISTINCT FROM action.target_text_digest) THEN
            RAISE EXCEPTION 'claimed customer target display contradicts the retained observation' USING ERRCODE='MO093';
        END IF;
        IF display.evidence_grade='INDEPENDENT_HUMAN' THEN
            IF NEW.verification_basis='OFFICIAL_EVIDENCE' OR display.observer_user_id=packet.executor_user_id
                OR EXISTS(SELECT 1 FROM ops.lc_manual_report r WHERE r.packet_id=packet.id AND r.reporter_user_id=display.observer_user_id)
                OR provenance.source_kind<>'MANUAL_ENTRY' OR provenance.recorded_by_user_id IS DISTINCT FROM display.observer_user_id THEN
                RAISE EXCEPTION 'customer display needs independently captured human evidence' USING ERRCODE='MO092';
            END IF;
        ELSIF provenance.source_kind<>'MARKETPLACE_RAW' OR provenance.raw_observation_id IS NULL THEN
            RAISE EXCEPTION 'official customer display needs retained marketplace source bytes' USING ERRCODE='MO092';
        END IF;
    ELSIF NEW.display_state<>'UNKNOWN' THEN
        RAISE EXCEPTION 'customer display requires its own exact observation' USING ERRCODE='MO093';
    END IF;
    NEW.observation_binding:=jsonb_build_object(
        'actionId',action.id,'listingId',action.platform_listing_id,'targetTextDigest',action.target_text_digest,
        'packetId',packet.id,'afterOperation',after_operation,'verifiedAt',NEW.verified_at,
        'managementObservationId',NEW.management_observation_id,
        'managementObservationDigest',CASE WHEN NEW.management_observation_id IS NULL THEN NULL
            ELSE encode(sha256(convert_to(to_jsonb(management)::text,'UTF8')),'hex') END,
        'displayObservationId',NEW.display_observation_id,
        'displayObservationDigest',CASE WHEN NEW.display_observation_id IS NULL THEN NULL
            ELSE encode(sha256(convert_to(to_jsonb(display)::text,'UTF8')),'hex') END,
        'displayClaimExtent','OBSERVED_INSTANT_ONLY');
    RETURN NEW;
END
$$;

CREATE FUNCTION ops.lc_manual_verification_is_independent() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'core', 'pg_temp'
    AS $$
DECLARE packet ops.lc_manual_packet%ROWTYPE; action ops.lc_action%ROWTYPE; observed text;
BEGIN
    SELECT * INTO packet FROM ops.lc_manual_packet WHERE id = NEW.packet_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'verification names an unknown packet' USING ERRCODE = 'MO090'; END IF;
    SELECT * INTO action FROM ops.lc_action WHERE id = packet.action_id;
    IF NEW.verifier_user_id IS NOT NULL AND (NEW.verifier_user_id = packet.executor_user_id
        OR EXISTS (SELECT 1 FROM ops.lc_manual_report r
                    WHERE r.packet_id = packet.id AND r.reporter_user_id = NEW.verifier_user_id)) THEN
        RAISE EXCEPTION 'the executor does not verify the execution' USING ERRCODE = 'MO092';
    END IF;
    IF action.action_kind='LISTING_PROMOTION_ACTION' THEN RETURN NEW; END IF;
    IF NEW.verification_basis = 'OFFICIAL_EVIDENCE' AND NOT EXISTS (
        SELECT 1 FROM core.lc_description_observation o
          JOIN core.fact_provenance p ON p.id = o.provenance_id
         WHERE o.id = NEW.management_observation_id AND p.source_kind = 'MARKETPLACE_RAW') THEN
        RAISE EXCEPTION 'official evidence is a marketplace-sourced observation' USING ERRCODE = 'MO092';
    END IF;
    IF NEW.management_observation_id IS NOT NULL THEN
        SELECT o.text_digest INTO observed FROM core.lc_description_observation o
         WHERE o.id = NEW.management_observation_id AND o.platform_listing_id = action.platform_listing_id
           AND o.observed_at >= packet.issued_at;
        IF observed IS NULL THEN
            RAISE EXCEPTION 'a verification observation is of this listing after the packet was issued'
                USING ERRCODE = 'MO092';
        END IF;
        IF (NEW.management_match = 'MATCHED_TARGET' AND observed IS DISTINCT FROM action.target_text_digest)
            OR (NEW.management_match = 'MATCHED_PRIOR' AND observed IS DISTINCT FROM action.current_text_digest)
            OR (NEW.management_match = 'DIFFERENT'
                AND (observed = action.target_text_digest OR observed = action.current_text_digest)) THEN
            RAISE EXCEPTION 'the claimed management match contradicts the observation digest'
                USING ERRCODE = 'MO093';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.lc_manual_verified_action_requires_bound_observations() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
BEGIN
 IF NEW.execution_path='MANUAL' AND NEW.state='VERIFIED' AND OLD.state<>NEW.state AND NOT EXISTS(
   SELECT 1 FROM ops.lc_manual_verification verification
   JOIN ops.lc_manual_packet packet ON packet.id=verification.packet_id
   WHERE packet.action_id=NEW.id AND verification.management_match='MATCHED_TARGET'
     AND verification.qualification_state='QUALIFIED'
     AND ((NEW.action_kind='LISTING_DESCRIPTION_CHANGE'
           AND verification.observation_binding->>'targetTextDigest'=NEW.target_text_digest)
       OR (NEW.action_kind='LISTING_PROMOTION_ACTION'
           AND verification.observation_binding->>'purpose'='PARTICIPATION'
           AND verification.observation_binding->>'claimExtent'='OBSERVED_INSTANT_ONLY'
           AND verification.observation_binding->>'participationState'='PARTICIPATING'
           AND verification.observation_binding->>'promotionTermsDigest'=ops.lc_promotion_terms_digest(NEW.promotion_terms)))
     AND verification.observation_binding->>'actionId'=NEW.id::text) THEN
   RAISE EXCEPTION 'manual verification must be qualified for this exact Action and observed result' USING ERRCODE='MO092';
 END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION ops.lc_materiality_evidence_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NEW.materiality_evidence IS DISTINCT FROM OLD.materiality_evidence THEN
  RAISE EXCEPTION 'prepared materiality evidence is immutable' USING ERRCODE='MO106';
 END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION ops.lc_meaning_review_basis_digest(p_action uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT CASE WHEN NOT (r.proposed_parameters ? 'simulationId') THEN ops.lc_meaning_review_basis_digest_v0112(p_action)
  ELSE encode(sha256(convert_to(jsonb_build_array('LC_MEANING_SIMULATION_BASIS_1',
    ops.lc_meaning_review_basis_digest_v0112(p_action),r.proposed_parameters->>'simulationId',
    r.proposed_parameters->>'simulationInputsDigest')::text,'UTF8')),'hex') END
 FROM ops.lc_action a JOIN ops.recommendation r ON r.id=a.recommendation_id AND r.organization_id=a.organization_id
 WHERE a.id=p_action
$$;

CREATE FUNCTION ops.lc_meaning_review_basis_digest_v0107(p_action uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT encode(sha256(convert_to(jsonb_build_object('model','LC_MEANING_BASIS_1','actionId',a.id,
  'currentTextDigest',a.current_text_digest,'targetTextDigest',a.target_text_digest,
  'promotionTermsDigest',a.promotion_terms_digest,'affectedSetDigest',a.affected_set_digest,
  'calibrationDigest',ops.lc_calibration_digest(a.calibration_package_id),
  'conditions',core.lc_meaning_catalog(a.calibration_package_id,a.action_kind))::text,'UTF8')),'hex')
 FROM ops.lc_action a WHERE a.id=p_action
$$;

CREATE FUNCTION ops.lc_meaning_review_basis_digest_v0112(p_action uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT CASE WHEN a.purpose_basis IS NULL THEN ops.lc_meaning_review_basis_digest_v0107(p_action)
   ELSE encode(sha256(convert_to(jsonb_build_array('LC_MEANING_PURPOSE_BASIS_1',
      ops.lc_meaning_review_basis_digest_v0107(p_action),
      ops.lc_purpose_basis_digest(r.proposed_parameters->>'purposeCode',a.purpose_basis))::text,'UTF8')),'hex') END
 FROM ops.lc_action a JOIN ops.recommendation r ON r.id=a.recommendation_id WHERE a.id=p_action
$$;

CREATE FUNCTION ops.lc_node_evidence_matches_plan() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE
    plan ops.lc_evaluation_plan%ROWTYPE;
    node jsonb;
    traffic jsonb;
    measured mart.lc_conversion_measurement%ROWTYPE;
    target_text text;
    lower_text text;
    lower_value numeric;
    evidence_from timestamptz;
    evidence_to timestamptz;
    expected_stop boolean;
BEGIN
    SELECT * INTO STRICT plan FROM ops.lc_evaluation_plan WHERE id=NEW.plan_id;
    SELECT entry INTO node
      FROM jsonb_array_elements(plan.formal_nodes) AS nodes(entry)
     WHERE entry->>'nodeCode'=NEW.node_code;
    IF NEW.evaluation_evidence IS NULL OR
       NEW.evaluation_evidence->>'planDigest' IS DISTINCT FROM plan.plan_digest OR
       NEW.evaluation_evidence->>'nodeCode' IS DISTINCT FROM NEW.node_code OR
       NEW.evaluation_evidence->>'requestedStage' IS DISTINCT FROM NEW.stage OR
       jsonb_typeof(NEW.evaluation_evidence->'qualificationGaps') IS DISTINCT FROM 'array' OR
       node IS NULL THEN
        RAISE EXCEPTION 'node evidence must retain its exact frozen plan, node, stage and qualification gaps'
            USING ERRCODE='MO093';
    END IF;

    IF node->>'method'='EXACT_BINOMIAL_FIXED_TRAFFIC_BONFERRONI_V1' THEN
        traffic:=NEW.evaluation_evidence->'formalTrafficComparison';
        IF jsonb_typeof(traffic) IS DISTINCT FROM 'object' OR
           traffic->>'method' IS DISTINCT FROM node->>'method' OR
           traffic->>'referenceMeasurementId' IS DISTINCT FROM node#>>'{comparisonReference,referenceMeasurementId}' OR
           NEW.accepted_threshold IS DISTINCT FROM (node->>'threshold')::numeric OR
           NEW.maturity_reached IS DISTINCT FROM
             coalesce((NEW.evaluation_evidence->>'nodeWindowQualified')::boolean,false) THEN
            RAISE EXCEPTION 'formal outcome must consume the exact frozen method, threshold, reference and node admission'
                USING ERRCODE='MO093';
        END IF;

        target_text:=traffic->>'targetMeasurementId';
        IF NEW.measurement_id IS NULL THEN
            IF target_text IS NOT NULL OR NEW.primary_ratio IS NOT NULL OR NEW.conservative_bound IS NOT NULL
                    OR NEW.source_time IS NOT NULL OR NEW.maturity_reached THEN
                RAISE EXCEPTION 'an absent target measurement cannot carry measured facts or a formal bound'
                    USING ERRCODE='MO093';
            END IF;
        ELSE
            BEGIN
                IF target_text IS NULL OR target_text::uuid IS DISTINCT FROM NEW.measurement_id THEN
                    RAISE EXCEPTION 'formal evidence must name the inserted target measurement' USING ERRCODE='MO093';
                END IF;
            EXCEPTION WHEN invalid_text_representation THEN
                RAISE EXCEPTION 'formal evidence contains an invalid target measurement identity' USING ERRCODE='MO093';
            END;
            SELECT * INTO STRICT measured FROM mart.lc_conversion_measurement WHERE id=NEW.measurement_id;
            IF measured.organization_id IS DISTINCT FROM NEW.organization_id OR
               NOT EXISTS (SELECT 1 FROM ops.lc_action action
                 WHERE action.id=plan.action_id AND action.organization_id=NEW.organization_id
                   AND action.platform_listing_id=measured.platform_listing_id) OR
               NEW.primary_ratio IS DISTINCT FROM measured.primary_ratio OR
               NEW.source_time IS DISTINCT FROM measured.source_time OR
               NEW.evaluation_evidence->>'measurementId' IS DISTINCT FROM target_text THEN
                RAISE EXCEPTION 'formal result measurement facts or scope do not match the canonical measurement'
                    USING ERRCODE='MO093';
            END IF;
            BEGIN
                evidence_from:=(NEW.evaluation_evidence->>'frozenWindowStart')::timestamptz;
                evidence_to:=(NEW.evaluation_evidence->>'frozenWindowEnd')::timestamptz;
            EXCEPTION WHEN others THEN
                RAISE EXCEPTION 'formal evidence contains an invalid frozen window' USING ERRCODE='MO093';
            END;
            IF measured.window_start IS DISTINCT FROM evidence_from OR measured.window_end IS DISTINCT FROM evidence_to OR
               measured.retention_window_days IS DISTINCT FROM (node->>'maturityDays')::integer THEN
                RAISE EXCEPTION 'formal result measurement is outside the exact frozen node window'
                    USING ERRCODE='MO093';
            END IF;
        END IF;

        lower_text:=traffic->>'lowerDifference';
        IF lower_text IS NULL THEN
            IF NEW.conservative_bound IS NOT NULL THEN
                RAISE EXCEPTION 'an unqualified comparison cannot carry a conservative bound' USING ERRCODE='MO093';
            END IF;
        ELSE
            BEGIN
                lower_value:=lower_text::numeric;
            EXCEPTION WHEN others THEN
                RAISE EXCEPTION 'formal evidence contains an invalid lower improvement bound' USING ERRCODE='MO093';
            END;
            IF traffic->>'state' IS DISTINCT FROM 'QUALIFIED_FORMAL_COMPARISON' OR
               NEW.conservative_bound IS DISTINCT FROM lower_value THEN
                RAISE EXCEPTION 'the result bound must equal the qualified frozen-comparison lower bound'
                    USING ERRCODE='MO093';
            END IF;
        END IF;
        expected_stop:=coalesce(NEW.evaluation_evidence#>>'{futility,state}'='TRIGGERED',false);
        IF NEW.stop_triggered IS DISTINCT FROM expected_stop THEN
            RAISE EXCEPTION 'stop state must come from the frozen qualified futility rule' USING ERRCODE='MO093';
        END IF;
    END IF;
    RETURN NEW;
END
$$;

CREATE FUNCTION ops.lc_node_result_is_consistent() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
BEGIN
    IF NEW.protection_verdict <> ops.lc_protection_verdict_of(NEW.protection_vector) THEN
        RAISE EXCEPTION 'the protection verdict is derived from the vector; % was supplied where % follows',
            NEW.protection_verdict, ops.lc_protection_verdict_of(NEW.protection_vector) USING ERRCODE = 'MO093';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM ops.lc_evaluation_plan p
                    WHERE p.id = NEW.plan_id AND p.organization_id = NEW.organization_id
                      AND EXISTS (SELECT 1 FROM jsonb_array_elements(p.formal_nodes) node
                                   WHERE node ->> 'nodeCode' = NEW.node_code)) THEN
        RAISE EXCEPTION 'a result belongs to a node the frozen plan names' USING ERRCODE = 'MO092';
    END IF;
    IF NEW.revision_no > 0 AND NOT EXISTS (
        SELECT 1 FROM ops.lc_node_result prior
         WHERE prior.plan_id = NEW.plan_id AND prior.node_code = NEW.node_code
           AND prior.stage = NEW.stage AND prior.revision_no = NEW.revision_no - 1) THEN
        RAISE EXCEPTION 'a revision follows the result it revises' USING ERRCODE = 'MO092';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.lc_plan_precedes_review() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE action ops.lc_action%ROWTYPE;
BEGIN
    SELECT * INTO STRICT action FROM ops.lc_action WHERE id=NEW.action_id;
    IF action.state<>'DRAFT' OR NEW.organization_id<>action.organization_id
        OR NEW.calibration_package_id IS DISTINCT FROM action.calibration_package_id
        OR NEW.calibration_version IS DISTINCT FROM action.calibration_version
        OR NEW.frozen_at<action.created_at OR NEW.frozen_at>statement_timestamp()
        OR EXISTS (SELECT 1 FROM ops.lc_action_review r WHERE r.action_id=action.id AND r.verdict='ATTESTED') THEN
        RAISE EXCEPTION 'a plan must be frozen for the exact draft before review or approval' USING ERRCODE='MO092';
    END IF;
    RETURN NEW;
END
$$;

CREATE FUNCTION ops.lc_promotion_entry_matches_approved_declaration() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE action ops.lc_action%ROWTYPE; actual jsonb;
BEGIN
 IF TG_OP='UPDATE' THEN
   IF OLD.action_id IS NOT NULL AND ROW(NEW.organization_id,NEW.store_id,NEW.platform_listing_id,
       NEW.action_id,NEW.engagement_kind,NEW.native_promotion_key,NEW.terms,NEW.price_freeze,
       NEW.auto_participation,NEW.terms_evidence_reference,NEW.obligations,NEW.adopted)
     IS DISTINCT FROM ROW(OLD.organization_id,OLD.store_id,OLD.platform_listing_id,
       OLD.action_id,OLD.engagement_kind,OLD.native_promotion_key,OLD.terms,OLD.price_freeze,
       OLD.auto_participation,OLD.terms_evidence_reference,OLD.obligations,OLD.adopted) THEN
     RAISE EXCEPTION 'bound commercial declaration is immutable; changed terms need new authority' USING ERRCODE='MO092';
   END IF;
   IF NEW.action_id IS NOT DISTINCT FROM OLD.action_id THEN RETURN NEW; END IF;
 END IF;
 IF NEW.action_id IS NULL THEN RETURN NEW; END IF; -- Adoption remains a separate observed-fact path.
 SELECT * INTO STRICT action FROM ops.lc_action WHERE id=NEW.action_id;
 actual:=jsonb_build_object('engagementKind',NEW.engagement_kind,'nativePromotionKey',NEW.native_promotion_key,
   'terms',NEW.terms,'priceFreeze',NEW.price_freeze,'autoParticipation',NEW.auto_participation,
   'termsEvidenceReference',NEW.terms_evidence_reference,'obligations',NEW.obligations);
 IF action.action_kind<>'LISTING_PROMOTION_ACTION' OR action.execution_path<>'MANUAL'
   OR action.state NOT IN ('LAUNCHED','VERIFIED') OR action.promotion_terms IS DISTINCT FROM actual
   OR action.organization_id<>NEW.organization_id OR action.platform_listing_id<>NEW.platform_listing_id
   OR action.store_id<>NEW.store_id THEN
   RAISE EXCEPTION 'entry cannot acquire the authority of different approved promotion terms' USING ERRCODE='MO092';
 END IF;
 RETURN NEW;
END
$$;

CREATE FUNCTION ops.lc_promotion_observation_is_independent_current(p_observation uuid, p_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS(
   SELECT 1 FROM core.lc_promotion_observation o
   JOIN core.fact_provenance p ON p.id=o.provenance_id AND p.organization_id=o.organization_id
   JOIN core.platform_listing l ON l.id=o.platform_listing_id AND l.organization_id=o.organization_id
   WHERE o.id=p_observation AND o.context_coverage='COMPLETE_ENUMERATION'
     AND o.observed_at<=p_at AND o.acquired_at<=p_at AND o.verification_expires_at>p_at
     AND p.source_time=o.observed_at AND p.ingestion_time=o.acquired_at
     AND ((p.source_kind='MARKETPLACE_RAW' AND p.raw_observation_id IS NOT NULL)
       OR (p.source_kind='MANUAL_ENTRY' AND p.recorded_by_user_id IS NOT NULL
         AND ops.lc_actor_holds_action(p.recorded_by_user_id,o.organization_id,l.store_id,'LISTING_MANUAL_VERIFY'))))
$$;

CREATE FUNCTION ops.lc_promotion_terms_digest(p_terms jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE part jsonb;
BEGIN
 IF p_terms IS NULL THEN RETURN NULL; END IF;
 IF jsonb_typeof(p_terms)<>'object' OR octet_length(p_terms::text)>131072 THEN
   RAISE EXCEPTION 'bounded promotion declaration required' USING ERRCODE='MO036';
 END IF;
 IF (SELECT count(*) FROM jsonb_object_keys(p_terms))<>7
   OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_terms) k WHERE k NOT IN
     ('engagementKind','nativePromotionKey','terms','priceFreeze','autoParticipation','termsEvidenceReference','obligations'))
   OR coalesce(p_terms->>'engagementKind','') NOT IN ('OFFICIAL_PROMOTION_PARTICIPATION','SELLER_DIRECT_DISCOUNT')
   OR jsonb_typeof(p_terms->'nativePromotionKey') IS DISTINCT FROM 'string'
   OR length(btrim(p_terms->>'nativePromotionKey'))=0 OR length(p_terms->>'nativePromotionKey')>128
   OR jsonb_typeof(p_terms->'termsEvidenceReference') IS DISTINCT FROM 'string'
   OR length(btrim(p_terms->>'termsEvidenceReference'))=0 OR length(p_terms->>'termsEvidenceReference')>512
   OR jsonb_typeof(p_terms->'priceFreeze') IS DISTINCT FROM 'boolean'
   OR jsonb_typeof(p_terms->'autoParticipation') IS DISTINCT FROM 'boolean' THEN
   RAISE EXCEPTION 'exact promotion declaration shape required' USING ERRCODE='MO036';
 END IF;
 FOREACH part IN ARRAY ARRAY[p_terms->'terms',p_terms->'obligations'] LOOP
   IF jsonb_typeof(part) IS DISTINCT FROM 'object' THEN
     RAISE EXCEPTION 'promotion terms and obligations are explicit maps' USING ERRCODE='MO036';
   END IF;
   IF (SELECT count(*) FROM jsonb_object_keys(part)) NOT BETWEEN 1 AND 64
     OR EXISTS(SELECT 1 FROM jsonb_each(part) e WHERE length(btrim(e.key))=0 OR length(e.key)>128
       OR jsonb_typeof(e.value)<>'string' OR length(btrim(e.value#>>'{}'))=0 OR length(e.value#>>'{}')>512) THEN
     RAISE EXCEPTION 'bounded explicit promotion values required' USING ERRCODE='MO036';
   END IF;
 END LOOP;
 RETURN encode(sha256(convert_to(p_terms::text,'UTF8')),'hex');
END
$$;

CREATE FUNCTION ops.lc_protection_verdict_of(p_vector jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
    IF p_vector IS NULL OR jsonb_typeof(p_vector) <> 'object' THEN
        RETURN 'UNDETERMINED';
    END IF;
    IF EXISTS (SELECT 1 FROM jsonb_each(p_vector) e WHERE e.value = '"FAIL"'::jsonb) THEN
        RETURN 'FAIL';
    END IF;
    IF NOT p_vector ?& ARRAY['DIRECT_CONTRIBUTION_PROFIT', 'LINKED_SCOPE_PROFIT',
            'OVERALL_RETURN_RATE', 'CRITICAL_VARIANT_RETURN', 'SUPPLY_COVERAGE'] THEN
        RETURN 'UNDETERMINED';
    END IF;
    IF EXISTS (SELECT 1 FROM jsonb_each(p_vector) e WHERE e.value IS DISTINCT FROM '"PASS"'::jsonb) THEN
        RETURN 'UNDETERMINED';
    END IF;
    RETURN 'PASS';
END
$$;

CREATE FUNCTION ops.lc_purpose_basis_digest(p_purpose text, p_basis jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT encode(sha256(convert_to(jsonb_build_array('LC_PURPOSE_BASIS_1',p_purpose,p_basis)::text,'UTF8')),'hex')
$$;

CREATE FUNCTION ops.lc_qualify_promotion_engagement() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    SET "DateStyle" TO 'ISO, YMD'
    AS $$
DECLARE observed core.lc_promotion_observation%ROWTYPE; provenance core.fact_provenance%ROWTYPE;
 item jsonb; context jsonb; now_at timestamptz:=statement_timestamp();
BEGIN
 NEW.terms_digest:=ops.lc_promotion_terms_digest(jsonb_build_object(
   'engagementKind',NEW.engagement_kind,'nativePromotionKey',NEW.native_promotion_key,'terms',NEW.terms,
   'priceFreeze',NEW.price_freeze,'autoParticipation',NEW.auto_participation,
   'termsEvidenceReference',NEW.terms_evidence_reference,'obligations',NEW.obligations));
 IF TG_OP='UPDATE' THEN
   IF ROW(NEW.organization_id,NEW.store_id,NEW.platform_listing_id,NEW.action_id,NEW.engagement_kind,
       NEW.native_promotion_key,NEW.terms,NEW.price_freeze,NEW.auto_participation,
       NEW.terms_evidence_reference,NEW.adopted,NEW.obligations,NEW.source_context_observation_id,
       NEW.original_authority_reference,NEW.original_authority_valid_until,NEW.responsible_user_id,
       NEW.adoption_qualification_state,NEW.axis_demands)
      IS DISTINCT FROM
      ROW(OLD.organization_id,OLD.store_id,OLD.platform_listing_id,OLD.action_id,OLD.engagement_kind,
       OLD.native_promotion_key,OLD.terms,OLD.price_freeze,OLD.auto_participation,
       OLD.terms_evidence_reference,OLD.adopted,OLD.obligations,OLD.source_context_observation_id,
       OLD.original_authority_reference,OLD.original_authority_valid_until,OLD.responsible_user_id,
       OLD.adoption_qualification_state,OLD.axis_demands) THEN
     RAISE EXCEPTION 'promotion identity, terms, authority and adopted responsibility are immutable' USING ERRCODE='MO092';
   END IF;
   RETURN NEW;
 END IF;
 IF NOT NEW.adopted THEN
   NEW.adoption_qualification_state:='ACTION_AUTHORIZED';
   NEW.source_context_observation_id:=NULL; NEW.original_authority_reference:=NULL;
   NEW.original_authority_valid_until:=NULL; NEW.responsible_user_id:=NULL; NEW.axis_demands:=NULL;
   RETURN NEW;
 END IF;
 NEW.adoption_qualification_state:='FACT_RECORDED_UNQUALIFIED';
 NEW.axis_demands:=NULL;
 IF NEW.source_context_observation_id IS NULL OR NEW.original_authority_reference IS NULL
    OR length(btrim(NEW.original_authority_reference)) NOT BETWEEN 1 AND 512
    OR NEW.original_authority_valid_until IS NULL OR NEW.original_authority_valid_until<=now_at
    OR NEW.responsible_user_id IS NULL
    OR NOT ops.lc_actor_holds_action(NEW.responsible_user_id,NEW.organization_id,NEW.store_id,'LISTING_PROMOTION_MANAGE') THEN
   RETURN NEW;
 END IF;
 SELECT * INTO observed FROM core.lc_promotion_observation o WHERE o.id=NEW.source_context_observation_id
   AND o.organization_id=NEW.organization_id AND o.platform_listing_id=NEW.platform_listing_id;
 IF observed.id IS NULL OR NOT ops.lc_promotion_observation_is_independent_current(observed.id,now_at) THEN RETURN NEW; END IF;
 SELECT * INTO provenance FROM core.fact_provenance p WHERE p.id=observed.provenance_id;
 IF provenance.source_kind='MANUAL_ENTRY' AND provenance.recorded_by_user_id=NEW.responsible_user_id THEN RETURN NEW; END IF;
 SELECT value INTO item FROM jsonb_array_elements(observed.context_snapshot)
  WHERE value#>>'{declaration,engagementKind}'=NEW.engagement_kind
    AND value#>>'{declaration,nativePromotionKey}'=NEW.native_promotion_key
    AND value->>'participationState'='PARTICIPATING'
    AND value->>'newTransactionsState'='OPEN'
    AND value->>'originalAuthorityReference'=NEW.original_authority_reference
    AND (value->>'originalAuthorityValidUntil')::timestamptz=NEW.original_authority_valid_until
    AND (value->>'originalAuthorityValidUntil')::timestamptz>now_at
    AND ops.lc_promotion_terms_digest(value->'declaration')=ops.lc_promotion_terms_digest(jsonb_build_object(
      'engagementKind',NEW.engagement_kind,'nativePromotionKey',NEW.native_promotion_key,'terms',NEW.terms,
      'priceFreeze',NEW.price_freeze,'autoParticipation',NEW.auto_participation,
      'termsEvidenceReference',NEW.terms_evidence_reference,'obligations',NEW.obligations));
 IF item IS NULL THEN RETURN NEW; END IF;
 context:=ops.lc_current_promotion_context(NEW.organization_id,NEW.platform_listing_id,
   (item->>'effectiveFrom')::timestamptz,(item->>'effectiveTo')::timestamptz,now_at);
 IF context->>'coverage'<>'QUALIFIED_COMPLETE' OR (context->>'observationId')::uuid<>observed.id THEN RETURN NEW; END IF;
 NEW.adoption_qualification_state:='QUALIFIED_CURRENT_STEWARDSHIP';
 NEW.axis_demands:=item->'axisDemands';
 RETURN NEW;
END $$;

CREATE FUNCTION ops.lc_recalculation_result_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'mart'
    AS $$
BEGIN
    IF TG_OP='UPDATE' AND OLD.state IN ('FINISHED','FAILED') THEN
        RAISE EXCEPTION 'terminal recalculation receipt is immutable' USING ERRCODE='MO105';
    END IF;
    IF TG_OP='UPDATE' AND OLD.lease_generation IS NOT NULL
       AND (NEW.lease_generation IS NULL OR NEW.lease_generation<OLD.lease_generation) THEN
        RAISE EXCEPTION 'recalculation generation cannot be erased or rewound' USING ERRCODE='MO105';
    END IF;
    IF NEW.state IN ('RUNNING','FINISHED','FAILED') AND NEW.lease_generation IS NULL THEN
        RAISE EXCEPTION 'managed recalculation state requires a lease generation' USING ERRCODE='MO105';
    END IF;
    IF NEW.state IN ('FINISHED','FAILED') AND (TG_OP<>'UPDATE' OR OLD.state<>'RUNNING'
       OR OLD.lease_generation IS NULL OR NEW.lease_generation IS DISTINCT FROM OLD.lease_generation
       OR OLD.leased_until IS NULL OR OLD.leased_until<=clock_timestamp()
       OR NEW.consumer_contract_version IS DISTINCT FROM OLD.consumer_contract_version) THEN
        RAISE EXCEPTION 'terminal recalculation receipt requires its current fenced claim' USING ERRCODE='MO105';
    END IF;
    IF NEW.lease_generation IS NOT NULL THEN
        IF (NEW.state='RUNNING') <> (NEW.leased_until IS NOT NULL) THEN
            RAISE EXCEPTION 'recalculation lease shape mismatch' USING ERRCODE='MO105';
        END IF;
        IF NEW.state='FINISHED' AND (NEW.consumer_contract_version IS DISTINCT FROM 1
           OR NEW.measurement_result_ids IS NULL OR NEW.binding_assessed_count IS NULL
           OR NEW.binding_invalidated_count IS NULL OR NEW.outcome_assessed_count IS NULL
           OR NEW.outcome_result_ids IS NULL) THEN
            RAISE EXCEPTION 'recalculation requires its complete consumer receipt' USING ERRCODE='MO105';
        END IF;
        IF NEW.state='FINISHED' AND NOT EXISTS (
            SELECT 1 FROM mart.lc_listing_health h
            JOIN mart.calculation_run r ON r.id=h.calculation_run_id
            WHERE h.id=NEW.health_result_id AND h.calculation_run_id=NEW.calculation_run_id
              AND h.organization_id=NEW.organization_id AND h.platform_listing_id=NEW.platform_listing_id
              AND r.organization_id=NEW.organization_id AND r.state='SUCCEEDED'
              AND h.computed_at>=NEW.started_at AND h.computed_at<=NEW.finished_at
        ) THEN
            RAISE EXCEPTION 'recalculation requires its actual listing result and calculation run' USING ERRCODE='MO105';
        END IF;
        IF NEW.state='FINISHED' THEN
            IF EXISTS (SELECT 1 FROM unnest(NEW.measurement_result_ids) result_id
                       WHERE NOT EXISTS (SELECT 1 FROM mart.lc_conversion_measurement m
                         WHERE m.id=result_id AND m.organization_id=NEW.organization_id
                           AND m.platform_listing_id=NEW.platform_listing_id
                           AND m.computed_at>=NEW.started_at AND m.computed_at<=NEW.finished_at)) THEN
                RAISE EXCEPTION 'recalculation measurement receipt is outside its fenced run' USING ERRCODE='MO105';
            END IF;
            IF EXISTS (SELECT 1 FROM unnest(NEW.outcome_result_ids) result_id
                       WHERE NOT EXISTS (SELECT 1 FROM ops.lc_node_result r
                         JOIN ops.lc_evaluation_plan p ON p.id=r.plan_id
                         JOIN ops.lc_action a ON a.id=p.action_id
                         WHERE r.id=result_id AND r.organization_id=NEW.organization_id
                           AND a.organization_id=NEW.organization_id
                           AND a.platform_listing_id=NEW.platform_listing_id
                           AND r.evaluated_at>=NEW.started_at AND r.evaluated_at<=NEW.finished_at)) THEN
                RAISE EXCEPTION 'recalculation outcome receipt is outside its fenced run' USING ERRCODE='MO105';
            END IF;
        END IF;
    END IF;
    RETURN NEW;
END $$;

CREATE FUNCTION ops.lc_response_value(p_document jsonb, p_pointer text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $_$
    SELECT CASE WHEN p_pointer='' THEN p_document
        WHEN p_pointer LIKE '/%' AND p_pointer !~ '~([^01]|$)'
            THEN ops.ad_json_value(p_document,p_pointer) ELSE NULL END
$_$;

CREATE FUNCTION ops.lc_restoration_intent_is_exact() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'core', 'pg_temp'
    AS $$
DECLARE source ops.lc_description_command%ROWTYPE;
BEGIN
    IF TG_OP='UPDATE' AND NEW.restores_command_id IS DISTINCT FROM OLD.restores_command_id THEN
        RAISE EXCEPTION 'the restoration source is immutable from preparation' USING ERRCODE='MO094';
    END IF;
    IF (SELECT r.proposed_parameters->>'restoresCommandId' FROM ops.recommendation r WHERE r.id=NEW.recommendation_id)
        IS DISTINCT FROM NEW.restores_command_id::text THEN
        RAISE EXCEPTION 'the proposal and exact restoration source must agree' USING ERRCODE='MO094';
    END IF;
    IF NEW.restores_command_id IS NULL THEN RETURN NEW; END IF;
    SELECT * INTO source FROM ops.lc_description_command WHERE id=NEW.restores_command_id;
    IF source.id IS NULL OR source.organization_id IS DISTINCT FROM NEW.organization_id
        OR source.platform_listing_id IS DISTINCT FROM NEW.platform_listing_id
        OR source.store_id IS DISTINCT FROM NEW.store_id OR source.action_id=NEW.id
        OR NEW.action_kind<>'LISTING_DESCRIPTION_CHANGE'
        OR source.prior_text IS NULL OR source.prior_text=''
        OR NEW.target_text IS DISTINCT FROM source.prior_text
        OR NEW.target_text_digest IS DISTINCT FROM encode(sha256(convert_to(source.prior_text,'UTF8')),'hex')
        OR NEW.current_text_digest IS DISTINCT FROM source.target_text_digest THEN
        RAISE EXCEPTION 'restoration must name the exact captured nonempty prior text of this listing' USING ERRCODE='MO094';
    END IF;
    IF TG_OP='INSERT' AND (NEW.state<>'DRAFT' OR source.state<>'READBACK_MATCHED'
        OR NOT EXISTS (SELECT 1 FROM ops.lc_execution_receipt r WHERE r.command_id=source.id
            AND r.execution_state='MANAGEMENT_VERIFIED')
        OR NOT EXISTS (SELECT 1 FROM ops.lc_action a WHERE a.id=source.action_id
            AND a.state IN ('VERIFIED','CONTAINED','CLOSED'))) THEN
        RAISE EXCEPTION 'restoration needs a new draft and a resolved exact source execution' USING ERRCODE='MO094';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.lc_restoration_preflight_version(p_command uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'raw', 'pg_temp'
    AS $$
    SELECT CASE WHEN a.outcome_class='ACCEPTED' AND a.fence_token=c.fence_token
        AND rb.match_state='MATCHES_PRIOR' AND r.response_complete
        AND r.identity_binding->>'qualified'='true'
        AND r.identity_binding->>'extent'='EXACT_NATIVE_OBJECT'
        AND r.identity_binding->>'nativeListingKey'=c.native_listing_key
        AND a.operation_snapshot #>> '{responseIdentity,commandId}'=c.id::text
        AND NOT EXISTS (SELECT 1 FROM ops.lc_description_command_attempt later
            WHERE later.command_id=c.id AND later.purpose IN ('APPLY','RESTORE') AND later.attempt_no>a.attempt_no)
        AND c.state IN ('READBACK_PENDING','EXECUTING') AND c.lease_expires_at>clock_timestamp()
        THEN nullif(r.version_token,'') END
      FROM ops.lc_description_command c JOIN ops.lc_action action ON action.id=c.action_id
      JOIN LATERAL (SELECT at.* FROM ops.lc_description_command_attempt at
          WHERE at.command_id=c.id AND at.purpose='READBACK' ORDER BY at.attempt_no DESC LIMIT 1) a ON true
      LEFT JOIN ops.lc_description_command_readback rb ON rb.attempt_id=a.id AND rb.command_id=c.id
      LEFT JOIN raw.lc_description_response_observation r ON r.id=rb.raw_observation_id AND r.id=a.raw_observation_id
     WHERE c.id=p_command AND action.restores_command_id IS NOT NULL;
$$;

CREATE FUNCTION ops.lc_restoration_proposal_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'core', 'pg_temp'
    AS $$
DECLARE source ops.lc_description_command%ROWTYPE;
BEGIN
    IF NEW.action_kind<>'LISTING_DESCRIPTION_CHANGE' THEN RETURN NEW; END IF;
    IF TG_OP='UPDATE' AND NEW.proposed_parameters->>'restoresCommandId' IS DISTINCT FROM OLD.proposed_parameters->>'restoresCommandId' THEN
        RAISE EXCEPTION 'restoration proposal source is immutable' USING ERRCODE='MO094';
    END IF;
    IF NEW.state NOT IN ('DRAFT','VALIDATED','READY_FOR_REVIEW','TASK_ONLY','APPROVED','POLICY_AUTHORIZED',
                        'COMMAND_CREATED','EXECUTION_TRACKING','OUTCOME_OBSERVATION') THEN RETURN NEW; END IF;
    -- Serialise both normal and restoration proposal creation on the same existing listing row.
    PERFORM 1 FROM core.platform_listing WHERE id=NEW.subject_id AND organization_id=NEW.organization_id FOR UPDATE;
    IF NEW.proposed_parameters ? 'restoresCommandId' THEN
        SELECT * INTO source FROM ops.lc_description_command WHERE id=(NEW.proposed_parameters->>'restoresCommandId')::uuid;
        IF source.id IS NULL OR source.organization_id IS DISTINCT FROM NEW.organization_id
            OR source.platform_listing_id IS DISTINCT FROM NEW.subject_id OR source.store_id IS DISTINCT FROM NEW.store_id
            OR source.state<>'READBACK_MATCHED' OR source.prior_text IS NULL OR source.prior_text=''
            OR NOT EXISTS (SELECT 1 FROM ops.lc_execution_receipt r WHERE r.command_id=source.id AND r.execution_state='MANAGEMENT_VERIFIED')
            OR NOT EXISTS (SELECT 1 FROM ops.lc_action a WHERE a.id=source.action_id AND a.state IN ('VERIFIED','CONTAINED','CLOSED')) THEN
            RAISE EXCEPTION 'restoration proposal needs the resolved exact source of this listing' USING ERRCODE='MO094';
        END IF;
    END IF;
    IF EXISTS (SELECT 1 FROM ops.recommendation other WHERE other.id<>NEW.id
        AND other.subject_kind=NEW.subject_kind AND other.subject_id=NEW.subject_id AND other.action_kind=NEW.action_kind
        AND other.state IN ('DRAFT','VALIDATED','READY_FOR_REVIEW','TASK_ONLY','APPROVED','POLICY_AUTHORIZED',
                            'COMMAND_CREATED','EXECUTION_TRACKING','OUTCOME_OBSERVATION')
        AND other.id IS DISTINCT FROM source.recommendation_id
        AND NOT EXISTS (SELECT 1 FROM ops.lc_description_command own_source
            WHERE own_source.recommendation_id=NEW.id AND own_source.id::text=other.proposed_parameters->>'restoresCommandId')) THEN
        RAISE EXCEPTION 'another live listing change already owns this scope' USING ERRCODE='23505';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.lc_review_attests_frozen_plan() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE plan ops.lc_evaluation_plan%ROWTYPE; action ops.lc_action%ROWTYPE; purpose text; expected_digest text;
BEGIN
 IF NEW.verdict<>'ATTESTED' THEN RETURN NEW; END IF;
 SELECT * INTO action FROM ops.lc_action WHERE id=NEW.action_id;
 SELECT r.proposed_parameters->>'purposeCode' INTO purpose FROM ops.recommendation r WHERE r.id=action.recommendation_id;
 IF purpose IN ('DESCRIPTION_CORRECTION','BOUNDED_EXPLORATION') THEN
   expected_digest:=ops.lc_purpose_basis_digest(purpose,action.purpose_basis);
   IF expected_digest IS NULL OR action.created_at>NEW.reviewed_at OR action.organization_id<>NEW.organization_id
      OR NEW.evaluation_plan_digest IS NOT NULL
      OR (NEW.purpose_basis_digest IS NOT NULL AND NEW.purpose_basis_digest<>expected_digest)
      OR (action.purpose_basis->>'useUntil')::timestamptz<=NEW.reviewed_at THEN
     RAISE EXCEPTION 'Review requires the exact current nonformal use basis' USING ERRCODE='MO092';
   END IF;
   NEW.purpose_basis_digest:=expected_digest;
   RETURN NEW;
 END IF;
 SELECT * INTO plan FROM ops.lc_evaluation_plan WHERE action_id=NEW.action_id;
 IF NOT FOUND OR plan.organization_id<>NEW.organization_id OR plan.frozen_at>NEW.reviewed_at
    OR (NEW.evaluation_plan_digest IS NOT NULL AND NEW.evaluation_plan_digest<>plan.plan_digest) THEN
   RAISE EXCEPTION 'review must attest the exact plan frozen before it' USING ERRCODE='MO092';
 END IF;
 NEW.evaluation_plan_digest:=plan.plan_digest;
 RETURN NEW;
END $$;

CREATE FUNCTION ops.lc_review_classification_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a ops.lc_action%ROWTYPE; meaning boolean;
BEGIN
 IF NEW.verdict<>'ATTESTED' THEN RETURN NEW; END IF;
 SELECT * INTO a FROM ops.lc_action WHERE id=NEW.action_id;
 meaning:=ops.lc_review_meaning_axis(a.id,NEW.meaning_assessment);
 IF meaning IS NULL OR NEW.content_axis_material IS DISTINCT FROM meaning OR NEW.exposure_axis_material IS NULL
    OR NEW.content_axis_material IS DISTINCT FROM a.content_axis_material
    OR NEW.exposure_axis_material IS DISTINCT FROM a.exposure_axis_material
    OR NEW.materiality_route IS DISTINCT FROM a.materiality_route
    OR NEW.materiality_route IS DISTINCT FROM (CASE WHEN meaning OR NEW.exposure_axis_material
        THEN 'MATERIAL_IMPACT' ELSE 'ORDINARY_IMPACT' END)
    OR NEW.exposure_evidence->>'state' IS DISTINCT FROM 'QUALIFIED' THEN
  RAISE EXCEPTION 'review requires exact structured meaning and qualified exposure' USING ERRCODE='MO107';
 END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION ops.lc_review_meaning_axis(p_action uuid, assessment jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE catalog jsonb; answer jsonb; ordinary boolean:=false; material boolean:=false; unknown boolean:=false;
 code text; codes text[]:='{}'; category text;
BEGIN
 SELECT core.lc_meaning_catalog(a.calibration_package_id,a.action_kind) INTO catalog FROM ops.lc_action a WHERE a.id=p_action;
 IF catalog IS NULL OR jsonb_typeof(assessment) IS DISTINCT FROM 'object' THEN RETURN NULL; END IF;
 IF assessment->>'model' IS DISTINCT FROM 'LC_MEANING_REVIEW_1'
    OR assessment->'complete' IS DISTINCT FROM 'true'::jsonb
    OR assessment->>'basisDigest' IS DISTINCT FROM ops.lc_meaning_review_basis_digest(p_action)
    OR jsonb_typeof(assessment->'evidenceReference') IS DISTINCT FROM 'string'
    OR length(btrim(assessment->>'evidenceReference')) NOT BETWEEN 1 AND 512
    OR jsonb_typeof(assessment->'answers') IS DISTINCT FROM 'array'
    OR EXISTS(SELECT 1 FROM jsonb_object_keys(assessment) k WHERE k NOT IN
        ('model','complete','basisDigest','evidenceReference','answers')) THEN RETURN NULL; END IF;
 IF jsonb_array_length(assessment->'answers')<>jsonb_array_length(catalog) THEN RETURN NULL; END IF;
 FOR answer IN SELECT value FROM jsonb_array_elements(assessment->'answers') LOOP
  IF jsonb_typeof(answer) IS DISTINCT FROM 'object' THEN RETURN NULL; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(answer) k WHERE k NOT IN ('code','state','reason'))
     OR coalesce(answer->>'state','') NOT IN ('APPLIES','DOES_NOT_APPLY','UNKNOWN')
     OR jsonb_typeof(answer->'reason') IS DISTINCT FROM 'string'
     OR length(btrim(answer->>'reason')) NOT BETWEEN 1 AND 2000 THEN RETURN NULL; END IF;
  code:=answer->>'code';
  IF code IS NULL OR code=ANY(codes) THEN RETURN NULL; END IF;
  SELECT r->>'axis' INTO category FROM jsonb_array_elements(catalog) r WHERE r->>'code'=code;
  IF NOT FOUND THEN RETURN NULL; END IF;
  codes:=array_append(codes,code);
  IF answer->>'state'='UNKNOWN' THEN unknown:=true; END IF;
  IF answer->>'state'='APPLIES' THEN
   IF category='MATERIAL' THEN material:=true; ELSE ordinary:=true; END IF;
  END IF;
 END LOOP;
 IF unknown THEN RETURN NULL; END IF;
 IF material THEN RETURN true; END IF;
 IF ordinary THEN RETURN false; END IF;
 RETURN NULL;
END $$;

CREATE FUNCTION ops.lc_reviewed_classification_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF OLD.state<>'DRAFT' AND (NEW.content_axis_material IS DISTINCT FROM OLD.content_axis_material
    OR NEW.exposure_axis_material IS DISTINCT FROM OLD.exposure_axis_material
    OR NEW.materiality_route IS DISTINCT FROM OLD.materiality_route) THEN
  RAISE EXCEPTION 'reviewed classification is immutable' USING ERRCODE='MO107';
 END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION ops.lc_scope_contained(p_org uuid, p_listing uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT ops.lc_scope_contained_v0117(p_org,p_listing) OR EXISTS(
   SELECT 1 FROM ops.lc_shared_isolation_scope(p_org,NULL) scope
    WHERE scope.platform_listing_id=p_listing AND scope.root_listing_id<>p_listing)
$$;

CREATE FUNCTION ops.lc_scope_contained_v0077(p_org uuid, p_listing uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'core', 'pg_temp'
    AS $$
    SELECT EXISTS (
        SELECT 1
          FROM ops.lc_containment c
          JOIN core.platform_listing l ON l.id = p_listing AND l.organization_id = p_org
         WHERE c.organization_id = p_org AND c.state = 'ACTIVE'
           AND ((c.scope_kind = 'ORGANIZATION')
             OR (c.scope_kind = 'PLATFORM' AND c.platform_code = l.platform_code)
             OR (c.scope_kind = 'STORE' AND c.store_id = l.store_id)
             OR (c.scope_kind = 'LISTING' AND c.platform_listing_id = l.id)
             OR (c.scope_kind = 'BATCH' AND EXISTS (
                    SELECT 1 FROM ops.lc_batch_member m
                      JOIN ops.lc_action a ON a.id = m.action_id
                     WHERE m.batch_id = c.batch_id AND a.platform_listing_id = l.id
                       AND m.sequence_no = (SELECT max(latest.sequence_no) FROM ops.lc_batch_member latest
                                             WHERE latest.batch_id = m.batch_id AND latest.action_id = m.action_id)
                       AND m.membership_state = 'ACTIVE'))))
$$;

CREATE FUNCTION ops.lc_scope_contained_v0117(p_org uuid, p_listing uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT ops.lc_scope_contained_v0077(p_org,p_listing)
    OR cardinality(ops.lc_unreleased_outcome_failures(p_org,p_listing))>0
$$;

CREATE FUNCTION ops.lc_select_description_response(p_document jsonb, p_shape jsonb, p_purpose text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE
    descriptor jsonb := p_shape->'operation'->'description_response_binding';
    identity jsonb := p_shape->'responseIdentity'; payload jsonb; item jsonb; value jsonb;
    selected jsonb; matches integer := 0; mode text; task_value jsonb;
BEGIN
    IF descriptor->>'schema' IS DISTINCT FROM 'DESCRIPTION_RESPONSE_IDENTITY_V1'
        OR nullif(descriptor->>'evidenceRef','') IS NULL
        OR descriptor->>'evidenceRef' IS DISTINCT FROM p_shape->'operation'->>'evidence_ref'
        OR p_shape->'operation'->>'verification_state' IS DISTINCT FROM 'VERIFIED' THEN
        RETURN jsonb_build_object('qualified',false,'gap','RESPONSE_BINDING_UNVERIFIED');
    END IF;
    mode := descriptor->>'mode';
    -- A task receipt is acceptance only, never proof of applied content.
    IF mode='TASK_ACCEPTANCE_ONLY' THEN
        IF p_purpose NOT IN ('APPLY','RESTORE') OR p_shape->>'writeResultModel' IS DISTINCT FROM 'ASYNCHRONOUS_TASK'
            OR jsonb_typeof(p_document) IS DISTINCT FROM 'object' THEN
            RETURN jsonb_build_object('qualified',false,'gap','TASK_RECEIPT_PURPOSE_MISMATCH');
        END IF;
        RETURN jsonb_build_object('qualified',true,'extent','TASK_ACCEPTANCE_ONLY','payload',p_document);
    END IF;
    IF mode IS DISTINCT FROM 'EXACT_OBJECT' OR nullif(identity->>'nativeListingKey','') IS NULL
        OR descriptor->>'listingKeyType' NOT IN ('string','number')
        OR descriptor->>'listingKeyType' IS NULL THEN
        RETURN jsonb_build_object('qualified',false,'gap','NATIVE_IDENTITY_UNBOUND');
    END IF;
    IF p_purpose='STATUS_ENQUIRY' THEN
        IF descriptor->>'statusValueType' IS NULL OR descriptor->>'statusValueType' NOT IN ('string','number')
            OR nullif(p_shape->'operation'->>'task_success_value','') IS NULL
            OR nullif(p_shape->'operation'->>'task_failure_value','') IS NULL
            OR p_shape->'operation'->>'task_success_value'=p_shape->'operation'->>'task_failure_value'
            OR (p_shape->'operation'->'task_pending_values') ? (p_shape->'operation'->>'task_success_value')
            OR (p_shape->'operation'->'task_pending_values') ? (p_shape->'operation'->>'task_failure_value') THEN
            RETURN jsonb_build_object('qualified',false,'gap','TASK_STATUS_SCHEMA_UNQUALIFIED');
        END IF;
        IF descriptor->>'taskBindingMethod'='REQUEST_UNIQUE' THEN
            IF p_shape->'queryIdentity'->>'method' IS DISTINCT FROM 'REQUEST_UNIQUE'
                OR p_shape->'queryIdentity'->'task' IS DISTINCT FROM identity->'task'
                OR nullif(identity->'task'->>'nativeTaskKey','') IS NULL
                OR p_shape->'queryIdentity'->>'operationSnapshotSha256' IS DISTINCT FROM
                    encode(sha256(convert_to((p_shape-'queryIdentity')::text,'UTF8')),'hex') THEN
                RETURN jsonb_build_object('qualified',false,'gap','EXACT_TASK_QUERY_EVIDENCE_MISSING');
            END IF;
        ELSE
        task_value := ops.lc_response_value(p_document,descriptor->>'taskEchoPointer');
        IF nullif(identity->'task'->>'nativeTaskKey','') IS NULL
            OR jsonb_typeof(task_value) NOT IN ('string','number') OR task_value IS NULL
            OR task_value #>> '{}' IS DISTINCT FROM identity->'task'->>'nativeTaskKey' THEN
            RETURN jsonb_build_object('qualified',false,'gap','NATIVE_TASK_RELATION_UNPROVED');
        END IF;
        END IF;
    END IF;
    payload := ops.lc_response_value(p_document,descriptor->>'payloadPointer');
    IF descriptor->>'selection'='OBJECT' AND jsonb_typeof(payload)='object' THEN
        payload := jsonb_build_array(payload);
    ELSIF descriptor->>'selection' IS DISTINCT FROM 'ITEMS' OR jsonb_typeof(payload) IS DISTINCT FROM 'array' THEN
        RETURN jsonb_build_object('qualified',false,'gap','RESPONSE_COLLECTION_SHAPE_UNKNOWN');
    END IF;
    FOR item IN SELECT * FROM jsonb_array_elements(payload) LOOP
        IF jsonb_typeof(item) IS DISTINCT FROM 'object' THEN
            RETURN jsonb_build_object('qualified',false,'gap','RESPONSE_ITEM_SHAPE_UNKNOWN');
        END IF;
        value := ops.lc_response_value(item,descriptor->>'listingKeyPointer');
        IF jsonb_typeof(value) IS DISTINCT FROM descriptor->>'listingKeyType' THEN
            RETURN jsonb_build_object('qualified',false,'gap','NATIVE_IDENTITY_TYPE_UNKNOWN');
        END IF;
        IF value #>> '{}' = identity->>'nativeListingKey' THEN
            matches := matches+1; selected := item;
        END IF;
    END LOOP;
    IF matches<>1 THEN
        RETURN jsonb_build_object('qualified',false,'gap','EXACTLY_ONE_NATIVE_OBJECT_REQUIRED','matchingItems',matches);
    END IF;
    RETURN jsonb_build_object('qualified',true,'extent','EXACT_NATIVE_OBJECT','payload',selected,
        'nativeListingKey',identity->>'nativeListingKey','task',identity->'task','matchingItems',matches,
        'taskQueryBinding',p_shape->'queryIdentity');
END;
$$;

CREATE FUNCTION ops.lc_shared_containment_has_current_cause() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NEW.cause_class='SHARED_VERSION' AND NOT EXISTS(
   SELECT 1 FROM core.platform_listing listing
   JOIN ops.lc_isolation_dependency dependency
     ON dependency.organization_id=listing.organization_id
    AND dependency.from_listing_id=listing.id
    AND dependency.proof_reference=NEW.evidence_reference
   WHERE listing.organization_id=NEW.organization_id
     AND (NEW.scope_kind='ORGANIZATION'
       OR (NEW.scope_kind='PLATFORM' AND NEW.platform_code=listing.platform_code)
       OR (NEW.scope_kind='STORE' AND NEW.store_id=listing.store_id)
       OR (NEW.scope_kind='LISTING' AND NEW.platform_listing_id=listing.id)
       OR (NEW.scope_kind='BATCH' AND EXISTS(SELECT 1 FROM ops.lc_batch_member member
          JOIN ops.lc_action action ON action.id=member.action_id
          WHERE member.batch_id=NEW.batch_id AND action.platform_listing_id=listing.id
            AND member.sequence_no=(SELECT max(latest.sequence_no) FROM ops.lc_batch_member latest
              WHERE latest.batch_id=member.batch_id AND latest.action_id=member.action_id)
            AND member.membership_state='ACTIVE')))
     AND ops.lc_listing_uses_isolation_dependency(NEW.organization_id,listing.id,
           dependency.dependency_kind,dependency.proof_reference,NEW.stopped_at)
     AND ops.lc_listing_uses_isolation_dependency(NEW.organization_id,dependency.to_listing_id,
           dependency.dependency_kind,dependency.proof_reference,NEW.stopped_at)) THEN
   RAISE EXCEPTION 'shared containment requires a retained dependency and current exact cause on both Listings'
     USING ERRCODE='MO092';
 END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION ops.lc_shared_isolation_scope(p_org uuid, p_source uuid) RETURNS TABLE(root_listing_id uuid, platform_listing_id uuid)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 WITH RECURSIVE direct_causes(root_listing_id,dependency_kind,proof_reference) AS (
   SELECT DISTINCT listing.id,d.dependency_kind,c.evidence_reference
   FROM ops.lc_containment c JOIN core.platform_listing listing ON listing.organization_id=c.organization_id
   JOIN ops.lc_isolation_dependency d ON d.organization_id=c.organization_id
      AND d.from_listing_id=listing.id AND d.proof_reference=c.evidence_reference
   WHERE c.organization_id=p_org AND c.state='ACTIVE' AND c.cause_class='SHARED_VERSION'
     AND (p_source IS NULL OR listing.id=p_source)
     AND (c.scope_kind='ORGANIZATION'
       OR (c.scope_kind='PLATFORM' AND c.platform_code=listing.platform_code)
       OR (c.scope_kind='STORE' AND c.store_id=listing.store_id)
       OR (c.scope_kind='LISTING' AND c.platform_listing_id=listing.id)
       OR (c.scope_kind='BATCH' AND EXISTS(SELECT 1 FROM ops.lc_batch_member member
          JOIN ops.lc_action action ON action.id=member.action_id
          WHERE member.batch_id=c.batch_id AND action.platform_listing_id=listing.id
            AND member.sequence_no=(SELECT max(latest.sequence_no) FROM ops.lc_batch_member latest
              WHERE latest.batch_id=member.batch_id AND latest.action_id=member.action_id)
            AND member.membership_state='ACTIVE')))
 ), walk(root_listing_id,platform_listing_id,dependency_kind,proof_reference) AS (
   SELECT root_listing_id,root_listing_id,dependency_kind,proof_reference
     FROM direct_causes
   UNION
   SELECT walk.root_listing_id,d.to_listing_id,walk.dependency_kind,walk.proof_reference
     FROM walk JOIN ops.lc_isolation_dependency d ON d.organization_id=p_org
       AND d.from_listing_id=walk.platform_listing_id
       AND d.dependency_kind=walk.dependency_kind AND d.proof_reference=walk.proof_reference
    WHERE ops.lc_listing_uses_isolation_dependency(p_org,d.to_listing_id,d.dependency_kind,
            d.proof_reference,statement_timestamp())
 )
 SELECT DISTINCT walk.root_listing_id,walk.platform_listing_id FROM walk
$$;

CREATE FUNCTION ops.lc_stamp_guardrail_transaction() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM ops.recommendation r WHERE r.id=NEW.recommendation_id
     AND r.organization_id=NEW.organization_id
     AND r.action_kind IN ('LISTING_DESCRIPTION_CHANGE','LISTING_PROMOTION_ACTION')) THEN
  NEW.listing_transaction_id:=txid_current();
 ELSE
  NEW.listing_transaction_id:=NULL;
 END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION ops.lc_task_deferral_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops'
    AS $_$
DECLARE binding ops.lc_task_responsibility%ROWTYPE; task ops.work_task%ROWTYPE; limit_value jsonb;
BEGIN
    IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Task deferral history cannot be deleted' USING ERRCODE='23514'; END IF;
    SELECT * INTO binding FROM ops.lc_task_responsibility WHERE task_id=NEW.task_id;
    SELECT * INTO task FROM ops.work_task WHERE id=NEW.task_id;
    IF NEW.review_queue_id IS NOT NULL AND (NEW.state<>'EXPIRED' OR NOT EXISTS(
        SELECT 1 FROM ops.lc_recalculation_queue q LEFT JOIN ops.lc_action a ON a.recommendation_id=binding.recommendation_id
        WHERE q.id=NEW.review_queue_id AND q.organization_id=NEW.organization_id
          AND q.platform_listing_id=coalesce(binding.platform_listing_id,a.platform_listing_id)
          AND q.trigger_reference='task-deferral-expired:'||NEW.id::text AND q.source_time=NEW.expires_at)) THEN
        RAISE EXCEPTION 'Expired deferral requires its exact scoped queue request' USING ERRCODE='23514';
    END IF;
    IF NEW.review_health_id IS NOT NULL AND NOT EXISTS(
        SELECT 1 FROM mart.lc_listing_health h LEFT JOIN ops.lc_action a ON a.recommendation_id=binding.recommendation_id
        WHERE h.id=NEW.review_health_id AND h.organization_id=NEW.organization_id
          AND h.platform_listing_id=coalesce(binding.platform_listing_id,a.platform_listing_id)
          AND h.computed_at>=coalesce(NEW.ended_at,NEW.requested_at)) THEN
        RAISE EXCEPTION 'Deferral review must name a subsequent diagnosis in its own scope' USING ERRCODE='23514';
    END IF;
    IF TG_OP='INSERT' THEN
        limit_value:=CASE WHEN binding.responsibility_lane='NECESSARY_RISK'
                         THEN binding.slo_snapshot#>'{necessaryRisk,maximumDeferMinutes}'
                         ELSE binding.slo_snapshot->'maximumDeferMinutes' END;
        IF binding.task_id IS NULL OR binding.organization_id<>NEW.organization_id
           OR task.state NOT IN ('OPEN','ASSIGNED','IN_PROGRESS') OR NEW.state<>'ACTIVE'
           OR NEW.requested_at<binding.first_raised_at OR NEW.requested_at>clock_timestamp()
           OR NEW.expires_at<>NEW.requested_at+make_interval(mins=>NEW.defer_minutes)
           OR NEW.review_health_id IS NOT NULL OR NEW.review_queue_id IS NOT NULL OR NEW.ended_at IS NOT NULL
           OR NEW.basis_digest IS DISTINCT FROM ops.lc_task_reassessment_basis(NEW.task_id)
           OR jsonb_typeof(limit_value) IS DISTINCT FROM 'number' THEN
            RAISE EXCEPTION 'Deferral requires original Task policy and current diagnosis' USING ERRCODE='23514';
        END IF;
        IF limit_value::text !~ '^[0-9]+$' OR (limit_value::text)::numeric<NEW.defer_minutes
           OR (limit_value::text)::numeric>2147483647 THEN
            RAISE EXCEPTION 'Deferral exceeds the declared finite policy' USING ERRCODE='23514';
        END IF;
    ELSE
        IF (to_jsonb(NEW)-ARRAY['state','ended_at','review_health_id','review_queue_id'])
             IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','ended_at','review_health_id','review_queue_id'])
           OR (OLD.state<>'ACTIVE' AND (NEW.state<>OLD.state OR NEW.ended_at IS DISTINCT FROM OLD.ended_at))
           OR (OLD.review_health_id IS NOT NULL AND NEW.review_health_id IS DISTINCT FROM OLD.review_health_id)
           OR (OLD.review_queue_id IS NOT NULL AND NEW.review_queue_id IS DISTINCT FROM OLD.review_queue_id)
           OR (OLD.state='ACTIVE' AND NEW.state='ACTIVE') THEN
            RAISE EXCEPTION 'Deferral origin and finite deadline cannot restart' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NEW;
END $_$;

CREATE FUNCTION ops.lc_task_deferral_review_required() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
BEGIN
    IF EXISTS(SELECT 1 FROM ops.lc_task_deferral d WHERE d.id=NEW.id AND d.state='EXPIRED'
              AND d.review_health_id IS NULL AND d.review_queue_id IS NULL) THEN
        RAISE EXCEPTION 'Deferral expiry and its review request must commit together' USING ERRCODE='23514';
    END IF;
    RETURN NULL;
END $$;

CREATE FUNCTION ops.lc_task_dependency_hold_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops'
    AS $_$
DECLARE binding ops.lc_task_responsibility%ROWTYPE; held ops.work_task%ROWTYPE;
        dependency ops.work_task%ROWTYPE; evidence ops.lc_collaboration_link%ROWTYPE;
        limit_value jsonb; used_minutes bigint; listing_id uuid;
BEGIN
    IF TG_OP='DELETE' THEN
        RAISE EXCEPTION 'Task dependency hold history cannot be deleted' USING ERRCODE='23514';
    END IF;
    SELECT * INTO binding FROM ops.lc_task_responsibility WHERE task_id=NEW.task_id;
    IF TG_OP='INSERT' THEN
        PERFORM id FROM ops.work_task WHERE id IN (NEW.task_id,NEW.dependency_task_id)
          ORDER BY id FOR UPDATE;
        SELECT * INTO held FROM ops.work_task WHERE id=NEW.task_id;
        SELECT * INTO dependency FROM ops.work_task WHERE id=NEW.dependency_task_id;
        SELECT * INTO evidence FROM ops.lc_collaboration_link WHERE id=NEW.collaboration_link_id;
        SELECT coalesce(binding.platform_listing_id,(SELECT a.platform_listing_id FROM ops.lc_action a
          WHERE a.recommendation_id=binding.recommendation_id ORDER BY a.id LIMIT 1)) INTO listing_id;
        limit_value:=CASE WHEN binding.responsibility_lane='NECESSARY_RISK'
            THEN binding.slo_snapshot#>'{necessaryRisk,maximumDeferMinutes}'
            ELSE binding.slo_snapshot->'maximumDeferMinutes' END;
        SELECT coalesce(sum(h.hold_minutes),0) INTO used_minutes
          FROM ops.lc_task_dependency_hold h WHERE h.task_id=NEW.task_id;
        IF binding.task_id IS NULL OR held.organization_id<>NEW.organization_id
           OR dependency.organization_id<>NEW.organization_id
           OR evidence.id IS NULL OR evidence.organization_id<>NEW.organization_id
           OR evidence.platform_listing_id<>listing_id OR evidence.task_id<>NEW.dependency_task_id
           OR evidence.link_kind<>'DEPENDENCY_REEVALUATION'
           OR evidence.evidence_reference<>NEW.evidence_reference
           OR evidence.recorded_at>NEW.started_at
           OR (evidence.source_time IS NOT NULL AND evidence.source_time>NEW.started_at)
           OR held.state NOT IN ('OPEN','ASSIGNED','IN_PROGRESS')
           OR dependency.state NOT IN ('OPEN','ASSIGNED','IN_PROGRESS') OR NEW.state<>'ACTIVE'
           OR NEW.started_at<binding.first_raised_at OR NEW.started_at>clock_timestamp()
           OR NEW.expires_at<>NEW.started_at+make_interval(mins=>NEW.hold_minutes)
           OR binding.action_due_at IS NULL OR NEW.started_at>=binding.action_due_at
           OR NEW.ended_at IS NOT NULL OR NEW.end_reason IS NOT NULL OR NEW.review_queue_id IS NOT NULL
           OR jsonb_typeof(limit_value) IS DISTINCT FROM 'number'
           OR limit_value::text !~ '^[0-9]+$' OR used_minutes+NEW.hold_minutes>(limit_value::text)::numeric
           OR (limit_value::text)::numeric>2147483647 THEN
            RAISE EXCEPTION 'dependency hold requires open scoped Tasks and the original finite policy' USING ERRCODE='23514';
        END IF;
        IF EXISTS(WITH RECURSIVE path(task_id) AS (
              SELECT NEW.dependency_task_id UNION
              SELECT h.dependency_task_id FROM ops.lc_task_dependency_hold h JOIN path p ON h.task_id=p.task_id
                WHERE h.state='ACTIVE') SELECT 1 FROM path WHERE task_id=NEW.task_id) THEN
            RAISE EXCEPTION 'dependency holds cannot create a cycle' USING ERRCODE='23514';
        END IF;
        IF EXISTS(SELECT 1 FROM ops.work_task_event e WHERE e.task_id=NEW.task_id
            AND e.event_kind='ACTION_RECORDED' AND e.occurred_at>=binding.first_raised_at) THEN
            RAISE EXCEPTION 'completed action work cannot be paused afterwards' USING ERRCODE='23514';
        END IF;
    ELSE
        SELECT coalesce(binding.platform_listing_id,(SELECT a.platform_listing_id FROM ops.lc_action a
          WHERE a.recommendation_id=binding.recommendation_id ORDER BY a.id LIMIT 1)) INTO listing_id;
        IF NEW.review_queue_id IS NULL OR NOT EXISTS(
              SELECT 1 FROM ops.lc_recalculation_queue q WHERE q.id=NEW.review_queue_id
                AND q.organization_id=NEW.organization_id AND q.platform_listing_id=listing_id
                AND q.trigger_class=CASE WHEN binding.responsibility_lane='NECESSARY_RISK' THEN 'RISK' ELSE 'ORDINARY' END
                AND q.trigger_reference='task-dependency-hold:'||NEW.id::text||':'||lower(NEW.state)
                AND q.source_time=NEW.ended_at)
           OR (to_jsonb(NEW)-ARRAY['state','ended_at','end_reason','review_queue_id']) IS DISTINCT FROM
             (to_jsonb(OLD)-ARRAY['state','ended_at','end_reason','review_queue_id'])
           OR OLD.state<>'ACTIVE' OR NEW.state='ACTIVE' OR NEW.ended_at IS NULL OR NEW.end_reason IS NULL THEN
            RAISE EXCEPTION 'dependency hold origin and finite deadline are immutable' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NEW;
END $_$;

CREATE FUNCTION ops.lc_task_reassessment_basis(p_task uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'ops', 'mart'
    AS $$
    SELECT encode(sha256(convert_to(jsonb_build_object(
        'scope',h.affected_set_id,'necessary',h.necessary_conditions,'eligibility',h.eligibility)::text,'UTF8')),'hex')
    FROM ops.lc_task_responsibility b LEFT JOIN ops.lc_action a ON a.recommendation_id=b.recommendation_id
    JOIN LATERAL (SELECT * FROM mart.lc_listing_health h
        WHERE h.platform_listing_id=coalesce(b.platform_listing_id,a.platform_listing_id)
          AND h.computed_at<=clock_timestamp() ORDER BY h.health_version DESC LIMIT 1) h ON true
    WHERE b.task_id=p_task;
$$;

CREATE FUNCTION ops.lc_task_responsibility_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'core'
    AS $$
DECLARE task ops.work_task%ROWTYPE; action ops.lc_action%ROWTYPE; health mart.lc_listing_health%ROWTYPE;
        expected_slo jsonb; expected_coverage jsonb; opportunity boolean;
BEGIN
    IF TG_OP<>'INSERT' THEN
        RAISE EXCEPTION 'Listing responsibility origins and policy snapshots are immutable' USING ERRCODE='23514';
    END IF;
    SELECT * INTO task FROM ops.work_task WHERE id=NEW.task_id;
    IF task.id IS NULL OR task.organization_id<>NEW.organization_id
       OR task.recommendation_id IS DISTINCT FROM NEW.recommendation_id OR task.created_at<>NEW.first_raised_at
       OR task.due_at IS DISTINCT FROM NEW.action_due_at THEN
        RAISE EXCEPTION 'Listing responsibility does not match its original Task' USING ERRCODE='23514';
    END IF;
    IF NEW.source_health_id IS NULL THEN
        SELECT * INTO action FROM ops.lc_action WHERE recommendation_id=NEW.recommendation_id;
        IF action.id IS NULL OR action.organization_id<>NEW.organization_id
           OR action.calibration_package_id IS DISTINCT FROM NEW.calibration_package_id
           OR action.calibration_version IS DISTINCT FROM NEW.calibration_version THEN
            RAISE EXCEPTION 'Listing responsibility does not match its original Action' USING ERRCODE='23514';
        END IF;
    ELSE
        SELECT * INTO health FROM mart.lc_listing_health WHERE id=NEW.source_health_id;
        opportunity:=NEW.cause_code IN ('DESCRIPTION_NOT_RUSSIAN','KIZ_MARKING_UNDECLARED',
            'SOURCE_STRATIFICATION_MISSING','NOT_SELLABLE_AT_LAST_OBSERVATION','FEEDBACK_THEMES_PRESENT');
        IF health.id IS NULL OR health.organization_id<>NEW.organization_id
           OR health.platform_listing_id<>NEW.platform_listing_id OR NEW.recommendation_id IS NOT NULL
           OR (NOT opportunity AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(health.necessary_conditions) condition
                 WHERE condition->>'code'=NEW.cause_code AND condition->>'state'='FAIL'))
           OR (opportunity AND (health.necessary_state<>'PASS' OR health.eligibility->>'EVALUATION'<>'ELIGIBLE'
                 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(health.opportunities) item
                    WHERE item->>'code'=NEW.cause_code)))
           OR EXISTS(SELECT 1 FROM mart.lc_listing_health newer WHERE newer.platform_listing_id=health.platform_listing_id
                AND newer.health_version>health.health_version) THEN
            RAISE EXCEPTION 'Listing responsibility requires its current qualified diagnosis' USING ERRCODE='23514';
        END IF;
        IF NOT EXISTS(SELECT 1 FROM core.platform_listing listing
            CROSS JOIN LATERAL core.lc_resolve_calibration_for(NEW.organization_id,listing.platform_code,
                listing.store_id,health.computed_at,'LISTING_CONVERSION') resolved
            WHERE listing.id=NEW.platform_listing_id
              AND (CASE WHEN resolved.resolution_state='RESOLVED' THEN resolved.package_id END)
                    IS NOT DISTINCT FROM NEW.calibration_package_id
              AND (CASE WHEN resolved.resolution_state='RESOLVED' THEN resolved.package_version END)
                    IS NOT DISTINCT FROM NEW.calibration_version) THEN
            RAISE EXCEPTION 'Listing responsibility calibration identity mismatch' USING ERRCODE='23514';
        END IF;
    END IF;
    SELECT value_json INTO expected_slo FROM core.lc_calibration_value
      WHERE package_id=NEW.calibration_package_id AND category_code='RESPONSIBILITY_SLO';
    SELECT value_json INTO expected_coverage FROM core.lc_calibration_value
      WHERE package_id=NEW.calibration_package_id AND category_code='RESPONSIBILITY_COVERAGE';
    IF jsonb_typeof(expected_slo) IS DISTINCT FROM 'object' THEN expected_slo:='{}'::jsonb; END IF;
    IF jsonb_typeof(expected_coverage) IS DISTINCT FROM 'object' THEN expected_coverage:='{}'::jsonb; END IF;
    IF NEW.slo_snapshot<>expected_slo OR NEW.coverage_snapshot<>expected_coverage THEN
        RAISE EXCEPTION 'Listing responsibility cannot substitute calibration values' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END $$;

CREATE FUNCTION ops.lc_unreleased_outcome_failures(p_org uuid, p_listing uuid) RETURNS uuid[]
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT coalesce(array_agg(r.id ORDER BY r.evaluated_at,r.id),'{}'::uuid[])
 FROM ops.lc_node_result r JOIN ops.lc_evaluation_plan p ON p.id=r.plan_id
 JOIN ops.lc_action a ON a.id=p.action_id
 WHERE r.organization_id=p_org AND a.platform_listing_id=p_listing AND r.protection_verdict='FAIL'
  AND NOT EXISTS(SELECT 1 FROM ops.lc_containment c WHERE c.organization_id=p_org
    AND c.scope_kind='LISTING' AND c.platform_listing_id=p_listing AND c.state='REENABLED'
    AND c.evidence_reference='lc-node-result:'||r.id::text)
$$;

CREATE FUNCTION ops.lease_ad_bid_command(p_command_id uuid, p_owner text, p_seconds integer) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE
    command ops.ad_bid_command%ROWTYPE;
    reasons text[];
    fence   bigint;
BEGIN
    IF p_owner IS NULL OR length(p_owner) NOT BETWEEN 1 AND 100
        OR p_seconds NOT BETWEEN 1 AND 900 THEN
        RAISE EXCEPTION 'lease owner or duration is invalid' USING ERRCODE = 'MO095';
    END IF;
    SELECT * INTO command FROM ops.ad_bid_command WHERE id = p_command_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'command does not exist' USING ERRCODE = 'MO090';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM ops.ad_bid_command_transition
                    WHERE from_state = command.state AND to_state = 'LEASED') THEN
        RAISE EXCEPTION 'this command cannot be claimed from %', command.state
            USING ERRCODE = 'MO091';
    END IF;
    IF command.state = 'RETRY_WAIT' AND (command.next_attempt_at IS NULL
        OR command.next_attempt_at > clock_timestamp() OR command.retry_budget_remaining <= 0) THEN
        RAISE EXCEPTION 'retry delay and remaining budget must permit a new lease'
            USING ERRCODE = 'MO092';
    END IF;
    -- The gate is evaluated inside the same transaction that takes the lease, so
    -- a command cannot be claimed against authority that has already lapsed.
    reasons := ops.evaluate_ad_bid_write_gate(p_command_id);
    IF cardinality(reasons) > 0 THEN
        RAISE EXCEPTION 'the advertising write gate is closed: %',
            array_to_string(reasons, ',') USING ERRCODE = 'MO092';
    END IF;
    UPDATE ops.ad_bid_command
       SET state = 'LEASED', fence_token = fence_token + 1, attempt_no = attempt_no + 1,
           retry_preflight_fence = CASE WHEN command.state = 'RETRY_WAIT' THEN fence_token + 1 ELSE NULL END,
           lease_owner = p_owner,
           lease_expires_at = clock_timestamp() + make_interval(secs => p_seconds),
           next_attempt_at = NULL, updated_at = clock_timestamp()
     WHERE id = p_command_id
     RETURNING fence_token INTO fence;
    RETURN fence;
END;
$$;

CREATE FUNCTION ops.lease_ad_bid_compensation(p_command_id uuid, p_owner text, p_seconds integer) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE reasons text[]; fence bigint;
BEGIN
    IF p_owner IS NULL OR length(p_owner) NOT BETWEEN 1 AND 100
        OR p_seconds NOT BETWEEN 1 AND 900 THEN
        RAISE EXCEPTION 'lease owner or duration is invalid' USING ERRCODE = 'MO095';
    END IF;
    reasons := ops.evaluate_ad_bid_compensation_gate(p_command_id);
    IF cardinality(reasons) > 0 THEN
        RAISE EXCEPTION 'the advertising write gate is closed: %',
            array_to_string(reasons, ',') USING ERRCODE = 'MO092';
    END IF;
    UPDATE ops.ad_bid_command
       SET fence_token = fence_token + 1, attempt_no = attempt_no + 1,
           lease_owner = p_owner,
           lease_expires_at = clock_timestamp() + make_interval(secs => p_seconds),
           updated_at = clock_timestamp()
     WHERE id = p_command_id
       AND state = 'COMPENSATION_PENDING'
       AND lease_owner IS NULL
     RETURNING fence_token INTO fence;
    IF fence IS NULL THEN
        RAISE EXCEPTION 'no compensation is authorised for this command' USING ERRCODE = 'MO090';
    END IF;
    RETURN fence;
END;
$$;

CREATE FUNCTION ops.lease_ad_bid_readback(p_command_id uuid, p_owner text, p_seconds integer) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE fence bigint;
BEGIN
    IF p_owner IS NULL OR length(p_owner) NOT BETWEEN 1 AND 100
        OR p_seconds NOT BETWEEN 1 AND 900 THEN
        RAISE EXCEPTION 'lease owner or duration is invalid' USING ERRCODE = 'MO095';
    END IF;
    UPDATE ops.ad_bid_command
       SET state = 'READBACK_PENDING', fence_token = fence_token + 1,
           attempt_no = attempt_no + 1, lease_owner = p_owner,
           lease_expires_at = clock_timestamp() + make_interval(secs => p_seconds),
           requested_operation = NULL, updated_at = clock_timestamp()
     WHERE id = p_command_id
       AND state = 'UNKNOWN_REQUIRES_READBACK'
       AND requested_operation = 'READBACK'
       AND lease_owner IS NULL
     RETURNING fence_token INTO fence;
    IF fence IS NULL THEN
        RAISE EXCEPTION 'no readback is authorised for this command' USING ERRCODE = 'MO090';
    END IF;
    RETURN fence;
END;
$$;

CREATE FUNCTION ops.lease_ad_bid_status(p_command uuid, p_owner text, p_seconds integer) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE fence bigint; BEGIN
 IF p_owner IS NULL OR length(p_owner) NOT BETWEEN 1 AND 100 OR p_seconds NOT BETWEEN 1 AND 900 THEN
  RAISE EXCEPTION 'invalid status lease' USING ERRCODE='MO095'; END IF;
 UPDATE ops.ad_bid_command SET fence_token=fence_token+1,lease_owner=p_owner,
 lease_expires_at=clock_timestamp()+make_interval(secs=>p_seconds),updated_at=clock_timestamp()
 WHERE id=p_command AND state='PLATFORM_PENDING' AND lease_owner IS NULL
 AND (next_attempt_at IS NULL OR next_attempt_at<=clock_timestamp()) RETURNING fence_token INTO fence;
 IF fence IS NULL THEN RAISE EXCEPTION 'status phase is not claimable' USING ERRCODE='MO090'; END IF;
 RETURN fence;
END $$;

CREATE FUNCTION ops.lease_lc_description_command(p_command_id uuid, p_owner text, p_seconds integer) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE command ops.lc_description_command%ROWTYPE; reasons text[]; fence bigint;
BEGIN
    IF p_owner IS NULL OR length(p_owner) NOT BETWEEN 1 AND 100 OR p_seconds NOT BETWEEN 1 AND 900 THEN
        RAISE EXCEPTION 'lease owner or duration is invalid' USING ERRCODE = 'MO095';
    END IF;
    SELECT * INTO command FROM ops.lc_description_command WHERE id = p_command_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'command does not exist' USING ERRCODE = 'MO090'; END IF;
    IF NOT EXISTS (SELECT 1 FROM ops.lc_description_command_transition
                    WHERE from_state = command.state AND to_state = 'LEASED') THEN
        RAISE EXCEPTION 'this command cannot be claimed from %', command.state USING ERRCODE = 'MO091';
    END IF;
    IF command.state = 'RETRY_WAIT' AND (command.next_attempt_at IS NULL
        OR command.next_attempt_at > clock_timestamp() OR command.retry_budget_remaining <= 0) THEN
        RAISE EXCEPTION 'retry delay and remaining budget must permit a new lease' USING ERRCODE = 'MO092';
    END IF;
    reasons := ops.evaluate_lc_description_write_gate(p_command_id);
    IF cardinality(reasons) > 0 THEN
        RAISE EXCEPTION 'the description write gate is closed: %', array_to_string(reasons, ',')
            USING ERRCODE = 'MO092';
    END IF;
    UPDATE ops.lc_description_command
       SET state = 'LEASED', fence_token = fence_token + 1, attempt_no = attempt_no + 1,
           retry_preflight_fence = CASE WHEN command.state = 'RETRY_WAIT' THEN fence_token + 1 ELSE NULL END,
           lease_owner = p_owner, lease_expires_at = clock_timestamp() + make_interval(secs => p_seconds),
           next_attempt_at = NULL, updated_at = clock_timestamp()
     WHERE id = p_command_id
     RETURNING fence_token INTO fence;
    RETURN fence;
END;
$$;

CREATE FUNCTION ops.lease_lc_description_compensation(p_command_id uuid, p_owner text, p_seconds integer) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE command ops.lc_description_command%ROWTYPE; fence bigint;
BEGIN
    IF p_owner IS NULL OR length(p_owner) NOT BETWEEN 1 AND 100 OR p_seconds NOT BETWEEN 1 AND 900 THEN
        RAISE EXCEPTION 'lease owner or duration is invalid' USING ERRCODE = 'MO095';
    END IF;
    SELECT * INTO command FROM ops.lc_description_command WHERE id = p_command_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'command does not exist' USING ERRCODE = 'MO090'; END IF;
    IF command.state <> 'COMPENSATION_PENDING' OR command.lease_owner IS NOT NULL THEN
        RAISE EXCEPTION 'a compensation lease needs an unleased pending compensation' USING ERRCODE = 'MO091';
    END IF;
    IF command.prior_text IS NULL THEN
        RAISE EXCEPTION 'RESTORE_UNSUPPORTED: no complete prior text was captured' USING ERRCODE = 'MO094';
    END IF;
    UPDATE ops.lc_description_command
       SET fence_token = fence_token + 1, attempt_no = attempt_no + 1, lease_owner = p_owner,
           lease_expires_at = clock_timestamp() + make_interval(secs => p_seconds),
           next_attempt_at = NULL, updated_at = clock_timestamp()
     WHERE id = p_command_id
     RETURNING fence_token INTO fence;
    RETURN fence;
END;
$$;

CREATE FUNCTION ops.lease_lc_description_readback(p_command_id uuid, p_owner text, p_seconds integer) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE command ops.lc_description_command%ROWTYPE; fence bigint;
BEGIN
    IF p_owner IS NULL OR length(p_owner) NOT BETWEEN 1 AND 100 OR p_seconds NOT BETWEEN 1 AND 900 THEN
        RAISE EXCEPTION 'lease owner or duration is invalid' USING ERRCODE = 'MO095';
    END IF;
    SELECT * INTO command FROM ops.lc_description_command WHERE id = p_command_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'command does not exist' USING ERRCODE = 'MO090'; END IF;
    IF command.state <> 'UNKNOWN_REQUIRES_READBACK' OR command.requested_operation IS DISTINCT FROM 'READBACK' THEN
        RAISE EXCEPTION 'a readback lease needs a requested readback on an unknown command'
            USING ERRCODE = 'MO091';
    END IF;
    UPDATE ops.lc_description_command
       SET state = 'READBACK_PENDING', fence_token = fence_token + 1, attempt_no = attempt_no + 1,
           lease_owner = p_owner, lease_expires_at = clock_timestamp() + make_interval(secs => p_seconds),
           requested_operation = NULL, updated_at = clock_timestamp()
     WHERE id = p_command_id
     RETURNING fence_token INTO fence;
    RETURN fence;
END;
$$;

CREATE FUNCTION ops.lease_lc_description_status(p_command_id uuid, p_owner text, p_seconds integer) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE command ops.lc_description_command%ROWTYPE; fence bigint;
BEGIN
    IF p_owner IS NULL OR length(p_owner) NOT BETWEEN 1 AND 100 OR p_seconds NOT BETWEEN 1 AND 900 THEN
        RAISE EXCEPTION 'lease owner or duration is invalid' USING ERRCODE = 'MO095';
    END IF;
    SELECT * INTO command FROM ops.lc_description_command WHERE id = p_command_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'command does not exist' USING ERRCODE = 'MO090'; END IF;
    IF command.state <> 'PLATFORM_PENDING' OR command.lease_owner IS NOT NULL
        OR (command.next_attempt_at IS NOT NULL AND command.next_attempt_at > clock_timestamp()) THEN
        RAISE EXCEPTION 'a status lease needs an unleased pending command whose delay elapsed'
            USING ERRCODE = 'MO091';
    END IF;
    UPDATE ops.lc_description_command
       SET fence_token = fence_token + 1, attempt_no = attempt_no + 1, lease_owner = p_owner,
           lease_expires_at = clock_timestamp() + make_interval(secs => p_seconds),
           next_attempt_at = NULL, updated_at = clock_timestamp()
     WHERE id = p_command_id
     RETURNING fence_token INTO fence;
    RETURN fence;
END;
$$;

CREATE FUNCTION ops.lease_price_command(p_command_id uuid, p_lease_owner text, p_lease_seconds integer) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    current_state text;
    gate_reasons  text[];
    new_fence     bigint;
BEGIN
    IF p_lease_owner IS NULL OR length(btrim(p_lease_owner)) = 0 THEN
        RAISE EXCEPTION 'a lease owner is required'
            USING ERRCODE = 'MO035';
    END IF;
    IF p_lease_seconds IS NULL OR p_lease_seconds <= 0 OR p_lease_seconds > 900 THEN
        RAISE EXCEPTION 'lease duration must be between 1 and 900 seconds'
            USING ERRCODE = 'MO035';
    END IF;

    SELECT command.state INTO current_state
      FROM ops.price_command AS command
     WHERE command.id = p_command_id
       FOR UPDATE OF command;

    IF current_state IS NULL THEN
        RAISE EXCEPTION 'price command % does not exist', p_command_id
            USING ERRCODE = 'MO030';
    END IF;

    PERFORM 1 FROM ops.price_command_transition AS allowed
     WHERE allowed.from_state = current_state AND allowed.to_state = 'LEASED';
    IF NOT FOUND
    THEN
        RAISE EXCEPTION 'price command % cannot be leased from state %',
            p_command_id, current_state
            USING ERRCODE = 'MO031';
    END IF;

    gate_reasons := ops.evaluate_price_write_gate(p_command_id);
    IF cardinality(gate_reasons) > 0 THEN
        RAISE EXCEPTION 'price write gate closed for command %: %',
            p_command_id, array_to_string(gate_reasons, ',')
            USING ERRCODE = 'MO032';
    END IF;

    UPDATE ops.price_command AS command
       SET state = 'LEASED',
           fence_token = command.fence_token + 1,
           attempt_no = command.attempt_no + 1,
           lease_owner = p_lease_owner,
           lease_expires_at = clock_timestamp() + make_interval(secs => p_lease_seconds),
           next_attempt_at = NULL,
           updated_at = clock_timestamp()
     WHERE command.id = p_command_id
       AND command.state = current_state
    RETURNING command.fence_token INTO new_fence;

    IF new_fence IS NULL THEN
        RAISE EXCEPTION 'price command % changed while being leased', p_command_id
            USING ERRCODE = 'MO030';
    END IF;

    RETURN new_fence;
END;
$$;

CREATE FUNCTION ops.lease_price_compensation(p_command_id uuid, p_lease_owner text, p_lease_seconds integer) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    command_row  record;
    gate_reasons text[];
    new_fence    bigint;
BEGIN
    IF p_lease_owner IS NULL OR length(btrim(p_lease_owner)) = 0 THEN
        RAISE EXCEPTION 'a lease owner is required'
            USING ERRCODE = 'MO035';
    END IF;
    IF p_lease_seconds IS NULL OR p_lease_seconds <= 0 OR p_lease_seconds > 900 THEN
        RAISE EXCEPTION 'lease duration must be between 1 and 900 seconds'
            USING ERRCODE = 'MO035';
    END IF;

    SELECT command.id, command.state, command.lease_expires_at
      INTO command_row
      FROM ops.price_command AS command
     WHERE command.id = p_command_id
       FOR UPDATE OF command;

    IF command_row.id IS NULL THEN
        RAISE EXCEPTION 'price command % does not exist', p_command_id
            USING ERRCODE = 'MO030';
    END IF;

    IF command_row.state <> 'COMPENSATION_PENDING' THEN
        RAISE EXCEPTION 'price command % is not awaiting a restore; it is %',
            p_command_id, command_row.state
            USING ERRCODE = 'MO031';
    END IF;

    IF command_row.lease_expires_at IS NOT NULL
        AND command_row.lease_expires_at > clock_timestamp() THEN
        RAISE EXCEPTION 'price command % is already held', p_command_id
            USING ERRCODE = 'MO035';
    END IF;

    gate_reasons := ops.evaluate_price_write_gate(p_command_id);
    IF cardinality(gate_reasons) > 0 THEN
        RAISE EXCEPTION 'price write gate closed for command %: %',
            p_command_id, array_to_string(gate_reasons, ',')
            USING ERRCODE = 'MO032';
    END IF;

    UPDATE ops.price_command AS command
       SET fence_token = command.fence_token + 1,
           attempt_no = command.attempt_no + 1,
           lease_owner = p_lease_owner,
           lease_expires_at = clock_timestamp() + make_interval(secs => p_lease_seconds),
           updated_at = clock_timestamp()
     WHERE command.id = p_command_id
       AND command.state = 'COMPENSATION_PENDING'
    RETURNING command.fence_token INTO new_fence;

    IF new_fence IS NULL THEN
        RAISE EXCEPTION 'price command % changed while being leased', p_command_id
            USING ERRCODE = 'MO030';
    END IF;

    RETURN new_fence;
END;
$$;

CREATE FUNCTION ops.lease_price_readback(p_command uuid, p_owner text, p_seconds integer) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE fence bigint;
BEGIN
    IF p_owner IS NULL OR length(btrim(p_owner)) = 0 OR p_seconds IS NULL
        OR p_seconds NOT BETWEEN 1 AND 900 THEN
        RAISE EXCEPTION 'invalid readback lease' USING ERRCODE = 'MO035';
    END IF;
    UPDATE ops.price_command SET state = 'READBACK_PENDING', requested_operation = NULL,
        fence_token = fence_token + 1, attempt_no = attempt_no + 1,
        lease_owner = p_owner, lease_expires_at = clock_timestamp() + make_interval(secs => p_seconds),
        updated_at = clock_timestamp()
    WHERE id = p_command AND state = 'UNKNOWN_REQUIRES_READBACK'
        AND requested_operation = 'READBACK' AND lease_owner IS NULL
    RETURNING fence_token INTO fence;
    IF fence IS NULL THEN RAISE EXCEPTION 'readback intent is not claimable' USING ERRCODE = 'MO030'; END IF;
    RETURN fence;
END;
$$;

CREATE FUNCTION ops.lock_lc_command_task_deliveries(p_limit integer) RETURNS TABLE(command_id uuid, organization_id uuid, task_id uuid, recommendation_id uuid, command_state text, failure_code text, recorded_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
    SELECT c.id,c.organization_id,t.id,a.recommendation_id,c.state,c.failure_code,c.updated_at
    FROM ops.lc_description_command c JOIN ops.lc_action a ON a.id=c.action_id
    JOIN LATERAL (SELECT w.id FROM ops.work_task w
      WHERE w.organization_id=c.organization_id AND w.recommendation_id=a.recommendation_id
      ORDER BY w.id LIMIT 1) t ON true
    WHERE c.state<>'READBACK_MATCHED'
      AND NOT EXISTS(SELECT 1 FROM ops.work_task_event e
        WHERE e.correlation_id='lc-command-state:'||c.id::text||':'||c.state)
    ORDER BY c.updated_at,c.id LIMIT least(greatest(p_limit,0),100)
    FOR UPDATE OF c SKIP LOCKED
$$;

CREATE FUNCTION ops.lock_lc_execution_deliveries(p_limit integer) RETURNS TABLE(receipt_id uuid, organization_id uuid, task_id uuid, recommendation_id uuid, execution_state text, recorded_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
    SELECT r.id,r.organization_id,t.id,a.recommendation_id,r.execution_state,r.recorded_at
      FROM ops.lc_execution_receipt r JOIN ops.lc_action a ON a.id=r.action_id
      JOIN LATERAL (SELECT w.id FROM ops.work_task w WHERE w.recommendation_id=a.recommendation_id
          AND w.organization_id=r.organization_id ORDER BY w.id LIMIT 1) t ON true
     WHERE r.task_event_id IS NULL ORDER BY r.recorded_at,r.id
     LIMIT least(greatest(p_limit,0),100) FOR UPDATE OF r SKIP LOCKED;
$$;

CREATE FUNCTION ops.lock_lc_launch_evaluation(p_action uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE organization uuid;
BEGIN
 SELECT organization_id INTO STRICT organization FROM ops.lc_action WHERE id=p_action;
 PERFORM pg_advisory_xact_lock(hashtext('lc_exposure_organization'),hashtext(organization::text));
 LOCK TABLE ops.lc_exposure_allowance IN SHARE MODE;
END
$$;

CREATE FUNCTION ops.lock_lc_outcome_failure_publication() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NEW.protection_verdict='FAIL' THEN
   PERFORM pg_advisory_xact_lock(hashtext('lc_exposure_organization'),hashtext(NEW.organization_id::text));
 END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION ops.observe_ad_reservation_condition(p_reservation_id uuid, p_condition text, p_holds boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
BEGIN
    IF p_condition NOT IN ('CONFIGURATION_RESOLVED', 'UNKNOWN_OR_MISMATCH_OPEN',
                           'EARLY_OBSERVATION_COMPLETE', 'REGRESSION_OPEN') THEN
        RAISE EXCEPTION 'unknown release condition %', p_condition USING ERRCODE = 'MO097';
    END IF;
    UPDATE ops.ad_action_reservation
       SET configuration_resolved = CASE WHEN p_condition = 'CONFIGURATION_RESOLVED'
                                         THEN p_holds ELSE configuration_resolved END,
           unknown_or_mismatch_open = CASE WHEN p_condition = 'UNKNOWN_OR_MISMATCH_OPEN'
                                           THEN p_holds ELSE unknown_or_mismatch_open END,
           early_observation_complete = CASE WHEN p_condition = 'EARLY_OBSERVATION_COMPLETE'
                                             THEN p_holds ELSE early_observation_complete END,
           regression_open = CASE WHEN p_condition = 'REGRESSION_OPEN'
                                  THEN p_holds ELSE regression_open END,
           version = version + 1
     WHERE id = p_reservation_id AND state = 'ACTIVE';
    IF NOT FOUND THEN
        RAISE EXCEPTION 'no active reservation to observe' USING ERRCODE = 'MO097';
    END IF;
END;
$$;

CREATE FUNCTION ops.observe_lc_occupation(p_occupation uuid, p_state text, p_occupied numeric) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 RAISE EXCEPTION 'occupation state and quantity require purpose-qualified canonical evidence' USING ERRCODE='MO092';
END
$$;

CREATE FUNCTION ops.open_ad_bid_command_attempt(p_attempt_id uuid, p_command_id uuid, p_purpose text, p_fence bigint, p_owner text, p_request_digest text, p_correlation_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'platform', 'pg_temp'
    AS $_$
DECLARE
    command ops.ad_bid_command%ROWTYPE;
    shape   jsonb;
    reasons text[];
    next_no integer;
    expected_version text;
BEGIN
    SELECT * INTO command FROM ops.ad_bid_command WHERE id = p_command_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'command does not exist' USING ERRCODE = 'MO090';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtext('ad_action_reservation'),hashtext(command.organization_id::text));
    IF command.fence_token <> p_fence
        OR command.lease_owner IS DISTINCT FROM p_owner
        OR command.lease_expires_at IS NULL
        OR command.lease_expires_at <= clock_timestamp() THEN
        RAISE EXCEPTION 'the lease that authorised this attempt is not current'
            USING ERRCODE = 'MO090';
    END IF;
    IF p_request_digest !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION 'a request digest is required before a call is made'
            USING ERRCODE = 'MO090';
    END IF;
    IF p_correlation_id IS NULL OR length(btrim(p_correlation_id)) NOT BETWEEN 1 AND 128 THEN
        RAISE EXCEPTION 'a correlation identifier is required' USING ERRCODE = 'MO090';
    END IF;

    -- Purpose and state must agree. A READBACK during EXECUTING would observe a
    -- value before the write it is meant to verify.
    IF NOT ((p_purpose = 'APPLY' AND command.state = 'EXECUTING')
         OR (p_purpose = 'STATUS_ENQUIRY' AND command.state IN ('EXECUTING', 'PLATFORM_PENDING', 'COMPENSATION_PENDING'))
         OR (p_purpose = 'READBACK' AND command.state IN ('READBACK_PENDING', 'COMPENSATION_PENDING'))
         OR (p_purpose = 'RESTORE' AND command.state = 'COMPENSATION_PENDING')) THEN
        RAISE EXCEPTION 'a % attempt cannot be opened from %', p_purpose, command.state
            USING ERRCODE = 'MO091';
    END IF;

    -- No second in-flight attempt at the same fence.
    IF EXISTS (SELECT 1 FROM ops.ad_bid_command_attempt a
                WHERE a.command_id = p_command_id
                  AND a.fence_token = p_fence
                  AND a.outcome_class = 'IN_FLIGHT') THEN
        RAISE EXCEPTION 'another attempt is already in flight at this fence'
            USING ERRCODE = 'MO090';
    END IF;

    -- A second submission requires current same-command proof. A timeout has
    -- no response body; verified native-key APPLY may instead rely on the
    -- later official status and current Readback required by the retry predicate.
    -- Without that verified identity, explicit non-application evidence remains mandatory.
    IF p_purpose IN ('APPLY', 'RESTORE')
        AND EXISTS (SELECT 1 FROM ops.ad_bid_command_attempt a
                     WHERE a.command_id = p_command_id AND a.purpose = p_purpose)
        AND NOT (command.retry_budget_remaining > 0 AND EXISTS (
            SELECT 1 FROM ops.ad_bid_command_attempt a
            WHERE a.command_id = p_command_id AND a.purpose = p_purpose
              AND a.id = (SELECT last_attempt.id FROM ops.ad_bid_command_attempt last_attempt
                           WHERE last_attempt.command_id = p_command_id
                             AND last_attempt.purpose = p_purpose
                           ORDER BY last_attempt.attempt_no DESC LIMIT 1)
              AND ops.ad_bid_retry_is_proven(p_command_id)
              AND (a.raw_observation_id IS NOT NULL OR p_purpose='APPLY'
                   AND a.operation_snapshot #>> '{adSemanticProfile,idempotency_semantics}'='VERIFIED_NATIVE_KEY')
              AND (a.error_code = 'provider_explicit_not_applied'
                   OR EXISTS(SELECT 1 FROM ops.ad_bid_command_attempt proof
                      WHERE proof.command_id=p_command_id AND proof.error_code='provider_explicit_not_applied'
                        AND proof.completed_at>a.completed_at AND proof.raw_observation_id IS NOT NULL)
                   OR a.operation_snapshot #>> '{adSemanticProfile,idempotency_semantics}'
                        = 'VERIFIED_NATIVE_KEY'))) THEN
        RAISE EXCEPTION 'a mutating command operation cannot be dispatched twice'
            USING ERRCODE = 'MO090';
    END IF;

    -- The transmission boundary. The gate is evaluated once more, here, so a
    -- quarantine or kill activated after the lease was taken stops the call.
    IF p_purpose IN ('APPLY', 'RESTORE') THEN
        reasons := CASE WHEN p_purpose='RESTORE' THEN ops.evaluate_ad_bid_compensation_gate(p_command_id)
                   ELSE ops.evaluate_ad_bid_write_gate(p_command_id) END;
        IF cardinality(reasons) > 0 THEN
            RAISE EXCEPTION 'the advertising write gate is closed at transmission: %',
                array_to_string(reasons, ',') USING ERRCODE = 'MO092';
        END IF;
    END IF;

    -- A restore may only be attempted while the bid is still what this command
    -- wrote, proven by the latest readback rather than by an earlier belief.
    IF p_purpose = 'RESTORE' THEN
        IF NOT EXISTS (
            SELECT 1 FROM ops.ad_bid_command_readback rb
             WHERE rb.command_id = p_command_id
               AND rb.match_state = 'MATCHES_TARGET'
               AND rb.observed_at = (SELECT max(latest.observed_at)
                                       FROM ops.ad_bid_command_readback latest
                                      WHERE latest.command_id = p_command_id)
               AND rb.observed_at > clock_timestamp() - interval '30 seconds') THEN
            RAISE EXCEPTION 'a restore needs a current readback proving this command still owns the bid'
                USING ERRCODE = 'MO094';
        END IF;
        SELECT obs.version_token INTO expected_version
          FROM ops.ad_bid_command_readback rb
          JOIN raw.ad_bid_response_observation obs ON obs.id = rb.raw_observation_id
         WHERE rb.command_id = p_command_id
         ORDER BY rb.observed_at DESC LIMIT 1;
    END IF;

    shape := platform.ad_bid_operation_snapshot(command.capability_id, p_purpose);
    IF shape IS NULL THEN
        RAISE EXCEPTION 'no verified advertising write shape exists for this operation'
            USING ERRCODE = 'MO093';
    END IF;

    shape := shape || jsonb_build_object('adSemanticProfile',
        (SELECT to_jsonb(p) FROM platform.ad_semantic_profile p
          WHERE p.id = command.semantic_profile_id AND p.verification_state = 'VERIFIED'
            AND p.status = 'ACTIVE'));
    IF shape -> 'adSemanticProfile' = 'null'::jsonb THEN
        RAISE EXCEPTION 'verified semantic profile is required' USING ERRCODE = 'MO093';
    END IF;
    SELECT coalesce(max(a.attempt_no), 0) + 1 INTO next_no
      FROM ops.ad_bid_command_attempt a WHERE a.command_id = p_command_id;

    INSERT INTO ops.ad_bid_command_attempt (
        id, command_id, attempt_no, purpose, fence_token, lease_owner, started_at,
        outcome_class, correlation_id, request_digest, operation_snapshot,
        expected_version_token)
    VALUES (p_attempt_id, p_command_id, next_no, p_purpose, p_fence, p_owner,
        clock_timestamp(), 'IN_FLIGHT', p_correlation_id, p_request_digest, shape,
        expected_version);

    RETURN p_attempt_id;
END;
$_$;

CREATE FUNCTION ops.open_lc_description_command_attempt(p_attempt_id uuid, p_command_id uuid, p_purpose text, p_fence bigint, p_owner text, p_request_digest text, p_correlation_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'platform', 'pg_temp'
    AS $_$
DECLARE command ops.lc_description_command%ROWTYPE; shape jsonb; reasons text[]; next_no integer; restoration boolean; expected_version text;
BEGIN
    SELECT * INTO command FROM ops.lc_description_command WHERE id = p_command_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'command does not exist' USING ERRCODE = 'MO090'; END IF;
    IF command.fence_token <> p_fence OR command.lease_owner IS DISTINCT FROM p_owner
        OR command.lease_expires_at IS NULL OR command.lease_expires_at <= clock_timestamp() THEN
        RAISE EXCEPTION 'the lease that authorised this attempt is not current' USING ERRCODE = 'MO090';
    END IF;
    IF p_request_digest !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION 'a request digest is required before a call is made' USING ERRCODE = 'MO090';
    END IF;
    IF p_correlation_id IS NULL OR length(btrim(p_correlation_id)) NOT BETWEEN 1 AND 128 THEN
        RAISE EXCEPTION 'a correlation identifier is required' USING ERRCODE = 'MO090';
    END IF;
    SELECT restores_command_id IS NOT NULL INTO restoration FROM ops.lc_action WHERE id=command.action_id;
    IF NOT ((p_purpose = 'APPLY' AND command.state = 'EXECUTING' AND NOT restoration)
         OR (p_purpose = 'STATUS_ENQUIRY' AND command.state IN ('EXECUTING', 'PLATFORM_PENDING', 'COMPENSATION_PENDING'))
         OR (p_purpose = 'READBACK' AND command.state IN ('READBACK_PENDING', 'COMPENSATION_PENDING'))
         OR (p_purpose = 'RESTORE' AND command.state = 'EXECUTING' AND restoration)) THEN
        RAISE EXCEPTION 'a % attempt cannot be opened from %', p_purpose, command.state USING ERRCODE = 'MO091';
    END IF;
    IF EXISTS (SELECT 1 FROM ops.lc_description_command_attempt a
                WHERE a.command_id = p_command_id AND a.fence_token = p_fence AND a.outcome_class = 'IN_FLIGHT') THEN
        RAISE EXCEPTION 'another attempt is already in flight at this fence' USING ERRCODE = 'MO096';
    END IF;
    -- The gate again, immediately before the call. A mutating attempt also
    -- needs every reason gone; an observation may proceed under some of them.
    reasons := ops.evaluate_lc_description_write_gate(p_command_id);
    IF p_purpose IN ('APPLY', 'RESTORE') AND cardinality(reasons) > 0 THEN
        RAISE EXCEPTION 'the description write gate is closed: %', array_to_string(reasons, ',')
            USING ERRCODE = 'MO092';
    END IF;
    IF p_purpose = 'RESTORE' THEN
        expected_version:=ops.lc_restoration_preflight_version(command.id);
        IF expected_version IS NULL THEN
            RAISE EXCEPTION 'RESTORE_UNSUPPORTED: current exact preflight version is missing' USING ERRCODE='MO094';
        END IF;
    END IF;
    -- The operation shape is frozen into the attempt so completion classifies
    -- against what was called, not against what the registry says later.
    shape := platform.lc_description_operation_snapshot(command.capability_id, p_purpose);
    IF shape IS NULL THEN
        RAISE EXCEPTION 'no verified % operation is recorded for this capability', p_purpose
            USING ERRCODE = 'MO092';
    END IF;
    SELECT coalesce(max(attempt_no), 0) + 1 INTO next_no FROM ops.lc_description_command_attempt
     WHERE command_id = p_command_id;
    INSERT INTO ops.lc_description_command_attempt (id, command_id, attempt_no, purpose, fence_token,
        lease_owner, started_at, outcome_class, correlation_id, request_digest, operation_snapshot, expected_version_token)
    VALUES (p_attempt_id, p_command_id, next_no, p_purpose, p_fence, p_owner, clock_timestamp(),
        'IN_FLIGHT', p_correlation_id, p_request_digest, shape, expected_version);
    RETURN p_attempt_id;
END;
$_$;

CREATE FUNCTION ops.open_price_command_attempt(p_id uuid, p_command uuid, p_purpose text, p_fence bigint, p_owner text, p_request_digest text, p_correlation text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE c ops.price_command%ROWTYPE; sequence integer; shape jsonb; precondition text;
BEGIN
    SELECT * INTO c FROM ops.price_command WHERE id = p_command FOR UPDATE;
    IF c.id IS NULL OR c.fence_token IS DISTINCT FROM p_fence
       OR c.lease_owner IS DISTINCT FROM p_owner OR c.lease_expires_at <= clock_timestamp()
       OR c.lease_expires_at IS NULL OR p_request_digest IS NULL
       OR p_correlation IS NULL OR length(btrim(p_correlation)) NOT BETWEEN 1 AND 128 THEN
        RAISE EXCEPTION 'attempt authority lost' USING ERRCODE = 'MO030';
    END IF;
    IF NOT ((p_purpose = 'APPLY' AND c.state = 'EXECUTING')
        OR (p_purpose = 'STATUS_ENQUIRY' AND c.state IN ('EXECUTING', 'PLATFORM_PENDING'))
        OR (p_purpose = 'READBACK' AND c.state IN ('READBACK_PENDING', 'COMPENSATION_PENDING'))
        OR (p_purpose = 'RESTORE' AND c.state = 'COMPENSATION_PENDING')) THEN
        RAISE EXCEPTION 'attempt purpose does not match command state' USING ERRCODE = 'MO031';
    END IF;
    IF p_purpose = 'RESTORE' AND NOT EXISTS (
        SELECT 1 FROM ops.price_command_readback r
        JOIN ops.price_command_attempt a ON a.id = r.attempt_id
        JOIN raw.price_response_observation evidence ON evidence.id = r.raw_observation_id
        JOIN platform.capability_operation operation ON operation.capability_id = c.capability_id
            AND operation.operation = 'RESTORE' AND operation.status = 'ACTIVE'
            AND operation.verification_state = 'VERIFIED'
        WHERE r.command_id = c.id AND r.match_state = 'MATCHES_TARGET'
          AND a.purpose = 'READBACK' AND a.fence_token = c.fence_token
          AND evidence.version_token IS NOT NULL AND operation.conditional_write_header IS NOT NULL
          AND r.observed_at >= c.updated_at
          AND r.observed_at > clock_timestamp() - interval '30 seconds'
          AND EXISTS (SELECT 1 FROM ops.price_command_attempt applied
               WHERE applied.command_id=c.id AND applied.purpose='APPLY'
                 AND applied.outcome_class IN ('ACCEPTED','UNKNOWN_STATE')
                 AND applied.completed_at<=r.observed_at)
          AND NOT EXISTS (SELECT 1 FROM ops.price_command_readback later
               WHERE later.command_id = c.id AND later.observed_at > r.observed_at)) THEN
        RAISE EXCEPTION 'restore requires a fresh conditional-write precondition'
            USING ERRCODE = 'MO034';
    END IF;
    IF p_purpose IN ('APPLY', 'RESTORE') AND cardinality(ops.evaluate_price_write_gate(c.id)) > 0 THEN
        RAISE EXCEPTION 'write gate closed before dispatch' USING ERRCODE = 'MO032';
    END IF;
    IF EXISTS (SELECT 1 FROM ops.price_command_attempt a WHERE a.command_id = c.id
        AND a.outcome_class = 'IN_FLIGHT' AND a.fence_token = c.fence_token) THEN
        RAISE EXCEPTION 'an unresolved attempt prohibits another call' USING ERRCODE = 'MO030';
    END IF;
    IF p_purpose IN ('APPLY','RESTORE') AND EXISTS (SELECT 1 FROM ops.price_command_attempt a
        WHERE a.command_id=c.id AND a.purpose=p_purpose) THEN
        RAISE EXCEPTION 'a mutating command operation cannot be dispatched twice' USING ERRCODE='MO030';
    END IF;
    shape := platform.price_operation_snapshot(c.capability_id,p_purpose);
    IF shape IS NULL THEN
        RAISE EXCEPTION 'attempt requires a verified operation snapshot' USING ERRCODE='MO033';
    END IF;
    IF p_purpose='RESTORE' THEN
        SELECT evidence.version_token INTO precondition
          FROM ops.price_command_readback r JOIN raw.price_response_observation evidence ON evidence.id=r.raw_observation_id
          JOIN ops.price_command_attempt a ON a.id=r.attempt_id
         WHERE r.command_id=c.id AND a.fence_token=c.fence_token AND r.match_state='MATCHES_TARGET'
         ORDER BY r.observed_at DESC LIMIT 1;
    END IF;
    SELECT coalesce(max(attempt_no), 0) + 1 INTO sequence
      FROM ops.price_command_attempt WHERE command_id = c.id;
    INSERT INTO ops.price_command_attempt (id, command_id, attempt_no, purpose, fence_token,
        lease_owner, started_at, outcome_class, correlation_id, request_digest,
        operation_snapshot, expected_version_token)
    VALUES (p_id, c.id, sequence, p_purpose, p_fence, p_owner, clock_timestamp(),
        'IN_FLIGHT', p_correlation, p_request_digest, shape, precondition);
    RETURN p_id;
END;
$$;

CREATE FUNCTION ops.prepare_lc_calibration(p_id uuid, p_proof text, p_body jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE g iam.ad_invocation_grant%ROWTYPE; v jsonb; digest text; now_at timestamptz:=clock_timestamp();
BEGIN
 g:=ops.consume_ad_control_invocation(p_proof,'LISTING_CALIBRATION_PREPARE',p_id,p_id);
 IF NOT ops.lc_calibration_actor_scope(g.actor_user_id,g.organization_id,p_body->>'scopeKind',
       (p_body->>'storeId')::uuid,'LISTING_CALIBRATION_PREPARE') THEN
  RAISE EXCEPTION 'calibration preparation scope denied' USING ERRCODE='MO092';
 END IF;
 IF jsonb_typeof(p_body->'values')<>'array' OR jsonb_array_length(p_body->'values')=0 THEN
  RAISE EXCEPTION 'calibration values required' USING ERRCODE='MO036';
 END IF;
 INSERT INTO core.lc_calibration_package(id,organization_id,package_code,package_version,scope_kind,platform_code,
   store_ref_id,purpose_code,status,published_by_user_id,published_at,evidence_reference,effective_from,effective_to)
 VALUES(p_id,g.organization_id,p_body->>'code',(p_body->>'version')::integer,p_body->>'scopeKind',p_body->>'platformCode',
   (p_body->>'storeId')::uuid,p_body->>'purposeCode','DRAFT',g.actor_user_id,now_at,p_body->>'evidenceReference',
   (p_body->>'effectiveFrom')::timestamptz,(p_body->>'effectiveTo')::timestamptz);
 FOR v IN SELECT value FROM jsonb_array_elements(p_body->'values') LOOP
  INSERT INTO core.lc_calibration_value(id,package_id,category_code,value_numeric,value_text,value_json,unit_code,
    scope_note,window_days,evidence_reference)
  VALUES(gen_random_uuid(),p_id,v->>'categoryCode',(v->>'numeric')::numeric,v->>'text',nullif(v->'json','null'::jsonb),
    v->>'unitCode',v->>'scopeNote',(v->>'windowDays')::integer,v->>'evidenceReference');
 END LOOP;
 INSERT INTO ops.lc_calibration_governance(package_id,replaces_package_id,rationale,impact,differences,
   drafted_by_user_id,drafted_at,draft_digest)
 VALUES(p_id,(p_body->>'replacesPackageId')::uuid,p_body->>'rationale',p_body->>'impact',p_body->>'differences',g.actor_user_id,now_at,repeat('0',64));
 digest:=ops.lc_calibration_digest(p_id);
 UPDATE ops.lc_calibration_governance SET draft_digest=digest WHERE package_id=p_id;
 INSERT INTO ops.lc_calibration_event VALUES(gen_random_uuid(),p_id,'DRAFTED',g.actor_user_id,digest,p_body->>'evidenceReference',now_at);
 RETURN p_id;
END $$;

CREATE FUNCTION ops.preview_ad_compensation(p_preview uuid, p_command uuid, p_bundle uuid, p_proof text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'iam', 'pg_temp'
    AS $$
DECLARE g iam.ad_invocation_grant%ROWTYPE; c ops.ad_bid_command%ROWTYPE; b ops.ad_decision_policy_bundle%ROWTYPE;
 lifetime integer;
BEGIN
 g:=ops.consume_ad_control_invocation(p_proof,'COMPENSATION_PREVIEW',p_command,p_preview);
 SELECT * INTO c FROM ops.ad_bid_command WHERE id=p_command FOR UPDATE;
 SELECT * INTO b FROM ops.ad_decision_policy_bundle WHERE id=p_bundle;
 IF c.id IS NULL OR g.organization_id<>c.organization_id OR NOT ops.ad_actor_has_role_scope(g.actor_user_id,
 c.organization_id,c.store_id,'MARKETPLACE_OPERATOR','ADVERTISING_TASK_ACT')
 OR b.id IS NULL OR b.direction<>'EXACT_PRIOR_BID_COMPENSATION' OR b.store_id<>c.store_id OR b.status<>'ACTIVE'
 OR NOT ops.ad_actor_covers_affected_set(g.actor_user_id,c.organization_id,
   (SELECT affected_set_id FROM ops.ad_action_reservation WHERE id=c.reservation_id),'ADVERTISING_TASK_ACT')
 OR EXISTS(SELECT 1 FROM ops.ad_compensation_authorization current_approval WHERE current_approval.command_id=c.id
   AND coalesce(current_approval.expires_at,current_approval.preview_expires_at)>clock_timestamp()
   AND NOT EXISTS(SELECT 1 FROM ops.ad_compensation_invalidation invalidated WHERE invalidated.compensation_id=current_approval.id))
 OR c.state IN ('COMPENSATION_PENDING','COMPENSATED','COMPENSATION_FAILED')
 OR NOT EXISTS(SELECT 1 FROM ops.ad_bid_command_readback rb WHERE rb.command_id=c.id AND rb.match_state='MATCHES_TARGET'
   AND rb.observed_bid=c.target_bid_amount AND rb.currency_code=c.currency_code AND rb.bid_unit_code=c.bid_unit_code
   AND NOT EXISTS(SELECT 1 FROM ops.ad_bid_command_readback newer WHERE newer.command_id=c.id
     AND (newer.observed_at,newer.id)>(rb.observed_at,rb.id)))
 OR NOT EXISTS(SELECT 1 FROM ops.ad_outcome_observation outcome WHERE outcome.command_id=c.id AND outcome.verdict='REGRESSED'
   AND outcome.evaluated_at<=clock_timestamp()
   AND NOT EXISTS(SELECT 1 FROM ops.ad_outcome_observation newer WHERE newer.supersedes_observation_id=outcome.id))
    AND NOT EXISTS(SELECT 1 FROM ops.ad_containment stop WHERE stop.action_command_id=c.id
     AND stop.containment_kind='EMERGENCY_ENTITY_HOLD' AND stop.cause_class='BUSINESS_HARM'
     AND stop.state IN('ACTIVE','REENABLEMENT_REVIEW') AND stop.activated_by_user_id IS NOT NULL) THEN
  RAISE EXCEPTION 'action-bound stop/regression and scoped maker are required for exact compensation' USING ERRCODE='MO094'; END IF;
 SELECT lease_seconds INTO lifetime FROM core.ad_approval_lease_policy WHERE id=b.approval_lease_policy_id AND status='ACTIVE';
 IF lifetime IS NULL THEN RAISE EXCEPTION 'compensation lease policy absent' USING ERRCODE='MO094'; END IF;
 INSERT INTO ops.ad_compensation_authorization(id,command_id,organization_id,bundle_id,reservation_id,captured_prior_bid,
 current_owner_bid,currency_code,bid_unit_code,affected_set_digest,maker_user_id,previewed_at,preview_expires_at,preview_snapshot)
 VALUES(p_preview,c.id,c.organization_id,b.id,c.reservation_id,c.prior_bid_amount,c.target_bid_amount,
 c.currency_code,c.bid_unit_code,c.affected_set_digest,g.actor_user_id,clock_timestamp(),
 least(clock_timestamp()+make_interval(secs=>lifetime),b.effective_to),ops.ad_bundle_authority_snapshot(b.id));
 RETURN p_preview;
END $$;

CREATE FUNCTION ops.price_authority_snapshot(p_recommendation_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
    SELECT ops.price_authority_snapshot(p_recommendation_id, statement_timestamp())
$$;

CREATE FUNCTION ops.price_authority_snapshot(p_recommendation_id uuid, p_as_of timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
    WITH recommendation AS (
        SELECT r.*
          FROM ops.recommendation r
         WHERE r.id = p_recommendation_id
    ), target AS (
        SELECT r.*,
               ops.price_change_parameter_contract_is_valid(r.proposed_parameters)
                   AS parameter_contract_valid,
               CASE WHEN (r.proposed_parameters ->> 'targetPrice')
                    ~ '^[0-9]{1,14}([.][0-9]{1,4})?$'
                    THEN (r.proposed_parameters ->> 'targetPrice')::numeric END
                   AS target_price
          FROM recommendation r
    ), listing_scope AS (
        SELECT target.*, listing.platform_code,
               listing.marketplace_account_id
          FROM target
          LEFT JOIN core.platform_listing_variant variant
            ON variant.id = target.subject_id
           AND variant.organization_id = target.organization_id
           AND target.subject_kind = 'PLATFORM_LISTING_VARIANT'
          LEFT JOIN core.platform_listing listing
            ON listing.id = variant.platform_listing_id
           AND listing.organization_id = target.organization_id
           AND listing.store_id = target.store_id
    ), mode_inventory AS (
        SELECT scope.id,
               count(declaration.*) AS active_mode_count,
               min(declaration.fulfillment_mode_code) AS only_mode,
               coalesce(jsonb_agg(jsonb_build_object(
                   'id', declaration.id,
                   'fulfillmentModeCode', declaration.fulfillment_mode_code,
                   'effectiveFrom', declaration.effective_from,
                   'effectiveTo', declaration.effective_to)
                   ORDER BY declaration.fulfillment_mode_code COLLATE "C",
                            declaration.id)
                   FILTER (WHERE declaration.id IS NOT NULL), '[]'::jsonb)
                   AS active_modes
          FROM listing_scope scope
          LEFT JOIN core.store_fulfillment_declaration declaration
            ON declaration.store_id = scope.store_id
           AND declaration.status = 'ACTIVE'
           AND declaration.effective_from <= p_as_of
           AND (declaration.effective_to IS NULL
                OR declaration.effective_to > p_as_of)
         GROUP BY scope.id
    ), selected_scope AS (
        SELECT scope.*,
               coalesce(CASE WHEN scope.proposed_parameters ? 'fulfillmentModeCode'
                        THEN scope.proposed_parameters ->> 'fulfillmentModeCode' END,
                   CASE WHEN inventory.active_mode_count = 1
                        THEN inventory.only_mode END) AS fulfillment_mode_code,
               inventory.active_mode_count, inventory.active_modes
          FROM listing_scope scope
          JOIN mode_inventory inventory ON inventory.id = scope.id
    ), selected_mode AS (
        SELECT scope.*,
               (SELECT count(*)
                  FROM core.store_fulfillment_declaration declaration
                 WHERE declaration.store_id = scope.store_id
                   AND declaration.fulfillment_mode_code = scope.fulfillment_mode_code
                   AND declaration.fulfillment_mode_code <> 'UNKNOWN'
                   AND declaration.status = 'ACTIVE'
                   AND declaration.effective_from <= p_as_of
                   AND (declaration.effective_to IS NULL
                        OR declaration.effective_to > p_as_of))
                   AS selected_mode_active_count
          FROM selected_scope scope
    ), current_profiles AS (
        SELECT profile.*
          FROM selected_mode scope
          JOIN core.economics_projection_profile profile
            ON profile.organization_id = scope.organization_id
           AND profile.platform_code = scope.platform_code
           AND profile.marketplace_account_id = scope.marketplace_account_id
           AND profile.store_id = scope.store_id
           AND profile.fulfillment_mode_code = scope.fulfillment_mode_code
           AND profile.status = 'ACTIVE'
           AND profile.effective_from <= p_as_of
           AND (profile.effective_to IS NULL
                OR profile.effective_to > p_as_of)
    ), profile_resolution AS (
        SELECT count(*) AS profile_count FROM current_profiles
    ), single_profile AS (
        SELECT profile.*
          FROM current_profiles profile
         WHERE (SELECT profile_count FROM profile_resolution) = 1
    ), family_contract AS (
        SELECT coalesce(jsonb_agg(jsonb_build_object(
                   'familyCode', family.family_code,
                   'applicability', family.applicability_state,
                   'evidenceReference', family.evidence_reference)
                   ORDER BY family.family_code COLLATE "C"), '[]'::jsonb) AS items
          FROM core.economics_projection_family family
         WHERE family.profile_id = (SELECT id FROM single_profile)
    ), all_components AS (
        SELECT coalesce(jsonb_agg(jsonb_build_object(
                   'id', component.id,
                   'componentCode', component.component_code,
                   'familyCode', component.family_code,
                   'componentKind', component.component_kind,
                   'fixedAmount', component.fixed_amount,
                   'rateValue', component.rate_value,
                   'lowerPriceInclusive', component.lower_price_inclusive,
                   'upperPriceExclusive', component.upper_price_exclusive,
                   'evidenceReference', component.evidence_reference)
                   ORDER BY component.family_code COLLATE "C",
                            component.component_code COLLATE "C",
                            component.lower_price_inclusive NULLS FIRST,
                            component.id), '[]'::jsonb) AS items
          FROM core.economics_projection_component component
         WHERE component.profile_id = (SELECT id FROM single_profile)
    ), selected_components AS (
        SELECT coalesce(jsonb_agg(jsonb_build_object(
                   'id', component.id,
                   'componentCode', component.component_code,
                   'familyCode', component.family_code)
                   ORDER BY component.family_code COLLATE "C",
                            component.component_code COLLATE "C", component.id),
                   '[]'::jsonb) AS items
          FROM core.economics_projection_component component
          JOIN selected_mode scope ON true
         WHERE component.profile_id = (SELECT id FROM single_profile)
           AND scope.target_price IS NOT NULL
           AND (component.lower_price_inclusive IS NULL
                OR scope.target_price >= component.lower_price_inclusive)
           AND (component.upper_price_exclusive IS NULL
                OR scope.target_price < component.upper_price_exclusive)
    ), latest_watermarks AS (
        SELECT DISTINCT ON (watermark.feed_code)
               watermark.*
          FROM selected_mode scope
          JOIN core.source_feed_watermark watermark
            ON watermark.organization_id = scope.organization_id
           AND watermark.platform_code = scope.platform_code
           AND watermark.marketplace_account_id = scope.marketplace_account_id
           AND watermark.store_id = scope.store_id
           AND watermark.verification_state = 'VERIFIED'
           AND watermark.recorded_at <= p_as_of
         ORDER BY watermark.feed_code, watermark.recorded_at DESC,
                  watermark.id DESC
    ), watermarks AS (
        SELECT coalesce(jsonb_agg(jsonb_build_object(
                   'id', watermark.id, 'feedCode', watermark.feed_code,
                   'sourceUpdatedAt', watermark.source_updated_at,
                   'ingestedAt', watermark.ingested_at,
                   'reconciledAt', watermark.reconciled_at,
                   'effectiveAt', coalesce(watermark.reconciled_at,
                       watermark.source_updated_at, watermark.ingested_at),
                   'evidenceReference', watermark.evidence_reference)
                   ORDER BY watermark.feed_code COLLATE "C"), '[]'::jsonb) AS items
          FROM latest_watermarks watermark
    )
    SELECT ops.price_authority_snapshot_v1_at(scope.id, p_as_of)
           || jsonb_build_object('economics', jsonb_build_object(
               'parameterContractValid', scope.parameter_contract_valid,
               'targetPrice', scope.target_price,
               'fulfillmentModeCode', scope.fulfillment_mode_code,
               'activeFulfillmentModeCount', scope.active_mode_count,
               'activeFulfillmentModes', scope.active_modes,
               'selectedModeActiveCount', scope.selected_mode_active_count,
               'profileCount', resolution.profile_count,
               'profile', CASE WHEN profile.id IS NULL THEN NULL
                    ELSE jsonb_build_object(
                        'id', profile.id, 'version', profile.profile_version,
                        'organizationId', profile.organization_id,
                        'platformCode', profile.platform_code,
                        'accountId', profile.marketplace_account_id,
                        'storeId', profile.store_id,
                        'fulfillmentModeCode', profile.fulfillment_mode_code,
                        'currencyCode', profile.currency_code,
                        'effectiveFrom', profile.effective_from,
                        'effectiveTo', profile.effective_to,
                        'verificationState', profile.verification_state,
                        'verifiedAt', profile.verified_at,
                        'verificationExpiresAt', profile.verification_expires_at,
                        'evidenceReference', profile.evidence_reference,
                        'minimumSupportedPrice', profile.minimum_supported_price,
                        'maximumSupportedPrice', profile.maximum_supported_price)
                    END,
               'familyContract', families.items,
               'allComponents', components.items,
               'selectedComponents', selected.items,
               'watermarks', watermarks.items))
      FROM selected_mode scope
      CROSS JOIN profile_resolution resolution
      LEFT JOIN single_profile profile ON true
      CROSS JOIN family_contract families
      CROSS JOIN all_components components
      CROSS JOIN selected_components selected
      CROSS JOIN watermarks
$_$;

CREATE FUNCTION ops.price_authority_snapshot_v1(p_recommendation_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
    SELECT jsonb_build_object(
        'proposal', jsonb_build_object(
            'id', r.id, 'organizationId', r.organization_id, 'storeId', r.store_id,
            'subjectKind', r.subject_kind, 'subjectId', r.subject_id,
            'actionKind', r.action_kind, 'parameters', r.proposed_parameters,
            'risk', r.risk_label, 'window', r.window_code,
            'validUntil', r.valid_until, 'entityDigest', r.entity_version_digest),
        'platformCode', l.platform_code, 'accountId', l.marketplace_account_id,
        'nativeListingKey', l.native_listing_key, 'nativeVariantKey', v.native_variant_key,
        'metrics', coalesce(metrics.items, '[]'::jsonb),
        'currentEntityDigest', metrics.entity_digest,
        'prior', prior.item, 'mapping', mapping.item, 'policy', policy.item,
        'policyLimits', coalesce(limits.items, '[]'::jsonb))
      FROM ops.recommendation r
      LEFT JOIN core.platform_listing_variant v
        ON v.id = r.subject_id AND v.organization_id = r.organization_id
       AND r.subject_kind = 'PLATFORM_LISTING_VARIANT'
      LEFT JOIN core.platform_listing l
        ON l.id = v.platform_listing_id AND l.organization_id = r.organization_id
       AND l.store_id = r.store_id
      LEFT JOIN LATERAL (
          SELECT jsonb_agg(to_jsonb(m) ORDER BY m.metric_code COLLATE "C") AS items,
                 encode(sha256(convert_to(string_agg(
                     m.metric_code || chr(31) || m.value_state || chr(31)
                     || m.input_digest || chr(31), '' ORDER BY m.metric_code COLLATE "C"),
                     'UTF8')), 'hex') AS entity_digest
            FROM (
                SELECT DISTINCT ON (mv.metric_code) mv.*
                  FROM mart.metric_value mv
                 WHERE mv.organization_id = r.organization_id
                   AND mv.subject_kind = r.subject_kind AND mv.subject_id = r.subject_id
                   AND mv.window_code = r.window_code
                 ORDER BY mv.metric_code, mv.computed_at DESC, mv.id DESC
            ) m
      ) metrics ON true
      LEFT JOIN LATERAL (
          SELECT jsonb_build_object('id', p.id, 'currency', p.currency_code,
                     'price', coalesce(p.discount_price, p.selling_price, p.list_price),
                     'observedAt', p.observed_at, 'provenanceId', p.provenance_id) AS item
            FROM core.listing_price_observation p
           WHERE p.organization_id = r.organization_id
             AND p.platform_listing_variant_id = v.id
             AND p.observed_at <= statement_timestamp()
             AND NOT EXISTS (SELECT 1 FROM core.listing_price_observation later
                              WHERE later.supersedes_fact_id = p.id)
           ORDER BY p.observed_at DESC, p.id DESC LIMIT 1
      ) prior ON true
      LEFT JOIN LATERAL (
          SELECT to_jsonb(m) AS item, m.product_variant_id
            FROM core.listing_mapping m
           WHERE m.organization_id = r.organization_id
             AND m.platform_listing_variant_id = v.id AND m.status = 'ACTIVE'
             AND m.effective_from <= statement_timestamp()
             AND (m.effective_to IS NULL OR m.effective_to > statement_timestamp())
           ORDER BY m.effective_from DESC, m.id DESC LIMIT 1
      ) mapping ON true
      LEFT JOIN LATERAL (
          SELECT to_jsonb(p) AS item, p.id
            FROM ops.commercial_policy p
           WHERE p.organization_id = r.organization_id AND p.status = 'ACTIVE'
             AND p.effective_from <= statement_timestamp()
             AND (p.effective_to IS NULL OR p.effective_to > statement_timestamp())
             AND (p.scope_kind = 'ORGANIZATION'
                  OR (p.scope_kind = 'PLATFORM' AND p.platform_code = l.platform_code)
                  OR (p.scope_kind = 'STORE' AND p.store_ref_id = r.store_id)
                  OR (p.scope_kind = 'PRODUCT_VARIANT'
                      AND p.product_variant_ref_id = mapping.product_variant_id))
           ORDER BY CASE p.scope_kind WHEN 'PRODUCT_VARIANT' THEN 1 WHEN 'STORE' THEN 2
                        WHEN 'PLATFORM' THEN 3 ELSE 4 END,
                    p.effective_from DESC, p.id DESC LIMIT 1
      ) policy ON true
      LEFT JOIN LATERAL (
          SELECT jsonb_agg(to_jsonb(lim) ORDER BY lim.limit_code) AS items
            FROM ops.commercial_policy_limit lim WHERE lim.policy_id = policy.id
      ) limits ON true
     WHERE r.id = p_recommendation_id
$$;

CREATE FUNCTION ops.price_authority_snapshot_v1_at(p_recommendation_id uuid, p_as_of timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
    SELECT jsonb_build_object(
        'proposal', jsonb_build_object(
            'id', r.id, 'organizationId', r.organization_id, 'storeId', r.store_id,
            'subjectKind', r.subject_kind, 'subjectId', r.subject_id,
            'actionKind', r.action_kind, 'parameters', r.proposed_parameters,
            'risk', r.risk_label, 'window', r.window_code,
            'validUntil', r.valid_until, 'entityDigest', r.entity_version_digest),
        'platformCode', l.platform_code, 'accountId', l.marketplace_account_id,
        'nativeListingKey', l.native_listing_key, 'nativeVariantKey', v.native_variant_key,
        'metrics', coalesce(metrics.items, '[]'::jsonb),
        'currentEntityDigest', metrics.entity_digest,
        'prior', prior.item, 'mapping', mapping.item,
        'mappingConflictOpen', coalesce(mapping.conflict_open, false),
        'policy', policy.item, 'policyLimits', coalesce(limits.items, '[]'::jsonb))
      FROM ops.recommendation r
      LEFT JOIN core.platform_listing_variant v
        ON v.id = r.subject_id AND v.organization_id = r.organization_id
       AND r.subject_kind = 'PLATFORM_LISTING_VARIANT'
      LEFT JOIN core.platform_listing l
        ON l.id = v.platform_listing_id AND l.organization_id = r.organization_id
       AND l.store_id = r.store_id
      LEFT JOIN LATERAL (
          SELECT jsonb_agg(to_jsonb(m) ORDER BY m.metric_code COLLATE "C") AS items,
                 encode(sha256(convert_to(string_agg(
                     m.metric_code || chr(31) || m.value_state || chr(31)
                     || m.input_digest || chr(31), '' ORDER BY m.metric_code COLLATE "C"),
                     'UTF8')), 'hex') AS entity_digest
            FROM (
                SELECT DISTINCT ON (mv.metric_code) mv.*
                  FROM mart.metric_value mv
                 WHERE mv.organization_id = r.organization_id
                   AND mv.subject_kind = r.subject_kind AND mv.subject_id = r.subject_id
                   AND mv.window_code = r.window_code AND mv.computed_at <= p_as_of
                 ORDER BY mv.metric_code, mv.computed_at DESC, mv.id DESC
            ) m
      ) metrics ON true
      LEFT JOIN LATERAL (
          SELECT jsonb_build_object('id', p.id, 'currency', p.currency_code,
                     'price', coalesce(p.discount_price, p.selling_price, p.list_price),
                     'observedAt', p.observed_at, 'provenanceId', p.provenance_id) AS item
            FROM core.listing_price_observation p
           WHERE p.organization_id = r.organization_id
             AND p.platform_listing_variant_id = v.id
             AND p.observed_at <= p_as_of
             AND NOT EXISTS (SELECT 1 FROM core.listing_price_observation later
                              WHERE later.supersedes_fact_id = p.id
                                AND later.observed_at <= p_as_of)
           ORDER BY p.observed_at DESC, p.id DESC LIMIT 1
      ) prior ON true
      LEFT JOIN LATERAL (
          SELECT to_jsonb(m) AS item, m.product_variant_id,
                 EXISTS (
                     SELECT 1 FROM core.mapping_conflict conflict
                      WHERE conflict.platform_listing_variant_id = v.id
                        AND conflict.state = 'OPEN'
                        AND conflict.detected_at <= p_as_of) AS conflict_open
            FROM core.listing_mapping m
           WHERE m.organization_id = r.organization_id
             AND m.platform_listing_variant_id = v.id AND m.status = 'ACTIVE'
             AND m.effective_from <= p_as_of
             AND (m.effective_to IS NULL OR m.effective_to > p_as_of)
           ORDER BY m.effective_from DESC, m.id DESC LIMIT 1
      ) mapping ON true
      LEFT JOIN LATERAL (
          SELECT to_jsonb(p) AS item, p.id
            FROM ops.commercial_policy p
           WHERE p.organization_id = r.organization_id AND p.status = 'ACTIVE'
             AND p.effective_from <= p_as_of
             AND (p.effective_to IS NULL OR p.effective_to > p_as_of)
             AND (p.scope_kind = 'ORGANIZATION'
                  OR (p.scope_kind = 'PLATFORM' AND p.platform_code = l.platform_code)
                  OR (p.scope_kind = 'STORE' AND p.store_ref_id = r.store_id)
                  OR (p.scope_kind = 'PRODUCT_VARIANT'
                      AND p.product_variant_ref_id = mapping.product_variant_id))
           ORDER BY CASE p.scope_kind WHEN 'PRODUCT_VARIANT' THEN 1 WHEN 'STORE' THEN 2
                        WHEN 'PLATFORM' THEN 3 ELSE 4 END,
                    p.effective_from DESC, p.id DESC LIMIT 1
      ) policy ON true
      LEFT JOIN LATERAL (
          SELECT jsonb_agg(to_jsonb(lim) ORDER BY lim.limit_code) AS items
            FROM ops.commercial_policy_limit lim WHERE lim.policy_id = policy.id
      ) limits ON true
     WHERE r.id = p_recommendation_id
$$;

CREATE FUNCTION ops.price_change_parameter_contract_is_valid(p_parameters jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
    SELECT coalesce(
        jsonb_typeof(p_parameters) = 'object'
        AND (p_parameters - ARRAY['targetPrice', 'fulfillmentModeCode']) = '{}'::jsonb
        AND CASE
            WHEN jsonb_typeof(p_parameters -> 'targetPrice') = 'string'
             AND (p_parameters ->> 'targetPrice')
                    ~ '^[0-9]{1,14}([.][0-9]{1,4})?$'
            THEN (p_parameters ->> 'targetPrice')::numeric > 0
            ELSE false
        END
        AND (NOT (p_parameters ? 'fulfillmentModeCode')
             OR (jsonb_typeof(p_parameters -> 'fulfillmentModeCode') = 'string'
                 AND (p_parameters ->> 'fulfillmentModeCode')
                        ~ '^[A-Z][A-Z0-9_]{1,62}$'
                 AND (p_parameters ->> 'fulfillmentModeCode') <> 'UNKNOWN')),
        false)
$_$;

CREATE FUNCTION ops.price_command_attempt_completes_once() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.outcome_class <> 'IN_FLIGHT' THEN
        RAISE EXCEPTION 'price command attempt % is already completed', OLD.id
            USING ERRCODE = 'MO037';
    END IF;

    IF NEW.outcome_class = 'IN_FLIGHT' THEN
        RAISE EXCEPTION 'completing price command attempt % must classify the answer',
            OLD.id
            USING ERRCODE = 'MO037';
    END IF;

    -- Everything that identifies the call is fixed at the moment it was made.
    IF NEW.id <> OLD.id
        OR NEW.command_id <> OLD.command_id
        OR NEW.attempt_no <> OLD.attempt_no
        OR NEW.purpose <> OLD.purpose
        OR NEW.fence_token <> OLD.fence_token
        OR NEW.lease_owner <> OLD.lease_owner
        OR NEW.started_at <> OLD.started_at
        OR NEW.correlation_id <> OLD.correlation_id
        OR NEW.request_digest IS DISTINCT FROM OLD.request_digest
        OR NEW.operation_snapshot IS DISTINCT FROM OLD.operation_snapshot
        OR NEW.expected_version_token IS DISTINCT FROM OLD.expected_version_token
    THEN
        RAISE EXCEPTION 'the identity of price command attempt % cannot change', OLD.id
            USING ERRCODE = 'MO037';
    END IF;

    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.price_command_authority_matches(p_command_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
    SELECT ops.price_command_authority_matches_v1(p_command_id)
       AND ops.r2_price_authority_is_current(
            command.authority_snapshot, statement_timestamp())
      FROM ops.price_command command
     WHERE command.id = p_command_id
$$;

CREATE FUNCTION ops.price_command_authority_matches_v1(p_command_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
    SELECT coalesce(bool_and(
        c.authority_snapshot = ops.price_authority_snapshot(r.id)
        AND a.authority_snapshot = c.authority_snapshot
        AND a.recommendation_id = r.id AND a.organization_id = c.organization_id
        AND r.organization_id = c.organization_id AND r.store_id = c.store_id
        AND r.subject_kind = 'PLATFORM_LISTING_VARIANT'
        AND r.subject_id = c.platform_listing_variant_id AND r.action_kind = 'PRICE_CHANGE'
        AND c.entity_version_digest = r.entity_version_digest
        AND c.entity_version_digest = c.authority_snapshot ->> 'currentEntityDigest'
        AND c.authority_snapshot #>> '{mapping,id}' IS NOT NULL
        AND c.authority_snapshot #>> '{policy,id}' IS NOT NULL
        AND ops.price_change_parameter_contract_is_valid(r.proposed_parameters)
        AND c.fulfillment_mode_code =
            c.authority_snapshot #>> '{economics,fulfillmentModeCode}'
        AND c.idempotency_key = 'pc-' || r.id::text
        AND c.target_price = CASE WHEN (r.proposed_parameters ->> 'targetPrice')
            ~ '^[0-9]{1,14}([.][0-9]{1,4})?$'
            THEN (r.proposed_parameters ->> 'targetPrice')::numeric END
        AND c.prior_price = (c.authority_snapshot #>> '{prior,price}')::numeric
        AND c.prior_price > 0 AND c.target_price <> c.prior_price
        AND c.currency_code = c.authority_snapshot #>> '{prior,currency}'
        AND c.prior_price_observation_id::text = c.authority_snapshot #>> '{prior,id}'
        AND c.platform_code = c.authority_snapshot ->> 'platformCode'
        AND cap.capability_code = 'price-change' AND cap.read_write_class = 'WRITE'
        AND cap.platform_code = c.platform_code
        AND EXISTS (SELECT 1 FROM core.organization org
                    JOIN core.store store ON store.organization_id=org.id
                    JOIN core.marketplace_account account ON account.id=store.marketplace_account_id
                    JOIN core.legal_entity legal ON legal.id=account.legal_entity_id
                    JOIN core.platform_listing listing ON listing.store_id=store.id
                    JOIN core.platform_listing_variant variant ON variant.platform_listing_id=listing.id
                    JOIN core.product_variant sku ON sku.id=(c.authority_snapshot #>> '{mapping,product_variant_id}')::uuid
                    JOIN core.product product ON product.id=sku.product_id
                    WHERE org.id=c.organization_id AND store.id=c.store_id AND variant.id=c.platform_listing_variant_id
                      AND org.status='ACTIVE' AND store.status='ACTIVE' AND account.status='ACTIVE'
                      AND legal.status='ACTIVE' AND listing.status='OBSERVED' AND variant.status='OBSERVED'
                      AND sku.status='ACTIVE' AND product.status='ACTIVE')
        AND EXISTS (SELECT 1 FROM ops.guardrail_evaluation g
                     WHERE g.recommendation_id = r.id AND g.organization_id = c.organization_id
                       AND g.purpose = 'EXECUTION' AND g.outcome = 'PASS'
                       AND g.authority_snapshot = c.authority_snapshot
                       AND g.policy_id::text = c.authority_snapshot #>> '{policy,id}'
                       AND g.policy_version::text = c.authority_snapshot #>> '{policy,policy_version}')
    ), false)
      FROM ops.price_command c
      JOIN ops.recommendation r ON r.id = c.recommendation_id
      JOIN ops.approval_decision a ON a.id = c.approval_decision_id
      JOIN platform.platform_capability cap ON cap.id = c.capability_id
     WHERE c.id = p_command_id
$_$;

CREATE FUNCTION ops.price_command_compensation_is_observed() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    latest_match text;
BEGIN
    IF NEW.state <> 'COMPENSATED' OR OLD.state = 'COMPENSATED' THEN
        RETURN NEW;
    END IF;

    SELECT readback.match_state INTO latest_match
      FROM ops.price_command_readback AS readback
      JOIN raw.price_response_observation evidence ON evidence.id = readback.raw_observation_id
      JOIN ops.price_command_attempt attempt ON attempt.id = readback.attempt_id
     WHERE readback.command_id = NEW.id
       AND evidence.command_id = NEW.id AND evidence.attempt_id = attempt.id
       AND attempt.command_id = NEW.id AND attempt.purpose = 'READBACK'
       AND attempt.fence_token = NEW.fence_token
       AND evidence.observed_price = NEW.prior_price
       AND evidence.observed_currency = NEW.currency_code
       AND EXISTS (SELECT 1 FROM ops.price_command_attempt restore
           WHERE restore.command_id=NEW.id AND restore.fence_token=NEW.fence_token
             AND restore.purpose='RESTORE' AND restore.outcome_class='ACCEPTED'
             AND restore.raw_observation_id IS NOT NULL
             AND restore.completed_at < attempt.started_at)
     ORDER BY readback.observed_at DESC, readback.id DESC
     LIMIT 1;

    IF latest_match IS DISTINCT FROM 'MATCHES_PRIOR' OR NOT EXISTS (
        SELECT 1 FROM ops.price_command_attempt restore
         WHERE restore.command_id = NEW.id AND restore.fence_token = NEW.fence_token
           AND restore.purpose = 'RESTORE' AND restore.outcome_class = 'ACCEPTED'
           AND restore.raw_observation_id IS NOT NULL) THEN
        RAISE EXCEPTION
            'price command % cannot be compensated: the latest readback is %',
            NEW.id, coalesce(latest_match, 'absent')
            USING ERRCODE = 'MO038',
                  HINT = 'observe the restored value before claiming compensation';
    END IF;

    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.price_json_pointer(p_document jsonb, p_pointer text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
    SELECT p_document #>> array_agg(replace(replace(component, '~1', '/'), '~0', '~') ORDER BY ordinal)
      FROM unnest(string_to_array(substring(p_pointer FROM 2), '/')) WITH ORDINALITY part(component, ordinal)
$$;

CREATE FUNCTION ops.price_json_value(p_document jsonb, p_pointer text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
    SELECT p_document #> array_agg(replace(replace(component,'~1','/'),'~0','~') ORDER BY ordinal)
      FROM unnest(string_to_array(substring(p_pointer FROM 2),'/')) WITH ORDINALITY part(component,ordinal)
$$;

CREATE FUNCTION ops.publish_ad_manual_policy(p_content jsonb, p_proof text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'iam', 'platform', 'pg_temp'
    AS $$
DECLARE policy core.ad_manual_policy%ROWTYPE; grant_row iam.ad_invocation_grant%ROWTYPE;
BEGIN
 policy:=jsonb_populate_record(NULL::core.ad_manual_policy,p_content);
 grant_row:=ops.consume_ad_control_invocation(p_proof,'MANUAL_POLICY_PUBLISH',policy.id,policy.store_id);
 IF policy.organization_id<>grant_row.organization_id OR NOT ops.ad_manual_actor_scoped(grant_row.actor_user_id,
   policy.organization_id,policy.store_id,NULL,'OWNER','ADVERTISING_POLICY_MANAGE') THEN
   RAISE EXCEPTION 'manual business policy requires scoped Owner' USING ERRCODE='MO064'; END IF;
 IF NOT EXISTS(SELECT 1 FROM core.store s JOIN core.marketplace_account a ON a.id=s.marketplace_account_id
   JOIN platform.ad_semantic_profile p ON p.id=policy.semantic_profile_id AND p.platform_code=a.platform_code
   WHERE s.id=policy.store_id AND s.organization_id=policy.organization_id AND p.status='ACTIVE') THEN
   RAISE EXCEPTION 'manual policy native profile does not belong to Store' USING ERRCODE='MO097'; END IF;
 IF EXISTS(SELECT 1 FROM core.ad_manual_policy p WHERE p.organization_id=policy.organization_id
   AND p.store_id=policy.store_id AND p.cause_code=policy.cause_code AND p.action_kind=policy.action_kind
   AND tstzrange(p.effective_from,p.effective_to,'[)') && tstzrange(policy.effective_from,policy.effective_to,'[)')) THEN
   RAISE EXCEPTION 'manual policy scope overlaps an existing immutable version' USING ERRCODE='MO097'; END IF;
 IF policy.action_kind='AD_STATUS_CHANGE' AND NOT EXISTS(SELECT 1 FROM platform.ad_semantic_profile p
   WHERE p.id=policy.semantic_profile_id AND p.status_semantics->>policy.target_status IN ('RUNNING','PAUSED','STOPPED')) THEN
   RAISE EXCEPTION 'native status is not declared in the exact profile' USING ERRCODE='MO097'; END IF;
 policy.approved_by_user_id:=grant_row.actor_user_id; policy.approved_at:=clock_timestamp();
 INSERT INTO core.ad_manual_policy SELECT policy.*;
 RETURN policy.id;
END $$;

CREATE FUNCTION ops.r2_price_authority_is_current(p_snapshot jsonb, p_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    max_age bigint;
    profile jsonb;
    family_count integer;
    watermark_count integer;
BEGIN
    IF p_snapshot IS NULL OR p_at IS NULL THEN RETURN false; END IF;
    SELECT (item ->> 'duration_seconds')::bigint INTO max_age
      FROM jsonb_array_elements(coalesce(p_snapshot -> 'policyLimits', '[]'::jsonb)) item
     WHERE item ->> 'limit_code' = 'MAX_INPUT_AGE_SECONDS';
    profile := p_snapshot #> '{economics,profile}';
    IF max_age IS NULL OR max_age < 0 OR profile IS NULL
       OR coalesce((p_snapshot #>> '{economics,parameterContractValid}')::boolean,
                   false) IS NOT TRUE
       OR (p_snapshot #>> '{economics,targetPrice}') IS NULL
       OR (p_snapshot #>> '{economics,fulfillmentModeCode}') IS NULL
       OR (p_snapshot #>> '{economics,fulfillmentModeCode}') = 'UNKNOWN'
       OR (p_snapshot #>> '{economics,profileCount}')::integer <> 1
       OR (p_snapshot #>> '{economics,selectedModeActiveCount}')::integer <> 1
       OR profile ->> 'verificationState' NOT IN (
            'ENGINEERING_VERIFIED', 'REAL_ACCOUNT_VERIFIED')
       OR (profile ->> 'verifiedAt')::timestamptz > p_at
       OR (profile ->> 'effectiveFrom')::timestamptz > p_at
       OR (profile ->> 'effectiveTo') IS NOT NULL
          AND (profile ->> 'effectiveTo')::timestamptz <= p_at
       OR (profile ->> 'verificationExpiresAt') IS NOT NULL
          AND (profile ->> 'verificationExpiresAt')::timestamptz <= p_at THEN
        RETURN false;
    END IF;

    SELECT count(*) INTO family_count
      FROM jsonb_array_elements(
          coalesce(p_snapshot #> '{economics,familyContract}', '[]'::jsonb));
    IF family_count <> 8 THEN RETURN false; END IF;

    -- Every required family has component authority. Every component code has
    -- exactly one price-applicable tier; overlap and gaps both fail closed.
    IF EXISTS (
        SELECT 1
          FROM jsonb_array_elements(
                   p_snapshot #> '{economics,familyContract}') family
         WHERE family ->> 'applicability' = 'REQUIRED'
           AND NOT EXISTS (
               SELECT 1 FROM jsonb_array_elements(
                   p_snapshot #> '{economics,allComponents}') component
                WHERE component ->> 'familyCode' = family ->> 'familyCode'))
       OR EXISTS (
        SELECT 1
          FROM jsonb_array_elements(
                   p_snapshot #> '{economics,allComponents}') component
          JOIN jsonb_array_elements(
                   p_snapshot #> '{economics,familyContract}') family
            ON family ->> 'familyCode' = component ->> 'familyCode'
         WHERE family ->> 'applicability' = 'VERIFIED_NOT_APPLICABLE')
       OR EXISTS (
        SELECT 1
          FROM (SELECT component ->> 'familyCode' AS family_code,
                       component ->> 'componentCode' AS component_code
                  FROM jsonb_array_elements(
                      p_snapshot #> '{economics,allComponents}') component
                 GROUP BY 1, 2) authority
         WHERE (SELECT count(*)
                  FROM jsonb_array_elements(
                      p_snapshot #> '{economics,selectedComponents}') selected
                 WHERE selected ->> 'familyCode' = authority.family_code
                   AND selected ->> 'componentCode' = authority.component_code) <> 1) THEN
        RETURN false;
    END IF;

    SELECT count(DISTINCT watermark ->> 'feedCode') INTO watermark_count
      FROM jsonb_array_elements(
          coalesce(p_snapshot #> '{economics,watermarks}', '[]'::jsonb)) watermark;
    IF watermark_count <> 8 OR EXISTS (
        SELECT 1
          FROM unnest(ARRAY['PRICE','STOCK','SALES','RETURNS','FINANCE_FEES',
                            'ADVERTISING','INTERNAL_COST','COMMERCIAL_INPUTS']) feed
         WHERE NOT EXISTS (
             SELECT 1 FROM jsonb_array_elements(
                 p_snapshot #> '{economics,watermarks}') watermark
              WHERE watermark ->> 'feedCode' = feed)
            OR EXISTS (
             SELECT 1 FROM jsonb_array_elements(
                 p_snapshot #> '{economics,watermarks}') watermark
              WHERE watermark ->> 'feedCode' = feed
                AND ((watermark ->> 'effectiveAt') IS NULL
                  OR (watermark ->> 'effectiveAt')::timestamptz > p_at
                  OR extract(epoch FROM (
                      p_at - (watermark ->> 'effectiveAt')::timestamptz)) > max_age))) THEN
        RETURN false;
    END IF;
    RETURN true;
END;
$$;

CREATE FUNCTION ops.reconcile_ad_manual_configuration_reservation(p_packet uuid, p_evidence text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'pg_temp'
    AS $$
DECLARE packet ops.ad_manual_execution_packet%ROWTYPE; held ops.ad_action_reservation%ROWTYPE;
 proven boolean;
BEGIN
 SELECT * INTO packet FROM ops.ad_manual_execution_packet WHERE id=p_packet;
 IF packet.id IS NULL OR packet.reservation_id IS NULL THEN
  RAISE EXCEPTION 'started manual reservation is required' USING ERRCODE='MO097'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext('ad_action_reservation'),hashtext(packet.organization_id::text));
 SELECT * INTO packet FROM ops.ad_manual_execution_packet WHERE id=p_packet FOR UPDATE;
 SELECT * INTO held FROM ops.ad_action_reservation WHERE id=packet.reservation_id FOR UPDATE;
 IF held.id IS NULL OR held.organization_id<>packet.organization_id
  OR held.intervention_kind<>'CONFIRMED_MANUAL_PACKET' OR held.intervention_reference_id<>packet.id THEN
  RAISE EXCEPTION 'exact original manual reservation is required' USING ERRCODE='MO097'; END IF;
 proven:=packet.state='MANUAL_CONFIGURATION_VERIFIED' AND ops.ad_manual_observation_is_qualified(packet.current_proof_id);
 IF held.state='ACTIVE' THEN
  UPDATE ops.ad_action_reservation SET configuration_resolved=proven,unknown_or_mismatch_open=NOT proven,
    version=version+1 WHERE id=held.id
    AND (configuration_resolved IS DISTINCT FROM proven OR unknown_or_mismatch_open IS DISTINCT FROM NOT proven);
 ELSIF NOT proven THEN
  IF NOT EXISTS(SELECT 1 FROM ops.ad_action_reservation other WHERE other.organization_id=held.organization_id
    AND other.id<>held.id AND other.state='ACTIVE'
    AND (other.ad_native_object_id=held.ad_native_object_id OR other.product_variant_ids && held.product_variant_ids)) THEN
   UPDATE ops.ad_action_reservation SET state='ACTIVE',released_at=NULL,release_reason=NULL,
     configuration_resolved=false,unknown_or_mismatch_open=true,early_observation_complete=false,
     version=version+1 WHERE id=held.id;
  ELSE
   -- Existing exact affected-set containment also covers intersecting variants.
   -- Its established trigger invalidates execution authority and marks in-flight
   -- work uncertain, while preserving every canonical observation and hold ID.
   IF NOT EXISTS(SELECT 1 FROM ops.ad_containment c WHERE c.organization_id=packet.organization_id
     AND c.containment_kind='EMERGENCY_ENTITY_HOLD' AND c.scope_kind='AFFECTED_SET'
     AND c.cause_class='EXECUTION_INTEGRITY' AND c.affected_set_digest=packet.affected_set_digest
     AND c.activated_by_trigger='AD_MANUAL_CONFIGURATION_UNCERTAIN' AND c.state<>'REENABLED') THEN
    INSERT INTO ops.ad_containment(id,organization_id,containment_kind,scope_kind,platform_code,store_id,
      ad_native_object_id,affected_set_digest,capability_code,cause_class,reason,evidence_reference,
      activated_by_trigger,activated_at,state,correlation_id,created_at,updated_at,review_owner_user_id)
    VALUES(gen_random_uuid(),packet.organization_id,'EMERGENCY_ENTITY_HOLD','AFFECTED_SET',packet.platform_code,packet.store_id,
      packet.ad_native_object_id,packet.affected_set_digest,'ad-bid-change','EXECUTION_INTEGRITY',
      'Later manual configuration uncertainty overlaps a newer intervention; preserve both factual histories',p_evidence,
      'AD_MANUAL_CONFIGURATION_UNCERTAIN',clock_timestamp(),'ACTIVE','manual:'||packet.id,
      clock_timestamp(),clock_timestamp(),packet.endorser_user_id);
   END IF;
  END IF;
 END IF;
END $$;

CREATE FUNCTION ops.record_ad_bid_command_readback(p_readback_id uuid, p_command_id uuid, p_attempt_id uuid, p_fence bigint, p_owner text, p_correlation_id text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'raw', 'pg_temp'
    AS $$
DECLARE
    command     ops.ad_bid_command%ROWTYPE;
    attempt     ops.ad_bid_command_attempt%ROWTYPE;
    observation raw.ad_bid_response_observation%ROWTYPE;
    match       text;
BEGIN
    SELECT * INTO command FROM ops.ad_bid_command WHERE id = p_command_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'command does not exist' USING ERRCODE = 'MO090';
    END IF;
    IF command.fence_token <> p_fence OR command.lease_owner IS DISTINCT FROM p_owner
        OR command.lease_expires_at IS NULL OR command.lease_expires_at <= clock_timestamp() THEN
        RAISE EXCEPTION 'the lease that authorised this readback is not current'
            USING ERRCODE = 'MO090';
    END IF;

    SELECT * INTO attempt FROM ops.ad_bid_command_attempt WHERE id = p_attempt_id;
    IF NOT FOUND OR attempt.command_id <> p_command_id OR attempt.purpose <> 'READBACK'
        OR attempt.fence_token <> p_fence OR attempt.lease_owner IS DISTINCT FROM p_owner
        OR attempt.outcome_class = 'IN_FLIGHT' OR attempt.raw_observation_id IS NULL THEN
        RAISE EXCEPTION 'a readback needs a completed readback attempt at this fence'
            USING ERRCODE = 'MO093';
    END IF;

    SELECT * INTO observation FROM raw.ad_bid_response_observation
     WHERE id = attempt.raw_observation_id;

    -- Four outcomes, derived. There is no tolerance: an equal value is equal.
    match := CASE
        WHEN observation.observed_bid IS NULL OR observation.observed_unit IS NULL THEN 'UNREADABLE'
        WHEN observation.observed_unit IS DISTINCT FROM command.bid_unit_code THEN 'DIFFERENT'
        WHEN observation.observed_currency IS DISTINCT FROM command.currency_code THEN 'DIFFERENT'
        WHEN observation.observed_bid = command.target_bid_amount THEN 'MATCHES_TARGET'
        WHEN observation.observed_bid = command.prior_bid_amount THEN 'MATCHES_PRIOR'
        ELSE 'DIFFERENT'
    END;

    INSERT INTO ops.ad_bid_command_readback (
        id, command_id, attempt_id, observed_at, observed_bid, currency_code,
        bid_unit_code, match_state, raw_observation_id, correlation_id)
    VALUES (p_readback_id, p_command_id, p_attempt_id, clock_timestamp(),
        CASE WHEN match = 'UNREADABLE' THEN NULL ELSE observation.observed_bid END,
        CASE WHEN match = 'UNREADABLE' THEN NULL ELSE observation.observed_currency END,
        CASE WHEN match = 'UNREADABLE' THEN NULL ELSE observation.observed_unit END,
        match, attempt.raw_observation_id, p_correlation_id);

    RETURN match;
END;
$$;

CREATE FUNCTION ops.record_ad_exception_case_boundary() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$ BEGIN
 IF ROW(OLD.superseded_at,OLD.cause_code,OLD.lane,OLD.semantic_profile_id,OLD.affected_set_id,
        OLD.policy_version_digest,OLD.bundle_id)
  IS DISTINCT FROM ROW(NEW.superseded_at,NEW.cause_code,NEW.lane,NEW.semantic_profile_id,NEW.affected_set_id,
        NEW.policy_version_digest,NEW.bundle_id) THEN
  INSERT INTO ops.ad_exception_authority_change(exception_id,source_table,source_id)
  SELECT id,'mart.ad_case',OLD.id FROM ops.ad_accepted_exception
   WHERE case_id=OLD.id AND state IN('REQUESTED','ENDORSED','ACTIVE');
 END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION ops.record_ad_exception_identity_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE actor uuid;
BEGIN
 IF to_jsonb(NEW) IS NOT DISTINCT FROM to_jsonb(OLD) THEN RETURN NEW; END IF;
 IF TG_TABLE_NAME='user_account' THEN actor:=OLD.id; ELSE actor:=OLD.user_id; END IF;
 INSERT INTO ops.ad_exception_authority_change(exception_id,source_table,source_id)
 SELECT x.id,TG_TABLE_NAME,OLD.id FROM ops.ad_accepted_exception x
 WHERE x.state IN('REQUESTED','ENDORSED','ACTIVE') AND actor IN(x.requester_user_id,x.endorser_user_id,x.approver_user_id);
 RETURN NEW;
END $$;

CREATE FUNCTION ops.record_ad_exception_policy_boundary() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$ BEGIN
 IF to_jsonb(OLD) IS DISTINCT FROM to_jsonb(NEW) THEN
  INSERT INTO ops.ad_exception_authority_change(exception_id,source_table,source_id)
  SELECT x.id,TG_TABLE_SCHEMA||'.'||TG_TABLE_NAME,OLD.id FROM ops.ad_accepted_exception x
   LEFT JOIN ops.ad_decision_policy_bundle b ON b.id=x.bundle_id
   WHERE ((to_jsonb(OLD)->>'organization_id') IS NULL
       OR x.organization_id=(to_jsonb(OLD)->>'organization_id')::uuid)
     AND x.state IN('REQUESTED','ENDORSED','ACTIVE')
    AND (x.bundle_id=OLD.id OR x.semantic_profile_id=OLD.id
       OR EXISTS(SELECT 1 FROM jsonb_each_text(to_jsonb(b)) field WHERE field.value=OLD.id::text)
       OR TG_TABLE_NAME='ad_freshness_profile');
 END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION ops.record_ad_manual_independent_observation(p_id uuid, p_packet uuid, p_expected bigint, p_observation jsonb, p_proof text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'iam', 'platform', 'pg_temp'
    AS $_$
DECLARE packet ops.ad_manual_execution_packet%ROWTYPE; policy core.ad_manual_policy%ROWTYPE;
 g iam.ad_invocation_grant%ROWTYPE; observed timestamptz; accepted timestamptz:=clock_timestamp();
 field_path text; actual_value text; expected_value text; grade text; proven boolean; conflicted boolean;
 later_unknown boolean; envelope jsonb;
BEGIN
 SELECT * INTO packet FROM ops.ad_manual_execution_packet WHERE id=p_packet;
 PERFORM pg_advisory_xact_lock(hashtext('ad_action_reservation'),hashtext(packet.organization_id::text));
 SELECT * INTO packet FROM ops.ad_manual_execution_packet WHERE id=p_packet FOR UPDATE;
 g:=ops.consume_ad_control_invocation(p_proof,'MANUAL_INDEPENDENT_VERIFY',p_packet,p_packet);
 accepted:=clock_timestamp();
 IF packet.id IS NULL OR packet.version IS DISTINCT FROM p_expected OR g.organization_id<>packet.organization_id
  OR packet.execution_started_at IS NULL OR packet.executor_user_id IS NULL OR packet.reservation_id IS NULL
  OR packet.state NOT IN ('MANUAL_EXECUTION_IN_PROGRESS','ACTION_REPORTED_CONFIGURATION_UNVERIFIED',
    'MANUAL_CONFIGURATION_VERIFIED','MANUAL_EXECUTION_UNCERTAIN') THEN
  RAISE EXCEPTION 'an actual started manual intervention and current revision are required' USING ERRCODE='23514'; END IF;
 IF g.actor_user_id=packet.executor_user_id OR NOT (
    ops.ad_manual_actor_scoped(g.actor_user_id,packet.organization_id,packet.store_id,packet.affected_set_id,'TECH_DATA','ADVERTISING_MANUAL_VERIFY')
    OR ops.ad_manual_actor_scoped(g.actor_user_id,packet.organization_id,packet.store_id,packet.affected_set_id,'OPS_LEAD','ADVERTISING_MANUAL_VERIFY'))
   OR NOT EXISTS(SELECT 1 FROM core.ad_affected_set a WHERE a.id=packet.affected_set_id
     AND a.organization_id=packet.organization_id AND a.resolution_state='COMPLETE'
     AND a.affected_set_digest=packet.affected_set_digest AND cardinality(a.product_variant_ids)>0) THEN
  RAISE EXCEPTION 'independent explicitly scoped verifier and complete packet scope required' USING ERRCODE='MO064'; END IF;
 IF p_observation IS NULL OR jsonb_typeof(p_observation)<>'object' THEN
  RAISE EXCEPTION 'an actual observation object is required' USING ERRCODE='23514'; END IF;
 IF NOT p_observation ?& ARRAY['observedValue','observedAt','evidenceSource','completeness','exactNativeObjectId',
    'exactFieldPath','semanticProfileId','evidenceReference','directObservationAttested']
  OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_observation) k WHERE k NOT IN ('observedValue','observedAt','evidenceSource',
    'completeness','exactNativeObjectId','exactFieldPath','semanticProfileId','evidenceReference','directObservationAttested'))
  OR jsonb_typeof(p_observation->'observedValue') IS DISTINCT FROM 'string'
  OR jsonb_typeof(p_observation->'observedAt') IS DISTINCT FROM 'string'
  OR (p_observation->>'observedAt') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,9})?(Z|[+-][0-9]{2}:[0-9]{2})$'
  OR jsonb_typeof(p_observation->'evidenceReference') IS DISTINCT FROM 'string'
  OR jsonb_typeof(p_observation->'directObservationAttested') IS DISTINCT FROM 'boolean'
  OR p_observation->>'evidenceSource' IS NULL OR p_observation->>'evidenceSource' NOT IN ('DIRECT_OFFICIAL_CONSOLE','SCREENSHOT')
  OR p_observation->>'completeness' IS NULL OR p_observation->>'completeness' NOT IN ('COMPLETE','INCOMPLETE') THEN
  RAISE EXCEPTION 'typed actual observation metadata is required; no completeness or time default exists' USING ERRCODE='23514'; END IF;
 BEGIN observed:=(p_observation->>'observedAt')::timestamptz;
 EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
  RAISE EXCEPTION 'actual observation time is invalid' USING ERRCODE='23514'; END;
 SELECT * INTO policy FROM core.ad_manual_policy WHERE id=packet.manual_policy_id;
 field_path:=CASE packet.action_kind WHEN 'AD_BID_CHANGE' THEN 'targetBid'
   WHEN 'AD_BUDGET_CHANGE' THEN 'targetBudget' ELSE 'targetStatus' END;
 actual_value:=p_observation->>'observedValue'; expected_value:=packet.intended_state->>field_path;
 IF observed IS NULL OR NOT isfinite(observed) OR observed<packet.execution_started_at OR observed>accepted
  OR policy.id IS NULL OR policy.organization_id<>packet.organization_id OR policy.store_id<>packet.store_id
  OR policy.semantic_profile_id<>packet.semantic_profile_id OR policy.action_kind<>packet.action_kind
  OR policy.approved_at>observed OR policy.effective_from>observed OR policy.effective_to<=accepted
  OR accepted-observed>make_interval(secs=>policy.configuration_max_age_seconds)
  OR packet.verification_plan->>'policyId' IS DISTINCT FROM policy.id::text
  OR packet.verification_plan->>'policyVersion' IS DISTINCT FROM policy.policy_version::text
  OR packet.authority_snapshot->'policy' IS DISTINCT FROM to_jsonb(policy)
  OR p_observation->>'exactNativeObjectId' IS DISTINCT FROM packet.ad_native_object_id::text
  OR p_observation->>'semanticProfileId' IS DISTINCT FROM packet.semantic_profile_id::text
  OR p_observation->>'exactFieldPath' IS DISTINCT FROM field_path
  OR length(btrim(actual_value)) NOT BETWEEN 1 AND 128
  OR length(btrim(p_observation->>'evidenceReference')) NOT BETWEEN 1 AND 512
  OR expected_value IS NULL
  OR (packet.action_kind IN ('AD_BID_CHANGE','AD_BUDGET_CHANGE') AND actual_value !~ '^[0-9]+(\.[0-9]{1,4})?$')
  OR (packet.action_kind='AD_STATUS_CHANGE' AND actual_value !~ '^[A-Za-z0-9_ -]{1,128}$')
  OR NOT EXISTS(SELECT 1 FROM core.ad_native_object o JOIN platform.ad_semantic_profile s ON s.id=o.semantic_profile_id
    WHERE o.id=packet.ad_native_object_id AND o.organization_id=packet.organization_id AND o.store_id=packet.store_id
      AND o.platform_code=packet.platform_code AND o.semantic_profile_id=packet.semantic_profile_id
      AND to_jsonb(o)->'lineage_generation'=packet.authority_snapshot#>'{object,lineage_generation}'
      AND to_jsonb(o)->'native_object_key'=packet.authority_snapshot#>'{object,native_object_key}'
      AND to_jsonb(o)->'native_campaign_key'=packet.authority_snapshot#>'{object,native_campaign_key}'
      AND to_jsonb(o)->'native_object_kind'=packet.authority_snapshot#>'{object,native_object_kind}'
      AND to_jsonb(s)=packet.authority_snapshot->'semanticProfile'
      AND s.platform_code=packet.platform_code AND s.status='ACTIVE' AND s.created_at<=observed
      AND (s.effective_to IS NULL OR s.effective_to>accepted)) THEN
  RAISE EXCEPTION 'actual observation time, immutable evidence policy or exact packet metadata is not applicable' USING ERRCODE='23514'; END IF;
 -- A newer unknown/conflicting observation cannot be cleared by reporting an
 -- older favorable value. No caller timestamp is replaced with server time.
 later_unknown:=ops.ad_manual_has_later_unresolved(packet.id,observed);
 conflicted:=later_unknown OR CASE WHEN packet.action_kind IN ('AD_BID_CHANGE','AD_BUDGET_CHANGE')
   THEN actual_value::numeric<>expected_value::numeric ELSE actual_value<>expected_value END;
 proven:=p_observation->>'evidenceSource'='DIRECT_OFFICIAL_CONSOLE'
   AND p_observation->>'completeness'='COMPLETE' AND p_observation->'directObservationAttested'='true'::jsonb
   AND policy.verification_mode='INDEPENDENT_OR_OFFICIAL' AND NOT conflicted;
 grade:=CASE WHEN p_observation->>'evidenceSource'='DIRECT_OFFICIAL_CONSOLE'
   AND p_observation->>'completeness'='COMPLETE' AND p_observation->'directObservationAttested'='true'::jsonb
   AND policy.verification_mode='INDEPENDENT_OR_OFFICIAL' THEN 'INDEPENDENT_MANUAL_VERIFICATION'
   ELSE 'UNVERIFIED_MANUAL_EVIDENCE' END;
 envelope:=p_observation||jsonb_build_object('observedAt',to_char(observed AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
 INSERT INTO ops.ad_manual_configuration_verification(id,organization_id,packet_id,evidence_grade,executor_user_id,
   verifier_user_id,observed_field_path,observed_value,observed_at,evidence_reference,conflict_state,proves_configuration,
   recorded_at,correlation_id,independent_observation)
 VALUES(p_id,packet.organization_id,packet.id,grade,packet.executor_user_id,g.actor_user_id,field_path,actual_value,
   observed,p_observation->>'evidenceReference',CASE WHEN conflicted THEN 'CONFLICTED' ELSE 'NONE' END,proven,
   accepted,'manual:'||packet.id,envelope);
 PERFORM ops.apply_ad_manual_observation(p_id);
 RETURN p_id;
END $_$;

CREATE FUNCTION ops.record_ad_manual_observation(p_id uuid, p_packet uuid, p_expected bigint, p_kind text, p_observed_value text, p_configuration uuid, p_proof text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
BEGIN
 IF p_kind IS NULL OR p_kind NOT IN ('REPORT','OFFICIAL') THEN
  RAISE EXCEPTION 'independent manual evidence requires the complete observation envelope' USING ERRCODE='MO097';
 END IF;
 RETURN ops.record_ad_manual_observation_legacy(p_id,p_packet,p_expected,p_kind,p_observed_value,p_configuration,p_proof);
END $$;

CREATE FUNCTION ops.record_ad_manual_observation_legacy(p_id uuid, p_packet uuid, p_expected bigint, p_kind text, p_observed_value text, p_configuration uuid, p_proof text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'iam', 'platform', 'raw', 'pg_temp'
    AS $$
DECLARE packet ops.ad_manual_execution_packet%ROWTYPE; policy core.ad_manual_policy%ROWTYPE;
 g iam.ad_invocation_grant%ROWTYPE; cfg core.ad_object_configuration_observation%ROWTYPE;
 expected_value text; actual_value text; field_path text; grade text; observed timestamptz;
 proven boolean; conflicted boolean; verifier uuid;
BEGIN
 SELECT * INTO packet FROM ops.ad_manual_execution_packet WHERE id=p_packet;
 PERFORM pg_advisory_xact_lock(hashtext('ad_action_reservation'),hashtext(packet.organization_id::text));
 SELECT * INTO packet FROM ops.ad_manual_execution_packet WHERE id=p_packet FOR UPDATE;
 IF p_kind IS NULL OR p_kind NOT IN ('REPORT','OFFICIAL') THEN RAISE EXCEPTION 'unknown manual observation workflow' USING ERRCODE='MO097'; END IF;
 g:=ops.consume_ad_control_invocation(p_proof,CASE WHEN p_kind='REPORT' THEN 'MANUAL_EXECUTION_REPORT' ELSE 'MANUAL_INDEPENDENT_VERIFY' END,p_packet,p_packet);
 IF packet.id IS NULL OR packet.version IS DISTINCT FROM p_expected OR g.organization_id<>packet.organization_id
 OR packet.execution_started_at IS NULL OR packet.executor_user_id IS NULL OR packet.reservation_id IS NULL
 OR packet.state NOT IN ('MANUAL_EXECUTION_IN_PROGRESS','ACTION_REPORTED_CONFIGURATION_UNVERIFIED',
   'MANUAL_CONFIGURATION_VERIFIED','MANUAL_EXECUTION_UNCERTAIN') THEN
   RAISE EXCEPTION 'an actual started manual intervention and current revision are required' USING ERRCODE='MO097'; END IF;
 SELECT * INTO policy FROM core.ad_manual_policy WHERE id=packet.manual_policy_id;
 field_path:=CASE packet.action_kind WHEN 'AD_BID_CHANGE' THEN 'targetBid' WHEN 'AD_BUDGET_CHANGE' THEN 'targetBudget' ELSE 'targetStatus' END;
 expected_value:=packet.intended_state->>field_path;
 IF p_kind='REPORT' THEN
   IF g.actor_user_id<>packet.executor_user_id OR packet.state='MANUAL_CONFIGURATION_VERIFIED'
    OR p_observed_value IS NOT NULL OR p_configuration IS NOT NULL
    OR NOT ops.ad_manual_actor_scoped(g.actor_user_id,packet.organization_id,packet.store_id,packet.affected_set_id,
      'MARKETPLACE_OPERATOR','ADVERTISING_MANUAL_EXECUTE') THEN
     RAISE EXCEPTION 'only the scoped executor may report the issued exact action' USING ERRCODE='MO064'; END IF;
   grade:='EXECUTOR_SELF_REPORT'; actual_value:=expected_value; observed:=clock_timestamp(); verifier:=NULL;
 ELSE
   IF g.actor_user_id=packet.executor_user_id OR NOT (
      ops.ad_manual_actor_scoped(g.actor_user_id,packet.organization_id,packet.store_id,packet.affected_set_id,'TECH_DATA','ADVERTISING_MANUAL_VERIFY')
      OR ops.ad_manual_actor_scoped(g.actor_user_id,packet.organization_id,packet.store_id,packet.affected_set_id,'OPS_LEAD','ADVERTISING_MANUAL_VERIFY')) THEN
     RAISE EXCEPTION 'independent explicitly scoped verifier required' USING ERRCODE='MO064'; END IF;
   verifier:=g.actor_user_id;
     IF p_observed_value IS NOT NULL OR p_configuration IS NULL THEN
       RAISE EXCEPTION 'official verification requires a canonical observation identity only' USING ERRCODE='MO097'; END IF;
     SELECT c.* INTO cfg FROM core.ad_object_configuration_observation c
     JOIN core.fact_provenance provenance ON provenance.id=c.provenance_id AND provenance.organization_id=c.organization_id
     JOIN raw.raw_acquisition_observation observation ON observation.id=provenance.raw_observation_id AND observation.outcome_class='SUCCESS_BYTES'
     JOIN raw.raw_logical_unit unit ON unit.id=observation.logical_unit_id
     JOIN platform.ingestion_job job ON job.id=unit.job_id AND job.organization_id=c.organization_id
     JOIN core.store st ON st.id=packet.store_id AND st.marketplace_account_id=job.marketplace_account_id
     WHERE c.id=p_configuration AND c.organization_id=packet.organization_id AND c.ad_native_object_id=packet.ad_native_object_id
       AND c.semantic_profile_id=packet.semantic_profile_id AND job.platform_code=packet.platform_code
       AND provenance.source_kind='MARKETPLACE_RAW' AND provenance.source_time IS NOT NULL
       AND c.evidence_grade IN ('OFFICIAL_API_READBACK','OFFICIAL_CONFIGURATION_EXPORT')
       AND c.observed_at>=packet.execution_started_at AND c.observed_at<=clock_timestamp()
       AND c.observed_at>clock_timestamp()-make_interval(secs=>policy.configuration_max_age_seconds)
       AND NOT EXISTS(SELECT 1 FROM core.ad_object_configuration_observation n
         WHERE n.ad_native_object_id=c.ad_native_object_id AND (n.supersedes_observation_id=c.id OR n.observed_at>c.observed_at));
     IF cfg.id IS NULL THEN RAISE EXCEPTION 'trusted current official source observation is absent' USING ERRCODE='MO097'; END IF;
     grade:=cfg.evidence_grade; observed:=cfg.observed_at;
     actual_value:=CASE packet.action_kind WHEN 'AD_BID_CHANGE' THEN cfg.observed_bid_amount::text
       WHEN 'AD_BUDGET_CHANGE' THEN cfg.observed_budget_amount::text ELSE cfg.native_status_raw END;
     IF actual_value IS NULL THEN RAISE EXCEPTION 'official native field is unknown' USING ERRCODE='MO097'; END IF;
 END IF;
 conflicted:=(p_kind='OFFICIAL' AND ops.ad_manual_has_later_unresolved(packet.id,observed)) OR CASE WHEN packet.action_kind IN ('AD_BID_CHANGE','AD_BUDGET_CHANGE')
   THEN actual_value::numeric<>expected_value::numeric ELSE actual_value<>expected_value END;
 proven:=p_kind<>'REPORT' AND NOT conflicted;
 INSERT INTO ops.ad_manual_configuration_verification(id,organization_id,packet_id,evidence_grade,executor_user_id,
   verifier_user_id,observed_field_path,observed_value,observed_at,evidence_reference,conflict_state,proves_configuration,
   recorded_at,correlation_id,configuration_observation_id)
 VALUES(p_id,packet.organization_id,p_packet,grade,packet.executor_user_id,verifier,field_path,actual_value,observed,
   CASE WHEN p_configuration IS NULL THEN 'manual-attestation:'||p_id ELSE 'configuration-observation:'||p_configuration END,
   CASE WHEN conflicted THEN 'CONFLICTED' ELSE 'NONE' END,proven,clock_timestamp(),'manual:'||p_packet,p_configuration);
 PERFORM ops.apply_ad_manual_observation(p_id);
 -- Configuration proof is never an early sales observation or an Outcome.
 RETURN p_id;
END $$;

CREATE FUNCTION ops.record_ad_reservation_state_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$ BEGIN
 INSERT INTO ops.ad_reservation_state_history(reservation_id,old_state,new_state) VALUES(NEW.id,to_jsonb(OLD),to_jsonb(NEW));
 RETURN NEW; END $$;

CREATE FUNCTION ops.record_diagnostic_export_part(p_id uuid, p_token uuid, p_first integer, p_last integer, p_content uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE j ops.diagnostic_export; c raw.raw_content; prior ops.diagnostic_export_part;
 next_first integer; next_part integer; n integer; bytes bigint; body text;
BEGIN
 j:=ops.require_diagnostic_export_lease(p_id,p_token);
 IF j.snapshot_at IS NULL OR p_first IS NULL OR p_last IS NULL OR p_first<1 OR p_last<p_first OR p_last>j.row_count THEN
   RAISE EXCEPTION 'invalid export range' USING ERRCODE='MO039'; END IF;
 SELECT * INTO c FROM raw.raw_content WHERE id=p_content;
 IF NOT FOUND OR c.byte_length>4194304 THEN RAISE EXCEPTION 'invalid export custody' USING ERRCODE='MO082'; END IF;
 SELECT * INTO prior FROM ops.diagnostic_export_part WHERE export_id=p_id AND first_ordinal=p_first;
 IF FOUND THEN
   IF prior.last_ordinal=p_last AND prior.content_id=p_content THEN RETURN; END IF;
   RAISE EXCEPTION 'export part conflict' USING ERRCODE='MO061';
 END IF;
 SELECT coalesce(max(last_ordinal),0)+1,coalesce(max(part_number),0)+1 INTO next_first,next_part
   FROM ops.diagnostic_export_part WHERE export_id=p_id;
 IF p_first<>next_first OR next_part>64 THEN RAISE EXCEPTION 'invalid export sequence' USING ERRCODE='MO082'; END IF;
 SELECT count(*),sum(byte_length) INTO n,bytes FROM mart.diagnostic_export_row
   WHERE export_id=p_id AND ordinal BETWEEN p_first AND p_last;
 IF n<>p_last-p_first+1 OR bytes IS NULL OR bytes>4194304 OR bytes<>c.byte_length THEN
   RAISE EXCEPTION 'invalid export bytes' USING ERRCODE='MO082'; END IF;
 SELECT string_agg(payload||chr(10),'' ORDER BY ordinal) INTO body FROM mart.diagnostic_export_row
   WHERE export_id=p_id AND ordinal BETWEEN p_first AND p_last;
 IF encode(sha256(convert_to(body,'UTF8')),'hex')<>c.hash_value OR c.hash_algorithm<>'SHA256' THEN
   RAISE EXCEPTION 'export custody mismatch' USING ERRCODE='MO083'; END IF;
 INSERT INTO ops.diagnostic_export_part VALUES(p_id,next_part,p_first,p_last,n,bytes,c.hash_value,c.id);
 PERFORM ops.audit_diagnostic_export(j,'PART_RECORDED');
END $$;

CREATE FUNCTION ops.record_lc_containment(p_id uuid, p_actor uuid, p_org uuid, p_proof text, p_scope_kind text, p_listing uuid, p_store uuid, p_platform text, p_batch uuid, p_cause_class text, p_cause_owner_role text, p_reason text, p_evidence text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'iam', 'pg_temp'
    AS $$
DECLARE scope_store uuid; grant_row iam.ad_invocation_grant%ROWTYPE;
BEGIN
    grant_row:=ops.consume_ad_control_invocation(p_proof, 'LISTING_CONTAINMENT_STOP', p_id, p_id);
    IF grant_row.actor_user_id<>p_actor OR grant_row.organization_id<>p_org THEN
        RAISE EXCEPTION 'stop actor must match the authenticated invocation' USING ERRCODE='MO092';
    END IF;
    scope_store := coalesce(p_store,
        (SELECT l.store_id FROM core.platform_listing l WHERE l.id = p_listing),
        (SELECT b.store_id FROM ops.lc_batch b WHERE b.id = p_batch));
    IF NOT ops.lc_current_containment_authority(p_actor,p_org,scope_store,'LISTING_CONTAINMENT_STOP') THEN
        RAISE EXCEPTION 'current stop authority required' USING ERRCODE='MO092';
    END IF;
    INSERT INTO ops.lc_containment (id, organization_id, scope_kind, platform_listing_id, store_id,
        platform_code, batch_id, cause_class, cause_owner_role_code, stopped_by_user_id, stopped_at,
        reason, evidence_reference, state)
    VALUES (p_id, p_org, p_scope_kind, p_listing, p_store, p_platform, p_batch, p_cause_class,
        p_cause_owner_role, p_actor, clock_timestamp(), p_reason, p_evidence, 'ACTIVE');
    -- Every live action inside the scope stops. Nothing is resumed by the stop
    -- itself; reenablement is a separate, doubly attested act.
    UPDATE ops.lc_action a
       SET state = 'CONTAINED', updated_at = clock_timestamp(), version = version + 1
     WHERE a.organization_id = p_org
       AND a.state IN ('APPROVED', 'APPROVED_NOT_LAUNCHABLE', 'LAUNCHED')
       AND ops.lc_scope_contained(p_org, a.platform_listing_id);
    RETURN p_id;
END;
$$;

CREATE FUNCTION ops.record_lc_description_command_readback(p_readback_id uuid, p_command_id uuid, p_attempt_id uuid, p_fence bigint, p_owner text, p_correlation_id text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'raw', 'pg_temp'
    AS $$
DECLARE
    command     ops.lc_description_command%ROWTYPE;
    attempt     ops.lc_description_command_attempt%ROWTYPE;
    observation raw.lc_description_response_observation%ROWTYPE;
    match       text;
BEGIN
    SELECT * INTO command FROM ops.lc_description_command WHERE id = p_command_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'command does not exist' USING ERRCODE = 'MO090'; END IF;
    IF command.fence_token <> p_fence OR command.lease_owner IS DISTINCT FROM p_owner
        OR command.lease_expires_at IS NULL OR command.lease_expires_at <= clock_timestamp() THEN
        RAISE EXCEPTION 'the lease that authorised this readback is not current' USING ERRCODE = 'MO090';
    END IF;
    SELECT * INTO attempt FROM ops.lc_description_command_attempt WHERE id = p_attempt_id;
    IF NOT FOUND OR attempt.command_id <> p_command_id OR attempt.purpose <> 'READBACK'
        OR attempt.fence_token <> p_fence OR attempt.lease_owner IS DISTINCT FROM p_owner
        OR attempt.outcome_class = 'IN_FLIGHT' OR attempt.raw_observation_id IS NULL THEN
        RAISE EXCEPTION 'a readback needs a completed readback attempt at this fence' USING ERRCODE = 'MO093';
    END IF;
    SELECT * INTO observation FROM raw.lc_description_response_observation WHERE id = attempt.raw_observation_id;
    match := CASE
        WHEN attempt.outcome_class <> 'ACCEPTED'
            OR observation.identity_binding->>'qualified' IS DISTINCT FROM 'true'
            OR observation.identity_binding->>'extent' IS DISTINCT FROM 'EXACT_NATIVE_OBJECT'
            OR observation.observed_text_digest IS NULL THEN 'UNREADABLE'
        WHEN observation.observed_text_digest
             = ops.lc_description_digest_under_rule(command.target_text, command.equivalence_rule)
             THEN 'MATCHES_TARGET'
        WHEN command.prior_text IS NOT NULL AND observation.observed_text_digest
             = ops.lc_description_digest_under_rule(command.prior_text, command.equivalence_rule)
             THEN 'MATCHES_PRIOR'
        ELSE 'DIFFERENT'
    END;
    -- A matched target whose marking declaration was lost is not a match: a
    -- description write that dropped kizMarked changed a non-target field.
    IF match = 'MATCHES_TARGET' AND observation.observed_kiz_marked IS NOT NULL
        AND observation.observed_kiz_marked <> command.kiz_marked_declared THEN
        match := 'DIFFERENT';
    END IF;
    INSERT INTO ops.lc_description_command_readback (id, command_id, attempt_id, observed_at,
        observed_text_digest, observed_kiz_marked, match_state, raw_observation_id, correlation_id)
    VALUES (p_readback_id, p_command_id, p_attempt_id, clock_timestamp(),
        CASE WHEN match = 'UNREADABLE' THEN NULL ELSE observation.observed_text_digest END,
        observation.observed_kiz_marked, match, attempt.raw_observation_id, p_correlation_id);
    RETURN match;
END;
$$;

CREATE FUNCTION ops.record_lc_description_execution_result(p_command uuid, p_readback uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE c ops.lc_description_command%ROWTYPE; proof jsonb; receipt uuid;
BEGIN
    SELECT * INTO c FROM ops.lc_description_command WHERE id=p_command FOR UPDATE;
    IF c.state IS DISTINCT FROM 'READBACK_MATCHED' OR NOT EXISTS (
        SELECT 1 FROM ops.lc_description_command_readback rb WHERE rb.id=p_readback AND rb.command_id=c.id) THEN
        RAISE EXCEPTION 'execution observation needs the exact terminal readback' USING ERRCODE='MO093';
    END IF;
    SELECT id INTO receipt FROM ops.lc_execution_receipt WHERE readback_id=p_readback;
    IF receipt IS NOT NULL THEN RETURN receipt; END IF;
    proof:=ops.lc_description_execution_evidence(c.id,p_readback); receipt:=gen_random_uuid();
    INSERT INTO ops.lc_execution_receipt(id,organization_id,action_id,command_id,readback_id,execution_state,evidence,recorded_at)
    VALUES(receipt,c.organization_id,c.action_id,c.id,p_readback,proof->>'executionState',proof,clock_timestamp());
    IF proof->>'executionState'='MANAGEMENT_VERIFIED' THEN
        UPDATE ops.lc_action SET state='VERIFIED',updated_at=clock_timestamp(),version=version+1
         WHERE id=c.action_id AND organization_id=c.organization_id AND execution_path='API' AND state='LAUNCHED'
           AND target_text_digest=c.target_text_digest AND affected_set_digest=c.affected_set_digest;
    END IF;
    RETURN receipt;
END;
$$;

CREATE FUNCTION ops.record_lc_description_task_query(p_attempt uuid, p_digest text, p_body bytea) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'platform', 'pg_temp'
    AS $$
DECLARE a ops.lc_description_command_attempt%ROWTYPE; c ops.lc_description_command%ROWTYPE;
    d jsonb; document jsonb; task jsonb; value jsonb; expected bytea; identity jsonb;
BEGIN
    SELECT * INTO a FROM ops.lc_description_command_attempt WHERE id=p_attempt FOR UPDATE;
    IF NOT FOUND OR a.purpose<>'STATUS_ENQUIRY' OR a.outcome_class<>'IN_FLIGHT'
        OR a.request_digest IS DISTINCT FROM p_digest THEN RETURN false; END IF;
    SELECT * INTO c FROM ops.lc_description_command WHERE id=a.command_id FOR SHARE;
    IF c.fence_token<>a.fence_token OR c.lease_owner IS DISTINCT FROM a.lease_owner
        OR c.lease_expires_at IS NULL OR c.lease_expires_at<=clock_timestamp() OR c.provider_retry_timing_unknown
        OR c.provider_not_before>clock_timestamp()
        OR (a.operation_snapshot-'responseIdentity') IS DISTINCT FROM platform.lc_description_operation_snapshot(c.capability_id,a.purpose)
        THEN RETURN false; END IF;
    d:=a.operation_snapshot #> '{operation,description_response_binding}';
    task:=a.operation_snapshot #> '{responseIdentity,task}';
    IF d->>'taskBindingMethod' IS DISTINCT FROM 'REQUEST_UNIQUE'
        OR NOT platform.lc_description_response_descriptor_valid(d,a.purpose,a.operation_snapshot->>'writeResultModel')
        OR task->>'attemptId' IS DISTINCT FROM (SELECT prior.id::text FROM ops.lc_description_command_attempt prior
            WHERE prior.command_id=c.id AND prior.purpose IN ('APPLY','RESTORE') ORDER BY prior.attempt_no DESC LIMIT 1)
        OR nullif(task->>'nativeTaskKey','') IS NULL
        OR a.operation_snapshot #>> '{endpoint,http_method}' IS DISTINCT FROM 'POST'
        OR p_body IS NULL OR octet_length(p_body) NOT BETWEEN 1 AND 65536 THEN RETURN false; END IF;
    expected:=ops.lc_description_render_task_query(a.operation_snapshot #>> '{operation,request_template}',
        jsonb_build_object('nativeTaskKey',task->>'nativeTaskKey','nativeListingKey',c.native_listing_key,'idempotencyKey',c.idempotency_key));
    IF p_body IS DISTINCT FROM expected THEN RETURN false; END IF;
    BEGIN
        IF NOT (convert_from(p_body,'UTF8') IS JSON WITH UNIQUE KEYS) THEN RETURN false; END IF;
        document:=convert_from(p_body,'UTF8')::jsonb;
    EXCEPTION WHEN invalid_text_representation OR character_not_in_repertoire THEN RETURN false;
    END;
    value:=ops.lc_response_value(document,d->>'taskRequestPointer');
    IF jsonb_typeof(value) IS DISTINCT FROM d->>'taskRequestValueType'
        OR value #>> '{}' IS DISTINCT FROM task->>'nativeTaskKey' THEN RETURN false; END IF;
    identity:=jsonb_build_object('method','REQUEST_UNIQUE','attemptId',a.id,'task',task,
        'requestDigest',a.request_digest,'bodySha256',encode(sha256(p_body),'hex'),
        'operationSnapshotSha256',encode(sha256(convert_to(a.operation_snapshot::text,'UTF8')),'hex'));
    IF a.query_identity IS NOT NULL THEN RETURN a.query_identity=identity AND a.query_body=p_body; END IF;
    UPDATE ops.lc_description_command_attempt SET query_body=p_body,query_identity=identity,query_recorded_at=clock_timestamp()
        WHERE id=a.id;
    RETURN true;
END;
$$;

CREATE FUNCTION ops.record_lc_isolation_dependency(p_id uuid, p_actor uuid, p_org uuid, p_proof text, p_from uuid, p_to uuid, p_kind text, p_reference text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE grant_row iam.ad_invocation_grant%ROWTYPE; from_store uuid; to_store uuid; now_at timestamptz;
BEGIN
 SELECT store_id INTO from_store FROM core.platform_listing WHERE id=p_from AND organization_id=p_org;
 SELECT store_id INTO to_store FROM core.platform_listing WHERE id=p_to AND organization_id=p_org;
 IF from_store IS NULL OR to_store IS NULL OR p_from=p_to
    OR p_kind NOT IN ('SHARED_TEMPLATE','SHARED_VARIANT_SET','SHARED_CAMPAIGN')
    OR length(btrim(coalesce(p_reference,''))) NOT BETWEEN 1 AND 512 THEN
   RAISE EXCEPTION 'bounded exact Listing dependency required' USING ERRCODE='MO092';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtext('lc_exposure_organization'),hashtext(p_org::text));
 now_at:=clock_timestamp();
 grant_row:=ops.consume_ad_control_invocation(p_proof,'LISTING_ISOLATION_DEPENDENCY_RECORD',p_id,p_id);
 IF grant_row.actor_user_id<>p_actor OR grant_row.organization_id<>p_org
    OR NOT ops.lc_actor_holds_action(p_actor,p_org,from_store,'LISTING_ACTION_PREPARE')
    OR NOT ops.lc_actor_holds_action(p_actor,p_org,to_store,'LISTING_ACTION_PREPARE') THEN
   RAISE EXCEPTION 'dependency recorder must match current authority for both Listings' USING ERRCODE='MO092';
 END IF;
 IF NOT ops.lc_listing_uses_isolation_dependency(p_org,p_from,p_kind,p_reference,now_at)
    OR NOT ops.lc_listing_uses_isolation_dependency(p_org,p_to,p_kind,p_reference,now_at) THEN
   RAISE EXCEPTION 'both Listings must currently use the exact shared cause' USING ERRCODE='MO092';
 END IF;
 INSERT INTO ops.lc_isolation_dependency(id,organization_id,from_listing_id,to_listing_id,dependency_kind,
   proof_reference,proven_at,recorded_by_user_id)
 VALUES(p_id,p_org,p_from,p_to,p_kind,p_reference,now_at,p_actor);
 RETURN p_id;
END $$;

CREATE FUNCTION ops.record_price_command_readback(p_id uuid, p_command uuid, p_attempt uuid, p_fence bigint, p_owner text, p_correlation text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE c ops.price_command%ROWTYPE; response raw.price_response_observation%ROWTYPE; match text;
BEGIN
    SELECT * INTO c FROM ops.price_command WHERE id = p_command FOR UPDATE;
    IF c.id IS NULL OR c.fence_token IS DISTINCT FROM p_fence
       OR c.lease_owner IS DISTINCT FROM p_owner OR c.lease_expires_at <= clock_timestamp()
       OR c.lease_expires_at IS NULL THEN
        RAISE EXCEPTION 'readback authority lost' USING ERRCODE = 'MO030';
    END IF;
    SELECT evidence.* INTO response FROM raw.price_response_observation evidence
      JOIN ops.price_command_attempt a ON a.id = evidence.attempt_id
     WHERE a.id = p_attempt AND a.command_id = c.id AND a.purpose = 'READBACK'
       AND a.fence_token = p_fence AND a.lease_owner = p_owner
       AND a.correlation_id = p_correlation AND a.outcome_class <> 'IN_FLIGHT'
       AND a.raw_observation_id = evidence.id;
    IF response.id IS NULL THEN
        RAISE EXCEPTION 'readback requires this attempt immutable response' USING ERRCODE = 'MO033';
    END IF;
    match := CASE WHEN response.observed_price IS NULL THEN 'UNREADABLE'
                  WHEN response.observed_currency <> c.currency_code THEN 'DIFFERENT'
                  WHEN response.observed_price = c.target_price THEN 'MATCHES_TARGET'
                  WHEN response.observed_price = c.prior_price THEN 'MATCHES_PRIOR'
                  ELSE 'DIFFERENT' END;
    INSERT INTO ops.price_command_readback (id, command_id, attempt_id, observed_at, observed_price,
        currency_code, match_state, raw_observation_id, correlation_id)
    VALUES (p_id, c.id, p_attempt, response.observed_at, response.observed_price,
        response.observed_currency, match, response.id, p_correlation);
    RETURN match;
END;
$$;

CREATE FUNCTION ops.recover_expired_ad_bid_command_leases() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE recovered integer := 0;
BEGIN
    WITH expired AS (
        SELECT id, state, retry_preflight_fence FROM ops.ad_bid_command
         WHERE lease_expires_at IS NOT NULL
           AND lease_expires_at <= clock_timestamp()
           AND state IN ('LEASED', 'EXECUTING', 'PLATFORM_PENDING',
                         'READBACK_PENDING', 'COMPENSATION_PENDING')
         FOR UPDATE SKIP LOCKED)
    UPDATE ops.ad_bid_command c
       SET state = CASE expired.state
               WHEN 'LEASED' THEN CASE WHEN expired.retry_preflight_fence IS NOT NULL
                   THEN 'UNKNOWN_REQUIRES_READBACK' ELSE 'PENDING' END
               WHEN 'COMPENSATION_PENDING' THEN 'MANUAL_RESOLUTION'
               ELSE 'UNKNOWN_REQUIRES_READBACK' END,
           lease_owner = NULL, lease_expires_at = NULL, retry_preflight_fence = NULL,
           updated_at = clock_timestamp()
      FROM expired
     WHERE c.id = expired.id;
    GET DIAGNOSTICS recovered = ROW_COUNT;
    RETURN recovered;
END;
$$;

CREATE FUNCTION ops.recover_expired_lc_description_leases() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE recovered integer := 0;
BEGIN
    WITH expired AS (
        SELECT id, state, retry_preflight_fence FROM ops.lc_description_command
         WHERE lease_expires_at IS NOT NULL AND lease_expires_at <= clock_timestamp()
           AND state IN ('LEASED', 'EXECUTING', 'PLATFORM_PENDING', 'READBACK_PENDING', 'COMPENSATION_PENDING')
         FOR UPDATE SKIP LOCKED)
    UPDATE ops.lc_description_command c
       SET state = CASE expired.state
               WHEN 'LEASED' THEN CASE WHEN expired.retry_preflight_fence IS NOT NULL
                   THEN 'UNKNOWN_REQUIRES_READBACK' ELSE 'PENDING' END
               WHEN 'COMPENSATION_PENDING' THEN 'MANUAL_RESOLUTION'
               ELSE 'UNKNOWN_REQUIRES_READBACK' END,
           lease_owner = NULL, lease_expires_at = NULL, retry_preflight_fence = NULL,
           updated_at = clock_timestamp()
      FROM expired
     WHERE c.id = expired.id;
    GET DIAGNOSTICS recovered = ROW_COUNT;
    RETURN recovered;
END;
$$;

CREATE FUNCTION ops.recover_expired_price_command_leases() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    recovered integer := 0;
    moved     integer;
BEGIN
    -- Claimed but never called: nothing reached the platform, so the command
    -- returns to the queue exactly as it was.
    WITH expired AS (
        SELECT command.id
          FROM ops.price_command AS command
         WHERE command.state = 'LEASED'
           AND command.lease_expires_at IS NOT NULL
           AND command.lease_expires_at <= clock_timestamp()
           FOR UPDATE OF command SKIP LOCKED
    )
    UPDATE ops.price_command AS command
       SET state = 'PENDING', lease_owner = NULL, lease_expires_at = NULL,
           next_attempt_at = clock_timestamp(), updated_at = clock_timestamp()
      FROM expired
     WHERE command.id = expired.id;
    GET DIAGNOSTICS moved = ROW_COUNT;
    recovered := recovered + moved;

    -- A call may have been made. Whether the marketplace applied it is exactly
    -- what nobody knows, which is the state this moves to and the reason there
    -- is no path from it back to executing.
    WITH expired AS (
        SELECT command.id
          FROM ops.price_command AS command
         WHERE command.state IN ('EXECUTING', 'PLATFORM_PENDING', 'READBACK_PENDING')
           AND command.lease_expires_at IS NOT NULL
           AND command.lease_expires_at <= clock_timestamp()
           FOR UPDATE OF command SKIP LOCKED
    )
    UPDATE ops.price_command AS command
       SET state = 'UNKNOWN_REQUIRES_READBACK', lease_owner = NULL,
           lease_expires_at = NULL, next_attempt_at = NULL,
           updated_at = clock_timestamp()
      FROM expired
     WHERE command.id = expired.id;
    GET DIAGNOSTICS moved = ROW_COUNT;
    recovered := recovered + moved;

    -- A restore that lost its worker goes to a person. Re-running it
    -- automatically would repeat a write whose effect nobody has observed.
    WITH expired AS (
        SELECT command.id
          FROM ops.price_command AS command
         WHERE command.state = 'COMPENSATION_PENDING'
           AND command.lease_expires_at IS NOT NULL
           AND command.lease_expires_at <= clock_timestamp()
           FOR UPDATE OF command SKIP LOCKED
    )
    UPDATE ops.price_command AS command
       SET state = 'MANUAL_RESOLUTION', lease_owner = NULL, lease_expires_at = NULL,
           next_attempt_at = NULL, updated_at = clock_timestamp()
      FROM expired
     WHERE command.id = expired.id;
    GET DIAGNOSTICS moved = ROW_COUNT;
    recovered := recovered + moved;

    RETURN recovered;
END;
$$;

CREATE FUNCTION ops.reenable_ad_containment(p_id uuid, p_new_bundle uuid, p_proof text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'iam', 'pg_temp'
    AS $$
DECLARE q ops.ad_containment%ROWTYPE; g iam.ad_invocation_grant%ROWTYPE; e uuid;
BEGIN
 SELECT * INTO q FROM ops.ad_containment WHERE id=p_id FOR UPDATE;
 g:=ops.consume_ad_control_invocation(p_proof,'CONTAINMENT_REENABLE',p_id,p_new_bundle);
 PERFORM pg_advisory_xact_lock(hashtext('ad_action_reservation'),hashtext(q.organization_id::text));
 SELECT actor_user_id INTO e FROM ops.ad_containment_attestation WHERE containment_id=p_id AND condition='OPERATIONS_ENDORSEMENT';
 IF q.id IS NULL OR g.organization_id<>q.organization_id OR q.state='REENABLED' OR e IS NULL
 OR g.actor_user_id=e OR g.actor_user_id=q.activated_by_user_id
 OR NOT (CASE WHEN q.scope_kind='AUTHORITY_VERSION' THEN
  ops.ad_actor_has_organization_role_scope(g.actor_user_id,q.organization_id,'OWNER','ADVERTISING_POLICY_MANAGE')
 ELSE ops.ad_actor_has_role_scope(g.actor_user_id,q.organization_id,q.store_id,'OWNER','ADVERTISING_POLICY_MANAGE') END)
 OR q.scope_kind='AUTHORITY_VERSION' AND EXISTS(SELECT 1 FROM ops.ad_containment_attestation a WHERE a.containment_id=p_id
  AND NOT ops.ad_actor_has_organization_role_scope(a.actor_user_id,q.organization_id,
   CASE WHEN a.condition='SECURITY_ATTESTATION_PRESENT' THEN 'TECH_DATA' ELSE 'OPS_LEAD' END,
   CASE WHEN a.condition='SECURITY_ATTESTATION_PRESENT' THEN 'ADVERTISING_TECHNICAL_ATTEST' ELSE 'ADVERTISING_POLICY_MANAGE' END))
 OR q.scope_kind='AUTHORITY_VERSION' AND EXISTS(SELECT 1 FROM ops.ad_decision_policy_bundle remaining
  WHERE remaining.organization_id=q.organization_id AND remaining.status='ACTIVE'
  AND ops.ad_bundle_consumes_authority_version(remaining.id,q.authority_version_reference::uuid))
 OR q.scope_kind='AUTHORITY_VERSION' AND EXISTS(SELECT 1 FROM ops.ad_manual_execution_packet packet
  WHERE packet.organization_id=q.organization_id AND packet.execution_started_at IS NOT NULL
  AND packet.state IN ('MANUAL_EXECUTION_IN_PROGRESS','ACTION_REPORTED_CONFIGURATION_UNVERIFIED','MANUAL_EXECUTION_UNCERTAIN')
  AND (ops.ad_bundle_consumes_authority_version(packet.bundle_id,q.authority_version_reference::uuid)
   OR q.authority_version_reference=ANY(ARRAY[packet.semantic_profile_id::text,
    to_jsonb(packet)#>>'{authority_snapshot,policy,id}',to_jsonb(packet)#>>'{authority_snapshot,outcomePolicy,id}'])))
 OR EXISTS(SELECT 1 FROM unnest(ARRAY['ROOT_CAUSE_CLASSIFIED','UNKNOWNS_RESOLVED','AUTHORITIES_REPLACED',
 'RESULTS_RECONCILED','CAPABILITY_EVIDENCE_CURRENT']) required(condition)
 WHERE NOT EXISTS(SELECT 1 FROM ops.ad_containment_attestation a WHERE a.containment_id=p_id AND a.condition=required.condition))
 OR q.cause_class IN ('CREDENTIAL_OR_SECURITY','PROVIDER_OR_READBACK_DEFECT','EXECUTION_INTEGRITY')
 AND NOT EXISTS(SELECT 1 FROM ops.ad_containment_attestation a WHERE a.containment_id=p_id AND a.condition='SECURITY_ATTESTATION_PRESENT')
 OR EXISTS(SELECT 1 FROM ops.ad_authority_invalidation i JOIN ops.ad_action_authorization a ON a.id=i.authorization_id
 JOIN ops.ad_bid_command c ON c.recommendation_id=a.recommendation_id WHERE i.cause_reference=p_id
 AND c.state IN ('EXECUTING','PLATFORM_PENDING','UNKNOWN_REQUIRES_READBACK','READBACK_PENDING','READBACK_MISMATCH',
 'LATER_CHANGE_OR_MISMATCH_INVESTIGATION','MANUAL_RESOLUTION','COMPENSATION_PENDING'))
 OR NOT EXISTS(SELECT 1 FROM ops.ad_decision_policy_bundle b JOIN ops.ad_gate_authority gate ON gate.id=b.gate_authority_id
 WHERE b.id=p_new_bundle AND b.status='ACTIVE' AND (q.scope_kind='AUTHORITY_VERSION' OR b.store_id=q.store_id)
 AND b.organization_id=q.organization_id AND cardinality(ops.ad_bundle_validation_failures(b.id))=0
 AND gate.organization_id=b.organization_id AND gate.store_id=b.store_id AND gate.bundle_id=b.id
 AND gate.status='ACTIVE' AND gate.valid_from<=clock_timestamp() AND gate.valid_until>clock_timestamp()
 AND NOT EXISTS(SELECT 1 FROM ops.ad_authority_invalidation i JOIN ops.ad_action_authorization a ON a.id=i.authorization_id
  WHERE i.cause_reference=p_id AND a.bundle_id=b.id)) THEN
 RAISE EXCEPTION 'new scope, resolved facts and independent recovery authorities required' USING ERRCODE='MO097'; END IF;
 UPDATE ops.ad_containment SET state='REENABLED',root_cause_classified=true,unknowns_resolved=true,authorities_replaced=true,
 results_reconciled=true,capability_evidence_current=true,security_attestation_present=EXISTS(SELECT 1 FROM ops.ad_containment_attestation a
 WHERE a.containment_id=p_id AND a.condition='SECURITY_ATTESTATION_PRESENT'),endorsed_by_user_id=e,approved_by_user_id=g.actor_user_id,
 reenabled_scope=jsonb_build_object('newBundleId',p_new_bundle)||CASE WHEN q.scope_kind='AUTHORITY_VERSION' THEN
  jsonb_build_object('organizationId',q.organization_id,'invalidAuthorityVersion',q.authority_version_reference,
   'allActiveConsumersReplaced',true,'invalidVersionRemainsForbidden',true) ELSE '{}'::jsonb END,reenabled_at=clock_timestamp(),updated_at=clock_timestamp(),version=version+1
 WHERE id=p_id;
 RETURN true;
END $$;

CREATE FUNCTION ops.reenable_lc_containment(p_containment uuid, p_actor uuid, p_proof text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE containment ops.lc_containment%ROWTYPE; repair ops.lc_containment_attestation%ROWTYPE;
 consent ops.lc_containment_attestation%ROWTYPE; cause_kind text;
BEGIN
 SELECT * INTO containment FROM ops.lc_containment WHERE id=p_containment FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'containment does not exist' USING ERRCODE='MO090'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext('lc_exposure_organization'),hashtext(containment.organization_id::text));
 IF containment.cause_class='SHARED_VERSION' THEN
   SELECT dependency_kind INTO cause_kind FROM ops.lc_isolation_dependency d
    JOIN ops.lc_shared_isolation_scope(containment.organization_id,NULL) scope
      ON scope.root_listing_id=d.from_listing_id
    WHERE d.organization_id=containment.organization_id
      AND d.proof_reference=containment.evidence_reference LIMIT 1;
   SELECT * INTO repair FROM ops.lc_containment_attestation WHERE containment_id=containment.id
      AND attestation_kind='REPAIR_ATTESTATION';
   SELECT * INTO consent FROM ops.lc_containment_attestation WHERE containment_id=containment.id
      AND attestation_kind='BUSINESS_CONSENT';
   IF cause_kind IS NULL OR repair.id IS NULL OR consent.id IS NULL
      OR repair.attested_at<=containment.stopped_at OR consent.attested_at<repair.attested_at
      OR EXISTS(SELECT 1 FROM ops.lc_shared_isolation_scope(containment.organization_id,NULL) scope
          WHERE EXISTS(SELECT 1 FROM ops.lc_isolation_dependency d
             WHERE d.organization_id=containment.organization_id
               AND d.proof_reference=containment.evidence_reference
               AND d.from_listing_id=scope.root_listing_id
               AND ops.lc_listing_uses_isolation_dependency(containment.organization_id,
                    scope.platform_listing_id,d.dependency_kind,d.proof_reference,statement_timestamp()))) THEN
     RAISE EXCEPTION 'shared cause is unqualified, still used, or not subsequently and independently released'
       USING ERRCODE='MO092';
   END IF;
 END IF;
 PERFORM ops.reenable_lc_containment_v0117(p_containment,p_actor,p_proof);
END $$;

CREATE FUNCTION ops.reenable_lc_containment_v0077(p_containment uuid, p_actor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE containment ops.lc_containment%ROWTYPE;
BEGIN
    SELECT * INTO containment FROM ops.lc_containment WHERE id = p_containment FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'containment does not exist' USING ERRCODE = 'MO090'; END IF;
    IF containment.state <> 'ACTIVE' THEN
        RAISE EXCEPTION 'the containment is not active' USING ERRCODE = 'MO091';
    END IF;
    IF (SELECT count(DISTINCT attestation_kind) FROM ops.lc_containment_attestation
         WHERE containment_id = p_containment) <> 2
       OR (SELECT count(DISTINCT actor_user_id) FROM ops.lc_containment_attestation
            WHERE containment_id = p_containment) <> 2 THEN
        RAISE EXCEPTION 'reenablement needs a repair attestation and a business consent by different people'
            USING ERRCODE = 'MO092';
    END IF;
    UPDATE ops.lc_containment SET state = 'REENABLED', reenabled_at = clock_timestamp()
     WHERE id = p_containment;
END;
$$;

CREATE FUNCTION ops.reenable_lc_containment_v0117(p_containment uuid, p_actor uuid, p_proof text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE c ops.lc_containment%ROWTYPE; failed ops.lc_node_result%ROWTYPE; latest ops.lc_node_result%ROWTYPE;
 grant_row iam.ad_invocation_grant%ROWTYPE; store_ref uuid; attestation record; repair ops.lc_containment_attestation%ROWTYPE; consent ops.lc_containment_attestation%ROWTYPE; required_action text;
BEGIN
 SELECT * INTO c FROM ops.lc_containment WHERE id=p_containment FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'containment does not exist' USING ERRCODE='MO090'; END IF;
 grant_row:=ops.consume_ad_control_invocation(p_proof,'LISTING_CONTAINMENT_REENABLE',p_containment,p_containment);
 IF grant_row.actor_user_id<>p_actor OR grant_row.organization_id<>c.organization_id THEN
   RAISE EXCEPTION 'reenablement actor must match the authenticated invocation' USING ERRCODE='MO092';
 END IF;
 store_ref:=coalesce(c.store_id,(SELECT store_id FROM core.platform_listing WHERE id=c.platform_listing_id),
   (SELECT store_id FROM ops.lc_batch WHERE id=c.batch_id));
 IF NOT ops.lc_current_containment_authority(p_actor,c.organization_id,store_ref,'LISTING_CONTAINMENT_CONSENT') THEN
   RAISE EXCEPTION 'current containment consent authority required' USING ERRCODE='MO092';
 END IF;
 FOR attestation IN SELECT * FROM ops.lc_containment_attestation WHERE containment_id=c.id LOOP
   required_action:=CASE WHEN attestation.attestation_kind='REPAIR_ATTESTATION'
     THEN 'LISTING_CONTAINMENT_ATTEST' ELSE 'LISTING_CONTAINMENT_CONSENT' END;
   IF NOT ops.lc_current_containment_authority(attestation.actor_user_id,c.organization_id,store_ref,required_action)
      OR (attestation.attestation_kind='REPAIR_ATTESTATION' AND NOT EXISTS(
        SELECT 1 FROM iam.user_role_assignment r WHERE r.user_id=attestation.actor_user_id
          AND r.organization_id=c.organization_id AND r.role_code=c.cause_owner_role_code AND r.status='ACTIVE'
          AND r.effective_from<=statement_timestamp() AND (r.effective_to IS NULL OR r.effective_to>statement_timestamp()))) THEN
     RAISE EXCEPTION 'containment attestation authority no longer applies' USING ERRCODE='MO092';
   END IF;
 END LOOP;
 IF c.evidence_reference LIKE 'lc-node-result:%' THEN
   SELECT r.* INTO failed FROM ops.lc_node_result r JOIN ops.lc_evaluation_plan p ON p.id=r.plan_id
    JOIN ops.lc_action a ON a.id=p.action_id
    WHERE c.evidence_reference='lc-node-result:'||r.id::text AND r.organization_id=c.organization_id
      AND c.scope_kind='LISTING' AND a.platform_listing_id=c.platform_listing_id AND r.protection_verdict='FAIL';
   IF NOT FOUND THEN RAISE EXCEPTION 'exact failed Outcome scope required' USING ERRCODE='MO092'; END IF;
   SELECT * INTO repair FROM ops.lc_containment_attestation WHERE containment_id=c.id AND attestation_kind='REPAIR_ATTESTATION';
   SELECT * INTO consent FROM ops.lc_containment_attestation WHERE containment_id=c.id AND attestation_kind='BUSINESS_CONSENT';
   SELECT r.* INTO latest FROM ops.lc_node_result r JOIN ops.lc_evaluation_plan p ON p.id=r.plan_id
    JOIN ops.lc_action a ON a.id=p.action_id
    WHERE repair.evidence_reference='lc-node-result:'||r.id::text AND r.organization_id=c.organization_id
      AND a.platform_listing_id=c.platform_listing_id AND r.evaluated_at>failed.evaluated_at;
   IF NOT FOUND THEN RAISE EXCEPTION 'repair must cite a subsequent qualified result for this Listing' USING ERRCODE='MO092'; END IF;
   -- A true past loss need not be rewritten: the repair may concern a later node or Action.
   PERFORM 1 FROM ops.lc_evaluation_plan WHERE id=latest.plan_id FOR UPDATE;
   IF latest.protection_verdict='FAIL' OR NOT latest.maturity_reached
      OR repair.attested_at<latest.evaluated_at OR consent.attested_at IS NULL OR consent.attested_at<repair.attested_at
      OR EXISTS(SELECT 1 FROM ops.lc_node_result newer WHERE newer.plan_id=latest.plan_id AND newer.node_code=latest.node_code
           AND newer.stage=latest.stage AND newer.revision_no>latest.revision_no)
      OR EXISTS(SELECT 1 FROM jsonb_each_text(failed.protection_vector) dimension WHERE dimension.value='FAIL'
           AND latest.protection_vector->>dimension.key IS DISTINCT FROM 'PASS') THEN
     RAISE EXCEPTION 'repair evidence and subsequent independent consent must still apply' USING ERRCODE='MO092';
   END IF;
 END IF;
 PERFORM ops.reenable_lc_containment_v0077(p_containment,p_actor);
END $$;

CREATE FUNCTION ops.release_ad_action_reservation(p_reservation_id uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE held ops.ad_action_reservation%ROWTYPE; c ops.ad_bid_command%ROWTYPE; packet ops.ad_manual_execution_packet%ROWTYPE;
 configuration_known boolean:=false; unresolved boolean:=true; early_complete boolean:=false; regressed boolean:=true;
 baseline_id uuid; platform_code text;
BEGIN
 SELECT * INTO held FROM ops.ad_action_reservation WHERE id=p_reservation_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'no such reservation' USING ERRCODE='MO097'; END IF;
 IF held.state='RELEASED' THEN RETURN false; END IF;
 IF p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 1 AND 256 THEN
  RAISE EXCEPTION 'release reason required' USING ERRCODE='MO097'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext('ad_action_reservation'),hashtext(held.organization_id::text));
 SELECT * INTO c FROM ops.ad_bid_command WHERE reservation_id=held.id;
 IF c.id IS NOT NULL THEN
  baseline_id:=c.outcome_baseline_id; platform_code:=c.platform_code;
  configuration_known:=c.state IN ('READBACK_MATCHED','COMPENSATED') AND EXISTS(
   SELECT 1 FROM ops.ad_bid_command_readback rb WHERE rb.command_id=c.id
   AND rb.match_state=CASE WHEN c.state='COMPENSATED' THEN 'MATCHES_PRIOR' ELSE 'MATCHES_TARGET' END
   AND rb.bid_unit_code=c.bid_unit_code AND rb.currency_code=c.currency_code
   AND rb.observed_bid=CASE WHEN c.state='COMPENSATED' THEN c.prior_bid_amount ELSE c.target_bid_amount END);
  unresolved:=c.state NOT IN ('READBACK_MATCHED','COMPENSATED');
 ELSE
  SELECT * INTO packet FROM ops.ad_manual_execution_packet WHERE reservation_id=held.id;
  baseline_id:=packet.outcome_baseline_id; platform_code:=packet.platform_code;
  configuration_known:=packet.state='MANUAL_CONFIGURATION_VERIFIED' AND EXISTS(
   SELECT 1 FROM ops.ad_manual_configuration_verification proof WHERE proof.id=packet.current_proof_id
   AND proof.packet_id=packet.id AND ops.ad_manual_observation_is_qualified(proof.id) AND proof.conflict_state='NONE'
   AND proof.evidence_grade<>'EXECUTOR_SELF_REPORT');
  unresolved:=NOT coalesce(configuration_known,false);
 END IF;
 IF baseline_id IS NOT NULL THEN
  early_complete:=EXISTS(SELECT 1 FROM ops.ad_outcome_observation o
   WHERE (o.command_id=c.id OR o.manual_packet_id=packet.id)
   AND o.outcome_stage IN ('OPERATIONAL','OPERATIONAL_REVISED') AND o.guard_state='NOT_APPLICABLE'
   AND o.verdict IN ('IMPROVED','UNCHANGED') AND o.evaluated_at>=o.window_ends_at
   AND EXISTS(SELECT 1 FROM ops.ad_outcome_axes axes WHERE axes.observation_id=o.id
     AND axes.outcome_baseline_id=baseline_id AND axes.sales_preservation_verdict='PRESERVED')
   AND NOT EXISTS(SELECT 1 FROM ops.ad_outcome_critical_unit unit WHERE unit.outcome_baseline_id=baseline_id
     AND NOT EXISTS(SELECT 1 FROM ops.ad_outcome_critical_guard guard WHERE guard.observation_id=o.id
       AND guard.outcome_baseline_id=unit.outcome_baseline_id AND guard.product_variant_id=unit.product_variant_id
       AND guard.listing_variant_id=unit.listing_variant_id AND guard.guard_state='PASS'))
   AND NOT EXISTS(SELECT 1 FROM ops.ad_outcome_observation n WHERE n.supersedes_observation_id=o.id));
  regressed:=EXISTS(SELECT 1 FROM ops.ad_outcome_observation o
   WHERE (o.command_id=c.id OR o.manual_packet_id=packet.id) AND o.verdict='REGRESSED'
   AND NOT EXISTS(SELECT 1 FROM ops.ad_outcome_observation n WHERE n.supersedes_observation_id=o.id))
   OR cardinality(ops.ad_active_containment(held.organization_id,held.ad_native_object_id,held.store_id,platform_code,
        'ad-bid-change',held.affected_set_digest))>0;
 END IF;
 UPDATE ops.ad_action_reservation SET configuration_resolved=coalesce(configuration_known,false),unknown_or_mismatch_open=unresolved,
 early_observation_complete=early_complete,regression_open=regressed,version=version+1 WHERE id=held.id;
 IF NOT coalesce(configuration_known,false) OR unresolved OR NOT early_complete OR regressed THEN RETURN false; END IF;
 UPDATE ops.ad_action_reservation SET state='RELEASED',released_at=clock_timestamp(),release_reason=p_reason,
 version=version+1 WHERE id=held.id;
 RETURN true;
END $$;

CREATE FUNCTION ops.release_lc_occupation(p_occupation uuid, p_actor uuid, p_proof text, p_basis text, p_evidence_id uuid, p_evidence text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'iam', 'pg_temp'
    AS $$
DECLARE occupation ops.lc_exposure_occupation%ROWTYPE; action ops.lc_action%ROWTYPE;
 grant_row iam.ad_invocation_grant%ROWTYPE; command ops.lc_description_command%ROWTYPE; evidence jsonb;
BEGIN
 SELECT * INTO occupation FROM ops.lc_exposure_occupation WHERE id=p_occupation FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'occupation does not exist' USING ERRCODE='MO090'; END IF;
 SELECT * INTO STRICT action FROM ops.lc_action WHERE id=occupation.action_id;
 IF NOT ops.lc_actor_holds_action(p_actor,action.organization_id,action.store_id,'LISTING_ACTION_LAUNCH') THEN
   RAISE EXCEPTION 'occupation scope authority required' USING ERRCODE='MO092';
 END IF;
 IF occupation.state='RELEASED' THEN RAISE EXCEPTION 'occupation already released' USING ERRCODE='MO091'; END IF;
 IF p_evidence IS NULL OR length(btrim(p_evidence)) NOT BETWEEN 1 AND 512 THEN
   RAISE EXCEPTION 'release evidence reference required' USING ERRCODE='MO092';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtext('lc_exposure_organization'),hashtext(action.organization_id::text));
 -- This proof means no external mutation was admitted, not merely an old-value readback.
 -- It is safe for every axis because this exact Action formed no provider obligation.
 IF p_basis='NOT_APPLIED_PROVEN' AND action.execution_path='API' THEN
   SELECT * INTO command FROM ops.lc_description_command WHERE id=p_evidence_id AND action_id=action.id FOR UPDATE;
   IF FOUND AND command.state='TERMINATED_WITHOUT_PROVIDER_CALL'
     AND command.terminal_at>=occupation.acquired_at
     AND NOT EXISTS(SELECT 1 FROM ops.lc_promotion_engagement e WHERE e.action_id=action.id)
     AND NOT EXISTS(SELECT 1 FROM ops.lc_description_command_attempt a
       WHERE a.command_id=command.id AND a.purpose IN ('APPLY','RESTORE')) THEN
     evidence:=jsonb_build_object('purpose','NOT_APPLIED','actionId',action.id,'commandId',command.id,
       'axisCode',occupation.axis_code,'terminalAt',command.terminal_at,'mutationAttemptCount',0);
   END IF;
 END IF;
 -- Generic display/description observations, self-reported promotion state and MATCHED_PRIOR
 -- are deliberately not lifecycle evidence. Qualified STOP_NEW / historical-clearing follows
 -- the independently verified lifecycle, not these old inference routes.
 IF evidence IS NULL THEN
   RAISE EXCEPTION 'exact purpose-qualified release evidence is missing' USING ERRCODE='MO092';
 END IF;
 -- All occupation, organization and command lock waits precede proof consumption.
 grant_row:=ops.consume_ad_control_invocation(p_proof,'LISTING_OCCUPATION_RELEASE',p_occupation,p_occupation);
 IF grant_row.actor_user_id<>p_actor OR grant_row.organization_id<>action.organization_id
   OR NOT ops.lc_actor_holds_action(p_actor,action.organization_id,action.store_id,'LISTING_ACTION_LAUNCH') THEN
   RAISE EXCEPTION 'exact authenticated actor and occupation scope required' USING ERRCODE='MO092';
 END IF;
 UPDATE ops.lc_exposure_occupation SET state='RELEASED',released_at=clock_timestamp(),release_basis=p_basis,
   release_evidence_reference=p_evidence,released_by_user_id=p_actor,
   release_evidence_id=p_evidence_id,release_evidence=evidence WHERE id=p_occupation;
END
$$;

CREATE FUNCTION ops.release_lc_promotion_engagement(p_engagement uuid, p_actor uuid, p_proof text, p_release_kind text, p_observation uuid, p_reference text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'iam', 'pg_temp'
    AS $$
DECLARE engagement ops.lc_promotion_engagement%ROWTYPE; observed core.lc_promotion_observation%ROWTYPE;
 provenance core.fact_provenance%ROWTYPE; item jsonb; grant_row iam.ad_invocation_grant%ROWTYPE;
 now_at timestamptz; evidence jsonb; phase_time timestamptz;
BEGIN
 SELECT * INTO engagement FROM ops.lc_promotion_engagement WHERE id=p_engagement FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'engagement does not exist' USING ERRCODE='MO090'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext('lc_exposure_organization'),hashtext(engagement.organization_id::text));
 now_at:=clock_timestamp();
 IF length(btrim(coalesce(p_reference,''))) NOT BETWEEN 1 AND 512 THEN
   RAISE EXCEPTION 'release evidence reference required' USING ERRCODE='MO092';
 END IF;
 SELECT * INTO observed FROM core.lc_promotion_observation o WHERE o.id=p_observation
   AND o.organization_id=engagement.organization_id AND o.platform_listing_id=engagement.platform_listing_id;
 IF observed.id IS NULL OR NOT ops.lc_promotion_observation_is_independent_current(observed.id,now_at)
    OR observed.coverage_from>observed.observed_at OR observed.coverage_until<=observed.observed_at THEN
   RAISE EXCEPTION 'release requires a current independent complete promotion observation' USING ERRCODE='MO092';
 END IF;
 SELECT * INTO STRICT provenance FROM core.fact_provenance WHERE id=observed.provenance_id;
 IF provenance.source_kind='MANUAL_ENTRY' AND (provenance.recorded_by_user_id=p_actor
    OR provenance.recorded_by_user_id=engagement.exit_authorized_by_user_id
    OR EXISTS(SELECT 1 FROM ops.lc_manual_packet p LEFT JOIN ops.lc_manual_report r ON r.packet_id=p.id
       WHERE p.action_id=engagement.action_id AND (p.executor_user_id=provenance.recorded_by_user_id
          OR r.reporter_user_id=provenance.recorded_by_user_id))) THEN
   RAISE EXCEPTION 'exit author or executor cannot independently prove release' USING ERRCODE='MO092';
 END IF;
 SELECT value INTO item FROM jsonb_array_elements(observed.context_snapshot)
  WHERE value#>>'{declaration,engagementKind}'=engagement.engagement_kind
    AND value#>>'{declaration,nativePromotionKey}'=engagement.native_promotion_key;
 IF item IS NULL THEN RAISE EXCEPTION 'release evidence omits the exact native engagement' USING ERRCODE='MO092'; END IF;
 IF p_release_kind='NEW_TRANSACTIONS_STOPPED' AND engagement.state='EXITING' THEN
   phase_time:=engagement.exit_authorized_at;
   IF item->>'participationState'<>'NOT_PARTICIPATING' OR item->>'newTransactionsState'<>'STOPPED' THEN
     RAISE EXCEPTION 'new-transaction cessation is not independently proven' USING ERRCODE='MO093';
   END IF;
   evidence:=jsonb_build_object('purpose','NEW_TRANSACTIONS_STOPPED','engagementId',engagement.id,
     'observationId',observed.id,'contextDigest',observed.context_digest,'termsDigest',engagement.terms_digest,
     'observedTermsDigest',ops.lc_promotion_terms_digest(item->'declaration'),
     'observedAt',observed.observed_at,'residualObligationState',item->>'residualObligationState');
 ELSIF p_release_kind='OBLIGATIONS_CLEARED' AND engagement.state='STOPPED' THEN
   phase_time:=engagement.new_transactions_stopped_at;
   IF item->>'newTransactionsState'<>'STOPPED' OR item->>'residualObligationState'<>'CLEARED' THEN
     RAISE EXCEPTION 'historical obligations are not independently proven cleared' USING ERRCODE='MO093';
   END IF;
   evidence:=jsonb_build_object('purpose','RESIDUAL_OBLIGATIONS_CLEARED','engagementId',engagement.id,
     'observationId',observed.id,'contextDigest',observed.context_digest,'termsDigest',engagement.terms_digest,
     'observedTermsDigest',ops.lc_promotion_terms_digest(item->'declaration'),
     'observedAt',observed.observed_at,'residualObligationState','CLEARED');
 ELSE
   RAISE EXCEPTION 'promotion release phase is out of order' USING ERRCODE='MO091';
 END IF;
 IF observed.observed_at<phase_time OR observed.acquired_at>now_at THEN
   RAISE EXCEPTION 'release observation must follow this exact lifecycle phase' USING ERRCODE='MO092';
 END IF;
 IF NOT ops.lc_actor_holds_action(p_actor,engagement.organization_id,engagement.store_id,'LISTING_PROMOTION_MANAGE') THEN
   RAISE EXCEPTION 'current promotion management authority required' USING ERRCODE='MO092';
 END IF;
 grant_row:=ops.consume_ad_control_invocation(p_proof,'LISTING_OCCUPATION_RELEASE',p_engagement,p_engagement);
 IF grant_row.actor_user_id<>p_actor OR grant_row.organization_id<>engagement.organization_id THEN
   RAISE EXCEPTION 'release actor must match the authenticated invocation' USING ERRCODE='MO092';
 END IF;
 IF p_release_kind='NEW_TRANSACTIONS_STOPPED' THEN
   UPDATE ops.lc_promotion_engagement SET state='STOPPED',new_transactions_stopped_at=now_at,
     stop_evidence_observation_id=observed.id,updated_at=now_at,version=version+1 WHERE id=engagement.id;
   UPDATE ops.lc_exposure_occupation SET state='RELEASED',released_at=now_at,release_basis='STOP_EVIDENCE',
     release_evidence_reference=p_reference,released_by_user_id=p_actor,release_evidence_id=observed.id,
     release_evidence=evidence||jsonb_build_object('axisCode',axis_code)
    WHERE action_id=engagement.action_id AND state<>'RELEASED'
      AND axis_code IN ('CONCURRENT_LISTINGS','AFFECTED_VARIANTS','CATEGORY_SHARE');
 ELSE
   UPDATE ops.lc_promotion_engagement SET state='CLEARED',obligations_cleared_at=now_at,
     obligation_evidence_observation_id=observed.id,updated_at=now_at,version=version+1 WHERE id=engagement.id;
   UPDATE ops.lc_exposure_occupation SET state='RELEASED',released_at=now_at,release_basis='OBLIGATION_CLEARED',
     release_evidence_reference=p_reference,released_by_user_id=p_actor,release_evidence_id=observed.id,
     release_evidence=evidence||jsonb_build_object('axisCode',axis_code)
    WHERE action_id=engagement.action_id AND state<>'RELEASED' AND axis_code='REVENUE_EXPOSURE';
 END IF;
END $$;

CREATE FUNCTION ops.renew_diagnostic_export(p_id uuid, p_token uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
 PERFORM ops.require_diagnostic_export_lease(p_id,p_token);
 UPDATE ops.diagnostic_export SET lease_until=least(deadline_at,statement_timestamp()+interval '2 minutes') WHERE id=p_id;
END $$;

CREATE FUNCTION ops.renew_ingestion_run_lease(p_run_id uuid, p_expected_fence bigint, p_expected_lease_owner text, p_lease_seconds integer) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    renewed timestamptz;
BEGIN
    IF p_lease_seconds IS NULL OR p_lease_seconds <= 0 OR p_lease_seconds > 3600 THEN
        RAISE EXCEPTION 'lease duration must be between 1 and 3600 seconds'
            USING ERRCODE = 'MO040';
    END IF;

    UPDATE ops.ingestion_run AS run
       SET lease_expires_at = clock_timestamp() + make_interval(secs => p_lease_seconds),
           updated_at = clock_timestamp()
     WHERE run.id = p_run_id
       AND run.fence_token = p_expected_fence
       AND run.lease_owner = p_expected_lease_owner
       AND run.state IN ('LEASED', 'RUNNING')
       AND run.lease_expires_at > clock_timestamp()
    RETURNING run.lease_expires_at INTO renewed;

    IF renewed IS NULL THEN
        RAISE EXCEPTION 'run % is not held by % at fence % with a live lease',
            p_run_id, p_expected_lease_owner, p_expected_fence
            USING ERRCODE = 'MO040';
    END IF;
    RETURN renewed;
END;
$$;

CREATE FUNCTION ops.reopen_ad_lineage_after_regression(p_containment_id uuid, p_observation_id uuid, p_accountable_role text, p_correlation_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'pg_temp'
    AS $$
DECLARE
    observation ops.ad_outcome_observation%ROWTYPE;
    command     ops.ad_bid_command%ROWTYPE;
    existing_id uuid;
BEGIN
    IF p_correlation_id IS NULL
        OR length(btrim(p_correlation_id)) NOT BETWEEN 1 AND 128 THEN
        RAISE EXCEPTION 'a correlation identifier is required' USING ERRCODE = 'MO098';
    END IF;

    SELECT * INTO observation FROM ops.ad_outcome_observation WHERE id = p_observation_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'no such outcome observation' USING ERRCODE = 'MO098';
    END IF;

    -- Only a settled regression reopens anything. An operational regression is
    -- a number that has not survived returns yet, and quarantining a lineage on
    -- one of those would stop work on evidence this product does not yet have.
    IF observation.outcome_stage = 'OPERATIONAL' OR observation.verdict <> 'REGRESSED'
        OR observation.guard_state <> 'SATISFIED' THEN
        RAISE EXCEPTION 'only a guarded settled regression reopens a lineage'
            USING ERRCODE = 'MO098';
    END IF;

    SELECT * INTO command FROM ops.ad_bid_command WHERE id = observation.command_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'the observation names no command' USING ERRCODE = 'MO098';
    END IF;

    -- Same lineage, so the quarantine is scoped to the affected set the command
    -- acted on rather than to the object alone. Another object promoting the
    -- same variants is part of the same question.
    SELECT c.id INTO existing_id
      FROM ops.ad_containment c
     WHERE c.organization_id = command.organization_id
       AND c.containment_kind = 'ACTION_OUTCOME_QUARANTINE'
       AND c.affected_set_digest = command.affected_set_digest
       AND c.state <> 'REENABLED';
    IF existing_id IS NOT NULL THEN
        RETURN existing_id;
    END IF;

    INSERT INTO ops.ad_containment (
        id, organization_id, containment_kind, scope_kind, affected_set_digest,
        cause_class, reason, evidence_reference, activated_by_trigger, activated_at,
        state, accountable_role_code, correlation_id, created_at, updated_at)
    VALUES (p_containment_id, command.organization_id, 'ACTION_OUTCOME_QUARANTINE',
        'AFFECTED_SET', command.affected_set_digest, 'OUTCOME_REGRESSION',
        'a settled outcome for this lineage regressed past the plan threshold',
        'ad-outcome-observation:' || p_observation_id::text,
        'SETTLED_OUTCOME_REGRESSION', clock_timestamp(), 'ACTIVE',
        p_accountable_role, p_correlation_id, clock_timestamp(), clock_timestamp());

    INSERT INTO ops.metadata_audit_event (
        id, actor_type, actor_id, source_domain, action, entity_type, entity_id,
        change_summary, reason, correlation_id)
    VALUES (gen_random_uuid(), 'SYSTEM', 'advertising-outcome', 'advertisingefficiency',
        'KILL_SWITCH', 'ad-containment', p_containment_id,
        jsonb_build_object('containmentKind',
            jsonb_build_object('previous', NULL, 'current', 'ACTION_OUTCOME_QUARANTINE'),
            'accountableRole',
            jsonb_build_object('previous', NULL, 'current', p_accountable_role)),
        'settled outcome regression reopened this lineage', p_correlation_id);

    RETURN p_containment_id;
END;
$$;

CREATE FUNCTION ops.replay_run_makes_no_call() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.run_kind = 'REPLAY' AND NEW.last_call_seq > OLD.last_call_seq THEN
        RAISE EXCEPTION 'replay run % may not acquire from a marketplace', OLD.id
            USING ERRCODE = 'MO042',
                  HINT = 'a replay reprocesses stored bytes and downloads nothing';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.request_ad_bid_readback(p_command_id uuid, p_expected_fence bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
BEGIN
    UPDATE ops.ad_bid_command
       SET requested_operation = 'READBACK', updated_at = clock_timestamp()
     WHERE id = p_command_id
       AND fence_token = p_expected_fence
       AND state = 'UNKNOWN_REQUIRES_READBACK';
    IF NOT FOUND THEN
        RAISE EXCEPTION 'a readback can only be requested for an unresolved command at its fence'
            USING ERRCODE = 'MO090';
    END IF;
END;
$$;

CREATE FUNCTION ops.request_lc_description_readback(p_command_id uuid, p_expected_fence bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
BEGIN
    UPDATE ops.lc_description_command
       SET requested_operation = 'READBACK', updated_at = clock_timestamp()
     WHERE id = p_command_id AND fence_token = p_expected_fence
       AND state = 'UNKNOWN_REQUIRES_READBACK';
    IF NOT FOUND THEN
        RAISE EXCEPTION 'a readback is requested only on an unknown command at its current fence'
            USING ERRCODE = 'MO091';
    END IF;
END;
$$;

CREATE FUNCTION ops.request_price_readback(p_command uuid, p_fence bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
    UPDATE ops.price_command SET requested_operation = 'READBACK', updated_at = clock_timestamp()
     WHERE id = p_command AND fence_token = p_fence AND state = 'UNKNOWN_REQUIRES_READBACK'
       AND lease_owner IS NULL;
    IF NOT FOUND THEN RAISE EXCEPTION 'command is not available for readback'
        USING ERRCODE = 'MO030'; END IF;
    RETURN true;
END;
$$;

CREATE FUNCTION ops.require_diagnostic_export_lease(p_id uuid, p_token uuid) RETURNS ops.diagnostic_export
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE j ops.diagnostic_export;
BEGIN
 SELECT * INTO j FROM ops.diagnostic_export WHERE id=p_id FOR UPDATE;
 IF NOT FOUND OR j.state<>'RUNNING' OR p_token IS NULL OR j.lease_token IS DISTINCT FROM p_token
   OR j.lease_until<=clock_timestamp() OR j.deadline_at<=clock_timestamp() THEN
   RAISE EXCEPTION 'export lease lost' USING ERRCODE='MO081'; END IF;
 IF NOT iam.diagnostic_export_allowed(j.requester_id,j.store_id) THEN
   RAISE EXCEPTION 'export scope denied' USING ERRCODE='MO064'; END IF;
 RETURN j;
END $$;

CREATE FUNCTION ops.schedule_ad_outcome_maturity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
DECLARE baseline ops.ad_outcome_baseline; landed timestamptz; stage ops.ad_outcome_stage_baseline;
BEGIN
    IF TG_TABLE_NAME='ad_bid_command_readback' THEN
        IF NEW.match_state<>'MATCHES_TARGET' THEN RETURN NEW; END IF;
        SELECT b.* INTO baseline FROM ops.ad_bid_command c JOIN ops.ad_outcome_baseline b ON b.id=c.outcome_baseline_id
            WHERE c.id=NEW.command_id;landed:=NEW.observed_at;
    ELSE
        IF NOT ops.ad_manual_observation_is_qualified(NEW.id) THEN RETURN NEW; END IF;
        SELECT b.* INTO baseline FROM ops.ad_manual_execution_packet p JOIN ops.ad_outcome_baseline b ON b.id=p.outcome_baseline_id
            WHERE p.id=NEW.packet_id;landed:=NEW.observed_at;
    END IF;
    IF baseline.id IS NULL THEN RETURN NEW; END IF;
    IF (CASE WHEN jsonb_typeof(baseline.plan_snapshot->'observationStartsMinutes')='number'
      THEN (baseline.plan_snapshot->>'observationStartsMinutes')::numeric NOT BETWEEN 0 AND 2147483647
        OR trunc((baseline.plan_snapshot->>'observationStartsMinutes')::numeric)<>(baseline.plan_snapshot->>'observationStartsMinutes')::numeric
      ELSE true END) THEN
        -- Preserve the external configuration fact. Missing local planning authority
        -- blocks outcome scheduling and is visible as an incident, never a zero deadline.
        INSERT INTO ops.ad_trace_event(id,organization_id,ad_native_object_id,path_kind,stage_code,status,
          correlation_id,subject_reference,detail,occurred_at)
        VALUES(gen_random_uuid(),baseline.organization_id,baseline.ad_native_object_id,'OPERATIONS','OUTCOME_MATURITY_SWEEP','FAILED',
          'outcome-deadline:'||gen_random_uuid(),baseline.id::text,
          '{"reason":"AD_OUTCOME_PLAN_DEADLINE_UNRESOLVED"}',clock_timestamp());
        RETURN NEW;
    END IF;
    FOR stage IN SELECT * FROM ops.ad_outcome_stage_baseline WHERE outcome_baseline_id=baseline.id LOOP
        INSERT INTO ops.ad_recalculation_due(organization_id,ad_native_object_id,trigger_class,source_reference,due_at)
        VALUES(baseline.organization_id,baseline.ad_native_object_id,'OUTCOME_MATURITY_OR_REGRESSION',
            'outcome:'||baseline.id||':'||stage.stage,
            landed+make_interval(mins=>(baseline.plan_snapshot->>'observationStartsMinutes')::integer,hours=>stage.window_hours))
        ON CONFLICT DO NOTHING;
    END LOOP;
    RETURN NEW;
END $$;

CREATE FUNCTION ops.schedule_ad_purpose_expiry() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'mart'
    AS $$
BEGIN
    IF NEW.expires_at IS NOT NULL AND NEW.expires_at>clock_timestamp() THEN
        INSERT INTO ops.ad_recalculation_due(organization_id,ad_native_object_id,trigger_class,source_reference,due_at)
        SELECT NEW.organization_id,c.ad_native_object_id,'FRESHNESS_OR_QUALIFICATION_POLICY',
            'purpose:'||NEW.case_id||':'||NEW.decision_purpose||':'||NEW.evidence_kind,NEW.expires_at
        FROM mart.ad_case c WHERE c.id=NEW.case_id AND c.organization_id=NEW.organization_id
        ON CONFLICT DO NOTHING;
    END IF;
    RETURN NEW;
END $$;

CREATE FUNCTION ops.seal_ad_action_authorization(p_recommendation uuid, p_approval uuid, p_baseline uuid, p_proof text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE candidate uuid;
BEGIN
 SELECT candidate_id INTO candidate FROM ops.ad_candidate_selection WHERE recommendation_id=p_recommendation;
 IF candidate IS NOT NULL AND cardinality(ops.ad_economic_cause_bound_failures(candidate,clock_timestamp()))>0 THEN
   RAISE EXCEPTION 'economic cause-specific action proof remains unresolved' USING ERRCODE='MO092'; END IF;
 RETURN ops.seal_ad_action_authorization_before_economic_cause(p_recommendation,p_approval,p_baseline,p_proof);
END $$;

CREATE FUNCTION ops.seal_ad_action_authorization_before_economic_cause(p_recommendation uuid, p_approval uuid, p_baseline uuid, p_proof text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'platform', 'iam', 'pg_temp'
    AS $$
DECLARE g iam.ad_invocation_grant%ROWTYPE; r ops.recommendation%ROWTYPE;
 a ops.approval_decision%ROWTYPE; b ops.ad_decision_policy_bundle%ROWTYPE;
 s ops.ad_candidate_selection%ROWTYPE; e ops.ad_candidate_endorsement%ROWTYPE;
 lease core.ad_approval_lease_policy%ROWTYPE; cfg core.ad_object_configuration_observation%ROWTYPE;
 candidate ops.ad_bid_candidate%ROWTYPE; kase mart.ad_case%ROWTYPE;
 deadline timestamptz; policy_end timestamptz; evidence_end timestamptz;
 snapshot jsonb; identity uuid; bounds jsonb; ordinary boolean; materiality text;
 credential_end timestamptz; baseline record; required_kinds text[];
BEGIN
 SELECT * INTO g FROM iam.ad_invocation_grant
  WHERE proof_hash=encode(sha256(convert_to(p_proof,'UTF8')),'hex') FOR UPDATE;
 IF NOT FOUND OR g.consumed_at IS NOT NULL OR g.expires_at<=clock_timestamp() OR g.purpose<>'FINAL_APPROVAL'
 OR g.recommendation_id<>p_recommendation OR g.approval_decision_id<>p_approval
 OR g.backend_pid<>pg_backend_pid() OR g.transaction_id<>txid_current()
 OR g.step_up_valid_until<=clock_timestamp()
 OR NOT EXISTS(SELECT 1 FROM iam.user_account actor JOIN iam.identity_provider provider ON provider.id=actor.identity_provider_id
 WHERE actor.id=g.actor_user_id AND actor.organization_id=g.organization_id AND actor.identity_provider_id=g.identity_provider_id
 AND actor.status='ACTIVE' AND actor.credentials_valid_from<=g.authenticated_at
 AND provider.status='ACTIVE' AND provider.verification_state='VERIFIED') THEN
  RAISE EXCEPTION 'one-use transaction-bound authenticated invocation required' USING ERRCODE='MO092'; END IF;
 SELECT * INTO r FROM ops.recommendation WHERE id=p_recommendation FOR UPDATE;
 SELECT * INTO a FROM ops.approval_decision WHERE id=p_approval;
 SELECT * INTO s FROM ops.ad_candidate_selection WHERE recommendation_id=p_recommendation;
 SELECT * INTO e FROM ops.ad_candidate_endorsement WHERE recommendation_id=p_recommendation;
 SELECT * INTO b FROM ops.ad_decision_policy_bundle WHERE id=s.bundle_id;
 SELECT * INTO candidate FROM ops.ad_bid_candidate WHERE id=s.candidate_id;
 SELECT * INTO kase FROM mart.ad_case WHERE id=candidate.case_id;
 SELECT * INTO lease FROM core.ad_approval_lease_policy WHERE id=b.approval_lease_policy_id;
 IF cardinality(ops.ad_action_blockers(candidate.candidate_basis,candidate.cause_code,kase.blocker_codes))>0 THEN
  RAISE EXCEPTION 'current action-specific evidence blockers remain unresolved' USING ERRCODE='MO092'; END IF;
 IF r.action_kind<>'AD_BID_CHANGE' OR a.decision<>'APPROVED'
 OR a.recommendation_id<>r.id OR a.decided_by_user_id IS DISTINCT FROM g.actor_user_id
 OR r.organization_id<>g.organization_id OR NOT a.step_up_satisfied
 OR s.id IS NULL OR e.id IS NULL OR e.selection_id<>s.id
 OR s.outcome_baseline_id IS DISTINCT FROM p_baseline
 OR s.maker_user_id=g.actor_user_id
 OR b.id IS NULL OR b.status<>'ACTIVE' OR b.bundle_version<>s.bundle_version
 OR lease.id IS NULL OR lease.status<>'ACTIVE'
 OR candidate.id IS DISTINCT FROM (r.proposed_parameters->>'candidateId')::uuid THEN
  RAISE EXCEPTION 'final approval identity or sealed selection is invalid' USING ERRCODE='MO092'; END IF;
 SELECT * INTO baseline FROM ops.ad_outcome_baseline frozen WHERE frozen.id=p_baseline
 AND frozen.organization_id=r.organization_id AND frozen.candidate_id=candidate.id
 AND frozen.ad_native_object_id=r.subject_id AND frozen.case_calculation_id=kase.calculation_id
 AND frozen.policy_version_digest=kase.policy_version_digest
 AND frozen.affected_set_id=kase.affected_set_id AND frozen.affected_set_digest=candidate.affected_set_digest
 AND frozen.outcome_policy_id=b.outcome_policy_id AND frozen.state='COMPLETE'
 AND frozen.prepared_at<=a.decided_at AND frozen.valid_until>a.decided_at;
 IF NOT FOUND OR ops.ad_outcome_baseline_is_canonical(p_baseline,a.decided_at) IS NOT TRUE THEN
  RAISE EXCEPTION 'exact canonical approved frozen Outcome baseline required' USING ERRCODE='MO099'; END IF;
 IF cardinality(ops.ad_action_isolation_failures(baseline.affected_set_id,baseline.id,clock_timestamp()))>0 THEN
  RAISE EXCEPTION 'known cross-domain intervention prevents isolated final approval' USING ERRCODE='MO099'; END IF;
 materiality:=ops.ad_materiality_assessment(b.id,candidate.id)->>'route';
 IF materiality IS NULL OR materiality NOT IN('ORDINARY_IMPACT','MATERIAL_IMPACT') THEN
  RAISE EXCEPTION 'all current materiality axes must resolve before final approval' USING ERRCODE='MO092'; END IF;
 ordinary:=materiality='ORDINARY_IMPACT';
 IF (NOT ordinary AND e.endorser_user_id=g.actor_user_id)
 OR NOT ops.ad_actor_has_role_scope(g.actor_user_id,r.organization_id,r.store_id,
    CASE WHEN ordinary THEN 'OPS_LEAD' ELSE 'OWNER' END,'AD_BID_CHANGE_APPROVE')
 OR NOT ops.ad_actor_covers_affected_set(g.actor_user_id,r.organization_id,kase.affected_set_id,'AD_BID_CHANGE_APPROVE')
 OR NOT ops.ad_actor_has_role_scope(e.endorser_user_id,r.organization_id,r.store_id,'OPS_LEAD','AD_BID_CHANGE_ENDORSE')
 OR NOT ops.ad_actor_covers_affected_set(e.endorser_user_id,r.organization_id,kase.affected_set_id,'AD_BID_CHANGE_ENDORSE') THEN
  RAISE EXCEPTION 'current exact Material/Ordinary scoped final approval required' USING ERRCODE='MO092'; END IF;
 SELECT min(ops.ad_credential_authority_expiry(cm.id,r.store_id)) INTO credential_end FROM platform.credential_metadata cm
 WHERE cm.organization_id=r.organization_id AND cm.marketplace_account_id=b.marketplace_account_id
 AND cm.purpose_code='ADS_WRITE' AND cm.status='ACTIVE'
 AND cm.effective_from<=a.decided_at AND (cm.scope_mode='ACCOUNT' OR EXISTS(
 SELECT 1 FROM platform.credential_store_scope cs WHERE cs.credential_id=cm.id AND cs.store_id=r.store_id));
 IF credential_end IS NULL OR credential_end<=clock_timestamp()
 OR NOT EXISTS(SELECT 1 FROM ops.ad_gate_authority gate WHERE gate.id=b.gate_authority_id
  AND gate.status='ACTIVE' AND gate.valid_from<=clock_timestamp() AND gate.valid_until>clock_timestamp()
  AND gate.bundle_id=b.id AND gate.store_id=r.store_id AND r.subject_id=ANY(gate.native_object_ids)
  AND gate.direction=candidate.direction AND gate.candidate_basis=candidate.candidate_basis) THEN
  RAISE EXCEPTION 'credential and exact Gate validity are required approval bounds' USING ERRCODE='MO092'; END IF;
 SELECT * INTO cfg FROM core.ad_object_configuration_observation c
 WHERE c.ad_native_object_id=r.subject_id AND c.organization_id=r.organization_id
 AND NOT EXISTS(SELECT 1 FROM core.ad_object_configuration_observation n WHERE n.supersedes_observation_id=c.id)
 ORDER BY c.observed_at DESC,c.id DESC LIMIT 1;
 snapshot:=ops.ad_bundle_authority_snapshot(b.id);
 IF s.authority_snapshot IS DISTINCT FROM jsonb_build_object('bid',ops.ad_bid_authority_snapshot(r.id),'bundle',snapshot)
 OR e.authority_snapshot IS DISTINCT FROM jsonb_build_object('bid',ops.ad_bid_authority_snapshot(r.id),'bundle',snapshot) THEN
  RAISE EXCEPTION 'human selection/endorsement authority changed' USING ERRCODE='MO092'; END IF;
 -- Every component contributes its finite end, including all required purposes.
 SELECT min((value->>'effective_to')::timestamptz) INTO policy_end
 FROM jsonb_each(snapshot) WHERE jsonb_typeof(value)='object';
 required_kinds:=ops.ad_required_action_evidence_kinds(candidate.candidate_basis,candidate.cause_code);
 IF required_kinds IS NULL THEN RAISE EXCEPTION 'unresolved cause-specific action evidence policy' USING ERRCODE='MO092'; END IF;
 SELECT min(least(evidence.expires_at,freshness.effective_to)) INTO evidence_end
 FROM mart.ad_case_purpose_evidence evidence
 JOIN core.ad_freshness_profile freshness ON freshness.id=evidence.freshness_profile_id
 WHERE evidence.case_id=candidate.case_id AND evidence.calculation_id=kase.calculation_id
 AND evidence.evidence_kind=ANY(required_kinds)
 AND evidence.decision_purpose=CASE WHEN candidate.direction='OPTIMIZATION_INCREASE'
     THEN 'OPTIMIZATION_BID_WRITE' ELSE 'PROTECTION_BID_WRITE' END
 HAVING count(DISTINCT evidence.evidence_kind)=cardinality(required_kinds) AND bool_and(evidence.eligible)
    AND count(evidence.expires_at)=count(*)
    AND bool_and(freshness.status='ACTIVE' AND freshness.effective_from<=a.decided_at
      AND (freshness.effective_to IS NULL OR freshness.effective_to>clock_timestamp()));
 snapshot:=snapshot || jsonb_build_object('decisionEvidence',
   (SELECT jsonb_agg(to_jsonb(evidence) ORDER BY evidence.evidence_kind)
    FROM mart.ad_case_purpose_evidence evidence WHERE evidence.case_id=candidate.case_id
    AND evidence.evidence_kind=ANY(required_kinds) AND evidence.calculation_id=kase.calculation_id
    AND evidence.decision_purpose=CASE WHEN candidate.direction='OPTIMIZATION_INCREASE'
     THEN 'OPTIMIZATION_BID_WRITE' ELSE 'PROTECTION_BID_WRITE' END));
 IF evidence_end IS NULL OR cfg.id IS NULL THEN
  RAISE EXCEPTION 'all evidence purpose expiry bounds required' USING ERRCODE='MO092'; END IF;
 deadline:=least(a.decided_at+make_interval(secs=>least(lease.lease_seconds,lease.material_lease_seconds)),
   r.valid_until,a.scope_expires_at,policy_end,evidence_end,baseline.valid_until,
   (snapshot#>>'{gate,valid_until}')::timestamptz,
   (SELECT min(ops.ad_credential_authority_expiry(cm.id,r.store_id)) FROM platform.credential_metadata cm
    WHERE cm.organization_id=r.organization_id AND cm.marketplace_account_id=b.marketplace_account_id
    AND cm.purpose_code='ADS_WRITE' AND cm.status='ACTIVE'
    AND cm.effective_from<=a.decided_at AND (cm.scope_mode='ACCOUNT' OR EXISTS(
      SELECT 1 FROM platform.credential_store_scope cs WHERE cs.credential_id=cm.id AND cs.store_id=r.store_id))),
   (SELECT min(sg.effective_to) FROM iam.user_scope_grant sg WHERE sg.user_id IN(g.actor_user_id,e.endorser_user_id,s.maker_user_id)
     AND sg.action_code IN('AD_BID_CHANGE_APPROVE','AD_BID_CHANGE_ENDORSE','ADVERTISING_TASK_ACT') AND sg.status='ACTIVE'),
   (SELECT min(role.effective_to) FROM iam.user_role_assignment role WHERE role.user_id IN(g.actor_user_id,e.endorser_user_id,s.maker_user_id)
     AND role.role_code IN('OWNER','OPS_LEAD','MARKETPLACE_OPERATOR') AND role.status='ACTIVE'));
 bounds:=jsonb_build_object('finalApprovedAt',a.decided_at,'leaseSeconds',least(lease.lease_seconds,lease.material_lease_seconds),
   'recommendation',r.valid_until,'ownerSelected',a.scope_expires_at,'policyPeriod',policy_end,
   'outcomeBaseline',baseline.valid_until,'requiredEvidenceKinds',to_jsonb(required_kinds),'requiredEvidence',evidence_end,'credentialValidity',credential_end,'gateWindow',snapshot#>'{gate,valid_until}');
 IF deadline<=clock_timestamp() THEN RAISE EXCEPTION 'approval is already expired' USING ERRCODE='MO092'; END IF;
 identity:=gen_random_uuid();
 INSERT INTO ops.ad_action_authorization VALUES(identity,r.organization_id,r.id,a.id,candidate.id,baseline.id,
   b.id,b.bundle_version,s.maker_user_id,e.endorser_user_id,g.actor_user_id,a.decided_at,deadline,bounds,snapshot,
 materiality);
 UPDATE iam.ad_invocation_grant SET consumed_at=clock_timestamp() WHERE proof_hash=g.proof_hash;
 RETURN identity;
END $$;

CREATE FUNCTION ops.select_ad_manual_packet(p_packet uuid, p_proposal uuid, p_baseline uuid, p_reason text, p_proof text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'mart', 'platform', 'iam', 'pg_temp'
    AS $$
DECLARE proposal ops.ad_manual_proposal%ROWTYPE; g iam.ad_invocation_grant%ROWTYPE;
BEGIN
 SELECT * INTO proposal FROM ops.ad_manual_proposal WHERE id=p_proposal;
 g:=ops.consume_ad_control_invocation(p_proof,'MANUAL_PACKET_SELECT',p_proposal,p_packet);
 IF proposal.id IS NULL OR g.organization_id<>proposal.organization_id OR NOT coalesce(ops.ad_manual_proposal_current(p_proposal),false)
 OR NOT ops.ad_manual_actor_scoped(g.actor_user_id,proposal.organization_id,proposal.store_id,proposal.affected_set_id,
   'MARKETPLACE_OPERATOR','ADVERTISING_TASK_ACT') OR NOT EXISTS(
   SELECT 1 FROM ops.ad_outcome_baseline b JOIN core.ad_manual_policy policy ON policy.id=proposal.policy_id
   WHERE b.id=p_baseline AND b.organization_id=proposal.organization_id AND b.manual_proposal_id=proposal.id
   AND b.ad_native_object_id=proposal.ad_native_object_id AND b.affected_set_id=proposal.affected_set_id
   AND b.affected_set_digest=proposal.affected_set_digest AND b.outcome_policy_id=policy.outcome_policy_id
   AND b.case_calculation_id=(SELECT calculation_id FROM mart.ad_case WHERE id=proposal.case_id)
   AND b.state='COMPLETE' AND b.valid_until>clock_timestamp()
   AND ops.ad_outcome_baseline_is_canonical(b.id,clock_timestamp()) IS TRUE
   AND cardinality(ops.ad_action_isolation_failures(b.affected_set_id,b.id,clock_timestamp()))=0) THEN RAISE EXCEPTION 'manual selection scope or authority denied' USING ERRCODE='MO064'; END IF;
 INSERT INTO ops.ad_manual_execution_packet(id,organization_id,case_id,ad_native_object_id,store_id,platform_code,
   affected_set_id,affected_set_digest,semantic_profile_id,action_kind,observed_configuration_id,intended_state,
   reason,evidence_reference,maker_user_id,expected_impact,verification_plan,state,issued_at,expires_at,correlation_id,
   created_at,updated_at,proposal_id,manual_policy_id,authority_snapshot,outcome_baseline_id)
 SELECT p_packet,proposal.organization_id,proposal.case_id,proposal.ad_native_object_id,proposal.store_id,o.platform_code,
   proposal.affected_set_id,proposal.affected_set_digest,o.semantic_profile_id,proposal.action_kind,proposal.observed_configuration_id,
   proposal.intended_state,p_reason,'manual-proposal:'||proposal.id,g.actor_user_id,
   jsonb_build_object('responsibilityRecommendationId',proposal.responsibility_recommendation_id,'state','OUTCOME_UNPROVEN'),
   jsonb_build_object('evidenceGrade','INDEPENDENT_OR_OFFICIAL','mode',policy.verification_mode,'policyId',policy.id,
     'policyVersion',policy.policy_version,'apiProfileState',profile.verification_state),
   'MANUAL_PACKET_DRAFT',clock_timestamp(),proposal.expires_at,'manual:'||p_packet,clock_timestamp(),clock_timestamp(),
   proposal.id,policy.id,proposal.authority_snapshot,p_baseline
 FROM core.ad_native_object o JOIN core.ad_manual_policy policy ON policy.id=proposal.policy_id
 JOIN platform.ad_semantic_profile profile ON profile.id=o.semantic_profile_id WHERE o.id=proposal.ad_native_object_id;
 RETURN p_packet;
END $$;

CREATE FUNCTION ops.snapshot_diagnostic_export(p_id uuid, p_token uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    SET "TimeZone" TO 'UTC'
    SET enable_nestloop TO 'off'
    SET jit TO 'off'
    AS $$
DECLARE j ops.diagnostic_export; n integer; bytes bigint; taken_at timestamptz;
BEGIN
 j:=ops.require_diagnostic_export_lease(p_id,p_token);
 IF j.snapshot_at IS NOT NULL THEN RETURN; END IF;
 taken_at:=clock_timestamp();
 -- This bulk query discourages nested loops only within this function: fresh
 -- small-table statistics otherwise caused millions of repeated CTE probes.
 -- JIT is off here to avoid compilation overhead for bounded background jobs.
 -- All four record families are read by this one MVCC statement. A finding's
 -- referenced metric versions are included even when they are no longer latest.
 WITH subjects AS MATERIALIZED (
   SELECT 'STORE'::text kind,j.store_id id UNION ALL
   SELECT 'PLATFORM_LISTING_VARIANT',v.id FROM core.platform_listing_variant v
     JOIN core.platform_listing l ON l.id=v.platform_listing_id
     WHERE l.store_id=j.store_id AND v.organization_id=j.organization_id
 ), findings AS MATERIALIZED (
   SELECT DISTINCT ON (f.subject_kind,f.subject_id,f.rule_code) f.* FROM mart.diagnosis_finding f
     JOIN subjects s ON s.kind=f.subject_kind AND s.id=f.subject_id
     WHERE f.organization_id=j.organization_id AND f.window_code=j.window_code
     ORDER BY f.subject_kind,f.subject_id,f.rule_code,f.evaluated_at DESC,f.id DESC
 ), latest_metrics AS MATERIALIZED (
   SELECT DISTINCT ON (m.subject_kind,m.subject_id,m.metric_code) m.id FROM mart.metric_value m
     JOIN subjects s ON s.kind=m.subject_kind AND s.id=m.subject_id
     WHERE m.organization_id=j.organization_id AND m.window_code=j.window_code
     ORDER BY m.subject_kind,m.subject_id,m.metric_code,m.computed_at DESC,m.id DESC
 ), metric_ids AS MATERIALIZED (
   SELECT id,bool_or(is_current) is_current FROM (
     SELECT id,true is_current FROM latest_metrics UNION ALL
     SELECT i.metric_value_id,false FROM mart.diagnosis_finding_input i JOIN findings f ON f.id=i.finding_id
   ) selected GROUP BY id
 ), metrics AS MATERIALIZED (
   SELECT m.*,ids.is_current FROM mart.metric_value m JOIN metric_ids ids ON ids.id=m.id
     JOIN subjects s ON s.kind=m.subject_kind AND s.id=m.subject_id
     WHERE m.organization_id=j.organization_id
 ), records AS (
   SELECT 1 family,m.id id,jsonb_build_object('schemaVersion',1,'recordType','METRIC','metricValueId',m.id,
     'metricCode',m.metric_code,'definitionVersion',m.definition_version,'subjectKind',m.subject_kind,
     'subjectId',m.subject_id,'window',m.window_code,'periodStart',m.period_start,'periodEnd',m.period_end,
     'valueState',m.value_state,'numericValue',m.numeric_value::text,'currencyCode',m.currency_code,
     'confidenceState',m.confidence_state,'estimated',m.estimated,'oldestSourceTime',m.oldest_source_time,
     'freshnessSeconds',m.freshness_seconds,'inputDigest',m.input_digest,'computedAt',m.computed_at,
     'current',m.is_current) payload FROM metrics m
   UNION ALL SELECT 2,i.id,jsonb_build_object('schemaVersion',1,'recordType','METRIC_INPUT',
     'metricValueId',i.metric_value_id,'referenceKind',i.reference_kind,'referenceId',i.reference_id)
     FROM mart.metric_input_reference i JOIN metrics m ON m.id=i.metric_value_id
   UNION ALL SELECT 3,f.id,jsonb_build_object('schemaVersion',1,'recordType','FINDING','findingId',f.id,
     'ruleCode',f.rule_code,'ruleVersion',f.rule_version,'subjectKind',f.subject_kind,'subjectId',f.subject_id,
     'window',f.window_code,'periodStart',f.period_start,'periodEnd',f.period_end,'outcome',f.outcome,
     'severity',f.severity,'declineReason',f.decline_reason,'inputDigest',f.input_digest,
     'blocksExecution',r.blocks_execution,'evaluatedAt',f.evaluated_at)
     FROM findings f JOIN mart.diagnosis_rule r ON r.rule_code=f.rule_code AND r.rule_version=f.rule_version
   UNION ALL SELECT 4,i.id,jsonb_build_object('schemaVersion',1,'recordType','FINDING_INPUT',
     'findingId',i.finding_id,'metricValueId',i.metric_value_id,'role',i.role)
     FROM mart.diagnosis_finding_input i JOIN findings f ON f.id=i.finding_id
     JOIN metrics m ON m.id=i.metric_value_id
   -- Refuse a finding with an input outside this authorized snapshot instead
   -- of silently dropping an input and publishing incomplete evidence.
   UNION ALL SELECT 0,j.id,NULL::jsonb WHERE EXISTS (
     SELECT 1 FROM mart.diagnosis_finding_input i JOIN findings f ON f.id=i.finding_id
       WHERE NOT EXISTS (SELECT 1 FROM metrics m WHERE m.id=i.metric_value_id))
 ), bounded AS (SELECT * FROM records ORDER BY family,id LIMIT 1000001)
 INSERT INTO mart.diagnostic_export_row(export_id,ordinal,payload)
 SELECT p_id,row_number() OVER (ORDER BY family,id),payload::text FROM bounded;
 SELECT count(*),coalesce(sum(byte_length),0) INTO n,bytes FROM mart.diagnostic_export_row WHERE export_id=p_id;
 IF n>1000000 OR bytes>268435456 THEN RAISE EXCEPTION 'export limit exceeded' USING ERRCODE='MO082'; END IF;
 UPDATE ops.diagnostic_export SET snapshot_at=taken_at,row_count=n,byte_length=bytes WHERE id=p_id RETURNING * INTO j;
 PERFORM ops.audit_diagnostic_export(j,'SNAPSHOTTED');
END $$;

CREATE FUNCTION ops.start_ad_manual_execution(p_packet uuid, p_expected bigint, p_proof text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'mart', 'iam', 'pg_temp'
    AS $$
DECLARE packet ops.ad_manual_execution_packet%ROWTYPE; g iam.ad_invocation_grant%ROWTYPE; reservation uuid;
 variants uuid[]; lane text;
BEGIN
 SELECT * INTO packet FROM ops.ad_manual_execution_packet WHERE id=p_packet FOR UPDATE;
 g:=ops.consume_ad_control_invocation(p_proof,'MANUAL_EXECUTION_START',p_packet,p_packet);
 IF packet.id IS NULL OR packet.version<>p_expected OR g.organization_id<>packet.organization_id
 OR packet.state<>'MANUAL_PACKET_ISSUED' OR packet.approver_user_id IS NULL OR packet.endorser_user_id IS NULL
 OR NOT coalesce(ops.ad_manual_proposal_current(packet.proposal_id),false)
 OR NOT EXISTS(SELECT 1 FROM ops.ad_outcome_baseline b WHERE b.id=packet.outcome_baseline_id AND b.manual_proposal_id=packet.proposal_id AND b.state='COMPLETE' AND b.valid_until>clock_timestamp()
   AND ops.ad_outcome_baseline_is_canonical(b.id,clock_timestamp()) IS TRUE
   AND cardinality(ops.ad_action_isolation_failures(b.affected_set_id,b.id,clock_timestamp()))=0)
 OR NOT ops.ad_manual_actor_scoped(g.actor_user_id,packet.organization_id,packet.store_id,packet.affected_set_id,
   'MARKETPLACE_OPERATOR','ADVERTISING_MANUAL_EXECUTE')
 OR NOT ops.ad_manual_actor_scoped(packet.endorser_user_id,packet.organization_id,packet.store_id,packet.affected_set_id,
   'OPS_LEAD','ADVERTISING_MANUAL_ENDORSE')
 OR NOT ops.ad_manual_actor_scoped(packet.approver_user_id,packet.organization_id,packet.store_id,packet.affected_set_id,
   'OWNER','ADVERTISING_MANUAL_APPROVE') THEN RAISE EXCEPTION 'manual execution authority or live scope denied' USING ERRCODE='MO064'; END IF;
 IF cardinality(ops.ad_active_containment(packet.organization_id,packet.ad_native_object_id,packet.store_id,
   packet.platform_code,'ad-bid-change',packet.affected_set_digest))>0 THEN RAISE EXCEPTION 'manual execution is contained' USING ERRCODE='MO097'; END IF;
 SELECT a.product_variant_ids,c.lane INTO variants,lane FROM core.ad_affected_set a JOIN mart.ad_case c ON c.affected_set_id=a.id WHERE c.id=packet.case_id;
 reservation:=ops.take_ad_action_reservation(gen_random_uuid(),packet.organization_id,packet.ad_native_object_id,
   packet.store_id,packet.affected_set_id,packet.affected_set_digest,variants,'CONFIRMED_MANUAL_PACKET',packet.id,
   coalesce(packet.intended_state->>'direction','PROTECTION_DECREASE'),lane,'manual:'||packet.id);
 UPDATE ops.ad_manual_execution_packet SET executor_user_id=g.actor_user_id,execution_started_at=clock_timestamp(),
   reservation_id=reservation,state='MANUAL_EXECUTION_IN_PROGRESS',updated_at=clock_timestamp(),version=version+1 WHERE id=p_packet;
END $$;

CREATE FUNCTION ops.submit_diagnostic_export(p_actor uuid, p_store uuid, p_window text, p_key text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE j ops.diagnostic_export; org uuid;
BEGIN
 IF p_window IS NULL OR p_window NOT IN ('D7','D14','D30') OR p_key IS NULL OR p_key !~ '^[0-9a-f]{64}$' THEN
   RAISE EXCEPTION 'invalid export request' USING ERRCODE='MO039'; END IF;
 IF NOT iam.diagnostic_export_allowed(p_actor,p_store) THEN
   RAISE EXCEPTION 'export scope denied' USING ERRCODE='MO064'; END IF;
 SELECT organization_id INTO STRICT org FROM core.store WHERE id=p_store;
 PERFORM pg_advisory_xact_lock(hashtextextended('diagnostic-export:'||org::text,0));
 SELECT * INTO j FROM ops.diagnostic_export WHERE requester_id=p_actor AND request_key_hash=p_key;
 IF FOUND THEN
   IF j.store_id<>p_store OR j.window_code<>p_window THEN
     RAISE EXCEPTION 'export key conflict' USING ERRCODE='MO061'; END IF;
   RETURN j.id;
 END IF;
 IF (SELECT count(*) FROM ops.diagnostic_export WHERE organization_id=org AND state IN ('QUEUED','RUNNING'))>=2
   OR (SELECT count(*) FROM ops.diagnostic_export WHERE organization_id=org AND created_at>statement_timestamp()-interval '1 hour')>=10 THEN
   RAISE EXCEPTION 'export queue full' USING ERRCODE='MO080'; END IF;
 INSERT INTO ops.diagnostic_export(id,organization_id,store_id,requester_id,window_code,request_key_hash,state)
 VALUES(gen_random_uuid(),org,p_store,p_actor,p_window,p_key,'QUEUED') RETURNING * INTO j;
 PERFORM ops.audit_diagnostic_export(j,'SUBMITTED'); RETURN j.id;
END $_$;

CREATE FUNCTION ops.take_ad_action_reservation(p_id uuid, p_org uuid, p_object uuid, p_store uuid, p_set uuid, p_digest text, p_variants uuid[], p_kind text, p_reference uuid, p_direction text, p_lane text, p_correlation text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'pg_temp'
    AS $$
DECLARE result uuid; failures text[]; baseline_id uuid;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('ad_action_reservation'),hashtext(p_org::text));
 IF NOT EXISTS(SELECT 1 FROM core.ad_affected_set a JOIN core.ad_native_object o ON o.id=a.ad_native_object_id
 WHERE a.id=p_set AND a.organization_id=p_org AND a.ad_native_object_id=p_object
 AND o.store_id=p_store AND a.resolution_state='COMPLETE' AND a.affected_set_digest=p_digest
 AND ARRAY(SELECT DISTINCT v FROM unnest(a.product_variant_ids) v ORDER BY v)
     =ARRAY(SELECT DISTINCT v FROM unnest(p_variants) v ORDER BY v)
 AND NOT EXISTS(SELECT 1 FROM core.ad_affected_set n WHERE n.ad_native_object_id=a.ad_native_object_id
     AND n.resolved_at>a.resolved_at)) THEN
  RAISE EXCEPTION 'reservation must identify the exact current canonical affected set' USING ERRCODE='MO097'; END IF;
 IF p_kind='CONTROLLED_AD_BID_CHANGE' AND NOT EXISTS(SELECT 1 FROM ops.ad_bid_candidate candidate
 WHERE candidate.id=p_reference AND candidate.organization_id=p_org AND candidate.ad_native_object_id=p_object
 AND candidate.affected_set_digest=p_digest AND candidate.direction=p_direction
 AND EXISTS(SELECT 1 FROM ops.ad_action_authorization authorized WHERE authorized.candidate_id=candidate.id
 AND authorized.expires_at>clock_timestamp() AND NOT EXISTS(SELECT 1 FROM ops.ad_authority_invalidation invalidated
 WHERE invalidated.authorization_id=authorized.id)))
 OR p_kind='CONFIRMED_MANUAL_PACKET' AND NOT EXISTS(SELECT 1 FROM ops.ad_manual_execution_packet packet
 WHERE packet.id=p_reference AND packet.organization_id=p_org AND packet.ad_native_object_id=p_object
 AND packet.affected_set_id=p_set AND packet.affected_set_digest=p_digest AND packet.state='MANUAL_PACKET_ISSUED')
 OR p_kind='EXACT_PRIOR_BID_COMPENSATION' THEN
  RAISE EXCEPTION 'reservation requires exact intervention; compensation retains the original reservation' USING ERRCODE='MO097'; END IF;
 IF p_kind='CONTROLLED_AD_BID_CHANGE' THEN
  SELECT authorized.outcome_baseline_id INTO baseline_id FROM ops.ad_action_authorization authorized
   WHERE authorized.candidate_id=p_reference;
 ELSIF p_kind='CONFIRMED_MANUAL_PACKET' THEN
  SELECT packet.outcome_baseline_id INTO baseline_id FROM ops.ad_manual_execution_packet packet WHERE packet.id=p_reference;
 END IF;
 failures:=ops.ad_action_isolation_failures(p_set,baseline_id,clock_timestamp());
 IF cardinality(failures)>0 THEN
  RAISE EXCEPTION 'cross-domain isolation admission refused: %',array_to_string(failures,',') USING ERRCODE='MO097'; END IF;
 result:=ops.take_ad_action_reservation_serialized(p_id,p_org,p_object,p_store,p_set,p_digest,p_variants,
   p_kind,p_reference,p_direction,p_lane,p_correlation);
 failures:=ops.ad_exposure_failures(p_org,p_store,p_direction);
 IF cardinality(failures)>0 THEN RAISE EXCEPTION 'exposure admission refused: %',array_to_string(failures,',') USING ERRCODE='MO097'; END IF;
 RETURN result;
END $$;

CREATE FUNCTION ops.take_ad_action_reservation_serialized(p_id uuid, p_organization_id uuid, p_ad_native_object_id uuid, p_store_id uuid, p_affected_set_id uuid, p_affected_set_digest text, p_product_variant_ids uuid[], p_intervention_kind text, p_intervention_reference_id uuid, p_direction text, p_lane text, p_correlation_id text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'core', 'pg_temp'
    AS $$
DECLARE
    blocking_id   uuid;
    blocking_lane text;
    existing_id   uuid;
BEGIN
    IF p_correlation_id IS NULL
        OR length(btrim(p_correlation_id)) NOT BETWEEN 1 AND 128 THEN
        RAISE EXCEPTION 'a correlation identifier is required' USING ERRCODE = 'MO097';
    END IF;

    -- Everything below happens in a defined order per organization.
    PERFORM pg_advisory_xact_lock(hashtext('ad_action_reservation'),
                                  hashtext(p_organization_id::text));

    -- Idempotent on the intervention. One decision holds one reservation, so a
    -- retried worker finds its own rather than taking a second.
    SELECT r.id INTO existing_id
      FROM ops.ad_action_reservation r
     WHERE r.organization_id = p_organization_id
       AND r.intervention_kind = p_intervention_kind
       AND r.intervention_reference_id = p_intervention_reference_id
       AND r.state = 'ACTIVE';
    IF existing_id IS NOT NULL THEN
        RETURN existing_id;
    END IF;

    SELECT o.reservation_id, o.lane INTO blocking_id, blocking_lane
      FROM ops.ad_overlapping_reservation(p_organization_id, p_product_variant_ids,
                                          p_ad_native_object_id) o
     LIMIT 1;
    IF blocking_id IS NOT NULL THEN
        RAISE EXCEPTION
            'an active % reservation already holds one of these product variants',
            blocking_lane USING ERRCODE = 'MO097';
    END IF;

    -- An object also holds at most one live reservation of its own, whatever the
    -- affected set says. Two decisions about one object are two decisions about
    -- one bid.
    IF EXISTS (SELECT 1 FROM ops.ad_action_reservation r
                WHERE r.organization_id = p_organization_id
                  AND r.ad_native_object_id = p_ad_native_object_id
                  AND r.state = 'ACTIVE') THEN
        RAISE EXCEPTION 'this advertising object already holds an active reservation'
            USING ERRCODE = 'MO097';
    END IF;

    INSERT INTO ops.ad_action_reservation (
        id, organization_id, ad_native_object_id, store_id, affected_set_id,
        affected_set_digest, product_variant_ids, intervention_kind,
        intervention_reference_id, direction, lane, state, reserved_at, correlation_id)
    VALUES (p_id, p_organization_id, p_ad_native_object_id, p_store_id, p_affected_set_id,
        p_affected_set_digest, p_product_variant_ids, p_intervention_kind,
        p_intervention_reference_id, p_direction, p_lane, 'ACTIVE',
        clock_timestamp(), p_correlation_id);
    RETURN p_id;
END;
$$;

CREATE FUNCTION ops.transition_ad_bid_command(p_command_id uuid, p_expected_fence bigint, p_expected_lease_owner text, p_to_state text, p_failure_code text, p_retry_delay_seconds integer, p_evidence_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE
    command    ops.ad_bid_command%ROWTYPE;
    edge       ops.ad_bid_command_transition%ROWTYPE;
    now_at     timestamptz := clock_timestamp();
BEGIN
    SELECT * INTO command FROM ops.ad_bid_command WHERE id = p_command_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'command does not exist' USING ERRCODE = 'MO090';
    END IF;

    SELECT * INTO edge FROM ops.ad_bid_command_transition
     WHERE from_state = command.state AND to_state = p_to_state;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'transition % -> % is not in the reviewed set',
            command.state, p_to_state USING ERRCODE = 'MO091';
    END IF;

    IF edge.requires_lease THEN
        IF command.fence_token <> p_expected_fence
            OR command.lease_owner IS DISTINCT FROM p_expected_lease_owner
            OR command.lease_expires_at IS NULL
            OR command.lease_expires_at <= now_at THEN
            RAISE EXCEPTION 'the lease that authorised this transition is not current'
                USING ERRCODE = 'MO090';
        END IF;
    END IF;

    -- A retry lease invalidates the prior fence's readback. Its only route to
    -- another APPLY is a newly recorded readback at this exact active lease.
    IF command.state = 'LEASED' AND p_to_state = 'READBACK_PENDING' THEN
        IF command.retry_preflight_fence IS DISTINCT FROM command.fence_token
            OR NOT EXISTS (SELECT 1 FROM ops.ad_bid_command_attempt previous_apply
                WHERE previous_apply.command_id = p_command_id AND previous_apply.purpose = 'APPLY') THEN
            RAISE EXCEPTION 'a governed retry lease is required for preflight readback'
                USING ERRCODE = 'MO092';
        END IF;
    END IF;
    IF p_to_state = 'EXECUTING' THEN
        IF (command.state = 'LEASED' AND command.retry_preflight_fence = command.fence_token)
            OR (command.state = 'READBACK_PENDING'
                AND (command.retry_preflight_fence IS DISTINCT FROM command.fence_token
                    OR NOT ops.ad_bid_retry_is_proven(p_command_id))) THEN
            RAISE EXCEPTION 'retry requires fresh proof at the current lease fence'
                USING ERRCODE = 'MO092';
        END IF;
    END IF;

    -- Success requires evidence, in the same transaction, at the current fence.
    IF p_to_state = 'READBACK_MATCHED' THEN
        IF NOT EXISTS (
            SELECT 1 FROM ops.ad_bid_command_readback rb
              JOIN ops.ad_bid_command_attempt at ON at.id = rb.attempt_id
             WHERE rb.id = p_evidence_id
               AND rb.command_id = p_command_id
               AND rb.match_state = 'MATCHES_TARGET'
               AND rb.observed_bid = command.target_bid_amount
               AND rb.currency_code = command.currency_code
               AND rb.bid_unit_code = command.bid_unit_code
               AND at.purpose = 'READBACK'
               AND at.fence_token = command.fence_token
               AND at.raw_observation_id IS NOT NULL) THEN
            RAISE EXCEPTION 'a matched readback at the current fence is required for success'
                USING ERRCODE = 'MO093';
        END IF;
    END IF;

    -- Compensation is only safe while the bid is still what this command wrote.
    IF p_to_state = 'RETRY_WAIT' AND NOT ops.ad_bid_retry_is_proven(p_command_id) THEN
        RAISE EXCEPTION 'retry requires status/readback-first proof and all current authorities' USING ERRCODE='MO092';
    END IF;
    IF p_to_state = 'COMPENSATION_PENDING' THEN
        IF cardinality(ops.evaluate_ad_bid_compensation_gate(p_command_id))>0 THEN
            RAISE EXCEPTION 'new exact human compensation authority required' USING ERRCODE='MO094';
        END IF;
        IF NOT EXISTS (
            SELECT 1 FROM ops.ad_bid_command_readback rb
             WHERE rb.command_id = p_command_id
               AND rb.observed_at = (SELECT max(latest.observed_at)
                                       FROM ops.ad_bid_command_readback latest
                                      WHERE latest.command_id = p_command_id)
               AND rb.match_state = 'MATCHES_TARGET')
            OR NOT EXISTS (
            SELECT 1 FROM ops.ad_bid_command_attempt at
             WHERE at.command_id = p_command_id
               AND at.purpose = 'APPLY'
               AND at.outcome_class IN ('ACCEPTED', 'UNKNOWN_STATE')) THEN
            RAISE EXCEPTION 'a compensation may not overwrite a value this command did not write'
                USING ERRCODE = 'MO094';
        END IF;
    END IF;

    IF p_to_state IN ('FAILED_FINAL', 'COMPENSATION_FAILED',
                      'TERMINATED_WITHOUT_PROVIDER_CALL')
        AND p_failure_code IS NULL THEN
        RAISE EXCEPTION 'a terminal failure names its reason' USING ERRCODE = 'MO091';
    END IF;

    UPDATE ops.ad_bid_command
       SET state = p_to_state,
           lease_owner = CASE WHEN edge.releases_lease THEN NULL ELSE lease_owner END,
           lease_expires_at = CASE WHEN edge.releases_lease THEN NULL ELSE lease_expires_at END,
           retry_preflight_fence = CASE WHEN edge.releases_lease OR p_to_state = 'EXECUTING'
               THEN NULL ELSE retry_preflight_fence END,
           retry_budget_remaining = CASE WHEN p_to_state = 'RETRY_WAIT'
               THEN greatest(retry_budget_remaining - 1, 0) ELSE retry_budget_remaining END,
           next_attempt_at = CASE WHEN p_to_state = 'RETRY_WAIT'
               THEN now_at + make_interval(secs => coalesce(p_retry_delay_seconds, 60))
               ELSE NULL END,
           requested_operation = CASE WHEN p_to_state = 'READBACK_PENDING'
               THEN NULL ELSE requested_operation END,
           failure_code = coalesce(p_failure_code, failure_code),
           terminal_at = CASE WHEN p_to_state IN ('READBACK_MATCHED', 'FAILED_FINAL',
                                                  'TERMINATED_WITHOUT_PROVIDER_CALL',
                                                  'COMPENSATED', 'COMPENSATION_FAILED')
               THEN now_at ELSE terminal_at END,
           updated_at = now_at
     WHERE id = p_command_id;

    RETURN p_to_state;
END;
$$;

CREATE FUNCTION ops.transition_ingestion_run(p_run_id uuid, p_expected_fence bigint, p_expected_lease_owner text, p_to_state text, p_lease_seconds integer, p_failure_code text, p_retry_delay_seconds integer DEFAULT 120) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    run_row       record;
    allowed       boolean;
    releases      boolean;
    updated_state text;
BEGIN
    IF p_to_state='RETRY_WAIT' AND (p_retry_delay_seconds IS NULL OR p_retry_delay_seconds < 1 OR p_retry_delay_seconds > 3600) THEN
        RAISE EXCEPTION 'retry delay is outside its bound' USING ERRCODE='MO040';
    END IF;
    SELECT run.id, run.state, run.fence_token, run.lease_owner, run.lease_expires_at,
           run.attempt_no, run.max_claims
      INTO run_row
      FROM ops.ingestion_run AS run
     WHERE run.id = p_run_id
       FOR UPDATE OF run;

    IF run_row.id IS NULL THEN
        RAISE EXCEPTION 'run % does not exist', p_run_id USING ERRCODE = 'MO040';
    END IF;

    IF p_to_state='RETRY_WAIT' AND run_row.attempt_no >= run_row.max_claims THEN
        p_to_state := 'FAILED_TERMINAL';
        p_failure_code := 'RETRY_BUDGET_EXHAUSTED';
    END IF;

    allowed := (run_row.state, p_to_state) IN (
        ('LEASED', 'RUNNING'),
        ('LEASED', 'QUEUED'),
        ('RUNNING', 'SUCCEEDED'),
        ('RUNNING', 'RETRY_WAIT'),
        ('RUNNING', 'BLOCKED'),
        ('RUNNING', 'FAILED_TERMINAL'),
        ('LEASED', 'FAILED_TERMINAL'),
        ('BLOCKED', 'RETRY_WAIT'),
        ('BLOCKED', 'FAILED_TERMINAL'));

    IF NOT allowed THEN
        RAISE EXCEPTION 'run % may not move from % to %',
            p_run_id, run_row.state, p_to_state
            USING ERRCODE = 'MO041';
    END IF;

    IF run_row.fence_token <> p_expected_fence
        OR run_row.lease_owner IS DISTINCT FROM p_expected_lease_owner
        OR run_row.lease_expires_at IS NULL
        OR run_row.lease_expires_at <= clock_timestamp()
    THEN
        RAISE EXCEPTION 'run % is not held by % at fence % with a live lease',
            p_run_id, p_expected_lease_owner, p_expected_fence
            USING ERRCODE = 'MO040';
    END IF;

    IF p_to_state = 'FAILED_TERMINAL'
        AND (p_failure_code IS NULL OR length(btrim(p_failure_code)) = 0)
    THEN
        RAISE EXCEPTION 'a terminal failure of run % must name a reason', p_run_id
            USING ERRCODE = 'MO041';
    END IF;

    releases := p_to_state IN ('QUEUED', 'RETRY_WAIT', 'BLOCKED',
                               'SUCCEEDED', 'FAILED_TERMINAL');

    UPDATE ops.ingestion_run AS run
       SET state = p_to_state,
           next_attempt_at = CASE WHEN p_to_state='RETRY_WAIT'
               THEN GREATEST(clock_timestamp()+make_interval(secs=>p_retry_delay_seconds),
                   (SELECT quota.blocked_until FROM platform.ingestion_job job
                       JOIN ops.endpoint_quota_window quota ON quota.endpoint_id=job.endpoint_id WHERE job.id=run.job_id))
               ELSE NULL END,
           lease_owner = CASE WHEN releases THEN NULL ELSE run.lease_owner END,
           lease_expires_at = CASE
                                  WHEN releases THEN NULL
                                  WHEN p_lease_seconds IS NULL THEN run.lease_expires_at
                                  ELSE clock_timestamp()
                                       + make_interval(secs => p_lease_seconds)
                              END,
           failure_code = CASE WHEN p_to_state = 'FAILED_TERMINAL'
                                   THEN p_failure_code ELSE NULL END,
           updated_at = clock_timestamp()
     WHERE run.id = p_run_id
       AND run.state = run_row.state
       AND run.fence_token = p_expected_fence
    RETURNING run.state INTO updated_state;

    IF updated_state IS NULL THEN
        RAISE EXCEPTION 'run % changed while transitioning to %', p_run_id, p_to_state
            USING ERRCODE = 'MO040';
    END IF;
    RETURN updated_state;
END;
$$;

CREATE FUNCTION ops.transition_lc_description_command(p_command_id uuid, p_expected_fence bigint, p_expected_lease_owner text, p_to_state text, p_failure_code text, p_retry_delay_seconds integer, p_evidence_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE
    command ops.lc_description_command%ROWTYPE;
    edge    ops.lc_description_command_transition%ROWTYPE;
    now_at  timestamptz := clock_timestamp();
    restoration boolean;
BEGIN
    SELECT * INTO command FROM ops.lc_description_command WHERE id = p_command_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'command does not exist' USING ERRCODE = 'MO090'; END IF;
    SELECT * INTO edge FROM ops.lc_description_command_transition
     WHERE from_state = command.state AND to_state = p_to_state;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'transition % -> % is not in the reviewed set', command.state, p_to_state
            USING ERRCODE = 'MO091';
    END IF;
    IF edge.requires_lease THEN
        IF command.fence_token <> p_expected_fence
            OR command.lease_owner IS DISTINCT FROM p_expected_lease_owner
            OR command.lease_expires_at IS NULL OR command.lease_expires_at <= now_at THEN
            RAISE EXCEPTION 'the lease that authorised this transition is not current'
                USING ERRCODE = 'MO090';
        END IF;
    END IF;
    SELECT restores_command_id IS NOT NULL INTO restoration FROM ops.lc_action WHERE id=command.action_id;
    IF command.state = 'LEASED' AND p_to_state = 'READBACK_PENDING' AND NOT restoration THEN
        IF command.retry_preflight_fence IS DISTINCT FROM command.fence_token
            OR NOT EXISTS (SELECT 1 FROM ops.lc_description_command_attempt previous_apply
                            WHERE previous_apply.command_id = p_command_id AND previous_apply.purpose = 'APPLY') THEN
            RAISE EXCEPTION 'a governed retry lease is required for preflight readback' USING ERRCODE = 'MO092';
        END IF;
    END IF;
    IF p_to_state = 'EXECUTING' THEN
        IF restoration THEN
            IF command.state<>'READBACK_PENDING' OR ops.lc_restoration_preflight_version(command.id) IS NULL
                OR cardinality(ops.evaluate_lc_description_write_gate(command.id))>0
                OR (EXISTS (SELECT 1 FROM ops.lc_description_command_attempt a
                    WHERE a.command_id=command.id AND a.purpose IN ('APPLY','RESTORE'))
                    AND NOT ops.lc_description_retry_is_proven(command.id)) THEN
                RAISE EXCEPTION 'restoration requires current exact preflight and its own authority' USING ERRCODE='MO094';
            END IF;
        ELSIF (command.state = 'LEASED' AND command.retry_preflight_fence = command.fence_token)
            OR (command.state = 'READBACK_PENDING'
                AND (command.retry_preflight_fence IS DISTINCT FROM command.fence_token
                     OR NOT ops.lc_description_retry_is_proven(p_command_id))) THEN
            RAISE EXCEPTION 'retry requires fresh proof at the current lease fence' USING ERRCODE='MO092';
        END IF;
    END IF;
    IF p_to_state = 'READBACK_MATCHED' THEN
        IF NOT EXISTS (SELECT 1 FROM ops.lc_description_command_readback rb
                         JOIN ops.lc_description_command_attempt at ON at.id = rb.attempt_id
                        WHERE rb.id = p_evidence_id AND rb.command_id = p_command_id
                          AND rb.match_state = 'MATCHES_TARGET'
                          AND at.purpose = 'READBACK' AND at.fence_token = command.fence_token
                          AND at.raw_observation_id IS NOT NULL) THEN
            RAISE EXCEPTION 'a matched readback at the current fence is required for success'
                USING ERRCODE = 'MO093';
        END IF;
    END IF;
    IF p_to_state = 'RETRY_WAIT' AND NOT ops.lc_description_retry_is_proven(p_command_id) THEN
        RAISE EXCEPTION 'retry requires readback-first proof and all current authorities' USING ERRCODE = 'MO092';
    END IF;
    IF p_to_state = 'COMPENSATION_PENDING' THEN
        RAISE EXCEPTION 'RESTORE_UNSUPPORTED: prepare and approve a new exact restoration action' USING ERRCODE='MO094';
    END IF;
    IF p_to_state IN ('FAILED_FINAL', 'COMPENSATION_FAILED', 'TERMINATED_WITHOUT_PROVIDER_CALL')
        AND p_failure_code IS NULL THEN
        RAISE EXCEPTION 'a terminal failure names its reason' USING ERRCODE = 'MO091';
    END IF;
    UPDATE ops.lc_description_command
       SET state = p_to_state,
           lease_owner = CASE WHEN edge.releases_lease THEN NULL ELSE lease_owner END,
           lease_expires_at = CASE WHEN edge.releases_lease THEN NULL ELSE lease_expires_at END,
           retry_preflight_fence = CASE WHEN edge.releases_lease OR p_to_state = 'EXECUTING'
               THEN NULL ELSE retry_preflight_fence END,
           retry_budget_remaining = CASE WHEN p_to_state = 'RETRY_WAIT'
               THEN greatest(retry_budget_remaining - 1, 0) ELSE retry_budget_remaining END,
           next_attempt_at = CASE WHEN p_to_state = 'RETRY_WAIT'
               THEN now_at + make_interval(secs => coalesce(p_retry_delay_seconds, 60)) ELSE NULL END,
           requested_operation = CASE WHEN p_to_state = 'READBACK_PENDING' THEN NULL ELSE requested_operation END,
           failure_code = coalesce(p_failure_code, failure_code),
           terminal_at = CASE WHEN p_to_state IN ('READBACK_MATCHED', 'FAILED_FINAL',
                                                  'TERMINATED_WITHOUT_PROVIDER_CALL', 'COMPENSATED',
                                                  'COMPENSATION_FAILED') THEN now_at ELSE terminal_at END,
           updated_at = now_at
     WHERE id = p_command_id;
    IF p_to_state='READBACK_MATCHED' THEN
        PERFORM ops.record_lc_description_execution_result(p_command_id,p_evidence_id);
    END IF;
    RETURN p_to_state;
END;
$$;

CREATE FUNCTION ops.transition_price_command(p_command_id uuid, p_expected_fence bigint, p_expected_lease_owner text, p_to_state text, p_failure_code text, p_retry_delay_seconds integer, p_evidence_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
    command_row   record;
    rule_row      record;
    latest_match  text;
    latest_observed_at timestamptz;
    updated_state text;
BEGIN
    SELECT command.id, command.state, command.fence_token, command.lease_owner,
           command.lease_expires_at, command.retry_budget_remaining,
           command.target_price, command.currency_code
      INTO command_row
      FROM ops.price_command AS command
     WHERE command.id = p_command_id
       FOR UPDATE OF command;

    IF command_row.id IS NULL THEN
        RAISE EXCEPTION 'price command % does not exist', p_command_id
            USING ERRCODE = 'MO030';
    END IF;

    SELECT allowed.requires_lease, allowed.releases_lease
      INTO rule_row
      FROM ops.price_command_transition AS allowed
     WHERE allowed.from_state = command_row.state
       AND allowed.to_state = p_to_state;

    IF rule_row.requires_lease IS NULL THEN
        RAISE EXCEPTION 'price command % may not move from % to %',
            p_command_id, command_row.state, p_to_state
            USING ERRCODE = 'MO031';
    END IF;

    IF rule_row.requires_lease THEN
        IF command_row.fence_token <> p_expected_fence
            OR command_row.lease_owner IS DISTINCT FROM p_expected_lease_owner
            OR command_row.lease_expires_at IS NULL
            OR command_row.lease_expires_at <= clock_timestamp()
        THEN
            RAISE EXCEPTION
                'price command % is not held by % at fence % with a live lease',
                p_command_id, p_expected_lease_owner, p_expected_fence
                USING ERRCODE = 'MO030';
        END IF;
    END IF;

    -- Platform acceptance is not success. The evidence named here must be a
    -- readback of this command that observed the intended value.
    IF p_to_state = 'SUCCEEDED' THEN
        PERFORM 1
          FROM ops.price_command_readback AS readback
          JOIN raw.price_response_observation response ON response.id = readback.raw_observation_id
          JOIN ops.price_command_attempt attempt ON attempt.id = readback.attempt_id
         WHERE readback.id = p_evidence_id
           AND readback.command_id = p_command_id
           AND response.command_id = p_command_id AND response.attempt_id = attempt.id
           AND attempt.command_id = p_command_id AND attempt.purpose = 'READBACK'
           AND attempt.fence_token = command_row.fence_token
           AND response.observed_price = readback.observed_price
           AND response.observed_currency = readback.currency_code
           AND readback.match_state = 'MATCHES_TARGET'
           AND readback.observed_price = command_row.target_price
           AND readback.currency_code = command_row.currency_code;
        IF NOT FOUND
        THEN
            RAISE EXCEPTION
                'price command % cannot succeed without a matching readback',
                p_command_id
                USING ERRCODE = 'MO033',
                      HINT = 'record the readback observation before claiming success';
        END IF;
    END IF;

    -- A restore may only proceed while the platform still holds what this
    -- command put there. Anything else means somebody or something changed the
    -- price afterwards, and overwriting that is not compensation.
    IF p_to_state = 'COMPENSATION_PENDING' THEN
        SELECT readback.match_state,readback.observed_at INTO latest_match,latest_observed_at
          FROM ops.price_command_readback AS readback
         WHERE readback.command_id = p_command_id
         ORDER BY readback.observed_at DESC, readback.id DESC
         LIMIT 1;

        IF latest_match IS DISTINCT FROM 'MATCHES_TARGET' THEN
            RAISE EXCEPTION
                'price command % cannot be compensated: the latest readback is %',
                p_command_id, coalesce(latest_match, 'absent')
                USING ERRCODE = 'MO034',
                      HINT = 'read the current platform value before restoring';
        END IF;
        IF (SELECT count(*) = 0 FROM ops.price_command_attempt applied
            WHERE applied.command_id=p_command_id AND applied.purpose='APPLY'
              AND applied.outcome_class IN ('ACCEPTED','UNKNOWN_STATE')
              AND applied.completed_at<=latest_observed_at) THEN
            RAISE EXCEPTION 'price command % has no possibly applied write to compensate',p_command_id
                USING ERRCODE='MO034';
        END IF;
    END IF;

    IF p_to_state IN ('FAILED_FINAL', 'COMPENSATION_FAILED')
        AND (p_failure_code IS NULL OR length(btrim(p_failure_code)) = 0)
    THEN
        RAISE EXCEPTION 'a terminal failure of price command % must name a reason',
            p_command_id
            USING ERRCODE = 'MO031';
    END IF;

    UPDATE ops.price_command AS command
       SET state = p_to_state,
           lease_owner = CASE WHEN rule_row.releases_lease THEN NULL
                              ELSE command.lease_owner END,
           lease_expires_at = CASE WHEN rule_row.releases_lease THEN NULL
                                   ELSE command.lease_expires_at END,
           retry_budget_remaining = CASE WHEN p_to_state = 'RETRY_WAIT'
                                             THEN greatest(command.retry_budget_remaining - 1, 0)
                                         ELSE command.retry_budget_remaining END,
           next_attempt_at = CASE WHEN p_to_state = 'RETRY_WAIT'
                                      THEN clock_timestamp()
                                           + make_interval(
                                               secs => coalesce(p_retry_delay_seconds, 60))
                                  ELSE NULL END,
           failure_code = CASE WHEN p_to_state IN ('FAILED_FINAL', 'COMPENSATION_FAILED')
                                   THEN p_failure_code
                               ELSE NULL END,
           terminal_at = CASE WHEN p_to_state IN ('SUCCEEDED', 'FAILED_FINAL',
                                                  'COMPENSATED', 'COMPENSATION_FAILED')
                                  THEN clock_timestamp()
                              ELSE NULL END,
           updated_at = clock_timestamp()
     WHERE command.id = p_command_id
       AND command.state = command_row.state
       AND command.fence_token = command_row.fence_token
    RETURNING command.state INTO updated_state;

    IF updated_state IS NULL THEN
        RAISE EXCEPTION 'price command % changed while transitioning to %',
            p_command_id, p_to_state
            USING ERRCODE = 'MO030';
    END IF;

    RETURN updated_state;
END;
$$;

CREATE FUNCTION ops.try_release_ad_reservation_after_outcome(p_observation uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE reservation uuid;
BEGIN
 SELECT coalesce(c.reservation_id,packet.reservation_id) INTO reservation FROM ops.ad_outcome_observation o
 LEFT JOIN ops.ad_bid_command c ON c.id=o.command_id
 LEFT JOIN ops.ad_manual_execution_packet packet ON packet.id=o.manual_packet_id
 WHERE o.id=p_observation AND o.outcome_stage IN ('OPERATIONAL','OPERATIONAL_REVISED')
 AND NOT EXISTS(SELECT 1 FROM ops.ad_outcome_observation newer WHERE newer.supersedes_observation_id=o.id);
 IF reservation IS NULL THEN RETURN false; END IF;
 RETURN ops.release_ad_action_reservation(reservation,'Canonical completed-sales and critical-unit early safety observation');
END $$;

CREATE FUNCTION ops.validate_ad_candidate_endorsement() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE selection ops.ad_candidate_selection%ROWTYPE;
BEGIN
    SELECT * INTO STRICT selection FROM ops.ad_candidate_selection WHERE id=NEW.selection_id;
    IF NEW.organization_id <> selection.organization_id
       OR NEW.recommendation_id <> selection.recommendation_id
       OR NEW.endorser_user_id = selection.maker_user_id
       OR NEW.endorsed_at < selection.selected_at
       OR NEW.authority_snapshot IS DISTINCT FROM selection.authority_snapshot THEN
        RAISE EXCEPTION 'endorsement requires a distinct person and the exact selected authority'
            USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END $$;

CREATE FUNCTION ops.validate_ad_outcome_review_binding() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'ops', 'pg_temp'
    AS $$
DECLARE context record; binding ops.ad_outcome_review_responsibility%ROWTYPE; observation uuid;
BEGIN
 IF TG_TABLE_NAME='ad_outcome_review_responsibility' THEN observation:=NEW.first_observation_id;
 ELSE observation:=NEW.observation_id; END IF;
 SELECT * INTO context FROM ops.ad_settled_review_context(observation);
 IF NOT FOUND THEN RAISE EXCEPTION 'current canonical Settled contradiction required' USING ERRCODE='MO099'; END IF;
 IF TG_TABLE_NAME='ad_outcome_review_responsibility' THEN
  IF NEW.organization_id<>context.organization_id OR NEW.case_id<>context.case_id
    OR NEW.primary_task_id<>context.primary_task_id OR NEW.outcome_baseline_id<>context.outcome_baseline_id
    OR NEW.action_id<>context.action_id OR NEW.action_kind<>context.action_kind
    OR NEW.first_raised_at<>context.observed_at
    OR NOT EXISTS(SELECT 1 FROM ops.work_task t WHERE t.id=NEW.task_id
      AND t.organization_id=context.organization_id AND t.recommendation_id=context.recommendation_id) THEN
   RAISE EXCEPTION 'review must bind the same action, case, scope and Shared Task' USING ERRCODE='MO099'; END IF;
 ELSE
  SELECT * INTO binding FROM ops.ad_outcome_review_responsibility WHERE task_id=NEW.task_id;
  IF binding.action_id IS DISTINCT FROM context.action_id OR binding.action_kind IS DISTINCT FROM context.action_kind
    OR binding.outcome_baseline_id IS DISTINCT FROM context.outcome_baseline_id THEN
   RAISE EXCEPTION 'review revision must retain its exact action lineage' USING ERRCODE='MO099'; END IF;
 END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION ops.validate_frozen_ad_outcome_observation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE baseline ops.ad_outcome_baseline%ROWTYPE; frozen_stage ops.ad_outcome_stage_baseline%ROWTYPE;
    prior ops.ad_outcome_observation%ROWTYPE; landed timestamptz; stage_code text;
BEGIN
    IF NEW.command_id IS NOT NULL THEN
        SELECT b.* INTO baseline FROM ops.ad_bid_command c JOIN ops.ad_outcome_baseline b ON b.id=c.outcome_baseline_id
            WHERE c.id=NEW.command_id AND c.organization_id=NEW.organization_id;
        SELECT min(observed_at) INTO landed FROM ops.ad_bid_command_readback
            WHERE command_id=NEW.command_id AND match_state='MATCHES_TARGET';
    ELSE
        SELECT b.* INTO baseline FROM ops.ad_manual_execution_packet p JOIN ops.ad_outcome_baseline b ON b.id=p.outcome_baseline_id
            WHERE p.id=NEW.manual_packet_id AND p.organization_id=NEW.organization_id
              AND b.manual_proposal_id=p.proposal_id AND b.prepared_at<=p.execution_started_at;
        SELECT proof.observed_at INTO landed FROM ops.ad_manual_execution_packet p
            JOIN ops.ad_manual_configuration_verification proof ON proof.id=p.current_proof_id
            WHERE p.id=NEW.manual_packet_id AND p.state='MANUAL_CONFIGURATION_VERIFIED'
              AND ops.ad_manual_observation_is_qualified(proof.id)
              AND proof.observed_at<=NEW.evaluated_at AND proof.recorded_at<=NEW.evaluated_at;
    END IF;
    IF baseline.id IS NULL OR landed IS NULL OR baseline.ad_native_object_id<>NEW.ad_native_object_id
      OR baseline.affected_set_digest<>NEW.affected_set_digest OR baseline.outcome_policy_id<>NEW.outcome_policy_id
      OR baseline.outcome_policy_version<>NEW.outcome_policy_version THEN
        RAISE EXCEPTION 'observation must use the exact sealed pre-action baseline and proven action' USING ERRCODE='MO099';
    END IF;
    stage_code=replace(NEW.outcome_stage,'_REVISED','');
    SELECT * INTO frozen_stage FROM ops.ad_outcome_stage_baseline WHERE outcome_baseline_id=baseline.id AND stage=stage_code;
    IF frozen_stage.outcome_baseline_id IS NULL
      OR NEW.window_starts_at<>landed+make_interval(mins=>(baseline.plan_snapshot->>'observationStartsMinutes')::integer)
      OR NEW.window_ends_at<>NEW.window_starts_at+make_interval(hours=>frozen_stage.window_hours)
      OR (NEW.evaluated_at<NEW.window_ends_at AND NEW.verdict<>'NOT_YET_EVALUABLE')
      OR NEW.baseline_metric_state IS DISTINCT FROM frozen_stage.snapshot#>>'{profit,absoluteProfit,valueState}'
      OR NEW.baseline_metric_value IS DISTINCT FROM (frozen_stage.snapshot#>>'{profit,absoluteProfit,value}')::numeric THEN
        RAISE EXCEPTION 'observation must respect the frozen window and baseline value' USING ERRCODE='MO099';
    END IF;
    IF NEW.supersedes_observation_id IS NOT NULL THEN
        SELECT * INTO prior FROM ops.ad_outcome_observation WHERE id=NEW.supersedes_observation_id;
        IF NOT FOUND OR prior.command_id IS DISTINCT FROM NEW.command_id OR prior.manual_packet_id IS DISTINCT FROM NEW.manual_packet_id
          OR replace(prior.outcome_stage,'_REVISED','')<>stage_code OR prior.revision_no+1<>NEW.revision_no
          OR NEW.evaluated_at<prior.evaluated_at
          OR EXISTS(SELECT 1 FROM ops.ad_outcome_observation WHERE supersedes_observation_id=prior.id) THEN
            RAISE EXCEPTION 'revision must append to the exact same action and stage lineage' USING ERRCODE='MO099';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION ops.validate_lc_calibration(p_id uuid, p_proof text, p_digest text, p_reference text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE g iam.ad_invocation_grant%ROWTYPE; p core.lc_calibration_package%ROWTYPE; v ops.lc_calibration_governance%ROWTYPE;
BEGIN
 SELECT * INTO p FROM core.lc_calibration_package WHERE id=p_id FOR UPDATE;
 SELECT * INTO v FROM ops.lc_calibration_governance WHERE package_id=p_id FOR UPDATE;
 IF NOT FOUND OR p.status<>'DRAFT' OR v.accepted_at IS NOT NULL THEN
  RAISE EXCEPTION 'calibration is not an unaccepted governed draft' USING ERRCODE='MO036';
 END IF;
 g:=ops.consume_ad_control_invocation(p_proof,'LISTING_CALIBRATION_VALIDATE',p_id,p_id);
 IF g.organization_id<>p.organization_id OR NOT ops.lc_calibration_actor_scope(g.actor_user_id,p.organization_id,
      p.scope_kind,p.store_ref_id,'LISTING_CALIBRATION_VALIDATE') THEN
  RAISE EXCEPTION 'calibration validation scope denied' USING ERRCODE='MO092';
 END IF;
 IF p_digest IS NULL OR p_reference IS NULL OR length(btrim(p_reference)) NOT BETWEEN 1 AND 512
    OR p_digest<>v.draft_digest OR p_digest<>ops.lc_calibration_digest(p_id)
    OR cardinality(ops.lc_calibration_combination_failures(p_id))<>0 THEN
  RAISE EXCEPTION 'exact complete calibration draft required' USING ERRCODE='MO036';
 END IF;
 UPDATE ops.lc_calibration_governance SET validated_by_user_id=g.actor_user_id,validated_at=clock_timestamp(),
   validation_reference=p_reference,validated_digest=p_digest WHERE package_id=p_id;
 INSERT INTO ops.lc_calibration_event VALUES(gen_random_uuid(),p_id,'VALIDATED',g.actor_user_id,p_digest,p_reference,clock_timestamp());
END $$;

CREATE FUNCTION platform.acquire_platform_job_set_guard(p_platform_codes text[]) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'platform'
    AS $$
DECLARE
    expected bigint;
    locked   bigint;
BEGIN
    SELECT count(DISTINCT code)
      INTO expected
      FROM unnest(p_platform_codes) AS code
     WHERE code IS NOT NULL;

    IF expected = 0 THEN
        RETURN 0;
    END IF;

    WITH ordered AS (
        SELECT DISTINCT code
          FROM unnest(p_platform_codes) AS code
         WHERE code IS NOT NULL
         ORDER BY code
    ), taken AS (
        SELECT guard.platform_code
          FROM platform.control_epoch_membership_guard AS guard
          JOIN ordered ON ordered.code = guard.platform_code
         WHERE guard.guard_kind = 'PLATFORM_JOB_SET'
         ORDER BY guard.platform_code
           FOR UPDATE OF guard
    )
    SELECT count(*) INTO locked FROM taken;

    IF locked <> expected THEN
        RAISE EXCEPTION
            'membership guard incomplete: locked % of % platform guards',
            locked, expected
            USING ERRCODE = 'MO002',
                  HINT = 'every marketplace platform must have exactly one '
                      || 'PLATFORM_JOB_SET guard; add it in the same forward '
                      || 'migration that adds the platform';
    END IF;

    UPDATE platform.control_epoch_membership_guard AS guard
       SET generation = guard.generation + 1,
           updated_at = now()
     WHERE guard.guard_kind = 'PLATFORM_JOB_SET'
       AND guard.platform_code = ANY (p_platform_codes);

    RETURN locked;
END;
$$;

CREATE FUNCTION platform.ad_bid_operation_snapshot(p_capability uuid, p_operation text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
    SELECT jsonb_build_object('operation', to_jsonb(op), 'endpoint', to_jsonb(endpoint),
        'writeResultModel', capability.write_result_model, 'capability', to_jsonb(capability),
        'profile', (SELECT to_jsonb(profile) FROM platform.platform_api_profile profile
                     WHERE profile.platform_code = op.platform_code),
        'headers', (SELECT coalesce(jsonb_agg(to_jsonb(header) ORDER BY header.id), '[]'::jsonb)
            FROM platform.platform_auth_header header
            WHERE header.platform_code = op.platform_code
              AND header.credential_purpose = 'ADS_WRITE'))
      FROM platform.capability_operation op
      JOIN platform.platform_endpoint endpoint ON endpoint.id = op.endpoint_id
      JOIN platform.platform_capability capability ON capability.id = op.capability_id
     WHERE op.capability_id = p_capability AND op.operation = p_operation
       AND op.status = 'ACTIVE' AND op.verification_state = 'VERIFIED'
       AND endpoint.status = 'ACTIVE' AND endpoint.verification_state = 'VERIFIED'
       AND endpoint.deprecated_at IS NULL
       AND capability.status = 'ACTIVE' AND capability.verification_state = 'VERIFIED'
       AND capability.deprecated_at IS NULL
       AND capability.capability_code = 'ad-bid-change' AND capability.read_write_class = 'WRITE'
       AND endpoint.capability_id = op.capability_id
       AND (op.operation <> 'READBACK' OR op.ad_observed_unit_pointer IS NOT NULL)
       AND endpoint.operation_function = CASE op.operation
               WHEN 'STATUS_ENQUIRY' THEN 'AD_BID_STATUS' ELSE 'AD_BID_' || op.operation END
       AND ((op.operation IN ('APPLY', 'RESTORE')
             AND endpoint.http_method IN ('POST', 'PUT', 'PATCH')
             AND endpoint.read_write_class = 'WRITE')
         OR (op.operation IN ('STATUS_ENQUIRY', 'READBACK')
             AND endpoint.http_method IN ('GET', 'POST')
             AND endpoint.read_write_class = 'READ'))
$$;

CREATE FUNCTION platform.ad_semantic_profile_advance_control_epoch_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'platform', 'core', 'pg_temp'
    AS $$
            DECLARE guarded text[]; scopes platform.control_scope[];
            BEGIN
                WITH rel AS (SELECT * FROM o)
                SELECT array_agg(DISTINCT rel.platform_code) INTO guarded FROM rel;
                IF guarded IS NOT NULL THEN
                    PERFORM platform.acquire_platform_job_set_guard(guarded);
                END IF;
                WITH rel AS (SELECT * FROM o)
                SELECT array_agg(DISTINCT mapped.scope) INTO scopes
                  FROM (SELECT ROW('JOB', job.id)::platform.control_scope AS scope
                          FROM rel JOIN platform.ingestion_job AS job
                            ON job.platform_code = rel.platform_code) AS mapped(scope);
                IF scopes IS NOT NULL THEN PERFORM platform.advance_control_epochs(scopes); END IF;
                RETURN NULL;
            END;
            $$;

