    LANGUAGE plpgsql
    AS $$
                DECLARE
                    guarded text[];
                    scopes  platform.control_scope[];
                BEGIN
                    IF EXISTS (SELECT 1 FROM o) THEN   SELECT array_agg(code) INTO guarded FROM core.marketplace_platform;   PERFORM platform.acquire_platform_job_set_guard(guarded); END IF;
