                    SELECT array_agg(DISTINCT mapped.scope) INTO scopes
                      FROM (SELECT ROW('JOB', job.id)::platform.control_scope FROM rel CROSS JOIN platform.ingestion_job AS job) AS mapped(scope);
                    IF scopes IS NOT NULL THEN
                        PERFORM platform.advance_control_epochs(scopes);
                    END IF;
                    RETURN NULL;
                END;
                $$;

