CREATE FUNCTION platform.ingestion_job_membership_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    codes text[];
BEGIN
    SELECT array_agg(DISTINCT inserted.platform_code)
      INTO codes
      FROM inserted_jobs AS inserted;

    IF codes IS NULL THEN
        RETURN NULL;
    END IF;

    PERFORM platform.acquire_platform_job_set_guard(codes);
    RETURN NULL;
END;
$$;

CREATE FUNCTION platform.ingestion_job_platform_write_once() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.platform_code IS DISTINCT FROM OLD.platform_code THEN
        RAISE EXCEPTION
            'ingestion job % may not change platform_code: % -> %',
            OLD.id, OLD.platform_code, NEW.platform_code
            USING ERRCODE = 'MO006',
                  HINT = 'retire the job and create a new one on the target platform';
    END IF;
    RETURN NEW;
END;
$$;

CREATE FUNCTION platform.lc_description_operation_snapshot(p_capability uuid, p_operation text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
    SELECT jsonb_build_object('operation', to_jsonb(op), 'endpoint', to_jsonb(endpoint),
        'writeResultModel', capability.write_result_model, 'capability', to_jsonb(capability),
        'profile', (SELECT to_jsonb(profile) FROM platform.platform_api_profile profile
                     WHERE profile.platform_code = op.platform_code),
        'headers', (SELECT coalesce(jsonb_agg(to_jsonb(header) ORDER BY header.id), '[]'::jsonb)
            FROM platform.platform_auth_header header
            WHERE header.platform_code = op.platform_code
              AND header.credential_purpose = 'CONTENT_WRITE'))
      FROM platform.capability_operation op
      JOIN platform.platform_endpoint endpoint ON endpoint.id = op.endpoint_id
      JOIN platform.platform_capability capability ON capability.id = op.capability_id
     WHERE op.capability_id = p_capability AND op.operation = p_operation
       AND op.status = 'ACTIVE' AND op.verification_state = 'VERIFIED'
       AND endpoint.status = 'ACTIVE' AND endpoint.verification_state = 'VERIFIED'
       AND endpoint.deprecated_at IS NULL
       AND capability.status = 'ACTIVE' AND capability.verification_state = 'VERIFIED'
       AND capability.deprecated_at IS NULL
       AND capability.capability_code = 'listing-description-change' AND capability.read_write_class = 'WRITE'
       AND endpoint.capability_id = op.capability_id
       AND (op.operation <> 'READBACK' OR op.description_observed_text_pointer IS NOT NULL)
       AND (op.operation NOT IN ('APPLY', 'RESTORE') OR op.description_attribute_key IS NOT NULL)
       AND endpoint.operation_function = CASE op.operation
               WHEN 'STATUS_ENQUIRY' THEN 'DESCRIPTION_STATUS' ELSE 'DESCRIPTION_' || op.operation END
       AND ((op.operation IN ('APPLY', 'RESTORE')
             AND endpoint.http_method IN ('POST', 'PUT', 'PATCH')
             AND endpoint.read_write_class = 'WRITE')
         OR (op.operation IN ('STATUS_ENQUIRY', 'READBACK')
             AND endpoint.http_method IN ('GET', 'POST')
             AND endpoint.read_write_class = 'READ'))
$$;

CREATE FUNCTION platform.lc_description_request_guard_valid(p_guard jsonb, p_attribute text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE
    node record; total integer:=0; listing_count integer:=0; attribute_count integer:=0;
    description_count integer:=0; marking_count integer:=0; binding text; scalar_type text;
    fields text[]:=ARRAY['schema','evidenceRef','mutationSemantics','markingPolicy','body'];
BEGIN
    IF p_guard IS NULL OR jsonb_typeof(p_guard)<>'object' OR NOT (p_guard ?& fields)
        OR p_guard-fields<>'{}'::jsonb OR p_guard->>'schema' IS DISTINCT FROM 'DESCRIPTION_REQUEST_V1'
        OR jsonb_typeof(p_guard->'evidenceRef') IS DISTINCT FROM 'string'
        OR nullif(btrim(p_guard->>'evidenceRef'),'') IS NULL
        OR coalesce(p_guard->>'mutationSemantics','') NOT IN ('PARTIAL_ATTRIBUTE','PARTIAL_FIELD')
        OR coalesce(p_guard->>'markingPolicy','') NOT IN ('REQUIRED','NOT_APPLICABLE')
        OR jsonb_typeof(p_guard->'body') NOT IN ('object','array') OR nullif(p_attribute,'') IS NULL THEN
        RETURN false;
    END IF;
    FOR node IN
        WITH RECURSIVE nodes(value,field_name,depth) AS (
            SELECT p_guard->'body',''::text,0
            UNION ALL
            SELECT child.value,child.field_name,parent.depth+1 FROM nodes parent
            CROSS JOIN LATERAL (
                SELECT e.value,e.key AS field_name FROM jsonb_each(
                    CASE WHEN jsonb_typeof(parent.value)='object' THEN parent.value ELSE '{}'::jsonb END) e
                UNION ALL
                SELECT a.value,(a.ordinality-1)::text FROM jsonb_array_elements(
                    CASE WHEN jsonb_typeof(parent.value)='array' THEN parent.value ELSE '[]'::jsonb END)
                    WITH ORDINALITY a(value,ordinality)
            ) child
            WHERE parent.depth<=32 AND NOT (jsonb_typeof(parent.value)='object' AND parent.value ? '$bind')
        ) SELECT * FROM nodes
    LOOP
        total:=total+1;
        IF total>4096 OR node.depth>32 THEN RETURN false; END IF;
        IF jsonb_typeof(node.value)='object' AND node.value ? '$bind' THEN
            IF NOT (node.value ?& ARRAY['$bind','$type']) OR node.value-ARRAY['$bind','$type']<>'{}'::jsonb
                OR jsonb_typeof(node.value->'$bind') IS DISTINCT FROM 'string'
                OR jsonb_typeof(node.value->'$type') IS DISTINCT FROM 'string' THEN RETURN false; END IF;
            binding:=node.value->>'$bind'; scalar_type:=node.value->>'$type';
            CASE binding
                WHEN 'LISTING_KEY' THEN
                    IF scalar_type NOT IN ('string','integer') THEN RETURN false; END IF;
                    listing_count:=listing_count+1;
                WHEN 'ATTRIBUTE_KEY' THEN
                    IF scalar_type NOT IN ('string','integer') THEN RETURN false; END IF;
                    attribute_count:=attribute_count+1;
                WHEN 'DESCRIPTION_TEXT' THEN
                    IF scalar_type<>'string' OR (p_guard->>'mutationSemantics'='PARTIAL_FIELD'
                        AND node.field_name IS DISTINCT FROM p_attribute) THEN RETURN false; END IF;
                    description_count:=description_count+1;
                WHEN 'KIZ_MARKED' THEN
                    IF scalar_type<>'boolean' THEN RETURN false; END IF;
                    marking_count:=marking_count+1;
                ELSE RETURN false;
            END CASE;
        END IF;
    END LOOP;
    RETURN listing_count=1 AND description_count=1
        AND attribute_count=CASE WHEN p_guard->>'mutationSemantics'='PARTIAL_ATTRIBUTE' THEN 1 ELSE 0 END
        AND marking_count=CASE WHEN p_guard->>'markingPolicy'='REQUIRED' THEN 1 ELSE 0 END;
END;
$_$;

CREATE FUNCTION platform.lc_description_response_descriptor_valid(p_descriptor jsonb, p_operation text, p_model text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE field text; pointer text;
BEGIN
    IF p_descriptor IS NULL OR jsonb_typeof(p_descriptor)<>'object'
        OR p_descriptor->>'schema' IS DISTINCT FROM 'DESCRIPTION_RESPONSE_IDENTITY_V1'
        OR jsonb_typeof(p_descriptor->'evidenceRef') IS DISTINCT FROM 'string'
        OR nullif(btrim(p_descriptor->>'evidenceRef'),'') IS NULL
        OR p_descriptor-ARRAY['schema','evidenceRef','mode','selection','payloadPointer',
            'listingKeyPointer','listingKeyType','taskEchoPointer','statusValueType',
            'taskBindingMethod','taskRequestPointer','taskRequestValueType']<>'{}'::jsonb THEN
        RETURN false;
    END IF;
    IF p_descriptor->>'mode'='TASK_ACCEPTANCE_ONLY' THEN
        RETURN p_operation IN ('APPLY','RESTORE') AND p_model='ASYNCHRONOUS_TASK'
            AND p_descriptor-ARRAY['schema','evidenceRef','mode']='{}'::jsonb;
    END IF;
    IF p_descriptor->>'mode' IS DISTINCT FROM 'EXACT_OBJECT'
        OR coalesce(p_descriptor->>'selection','') NOT IN ('OBJECT','ITEMS')
        OR coalesce(p_descriptor->>'listingKeyType','') NOT IN ('string','number') THEN RETURN false; END IF;
    FOREACH field IN ARRAY ARRAY['payloadPointer','listingKeyPointer'] LOOP
        pointer := p_descriptor->>field;
        IF jsonb_typeof(p_descriptor->field) IS DISTINCT FROM 'string'
            OR (pointer<>'' AND (left(pointer,1)<>'/' OR pointer ~ '~([^01]|$)'))
            OR (field='listingKeyPointer' AND pointer='') THEN RETURN false; END IF;
    END LOOP;
    IF p_operation='STATUS_ENQUIRY' THEN
        IF coalesce(p_descriptor->>'taskBindingMethod','ECHO') NOT IN ('ECHO','REQUEST_UNIQUE') THEN RETURN false; END IF;
        IF p_descriptor->>'taskBindingMethod'='REQUEST_UNIQUE' THEN
            IF p_descriptor ? 'taskEchoPointer' OR coalesce(p_descriptor->>'taskRequestValueType','') NOT IN ('string','number') THEN RETURN false; END IF;
            pointer:=p_descriptor->>'taskRequestPointer';
        ELSE
            IF p_descriptor ?| ARRAY['taskRequestPointer','taskRequestValueType'] THEN RETURN false; END IF;
            pointer:=p_descriptor->>'taskEchoPointer';
        END IF;
        IF pointer IS NULL
            OR left(pointer,1)<>'/' OR pointer ~ '~([^01]|$)'
            OR coalesce(p_descriptor->>'statusValueType','') NOT IN ('string','number') THEN RETURN false; END IF;
    ELSIF p_descriptor ?| ARRAY['taskBindingMethod','taskRequestPointer','taskRequestValueType'] THEN RETURN false;
    END IF;
    RETURN true;
END;
$_$;

CREATE FUNCTION platform.lc_description_task_query_shape_valid(p_operation jsonb, p_endpoint jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE d jsonb:=p_operation->'description_response_binding'; probe text; rendered bytea; document jsonb; value jsonb;
BEGIN
    IF jsonb_typeof(p_operation) IS DISTINCT FROM 'object' OR jsonb_typeof(p_endpoint) IS DISTINCT FROM 'object' THEN RETURN false; END IF;
    IF d->>'taskBindingMethod' IS DISTINCT FROM 'REQUEST_UNIQUE' THEN RETURN true; END IF;
    IF p_operation->>'operation' IS DISTINCT FROM 'STATUS_ENQUIRY'
        OR p_endpoint->>'http_method' IS DISTINCT FROM 'POST' THEN RETURN false; END IF;
    FOREACH probe IN ARRAY ARRAY['1','2'] LOOP
        rendered:=ops.lc_description_render_task_query(p_operation->>'request_template',
            jsonb_build_object('nativeTaskKey',probe,'nativeListingKey','fixture-listing','idempotencyKey','fixture-query'));
        IF rendered IS NULL THEN RETURN false; END IF;
        BEGIN
            IF NOT (convert_from(rendered,'UTF8') IS JSON WITH UNIQUE KEYS) THEN RETURN false; END IF;
            document:=convert_from(rendered,'UTF8')::jsonb;
        EXCEPTION WHEN invalid_text_representation OR character_not_in_repertoire THEN RETURN false;
        END;
        value:=ops.lc_response_value(document,d->>'taskRequestPointer');
        IF jsonb_typeof(value) IS DISTINCT FROM d->>'taskRequestValueType'
            OR value #>> '{}' IS DISTINCT FROM probe THEN RETURN false; END IF;
    END LOOP;
    RETURN true;
END;
$$;

CREATE FUNCTION platform.lc_description_template_is_well_formed(p_template text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE rendered text:=p_template; token text[];
BEGIN
    IF p_template IS NULL OR length(p_template)>4096 THEN RETURN false; END IF;
    FOR token IN SELECT regexp_matches(p_template,'\{([a-zA-Z][a-zA-Z0-9]{0,31})\}','g') LOOP
        IF token[1] NOT IN ('nativeListingKey','nativeVariantKey','idempotencyKey','nativeTaskKey',
            'descriptionText','descriptionAttributeKey','kizMarkedDeclared') THEN RETURN false; END IF;
        rendered:=replace(rendered,'{'||token[1]||'}',CASE
            WHEN token[1] IN ('nativeListingKey','nativeVariantKey','nativeTaskKey','descriptionAttributeKey') THEN '1'
            WHEN token[1]='kizMarkedDeclared' THEN 'false' ELSE 'fixture' END);
    END LOOP;
    RETURN rendered IS JSON OBJECT WITH UNIQUE KEYS OR rendered IS JSON ARRAY WITH UNIQUE KEYS;
END;
$$;

CREATE FUNCTION platform.legal_entity_advance_control_epoch_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
                DECLARE
                    guarded text[];
                    scopes  platform.control_scope[];
                BEGIN
                    
                    WITH rel AS (SELECT * FROM o)
                    SELECT array_agg(DISTINCT mapped.scope) INTO scopes
                      FROM (SELECT ROW('ORGANIZATION', rel.organization_id)::platform.control_scope FROM rel) AS mapped(scope);
                    IF scopes IS NOT NULL THEN
                        PERFORM platform.advance_control_epochs(scopes);
                    END IF;
                    RETURN NULL;
                END;
                $$;

