                    WITH rel AS (SELECT * FROM n UNION ALL SELECT * FROM o) SELECT array_agg(DISTINCT rel.platform_code) INTO guarded FROM rel; IF guarded IS NOT NULL THEN   PERFORM platform.acquire_platform_job_set_guard(guarded); END IF;
                    WITH rel AS (SELECT * FROM n UNION ALL SELECT * FROM o)
                    SELECT array_agg(DISTINCT mapped.scope) INTO scopes
                      FROM (SELECT ROW('JOB', job.id)::platform.control_scope FROM rel JOIN platform.ingestion_job AS job ON job.platform_code = rel.platform_code) AS mapped(scope);
                    IF scopes IS NOT NULL THEN
                        PERFORM platform.advance_control_epochs(scopes);
                    END IF;
                    RETURN NULL;
                END;
                $$;

