                      FROM (SELECT ROW('SERVICE_ACCOUNT', rel.service_account_id)::platform.control_scope FROM rel) AS mapped(scope);
                    IF scopes IS NOT NULL THEN
                        PERFORM platform.advance_control_epochs(scopes);
                    END IF;
                    RETURN NULL;
                END;
                $$;

