CREATE FUNCTION raw.bind_acquisition_receipt() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE endpoint uuid; header record;
BEGIN
    IF NEW.outcome_class='SUCCESS_BYTES' AND NOT NEW.response_complete THEN
        RAISE EXCEPTION 'partial bytes cannot prove acquisition success' USING ERRCODE='MO009';
    END IF;
    FOR header IN SELECT key,value FROM jsonb_each_text(NEW.response_headers) LOOP
        IF header.key NOT IN ('content-type','retry-after','x-ratelimit-remaining','x-ratelimit-reset','x-ratelimit-limit')
           OR length(header.value)>256 OR header.value ~ '[[:cntrl:]]' THEN
            RAISE EXCEPTION 'unsafe acquisition response metadata' USING ERRCODE='MO009';
        END IF;
    END LOOP;
    IF NEW.authority_decision_id IS NOT NULL THEN
        SELECT decision.endpoint_id INTO endpoint FROM ops.authorization_decision_evidence decision
          JOIN raw.raw_logical_unit unit ON unit.id=NEW.logical_unit_id
          JOIN platform.ingestion_job job ON job.id=decision.job_id
         WHERE decision.id=NEW.authority_decision_id AND decision.run_id=NEW.run_id AND decision.call_seq=NEW.call_seq
           AND unit.job_id=decision.job_id AND unit.marketplace_account_id=job.marketplace_account_id;
        IF endpoint IS NULL THEN
            RAISE EXCEPTION 'acquisition receipt does not match its committed authority' USING ERRCODE='MO009';
        END IF;
        IF NEW.native_status ~ '^HTTP [0-9]{3}$' THEN
            PERFORM platform.defer_endpoint_quota(endpoint,substring(NEW.native_status FROM 6)::integer,NEW.response_headers);
        END IF;
    END IF;
    RETURN NEW;
END $_$;

CREATE FUNCTION staging.guard_import_batch() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE total_rows integer; accepted_rows integer; actual_facts integer;
BEGIN
    PERFORM 1 FROM staging.import_schema_profile p
        WHERE p.id=NEW.schema_profile_id AND p.organization_id=NEW.organization_id
          AND p.dataset_kind=NEW.dataset_kind;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'import ownership mismatch' USING ERRCODE='MO060';
    END IF;
    PERFORM 1 FROM iam.user_account u WHERE u.id=NEW.submitted_by_user_id AND u.organization_id=NEW.organization_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'import ownership mismatch' USING ERRCODE='MO060';
    END IF;
    IF NEW.approved_by_user_id IS NOT NULL THEN
        PERFORM 1 FROM iam.user_account u WHERE u.id=NEW.approved_by_user_id
            AND u.organization_id=NEW.organization_id AND u.status='ACTIVE';
        IF NOT FOUND THEN RAISE EXCEPTION 'import ownership mismatch' USING ERRCODE='MO060'; END IF;
    END IF;
    IF TG_OP='INSERT' THEN
        IF NEW.state <> 'RECEIVED' THEN
            RAISE EXCEPTION 'an import must begin at receipt' USING ERRCODE='MO061';
        END IF;
        RETURN NEW;
    END IF;
    IF (NEW.organization_id,NEW.dataset_kind,NEW.schema_profile_id,NEW.content_id,
        NEW.declared_file_name,NEW.declared_media_type,NEW.submitted_by_user_id,NEW.submitted_at)
       IS DISTINCT FROM
       (OLD.organization_id,OLD.dataset_kind,OLD.schema_profile_id,OLD.content_id,
        OLD.declared_file_name,OLD.declared_media_type,OLD.submitted_by_user_id,OLD.submitted_at)
       OR NOT ((OLD.state='RECEIVED' AND NEW.state IN ('VALIDATED','REJECTED'))
          OR (OLD.state='VALIDATED' AND NEW.state IN ('APPROVED','REJECTED'))
          OR (OLD.state='APPROVED' AND NEW.state='APPLIED')
          OR (OLD.state='APPLIED' AND NEW.state='SUPERSEDED')) THEN
        RAISE EXCEPTION 'import content or transition is immutable' USING ERRCODE='MO061';
    END IF;
    SELECT count(*), count(*) FILTER (WHERE validation_state='ACCEPTED')
      INTO total_rows,accepted_rows FROM staging.import_row WHERE batch_id=NEW.id;
    IF (NEW.total_row_count,NEW.accepted_row_count,NEW.rejected_row_count)
       IS DISTINCT FROM (total_rows,accepted_rows,total_rows-accepted_rows)
       OR (NEW.state IN ('VALIDATED','APPROVED','APPLIED') AND accepted_rows=0) THEN
        RAISE EXCEPTION 'import row reconciliation failed' USING ERRCODE='MO062';
    END IF;
    IF NEW.state='APPLIED' THEN
        SELECT CASE NEW.dataset_kind
          WHEN 'PURCHASE_COST' THEN (SELECT count(*) FROM core.cost_version f
            JOIN core.fact_provenance p ON p.id=f.provenance_id WHERE p.import_batch_id=NEW.id)
          WHEN 'INTERNAL_STOCK' THEN (SELECT count(*) FROM core.internal_stock_snapshot f
            JOIN core.fact_provenance p ON p.id=f.provenance_id WHERE p.import_batch_id=NEW.id)
          WHEN 'FINANCE_INPUT' THEN (SELECT count(*) FROM core.finance_input_version f
            JOIN core.fact_provenance p ON p.id=f.provenance_id WHERE p.import_batch_id=NEW.id)
          END INTO actual_facts;
        IF actual_facts IS DISTINCT FROM accepted_rows
           OR NEW.applied_row_count IS DISTINCT FROM accepted_rows THEN
            RAISE EXCEPTION 'import fact reconciliation failed' USING ERRCODE='MO062';
        END IF;
    END IF;
    RETURN NEW;
END $$;

CREATE FUNCTION staging.guard_import_row() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE batch_state text;
BEGIN
    SELECT state INTO batch_state FROM staging.import_batch WHERE id=NEW.batch_id FOR UPDATE;
    IF batch_state IS DISTINCT FROM 'RECEIVED' THEN
        RAISE EXCEPTION 'validated import rows are immutable' USING ERRCODE='MO063';
    END IF;
    RETURN NEW;
END $$;

CREATE TABLE core.ad_affected_set (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    ad_native_object_id uuid NOT NULL,
    affected_set_digest text NOT NULL,
    product_variant_ids uuid[] NOT NULL,
    platform_listing_variant_ids uuid[] NOT NULL,
    resolution_state text NOT NULL,
    unresolved_reason_codes text[] DEFAULT '{}'::text[] NOT NULL,
    resolved_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT ad_affected_set_complete_ck CHECK (((resolution_state <> 'COMPLETE'::text) OR ((cardinality(product_variant_ids) >= 1) AND (cardinality(unresolved_reason_codes) = 0)))),
    CONSTRAINT ad_affected_set_digest_ck CHECK ((affected_set_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT ad_affected_set_incomplete_ck CHECK (((resolution_state = 'COMPLETE'::text) OR (cardinality(unresolved_reason_codes) >= 1))),
    CONSTRAINT ad_affected_set_listings_ck CHECK ((((cardinality(platform_listing_variant_ids) >= 0) AND (cardinality(platform_listing_variant_ids) <= 4096)) AND (array_position(platform_listing_variant_ids, NULL::uuid) IS NULL))),
    CONSTRAINT ad_affected_set_reasons_ck CHECK ((((cardinality(unresolved_reason_codes) >= 0) AND (cardinality(unresolved_reason_codes) <= 32)) AND (array_position(unresolved_reason_codes, NULL::text) IS NULL))),
    CONSTRAINT ad_affected_set_resolution_ck CHECK ((resolution_state = ANY (ARRAY['COMPLETE'::text, 'INCOMPLETE'::text, 'CONFLICTED'::text, 'UNRESOLVED'::text]))),
    CONSTRAINT ad_affected_set_variants_ck CHECK ((((cardinality(product_variant_ids) >= 0) AND (cardinality(product_variant_ids) <= 4096)) AND (array_position(product_variant_ids, NULL::uuid) IS NULL)))
);

CREATE TABLE core.ad_allowable_cpa_definition (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    definition_version integer NOT NULL,
    scope_kind text NOT NULL,
    platform_code text,
    store_ref_id uuid,
    product_variant_ref_id uuid,
    sale_stage text NOT NULL,
    currency_code text NOT NULL,
    contribution_basis text NOT NULL,
    target_contribution_retention_ratio numeric(6,5) CONSTRAINT ad_allowable_cpa_definition_target_contribution_retent_not_null NOT NULL,
    return_loss_treatment text NOT NULL,
    owner_user_id uuid NOT NULL,
    reason text NOT NULL,
    evidence_reference text NOT NULL,
    effective_from timestamp with time zone NOT NULL,
    effective_to timestamp with time zone,
    status text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT ad_allowable_cpa_definition_basis_ck CHECK ((contribution_basis = ANY (ARRAY['OPERATIONAL_CONTRIBUTION'::text, 'SETTLED_CONTRIBUTION'::text]))),
    CONSTRAINT ad_allowable_cpa_definition_currency_ck CHECK ((currency_code ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT ad_allowable_cpa_definition_evidence_ck CHECK (((length(btrim(evidence_reference)) >= 1) AND (length(btrim(evidence_reference)) <= 512))),
    CONSTRAINT ad_allowable_cpa_definition_interval_ck CHECK (((effective_to IS NULL) OR (effective_to > effective_from))),
    CONSTRAINT ad_allowable_cpa_definition_reason_ck CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 1024))),
    CONSTRAINT ad_allowable_cpa_definition_retained_ck CHECK (((sale_stage <> 'CANONICAL_AD_LINKED_RETAINED_SALE'::text) OR (return_loss_treatment = 'INCLUDED_IN_STAGE_CONTRIBUTION'::text))),
    CONSTRAINT ad_allowable_cpa_definition_retention_ck CHECK (((target_contribution_retention_ratio > (0)::numeric) AND (target_contribution_retention_ratio <= (1)::numeric))),
    CONSTRAINT ad_allowable_cpa_definition_return_ck CHECK ((return_loss_treatment = ANY (ARRAY['INCLUDED_IN_STAGE_CONTRIBUTION'::text, 'APPLIED_ONCE_ON_TOP'::text]))),
    CONSTRAINT ad_allowable_cpa_definition_scope_ck CHECK ((scope_kind = ANY (ARRAY['ORGANIZATION'::text, 'PLATFORM'::text, 'STORE'::text, 'PRODUCT_VARIANT'::text]))),
    CONSTRAINT ad_allowable_cpa_definition_scope_shape_ck CHECK ((num_nonnulls(platform_code, store_ref_id, product_variant_ref_id) =
CASE scope_kind
    WHEN 'ORGANIZATION'::text THEN 0
    WHEN 'PLATFORM'::text THEN 1
    WHEN 'STORE'::text THEN 2
    ELSE 1
END)),
    CONSTRAINT ad_allowable_cpa_definition_stage_ck CHECK ((sale_stage = ANY (ARRAY['CANONICAL_AD_LINKED_ORDER'::text, 'CANONICAL_AD_LINKED_COMPLETED_SALE'::text, 'CANONICAL_AD_LINKED_RETAINED_SALE'::text]))),
    CONSTRAINT ad_allowable_cpa_definition_status_ck CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'RETIRED'::text, 'CANCELLED'::text]))),
    CONSTRAINT ad_allowable_cpa_definition_version_ck CHECK ((definition_version >= 1))
);

CREATE TABLE core.ad_approval_lease_policy (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    policy_version integer NOT NULL,
    scope_kind text NOT NULL,
    platform_code text,
    store_ref_id uuid,
    direction text NOT NULL,
    lease_seconds integer NOT NULL,
    material_lease_seconds integer NOT NULL,
    renewable boolean DEFAULT false NOT NULL,
    owner_user_id uuid NOT NULL,
    reason text NOT NULL,
    evidence_reference text NOT NULL,
    effective_from timestamp with time zone NOT NULL,
    effective_to timestamp with time zone,
    status text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT ad_approval_lease_policy_direction_ck CHECK ((direction = ANY (ARRAY['PROTECTION_DECREASE'::text, 'OPTIMIZATION_INCREASE'::text, 'EXACT_PRIOR_BID_COMPENSATION'::text]))),
    CONSTRAINT ad_approval_lease_policy_evidence_ck CHECK (((length(btrim(evidence_reference)) >= 1) AND (length(btrim(evidence_reference)) <= 512))),
    CONSTRAINT ad_approval_lease_policy_interval_ck CHECK (((effective_to IS NULL) OR (effective_to > effective_from))),
    CONSTRAINT ad_approval_lease_policy_material_ck CHECK ((material_lease_seconds <= lease_seconds)),
    CONSTRAINT ad_approval_lease_policy_reason_ck CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 1024))),
    CONSTRAINT ad_approval_lease_policy_renewable_ck CHECK ((NOT renewable)),
    CONSTRAINT ad_approval_lease_policy_scope_ck CHECK ((scope_kind = ANY (ARRAY['ORGANIZATION'::text, 'PLATFORM'::text, 'STORE'::text]))),
