    CONSTRAINT economics_projection_family_code_ck CHECK ((family_code = ANY (ARRAY['COMMISSION'::text, 'FULFILLMENT_DELIVERY'::text, 'STORAGE'::text, 'PROMOTION'::text, 'OTHER_VARIABLE'::text, 'RETURN_LOSS'::text, 'ADVERTISING'::text, 'VARIABLE_TAX'::text]))),
    CONSTRAINT economics_projection_family_evidence_ck CHECK (((length(btrim(evidence_reference)) >= 1) AND (length(btrim(evidence_reference)) <= 512)))
);

CREATE TABLE core.economics_projection_profile (
    id uuid NOT NULL,
    profile_version integer NOT NULL,
    organization_id uuid NOT NULL,
    platform_code text NOT NULL,
    marketplace_account_id uuid NOT NULL,
    store_id uuid NOT NULL,
    fulfillment_mode_code text NOT NULL,
    currency_code text NOT NULL,
    effective_from timestamp with time zone NOT NULL,
    effective_to timestamp with time zone,
    verification_state text NOT NULL,
    verified_at timestamp with time zone NOT NULL,
    verification_expires_at timestamp with time zone,
    evidence_reference text NOT NULL,
    minimum_supported_price numeric(18,4) NOT NULL,
    maximum_supported_price numeric(18,4) NOT NULL,
    status text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT economics_projection_profile_currency_ck CHECK ((currency_code ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT economics_projection_profile_evidence_ck CHECK (((length(btrim(evidence_reference)) >= 1) AND (length(btrim(evidence_reference)) <= 512))),
    CONSTRAINT economics_projection_profile_interval_ck CHECK (((effective_to IS NULL) OR (effective_from < effective_to))),
    CONSTRAINT economics_projection_profile_price_domain_ck CHECK (((minimum_supported_price > (0)::numeric) AND (minimum_supported_price < maximum_supported_price))),
    CONSTRAINT economics_projection_profile_status_ck CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'RETIRED'::text]))),
    CONSTRAINT economics_projection_profile_verification_ck CHECK ((verification_state = ANY (ARRAY['UNVERIFIED'::text, 'ENGINEERING_VERIFIED'::text, 'REAL_ACCOUNT_VERIFIED'::text]))),
    CONSTRAINT economics_projection_profile_verification_interval_ck CHECK (((verification_expires_at IS NULL) OR (verified_at < verification_expires_at))),
    CONSTRAINT economics_projection_profile_version_ck CHECK ((profile_version > 0))
);

CREATE TABLE core.exception_materiality_policy (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    currency_code text NOT NULL,
    material_profit_at_risk numeric(18,4) NOT NULL,
    material_duration_days integer NOT NULL,
    repeat_occurrence_count integer NOT NULL,
    repeat_lookback_days integer NOT NULL,
    max_exception_days integer NOT NULL,
    owner_user_id uuid NOT NULL,
    reason text NOT NULL,
    evidence_reference text NOT NULL,
    effective_from timestamp with time zone NOT NULL,
    effective_to timestamp with time zone,
    status text NOT NULL,
    policy_version integer NOT NULL,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT exception_materiality_policy_amount_ck CHECK ((material_profit_at_risk >= (0)::numeric)),
    CONSTRAINT exception_materiality_policy_currency_ck CHECK ((currency_code ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT exception_materiality_policy_duration_ck CHECK (((material_duration_days >= 1) AND (material_duration_days <= 3650))),
    CONSTRAINT exception_materiality_policy_evidence_ck CHECK (((length(btrim(evidence_reference)) >= 1) AND (length(btrim(evidence_reference)) <= 512))),
    CONSTRAINT exception_materiality_policy_interval_ck CHECK (((effective_to IS NULL) OR (effective_from < effective_to))),
    CONSTRAINT exception_materiality_policy_lookback_ck CHECK (((repeat_lookback_days >= 1) AND (repeat_lookback_days <= 3650))),
    CONSTRAINT exception_materiality_policy_max_days_ck CHECK (((max_exception_days >= 1) AND (max_exception_days <= 3650))),
    CONSTRAINT exception_materiality_policy_reason_ck CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 1024))),
    CONSTRAINT exception_materiality_policy_repeat_ck CHECK (((repeat_occurrence_count >= 2) AND (repeat_occurrence_count <= 100))),
    CONSTRAINT exception_materiality_policy_status_ck CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'RETIRED'::text]))),
    CONSTRAINT exception_materiality_policy_version_ck CHECK ((policy_version >= 1))
);

CREATE TABLE core.fact_provenance (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    source_kind text NOT NULL,
    raw_observation_id uuid,
    source_time timestamp with time zone,
    ingestion_time timestamp with time zone NOT NULL,
    recorded_by_user_id uuid,
    evidence_note text,
    import_batch_id uuid,
    CONSTRAINT fact_provenance_manual_actor_ck CHECK (((source_kind <> 'MANUAL_ENTRY'::text) OR (recorded_by_user_id IS NOT NULL))),
    CONSTRAINT fact_provenance_source_kind_ck CHECK ((source_kind = ANY (ARRAY['MARKETPLACE_RAW'::text, 'INTERNAL_IMPORT'::text, 'MANUAL_ENTRY'::text]))),
    CONSTRAINT fact_provenance_source_reference_ck CHECK (
CASE source_kind
    WHEN 'MARKETPLACE_RAW'::text THEN ((raw_observation_id IS NOT NULL) AND (import_batch_id IS NULL))
    WHEN 'INTERNAL_IMPORT'::text THEN ((import_batch_id IS NOT NULL) AND (raw_observation_id IS NULL))
    ELSE ((raw_observation_id IS NULL) AND (import_batch_id IS NULL))
END)
);

CREATE TABLE core.finance_input_version (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    input_code text NOT NULL,
    scope_kind text NOT NULL,
    store_ref_id uuid,
    product_variant_ref_id uuid,
    value_kind text NOT NULL,
    rate_value numeric(9,6),
    amount_value numeric(18,4),
    currency_code text,
    provenance_id uuid NOT NULL,
    effective_from timestamp with time zone NOT NULL,
    effective_to timestamp with time zone,
    status text NOT NULL,
    reason text,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    promotion_kind text,
    native_promotion_key text,
    promotion_listing_ref_id uuid,
    promotion_terms_digest text,
    CONSTRAINT finance_input_promotion_amount_ck CHECK ((((input_code = ANY (ARRAY['PROMOTION_FIXED_FEE'::text, 'PROMOTION_BUYER_PAYMENT_PER_UNIT'::text, 'PROMOTION_SELLER_REVENUE_PER_UNIT'::text, 'PROMOTION_PLATFORM_COMPENSATION_PER_UNIT'::text])) = (scope_kind = 'PROMOTION'::text)) AND ((scope_kind <> 'PROMOTION'::text) OR ((value_kind = 'AMOUNT'::text) AND (effective_to IS NOT NULL))))),
    CONSTRAINT finance_input_promotion_revenue_scope_ck CHECK ((((input_code = ANY (ARRAY['PROMOTION_BUYER_PAYMENT_PER_UNIT'::text, 'PROMOTION_SELLER_REVENUE_PER_UNIT'::text, 'PROMOTION_PLATFORM_COMPENSATION_PER_UNIT'::text])) AND (promotion_listing_ref_id IS NOT NULL) AND (promotion_terms_digest IS NOT NULL) AND (promotion_terms_digest ~ '^[0-9a-f]{64}$'::text)) OR ((input_code <> ALL (ARRAY['PROMOTION_BUYER_PAYMENT_PER_UNIT'::text, 'PROMOTION_SELLER_REVENUE_PER_UNIT'::text, 'PROMOTION_PLATFORM_COMPENSATION_PER_UNIT'::text])) AND (promotion_listing_ref_id IS NULL) AND (promotion_terms_digest IS NULL)))),
    CONSTRAINT finance_input_version_code_ck CHECK ((input_code = ANY (ARRAY['VARIABLE_TAX_RATE'::text, 'PAYMENT_PROCESSING_RATE'::text, 'RETURN_HANDLING_UNIT_COST'::text, 'INBOUND_LOGISTICS_UNIT_COST'::text, 'REQUIRED_PROFIT_PER_UNIT'::text, 'SAFETY_BUFFER_PER_UNIT'::text, 'PROMOTION_FIXED_FEE'::text, 'PROMOTION_BUYER_PAYMENT_PER_UNIT'::text, 'PROMOTION_SELLER_REVENUE_PER_UNIT'::text, 'PROMOTION_PLATFORM_COMPENSATION_PER_UNIT'::text]))),
    CONSTRAINT finance_input_version_commercial_amount_ck CHECK (((input_code <> ALL (ARRAY['REQUIRED_PROFIT_PER_UNIT'::text, 'SAFETY_BUFFER_PER_UNIT'::text])) OR (value_kind = 'AMOUNT'::text))),
    CONSTRAINT finance_input_version_currency_ck CHECK (((currency_code IS NULL) OR (currency_code ~ '^[A-Z]{3}$'::text))),
    CONSTRAINT finance_input_version_interval_ck CHECK (((effective_to IS NULL) OR (effective_from < effective_to))),
    CONSTRAINT finance_input_version_reason_ck CHECK (((status = 'ACTIVE'::text) OR (reason IS NOT NULL))),
    CONSTRAINT finance_input_version_scope_ck CHECK ((scope_kind = ANY (ARRAY['ORGANIZATION'::text, 'STORE'::text, 'PRODUCT_VARIANT'::text, 'PROMOTION'::text]))),
    CONSTRAINT finance_input_version_scope_matrix_ck CHECK ((((scope_kind = 'ORGANIZATION'::text) AND (num_nonnulls(store_ref_id, product_variant_ref_id, promotion_kind, native_promotion_key) = 0)) OR ((scope_kind = 'STORE'::text) AND (store_ref_id IS NOT NULL) AND (num_nonnulls(product_variant_ref_id, promotion_kind, native_promotion_key) = 0)) OR ((scope_kind = 'PRODUCT_VARIANT'::text) AND (product_variant_ref_id IS NOT NULL) AND (num_nonnulls(store_ref_id, promotion_kind, native_promotion_key) = 0)) OR ((scope_kind = 'PROMOTION'::text) AND (store_ref_id IS NOT NULL) AND (product_variant_ref_id IS NULL) AND (promotion_kind IS NOT NULL) AND (promotion_kind = ANY (ARRAY['OFFICIAL_PROMOTION_PARTICIPATION'::text, 'SELLER_DIRECT_DISCOUNT'::text])) AND (native_promotion_key IS NOT NULL) AND ((length(btrim(native_promotion_key)) >= 1) AND (length(btrim(native_promotion_key)) <= 128))))),
    CONSTRAINT finance_input_version_status_ck CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'ENDED'::text, 'CANCELLED'::text]))),
    CONSTRAINT finance_input_version_value_kind_ck CHECK ((value_kind = ANY (ARRAY['RATE'::text, 'AMOUNT'::text]))),
    CONSTRAINT finance_input_version_value_matrix_ck CHECK ((((value_kind = 'RATE'::text) AND (rate_value IS NOT NULL) AND (rate_value >= (0)::numeric) AND (rate_value <= (1)::numeric) AND (amount_value IS NULL) AND (currency_code IS NULL)) OR ((value_kind = 'AMOUNT'::text) AND (amount_value IS NOT NULL) AND (amount_value >= (0)::numeric) AND (currency_code IS NOT NULL) AND (rate_value IS NULL))))
);

CREATE TABLE core.fulfillment_mode (
    code text NOT NULL,
    display_name text NOT NULL,
    CONSTRAINT fulfillment_mode_code_ck CHECK ((code ~ '^[A-Z][A-Z0-9_]{1,62}$'::text))
);

CREATE TABLE core.inbound_supply_attestation (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    product_variant_id uuid NOT NULL,
    external_reference text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT inbound_supply_attestation_reference_ck CHECK (((length(btrim(external_reference)) >= 1) AND (length(btrim(external_reference)) <= 128)))
);

CREATE TABLE core.inbound_supply_attestation_version (
    id uuid NOT NULL,
    attestation_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    version_no integer NOT NULL,
    quantity integer NOT NULL,
    expected_arrival_from timestamp with time zone CONSTRAINT inbound_supply_attestation_versi_expected_arrival_from_not_null NOT NULL,
    expected_arrival_to timestamp with time zone NOT NULL,
    business_status text NOT NULL,
    change_kind text NOT NULL,
    evidence_reference text NOT NULL,
    source_time timestamp with time zone,
    last_verified_at timestamp with time zone NOT NULL,
    attested_by_user_id uuid NOT NULL,
    reason text,
    supersedes_version_id uuid,
    recorded_at timestamp with time zone NOT NULL,
    CONSTRAINT inbound_supply_attestation_version_cancel_reason_ck CHECK (((change_kind <> 'CANCEL'::text) OR (reason IS NOT NULL))),
    CONSTRAINT inbound_supply_attestation_version_chain_ck CHECK (((version_no = 1) = (supersedes_version_id IS NULL))),
    CONSTRAINT inbound_supply_attestation_version_change_ck CHECK ((change_kind = ANY (ARRAY['CREATE'::text, 'AMEND'::text, 'CANCEL'::text, 'STATUS_CHANGE'::text, 'REVERIFY'::text]))),
    CONSTRAINT inbound_supply_attestation_version_create_ck CHECK (((change_kind = 'CREATE'::text) = (version_no = 1))),
    CONSTRAINT inbound_supply_attestation_version_evidence_ck CHECK (((length(btrim(evidence_reference)) >= 1) AND (length(btrim(evidence_reference)) <= 512))),
    CONSTRAINT inbound_supply_attestation_version_no_ck CHECK ((version_no >= 1)),
    CONSTRAINT inbound_supply_attestation_version_quantity_ck CHECK (((quantity > 0) AND (quantity <= 100000000))),
    CONSTRAINT inbound_supply_attestation_version_reason_ck CHECK (((reason IS NULL) OR ((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 1024)))),
    CONSTRAINT inbound_supply_attestation_version_status_ck CHECK ((business_status = ANY (ARRAY['DRAFT'::text, 'REQUESTED'::text, 'SUPPLIER_CONFIRMED'::text, 'IN_TRANSIT'::text, 'RECEIVED'::text, 'CANCELLED'::text, 'OVERDUE'::text, 'CONFLICTED'::text, 'UNKNOWN'::text]))),
    CONSTRAINT inbound_supply_attestation_version_window_ck CHECK ((expected_arrival_to >= expected_arrival_from))
);

CREATE TABLE core.internal_stock_snapshot (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    provenance_id uuid NOT NULL,
    warehouse_id uuid NOT NULL,
    product_variant_id uuid NOT NULL,
    source_fact_key text NOT NULL,
    observed_at timestamp with time zone NOT NULL,
    quantity_on_hand integer NOT NULL,
    quantity_reserved integer,
    quantity_quality_locked integer,
    quantity_damaged integer,
    quantity_written_off integer,
    sellable text,
    return_reentry_id uuid,
    CONSTRAINT internal_stock_snapshot_damaged_ck CHECK (((quantity_damaged IS NULL) OR (quantity_damaged >= 0))),
    CONSTRAINT internal_stock_snapshot_on_hand_ck CHECK ((quantity_on_hand >= 0)),
    CONSTRAINT internal_stock_snapshot_quality_locked_ck CHECK (((quantity_quality_locked IS NULL) OR (quantity_quality_locked >= 0))),
    CONSTRAINT internal_stock_snapshot_reserved_ck CHECK (((quantity_reserved IS NULL) OR (quantity_reserved >= 0))),
    CONSTRAINT internal_stock_snapshot_sellable_ck CHECK (((sellable IS NULL) OR (sellable = ANY (ARRAY['YES'::text, 'NO'::text, 'UNKNOWN'::text])))),
    CONSTRAINT internal_stock_snapshot_unavailable_total_ck CHECK (((((COALESCE(quantity_reserved, 0) + COALESCE(quantity_quality_locked, 0)) + COALESCE(quantity_damaged, 0)) + COALESCE(quantity_written_off, 0)) <= quantity_on_hand)),
    CONSTRAINT internal_stock_snapshot_written_off_ck CHECK (((quantity_written_off IS NULL) OR (quantity_written_off >= 0)))
);

CREATE TABLE core.lc_affected_set (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    platform_listing_id uuid NOT NULL,
    affected_set_digest text NOT NULL,
    platform_listing_variant_ids uuid[] NOT NULL,
    product_variant_ids uuid[] NOT NULL,
    resolution_state text NOT NULL,
    unresolved_reason_codes text[] DEFAULT '{}'::text[] NOT NULL,
    resolved_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone NOT NULL,
    identity_lineage jsonb,
    native_scope_observation_id uuid,
    CONSTRAINT lc_affected_set_complete_ck CHECK (((resolution_state <> 'COMPLETE'::text) OR ((cardinality(platform_listing_variant_ids) >= 1) AND (cardinality(unresolved_reason_codes) = 0)))),
    CONSTRAINT lc_affected_set_digest_ck CHECK ((affected_set_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT lc_affected_set_identity_lineage_ck CHECK (((identity_lineage IS NULL) OR ((jsonb_typeof(identity_lineage) = 'object'::text) AND (affected_set_digest = encode(sha256(convert_to((identity_lineage)::text, 'UTF8'::name)), 'hex'::text))))),
    CONSTRAINT lc_affected_set_incomplete_ck CHECK (((resolution_state = 'COMPLETE'::text) OR (cardinality(unresolved_reason_codes) >= 1))),
    CONSTRAINT lc_affected_set_listing_variants_ck CHECK ((((cardinality(platform_listing_variant_ids) >= 0) AND (cardinality(platform_listing_variant_ids) <= 4096)) AND (array_position(platform_listing_variant_ids, NULL::uuid) IS NULL))),
    CONSTRAINT lc_affected_set_product_variants_ck CHECK ((((cardinality(product_variant_ids) >= 0) AND (cardinality(product_variant_ids) <= 4096)) AND (array_position(product_variant_ids, NULL::uuid) IS NULL))),
    CONSTRAINT lc_affected_set_reasons_ck CHECK ((((cardinality(unresolved_reason_codes) >= 0) AND (cardinality(unresolved_reason_codes) <= 32)) AND (array_position(unresolved_reason_codes, NULL::text) IS NULL))),
    CONSTRAINT lc_affected_set_resolution_ck CHECK ((resolution_state = ANY (ARRAY['COMPLETE'::text, 'INCOMPLETE'::text, 'CONFLICTED'::text])))
);

CREATE TABLE core.lc_calibration_category (
    code text NOT NULL,
    display_name text NOT NULL,
    value_shape text NOT NULL,
    ordinal integer NOT NULL,
    CONSTRAINT lc_calibration_category_code_ck CHECK ((code ~ '^[A-Z][A-Z0-9_]{1,62}$'::text)),
    CONSTRAINT lc_calibration_category_shape_ck CHECK ((value_shape = ANY (ARRAY['NUMERIC'::text, 'TEXT'::text, 'JSON'::text])))
);

CREATE TABLE core.lc_calibration_package (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    package_code text NOT NULL,
    package_version integer NOT NULL,
    scope_kind text NOT NULL,
    platform_code text,
    store_ref_id uuid,
    scope_key text GENERATED ALWAYS AS (((((scope_kind || ':'::text) || COALESCE(platform_code, ''::text)) || ':'::text) || COALESCE((store_ref_id)::text, ''::text))) STORED,
    status text NOT NULL,
    published_by_user_id uuid NOT NULL,
    published_at timestamp with time zone NOT NULL,
    evidence_reference text NOT NULL,
    effective_from timestamp with time zone NOT NULL,
    effective_to timestamp with time zone,
    activated_at timestamp with time zone,
    retired_at timestamp with time zone,
    purpose_code text DEFAULT 'LISTING_CONVERSION'::text NOT NULL,
    CONSTRAINT lc_calibration_package_activation_ck CHECK (((status = 'ACTIVE'::text) = ((activated_at IS NOT NULL) AND (retired_at IS NULL)))),
    CONSTRAINT lc_calibration_package_code_ck CHECK ((package_code ~ '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$'::text)),
    CONSTRAINT lc_calibration_package_purpose_code_check CHECK ((purpose_code = ANY (ARRAY['LISTING_CONVERSION'::text, 'DESCRIPTION_CORRECTION'::text, 'BOUNDED_EXPLORATION'::text, 'PROMOTION'::text]))),
    CONSTRAINT lc_calibration_package_range_ck CHECK (((effective_to IS NULL) OR (effective_to > effective_from))),
    CONSTRAINT lc_calibration_package_reference_ck CHECK (((length(btrim(evidence_reference)) >= 1) AND (length(btrim(evidence_reference)) <= 512))),
    CONSTRAINT lc_calibration_package_retirement_ck CHECK (((status = 'RETIRED'::text) = (retired_at IS NOT NULL))),
    CONSTRAINT lc_calibration_package_scope_ck CHECK ((scope_kind = ANY (ARRAY['ORGANIZATION'::text, 'PLATFORM'::text, 'STORE'::text]))),
    CONSTRAINT lc_calibration_package_scope_shape_ck CHECK ((((scope_kind = 'ORGANIZATION'::text) AND (platform_code IS NULL) AND (store_ref_id IS NULL)) OR ((scope_kind = 'PLATFORM'::text) AND (platform_code IS NOT NULL) AND (store_ref_id IS NULL)) OR ((scope_kind = 'STORE'::text) AND (platform_code IS NULL) AND (store_ref_id IS NOT NULL)))),
    CONSTRAINT lc_calibration_package_status_ck CHECK ((status = ANY (ARRAY['DRAFT'::text, 'ACTIVE'::text, 'RETIRED'::text]))),
    CONSTRAINT lc_calibration_package_version_ck CHECK ((package_version >= 1))
);

CREATE TABLE core.lc_calibration_value (
    id uuid NOT NULL,
    package_id uuid NOT NULL,
    category_code text NOT NULL,
    value_numeric numeric(18,6),
    value_text text,
    value_json jsonb,
    unit_code text NOT NULL,
    scope_note text NOT NULL,
    window_days integer,
    evidence_reference text NOT NULL,
    CONSTRAINT lc_calibration_value_equivalence_ck CHECK (((category_code <> 'REPRESENTATION_EQUIVALENCE_RULE'::text) OR (value_text = ANY (ARRAY['EXACT'::text, 'WHITESPACE_NORMALIZED'::text])))),
    CONSTRAINT lc_calibration_value_note_ck CHECK (((length(btrim(scope_note)) >= 1) AND (length(btrim(scope_note)) <= 512))),
    CONSTRAINT lc_calibration_value_present_ck CHECK (((num_nonnulls(value_numeric, value_text, value_json) = 1) OR ((category_code = 'NON_WORSENING_PROFIT_BOUND'::text) AND (value_numeric IS NOT NULL) AND (value_text IS NULL) AND (value_json IS NOT NULL)))),
    CONSTRAINT lc_calibration_value_reference_ck CHECK (((length(btrim(evidence_reference)) >= 1) AND (length(btrim(evidence_reference)) <= 512))),
    CONSTRAINT lc_calibration_value_unit_ck CHECK ((unit_code ~ '^[A-Z][A-Z0-9_]{0,31}$'::text)),
    CONSTRAINT lc_calibration_value_window_ck CHECK (((window_days IS NULL) OR ((window_days >= 1) AND (window_days <= 3660))))
);

CREATE TABLE core.lc_description_observation (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    provenance_id uuid NOT NULL,
    platform_listing_id uuid NOT NULL,
    source_fact_key text NOT NULL,
    observed_at timestamp with time zone NOT NULL,
    acquired_at timestamp with time zone NOT NULL,
    description_text text NOT NULL,
    text_digest text NOT NULL,
    language_code text NOT NULL,
    kiz_marked_declared boolean,
    native_version_token text,
    supersedes_fact_id uuid,
    CONSTRAINT lc_description_observation_digest_ck CHECK ((text_digest = encode(sha256(convert_to(description_text, 'UTF8'::name)), 'hex'::text))),
    CONSTRAINT lc_description_observation_language_ck CHECK ((language_code ~ '^[a-z]{2}(-[A-Z]{2})?$'::text)),
    CONSTRAINT lc_description_observation_length_ck CHECK ((length(description_text) <= 65536)),
    CONSTRAINT lc_description_observation_times_ck CHECK ((acquired_at >= observed_at)),
    CONSTRAINT lc_description_observation_token_ck CHECK (((native_version_token IS NULL) OR ((length(btrim(native_version_token)) >= 1) AND (length(btrim(native_version_token)) <= 256))))
);

CREATE TABLE core.lc_display_observation (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    provenance_id uuid NOT NULL,
    platform_listing_id uuid NOT NULL,
    source_fact_key text NOT NULL,
    observed_at timestamp with time zone NOT NULL,
    acquired_at timestamp with time zone NOT NULL,
    evidence_grade text NOT NULL,
    observer_user_id uuid,
    display_state text NOT NULL,
    displayed_text_digest text,
    displayed_text text,
    evidence_reference text NOT NULL,
    CONSTRAINT lc_display_observation_digest_ck CHECK ((((displayed_text IS NULL) AND (displayed_text_digest IS NULL)) OR (displayed_text_digest = encode(sha256(convert_to(displayed_text, 'UTF8'::name)), 'hex'::text)))),
    CONSTRAINT lc_display_observation_displayed_ck CHECK (((display_state <> 'DISPLAYED'::text) OR (displayed_text_digest IS NOT NULL))),
    CONSTRAINT lc_display_observation_grade_ck CHECK ((evidence_grade = ANY (ARRAY['OFFICIAL_EVIDENCE'::text, 'INDEPENDENT_HUMAN'::text]))),
    CONSTRAINT lc_display_observation_observer_ck CHECK (((evidence_grade = 'INDEPENDENT_HUMAN'::text) = (observer_user_id IS NOT NULL))),
    CONSTRAINT lc_display_observation_reference_ck CHECK (((length(btrim(evidence_reference)) >= 1) AND (length(btrim(evidence_reference)) <= 512))),
    CONSTRAINT lc_display_observation_state_ck CHECK ((display_state = ANY (ARRAY['DISPLAYED'::text, 'NOT_DISPLAYED'::text, 'UNKNOWN'::text]))),
    CONSTRAINT lc_display_observation_times_ck CHECK ((acquired_at >= observed_at))
);

CREATE TABLE core.lc_feedback_item (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    platform_listing_id uuid NOT NULL,
    source_identity text NOT NULL,
    raw_observation_id uuid NOT NULL,
    original_pointer text NOT NULL,
    original_digest text NOT NULL,
    observed_at timestamp with time zone NOT NULL,
    acquired_at timestamp with time zone NOT NULL,
    linked_by uuid NOT NULL,
    linked_at timestamp with time zone NOT NULL,
    CONSTRAINT lc_feedback_item_check CHECK (((observed_at <= acquired_at) AND (acquired_at <= linked_at))),
    CONSTRAINT lc_feedback_item_original_digest_check CHECK ((original_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT lc_feedback_item_original_pointer_check CHECK (((length(original_pointer) >= 1) AND (length(original_pointer) <= 512))),
    CONSTRAINT lc_feedback_item_source_identity_check CHECK (((length(source_identity) >= 1) AND (length(source_identity) <= 512)))
);

CREATE TABLE core.lc_measurement_coverage (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    platform_listing_id uuid NOT NULL,
    provenance_id uuid NOT NULL,
    evidence_path text NOT NULL,
    window_start timestamp with time zone NOT NULL,
    window_end timestamp with time zone NOT NULL,
    retention_window_days integer NOT NULL,
    source_complete_through timestamp with time zone NOT NULL,
    source_reference text NOT NULL,
    expected_visit_rows bigint,
    expected_link_rows bigint,
    summary_observation_id uuid,
    equivalence_profile_id uuid,
    input_digest text NOT NULL,
    recorded_at timestamp with time zone NOT NULL,
    CONSTRAINT lc_measurement_coverage_check CHECK (((window_start < window_end) AND (source_complete_through >= window_end) AND (source_complete_through <= recorded_at))),
    CONSTRAINT lc_measurement_coverage_check1 CHECK ((((evidence_path = 'DETAIL'::text) AND (expected_visit_rows IS NOT NULL) AND (expected_link_rows IS NOT NULL) AND (summary_observation_id IS NULL)) OR ((evidence_path = 'OFFICIAL_SUMMARY'::text) AND (summary_observation_id IS NOT NULL) AND (expected_visit_rows IS NULL) AND (expected_link_rows IS NULL)))),
    CONSTRAINT lc_measurement_coverage_evidence_path_check CHECK ((evidence_path = ANY (ARRAY['DETAIL'::text, 'OFFICIAL_SUMMARY'::text]))),
    CONSTRAINT lc_measurement_coverage_expected_link_rows_check CHECK ((expected_link_rows >= 0)),
    CONSTRAINT lc_measurement_coverage_expected_visit_rows_check CHECK ((expected_visit_rows >= 0)),
    CONSTRAINT lc_measurement_coverage_input_digest_check CHECK ((input_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT lc_measurement_coverage_retention_window_days_check CHECK ((retention_window_days = ANY (ARRAY[7, 14, 30]))),
    CONSTRAINT lc_measurement_coverage_source_reference_check CHECK (((length(btrim(source_reference)) >= 1) AND (length(btrim(source_reference)) <= 512)))
);

CREATE TABLE core.lc_official_summary_observation (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    provenance_id uuid NOT NULL,
    store_id uuid NOT NULL,
    platform_listing_id uuid NOT NULL,
    source_fact_key text NOT NULL,
    summary_kind text NOT NULL,
    period_start timestamp with time zone NOT NULL,
    period_end timestamp with time zone NOT NULL,
    reported_visits bigint,
    reported_retained_purchases bigint,
    reported_conversion_label text,
    observed_at timestamp with time zone NOT NULL,
    acquired_at timestamp with time zone NOT NULL,
    supersedes_fact_id uuid,
    retention_window_days integer,
    source_method_input_version integer,
    source_strata jsonb,
    critical_group_source_strata jsonb,
    CONSTRAINT lc_official_summary_group_strata_shape_ck CHECK (((critical_group_source_strata IS NULL) OR (jsonb_typeof(critical_group_source_strata) = 'object'::text))),
    CONSTRAINT lc_official_summary_method_presence_ck CHECK ((((source_strata IS NULL) AND (critical_group_source_strata IS NULL)) OR (source_method_input_version IS NOT NULL))),
    CONSTRAINT lc_official_summary_method_version_ck CHECK (((source_method_input_version IS NULL) OR (source_method_input_version >= 1))),
    CONSTRAINT lc_official_summary_observation_counts_ck CHECK ((((reported_visits IS NULL) OR (reported_visits >= 0)) AND ((reported_retained_purchases IS NULL) OR (reported_retained_purchases >= 0)))),
    CONSTRAINT lc_official_summary_observation_kind_ck CHECK ((summary_kind ~ '^[A-Z][A-Z0-9_]{1,62}$'::text)),
    CONSTRAINT lc_official_summary_observation_label_ck CHECK (((reported_conversion_label IS NULL) OR ((length(btrim(reported_conversion_label)) >= 1) AND (length(btrim(reported_conversion_label)) <= 128)))),
    CONSTRAINT lc_official_summary_observation_period_ck CHECK ((period_start < period_end)),
    CONSTRAINT lc_official_summary_observation_retention_window_days_check CHECK ((retention_window_days = ANY (ARRAY[7, 14, 30]))),
    CONSTRAINT lc_official_summary_observation_times_ck CHECK ((acquired_at >= observed_at)),
    CONSTRAINT lc_official_summary_source_strata_shape_ck CHECK (((source_strata IS NULL) OR (jsonb_typeof(source_strata) = 'object'::text)))
);

COMMENT ON COLUMN core.lc_official_summary_observation.source_strata IS 'Exact official aggregate counts by ADVERTISING/ORGANIC; never synthesized into visit identities.';

COMMENT ON COLUMN core.lc_official_summary_observation.critical_group_source_strata IS 'Exact official aggregate counts by critical group and source; missing groups remain missing.';

CREATE TABLE core.lc_promotion_observation (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    platform_listing_id uuid NOT NULL,
    provenance_id uuid NOT NULL,
    observed_at timestamp with time zone NOT NULL,
    acquired_at timestamp with time zone NOT NULL,
    participation_state text NOT NULL,
    engagement_kind text NOT NULL,
    native_promotion_key text NOT NULL,
    declaration jsonb,
    declaration_digest text GENERATED ALWAYS AS (ops.lc_promotion_terms_digest(declaration)) STORED,
    evidence_reference text NOT NULL,
    context_coverage text DEFAULT 'SINGLE_ACTIVITY_ONLY'::text NOT NULL,
    coverage_from timestamp with time zone,
    coverage_until timestamp with time zone,
    verification_expires_at timestamp with time zone,
    context_snapshot jsonb,
    context_digest text,
    CONSTRAINT lc_promotion_observation_check CHECK (((declaration IS NULL) OR (((declaration ->> 'engagementKind'::text) = engagement_kind) AND ((declaration ->> 'nativePromotionKey'::text) = native_promotion_key)))),
    CONSTRAINT lc_promotion_observation_check1 CHECK ((acquired_at >= observed_at)),
    CONSTRAINT lc_promotion_observation_context_coverage_ck CHECK ((context_coverage = ANY (ARRAY['SINGLE_ACTIVITY_ONLY'::text, 'COMPLETE_ENUMERATION'::text]))),
    CONSTRAINT lc_promotion_observation_context_shape_ck CHECK ((((context_coverage = 'SINGLE_ACTIVITY_ONLY'::text) AND (num_nonnulls(coverage_from, coverage_until, verification_expires_at, context_snapshot, context_digest) = 0)) OR ((context_coverage = 'COMPLETE_ENUMERATION'::text) AND (coverage_from IS NOT NULL) AND (coverage_until IS NOT NULL) AND (verification_expires_at IS NOT NULL) AND (context_snapshot IS NOT NULL) AND (context_digest IS NOT NULL) AND (coverage_from < coverage_until) AND (verification_expires_at > acquired_at) AND (jsonb_typeof(context_snapshot) = 'array'::text) AND (jsonb_array_length(context_snapshot) <= 64) AND (context_digest ~ '^[0-9a-f]{64}$'::text)))),
    CONSTRAINT lc_promotion_observation_engagement_kind_check CHECK ((engagement_kind = ANY (ARRAY['OFFICIAL_PROMOTION_PARTICIPATION'::text, 'SELLER_DIRECT_DISCOUNT'::text]))),
    CONSTRAINT lc_promotion_observation_evidence_reference_check CHECK (((length(btrim(evidence_reference)) >= 1) AND (length(btrim(evidence_reference)) <= 512))),
    CONSTRAINT lc_promotion_observation_native_promotion_key_check CHECK (((length(btrim(native_promotion_key)) >= 1) AND (length(btrim(native_promotion_key)) <= 128))),
    CONSTRAINT lc_promotion_observation_participation_state_check CHECK ((participation_state = ANY (ARRAY['PARTICIPATING'::text, 'NOT_PARTICIPATING'::text, 'UNKNOWN'::text])))
);

CREATE TABLE core.lc_summary_equivalence_profile (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    platform_code text NOT NULL,
    summary_kind text NOT NULL,
    profile_version integer NOT NULL,
    proof_state text NOT NULL,
    covers_numerator boolean NOT NULL,
    covers_denominator boolean NOT NULL,
    covers_time_attribution boolean NOT NULL,
    covers_maturity boolean NOT NULL,
    covers_revision boolean NOT NULL,
    evidence_reference text,
    published_by_user_id uuid NOT NULL,
    published_at timestamp with time zone NOT NULL,
    effective_from timestamp with time zone NOT NULL,
    effective_to timestamp with time zone,
    status text NOT NULL,
    source_method_input_version integer,
    covers_source_strata boolean DEFAULT false NOT NULL,
    covers_critical_groups boolean DEFAULT false NOT NULL,
    CONSTRAINT lc_summary_equivalence_profile_kind_ck CHECK ((summary_kind ~ '^[A-Z][A-Z0-9_]{1,62}$'::text)),
    CONSTRAINT lc_summary_equivalence_profile_method_coverage_ck CHECK ((((NOT covers_source_strata) AND (NOT covers_critical_groups)) OR ((source_method_input_version IS NOT NULL) AND covers_source_strata))),
    CONSTRAINT lc_summary_equivalence_profile_method_version_ck CHECK (((source_method_input_version IS NULL) OR (source_method_input_version >= 1))),
    CONSTRAINT lc_summary_equivalence_profile_proof_ck CHECK ((proof_state = ANY (ARRAY['PROVEN'::text, 'UNPROVEN'::text, 'REFUTED'::text]))),
    CONSTRAINT lc_summary_equivalence_profile_proven_ck CHECK (((proof_state <> 'PROVEN'::text) OR (covers_numerator AND covers_denominator AND covers_time_attribution AND covers_maturity AND covers_revision AND (evidence_reference IS NOT NULL)))),
    CONSTRAINT lc_summary_equivalence_profile_range_ck CHECK (((effective_to IS NULL) OR (effective_to > effective_from))),
    CONSTRAINT lc_summary_equivalence_profile_status_ck CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'RETIRED'::text]))),
    CONSTRAINT lc_summary_equivalence_profile_version_ck CHECK ((profile_version >= 1))
);

COMMENT ON COLUMN core.lc_summary_equivalence_profile.source_method_input_version IS 'Explicit schema version for aggregate fixed-source numerator/denominator inputs; NULL grants no formal-method qualification.';

COMMENT ON COLUMN core.lc_summary_equivalence_profile.covers_source_strata IS 'Proof covers retained-visit numerator and visit denominator semantics within each fixed source stratum.';

COMMENT ON COLUMN core.lc_summary_equivalence_profile.covers_critical_groups IS 'Proof covers the same count semantics within reported critical groups; it does not assert that any required group was supplied.';

