    CONSTRAINT lc_visit_fact_key_group_ck CHECK (((key_group_code IS NULL) OR (key_group_code ~ '^[A-Z][A-Z0-9_]{1,62}$'::text))),
    CONSTRAINT lc_visit_fact_sellable_ck CHECK ((sellable_at_visit = ANY (ARRAY['YES'::text, 'NO'::text, 'UNKNOWN'::text]))),
