CREATE TABLE core.lead_time_safety_policy (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    scope_kind text NOT NULL,
    scope_precedence integer NOT NULL,
    product_variant_id uuid,
    supplier_code text,
    route_code text,
    category_code text,
    lead_time_days_min integer NOT NULL,
    lead_time_days_max integer NOT NULL,
    safety_days integer NOT NULL,
    owner_user_id uuid NOT NULL,
    reason text NOT NULL,
    evidence_reference text NOT NULL,
    last_reviewed_at timestamp with time zone NOT NULL,
    effective_from timestamp with time zone NOT NULL,
    effective_to timestamp with time zone,
    status text NOT NULL,
    policy_version integer NOT NULL,
    fallback_of_id uuid,
    created_at timestamp with time zone NOT NULL,
    scope_key text GENERATED ALWAYS AS (((((((((scope_kind || '|'::text) || COALESCE((product_variant_id)::text, '-'::text)) || '|'::text) || COALESCE(supplier_code, '-'::text)) || '|'::text) || COALESCE(route_code, '-'::text)) || '|'::text) || COALESCE(category_code, '-'::text))) STORED,
    CONSTRAINT lead_time_safety_policy_category_ck CHECK (((category_code IS NULL) OR (category_code ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$'::text))),
    CONSTRAINT lead_time_safety_policy_evidence_ck CHECK (((length(btrim(evidence_reference)) >= 1) AND (length(btrim(evidence_reference)) <= 512))),
    CONSTRAINT lead_time_safety_policy_interval_ck CHECK (((effective_to IS NULL) OR (effective_from < effective_to))),
    CONSTRAINT lead_time_safety_policy_lead_ck CHECK (((lead_time_days_min >= 0) AND (lead_time_days_max >= lead_time_days_min) AND (lead_time_days_max <= 3650))),
    CONSTRAINT lead_time_safety_policy_precedence_ck CHECK ((scope_precedence =
CASE scope_kind
    WHEN 'VARIANT_SUPPLIER_ROUTE'::text THEN 1
    WHEN 'SUPPLIER'::text THEN 2
    WHEN 'PRODUCT_CATEGORY'::text THEN 2
    ELSE 3
END)),
    CONSTRAINT lead_time_safety_policy_reason_ck CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 1024))),
    CONSTRAINT lead_time_safety_policy_route_ck CHECK (((route_code IS NULL) OR (route_code ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$'::text))),
    CONSTRAINT lead_time_safety_policy_safety_ck CHECK (((safety_days >= 0) AND (safety_days <= 3650))),
    CONSTRAINT lead_time_safety_policy_scope_ck CHECK ((scope_kind = ANY (ARRAY['VARIANT_SUPPLIER_ROUTE'::text, 'SUPPLIER'::text, 'PRODUCT_CATEGORY'::text, 'ORGANIZATION'::text]))),
    CONSTRAINT lead_time_safety_policy_scope_shape_ck CHECK ((((scope_kind = 'VARIANT_SUPPLIER_ROUTE'::text) AND (product_variant_id IS NOT NULL) AND (supplier_code IS NOT NULL) AND (route_code IS NOT NULL) AND (category_code IS NULL)) OR ((scope_kind = 'SUPPLIER'::text) AND (product_variant_id IS NULL) AND (supplier_code IS NOT NULL) AND (route_code IS NULL) AND (category_code IS NULL)) OR ((scope_kind = 'PRODUCT_CATEGORY'::text) AND (product_variant_id IS NULL) AND (supplier_code IS NULL) AND (route_code IS NULL) AND (category_code IS NOT NULL)) OR ((scope_kind = 'ORGANIZATION'::text) AND (product_variant_id IS NULL) AND (supplier_code IS NULL) AND (route_code IS NULL) AND (category_code IS NULL)))),
    CONSTRAINT lead_time_safety_policy_status_ck CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'RETIRED'::text, 'CANCELLED'::text]))),
    CONSTRAINT lead_time_safety_policy_supplier_ck CHECK (((supplier_code IS NULL) OR (supplier_code ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$'::text))),
    CONSTRAINT lead_time_safety_policy_version_ck CHECK ((policy_version >= 1))
);

