    CONSTRAINT platform_listing_native_product_key_ck CHECK (((native_product_key IS NULL) OR ((length(btrim(native_product_key)) >= 1) AND (length(btrim(native_product_key)) <= 128)))),
    CONSTRAINT platform_listing_seen_ck CHECK ((last_seen_at >= first_seen_at)),
    CONSTRAINT platform_listing_status_ck CHECK ((status = ANY (ARRAY['OBSERVED'::text, 'ARCHIVED'::text])))
);

