CREATE TABLE core.return_quality_policy (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    policy_version integer NOT NULL,
    maximum_return_ratio numeric(6,5) NOT NULL,
    minimum_retention_ratio numeric(6,5) NOT NULL,
    maximum_defect_return_ratio numeric(6,5) NOT NULL,
    owner_user_id uuid NOT NULL,
    reason text NOT NULL,
    evidence_reference text NOT NULL,
    effective_from timestamp with time zone NOT NULL,
    effective_to timestamp with time zone,
    status text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    evidence_freshness_max_minutes integer,
    CONSTRAINT return_quality_policy_evidence_ck CHECK (((length(btrim(evidence_reference)) >= 1) AND (length(btrim(evidence_reference)) <= 512))),
    CONSTRAINT return_quality_policy_freshness_ck CHECK (((evidence_freshness_max_minutes IS NULL) OR ((evidence_freshness_max_minutes >= 1) AND (evidence_freshness_max_minutes <= 10080)))),
    CONSTRAINT return_quality_policy_interval_ck CHECK (((effective_to IS NULL) OR (effective_to > effective_from))),
    CONSTRAINT return_quality_policy_ratio_ck CHECK ((((maximum_return_ratio >= (0)::numeric) AND (maximum_return_ratio <= (1)::numeric)) AND ((minimum_retention_ratio >= (0)::numeric) AND (minimum_retention_ratio <= (1)::numeric)) AND ((maximum_defect_return_ratio >= (0)::numeric) AND (maximum_defect_return_ratio <= (1)::numeric)))),
    CONSTRAINT return_quality_policy_reason_ck CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 1024))),
    CONSTRAINT return_quality_policy_status_ck CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'RETIRED'::text, 'CANCELLED'::text]))),
    CONSTRAINT return_quality_policy_version_ck CHECK ((policy_version >= 1))
);

