    CONSTRAINT source_feed_watermark_ingestion_ck CHECK ((ingested_at <= recorded_at)),
    CONSTRAINT source_feed_watermark_reconciliation_ck CHECK (((reconciled_at IS NULL) OR (reconciled_at <= recorded_at))),
