    CONSTRAINT identity_decision_event_denial_ck CHECK (((decision <> ALL (ARRAY['DENIED'::text, 'STEP_UP_REQUIRED'::text])) OR (denial_code IS NOT NULL))),
    CONSTRAINT identity_decision_event_session_digest_ck CHECK (((session_digest IS NULL) OR (session_digest ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT identity_decision_event_subject_digest_ck CHECK ((subject_digest ~ '^[0-9a-f]{64}$'::text))
);

