    mfa_claim_name text,
    mfa_claim_value text,
    max_auth_age_seconds integer NOT NULL,
    verification_state text NOT NULL,
    last_verified_at timestamp with time zone,
    evidence_ref text,
    verified_source_title text,
    owner_label text NOT NULL,
    status text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT identity_provider_active_readiness_ck CHECK (((status <> 'ACTIVE'::text) OR ((verification_state = 'VERIFIED'::text) AND (mfa_claim_name IS NOT NULL) AND (mfa_claim_value IS NOT NULL)))),
    CONSTRAINT identity_provider_auth_age_ck CHECK (((max_auth_age_seconds >= 60) AND (max_auth_age_seconds <= 86400))),
    CONSTRAINT identity_provider_code_ck CHECK ((code ~ '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$'::text)),
    CONSTRAINT identity_provider_issuer_ck CHECK ((issuer ~ '^https://[a-z0-9][a-z0-9.-]{0,252}(/[A-Za-z0-9._~-]{1,64}){0,6}$'::text)),
    CONSTRAINT identity_provider_mfa_claim_ck CHECK ((num_nonnulls(mfa_claim_name, mfa_claim_value) <> 1)),
    CONSTRAINT identity_provider_provenance_ck CHECK (((verification_state <> 'VERIFIED'::text) OR ((last_verified_at IS NOT NULL) AND (evidence_ref IS NOT NULL) AND (verified_source_title IS NOT NULL)))),
    CONSTRAINT identity_provider_status_ck CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'RETIRED'::text]))),
    CONSTRAINT identity_provider_verification_ck CHECK ((verification_state = ANY (ARRAY['UNKNOWN'::text, 'UNVERIFIED'::text, 'VERIFIED'::text])))
);

