    CONSTRAINT ad_linked_sale_event_correction_ck CHECK (((adjustment_kind IS NULL) OR (supersedes_event_id IS NOT NULL))),
    CONSTRAINT ad_linked_sale_event_count_ck CHECK ((event_count >= 1)),
