    CONSTRAINT ad_case_calculation_kind_ck CHECK ((calculation_kind = ANY (ARRAY['TARGETED'::text, 'RECONCILIATION'::text]))),
    CONSTRAINT ad_case_cause_ck CHECK ((cause_code ~ '^[A-Z][A-Z0-9_]{1,62}$'::text)),
    CONSTRAINT ad_case_confidence_ck CHECK ((confidence_state = ANY (ARRAY['HIGH'::text, 'MEDIUM'::text, 'LOW'::text, 'UNUSABLE'::text]))),
    CONSTRAINT ad_case_conversion_range_ck CHECK (((ad_linked_conversion_value IS NULL) OR ((ad_linked_conversion_value >= (0)::numeric) AND (ad_linked_conversion_value <= (1)::numeric)))),
    CONSTRAINT ad_case_conversion_stage_ck CHECK (((ad_linked_conversion_state = 'AVAILABLE'::text) = (ad_linked_conversion_stage IS NOT NULL))),
    CONSTRAINT ad_case_conversion_stage_value_ck CHECK (((ad_linked_conversion_stage IS NULL) OR (ad_linked_conversion_stage = ANY (ARRAY['CANONICAL_AD_LINKED_ORDER'::text, 'CANONICAL_AD_LINKED_COMPLETED_SALE'::text, 'CANONICAL_AD_LINKED_RETAINED_SALE'::text])))),
    CONSTRAINT ad_case_currency_ck CHECK (((profit_currency_code IS NULL) OR (profit_currency_code ~ '^[A-Z]{3}$'::text))),
    CONSTRAINT ad_case_currency_presence_ck CHECK (((profit_currency_code IS NOT NULL) = ((contribution_profit_amount IS NOT NULL) OR (official_spend_amount IS NOT NULL) OR (max_cpc_amount IS NOT NULL) OR (current_bid_amount IS NOT NULL) OR (recoverable_profit_amount IS NOT NULL)))),
    CONSTRAINT ad_case_digest_ck CHECK ((policy_version_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT ad_case_evidence_state_ck CHECK ((evidence_state = ANY (ARRAY['CANONICAL_CONFIRMED'::text, 'OPERATIONAL'::text, 'PROVISIONAL_OR_ESTIMATED'::text, 'STALE'::text, 'INCOMPLETE'::text, 'CONFLICTED'::text, 'UNKNOWN'::text, 'NOT_AVAILABLE'::text, 'DATA_BLOCKED'::text, 'POLICY_BLOCKED'::text, 'PROFILE_UNRESOLVED'::text, 'BUNDLE_UNRESOLVED'::text]))),
    CONSTRAINT ad_case_gap_ck CHECK (((attribution_gap_ratio IS NULL) OR (attribution_gap_ratio >= (0)::numeric))),
    CONSTRAINT ad_case_generation_ck CHECK ((lineage_generation >= 1)),
    CONSTRAINT ad_case_key_ck CHECK (((length(btrim(case_key)) >= 1) AND (length(btrim(case_key)) <= 512))),
    CONSTRAINT ad_case_lane_ck CHECK ((lane = ANY (ARRAY['PROTECTION'::text, 'DATA_REPAIR'::text, 'OPTIMIZATION'::text, 'WATCH'::text]))),
    CONSTRAINT ad_case_max_cpc_ck CHECK (((max_cpc_amount IS NULL) OR (max_cpc_amount >= (0)::numeric))),
    CONSTRAINT ad_case_protection_tier_ck CHECK (((lane = 'PROTECTION'::text) = (protection_tier IS NOT NULL))),
    CONSTRAINT ad_case_protection_tier_value_ck CHECK (((protection_tier IS NULL) OR (protection_tier = ANY (ARRAY['P0'::text, 'P1'::text, 'P2'::text, 'P3'::text])))),
    CONSTRAINT ad_case_rank_ck CHECK (((rank_score >= (0)::numeric) AND (rank_score <= (1000000)::numeric))),
    CONSTRAINT ad_case_spend_ck CHECK (((official_spend_amount IS NULL) OR (official_spend_amount >= (0)::numeric))),
    CONSTRAINT ad_case_superseded_reason_ck CHECK (((superseded_reason IS NULL) OR (superseded_reason = ANY (ARRAY['CAUSE_NO_LONGER_CALCULATED'::text, 'OBJECT_LINEAGE_REBUILT'::text, 'OBJECT_RETIRED'::text])))),
    CONSTRAINT ad_case_superseded_shape_ck CHECK (((superseded_at IS NULL) = (superseded_reason IS NULL))),
    CONSTRAINT ad_case_sustained_ck CHECK ((((sustained_lane IS NULL) = (sustained_since IS NULL)) AND ((sustained_lane IS NULL) = (sustained_cycles = 0)))),
    CONSTRAINT ad_case_sustained_cycles_ck CHECK ((sustained_cycles >= 0)),
    CONSTRAINT ad_case_sustained_lane_ck CHECK (((sustained_lane IS NULL) OR (sustained_lane = ANY (ARRAY['PROTECTION'::text, 'DATA_REPAIR'::text, 'OPTIMIZATION'::text, 'WATCH'::text])))),
    CONSTRAINT ad_case_traffic_ck CHECK (((eligible_traffic_count IS NULL) OR (eligible_traffic_count >= 0))),
    CONSTRAINT ad_case_unresolved_affected_set_ck CHECK (((affected_set_id IS NOT NULL) OR ((lane = 'DATA_REPAIR'::text) AND (cause_code = 'AFFECTED_SET_UNRESOLVED'::text) AND ('AFFECTED_SET_NEVER_RESOLVED'::text = ANY (blocker_codes))))),
    CONSTRAINT ad_case_value_presence_ck CHECK ((((contribution_profit_state = 'AVAILABLE'::text) = (contribution_profit_amount IS NOT NULL)) AND ((profit_per_ad_rub_state = 'AVAILABLE'::text) = (profit_per_ad_rub_value IS NOT NULL)) AND ((official_spend_state = 'AVAILABLE'::text) = (official_spend_amount IS NOT NULL)) AND ((eligible_traffic_state = 'AVAILABLE'::text) = (eligible_traffic_count IS NOT NULL)) AND ((ad_linked_conversion_state = 'AVAILABLE'::text) = (ad_linked_conversion_value IS NOT NULL)) AND ((max_cpc_state = 'AVAILABLE'::text) = (max_cpc_amount IS NOT NULL)) AND ((attribution_gap_state = 'AVAILABLE'::text) = (attribution_gap_ratio IS NOT NULL)) AND ((current_bid_state = 'AVAILABLE'::text) = (current_bid_amount IS NOT NULL)))),
    CONSTRAINT ad_case_value_states_ck CHECK (((contribution_profit_state = ANY (ARRAY['AVAILABLE'::text, 'NOT_AVAILABLE'::text, 'UNDEFINED'::text])) AND (profit_per_ad_rub_state = ANY (ARRAY['AVAILABLE'::text, 'NOT_AVAILABLE'::text, 'UNDEFINED'::text])) AND (official_spend_state = ANY (ARRAY['AVAILABLE'::text, 'NOT_AVAILABLE'::text, 'UNDEFINED'::text])) AND (eligible_traffic_state = ANY (ARRAY['AVAILABLE'::text, 'NOT_AVAILABLE'::text, 'UNDEFINED'::text])) AND (ad_linked_conversion_state = ANY (ARRAY['AVAILABLE'::text, 'NOT_AVAILABLE'::text, 'UNDEFINED'::text])) AND (max_cpc_state = ANY (ARRAY['AVAILABLE'::text, 'NOT_AVAILABLE'::text, 'UNDEFINED'::text])) AND (attribution_gap_state = ANY (ARRAY['AVAILABLE'::text, 'NOT_AVAILABLE'::text, 'UNDEFINED'::text])) AND (current_bid_state = ANY (ARRAY['AVAILABLE'::text, 'NOT_AVAILABLE'::text, 'UNDEFINED'::text]))))
);

