    CONSTRAINT ad_case_evidence_role_ck CHECK ((evidence_role = ANY (ARRAY['OFFICIAL_SPEND'::text, 'OFFICIAL_TRAFFIC'::text, 'PROVIDER_ATTRIBUTION'::text, 'AD_LINKED_SALE'::text, 'COMPANY_SALES'::text, 'PROFIT_ECONOMICS'::text, 'OBJECT_CONFIGURATION'::text, 'AFFECTED_SET'::text, 'MAPPING'::text, 'CONVERSION_DEFINITION'::text, 'ALLOWABLE_CPA_DEFINITION'::text, 'FRESHNESS_PROFILE'::text, 'QUALIFICATION_POLICY'::text, 'PRIORITY_POLICY'::text, 'HUMAN_SLO_PROFILE'::text, 'SEMANTIC_PROFILE'::text, 'POLICY_BUNDLE'::text, 'CRITICAL_SALES_GUARD'::text, 'OUTCOME_POLICY'::text])))
