    CONSTRAINT ad_case_variant_diagnostic_money_ck CHECK (((currency_code IS NOT NULL) = ((spend_amount IS NOT NULL) OR (contribution_profit_amount IS NOT NULL)))),
    CONSTRAINT ad_case_variant_diagnostic_official_ck CHECK (((basis <> 'OFFICIAL_OBSERVATION'::text) OR (confidence_state <> 'ESTIMATED_EXPLAINED'::text))),
