    blocker_codes text[] DEFAULT '{}'::text[] NOT NULL,
    calculation_id uuid NOT NULL,
    calculated_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    sustained_lane text,
    sustained_cycles integer DEFAULT 0 NOT NULL,
    sustained_since timestamp with time zone,
    CONSTRAINT availability_risk_child_amount_currency_ck CHECK (((profit_at_risk_amount IS NULL) = (profit_at_risk_currency IS NULL))),
    CONSTRAINT availability_risk_child_cause_ck CHECK ((cause_code ~ '^[A-Z][A-Z0-9_]{1,62}$'::text)),
    CONSTRAINT availability_risk_child_company_safety_ck CHECK (((child_kind <> 'COMPANY'::text) OR (lane <> 'HEALTHY'::text) OR (evidence_state = ANY (ARRAY['CONFIRMED'::text, 'OPERATIONAL'::text])))),
    CONSTRAINT availability_risk_child_confidence_ck CHECK ((confidence_state = ANY (ARRAY['HIGH'::text, 'MEDIUM'::text, 'LOW'::text, 'UNUSABLE'::text]))),
    CONSTRAINT availability_risk_child_currency_ck CHECK (((profit_at_risk_currency IS NULL) OR (profit_at_risk_currency ~ '^[A-Z]{3}$'::text))),
    CONSTRAINT availability_risk_child_demand_ck CHECK (((daily_demand_rate IS NULL) OR (daily_demand_rate >= (0)::numeric))),
    CONSTRAINT availability_risk_child_evidence_ck CHECK ((evidence_state = ANY (ARRAY['CONFIRMED'::text, 'OPERATIONAL'::text, 'PROVISIONAL'::text, 'CARRIED_FORWARD'::text, 'DATA_BLOCKED'::text, 'POLICY_BLOCKED'::text, 'CONFLICTED'::text, 'STALE'::text, 'UNKNOWN'::text]))),
    CONSTRAINT availability_risk_child_horizon_ck CHECK (((coverage_horizon_days IS NULL) OR (coverage_horizon_days >= 0))),
    CONSTRAINT availability_risk_child_identity_ck CHECK ((((child_kind = 'CHANNEL'::text) AND (store_id IS NOT NULL) AND (platform_listing_variant_id IS NOT NULL) AND (fulfillment_mode_code IS NOT NULL)) OR ((child_kind = 'COMPANY'::text) AND (store_id IS NULL) AND (platform_listing_variant_id IS NULL) AND (fulfillment_mode_code IS NULL)))),
    CONSTRAINT availability_risk_child_kind_ck CHECK ((child_kind = ANY (ARRAY['CHANNEL'::text, 'COMPANY'::text]))),
    CONSTRAINT availability_risk_child_lane_ck CHECK ((lane = ANY (ARRAY['HEALTHY'::text, 'WATCH'::text, 'HIGH'::text, 'CRITICAL'::text, 'REVIEW'::text, 'UNRESOLVED'::text]))),
    CONSTRAINT availability_risk_child_profit_lane_ck CHECK ((profit_lane = ANY (ARRAY['CONFIRMED_ELIGIBLE'::text, 'OPERATIONAL_ELIGIBLE'::text, 'PROVISIONAL'::text, 'PROFIT_DATA_BLOCKED'::text, 'NOT_PROFITABLE'::text, 'PROFIT_UNKNOWN'::text]))),
    CONSTRAINT availability_risk_child_proof_shape_ck CHECK ((jsonb_typeof(conservative_proof) = 'object'::text)),
    CONSTRAINT availability_risk_child_provisional_proof_ck CHECK (((evidence_state <> 'PROVISIONAL'::text) OR (jsonb_array_length(COALESCE((conservative_proof -> 'terms'::text), '[]'::jsonb)) > 0))),
    CONSTRAINT availability_risk_child_reason_ck CHECK (((length(btrim(demand_selection_reason)) >= 1) AND (length(btrim(demand_selection_reason)) <= 256))),
    CONSTRAINT availability_risk_child_sustained_cycles_ck CHECK (((sustained_cycles >= 0) AND (sustained_cycles <= 1000000))),
    CONSTRAINT availability_risk_child_sustained_lane_ck CHECK (((sustained_lane IS NULL) OR (sustained_lane = ANY (ARRAY['HEALTHY'::text, 'WATCH'::text, 'HIGH'::text, 'CRITICAL'::text, 'REVIEW'::text, 'UNRESOLVED'::text])))),
    CONSTRAINT availability_risk_child_sustained_shape_ck CHECK ((((sustained_lane IS NULL) = (sustained_since IS NULL)) AND ((sustained_lane IS NULL) = (sustained_cycles = 0)))),
    CONSTRAINT availability_risk_child_units_ck CHECK (((available_units IS NULL) OR (available_units >= 0)))
);

