    CONSTRAINT calculation_run_scope_ck CHECK ((scope_kind = ANY (ARRAY['ORGANIZATION'::text, 'STORE'::text]))),
    CONSTRAINT calculation_run_scope_matrix_ck CHECK (((scope_kind = 'STORE'::text) = (store_ref_id IS NOT NULL))),
    CONSTRAINT calculation_run_state_ck CHECK ((state = ANY (ARRAY['RUNNING'::text, 'SUCCEEDED'::text, 'FAILED'::text]))),
    CONSTRAINT calculation_run_trigger_ck CHECK ((trigger_kind = ANY (ARRAY['SCHEDULED'::text, 'MANUAL'::text, 'LATE_DATA'::text, 'BACKFILL'::text]))),
    CONSTRAINT calculation_run_window_ck CHECK ((window_code = ANY (ARRAY['D7'::text, 'D14'::text, 'D30'::text])))
);

