    CONSTRAINT demand_window_observation_censoring_ck CHECK ((censored = (censoring_reason IS NOT NULL))),
    CONSTRAINT demand_window_observation_coverage_ck CHECK (((coverage_ratio >= (0)::numeric) AND (coverage_ratio <= (1)::numeric))),
    CONSTRAINT demand_window_observation_eligibility_ck CHECK ((eligibility = ANY (ARRAY['ELIGIBLE'::text, 'LOW_SAMPLE'::text, 'CENSORED'::text, 'OUTLIER_REVIEW'::text, 'WINDOW_CONFLICT'::text, 'DATA_BLOCKED'::text]))),
    CONSTRAINT demand_window_observation_observed_ck CHECK ((observed_days >= (0)::numeric)),
    CONSTRAINT demand_window_observation_period_ck CHECK ((period_end > period_start)),
    CONSTRAINT demand_window_observation_rate_ck CHECK (((daily_rate IS NULL) OR (daily_rate >= (0)::numeric))),
    CONSTRAINT demand_window_observation_reason_ck CHECK (((censoring_reason IS NULL) OR (censoring_reason = ANY (ARRAY['NOT_SELLABLE'::text, 'NO_STOCK'::text, 'SOURCE_STALE'::text, 'KNOWN_OUTAGE'::text, 'PARTIAL_COVERAGE'::text])))),
    CONSTRAINT demand_window_observation_units_ck CHECK (((completed_units IS NULL) OR (completed_units >= 0))),
    CONSTRAINT demand_window_observation_window_ck CHECK ((window_code = ANY (ARRAY['D7'::text, 'D14'::text, 'D30'::text])))
);

CREATE TABLE mart.diagnosis_finding (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    calculation_run_id uuid NOT NULL,
    rule_code text NOT NULL,
    rule_version integer NOT NULL,
    subject_kind text NOT NULL,
    subject_id uuid NOT NULL,
    window_code text NOT NULL,
    period_start timestamp with time zone NOT NULL,
    period_end timestamp with time zone NOT NULL,
    outcome text NOT NULL,
    severity text,
    decline_reason text,
    detail jsonb NOT NULL,
    input_digest text NOT NULL,
    evaluated_at timestamp with time zone NOT NULL,
    CONSTRAINT diagnosis_finding_decline_ck CHECK (((outcome = 'DECLINED'::text) = (decline_reason IS NOT NULL))),
    CONSTRAINT diagnosis_finding_decline_values_ck CHECK (((decline_reason IS NULL) OR (decline_reason = ANY (ARRAY['BLOCKED_BY_EARLIER_RULE'::text, 'REQUIRED_METRIC_UNAVAILABLE'::text, 'REQUIRED_METRIC_UNDEFINED'::text, 'MAPPING_UNRESOLVED'::text, 'THRESHOLD_NOT_CONFIGURED'::text, 'INSUFFICIENT_SAMPLE'::text])))),
    CONSTRAINT diagnosis_finding_detail_ck CHECK ((jsonb_typeof(detail) = 'object'::text)),
    CONSTRAINT diagnosis_finding_digest_ck CHECK ((input_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT diagnosis_finding_outcome_ck CHECK ((outcome = ANY (ARRAY['TRIGGERED'::text, 'CLEAR'::text, 'DECLINED'::text]))),
    CONSTRAINT diagnosis_finding_period_ck CHECK ((period_start < period_end)),
    CONSTRAINT diagnosis_finding_severity_ck CHECK (((outcome = 'TRIGGERED'::text) = (severity IS NOT NULL))),
    CONSTRAINT diagnosis_finding_severity_values_ck CHECK (((severity IS NULL) OR (severity = ANY (ARRAY['INFO'::text, 'WARNING'::text, 'CRITICAL'::text])))),
    CONSTRAINT diagnosis_finding_subject_ck CHECK ((subject_kind = ANY (ARRAY['PRODUCT_VARIANT'::text, 'PLATFORM_LISTING_VARIANT'::text, 'STORE'::text]))),
    CONSTRAINT diagnosis_finding_window_ck CHECK ((window_code = ANY (ARRAY['D7'::text, 'D14'::text, 'D30'::text])))
);

