CREATE TABLE mart.lc_conversion_measurement (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    store_id uuid NOT NULL,
    platform_listing_id uuid NOT NULL,
    calculation_run_id uuid NOT NULL,
    definition_version integer NOT NULL,
    window_start timestamp with time zone NOT NULL,
    window_end timestamp with time zone NOT NULL,
    retention_window_days integer NOT NULL,
    evidence_path text NOT NULL,
    path_qualified boolean NOT NULL,
    qualification_reason_codes text[] DEFAULT '{}'::text[] NOT NULL,
    visit_count bigint,
    retained_purchase_visit_count bigint,
    primary_ratio numeric(9,6),
    ratio_state text NOT NULL,
    maturity_reached boolean NOT NULL,
    source_stratified boolean NOT NULL,
    sellable_split jsonb DEFAULT '{}'::jsonb NOT NULL,
    excluded_transition_days date[] DEFAULT '{}'::date[] NOT NULL,
    source_time timestamp with time zone,
    acquisition_time timestamp with time zone,
    computed_at timestamp with time zone NOT NULL,
    CONSTRAINT lc_conversion_measurement_counts_ck CHECK ((((visit_count IS NULL) OR (visit_count >= 0)) AND ((retained_purchase_visit_count IS NULL) OR (retained_purchase_visit_count >= 0)) AND ((visit_count IS NULL) OR (retained_purchase_visit_count IS NULL) OR (retained_purchase_visit_count <= visit_count)))),
    CONSTRAINT lc_conversion_measurement_defined_ck CHECK (((ratio_state <> 'DEFINED'::text) OR ((visit_count > 0) AND (retained_purchase_visit_count IS NOT NULL) AND path_qualified AND maturity_reached))),
    CONSTRAINT lc_conversion_measurement_path_ck CHECK ((evidence_path = ANY (ARRAY['DETAIL'::text, 'OFFICIAL_SUMMARY'::text]))),
    CONSTRAINT lc_conversion_measurement_ratio_bounds_ck CHECK (((primary_ratio IS NULL) OR ((primary_ratio >= (0)::numeric) AND (primary_ratio <= (1)::numeric)))),
    CONSTRAINT lc_conversion_measurement_ratio_ck CHECK (((ratio_state = 'DEFINED'::text) = (primary_ratio IS NOT NULL))),
    CONSTRAINT lc_conversion_measurement_reasons_ck CHECK ((path_qualified = (cardinality(qualification_reason_codes) = 0))),
    CONSTRAINT lc_conversion_measurement_retention_ck CHECK ((retention_window_days = ANY (ARRAY[7, 14, 30]))),
    CONSTRAINT lc_conversion_measurement_split_ck CHECK ((jsonb_typeof(sellable_split) = 'object'::text)),
    CONSTRAINT lc_conversion_measurement_state_ck CHECK ((ratio_state = ANY (ARRAY['DEFINED'::text, 'UNDEFINED'::text, 'NOT_AVAILABLE'::text]))),
    CONSTRAINT lc_conversion_measurement_undefined_ck CHECK (((ratio_state <> 'UNDEFINED'::text) OR (visit_count = 0))),
    CONSTRAINT lc_conversion_measurement_version_ck CHECK ((definition_version >= 1)),
    CONSTRAINT lc_conversion_measurement_window_ck CHECK ((window_start < window_end))
);

CREATE TABLE mart.lc_feedback_classification (
