    CONSTRAINT lc_feedback_classification_reason_check CHECK (((length(reason) >= 1) AND (length(reason) <= 512))),
    CONSTRAINT lc_feedback_classification_revision_no_check CHECK ((revision_no >= 0)),
    CONSTRAINT lc_feedback_classification_theme_code_check CHECK ((theme_code ~ '^[A-Z][A-Z0-9_]{1,62}$'::text))
);

