CREATE TABLE mart.lc_listing_health (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    store_id uuid NOT NULL,
    platform_listing_id uuid NOT NULL,
    calculation_run_id uuid NOT NULL,
    affected_set_id uuid NOT NULL,
    health_version integer NOT NULL,
    necessary_conditions jsonb NOT NULL,
    necessary_state text NOT NULL,
    eligibility jsonb NOT NULL,
    opportunities jsonb NOT NULL,
    definition_digest text NOT NULL,
    source_time timestamp with time zone,
    acquisition_time timestamp with time zone,
    computed_at timestamp with time zone NOT NULL,
    CONSTRAINT lc_listing_health_conditions_ck CHECK ((jsonb_typeof(necessary_conditions) = 'array'::text)),
    CONSTRAINT lc_listing_health_digest_ck CHECK ((definition_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT lc_listing_health_eligibility_ck CHECK (((jsonb_typeof(eligibility) = 'object'::text) AND (eligibility ? 'MEASUREMENT'::text) AND (eligibility ? 'PROTECTION'::text) AND (eligibility ? 'EVALUATION'::text) AND ((eligibility ->> 'MEASUREMENT'::text) = ANY (ARRAY['ELIGIBLE'::text, 'INELIGIBLE'::text, 'UNKNOWN'::text])) AND ((eligibility ->> 'PROTECTION'::text) = ANY (ARRAY['ELIGIBLE'::text, 'INELIGIBLE'::text, 'UNKNOWN'::text])) AND ((eligibility ->> 'EVALUATION'::text) = ANY (ARRAY['ELIGIBLE'::text, 'INELIGIBLE'::text, 'UNKNOWN'::text])))),
    CONSTRAINT lc_listing_health_necessary_ck CHECK ((necessary_state = ANY (ARRAY['PASS'::text, 'FAIL'::text, 'UNKNOWN'::text]))),
    CONSTRAINT lc_listing_health_opportunities_ck CHECK ((jsonb_typeof(opportunities) = 'array'::text)),
    CONSTRAINT lc_listing_health_version_ck CHECK ((health_version >= 1))
);

