    CONSTRAINT lc_measurement_lineage_input_digest_check CHECK ((input_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT lc_measurement_lineage_inputs_check CHECK ((jsonb_typeof(inputs) = 'object'::text))
);

