    CONSTRAINT metric_value_currency_ck CHECK (((currency_code IS NULL) OR (currency_code ~ '^[A-Z]{3}$'::text))),
    CONSTRAINT metric_value_digest_ck CHECK ((input_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT metric_value_estimated_ck CHECK ((estimated = (confidence_state = 'ESTIMATED_EXPLAINED'::text))),
    CONSTRAINT metric_value_freshness_ck CHECK (((freshness_seconds IS NULL) OR (freshness_seconds >= 0))),
    CONSTRAINT metric_value_number_ck CHECK (((value_state = 'AVAILABLE'::text) = (numeric_value IS NOT NULL))),
    CONSTRAINT metric_value_period_ck CHECK ((period_start < period_end)),
    CONSTRAINT metric_value_state_ck CHECK ((value_state = ANY (ARRAY['AVAILABLE'::text, 'NOT_AVAILABLE'::text, 'UNDEFINED'::text]))),
    CONSTRAINT metric_value_subject_ck CHECK ((subject_kind = ANY (ARRAY['PRODUCT_VARIANT'::text, 'PLATFORM_LISTING_VARIANT'::text, 'STORE'::text]))),
    CONSTRAINT metric_value_window_ck CHECK ((window_code = ANY (ARRAY['D7'::text, 'D14'::text, 'D30'::text])))
);

