CREATE TABLE ops.ad_accepted_exception (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    case_id uuid NOT NULL,
    ad_native_object_id uuid NOT NULL,
    store_id uuid NOT NULL,
    platform_code text NOT NULL,
    semantic_profile_id uuid NOT NULL,
    affected_set_digest text NOT NULL,
    cause_code text NOT NULL,
    lane text NOT NULL,
    policy_version_digest text NOT NULL,
    bundle_id uuid,
    known_consequence jsonb NOT NULL,
    exposure_snapshot jsonb NOT NULL,
    requester_user_id uuid NOT NULL,
    requester_role_code text NOT NULL,
    requested_at timestamp with time zone NOT NULL,
    endorser_user_id uuid,
    endorsed_at timestamp with time zone,
    approver_user_id uuid,
    approved_at timestamp with time zone,
    reason text NOT NULL,
    evidence_reference text NOT NULL,
    effective_from timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    review_due_at timestamp with time zone NOT NULL,
    state text NOT NULL,
    ended_at timestamp with time zone,
    end_reason text,
    version bigint DEFAULT 0 NOT NULL,
    authority_valid_until timestamp with time zone,
    CONSTRAINT ad_accepted_exception_affected_set_digest_check CHECK ((affected_set_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT ad_accepted_exception_check CHECK (((effective_from < expires_at) AND (review_due_at > effective_from) AND (review_due_at <= expires_at))),
    CONSTRAINT ad_accepted_exception_check1 CHECK (((endorser_user_id IS NULL) OR (endorser_user_id <> requester_user_id))),
    CONSTRAINT ad_accepted_exception_check2 CHECK (((approver_user_id IS NULL) OR ((approver_user_id <> requester_user_id) AND (approver_user_id <> endorser_user_id)))),
    CONSTRAINT ad_accepted_exception_check3 CHECK (((state <> 'ACTIVE'::text) OR ((approved_at IS NOT NULL) AND (approver_user_id IS NOT NULL) AND (endorsed_at IS NOT NULL) AND (endorser_user_id IS NOT NULL)))),
    CONSTRAINT ad_accepted_exception_check4 CHECK (((state = ANY (ARRAY['ENDED'::text, 'INVALIDATED'::text, 'EXPIRED'::text])) = ((ended_at IS NOT NULL) AND (end_reason IS NOT NULL)))),
    CONSTRAINT ad_accepted_exception_evidence_reference_check CHECK (((length(btrim(evidence_reference)) >= 1) AND (length(btrim(evidence_reference)) <= 512))),
    CONSTRAINT ad_accepted_exception_exposure_snapshot_check CHECK ((jsonb_typeof(exposure_snapshot) = 'object'::text)),
    CONSTRAINT ad_accepted_exception_known_consequence_check CHECK ((jsonb_typeof(known_consequence) = 'object'::text)),
    CONSTRAINT ad_accepted_exception_lane_check CHECK ((lane = ANY (ARRAY['PROTECTION'::text, 'DATA_REPAIR'::text]))),
    CONSTRAINT ad_accepted_exception_reason_check CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 1024))),
    CONSTRAINT ad_accepted_exception_state_check CHECK ((state = ANY (ARRAY['REQUESTED'::text, 'ENDORSED'::text, 'ACTIVE'::text, 'ENDED'::text, 'INVALIDATED'::text, 'EXPIRED'::text]))),
    CONSTRAINT ad_exception_authority_window_ck CHECK (((authority_valid_until IS NOT NULL) AND (authority_valid_until <= expires_at) AND (authority_valid_until > effective_from)))
);

CREATE TABLE ops.ad_action_authorization (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    recommendation_id uuid NOT NULL,
    approval_decision_id uuid NOT NULL,
    candidate_id uuid NOT NULL,
    outcome_baseline_id uuid NOT NULL,
    bundle_id uuid NOT NULL,
    bundle_version integer NOT NULL,
    maker_user_id uuid NOT NULL,
    endorser_user_id uuid NOT NULL,
    final_approver_user_id uuid NOT NULL,
    final_approved_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    bounds jsonb NOT NULL,
    authority_snapshot jsonb NOT NULL,
    materiality_route text NOT NULL,
    CONSTRAINT ad_action_authorization_check CHECK (((maker_user_id <> endorser_user_id) AND (maker_user_id <> final_approver_user_id) AND ((materiality_route = 'ORDINARY_IMPACT'::text) OR (endorser_user_id <> final_approver_user_id)))),
    CONSTRAINT ad_action_authorization_check1 CHECK ((expires_at > final_approved_at)),
    CONSTRAINT ad_action_authorization_materiality_route_check CHECK ((materiality_route = ANY (ARRAY['MATERIAL_IMPACT'::text, 'ORDINARY_IMPACT'::text])))
);

CREATE TABLE ops.ad_action_reservation (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    ad_native_object_id uuid NOT NULL,
    store_id uuid NOT NULL,
    affected_set_id uuid NOT NULL,
    affected_set_digest text NOT NULL,
    product_variant_ids uuid[] NOT NULL,
    intervention_kind text NOT NULL,
    intervention_reference_id uuid NOT NULL,
    direction text,
    lane text NOT NULL,
    state text NOT NULL,
    configuration_resolved boolean DEFAULT false NOT NULL,
    unknown_or_mismatch_open boolean DEFAULT false NOT NULL,
    early_observation_complete boolean DEFAULT false NOT NULL,
    regression_open boolean DEFAULT false NOT NULL,
    reserved_at timestamp with time zone NOT NULL,
    released_at timestamp with time zone,
    release_reason text,
    correlation_id text NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT ad_action_reservation_correlation_ck CHECK (((length(btrim(correlation_id)) >= 1) AND (length(btrim(correlation_id)) <= 128))),
    CONSTRAINT ad_action_reservation_digest_ck CHECK ((affected_set_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT ad_action_reservation_direction_ck CHECK (((direction IS NULL) OR (direction = ANY (ARRAY['PROTECTION_DECREASE'::text, 'OPTIMIZATION_INCREASE'::text, 'EXACT_PRIOR_BID_COMPENSATION'::text])))),
    CONSTRAINT ad_action_reservation_kind_ck CHECK ((intervention_kind = ANY (ARRAY['CONTROLLED_AD_BID_CHANGE'::text, 'CONFIRMED_MANUAL_PACKET'::text, 'EXACT_PRIOR_BID_COMPENSATION'::text]))),
    CONSTRAINT ad_action_reservation_lane_ck CHECK ((lane = ANY (ARRAY['PROTECTION'::text, 'DATA_REPAIR'::text, 'OPTIMIZATION'::text, 'WATCH'::text]))),
    CONSTRAINT ad_action_reservation_release_ck CHECK (((state = 'RELEASED'::text) = ((released_at IS NOT NULL) AND (release_reason IS NOT NULL)))),
    CONSTRAINT ad_action_reservation_release_conditions_ck CHECK (((state <> 'RELEASED'::text) OR (configuration_resolved AND (NOT unknown_or_mismatch_open) AND early_observation_complete AND (NOT regression_open)))),
    CONSTRAINT ad_action_reservation_release_order_ck CHECK (((released_at IS NULL) OR (released_at >= reserved_at))),
    CONSTRAINT ad_action_reservation_release_reason_ck CHECK (((release_reason IS NULL) OR ((length(btrim(release_reason)) >= 1) AND (length(btrim(release_reason)) <= 256)))),
    CONSTRAINT ad_action_reservation_state_ck CHECK ((state = ANY (ARRAY['ACTIVE'::text, 'RELEASED'::text]))),
    CONSTRAINT ad_action_reservation_variants_ck CHECK ((((cardinality(product_variant_ids) >= 1) AND (cardinality(product_variant_ids) <= 4096)) AND (array_position(product_variant_ids, NULL::uuid) IS NULL)))
);

CREATE TABLE ops.ad_authority_invalidation (
