    authorization_id uuid NOT NULL,
    cause_reference uuid NOT NULL,
    cause_code text NOT NULL,
    invalidated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL
);

CREATE TABLE ops.ad_bid_candidate (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    case_id uuid NOT NULL,
    ad_native_object_id uuid NOT NULL,
    affected_set_digest text NOT NULL,
    target_policy_id uuid NOT NULL,
    target_policy_version integer NOT NULL,
    semantic_profile_id uuid NOT NULL,
    direction text NOT NULL,
    candidate_basis text NOT NULL,
    ordinal integer NOT NULL,
    current_bid_amount numeric(18,4) NOT NULL,
    requested_amount numeric(18,4) NOT NULL,
    provider_normalized_amount numeric(18,4) NOT NULL,
    currency_code text NOT NULL,
    bid_unit_code text NOT NULL,
    max_cpc_amount numeric(18,4),
    max_cpc_absence_reason text,
    cause_code text,
    generated_at timestamp with time zone NOT NULL,
    correlation_id text NOT NULL,
    CONSTRAINT ad_bid_candidate_absence_reason_ck CHECK (((max_cpc_absence_reason IS NULL) OR (max_cpc_absence_reason = ANY (ARRAY['STAGE_MISMATCH'::text, 'CONVERSION_NOT_WRITE_GRADE'::text, 'ALLOWABLE_CPA_UNRESOLVED'::text, 'CONVERSION_ZERO'::text])))),
    CONSTRAINT ad_bid_candidate_amounts_ck CHECK (((current_bid_amount >= (0)::numeric) AND (requested_amount >= (0)::numeric) AND (provider_normalized_amount >= (0)::numeric))),
    CONSTRAINT ad_bid_candidate_basis_ck CHECK ((candidate_basis = ANY (ARRAY['MAX_CPC_BOUNDED'::text, 'CAUSE_BOUND_PROTECTION_STEP'::text]))),
    CONSTRAINT ad_bid_candidate_bounded_shape_ck CHECK (((candidate_basis <> 'MAX_CPC_BOUNDED'::text) OR ((max_cpc_amount IS NOT NULL) AND (max_cpc_absence_reason IS NULL)))),
    CONSTRAINT ad_bid_candidate_cause_bound_shape_ck CHECK (((candidate_basis <> 'CAUSE_BOUND_PROTECTION_STEP'::text) OR ((max_cpc_amount IS NULL) AND (max_cpc_absence_reason IS NOT NULL) AND (cause_code IS NOT NULL) AND (direction = 'PROTECTION_DECREASE'::text)))),
    CONSTRAINT ad_bid_candidate_cause_shape_ck CHECK (((cause_code IS NULL) OR (cause_code ~ '^[A-Z][A-Z0-9_]{1,62}$'::text))),
    CONSTRAINT ad_bid_candidate_ceiling_ck CHECK (((direction <> 'OPTIMIZATION_INCREASE'::text) OR ((max_cpc_amount IS NOT NULL) AND (provider_normalized_amount <= max_cpc_amount)))),
    CONSTRAINT ad_bid_candidate_change_ck CHECK ((provider_normalized_amount <> current_bid_amount)),
    CONSTRAINT ad_bid_candidate_correlation_ck CHECK (((length(btrim(correlation_id)) >= 1) AND (length(btrim(correlation_id)) <= 128))),
    CONSTRAINT ad_bid_candidate_currency_ck CHECK ((currency_code ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT ad_bid_candidate_digest_ck CHECK ((affected_set_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT ad_bid_candidate_direction_agrees_ck CHECK ((((direction = 'OPTIMIZATION_INCREASE'::text) = (provider_normalized_amount > current_bid_amount)) OR (direction = 'EXACT_PRIOR_BID_COMPENSATION'::text))),
    CONSTRAINT ad_bid_candidate_direction_ck CHECK ((direction = ANY (ARRAY['PROTECTION_DECREASE'::text, 'OPTIMIZATION_INCREASE'::text, 'EXACT_PRIOR_BID_COMPENSATION'::text]))),
    CONSTRAINT ad_bid_candidate_ordinal_ck CHECK (((ordinal >= 1) AND (ordinal <= 8))),
    CONSTRAINT ad_bid_candidate_target_positive_ck CHECK ((provider_normalized_amount > (0)::numeric)),
    CONSTRAINT ad_bid_candidate_unit_ck CHECK ((bid_unit_code = ANY (ARRAY['CURRENCY_MAJOR'::text, 'CURRENCY_MINOR'::text])))
);

CREATE TABLE ops.ad_bid_command (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    recommendation_id uuid NOT NULL,
    approval_decision_id uuid NOT NULL,
    store_id uuid NOT NULL,
    ad_native_object_id uuid NOT NULL,
    platform_code text NOT NULL,
    capability_id uuid NOT NULL,
    semantic_profile_id uuid NOT NULL,
    candidate_id uuid NOT NULL,
    bundle_id uuid NOT NULL,
    reservation_id uuid NOT NULL,
    idempotency_key text NOT NULL,
    currency_code text NOT NULL,
    bid_unit_code text NOT NULL,
    direction text NOT NULL,
    candidate_basis text NOT NULL,
    materiality_route text NOT NULL,
    prior_bid_amount numeric(18,4) NOT NULL,
    target_bid_amount numeric(18,4) NOT NULL,
    prior_configuration_id uuid NOT NULL,
    affected_set_digest text NOT NULL,
    lineage_generation integer NOT NULL,
    entity_version_digest text NOT NULL,
    authority_snapshot jsonb NOT NULL,
    approval_expires_at timestamp with time zone NOT NULL,
    requested_operation text,
    state text NOT NULL,
    attempt_no integer DEFAULT 0 NOT NULL,
    retry_budget_remaining integer NOT NULL,
    fence_token bigint DEFAULT 1 NOT NULL,
    retry_preflight_fence bigint,
    lease_owner text,
    lease_expires_at timestamp with time zone,
    next_attempt_at timestamp with time zone,
    failure_code text,
    terminal_at timestamp with time zone,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    outcome_baseline_id uuid,
    CONSTRAINT ad_bid_command_amounts_ck CHECK (((prior_bid_amount >= (0)::numeric) AND (target_bid_amount >= (0)::numeric))),
    CONSTRAINT ad_bid_command_attempt_ck CHECK ((attempt_no >= 0)),
    CONSTRAINT ad_bid_command_basis_ck CHECK ((candidate_basis = ANY (ARRAY['MAX_CPC_BOUNDED'::text, 'CAUSE_BOUND_PROTECTION_STEP'::text]))),
    CONSTRAINT ad_bid_command_change_ck CHECK ((target_bid_amount <> prior_bid_amount)),
    CONSTRAINT ad_bid_command_currency_ck CHECK ((currency_code ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT ad_bid_command_digest_ck CHECK (((entity_version_digest ~ '^[0-9a-f]{64}$'::text) AND (affected_set_digest ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT ad_bid_command_direction_agrees_ck CHECK (((direction = 'EXACT_PRIOR_BID_COMPENSATION'::text) OR ((direction = 'OPTIMIZATION_INCREASE'::text) = (target_bid_amount > prior_bid_amount)))),
    CONSTRAINT ad_bid_command_direction_ck CHECK ((direction = ANY (ARRAY['PROTECTION_DECREASE'::text, 'OPTIMIZATION_INCREASE'::text, 'EXACT_PRIOR_BID_COMPENSATION'::text]))),
    CONSTRAINT ad_bid_command_failure_ck CHECK (((state <> ALL (ARRAY['FAILED_FINAL'::text, 'COMPENSATION_FAILED'::text, 'TERMINATED_WITHOUT_PROVIDER_CALL'::text])) OR (failure_code IS NOT NULL))),
    CONSTRAINT ad_bid_command_fence_ck CHECK ((fence_token > 0)),
    CONSTRAINT ad_bid_command_generation_ck CHECK ((lineage_generation >= 1)),
    CONSTRAINT ad_bid_command_idempotency_ck CHECK ((idempotency_key ~ '^[a-z0-9][a-z0-9._-]{15,127}$'::text)),
    CONSTRAINT ad_bid_command_lease_pairing_ck CHECK ((num_nonnulls(lease_owner, lease_expires_at) <> 1)),
    CONSTRAINT ad_bid_command_leased_state_ck CHECK (((state <> ALL (ARRAY['LEASED'::text, 'EXECUTING'::text, 'READBACK_PENDING'::text])) OR (lease_owner IS NOT NULL))),
    CONSTRAINT ad_bid_command_materiality_ck CHECK ((materiality_route = ANY (ARRAY['MATERIAL_IMPACT'::text, 'ORDINARY_IMPACT'::text, 'MATERIALITY_UNRESOLVED'::text]))),
    CONSTRAINT ad_bid_command_requested_operation_check CHECK ((requested_operation = 'READBACK'::text)),
    CONSTRAINT ad_bid_command_retry_budget_ck CHECK ((retry_budget_remaining >= 0)),
    CONSTRAINT ad_bid_command_retry_preflight_fence_ck CHECK (((retry_preflight_fence > 0) AND (retry_preflight_fence <= fence_token))),
    CONSTRAINT ad_bid_command_state_ck CHECK ((state = ANY (ARRAY['PENDING'::text, 'LEASED'::text, 'EXECUTING'::text, 'PLATFORM_PENDING'::text, 'READBACK_PENDING'::text, 'READBACK_MATCHED'::text, 'RETRY_WAIT'::text, 'UNKNOWN_REQUIRES_READBACK'::text, 'READBACK_MISMATCH'::text, 'LATER_CHANGE_OR_MISMATCH_INVESTIGATION'::text, 'MANUAL_RESOLUTION'::text, 'FAILED_FINAL'::text, 'TERMINATED_WITHOUT_PROVIDER_CALL'::text, 'COMPENSATION_PENDING'::text, 'COMPENSATED'::text, 'COMPENSATION_FAILED'::text]))),
    CONSTRAINT ad_bid_command_terminal_ck CHECK (((state = ANY (ARRAY['READBACK_MATCHED'::text, 'FAILED_FINAL'::text, 'TERMINATED_WITHOUT_PROVIDER_CALL'::text, 'COMPENSATED'::text, 'COMPENSATION_FAILED'::text])) = (terminal_at IS NOT NULL))),
    CONSTRAINT ad_bid_command_unit_ck CHECK ((bid_unit_code = ANY (ARRAY['CURRENCY_MAJOR'::text, 'CURRENCY_MINOR'::text]))),
    CONSTRAINT ad_bid_command_unresolved_materiality_ck CHECK (((materiality_route <> 'MATERIALITY_UNRESOLVED'::text) OR (state = ANY (ARRAY['TERMINATED_WITHOUT_PROVIDER_CALL'::text, 'FAILED_FINAL'::text]))))
);

CREATE TABLE ops.ad_bid_command_attempt (
    id uuid NOT NULL,
    command_id uuid NOT NULL,
    attempt_no integer NOT NULL,
    purpose text NOT NULL,
    fence_token bigint NOT NULL,
    lease_owner text NOT NULL,
    started_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    outcome_class text NOT NULL,
    native_status text,
    native_task_key text,
    raw_observation_id uuid,
    error_code text,
    correlation_id text NOT NULL,
    request_digest text NOT NULL,
    operation_snapshot jsonb NOT NULL,
    expected_version_token text,
    CONSTRAINT ad_bid_command_attempt_completion_ck CHECK (((outcome_class = 'IN_FLIGHT'::text) = (completed_at IS NULL))),
    CONSTRAINT ad_bid_command_attempt_correlation_ck CHECK (((length(btrim(correlation_id)) >= 1) AND (length(btrim(correlation_id)) <= 128))),
    CONSTRAINT ad_bid_command_attempt_digest_ck CHECK ((request_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT ad_bid_command_attempt_fence_ck CHECK ((fence_token > 0)),
    CONSTRAINT ad_bid_command_attempt_no_ck CHECK ((attempt_no > 0)),
    CONSTRAINT ad_bid_command_attempt_outcome_ck CHECK ((outcome_class = ANY (ARRAY['IN_FLIGHT'::text, 'ACCEPTED'::text, 'REJECTED'::text, 'RETRIABLE_ERROR'::text, 'TIMEOUT'::text, 'UNKNOWN_STATE'::text]))),
    CONSTRAINT ad_bid_command_attempt_purpose_ck CHECK ((purpose = ANY (ARRAY['APPLY'::text, 'STATUS_ENQUIRY'::text, 'READBACK'::text, 'RESTORE'::text]))),
    CONSTRAINT ad_bid_command_attempt_snapshot_ck CHECK ((jsonb_typeof(operation_snapshot) = 'object'::text))
);

CREATE TABLE ops.ad_bid_command_readback (
    id uuid NOT NULL,
    command_id uuid NOT NULL,
    attempt_id uuid NOT NULL,
    observed_at timestamp with time zone NOT NULL,
    observed_bid numeric(18,4),
    currency_code text,
    bid_unit_code text,
    match_state text NOT NULL,
    raw_observation_id uuid NOT NULL,
    correlation_id text NOT NULL,
    CONSTRAINT ad_bid_command_readback_bid_ck CHECK (((observed_bid IS NULL) OR (observed_bid >= (0)::numeric))),
    CONSTRAINT ad_bid_command_readback_correlation_ck CHECK (((length(btrim(correlation_id)) >= 1) AND (length(btrim(correlation_id)) <= 128))),
    CONSTRAINT ad_bid_command_readback_currency_ck CHECK (((currency_code IS NULL) OR (currency_code ~ '^[A-Z]{3}$'::text))),
    CONSTRAINT ad_bid_command_readback_match_ck CHECK ((match_state = ANY (ARRAY['MATCHES_TARGET'::text, 'MATCHES_PRIOR'::text, 'DIFFERENT'::text, 'UNREADABLE'::text]))),
    CONSTRAINT ad_bid_command_readback_unit_ck CHECK (((bid_unit_code IS NULL) OR (bid_unit_code = ANY (ARRAY['CURRENCY_MAJOR'::text, 'CURRENCY_MINOR'::text])))),
    CONSTRAINT ad_bid_command_readback_value_ck CHECK (((match_state = 'UNREADABLE'::text) = ((observed_bid IS NULL) AND (currency_code IS NULL) AND (bid_unit_code IS NULL))))
);

CREATE TABLE ops.ad_bid_command_transition (
    from_state text NOT NULL,
    to_state text NOT NULL,
    requires_lease boolean NOT NULL,
    releases_lease boolean NOT NULL,
    note text NOT NULL,
    CONSTRAINT ad_bid_command_transition_distinct_ck CHECK ((from_state <> to_state))
);

CREATE TABLE ops.ad_brief_publication (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    brief_kind text NOT NULL,
    period_key text NOT NULL,
    period_starts_at timestamp with time zone NOT NULL,
    period_ends_at timestamp with time zone NOT NULL,
    as_of timestamp with time zone NOT NULL,
    calendar_policy_id uuid NOT NULL,
    calendar_policy_version integer NOT NULL,
    cursor_feed_code text NOT NULL,
    cursor_position_at timestamp with time zone NOT NULL,
    cursor_position_item_key text NOT NULL,
    max_calculation_id uuid,
    reconciliation_run_id uuid,
    policy_version_digest text NOT NULL,
    bundle_version_snapshot jsonb NOT NULL,
    gap_codes text[] DEFAULT '{}'::text[] NOT NULL,
    revision_no integer DEFAULT 1 NOT NULL,
    supersedes_publication_id uuid,
    revision_kind text NOT NULL,
    adjustment_reason text,
    late_fact_reference text,
    content_digest text NOT NULL,
    published_at timestamp with time zone NOT NULL,
    correlation_id text NOT NULL,
    CONSTRAINT ad_brief_publication_adjustment_ck CHECK (((adjustment_reason IS NULL) OR ((length(btrim(adjustment_reason)) >= 1) AND (length(btrim(adjustment_reason)) <= 1024)))),
    CONSTRAINT ad_brief_publication_as_of_ck CHECK ((as_of <= published_at)),
    CONSTRAINT ad_brief_publication_bundle_snapshot_ck CHECK ((jsonb_typeof(bundle_version_snapshot) = 'array'::text)),
    CONSTRAINT ad_brief_publication_correlation_ck CHECK (((length(btrim(correlation_id)) >= 1) AND (length(btrim(correlation_id)) <= 128))),
    CONSTRAINT ad_brief_publication_cursor_feed_ck CHECK ((cursor_feed_code = 'ADVERTISING_ACCEPTED_FACT'::text)),
    CONSTRAINT ad_brief_publication_cursor_item_ck CHECK (((length(btrim(cursor_position_item_key)) >= 1) AND (length(btrim(cursor_position_item_key)) <= 256))),
    CONSTRAINT ad_brief_publication_digest_ck CHECK (((policy_version_digest ~ '^[0-9a-f]{64}$'::text) AND (content_digest ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT ad_brief_publication_first_revision_ck CHECK (((revision_kind <> 'ORIGINAL'::text) OR (revision_no = 1))),
    CONSTRAINT ad_brief_publication_gaps_ck CHECK ((((cardinality(gap_codes) >= 0) AND (cardinality(gap_codes) <= 64)) AND (array_position(gap_codes, NULL::text) IS NULL))),
    CONSTRAINT ad_brief_publication_kind_ck CHECK ((brief_kind = ANY (ARRAY['DAILY_ACTION_BRIEF'::text, 'WEEKLY_EVIDENCE_REVIEW'::text]))),
    CONSTRAINT ad_brief_publication_late_fact_ck CHECK (((late_fact_reference IS NULL) OR ((length(btrim(late_fact_reference)) >= 1) AND (length(btrim(late_fact_reference)) <= 512)))),
    CONSTRAINT ad_brief_publication_period_ck CHECK ((period_ends_at > period_starts_at)),
    CONSTRAINT ad_brief_publication_period_key_ck CHECK (((length(btrim(period_key)) >= 1) AND (length(btrim(period_key)) <= 32))),
    CONSTRAINT ad_brief_publication_revision_ck CHECK ((revision_no >= 1)),
    CONSTRAINT ad_brief_publication_revision_kind_ck CHECK ((revision_kind = ANY (ARRAY['ORIGINAL'::text, 'REVISION'::text, 'DELTA'::text]))),
    CONSTRAINT ad_brief_publication_revision_shape_ck CHECK (((revision_kind = ANY (ARRAY['REVISION'::text, 'DELTA'::text])) = ((supersedes_publication_id IS NOT NULL) AND (revision_no > 1) AND (adjustment_reason IS NOT NULL) AND (late_fact_reference IS NOT NULL))))
);

CREATE TABLE ops.ad_bundle_endorsement (
    bundle_id uuid NOT NULL,
    endorser_user_id uuid NOT NULL,
    endorsed_at timestamp with time zone NOT NULL,
    authority_snapshot jsonb NOT NULL
);

CREATE TABLE ops.ad_candidate_endorsement (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    selection_id uuid NOT NULL,
    recommendation_id uuid NOT NULL,
    endorser_user_id uuid NOT NULL,
    endorsed_at timestamp with time zone NOT NULL,
    reason text NOT NULL,
    authority_snapshot jsonb NOT NULL,
    CONSTRAINT ad_candidate_endorsement_authority_snapshot_check CHECK ((jsonb_typeof(authority_snapshot) = 'object'::text)),
    CONSTRAINT ad_candidate_endorsement_reason_check CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 1024)))
);

CREATE TABLE ops.ad_candidate_selection (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    case_id uuid NOT NULL,
    candidate_id uuid NOT NULL,
    recommendation_id uuid NOT NULL,
    maker_user_id uuid NOT NULL,
    outcome_baseline_id uuid NOT NULL,
    selected_at timestamp with time zone NOT NULL,
    reason text NOT NULL,
    bundle_id uuid NOT NULL,
    bundle_version integer NOT NULL,
    affected_set_digest text NOT NULL,
    authority_snapshot jsonb NOT NULL,
    CONSTRAINT ad_candidate_selection_affected_set_digest_check CHECK ((affected_set_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT ad_candidate_selection_authority_snapshot_check CHECK ((jsonb_typeof(authority_snapshot) = 'object'::text)),
    CONSTRAINT ad_candidate_selection_bundle_version_check CHECK ((bundle_version > 0)),
    CONSTRAINT ad_candidate_selection_reason_check CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 1024)))
);

CREATE TABLE ops.ad_case_responsibility (
    case_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    task_id uuid NOT NULL,
    recommendation_id uuid NOT NULL,
    owner_role_code text NOT NULL,
    slo_profile_id uuid,
    slo_profile_version integer,
    calendar_id uuid,
    calendar_version integer,
    first_raised_at timestamp with time zone NOT NULL,
    recorded_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    acknowledgement_due_at timestamp with time zone,
    action_due_at timestamp with time zone,
    escalation_due_at timestamp with time zone,
    next_staffed_response_at timestamp with time zone,
    coverage_state text NOT NULL,
    profile_snapshot jsonb NOT NULL,
    CONSTRAINT ad_case_responsibility_coverage_state_check CHECK ((coverage_state = ANY (ARRAY['IN_COVERAGE'::text, 'OUT_OF_COVERAGE_ACTIVE_HARM'::text, 'OUT_OF_COVERAGE'::text, 'PROFILE_MISSING'::text, 'CALENDAR_MISSING'::text]))),
    CONSTRAINT ad_case_responsibility_profile_snapshot_check CHECK ((jsonb_typeof(profile_snapshot) = 'object'::text)),
    CONSTRAINT ad_responsibility_deadline_order CHECK (((acknowledgement_due_at <= action_due_at) AND (action_due_at <= escalation_due_at))),
    CONSTRAINT ad_responsibility_profile_shape CHECK ((((slo_profile_id IS NULL) AND (slo_profile_version IS NULL) AND (acknowledgement_due_at IS NULL) AND (action_due_at IS NULL) AND (escalation_due_at IS NULL)) OR ((slo_profile_id IS NOT NULL) AND (slo_profile_version > 0))))
);

CREATE TABLE ops.ad_compensation_authorization (
    id uuid NOT NULL,
    command_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    bundle_id uuid NOT NULL,
    reservation_id uuid NOT NULL,
    captured_prior_bid numeric(18,4) NOT NULL,
    current_owner_bid numeric(18,4) NOT NULL,
    currency_code text NOT NULL,
    bid_unit_code text NOT NULL,
    affected_set_digest text NOT NULL,
    maker_user_id uuid NOT NULL,
    previewed_at timestamp with time zone NOT NULL,
    preview_expires_at timestamp with time zone NOT NULL,
    preview_snapshot jsonb NOT NULL,
    endorser_user_id uuid,
    endorsed_at timestamp with time zone,
    owner_user_id uuid,
    approved_at timestamp with time zone,
    expires_at timestamp with time zone,
    CONSTRAINT ad_compensation_authorization_check CHECK (((maker_user_id IS DISTINCT FROM endorser_user_id) AND (maker_user_id IS DISTINCT FROM owner_user_id))),
    CONSTRAINT ad_compensation_authorization_check1 CHECK (((endorser_user_id IS NULL) OR (owner_user_id IS NULL) OR (endorser_user_id <> owner_user_id)))
);

CREATE TABLE ops.ad_compensation_invalidation (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    compensation_id uuid NOT NULL,
    cause_reference uuid NOT NULL,
    cause_code text NOT NULL,
    invalidated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL
);

CREATE TABLE ops.ad_containment (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    containment_kind text NOT NULL,
    scope_kind text NOT NULL,
    platform_code text,
    marketplace_account_id uuid,
    store_id uuid,
    ad_native_object_id uuid,
    affected_set_digest text,
    capability_code text,
    authority_version_reference text,
    cause_class text NOT NULL,
    reason text NOT NULL,
    evidence_reference text NOT NULL,
    activated_by_user_id uuid,
    activated_by_trigger text,
    activated_at timestamp with time zone NOT NULL,
    state text NOT NULL,
    root_cause_classified boolean DEFAULT false NOT NULL,
    unknowns_resolved boolean DEFAULT false NOT NULL,
    authorities_replaced boolean DEFAULT false NOT NULL,
    results_reconciled boolean DEFAULT false NOT NULL,
    capability_evidence_current boolean DEFAULT false NOT NULL,
    security_attestation_present boolean DEFAULT false NOT NULL,
    endorsed_by_user_id uuid,
    approved_by_user_id uuid,
    reenabled_scope jsonb,
    reenabled_at timestamp with time zone,
    correlation_id text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    accountable_role_code text,
    action_command_id uuid,
    review_owner_user_id uuid,
    CONSTRAINT ad_containment_accountable_role_ck CHECK (((accountable_role_code IS NULL) OR (accountable_role_code = ANY (ARRAY['OWNER'::text, 'OPERATIONS'::text, 'FINANCE'::text, 'MARKETPLACE_OPERATOR'::text, 'PRODUCT_PROCUREMENT'::text, 'TECH_DATA'::text, 'FINANCE_ANALYST'::text, 'OPS_LEAD'::text, 'RISK_AUTHORITY'::text])))),
    CONSTRAINT ad_containment_activator_ck CHECK ((num_nonnulls(activated_by_user_id, activated_by_trigger) = 1)),
    CONSTRAINT ad_containment_approval_separation_ck CHECK (((approved_by_user_id IS NULL) OR (endorsed_by_user_id IS NULL) OR (approved_by_user_id <> endorsed_by_user_id))),
    CONSTRAINT ad_containment_attestation_ck CHECK (((state <> 'REENABLED'::text) OR (cause_class <> ALL (ARRAY['EXECUTION_INTEGRITY'::text, 'PROVIDER_OR_READBACK_DEFECT'::text, 'CREDENTIAL_OR_SECURITY'::text])) OR security_attestation_present)),
    CONSTRAINT ad_containment_cause_ck CHECK ((cause_class = ANY (ARRAY['BUSINESS_HARM'::text, 'OUTCOME_REGRESSION'::text, 'EXECUTION_INTEGRITY'::text, 'AUTHORITY_VERSION_INVALID'::text, 'PROVIDER_OR_READBACK_DEFECT'::text, 'CREDENTIAL_OR_SECURITY'::text]))),
    CONSTRAINT ad_containment_correlation_ck CHECK (((length(btrim(correlation_id)) >= 1) AND (length(btrim(correlation_id)) <= 128))),
    CONSTRAINT ad_containment_digest_ck CHECK (((affected_set_digest IS NULL) OR (affected_set_digest ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT ad_containment_evidence_ck CHECK (((length(btrim(evidence_reference)) >= 1) AND (length(btrim(evidence_reference)) <= 512))),
    CONSTRAINT ad_containment_kind_ck CHECK ((containment_kind = ANY (ARRAY['EMERGENCY_ENTITY_HOLD'::text, 'ACTION_OUTCOME_QUARANTINE'::text, 'AUTHORITY_VERSION_QUARANTINE'::text, 'CAPABILITY_QUARANTINED'::text, 'KILL_SWITCH_ACTIVE'::text]))),
    CONSTRAINT ad_containment_reason_ck CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 1024))),
    CONSTRAINT ad_containment_reenablement_ck CHECK (((state <> 'REENABLED'::text) OR (root_cause_classified AND unknowns_resolved AND authorities_replaced AND results_reconciled AND capability_evidence_current AND (endorsed_by_user_id IS NOT NULL) AND (approved_by_user_id IS NOT NULL) AND (reenabled_scope IS NOT NULL) AND (reenabled_at IS NOT NULL)))),
    CONSTRAINT ad_containment_scope_ck CHECK ((scope_kind = ANY (ARRAY['ENTITY'::text, 'AFFECTED_SET'::text, 'AUTHORITY_VERSION'::text, 'PLATFORM_STORE_CAPABILITY'::text, 'PLATFORM_ACCOUNT_CAPABILITY'::text]))),
    CONSTRAINT ad_containment_scope_json_ck CHECK (((reenabled_scope IS NULL) OR (jsonb_typeof(reenabled_scope) = 'object'::text))),
    CONSTRAINT ad_containment_scope_shape_ck CHECK ((((scope_kind = 'ENTITY'::text) AND (ad_native_object_id IS NOT NULL)) OR ((scope_kind = 'AFFECTED_SET'::text) AND (affected_set_digest IS NOT NULL)) OR ((scope_kind = 'AUTHORITY_VERSION'::text) AND (authority_version_reference IS NOT NULL)) OR ((scope_kind = 'PLATFORM_STORE_CAPABILITY'::text) AND (platform_code IS NOT NULL) AND (store_id IS NOT NULL) AND (capability_code IS NOT NULL)) OR ((scope_kind = 'PLATFORM_ACCOUNT_CAPABILITY'::text) AND (platform_code IS NOT NULL) AND (marketplace_account_id IS NOT NULL) AND (capability_code IS NOT NULL)))),
    CONSTRAINT ad_containment_separation_ck CHECK (((activated_by_user_id IS NULL) OR ((endorsed_by_user_id IS DISTINCT FROM activated_by_user_id) AND (approved_by_user_id IS DISTINCT FROM activated_by_user_id)))),
    CONSTRAINT ad_containment_state_ck CHECK ((state = ANY (ARRAY['ACTIVE'::text, 'REENABLEMENT_REVIEW'::text, 'REENABLED'::text]))),
    CONSTRAINT ad_containment_trigger_ck CHECK (((activated_by_trigger IS NULL) OR (activated_by_trigger ~ '^[A-Z][A-Z0-9_]{1,62}$'::text)))
);

CREATE TABLE ops.ad_containment_attestation (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    containment_id uuid NOT NULL,
    condition text NOT NULL,
    actor_user_id uuid NOT NULL,
    evidence_reference text NOT NULL,
    attested_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT ad_containment_attestation_condition_check CHECK ((condition = ANY (ARRAY['ROOT_CAUSE_CLASSIFIED'::text, 'UNKNOWNS_RESOLVED'::text, 'AUTHORITIES_REPLACED'::text, 'RESULTS_RECONCILED'::text, 'CAPABILITY_EVIDENCE_CURRENT'::text, 'SECURITY_ATTESTATION_PRESENT'::text, 'OPERATIONS_ENDORSEMENT'::text])))
);

CREATE TABLE ops.ad_decision_policy_bundle (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    bundle_version integer NOT NULL,
    platform_code text NOT NULL,
    marketplace_account_id uuid NOT NULL,
    store_id uuid NOT NULL,
    capability_code text NOT NULL,
    direction text NOT NULL,
    candidate_basis text NOT NULL,
    native_object_kind text NOT NULL,
    lifecycle_scope text NOT NULL,
    semantic_profile_id uuid NOT NULL,
    conversion_definition_id uuid NOT NULL,
    allowable_cpa_definition_id uuid NOT NULL,
    qualification_policy_id uuid NOT NULL,
    target_policy_id uuid NOT NULL,
    outcome_policy_id uuid,
    priority_policy_id uuid NOT NULL,
    human_slo_profile_id uuid NOT NULL,
    approval_lease_policy_id uuid NOT NULL,
    exposure_envelope_id uuid NOT NULL,
    materiality_policy_id uuid NOT NULL,
    ordinary_promotion_id uuid,
    validation_state text NOT NULL,
    validation_failure_codes text[] DEFAULT '{}'::text[] NOT NULL,
    activated_by_user_id uuid,
    endorsed_by_user_id uuid,
    approved_by_user_id uuid,
    security_attestation_present boolean DEFAULT false NOT NULL,
    gate_scope_reference text,
    effective_from timestamp with time zone NOT NULL,
    effective_to timestamp with time zone,
    status text NOT NULL,
    reason text NOT NULL,
    evidence_reference text NOT NULL,
    correlation_id text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    gate_authority_id uuid,
    CONSTRAINT ad_decision_policy_bundle_activation_ck CHECK (((status <> 'ACTIVE'::text) OR ((validation_state = 'VALIDATED'::text) AND (activated_by_user_id IS NOT NULL) AND (endorsed_by_user_id IS NOT NULL) AND (approved_by_user_id IS NOT NULL) AND (gate_scope_reference IS NOT NULL)))),
    CONSTRAINT ad_decision_policy_bundle_basis_ck CHECK ((candidate_basis = ANY (ARRAY['MAX_CPC_BOUNDED'::text, 'CAUSE_BOUND_PROTECTION_STEP'::text]))),
    CONSTRAINT ad_decision_policy_bundle_capability_ck CHECK ((capability_code = 'ad-bid-change'::text)),
    CONSTRAINT ad_decision_policy_bundle_correlation_ck CHECK (((length(btrim(correlation_id)) >= 1) AND (length(btrim(correlation_id)) <= 128))),
    CONSTRAINT ad_decision_policy_bundle_direction_ck CHECK ((direction = ANY (ARRAY['PROTECTION_DECREASE'::text, 'OPTIMIZATION_INCREASE'::text, 'EXACT_PRIOR_BID_COMPENSATION'::text]))),
    CONSTRAINT ad_decision_policy_bundle_evidence_ck CHECK (((length(btrim(evidence_reference)) >= 1) AND (length(btrim(evidence_reference)) <= 512))),
    CONSTRAINT ad_decision_policy_bundle_failures_ck CHECK (((validation_state = 'VALIDATED'::text) = (cardinality(validation_failure_codes) = 0))),
    CONSTRAINT ad_decision_policy_bundle_gate_ck CHECK (((gate_scope_reference IS NULL) OR ((length(btrim(gate_scope_reference)) >= 1) AND (length(btrim(gate_scope_reference)) <= 256)))),
    CONSTRAINT ad_decision_policy_bundle_increase_basis_ck CHECK (((direction <> 'OPTIMIZATION_INCREASE'::text) OR (candidate_basis = 'MAX_CPC_BOUNDED'::text))),
    CONSTRAINT ad_decision_policy_bundle_interval_ck CHECK (((effective_to IS NULL) OR (effective_to > effective_from))),
    CONSTRAINT ad_decision_policy_bundle_lifecycle_ck CHECK ((lifecycle_scope = ANY (ARRAY['ALL'::text, 'HERO'::text, 'GROWTH'::text, 'MATURE'::text, 'REPAIR'::text, 'EXIT'::text]))),
    CONSTRAINT ad_decision_policy_bundle_object_kind_ck CHECK ((native_object_kind = ANY (ARRAY['CAMPAIGN'::text, 'AD_GROUP'::text, 'TARGET'::text, 'KEYWORD'::text, 'PLACEMENT'::text]))),
    CONSTRAINT ad_decision_policy_bundle_outcome_ck CHECK (((direction = 'EXACT_PRIOR_BID_COMPENSATION'::text) OR (outcome_policy_id IS NOT NULL))),
    CONSTRAINT ad_decision_policy_bundle_reason_ck CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 1024))),
    CONSTRAINT ad_decision_policy_bundle_separation_ck CHECK (((endorsed_by_user_id IS NULL) OR (approved_by_user_id IS NULL) OR ((endorsed_by_user_id <> approved_by_user_id) AND (endorsed_by_user_id IS DISTINCT FROM activated_by_user_id) AND (approved_by_user_id IS DISTINCT FROM activated_by_user_id)))),
    CONSTRAINT ad_decision_policy_bundle_status_ck CHECK ((status = ANY (ARRAY['DRAFT'::text, 'ACTIVE'::text, 'SUPERSEDED'::text, 'REVOKED'::text]))),
    CONSTRAINT ad_decision_policy_bundle_validation_ck CHECK ((validation_state = ANY (ARRAY['PENDING'::text, 'VALIDATED'::text, 'REJECTED'::text]))),
    CONSTRAINT ad_decision_policy_bundle_version_ck CHECK ((bundle_version >= 1))
);

CREATE TABLE ops.ad_exception_authority_change (
