CREATE TABLE ops.ad_gate_authority (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    gate_kind text NOT NULL,
    platform_code text NOT NULL,
    marketplace_account_id uuid NOT NULL,
    store_id uuid NOT NULL,
    capability_code text NOT NULL,
    native_object_ids uuid[] NOT NULL,
    direction text NOT NULL,
    candidate_basis text NOT NULL,
    bundle_id uuid NOT NULL,
    exact_head_sha text NOT NULL,
    exact_tree_sha text NOT NULL,
    owner_user_id uuid NOT NULL,
    approved_at timestamp with time zone NOT NULL,
    valid_from timestamp with time zone NOT NULL,
    valid_until timestamp with time zone NOT NULL,
    max_commands integer NOT NULL,
    max_bid_change_amount numeric(18,4) NOT NULL,
    currency_code text NOT NULL,
    stop_conditions jsonb NOT NULL,
    evidence_reference text NOT NULL,
    controller_verdict_reference text NOT NULL,
    security_attestation_reference text NOT NULL,
    restoration_plan_reference text NOT NULL,
    status text DEFAULT 'DRAFT'::text NOT NULL,
    production_write_enabled boolean DEFAULT false NOT NULL,
    exact_object_values jsonb NOT NULL,
    release_evidence_reference text NOT NULL,
    shadow_evidence_reference text NOT NULL,
    adoption_evidence_reference text NOT NULL,
    execution_evidence_reference text NOT NULL,
    early_safety_evidence_reference text NOT NULL,
    operating_coverage_reference text NOT NULL,
    demonstrated_object_ids uuid[] NOT NULL,
    predecessor_gate_ev_id uuid,
    CONSTRAINT ad_gate_authority_capability_code_check CHECK ((capability_code = 'ad-bid-change'::text)),
    CONSTRAINT ad_gate_authority_check CHECK ((valid_until > valid_from)),
    CONSTRAINT ad_gate_authority_check1 CHECK ((native_object_ids <@ demonstrated_object_ids)),
    CONSTRAINT ad_gate_authority_check2 CHECK (((gate_kind <> 'GATE_E'::text) OR (predecessor_gate_ev_id IS NOT NULL))),
    CONSTRAINT ad_gate_authority_check3 CHECK (((NOT production_write_enabled) OR (status = 'ACTIVE'::text))),
    CONSTRAINT ad_gate_authority_currency_code_check CHECK ((currency_code ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT ad_gate_authority_direction_check CHECK ((direction = ANY (ARRAY['PROTECTION_DECREASE'::text, 'OPTIMIZATION_INCREASE'::text, 'EXACT_PRIOR_BID_COMPENSATION'::text]))),
    CONSTRAINT ad_gate_authority_exact_head_sha_check CHECK ((exact_head_sha ~ '^[0-9a-f]{40}$'::text)),
    CONSTRAINT ad_gate_authority_exact_object_values_check CHECK ((jsonb_typeof(exact_object_values) = 'object'::text)),
    CONSTRAINT ad_gate_authority_exact_tree_sha_check CHECK ((exact_tree_sha ~ '^[0-9a-f]{40}$'::text)),
    CONSTRAINT ad_gate_authority_gate_kind_check CHECK ((gate_kind = ANY (ARRAY['GATE_EV'::text, 'GATE_E'::text]))),
    CONSTRAINT ad_gate_authority_max_bid_change_amount_check CHECK ((max_bid_change_amount >= (0)::numeric)),
    CONSTRAINT ad_gate_authority_max_commands_check CHECK ((max_commands > 0)),
    CONSTRAINT ad_gate_authority_native_object_ids_check CHECK ((cardinality(native_object_ids) > 0)),
    CONSTRAINT ad_gate_authority_status_check CHECK ((status = ANY (ARRAY['DRAFT'::text, 'ACTIVE'::text, 'REVOKED'::text, 'EXPIRED'::text]))),
    CONSTRAINT ad_gate_authority_stop_conditions_check CHECK (((jsonb_typeof(stop_conditions) = 'array'::text) AND (jsonb_array_length(stop_conditions) > 0)))
);

