);

CREATE TABLE ops.ad_manual_configuration_verification (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    packet_id uuid NOT NULL,
    evidence_grade text NOT NULL,
    executor_user_id uuid NOT NULL,
    verifier_user_id uuid,
    observed_field_path text CONSTRAINT ad_manual_configuration_verificati_observed_field_path_not_null NOT NULL,
    observed_value text NOT NULL,
    observed_at timestamp with time zone NOT NULL,
    evidence_reference text CONSTRAINT ad_manual_configuration_verificatio_evidence_reference_not_null NOT NULL,
    conflict_state text NOT NULL,
    proves_configuration boolean CONSTRAINT ad_manual_configuration_verificat_proves_configuration_not_null NOT NULL,
    recorded_at timestamp with time zone NOT NULL,
    correlation_id text NOT NULL,
    configuration_observation_id uuid,
    independent_observation jsonb,
    CONSTRAINT ad_manual_configuration_verification_conflict_ck CHECK ((conflict_state = ANY (ARRAY['NONE'::text, 'CONFLICTED'::text, 'SUPERSEDED_BY_LATER_CHANGE'::text]))),
    CONSTRAINT ad_manual_configuration_verification_conflict_proof_ck CHECK (((conflict_state = 'NONE'::text) OR (NOT proves_configuration))),
    CONSTRAINT ad_manual_configuration_verification_correlation_ck CHECK (((length(btrim(correlation_id)) >= 1) AND (length(btrim(correlation_id)) <= 128))),
    CONSTRAINT ad_manual_configuration_verification_evidence_ck CHECK (((length(btrim(evidence_reference)) >= 1) AND (length(btrim(evidence_reference)) <= 512))),
    CONSTRAINT ad_manual_configuration_verification_field_ck CHECK (((length(btrim(observed_field_path)) >= 1) AND (length(btrim(observed_field_path)) <= 256))),
    CONSTRAINT ad_manual_configuration_verification_grade_ck CHECK ((evidence_grade = ANY (ARRAY['OFFICIAL_API_READBACK'::text, 'OFFICIAL_CONFIGURATION_EXPORT'::text, 'INDEPENDENT_MANUAL_VERIFICATION'::text, 'EXECUTOR_SELF_REPORT'::text, 'UNVERIFIED_MANUAL_EVIDENCE'::text]))),
    CONSTRAINT ad_manual_configuration_verification_independent_ck CHECK (((evidence_grade <> ALL (ARRAY['INDEPENDENT_MANUAL_VERIFICATION'::text, 'UNVERIFIED_MANUAL_EVIDENCE'::text])) OR ((verifier_user_id IS NOT NULL) AND (verifier_user_id <> executor_user_id)))),
    CONSTRAINT ad_manual_configuration_verification_proof_ck CHECK (((NOT proves_configuration) OR (evidence_grade = ANY (ARRAY['OFFICIAL_API_READBACK'::text, 'OFFICIAL_CONFIGURATION_EXPORT'::text, 'INDEPENDENT_MANUAL_VERIFICATION'::text])))),
    CONSTRAINT ad_manual_configuration_verification_self_report_ck CHECK (((evidence_grade <> 'EXECUTOR_SELF_REPORT'::text) OR ((verifier_user_id IS NULL) AND (NOT proves_configuration)))),
    CONSTRAINT ad_manual_configuration_verification_value_ck CHECK (((length(btrim(observed_value)) >= 1) AND (length(btrim(observed_value)) <= 512))),
    CONSTRAINT ad_manual_independent_observation_shape_ck CHECK (((independent_observation IS NULL) OR (jsonb_typeof(independent_observation) = 'object'::text)))
);

CREATE TABLE ops.ad_manual_execution_packet (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    case_id uuid NOT NULL,
    ad_native_object_id uuid NOT NULL,
    store_id uuid NOT NULL,
    platform_code text NOT NULL,
    affected_set_id uuid NOT NULL,
    affected_set_digest text NOT NULL,
    semantic_profile_id uuid NOT NULL,
    action_kind text NOT NULL,
    observed_configuration_id uuid NOT NULL,
    intended_state jsonb NOT NULL,
    reason text NOT NULL,
    evidence_reference text NOT NULL,
    guardrail_evaluation_id uuid,
    blocker_codes text[] DEFAULT '{}'::text[] NOT NULL,
    maker_user_id uuid NOT NULL,
    endorser_user_id uuid,
    approver_user_id uuid,
    bundle_id uuid,
    expected_impact jsonb NOT NULL,
    verification_plan jsonb NOT NULL,
    state text NOT NULL,
    issued_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    revoked_at timestamp with time zone,
    revoked_reason text,
    correlation_id text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    proposal_id uuid,
    manual_policy_id uuid,
    executor_user_id uuid,
    execution_started_at timestamp with time zone,
    reservation_id uuid,
    current_proof_id uuid,
    authority_snapshot jsonb,
    outcome_baseline_id uuid,
    CONSTRAINT ad_manual_execution_packet_action_ck CHECK ((action_kind = ANY (ARRAY['AD_BID_CHANGE'::text, 'AD_BUDGET_CHANGE'::text, 'AD_STATUS_CHANGE'::text]))),
    CONSTRAINT ad_manual_execution_packet_blockers_ck CHECK ((((cardinality(blocker_codes) >= 0) AND (cardinality(blocker_codes) <= 64)) AND (array_position(blocker_codes, NULL::text) IS NULL))),
    CONSTRAINT ad_manual_execution_packet_correlation_ck CHECK (((length(btrim(correlation_id)) >= 1) AND (length(btrim(correlation_id)) <= 128))),
    CONSTRAINT ad_manual_execution_packet_digest_ck CHECK ((affected_set_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT ad_manual_execution_packet_evidence_ck CHECK (((length(btrim(evidence_reference)) >= 1) AND (length(btrim(evidence_reference)) <= 512))),
    CONSTRAINT ad_manual_execution_packet_expiry_ck CHECK ((expires_at > issued_at)),
    CONSTRAINT ad_manual_execution_packet_json_ck CHECK (((jsonb_typeof(intended_state) = 'object'::text) AND (jsonb_typeof(expected_impact) = 'object'::text) AND (jsonb_typeof(verification_plan) = 'object'::text))),
    CONSTRAINT ad_manual_execution_packet_reason_ck CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 1024))),
    CONSTRAINT ad_manual_execution_packet_revoked_ck CHECK (((state = 'MANUAL_PACKET_REVOKED'::text) = ((revoked_at IS NOT NULL) AND (revoked_reason IS NOT NULL)))),
    CONSTRAINT ad_manual_execution_packet_revoked_reason_ck CHECK (((revoked_reason IS NULL) OR ((length(btrim(revoked_reason)) >= 1) AND (length(btrim(revoked_reason)) <= 512)))),
    CONSTRAINT ad_manual_execution_packet_separation_ck CHECK ((((endorser_user_id IS NULL) OR (endorser_user_id <> maker_user_id)) AND ((approver_user_id IS NULL) OR (approver_user_id <> maker_user_id)) AND ((approver_user_id IS NULL) OR (endorser_user_id IS NULL) OR (approver_user_id <> endorser_user_id)))),
    CONSTRAINT ad_manual_execution_packet_state_ck CHECK ((state = ANY (ARRAY['MANUAL_PACKET_DRAFT'::text, 'MANUAL_PACKET_ENDORSED'::text, 'MANUAL_PACKET_ISSUED'::text, 'MANUAL_EXECUTION_IN_PROGRESS'::text, 'MANUAL_PACKET_REVOKED'::text, 'ACTION_REPORTED_CONFIGURATION_UNVERIFIED'::text, 'MANUAL_CONFIGURATION_VERIFIED'::text, 'MANUAL_EXECUTION_UNCERTAIN'::text, 'MANUAL_PACKET_EXPIRED'::text]))),
    CONSTRAINT ad_manual_execution_packet_verification_ck CHECK ((verification_plan ? 'evidenceGrade'::text))
);

CREATE TABLE ops.ad_manual_proposal (
    id uuid NOT NULL,
