    CONSTRAINT ad_ordinary_promotion_check CHECK ((valid_until > valid_from)),
    CONSTRAINT ad_ordinary_promotion_evidence_present CHECK (((NULLIF(btrim(shadow_evidence_reference), ''::text) IS NOT NULL) AND (NULLIF(btrim(pilot_evidence_reference), ''::text) IS NOT NULL) AND (NULLIF(btrim(matured_outcome_reference), ''::text) IS NOT NULL) AND (NULLIF(btrim(rollback_evidence_reference), ''::text) IS NOT NULL) AND (NULLIF(btrim(owner_approval_reference), ''::text) IS NOT NULL))),
    CONSTRAINT ad_ordinary_promotion_material_envelope_amount_check CHECK ((material_envelope_amount > (0)::numeric)),
    CONSTRAINT ad_ordinary_promotion_status_check CHECK ((status = ANY (ARRAY['DRAFT'::text, 'ACTIVE'::text, 'REVOKED'::text])))
);

CREATE TABLE ops.ad_outcome_axes (
