    CONSTRAINT ad_outcome_axes_input_snapshot_check CHECK ((jsonb_typeof(input_snapshot) = 'object'::text))
);

CREATE TABLE ops.ad_outcome_baseline (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    candidate_id uuid,
    manual_proposal_id uuid,
    ad_native_object_id uuid NOT NULL,
    affected_set_id uuid NOT NULL,
    affected_set_digest text NOT NULL,
    product_variant_ids uuid[] NOT NULL,
    listing_variant_ids uuid[] NOT NULL,
    outcome_policy_id uuid NOT NULL,
    outcome_policy_version integer NOT NULL,
    case_calculation_id uuid NOT NULL,
    policy_version_digest text NOT NULL,
    prepared_at timestamp with time zone NOT NULL,
    valid_until timestamp with time zone NOT NULL,
    plan_snapshot jsonb NOT NULL,
    input_digest text NOT NULL,
    state text NOT NULL,
    blocker_codes text[] NOT NULL,
    CONSTRAINT ad_outcome_baseline_affected_set_digest_check CHECK ((affected_set_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT ad_outcome_baseline_check CHECK (((candidate_id IS NULL) <> (manual_proposal_id IS NULL))),
    CONSTRAINT ad_outcome_baseline_check1 CHECK ((prepared_at < valid_until)),
    CONSTRAINT ad_outcome_baseline_check2 CHECK (((state <> 'COMPLETE'::text) OR (cardinality(blocker_codes) = 0))),
    CONSTRAINT ad_outcome_baseline_input_digest_check CHECK ((input_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT ad_outcome_baseline_plan_snapshot_check CHECK ((jsonb_typeof(plan_snapshot) = 'object'::text)),
    CONSTRAINT ad_outcome_baseline_state_check CHECK ((state = ANY (ARRAY['COMPLETE'::text, 'INCOMPLETE'::text])))
);

