    observation_id uuid NOT NULL,
    baseline_sales numeric(18,4),
    observed_sales numeric(18,4),
    CONSTRAINT ad_outcome_critical_guard_guard_state_check CHECK ((guard_state = ANY (ARRAY['PASS'::text, 'REGRESSED'::text, 'UNKNOWN'::text, 'NOT_DUE'::text])))
);

CREATE TABLE ops.ad_outcome_critical_unit (
