);

CREATE TABLE ops.ad_outcome_observation (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    command_id uuid,
    ad_native_object_id uuid NOT NULL,
    affected_set_digest text NOT NULL,
    outcome_policy_id uuid NOT NULL,
    outcome_policy_version integer NOT NULL,
    outcome_stage text NOT NULL,
    window_starts_at timestamp with time zone NOT NULL,
    window_ends_at timestamp with time zone NOT NULL,
    baseline_metric_state text NOT NULL,
    baseline_metric_value numeric(20,6),
    observed_metric_state text NOT NULL,
    observed_metric_value numeric(20,6),
    observed_traffic_count bigint,
    settled_coverage_ratio numeric(6,5),
    verdict text NOT NULL,
    guard_state text NOT NULL,
    unresolved_reason_codes text[] DEFAULT '{}'::text[] NOT NULL,
    evaluated_at timestamp with time zone NOT NULL,
    input_digest text NOT NULL,
    correlation_id text NOT NULL,
    revision_no integer DEFAULT 1 NOT NULL,
    supersedes_observation_id uuid,
    adjustment_reason text,
    manual_packet_id uuid,
    CONSTRAINT ad_outcome_observation_adjustment_reason_ck CHECK (((adjustment_reason IS NULL) OR ((length(btrim(adjustment_reason)) >= 1) AND (length(btrim(adjustment_reason)) <= 512)))),
    CONSTRAINT ad_outcome_observation_correlation_ck CHECK (((length(btrim(correlation_id)) >= 1) AND (length(btrim(correlation_id)) <= 128))),
    CONSTRAINT ad_outcome_observation_coverage_ck CHECK (((settled_coverage_ratio IS NULL) OR ((settled_coverage_ratio >= (0)::numeric) AND (settled_coverage_ratio <= (1)::numeric)))),
    CONSTRAINT ad_outcome_observation_digest_ck CHECK (((affected_set_digest ~ '^[0-9a-f]{64}$'::text) AND (input_digest ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT ad_outcome_observation_first_revision_ck CHECK (((outcome_stage ~~ '%_REVISED'::text) OR (revision_no = 1))),
    CONSTRAINT ad_outcome_observation_guard_ck CHECK ((guard_state = ANY (ARRAY['SATISFIED'::text, 'SALES_TOO_RECENT'::text, 'COVERAGE_INSUFFICIENT'::text, 'NOT_APPLICABLE'::text]))),
    CONSTRAINT ad_outcome_observation_guard_stage_ck CHECK (((outcome_stage = ANY (ARRAY['OPERATIONAL'::text, 'OPERATIONAL_REVISED'::text])) = (guard_state = 'NOT_APPLICABLE'::text))),
    CONSTRAINT ad_outcome_observation_reason_presence_ck CHECK (((verdict = ANY (ARRAY['INDETERMINATE'::text, 'NOT_YET_EVALUABLE'::text])) = (cardinality(unresolved_reason_codes) >= 1))),
    CONSTRAINT ad_outcome_observation_reasons_ck CHECK ((((cardinality(unresolved_reason_codes) >= 0) AND (cardinality(unresolved_reason_codes) <= 32)) AND (array_position(unresolved_reason_codes, NULL::text) IS NULL))),
    CONSTRAINT ad_outcome_observation_revision_ck CHECK ((revision_no >= 1)),
    CONSTRAINT ad_outcome_observation_revision_shape_ck CHECK (((outcome_stage ~~ '%_REVISED'::text) = ((supersedes_observation_id IS NOT NULL) AND (revision_no > 1) AND (adjustment_reason IS NOT NULL)))),
    CONSTRAINT ad_outcome_observation_settled_guard_ck CHECK (((outcome_stage = ANY (ARRAY['OPERATIONAL'::text, 'OPERATIONAL_REVISED'::text])) OR (guard_state = 'SATISFIED'::text) OR (verdict = ANY (ARRAY['INDETERMINATE'::text, 'NOT_YET_EVALUABLE'::text, 'REGRESSED'::text])))),
    CONSTRAINT ad_outcome_observation_stage_ck CHECK ((outcome_stage = ANY (ARRAY['OPERATIONAL'::text, 'OPERATIONAL_REVISED'::text, 'RETAINED'::text, 'RETAINED_REVISED'::text, 'SETTLED'::text, 'SETTLED_REVISED'::text]))),
    CONSTRAINT ad_outcome_observation_traffic_ck CHECK (((observed_traffic_count IS NULL) OR (observed_traffic_count >= 0))),
    CONSTRAINT ad_outcome_observation_value_presence_ck CHECK ((((baseline_metric_state = 'AVAILABLE'::text) = (baseline_metric_value IS NOT NULL)) AND ((observed_metric_state = 'AVAILABLE'::text) = (observed_metric_value IS NOT NULL)))),
    CONSTRAINT ad_outcome_observation_value_states_ck CHECK (((baseline_metric_state = ANY (ARRAY['AVAILABLE'::text, 'NOT_AVAILABLE'::text, 'UNDEFINED'::text])) AND (observed_metric_state = ANY (ARRAY['AVAILABLE'::text, 'NOT_AVAILABLE'::text, 'UNDEFINED'::text])))),
    CONSTRAINT ad_outcome_observation_verdict_ck CHECK ((verdict = ANY (ARRAY['IMPROVED'::text, 'UNCHANGED'::text, 'REGRESSED'::text, 'INDETERMINATE'::text, 'NOT_YET_EVALUABLE'::text]))),
    CONSTRAINT ad_outcome_observation_window_ck CHECK ((window_ends_at > window_starts_at)),
    CONSTRAINT ad_outcome_one_action_anchor_ck CHECK (((command_id IS NULL) <> (manual_packet_id IS NULL)))
);

CREATE TABLE ops.ad_outcome_plan_grant (
    proof_digest text NOT NULL,
    baseline_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    payload_digest text NOT NULL,
    application_backend_pid integer NOT NULL,
    application_transaction_id bigint NOT NULL,
    issued_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    consumed_at timestamp with time zone,
    CONSTRAINT ad_outcome_plan_grant_payload_digest_check CHECK ((payload_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT ad_outcome_plan_grant_proof_digest_check CHECK ((proof_digest ~ '^[0-9a-f]{64}$'::text))
);

CREATE TABLE ops.ad_outcome_review_observation (
    task_id uuid NOT NULL,
    observation_id uuid NOT NULL,
    recorded_at timestamp with time zone NOT NULL
);

CREATE TABLE ops.ad_outcome_review_responsibility (
    task_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    case_id uuid NOT NULL,
    primary_task_id uuid NOT NULL,
    outcome_baseline_id uuid NOT NULL,
    action_id uuid NOT NULL,
    action_kind text NOT NULL,
    required_role_code text DEFAULT 'FINANCE_ANALYST'::text NOT NULL,
    first_observation_id uuid NOT NULL,
    first_raised_at timestamp with time zone NOT NULL,
    CONSTRAINT ad_outcome_review_responsibility_action_kind_check CHECK ((action_kind = ANY (ARRAY['COMMAND'::text, 'MANUAL_PACKET'::text]))),
    CONSTRAINT ad_outcome_review_responsibility_required_role_code_check CHECK ((required_role_code = 'FINANCE_ANALYST'::text)),
    CONSTRAINT ad_review_task_distinct_ck CHECK ((task_id <> primary_task_id))
);

CREATE TABLE ops.ad_outcome_stage_baseline (
    outcome_baseline_id uuid NOT NULL,
    stage text NOT NULL,
    window_hours integer NOT NULL,
    snapshot jsonb NOT NULL,
    CONSTRAINT ad_outcome_stage_baseline_snapshot_check CHECK ((jsonb_typeof(snapshot) = 'object'::text)),
    CONSTRAINT ad_outcome_stage_baseline_stage_check CHECK ((stage = ANY (ARRAY['OPERATIONAL'::text, 'RETAINED'::text, 'SETTLED'::text]))),
    CONSTRAINT ad_outcome_stage_baseline_window_hours_check CHECK ((window_hours > 0))
);

CREATE TABLE ops.ad_recalculation_due (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    ad_native_object_id uuid NOT NULL,
    trigger_class text NOT NULL,
    source_reference text NOT NULL,
    due_at timestamp with time zone NOT NULL,
    delivered_at timestamp with time zone
);

CREATE TABLE ops.ad_recalculation_request (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    ad_native_object_id uuid NOT NULL,
    trigger_class text NOT NULL,
    trigger_reference text NOT NULL,
    fact_accepted_at timestamp with time zone NOT NULL,
    requested_at timestamp with time zone NOT NULL,
    state text NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    leased_until timestamp with time zone,
    lease_owner text,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    failure_code text,
    correlation_id text NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    calculation_as_of timestamp with time zone,
    latest_fact_accepted_at timestamp with time zone,
    next_fact_accepted_at timestamp with time zone,
    CONSTRAINT ad_recalculation_request_attempt_ck CHECK ((attempt_count >= 0)),
    CONSTRAINT ad_recalculation_request_completion_ck CHECK (((state = ANY (ARRAY['COMPLETED'::text, 'FAILED'::text, 'ABANDONED'::text])) = (completed_at IS NOT NULL))),
    CONSTRAINT ad_recalculation_request_correlation_ck CHECK (((length(btrim(correlation_id)) >= 1) AND (length(btrim(correlation_id)) <= 128))),
    CONSTRAINT ad_recalculation_request_failure_ck CHECK (((state <> ALL (ARRAY['FAILED'::text, 'ABANDONED'::text])) OR (failure_code IS NOT NULL))),
    CONSTRAINT ad_recalculation_request_lease_ck CHECK ((num_nonnulls(lease_owner, leased_until) <> 1)),
    CONSTRAINT ad_recalculation_request_leased_ck CHECK (((state <> 'LEASED'::text) OR (lease_owner IS NOT NULL))),
    CONSTRAINT ad_recalculation_request_reference_ck CHECK (((length(btrim(trigger_reference)) >= 1) AND (length(btrim(trigger_reference)) <= 256))),
    CONSTRAINT ad_recalculation_request_state_ck CHECK ((state = ANY (ARRAY['PENDING'::text, 'LEASED'::text, 'COMPLETED'::text, 'FAILED'::text, 'ABANDONED'::text]))),
    CONSTRAINT ad_recalculation_request_trigger_ck CHECK ((trigger_class = ANY (ARRAY['AD_CONFIGURATION'::text, 'AD_SPEND_OR_TRAFFIC'::text, 'PROVIDER_ATTRIBUTION'::text, 'PRODUCT_MAPPING_OR_AFFECTED_SET'::text, 'SELLABILITY_OR_AVAILABILITY'::text, 'COMPANY_SALES_OR_RETURNS'::text, 'SETTLEMENT_OR_ADJUSTMENT'::text, 'COST_OR_FEE'::text, 'CONVERSION_OR_ALLOWABLE_CPA'::text, 'FRESHNESS_OR_QUALIFICATION_POLICY'::text, 'TARGET_OR_OUTCOME_POLICY'::text, 'PRIORITY_OR_SLO_POLICY'::text, 'LEASE_OR_EXPOSURE_POLICY'::text, 'POLICY_BUNDLE_LIFECYCLE'::text, 'EXCEPTION_HOLD_KILL_OR_QUARANTINE'::text, 'PROVIDER_READBACK_OR_UNKNOWN'::text, 'CRITICAL_SALES_OR_CONFOUNDER'::text, 'OUTCOME_MATURITY_OR_REGRESSION'::text, 'MANUAL_REQUEST'::text])))
);

CREATE TABLE ops.ad_reconciliation_run (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    as_of timestamp with time zone NOT NULL,
    state text NOT NULL,
    trigger_kind text NOT NULL,
    object_count integer DEFAULT 0 NOT NULL,
    changed_case_count integer DEFAULT 0 NOT NULL,
    repaired_count integer DEFAULT 0 NOT NULL,
    expired_exception_count integer DEFAULT 0 NOT NULL,
    expired_approval_count integer DEFAULT 0 NOT NULL,
    released_reservation_count integer DEFAULT 0 NOT NULL,
    failed_object_count integer DEFAULT 0 NOT NULL,
    last_ad_native_object_id uuid,
    failure_code text,
    started_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    correlation_id text NOT NULL,
    CONSTRAINT ad_reconciliation_run_completion_ck CHECK (((state = ANY (ARRAY['COMPLETED'::text, 'FAILED'::text])) = (completed_at IS NOT NULL))),
    CONSTRAINT ad_reconciliation_run_correlation_ck CHECK (((length(btrim(correlation_id)) >= 1) AND (length(btrim(correlation_id)) <= 128))),
    CONSTRAINT ad_reconciliation_run_counts_ck CHECK (((object_count >= 0) AND (changed_case_count >= 0) AND (repaired_count >= 0) AND (expired_exception_count >= 0) AND (expired_approval_count >= 0) AND (released_reservation_count >= 0) AND (failed_object_count >= 0))),
    CONSTRAINT ad_reconciliation_run_failure_ck CHECK (((state <> 'FAILED'::text) OR (failure_code IS NOT NULL))),
    CONSTRAINT ad_reconciliation_run_state_ck CHECK ((state = ANY (ARRAY['RUNNING'::text, 'COMPLETED'::text, 'FAILED'::text]))),
    CONSTRAINT ad_reconciliation_run_trigger_ck CHECK ((trigger_kind = ANY (ARRAY['SCHEDULED'::text, 'MANUAL'::text, 'RECOVERY'::text])))
);

CREATE TABLE ops.ad_reservation_state_history (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    reservation_id uuid NOT NULL,
    old_state jsonb NOT NULL,
    new_state jsonb NOT NULL,
    recorded_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL
);

CREATE TABLE ops.ad_slo_observation (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    ad_native_object_id uuid NOT NULL,
    case_id uuid,
    lane text NOT NULL,
    path_kind text NOT NULL,
    source_event_time timestamp with time zone,
    source_updated_at timestamp with time zone,
    ingested_at timestamp with time zone,
    fact_accepted_at timestamp with time zone NOT NULL,
    calculated_at timestamp with time zone NOT NULL,
    case_updated_at timestamp with time zone,
    internal_latency_ms bigint,
    source_latency_ms bigint,
    breached boolean NOT NULL,
    correlation_id text NOT NULL,
    clock_state text DEFAULT 'VALID'::text NOT NULL,
    CONSTRAINT ad_slo_clock_evidence_ck CHECK ((((clock_state = 'VALID'::text) AND (calculated_at >= fact_accepted_at) AND (internal_latency_ms >= 0)) OR ((clock_state = 'CLOCK_INCONSISTENT'::text) AND (calculated_at < fact_accepted_at) AND (internal_latency_ms IS NULL)))),
    CONSTRAINT ad_slo_observation_clock_state_check CHECK ((clock_state = ANY (ARRAY['VALID'::text, 'CLOCK_INCONSISTENT'::text]))),
    CONSTRAINT ad_slo_observation_correlation_ck CHECK (((length(btrim(correlation_id)) >= 1) AND (length(btrim(correlation_id)) <= 128))),
    CONSTRAINT ad_slo_observation_lane_ck CHECK ((lane = ANY (ARRAY['PROTECTION'::text, 'DATA_REPAIR'::text, 'OPTIMIZATION'::text, 'WATCH'::text]))),
    CONSTRAINT ad_slo_observation_path_ck CHECK ((path_kind = ANY (ARRAY['TARGETED'::text, 'RECONCILIATION'::text]))),
    CONSTRAINT ad_slo_observation_source_ck CHECK (((source_latency_ms IS NULL) OR (source_latency_ms >= 0)))
);

CREATE TABLE ops.ad_trace_event (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    ad_native_object_id uuid,
    path_kind text NOT NULL,
    stage_code text NOT NULL,
    status text NOT NULL,
    correlation_id text NOT NULL,
    parent_correlation_id text,
    subject_reference text,
    detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    occurred_at timestamp with time zone NOT NULL,
    CONSTRAINT ad_trace_event_correlation_ck CHECK (((length(btrim(correlation_id)) >= 1) AND (length(btrim(correlation_id)) <= 128))),
    CONSTRAINT ad_trace_event_detail_ck CHECK ((jsonb_typeof(detail) = 'object'::text)),
    CONSTRAINT ad_trace_event_parent_ck CHECK (((parent_correlation_id IS NULL) OR ((length(btrim(parent_correlation_id)) >= 1) AND (length(btrim(parent_correlation_id)) <= 128)))),
    CONSTRAINT ad_trace_event_path_ck CHECK ((path_kind = ANY (ARRAY['TARGETED'::text, 'RECONCILIATION'::text, 'OPERATIONS'::text]))),
    CONSTRAINT ad_trace_event_stage_ck CHECK ((stage_code = ANY (ARRAY['TARGET_DEDUP_QUEUED'::text, 'TARGET_DEDUP_COALESCED'::text, 'TARGET_DEDUP_SUPPRESSED'::text, 'CALCULATION_STARTED'::text, 'EVIDENCE_AND_LANE_CALCULATED'::text, 'PROJECTION_WRITTEN'::text, 'CASE_SYNCHRONIZED'::text, 'AUTO_VERIFICATION'::text, 'SLO_RECORDED'::text, 'SWEEP_STARTED'::text, 'SWEEP_COMPLETED'::text, 'SWEEP_FAILED'::text, 'BACKLOG_SNAPSHOT'::text, 'EXCEPTION_EXPIRY_REVALIDATION'::text, 'APPROVAL_EXPIRY_SWEEP'::text, 'RESERVATION_RELEASE_SWEEP'::text, 'OUTCOME_MATURITY_SWEEP'::text, 'FACT_ACCEPTED'::text]))),
    CONSTRAINT ad_trace_event_status_ck CHECK ((status = ANY (ARRAY['STARTED'::text, 'COMPLETED'::text, 'SUPPRESSED'::text, 'FAILED'::text, 'OBSERVED'::text]))),
    CONSTRAINT ad_trace_event_subject_ck CHECK (((subject_reference IS NULL) OR ((length(btrim(subject_reference)) >= 1) AND (length(btrim(subject_reference)) <= 256))))
);

CREATE TABLE ops.ai_claim_evidence (
    id uuid NOT NULL,
    claim_id uuid NOT NULL,
    metric_value_id uuid,
    finding_id uuid,
    CONSTRAINT ai_claim_evidence_one_target_ck CHECK ((num_nonnulls(metric_value_id, finding_id) = 1))
);

CREATE TABLE ops.ai_invocation (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    projection_code text NOT NULL,
    projection_version integer NOT NULL,
    prompt_template_code text NOT NULL,
    prompt_version integer NOT NULL,
    output_schema_version integer DEFAULT 2 NOT NULL,
    model_id uuid,
    subject_kind text NOT NULL,
    subject_id uuid NOT NULL,
    window_code text NOT NULL,
    request_digest text NOT NULL,
    state text NOT NULL,
    failure_code text,
    degraded boolean NOT NULL,
    requested_by_user_id uuid,
    started_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    execution_deadline_at timestamp with time zone DEFAULT (clock_timestamp() + '00:02:00'::interval) NOT NULL,
    latency_ms integer,
    correlation_id text NOT NULL,
    CONSTRAINT ai_invocation_completion_ck CHECK (((state = ANY (ARRAY['PREPARED'::text, 'DISPATCHED'::text])) = (completed_at IS NULL))),
    CONSTRAINT ai_invocation_digest_ck CHECK ((request_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT ai_invocation_failure_ck CHECK (((state <> ALL (ARRAY['OUTPUT_REJECTED'::text, 'PARTIAL_OUTPUT_REJECTED'::text, 'PROVIDER_FAILED'::text, 'PROVIDER_OUTCOME_UNKNOWN'::text, 'REFUSED'::text])) OR (failure_code IS NOT NULL))),
    CONSTRAINT ai_invocation_latency_ck CHECK (((latency_ms IS NULL) OR (latency_ms >= 0))),
    CONSTRAINT ai_invocation_model_presence_ck CHECK (
CASE
    WHEN (state = ANY (ARRAY['PREPARED'::text, 'REFUSED'::text])) THEN (model_id IS NULL)
    ELSE (model_id IS NOT NULL)
END),
    CONSTRAINT ai_invocation_output_schema_version_check CHECK ((output_schema_version = 2)),
    CONSTRAINT ai_invocation_state_ck CHECK ((state = ANY (ARRAY['PREPARED'::text, 'DISPATCHED'::text, 'SUCCEEDED'::text, 'OUTPUT_REJECTED'::text, 'PARTIAL_OUTPUT_REJECTED'::text, 'PROVIDER_FAILED'::text, 'PROVIDER_OUTCOME_UNKNOWN'::text, 'REFUSED'::text]))),
    CONSTRAINT ai_invocation_subject_ck CHECK ((subject_kind = ANY (ARRAY['PRODUCT_VARIANT'::text, 'PLATFORM_LISTING_VARIANT'::text, 'STORE'::text, 'PLATFORM_LISTING'::text]))),
    CONSTRAINT ai_invocation_window_ck CHECK ((window_code = ANY (ARRAY['D7'::text, 'D14'::text, 'D30'::text])))
);

CREATE TABLE ops.ai_listing_invocation_scope (
    invocation_id uuid NOT NULL,
    store_id uuid NOT NULL,
    listing_variant_ids uuid[] NOT NULL,
    product_variant_ids uuid[] NOT NULL,
    CONSTRAINT ai_listing_invocation_scope_listing_variant_ids_check CHECK (((cardinality(listing_variant_ids) > 0) AND (array_position(listing_variant_ids, NULL::uuid) IS NULL))),
    CONSTRAINT ai_listing_invocation_scope_product_variant_ids_check CHECK (((cardinality(product_variant_ids) > 0) AND (array_position(product_variant_ids, NULL::uuid) IS NULL)))
);

CREATE TABLE ops.ai_model (
    id uuid NOT NULL,
    provider_id uuid NOT NULL,
    model_code text NOT NULL,
    display_name text NOT NULL,
    secret_reference text NOT NULL,
    max_context_tokens integer,
    status text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT ai_model_code_ck CHECK ((model_code ~ '^[a-z0-9]([a-z0-9._-]{0,61}[a-z0-9])?$'::text)),
    CONSTRAINT ai_model_context_ck CHECK (((max_context_tokens IS NULL) OR (max_context_tokens > 0))),
    CONSTRAINT ai_model_secret_reference_ck CHECK ((secret_reference ~ '^secret-ref://[a-z0-9][a-z0-9-]{0,62}(/[a-z0-9][a-z0-9._-]{0,62}){1,4}$'::text)),
    CONSTRAINT ai_model_status_ck CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'RETIRED'::text])))
);

CREATE TABLE ops.ai_output_claim (
    id uuid NOT NULL,
    invocation_id uuid NOT NULL,
    ordinal integer NOT NULL,
    claim_kind text NOT NULL,
    statement text NOT NULL,
    payload jsonb NOT NULL,
    confidence_label text,
    validation_state text NOT NULL,
    rejection_code text,
    CONSTRAINT ai_output_claim_confidence_ck CHECK (((confidence_label IS NULL) OR (confidence_label = ANY (ARRAY['LOW'::text, 'MEDIUM'::text, 'HIGH'::text])))),
    CONSTRAINT ai_output_claim_kind_ck CHECK ((claim_kind = ANY (ARRAY['FACT'::text, 'INFERENCE'::text, 'RECOMMENDATION'::text, 'UNKNOWN'::text]))),
    CONSTRAINT ai_output_claim_ordinal_ck CHECK ((ordinal > 0)),
    CONSTRAINT ai_output_claim_payload_ck CHECK ((jsonb_typeof(payload) = 'object'::text)),
    CONSTRAINT ai_output_claim_rejection_ck CHECK (((validation_state = 'REJECTED'::text) = (rejection_code IS NOT NULL))),
    CONSTRAINT ai_output_claim_rejection_values_ck CHECK (((rejection_code IS NULL) OR (rejection_code = ANY (ARRAY['SCHEMA_INVALID'::text, 'UNKNOWN_FIELD'::text, 'EVIDENCE_REFERENCE_UNRESOLVED'::text, 'EVIDENCE_REFERENCE_MISSING'::text, 'METRIC_NOT_RECOGNISED'::text, 'DERIVED_CALCULATION_NOT_PRODUCTIZED'::text, 'CAPABILITY_NOT_RECOGNISED'::text, 'STATEMENT_TOO_LONG'::text, 'INSTRUCTION_LIKE_CONTENT'::text, 'SECRET_LIKE_CONTENT'::text, 'LISTING_ASSISTANCE_ACTION_OUT_OF_SCOPE'::text])))),
    CONSTRAINT ai_output_claim_statement_ck CHECK (((length(btrim(statement)) >= 1) AND (length(btrim(statement)) <= 2000))),
    CONSTRAINT ai_output_claim_validation_ck CHECK ((validation_state = ANY (ARRAY['ACCEPTED'::text, 'REJECTED'::text])))
);

CREATE TABLE ops.ai_projection_definition (
    projection_code text NOT NULL,
    projection_version integer NOT NULL,
    purpose text NOT NULL,
    retention_policy text NOT NULL,
    owner_label text NOT NULL,
    status text NOT NULL,
    CONSTRAINT ai_projection_definition_code_ck CHECK ((projection_code ~ '^[A-Z][A-Z0-9_]{1,62}$'::text)),
    CONSTRAINT ai_projection_definition_retention_ck CHECK ((retention_policy = ANY (ARRAY['NO_PROVIDER_RETENTION'::text, 'PROVIDER_RETENTION_AGREED'::text]))),
    CONSTRAINT ai_projection_definition_status_ck CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'RETIRED'::text]))),
    CONSTRAINT ai_projection_definition_version_ck CHECK ((projection_version > 0))
);

CREATE TABLE ops.ai_projection_field (
    projection_code text NOT NULL,
    projection_version integer NOT NULL,
    field_path text NOT NULL,
    data_classification text NOT NULL,
    CONSTRAINT ai_projection_field_classification_ck CHECK ((data_classification = ANY (ARRAY['OPAQUE_IDENTIFIER'::text, 'CANONICAL_METRIC'::text, 'DETERMINISTIC_FINDING'::text, 'OPERATING_ATTRIBUTE'::text]))),
    CONSTRAINT ai_projection_field_path_ck CHECK ((field_path ~ '^[a-z][a-zA-Z0-9]*(\.[a-z][a-zA-Z0-9]*)*$'::text))
);

CREATE TABLE ops.ai_provider (
    id uuid NOT NULL,
    provider_code text NOT NULL,
    display_name text NOT NULL,
    service_region_label text,
    invocation_url text,
    request_template text,
    response_pointer text,
    auth_header_name text,
    auth_value_template text,
    request_timeout_ms integer DEFAULT 60000 NOT NULL,
    eligibility_state text NOT NULL,
    last_verified_at timestamp with time zone,
    evidence_ref text,
    verified_source_title text,
    owner_label text NOT NULL,
    status text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT ai_provider_active_readiness_ck CHECK (((status <> 'ACTIVE'::text) OR ((eligibility_state = 'VERIFIED'::text) AND (invocation_url IS NOT NULL) AND (request_template IS NOT NULL) AND (response_pointer IS NOT NULL) AND (auth_header_name IS NOT NULL) AND (auth_value_template IS NOT NULL)))),
    CONSTRAINT ai_provider_auth_header_ck CHECK (((auth_header_name IS NULL) OR (auth_header_name ~ '^[A-Za-z][A-Za-z0-9-]{0,63}$'::text))),
    CONSTRAINT ai_provider_auth_template_ck CHECK (((auth_value_template IS NULL) OR (auth_value_template ~ '^[!-~ ]{0,32}\{value\}[!-~ ]{0,32}$'::text))),
    CONSTRAINT ai_provider_code_ck CHECK ((provider_code ~ '^[a-z0-9]([a-z0-9._-]{0,61}[a-z0-9])?$'::text)),
    CONSTRAINT ai_provider_eligibility_ck CHECK ((eligibility_state = ANY (ARRAY['UNKNOWN'::text, 'UNVERIFIED'::text, 'VERIFIED'::text]))),
    CONSTRAINT ai_provider_invocation_url_ck CHECK (((invocation_url IS NULL) OR (invocation_url ~ '^https://[a-z0-9][a-z0-9.-]{0,252}(:[0-9]{2,5})?(/[A-Za-z0-9._~-]{1,64}){0,8}$'::text))),
    CONSTRAINT ai_provider_provenance_ck CHECK (((eligibility_state <> 'VERIFIED'::text) OR ((last_verified_at IS NOT NULL) AND (evidence_ref IS NOT NULL) AND (verified_source_title IS NOT NULL)))),
    CONSTRAINT ai_provider_response_pointer_ck CHECK (((response_pointer IS NULL) OR (response_pointer ~ '^(/[^/~]*(~[01][^/~]*)*)+$'::text))),
    CONSTRAINT ai_provider_status_ck CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'RETIRED'::text]))),
    CONSTRAINT ai_provider_timeout_ck CHECK (((request_timeout_ms >= 1000) AND (request_timeout_ms <= 300000)))
);

CREATE TABLE ops.approval_decision (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    recommendation_id uuid NOT NULL,
    decision text NOT NULL,
    decided_by_user_id uuid,
    policy_authorization_id uuid,
    authenticated_at timestamp with time zone,
    step_up_satisfied boolean NOT NULL,
    entity_version_digest text NOT NULL,
    scope_expires_at timestamp with time zone NOT NULL,
    reason text NOT NULL,
    decided_at timestamp with time zone NOT NULL,
    correlation_id text NOT NULL,
    authority_snapshot jsonb NOT NULL,
    CONSTRAINT approval_decision_actor_ck CHECK ((((decision = ANY (ARRAY['APPROVED'::text, 'REJECTED'::text])) AND (decided_by_user_id IS NOT NULL) AND (policy_authorization_id IS NULL)) OR ((decision = 'POLICY_AUTHORIZED'::text) AND (policy_authorization_id IS NOT NULL) AND (decided_by_user_id IS NULL)))),
    CONSTRAINT approval_decision_decision_ck CHECK ((decision = ANY (ARRAY['APPROVED'::text, 'REJECTED'::text, 'POLICY_AUTHORIZED'::text]))),
    CONSTRAINT approval_decision_digest_ck CHECK ((entity_version_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT approval_decision_scope_ck CHECK ((scope_expires_at > decided_at)),
    CONSTRAINT approval_decision_step_up_ck CHECK (((step_up_satisfied = false) OR (authenticated_at IS NOT NULL)))
);

CREATE TABLE ops.authorization_decision_evidence (
    id uuid NOT NULL,
    job_id uuid NOT NULL,
    service_account_id uuid NOT NULL,
    marketplace_account_id uuid NOT NULL,
    scope_grant_id uuid NOT NULL,
    credential_id uuid NOT NULL,
    evaluated_at timestamp with time zone NOT NULL,
    granted_at timestamp with time zone NOT NULL,
    control_epoch_scopes text[] NOT NULL,
    control_epoch_values bigint[] NOT NULL,
    control_snapshot_valid_until timestamp with time zone CONSTRAINT authorization_decision_evid_control_snapshot_valid_unt_not_null NOT NULL,
    boundary_kind_count integer NOT NULL,
    boundary_kind_set text[] NOT NULL,
    boundary_set_digest text NOT NULL,
    winning_boundary_kind text NOT NULL,
    call_authority_expires_at timestamp with time zone CONSTRAINT authorization_decision_evide_call_authority_expires_at_not_null NOT NULL,
    correlation_id text NOT NULL,
    run_id uuid NOT NULL,
    fence_token bigint NOT NULL,
    lease_owner text NOT NULL,
    platform_code text NOT NULL,
    endpoint_id uuid NOT NULL,
    call_seq integer NOT NULL,
    run_lease_expires_at timestamp with time zone NOT NULL,
    server_policy_deadline timestamp with time zone NOT NULL,
    CONSTRAINT auth_decision_evidence_authority_within_server_policy_ck CHECK ((call_authority_expires_at <= server_policy_deadline)),
    CONSTRAINT authorization_decision_evidence_authority_after_grant_ck CHECK ((call_authority_expires_at > granted_at)),
    CONSTRAINT authorization_decision_evidence_authority_capped_ck CHECK ((call_authority_expires_at <= control_snapshot_valid_until)),
    CONSTRAINT authorization_decision_evidence_authority_within_lease_ck CHECK ((call_authority_expires_at <= run_lease_expires_at)),
    CONSTRAINT authorization_decision_evidence_boundary_pairing_ck CHECK ((cardinality(boundary_kind_set) = boundary_kind_count)),
    CONSTRAINT authorization_decision_evidence_call_seq_ck CHECK ((call_seq > 0)),
    CONSTRAINT authorization_decision_evidence_digest_ck CHECK ((boundary_set_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT authorization_decision_evidence_epoch_count_ck CHECK ((cardinality(control_epoch_scopes) = 4)),
    CONSTRAINT authorization_decision_evidence_epoch_pairing_ck CHECK ((cardinality(control_epoch_scopes) = cardinality(control_epoch_values))),
    CONSTRAINT authorization_decision_evidence_fence_ck CHECK ((fence_token > 0)),
    CONSTRAINT authorization_decision_evidence_grant_before_boundary_ck CHECK ((granted_at < control_snapshot_valid_until)),
    CONSTRAINT authorization_decision_evidence_lease_after_grant_ck CHECK ((run_lease_expires_at > granted_at)),
    CONSTRAINT authorization_decision_evidence_order_ck CHECK ((evaluated_at <= granted_at)),
    CONSTRAINT authorization_decision_evidence_owner_ck CHECK ((length(btrim(lease_owner)) > 0)),
    CONSTRAINT authorization_decision_evidence_server_policy_after_grant_ck CHECK ((server_policy_deadline > granted_at))
);

CREATE TABLE ops.availability_accepted_exception (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    case_id uuid NOT NULL,
    child_id uuid NOT NULL,
    cause_code text NOT NULL,
    scope_kind text NOT NULL,
    scope_reference text NOT NULL,
    reason_code text NOT NULL,
    rationale text NOT NULL,
    expected_consequence text NOT NULL,
    consequence_amount numeric(18,4),
    consequence_currency text,
    evidence_reference text NOT NULL,
    requested_by_user_id uuid NOT NULL,
    requested_at timestamp with time zone NOT NULL,
    decision_owner_role_code text CONSTRAINT availability_accepted_excepti_decision_owner_role_code_not_null NOT NULL,
    required_authority_level text CONSTRAINT availability_accepted_excepti_required_authority_level_not_null NOT NULL,
    state text NOT NULL,
    effective_from timestamp with time zone,
    expires_at timestamp with time zone,
    review_at timestamp with time zone,
    invalidated_at timestamp with time zone,
    invalidation_reason text,
    materiality_policy_id uuid,
    policy_version integer,
    occurrence_count integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    accepted_risk_digest text,
    accepted_severity text,
    accepted_profit_at_risk_amount numeric(19,4),
    accepted_profit_at_risk_currency character(3),
    accepted_case_reopen_count integer,
    CONSTRAINT availability_accepted_exception_accepted_profit_ck CHECK (((accepted_profit_at_risk_amount IS NULL) = (accepted_profit_at_risk_currency IS NULL))),
    CONSTRAINT availability_accepted_exception_accepted_reopen_ck CHECK (((accepted_case_reopen_count IS NULL) OR (accepted_case_reopen_count >= 0))),
    CONSTRAINT availability_accepted_exception_accepted_severity_ck CHECK (((accepted_severity IS NULL) OR (accepted_severity = ANY (ARRAY['WATCH'::text, 'HIGH'::text, 'CRITICAL'::text, 'REVIEW'::text, 'UNRESOLVED'::text])))),
    CONSTRAINT availability_accepted_exception_active_ck CHECK (((state <> 'ACTIVE'::text) OR ((effective_from IS NOT NULL) AND (expires_at IS NOT NULL) AND (review_at IS NOT NULL) AND (expires_at > effective_from) AND (materiality_policy_id IS NOT NULL) AND (policy_version IS NOT NULL)))),
    CONSTRAINT availability_accepted_exception_amount_ck CHECK (((consequence_amount IS NULL) = (consequence_currency IS NULL))),
    CONSTRAINT availability_accepted_exception_authority_ck CHECK ((required_authority_level = ANY (ARRAY['DOMAIN_LEAD'::text, 'OPS_LEAD'::text, 'RISK_AUTHORITY'::text]))),
    CONSTRAINT availability_accepted_exception_cause_ck CHECK ((cause_code ~ '^[A-Z][A-Z0-9_]{1,62}$'::text)),
    CONSTRAINT availability_accepted_exception_consequence_ck CHECK (((length(btrim(expected_consequence)) >= 1) AND (length(btrim(expected_consequence)) <= 2048))),
    CONSTRAINT availability_accepted_exception_currency_ck CHECK (((consequence_currency IS NULL) OR (consequence_currency ~ '^[A-Z]{3}$'::text))),
    CONSTRAINT availability_accepted_exception_evidence_ck CHECK (((length(btrim(evidence_reference)) >= 1) AND (length(btrim(evidence_reference)) <= 512))),
    CONSTRAINT availability_accepted_exception_invalidation_ck CHECK (((state = ANY (ARRAY['INVALIDATED'::text, 'EXPIRED'::text])) = ((invalidated_at IS NOT NULL) AND (invalidation_reason IS NOT NULL)))),
    CONSTRAINT availability_accepted_exception_occurrence_ck CHECK ((occurrence_count >= 1)),
    CONSTRAINT availability_accepted_exception_rationale_ck CHECK (((length(btrim(rationale)) >= 1) AND (length(btrim(rationale)) <= 2048))),
    CONSTRAINT availability_accepted_exception_reason_code_ck CHECK ((reason_code = ANY (ARRAY['PLANNED_DISCONTINUATION'::text, 'SEASONAL_PAUSE'::text, 'SUPPLIER_OUTAGE_ACCEPTED'::text, 'COMMERCIALLY_IMMATERIAL'::text, 'ALTERNATIVE_SUPPLY_ARRANGED'::text, 'KNOWN_DATA_LIMITATION_ACCEPTED'::text]))),
    CONSTRAINT availability_accepted_exception_risk_digest_ck CHECK (((accepted_risk_digest IS NULL) OR (accepted_risk_digest ~ '^[0-9a-f]{32}$'::text))),
    CONSTRAINT availability_accepted_exception_scope_ck CHECK ((scope_kind = ANY (ARRAY['CHILD'::text, 'VARIANT'::text, 'STORE'::text, 'CHANNEL'::text]))),
    CONSTRAINT availability_accepted_exception_scope_reference_ck CHECK (((length(btrim(scope_reference)) >= 1) AND (length(btrim(scope_reference)) <= 256))),
    CONSTRAINT availability_accepted_exception_state_ck CHECK ((state = ANY (ARRAY['REQUESTED'::text, 'AUTHORITY_BLOCKED'::text, 'ACTIVE'::text, 'REJECTED'::text, 'EXPIRED'::text, 'INVALIDATED'::text, 'WITHDRAWN'::text])))
);

CREATE TABLE ops.availability_case (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    card_id uuid NOT NULL,
    child_id uuid NOT NULL,
    cause_code text NOT NULL,
    cause_key text NOT NULL,
    child_kind text NOT NULL,
    severity text NOT NULL,
    state text NOT NULL,
    accountable_role_code text NOT NULL,
    assignee_user_id uuid,
    action_due_at timestamp with time zone NOT NULL,
    outcome_due_at timestamp with time zone,
    action_recorded_at timestamp with time zone,
    verification_started_at timestamp with time zone,
    verified_at timestamp with time zone,
    closed_at timestamp with time zone,
    closure_reason text,
    reopen_count integer DEFAULT 0 NOT NULL,
    escalation_level integer DEFAULT 0 NOT NULL,
    activation_policy_id uuid NOT NULL,
    first_activated_at timestamp with time zone NOT NULL,
    last_evidence_at timestamp with time zone NOT NULL,
    correlation_id text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    improvement_first_seen_at timestamp with time zone,
    original_action_due_at timestamp with time zone NOT NULL,
    action_sla_paused_at timestamp with time zone,
    action_sla_remaining_ms bigint,
    CONSTRAINT availability_case_action_ck CHECK (((state <> ALL (ARRAY['ACTION_RECORDED'::text, 'VERIFYING'::text, 'VERIFIED_SUCCESS'::text])) OR (action_recorded_at IS NOT NULL))),
    CONSTRAINT availability_case_action_sla_pause_shape_ck CHECK (((state = 'ACCEPTED_RISK'::text) = ((action_sla_paused_at IS NOT NULL) AND (action_sla_remaining_ms IS NOT NULL)))),
    CONSTRAINT availability_case_action_sla_remaining_ck CHECK (((action_sla_remaining_ms IS NULL) OR (action_sla_remaining_ms >= 0))),
    CONSTRAINT availability_case_assignment_ck CHECK (((state <> ALL (ARRAY['ASSIGNED'::text, 'IN_PROGRESS'::text])) OR (assignee_user_id IS NOT NULL))),
    CONSTRAINT availability_case_cause_ck CHECK ((cause_code ~ '^[A-Z][A-Z0-9_]{1,62}$'::text)),
    CONSTRAINT availability_case_cause_key_ck CHECK (((length(btrim(cause_key)) >= 1) AND (length(btrim(cause_key)) <= 256))),
    CONSTRAINT availability_case_closure_ck CHECK (((state = ANY (ARRAY['VERIFIED_SUCCESS'::text, 'CANCELLED'::text])) = ((closed_at IS NOT NULL) AND (closure_reason IS NOT NULL)))),
    CONSTRAINT availability_case_correlation_ck CHECK (((length(btrim(correlation_id)) >= 1) AND (length(btrim(correlation_id)) <= 128))),
    CONSTRAINT availability_case_escalation_ck CHECK (((escalation_level >= 0) AND (escalation_level <= 3))),
    CONSTRAINT availability_case_improvement_ck CHECK (((improvement_first_seen_at IS NULL) OR (action_recorded_at IS NOT NULL))),
    CONSTRAINT availability_case_kind_ck CHECK ((child_kind = ANY (ARRAY['CHANNEL'::text, 'COMPANY'::text]))),
    CONSTRAINT availability_case_reopen_ck CHECK (((reopen_count >= 0) AND (reopen_count <= 10000))),
    CONSTRAINT availability_case_severity_ck CHECK ((severity = ANY (ARRAY['WATCH'::text, 'HIGH'::text, 'CRITICAL'::text, 'REVIEW'::text, 'UNRESOLVED'::text]))),
    CONSTRAINT availability_case_state_ck CHECK ((state = ANY (ARRAY['OPEN'::text, 'ASSIGNED'::text, 'IN_PROGRESS'::text, 'ACTION_RECORDED'::text, 'VERIFYING'::text, 'VERIFIED_SUCCESS'::text, 'REOPENED'::text, 'ESCALATED'::text, 'REWORK_REQUIRED'::text, 'ACCEPTED_RISK'::text, 'CANCELLED'::text]))),
    CONSTRAINT availability_case_verification_ck CHECK (((state = 'VERIFIED_SUCCESS'::text) = (verified_at IS NOT NULL)))
);

CREATE TABLE ops.availability_case_event (
    id uuid NOT NULL,
    case_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    sequence_no integer NOT NULL,
    event_kind text NOT NULL,
    from_state text,
    to_state text,
    action_kind text,
    action_evidence jsonb,
    verification_kind text,
    verification_outcome text,
    actor_user_id uuid,
    actor_role_code text,
    reason text NOT NULL,
    evidence_reference text,
    observed_at timestamp with time zone,
    occurred_at timestamp with time zone NOT NULL,
    correlation_id text NOT NULL,
    CONSTRAINT availability_case_event_action_kind_ck CHECK (((action_kind IS NULL) OR (action_kind = ANY (ARRAY['INBOUND_EVIDENCE_BOUND'::text, 'CHANNEL_RESTORATION_REFERENCE'::text, 'DATA_OR_MAPPING_REPAIR'::text, 'POLICY_VERSION_PUBLISHED'::text, 'QUALITY_DISPOSITION_RECORDED'::text, 'OWNERSHIP_DECLARATION_PUBLISHED'::text])))),
    CONSTRAINT availability_case_event_action_shape_ck CHECK (((event_kind <> 'ACTION_RECORDED'::text) OR ((action_kind IS NOT NULL) AND (action_evidence IS NOT NULL) AND (jsonb_typeof(action_evidence) = 'object'::text) AND (action_evidence ? 'reference'::text) AND (evidence_reference IS NOT NULL) AND (actor_user_id IS NOT NULL)))),
    CONSTRAINT availability_case_event_correlation_ck CHECK (((length(btrim(correlation_id)) >= 1) AND (length(btrim(correlation_id)) <= 128))),
    CONSTRAINT availability_case_event_evidence_ck CHECK (((evidence_reference IS NULL) OR ((length(btrim(evidence_reference)) >= 1) AND (length(btrim(evidence_reference)) <= 512)))),
    CONSTRAINT availability_case_event_kind_ck CHECK ((event_kind = ANY (ARRAY['ACTIVATED'::text, 'EVIDENCE_APPENDED'::text, 'ASSIGNED'::text, 'SEVERITY_CHANGED'::text, 'ACTION_RECORDED'::text, 'VERIFICATION_STARTED'::text, 'VERIFICATION_OBSERVED'::text, 'VERIFIED_SUCCESS'::text, 'REOPENED'::text, 'ESCALATED'::text, 'REWORK_REQUIRED'::text, 'EXCEPTION_APPLIED'::text, 'EXCEPTION_INVALIDATED'::text, 'CANCELLED'::text]))),
    CONSTRAINT availability_case_event_reason_ck CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 1024))),
    CONSTRAINT availability_case_event_sequence_ck CHECK ((sequence_no >= 1)),
    CONSTRAINT availability_case_event_verification_kind_ck CHECK (((verification_kind IS NULL) OR (verification_kind = ANY (ARRAY['COMPANY_RISK_BELOW_THRESHOLD'::text, 'CHANNEL_FRESH_AND_SELLABLE'::text, 'SOURCE_RECOVERED'::text, 'UNIQUE_POLICY_RESOLVED'::text, 'QUALITY_DISPOSITION_RECOMPUTED'::text])))),
    CONSTRAINT availability_case_event_verification_outcome_ck CHECK (((verification_outcome IS NULL) OR (verification_outcome = ANY (ARRAY['VERIFIED'::text, 'CONTINUING'::text, 'FAILED'::text, 'REGRESSED'::text])))),
    CONSTRAINT availability_case_event_verification_shape_ck CHECK (((event_kind <> 'VERIFICATION_OBSERVED'::text) OR ((verification_kind IS NOT NULL) AND (verification_outcome IS NOT NULL) AND (observed_at IS NOT NULL))))
);

CREATE TABLE ops.availability_exception_decision (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    exception_id uuid NOT NULL,
    decision text NOT NULL,
    authority_level text NOT NULL,
    decided_by_user_id uuid NOT NULL,
    decided_by_role_code text NOT NULL,
    delegation_reference text,
    requester_is_approver boolean NOT NULL,
    separation_required boolean NOT NULL,
    authenticated_at timestamp with time zone,
    step_up_satisfied boolean NOT NULL,
    reason text NOT NULL,
    granted_effective_from timestamp with time zone,
    granted_expires_at timestamp with time zone,
    decided_at timestamp with time zone NOT NULL,
    correlation_id text NOT NULL,
    CONSTRAINT availability_exception_decision_authority_ck CHECK ((authority_level = ANY (ARRAY['DOMAIN_LEAD'::text, 'OPS_LEAD'::text, 'RISK_AUTHORITY'::text]))),
    CONSTRAINT availability_exception_decision_correlation_ck CHECK (((length(btrim(correlation_id)) >= 1) AND (length(btrim(correlation_id)) <= 128))),
    CONSTRAINT availability_exception_decision_decision_ck CHECK ((decision = ANY (ARRAY['APPROVED'::text, 'REJECTED'::text, 'AUTHORITY_BLOCKED'::text]))),
    CONSTRAINT availability_exception_decision_delegation_ck CHECK (((delegation_reference IS NULL) OR ((length(btrim(delegation_reference)) >= 1) AND (length(btrim(delegation_reference)) <= 256)))),
    CONSTRAINT availability_exception_decision_grant_ck CHECK (((decision = 'APPROVED'::text) = ((granted_effective_from IS NOT NULL) AND (granted_expires_at IS NOT NULL)))),
    CONSTRAINT availability_exception_decision_period_ck CHECK (((granted_expires_at IS NULL) OR (granted_expires_at > granted_effective_from))),
    CONSTRAINT availability_exception_decision_reason_ck CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 1024))),
    CONSTRAINT availability_exception_decision_separation_ck CHECK ((NOT ((decision = 'APPROVED'::text) AND separation_required AND requester_is_approver))),
    CONSTRAINT availability_exception_decision_step_up_ck CHECK (((decision <> 'APPROVED'::text) OR (step_up_satisfied AND (authenticated_at IS NOT NULL))))
);

CREATE TABLE ops.availability_exception_delegation (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    delegation_reference text NOT NULL,
    delegate_user_id uuid NOT NULL,
    delegated_role_code text NOT NULL,
    granted_by_user_id uuid NOT NULL,
    granted_by_role_code text NOT NULL,
    effective_from timestamp with time zone NOT NULL,
    effective_to timestamp with time zone NOT NULL,
    evidence_reference text NOT NULL,
    granted_at timestamp with time zone NOT NULL,
    revoked_at timestamp with time zone,
    revoked_by_user_id uuid,
    revocation_reason text,
    correlation_id text NOT NULL,
    CONSTRAINT availability_exception_delegation_correlation_ck CHECK (((length(btrim(correlation_id)) >= 1) AND (length(btrim(correlation_id)) <= 128))),
    CONSTRAINT availability_exception_delegation_evidence_ck CHECK (((length(btrim(evidence_reference)) >= 1) AND (length(btrim(evidence_reference)) <= 512))),
    CONSTRAINT availability_exception_delegation_period_ck CHECK ((effective_to > effective_from)),
    CONSTRAINT availability_exception_delegation_reference_ck CHECK (((length(btrim(delegation_reference)) >= 1) AND (length(btrim(delegation_reference)) <= 256))),
    CONSTRAINT availability_exception_delegation_revoke_ck CHECK ((((revoked_at IS NULL) AND (revoked_by_user_id IS NULL) AND (revocation_reason IS NULL)) OR ((revoked_at IS NOT NULL) AND (revoked_by_user_id IS NOT NULL) AND ((length(btrim(revocation_reason)) >= 1) AND (length(btrim(revocation_reason)) <= 1024)))))
);

CREATE TABLE ops.availability_fact_cursor (
    feed_code text NOT NULL,
    position_at timestamp with time zone NOT NULL,
    last_scanned_at timestamp with time zone NOT NULL,
    scanned_count bigint DEFAULT 0 NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    position_provenance_id uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    position_item_key text DEFAULT ''::text NOT NULL,
    CONSTRAINT availability_fact_cursor_count_ck CHECK ((scanned_count >= 0)),
    CONSTRAINT availability_fact_cursor_feed_ck CHECK ((feed_code = 'ACCEPTED_FACT'::text)),
    CONSTRAINT availability_fact_cursor_item_key_ck CHECK ((length(position_item_key) <= 192)),
    CONSTRAINT availability_fact_cursor_order_ck CHECK (((last_scanned_at >= position_at) OR (scanned_count = 0)))
);

CREATE TABLE ops.availability_recalculation_request (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    product_variant_id uuid NOT NULL,
    trigger_class text NOT NULL,
    trigger_reference text,
    fact_accepted_at timestamp with time zone NOT NULL,
    requested_at timestamp with time zone NOT NULL,
    state text NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    leased_until timestamp with time zone,
    lease_owner text,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    failure_code text,
    correlation_id text NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT availability_recalculation_request_attempt_ck CHECK (((attempt_count >= 0) AND (attempt_count <= 1000))),
    CONSTRAINT availability_recalculation_request_completion_ck CHECK (((state = ANY (ARRAY['COMPLETED'::text, 'FAILED'::text, 'ABANDONED'::text])) = (completed_at IS NOT NULL))),
    CONSTRAINT availability_recalculation_request_correlation_ck CHECK (((length(btrim(correlation_id)) >= 1) AND (length(btrim(correlation_id)) <= 128))),
    CONSTRAINT availability_recalculation_request_failure_ck CHECK (((state <> 'FAILED'::text) OR (failure_code IS NOT NULL))),
    CONSTRAINT availability_recalculation_request_lease_ck CHECK (((state = 'LEASED'::text) = ((leased_until IS NOT NULL) AND (lease_owner IS NOT NULL)))),
    CONSTRAINT availability_recalculation_request_reference_ck CHECK (((trigger_reference IS NULL) OR ((length(btrim(trigger_reference)) >= 1) AND (length(btrim(trigger_reference)) <= 256)))),
    CONSTRAINT availability_recalculation_request_state_ck CHECK ((state = ANY (ARRAY['PENDING'::text, 'LEASED'::text, 'COMPLETED'::text, 'FAILED'::text, 'ABANDONED'::text]))),
    CONSTRAINT availability_recalculation_request_trigger_ck CHECK ((trigger_class = ANY (ARRAY['STOCK_OR_SELLABILITY'::text, 'SALES_EVIDENCE'::text, 'RETURN_EVIDENCE'::text, 'INBOUND_CHANGE'::text, 'LEAD_TIME_POLICY'::text, 'DEMAND_POLICY'::text, 'PROFIT_OR_LIFECYCLE'::text, 'MAPPING_OR_OWNERSHIP'::text, 'EXCEPTION_LIFECYCLE'::text, 'FRESHNESS_CHANGE'::text, 'VERIFICATION_EVIDENCE'::text, 'MANUAL_REQUEST'::text])))
);

CREATE TABLE ops.availability_reconciliation_run (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    as_of timestamp with time zone NOT NULL,
    state text NOT NULL,
    trigger_kind text NOT NULL,
    variant_count integer,
    changed_card_count integer,
    repaired_count integer,
    expired_inbound_count integer,
    expired_exception_count integer,
    failure_code text,
    started_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    correlation_id text NOT NULL,
    last_product_variant_id uuid,
    failed_variant_count integer DEFAULT 0 NOT NULL,
    CONSTRAINT availability_reconciliation_run_completion_ck CHECK (((state = ANY (ARRAY['COMPLETED'::text, 'FAILED'::text])) = (completed_at IS NOT NULL))),
    CONSTRAINT availability_reconciliation_run_correlation_ck CHECK (((length(btrim(correlation_id)) >= 1) AND (length(btrim(correlation_id)) <= 128))),
    CONSTRAINT availability_reconciliation_run_counts_ck CHECK (((COALESCE(variant_count, 0) >= 0) AND (COALESCE(changed_card_count, 0) >= 0) AND (COALESCE(repaired_count, 0) >= 0) AND (COALESCE(expired_inbound_count, 0) >= 0) AND (COALESCE(expired_exception_count, 0) >= 0))),
    CONSTRAINT availability_reconciliation_run_failed_count_ck CHECK ((failed_variant_count >= 0)),
    CONSTRAINT availability_reconciliation_run_failure_ck CHECK (((state <> 'FAILED'::text) OR (failure_code IS NOT NULL))),
    CONSTRAINT availability_reconciliation_run_state_ck CHECK ((state = ANY (ARRAY['RUNNING'::text, 'COMPLETED'::text, 'FAILED'::text]))),
    CONSTRAINT availability_reconciliation_run_trigger_ck CHECK ((trigger_kind = ANY (ARRAY['SCHEDULED'::text, 'MANUAL'::text, 'RECOVERY'::text])))
);

CREATE TABLE ops.availability_slo_observation (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    product_variant_id uuid NOT NULL,
    lane text NOT NULL,
    path_kind text NOT NULL,
    source_event_time timestamp with time zone,
    source_updated_at timestamp with time zone,
    ingested_at timestamp with time zone,
    fact_accepted_at timestamp with time zone NOT NULL,
    risk_calculated_at timestamp with time zone NOT NULL,
    case_updated_at timestamp with time zone,
    internal_latency_ms bigint NOT NULL,
    source_latency_ms bigint,
    breached boolean NOT NULL,
    correlation_id text NOT NULL,
    CONSTRAINT availability_slo_observation_correlation_ck CHECK (((length(btrim(correlation_id)) >= 1) AND (length(btrim(correlation_id)) <= 128))),
    CONSTRAINT availability_slo_observation_lane_ck CHECK ((lane = ANY (ARRAY['HEALTHY'::text, 'WATCH'::text, 'HIGH'::text, 'CRITICAL'::text, 'REVIEW'::text, 'UNRESOLVED'::text]))),
    CONSTRAINT availability_slo_observation_latency_ck CHECK ((internal_latency_ms >= 0)),
    CONSTRAINT availability_slo_observation_order_ck CHECK ((risk_calculated_at >= fact_accepted_at)),
    CONSTRAINT availability_slo_observation_path_ck CHECK ((path_kind = ANY (ARRAY['TARGETED'::text, 'RECONCILIATION'::text]))),
    CONSTRAINT availability_slo_observation_source_latency_ck CHECK (((source_latency_ms IS NULL) OR (source_latency_ms >= 0)))
);

CREATE TABLE ops.availability_trace_event (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    product_variant_id uuid,
    path_kind text NOT NULL,
    stage_code text NOT NULL,
    status text NOT NULL,
    correlation_id text NOT NULL,
    parent_correlation_id text,
    subject_reference text,
    detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    occurred_at timestamp with time zone NOT NULL,
    CONSTRAINT availability_trace_event_correlation_ck CHECK (((length(btrim(correlation_id)) >= 1) AND (length(btrim(correlation_id)) <= 128))),
    CONSTRAINT availability_trace_event_detail_ck CHECK ((jsonb_typeof(detail) = 'object'::text)),
    CONSTRAINT availability_trace_event_parent_ck CHECK (((parent_correlation_id IS NULL) OR ((length(btrim(parent_correlation_id)) >= 1) AND (length(btrim(parent_correlation_id)) <= 128)))),
    CONSTRAINT availability_trace_event_path_ck CHECK ((path_kind = ANY (ARRAY['TARGETED'::text, 'RECONCILIATION'::text, 'OPERATIONS'::text]))),
    CONSTRAINT availability_trace_event_stage_ck CHECK ((stage_code = ANY (ARRAY['TARGET_DEDUP_QUEUED'::text, 'TARGET_DEDUP_COALESCED'::text, 'TARGET_DEDUP_SUPPRESSED'::text, 'TARGETED_PROCESS_STARTED'::text, 'CALCULATION_STARTED'::text, 'EVIDENCE_AND_RISK_CALCULATED'::text, 'PROJECTION_WRITTEN'::text, 'CASE_SYNCHRONIZED'::text, 'AUTO_VERIFICATION'::text, 'SLO_RECORDED'::text, 'SWEEP_STARTED'::text, 'BACKLOG_SNAPSHOT'::text, 'EXCEPTION_EXPIRY_REVALIDATION'::text, 'SWEEP_COMPLETED'::text, 'SWEEP_FAILED'::text]))),
    CONSTRAINT availability_trace_event_status_ck CHECK ((status = ANY (ARRAY['STARTED'::text, 'COMPLETED'::text, 'SUPPRESSED'::text, 'FAILED'::text, 'OBSERVED'::text]))),
    CONSTRAINT availability_trace_event_subject_ck CHECK (((subject_reference IS NULL) OR ((length(btrim(subject_reference)) >= 1) AND (length(btrim(subject_reference)) <= 512))))
);

CREATE TABLE ops.commercial_policy (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    policy_code text NOT NULL,
    policy_version integer NOT NULL,
    scope_kind text NOT NULL,
    platform_code text,
    store_ref_id uuid,
    product_variant_ref_id uuid,
    lifecycle_objective text NOT NULL,
    currency_code text NOT NULL,
    effective_from timestamp with time zone NOT NULL,
    effective_to timestamp with time zone,
    status text NOT NULL,
    published_by_user_id uuid NOT NULL,
    reason text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT commercial_policy_code_ck CHECK ((policy_code ~ '^[a-z0-9]([a-z0-9._-]{0,61}[a-z0-9])?$'::text)),
    CONSTRAINT commercial_policy_currency_ck CHECK ((currency_code ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT commercial_policy_interval_ck CHECK (((effective_to IS NULL) OR (effective_from < effective_to))),
    CONSTRAINT commercial_policy_objective_ck CHECK ((lifecycle_objective = ANY (ARRAY['HERO'::text, 'GROWTH'::text, 'MATURE'::text, 'REPAIR'::text, 'EXIT'::text]))),
    CONSTRAINT commercial_policy_scope_ck CHECK ((scope_kind = ANY (ARRAY['ORGANIZATION'::text, 'PLATFORM'::text, 'STORE'::text, 'PRODUCT_VARIANT'::text]))),
    CONSTRAINT commercial_policy_scope_matrix_ck CHECK ((((scope_kind = 'ORGANIZATION'::text) AND (num_nonnulls(platform_code, store_ref_id, product_variant_ref_id) = 0)) OR ((scope_kind = 'PLATFORM'::text) AND (platform_code IS NOT NULL) AND (num_nonnulls(store_ref_id, product_variant_ref_id) = 0)) OR ((scope_kind = 'STORE'::text) AND (store_ref_id IS NOT NULL) AND (num_nonnulls(platform_code, product_variant_ref_id) = 0)) OR ((scope_kind = 'PRODUCT_VARIANT'::text) AND (product_variant_ref_id IS NOT NULL) AND (num_nonnulls(platform_code, store_ref_id) = 0)))),
    CONSTRAINT commercial_policy_status_ck CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'ENDED'::text, 'CANCELLED'::text]))),
    CONSTRAINT commercial_policy_version_ck CHECK ((policy_version > 0))
);

CREATE TABLE ops.commercial_policy_limit (
    id uuid NOT NULL,
    policy_id uuid NOT NULL,
    limit_code text NOT NULL,
    rate_value numeric(9,6),
    amount_value numeric(18,4),
    count_value integer,
    duration_seconds bigint,
    CONSTRAINT commercial_policy_limit_amount_ck CHECK (((amount_value IS NULL) OR (amount_value >= (0)::numeric))),
    CONSTRAINT commercial_policy_limit_count_ck CHECK (((count_value IS NULL) OR (count_value >= 0))),
    CONSTRAINT commercial_policy_limit_duration_ck CHECK (((duration_seconds IS NULL) OR (duration_seconds >= 0))),
    CONSTRAINT commercial_policy_limit_one_value_ck CHECK ((num_nonnulls(rate_value, amount_value, count_value, duration_seconds) = 1)),
    CONSTRAINT commercial_policy_limit_rate_ck CHECK (((rate_value IS NULL) OR ((rate_value >= (0)::numeric) AND (rate_value <= (1)::numeric))))
);

CREATE TABLE ops.diagnostic_export_part (
    export_id uuid NOT NULL,
    part_number integer NOT NULL,
    first_ordinal integer NOT NULL,
    last_ordinal integer NOT NULL,
    row_count integer NOT NULL,
    byte_length integer NOT NULL,
    sha256 text NOT NULL,
    content_id uuid NOT NULL,
    CONSTRAINT diagnostic_export_part_byte_length_check CHECK (((byte_length >= 1) AND (byte_length <= 4194304))),
    CONSTRAINT diagnostic_export_part_check CHECK ((last_ordinal >= first_ordinal)),
    CONSTRAINT diagnostic_export_part_check1 CHECK ((row_count = ((last_ordinal - first_ordinal) + 1))),
    CONSTRAINT diagnostic_export_part_first_ordinal_check CHECK ((first_ordinal > 0)),
    CONSTRAINT diagnostic_export_part_part_number_check CHECK (((part_number >= 1) AND (part_number <= 64))),
    CONSTRAINT diagnostic_export_part_sha256_check CHECK ((sha256 ~ '^[0-9a-f]{64}$'::text))
);

CREATE TABLE ops.endpoint_quota_window (
    endpoint_id uuid NOT NULL,
    window_started_at timestamp with time zone NOT NULL,
    blocked_until timestamp with time zone,
    used_calls integer NOT NULL,
    CONSTRAINT endpoint_quota_window_used_calls_check CHECK ((used_calls > 0))
);

CREATE TABLE ops.guardrail_evaluation (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    recommendation_id uuid NOT NULL,
    policy_id uuid,
    policy_version integer,
    purpose text NOT NULL,
    outcome text NOT NULL,
    reason_codes text[] NOT NULL,
    detail jsonb NOT NULL,
    input_digest text NOT NULL,
    evaluated_at timestamp with time zone NOT NULL,
    correlation_id text NOT NULL,
    authority_snapshot jsonb NOT NULL,
    ad_decision_bundle_id uuid,
    ad_bundle_version integer,
    lc_calibration_package_id uuid,
    lc_calibration_version integer,
    listing_transaction_id bigint,
    CONSTRAINT guardrail_evaluation_ad_bundle_shape_ck CHECK (((ad_decision_bundle_id IS NULL) = (ad_bundle_version IS NULL))),
    CONSTRAINT guardrail_evaluation_detail_ck CHECK ((jsonb_typeof(detail) = 'object'::text)),
    CONSTRAINT guardrail_evaluation_digest_ck CHECK ((input_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT guardrail_evaluation_lc_calibration_shape_ck CHECK (((lc_calibration_package_id IS NULL) = (lc_calibration_version IS NULL))),
    CONSTRAINT guardrail_evaluation_outcome_ck CHECK ((outcome = ANY (ARRAY['PASS'::text, 'BLOCK'::text]))),
    CONSTRAINT guardrail_evaluation_policy_presence_ck CHECK (((outcome = 'BLOCK'::text) OR ((((((policy_id IS NOT NULL) AND (policy_version IS NOT NULL)))::integer + (((ad_decision_bundle_id IS NOT NULL) AND (ad_bundle_version IS NOT NULL)))::integer) + (((lc_calibration_package_id IS NOT NULL) AND (lc_calibration_version IS NOT NULL)))::integer) = 1))),
    CONSTRAINT guardrail_evaluation_purpose_ck CHECK ((purpose = ANY (ARRAY['IMPACT_PREVIEW'::text, 'APPROVAL'::text, 'EXECUTION'::text]))),
    CONSTRAINT guardrail_evaluation_reasons_ck CHECK (((outcome = 'PASS'::text) = (cardinality(reason_codes) = 0)))
);

CREATE TABLE ops.ingestion_checkpoint (
    job_id uuid NOT NULL,
    strategy text NOT NULL,
    position_value text,
    checkpoint_version bigint NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT ingestion_checkpoint_strategy_ck CHECK ((strategy = ANY (ARRAY['CURSOR'::text, 'OFFSET'::text, 'PAGE'::text, 'DATE_WINDOW'::text, 'NONE'::text, 'UNKNOWN'::text]))),
    CONSTRAINT ingestion_checkpoint_unknown_ck CHECK (((strategy <> 'UNKNOWN'::text) OR (position_value IS NULL))),
    CONSTRAINT ingestion_checkpoint_version_ck CHECK ((checkpoint_version >= 0))
);

CREATE TABLE ops.ingestion_run (
    id uuid NOT NULL,
    job_id uuid NOT NULL,
    state text NOT NULL,
    fence_token bigint NOT NULL,
    lease_owner text,
    lease_expires_at timestamp with time zone,
    attempt_no integer NOT NULL,
    last_call_seq integer NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    run_kind text DEFAULT 'SCHEDULED'::text NOT NULL,
    window_from timestamp with time zone,
    window_to timestamp with time zone,
    failure_code text,
    next_attempt_at timestamp with time zone,
    max_claims integer DEFAULT 4 NOT NULL,
    CONSTRAINT ingestion_run_attempt_ck CHECK ((attempt_no >= 0)),
    CONSTRAINT ingestion_run_backfill_window_ck CHECK (((run_kind <> 'BACKFILL'::text) OR (window_from IS NOT NULL))),
    CONSTRAINT ingestion_run_call_seq_ck CHECK ((last_call_seq >= 0)),
    CONSTRAINT ingestion_run_failure_ck CHECK (((state <> 'FAILED_TERMINAL'::text) OR (failure_code IS NOT NULL))),
    CONSTRAINT ingestion_run_fence_ck CHECK ((fence_token > 0)),
    CONSTRAINT ingestion_run_kind_ck CHECK ((run_kind = ANY (ARRAY['SCHEDULED'::text, 'MANUAL'::text, 'BACKFILL'::text, 'REPLAY'::text]))),
    CONSTRAINT ingestion_run_lease_pairing_ck CHECK ((num_nonnulls(lease_owner, lease_expires_at) <> 1)),
    CONSTRAINT ingestion_run_leased_state_ck CHECK (((state <> ALL (ARRAY['LEASED'::text, 'RUNNING'::text])) OR (lease_owner IS NOT NULL))),
    CONSTRAINT ingestion_run_max_claims_check CHECK (((max_claims >= 1) AND (max_claims <= 11))),
    CONSTRAINT ingestion_run_state_ck CHECK ((state = ANY (ARRAY['QUEUED'::text, 'LEASED'::text, 'RUNNING'::text, 'RETRY_WAIT'::text, 'BLOCKED'::text, 'SUCCEEDED'::text, 'FAILED_TERMINAL'::text]))),
    CONSTRAINT ingestion_run_window_ck CHECK (((num_nonnulls(window_from, window_to) <> 1) AND ((window_from IS NULL) OR (window_from < window_to))))
);

CREATE TABLE ops.kill_switch_event (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    action_kind text CONSTRAINT kill_switch_event_capability_code_not_null NOT NULL,
    scope_kind text NOT NULL,
    scope_reference text,
