    actor_user_id uuid NOT NULL,
    reason text NOT NULL,
    in_flight_command_count integer NOT NULL,
    occurred_at timestamp with time zone NOT NULL,
    correlation_id text NOT NULL,
    CONSTRAINT kill_switch_event_action_ck CHECK ((action = ANY (ARRAY['DISABLE'::text, 'ENABLE'::text]))),
    CONSTRAINT kill_switch_event_in_flight_ck CHECK ((in_flight_command_count >= 0)),
    CONSTRAINT kill_switch_event_scope_ck CHECK ((scope_kind = ANY (ARRAY['GLOBAL'::text, 'PLATFORM'::text, 'MARKETPLACE_ACCOUNT'::text, 'STORE'::text, 'CAPABILITY'::text]))),
    CONSTRAINT kill_switch_event_scope_reference_ck CHECK (((scope_kind = 'GLOBAL'::text) = (scope_reference IS NULL)))
);

CREATE TABLE ops.lc_action (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    store_id uuid NOT NULL,
    platform_listing_id uuid NOT NULL,
    candidate_id uuid NOT NULL,
    recommendation_id uuid NOT NULL,
    affected_set_id uuid NOT NULL,
    affected_set_digest text NOT NULL,
    action_kind text NOT NULL,
    execution_path text NOT NULL,
    current_description_observation_id uuid,
    current_text_digest text,
    target_text text,
    target_text_digest text,
    target_language_code text,
    kiz_marked_declared boolean,
    content_axis_material boolean,
    exposure_axis_material boolean,
    materiality_route text NOT NULL,
    calibration_package_id uuid,
    calibration_version integer,
    author_user_id uuid NOT NULL,
    state text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    restores_command_id uuid,
    promotion_terms jsonb,
    promotion_terms_digest text GENERATED ALWAYS AS (ops.lc_promotion_terms_digest(promotion_terms)) STORED,
    calibration_dependencies jsonb,
    materiality_evidence jsonb,
    purpose_basis jsonb,
    CONSTRAINT lc_action_description_shape_ck CHECK (((action_kind <> 'LISTING_DESCRIPTION_CHANGE'::text) OR ((current_description_observation_id IS NOT NULL) AND (current_text_digest ~ '^[0-9a-f]{64}$'::text) AND (target_text IS NOT NULL) AND ((length(target_text) >= 1) AND (length(target_text) <= 65536)) AND (target_text_digest = encode(sha256(convert_to(target_text, 'UTF8'::name)), 'hex'::text)) AND (target_language_code = 'ru'::text) AND (kiz_marked_declared IS NOT NULL)))),
    CONSTRAINT lc_action_digest_ck CHECK ((affected_set_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT lc_action_kind_ck CHECK ((action_kind = ANY (ARRAY['LISTING_DESCRIPTION_CHANGE'::text, 'LISTING_PROMOTION_ACTION'::text]))),
    CONSTRAINT lc_action_materiality_axes_ck CHECK ((((calibration_package_id IS NULL) = (calibration_version IS NULL)) AND (((materiality_route = 'MATERIAL_IMPACT'::text) AND (calibration_package_id IS NOT NULL) AND ((content_axis_material IS TRUE) OR (exposure_axis_material IS TRUE))) OR ((materiality_route = 'ORDINARY_IMPACT'::text) AND (calibration_package_id IS NOT NULL) AND (content_axis_material IS FALSE) AND (exposure_axis_material IS FALSE)) OR ((materiality_route = 'MATERIALITY_UNRESOLVED'::text) AND (content_axis_material IS NOT TRUE) AND (exposure_axis_material IS NOT TRUE) AND ((content_axis_material IS NULL) OR (exposure_axis_material IS NULL)))))),
    CONSTRAINT lc_action_materiality_ck CHECK ((materiality_route = ANY (ARRAY['MATERIAL_IMPACT'::text, 'ORDINARY_IMPACT'::text, 'MATERIALITY_UNRESOLVED'::text]))),
    CONSTRAINT lc_action_path_ck CHECK ((execution_path = ANY (ARRAY['MANUAL'::text, 'API'::text]))),
    CONSTRAINT lc_action_promotion_path_ck CHECK (((action_kind <> 'LISTING_PROMOTION_ACTION'::text) OR (execution_path = 'MANUAL'::text))),
    CONSTRAINT lc_action_promotion_shape_ck CHECK (((action_kind <> 'LISTING_PROMOTION_ACTION'::text) OR ((target_text IS NULL) AND (target_text_digest IS NULL)))),
    CONSTRAINT lc_action_state_ck CHECK ((state = ANY (ARRAY['DRAFT'::text, 'REVIEWED'::text, 'APPROVED'::text, 'APPROVED_NOT_LAUNCHABLE'::text, 'LAUNCHED'::text, 'VERIFIED'::text, 'CLOSED'::text, 'CANCELLED'::text, 'CONTAINED'::text]))),
    CONSTRAINT lc_action_unresolved_stays_draft_ck CHECK (((materiality_route <> 'MATERIALITY_UNRESOLVED'::text) OR (state = ANY (ARRAY['DRAFT'::text, 'CANCELLED'::text]))))
);

COMMENT ON COLUMN ops.lc_action.calibration_dependencies IS 'Exact rule dependency projection captured at preparation; historical NULL is unproven for cross-package continuation.';

CREATE TABLE ops.lc_action_binding (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    action_id uuid NOT NULL,
    approval_decision_id uuid NOT NULL,
    guardrail_evaluation_id uuid NOT NULL,
    target_text_digest text,
    current_text_digest text,
    affected_set_digest text NOT NULL,
    execution_path text NOT NULL,
    evidence_versions jsonb NOT NULL,
    rule_versions jsonb NOT NULL,
    calibration_package_id uuid NOT NULL,
    calibration_version integer NOT NULL,
    binding_digest text NOT NULL,
    bound_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    state text NOT NULL,
    inapplicable_reason text,
    inapplicable_at timestamp with time zone,
    evaluation_plan_digest text,
    purpose_basis_digest text,
    CONSTRAINT lc_action_binding_digests_ck CHECK (((affected_set_digest ~ '^[0-9a-f]{64}$'::text) AND (binding_digest ~ '^[0-9a-f]{64}$'::text) AND ((target_text_digest IS NULL) OR (target_text_digest ~ '^[0-9a-f]{64}$'::text)) AND ((current_text_digest IS NULL) OR (current_text_digest ~ '^[0-9a-f]{64}$'::text)))),
    CONSTRAINT lc_action_binding_evaluation_plan_digest_check CHECK (((evaluation_plan_digest IS NULL) OR (evaluation_plan_digest ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT lc_action_binding_expiry_ck CHECK ((expires_at > bound_at)),
    CONSTRAINT lc_action_binding_inapplicable_ck CHECK (((state = 'INAPPLICABLE'::text) = ((inapplicable_reason IS NOT NULL) AND (inapplicable_at IS NOT NULL)))),
    CONSTRAINT lc_action_binding_path_ck CHECK ((execution_path = ANY (ARRAY['MANUAL'::text, 'API'::text]))),
    CONSTRAINT lc_action_binding_purpose_basis_digest_check CHECK (((purpose_basis_digest IS NULL) OR (purpose_basis_digest ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT lc_action_binding_state_ck CHECK ((state = ANY (ARRAY['BOUND'::text, 'INAPPLICABLE'::text]))),
    CONSTRAINT lc_action_binding_versions_ck CHECK (((jsonb_typeof(evidence_versions) = 'object'::text) AND (jsonb_typeof(rule_versions) = 'object'::text)))
);

CREATE TABLE ops.lc_action_review (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    action_id uuid NOT NULL,
    reviewer_user_id uuid NOT NULL,
    attested_target_text_digest text,
    attested_current_text_digest text,
    attested_affected_set_digest text NOT NULL,
    facts_digest text NOT NULL,
    verdict text NOT NULL,
    reason text NOT NULL,
    reviewed_at timestamp with time zone NOT NULL,
    evaluation_plan_digest text,
    meaning_assessment jsonb,
    exposure_evidence jsonb,
    content_axis_material boolean,
    exposure_axis_material boolean,
    materiality_route text,
    purpose_basis_digest text,
    CONSTRAINT lc_action_review_digests_ck CHECK (((attested_affected_set_digest ~ '^[0-9a-f]{64}$'::text) AND (facts_digest ~ '^[0-9a-f]{64}$'::text) AND ((attested_target_text_digest IS NULL) OR (attested_target_text_digest ~ '^[0-9a-f]{64}$'::text)) AND ((attested_current_text_digest IS NULL) OR (attested_current_text_digest ~ '^[0-9a-f]{64}$'::text)))),
    CONSTRAINT lc_action_review_evaluation_plan_digest_check CHECK (((evaluation_plan_digest IS NULL) OR (evaluation_plan_digest ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT lc_action_review_purpose_basis_digest_check CHECK (((purpose_basis_digest IS NULL) OR (purpose_basis_digest ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT lc_action_review_reason_ck CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 2000))),
    CONSTRAINT lc_action_review_verdict_ck CHECK ((verdict = ANY (ARRAY['ATTESTED'::text, 'RETURNED'::text])))
);

CREATE TABLE ops.lc_action_transition (
    from_state text NOT NULL,
    to_state text NOT NULL,
