    CONSTRAINT lc_batch_code_ck CHECK ((batch_code ~ '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$'::text)),
    CONSTRAINT lc_batch_state_ck CHECK ((state = ANY (ARRAY['OPEN'::text, 'CLOSED'::text])))
);

CREATE TABLE ops.lc_batch_member (
