    sequence_no integer NOT NULL,
    membership_state text NOT NULL,
    recorded_by_user_id uuid NOT NULL,
    recorded_at timestamp with time zone NOT NULL,
    CONSTRAINT lc_batch_member_sequence_ck CHECK ((sequence_no >= 1)),
    CONSTRAINT lc_batch_member_state_ck CHECK ((membership_state = ANY (ARRAY['ACTIVE'::text, 'REMOVED'::text])))
);

CREATE TABLE ops.lc_calibration_event (
    id uuid NOT NULL,
    package_id uuid NOT NULL,
    event_kind text NOT NULL,
    actor_user_id uuid NOT NULL,
    package_digest text NOT NULL,
    evidence_reference text NOT NULL,
    occurred_at timestamp with time zone NOT NULL,
    CONSTRAINT lc_calibration_event_event_kind_check CHECK ((event_kind = ANY (ARRAY['DRAFTED'::text, 'VALIDATED'::text, 'ACCEPTED'::text, 'ACTIVATED'::text, 'RETIRED'::text]))),
    CONSTRAINT lc_calibration_event_evidence_reference_check CHECK (((length(btrim(evidence_reference)) >= 1) AND (length(btrim(evidence_reference)) <= 512))),
    CONSTRAINT lc_calibration_event_package_digest_check CHECK ((package_digest ~ '^[0-9a-f]{64}$'::text))
);

CREATE TABLE ops.lc_calibration_governance (
    package_id uuid NOT NULL,
    replaces_package_id uuid,
    rationale text NOT NULL,
    impact text NOT NULL,
    differences text NOT NULL,
    drafted_by_user_id uuid NOT NULL,
    drafted_at timestamp with time zone NOT NULL,
    draft_digest text NOT NULL,
    validated_by_user_id uuid,
    validated_at timestamp with time zone,
    validation_reference text,
    validated_digest text,
    accepted_by_user_id uuid,
    accepted_at timestamp with time zone,
    acceptance_reference text,
    accepted_digest text,
    CONSTRAINT lc_calibration_governance_check CHECK ((((validated_at IS NULL) AND (validated_by_user_id IS NULL) AND (validated_digest IS NULL) AND (validation_reference IS NULL)) OR ((validated_at IS NOT NULL) AND (validated_by_user_id IS NOT NULL) AND (validated_digest IS NOT NULL) AND (validation_reference IS NOT NULL) AND (validated_digest = draft_digest) AND ((length(btrim(validation_reference)) >= 1) AND (length(btrim(validation_reference)) <= 512))))),
    CONSTRAINT lc_calibration_governance_check1 CHECK ((((accepted_at IS NULL) AND (accepted_by_user_id IS NULL) AND (accepted_digest IS NULL) AND (acceptance_reference IS NULL)) OR ((accepted_at IS NOT NULL) AND (accepted_by_user_id IS NOT NULL) AND (accepted_digest IS NOT NULL) AND (acceptance_reference IS NOT NULL) AND (accepted_digest = validated_digest) AND (validated_at IS NOT NULL) AND (accepted_by_user_id <> drafted_by_user_id) AND (accepted_by_user_id <> validated_by_user_id) AND ((length(btrim(acceptance_reference)) >= 1) AND (length(btrim(acceptance_reference)) <= 512))))),
    CONSTRAINT lc_calibration_governance_differences_check CHECK (((length(btrim(differences)) >= 1) AND (length(btrim(differences)) <= 4096))),
    CONSTRAINT lc_calibration_governance_draft_digest_check CHECK ((draft_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT lc_calibration_governance_impact_check CHECK (((length(btrim(impact)) >= 1) AND (length(btrim(impact)) <= 4096))),
    CONSTRAINT lc_calibration_governance_rationale_check CHECK (((length(btrim(rationale)) >= 1) AND (length(btrim(rationale)) <= 4096)))
);

CREATE TABLE ops.lc_candidate (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
