    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT lc_candidate_effect_ck CHECK ((jsonb_typeof(expected_effect) = 'object'::text)),
    CONSTRAINT lc_candidate_evidence_ck CHECK ((jsonb_typeof(evidence_references) = 'array'::text)),
    CONSTRAINT lc_candidate_kind_ck CHECK ((candidate_kind = ANY (ARRAY['CONTENT_DESCRIPTION'::text, 'OFFICIAL_PROMOTION_PARTICIPATION'::text, 'SELLER_DIRECT_DISCOUNT'::text]))),
    CONSTRAINT lc_candidate_round_ck CHECK ((comparison_round_key ~ '^[a-z0-9][a-z0-9._-]{0,63}$'::text)),
    CONSTRAINT lc_candidate_state_ck CHECK ((state = ANY (ARRAY['OPEN'::text, 'SELECTED'::text, 'DISMISSED'::text])))
);

CREATE TABLE ops.lc_collaboration_link (
