    recorded_by_user_id uuid NOT NULL,
    source_time timestamp with time zone,
    recorded_at timestamp with time zone NOT NULL,
    CONSTRAINT lc_collaboration_link_domain_ck CHECK ((target_domain = ANY (ARRAY['INVENTORY'::text, 'FINANCE'::text, 'PRODUCT'::text, 'ADVERTISING'::text, 'CONTENT'::text]))),
    CONSTRAINT lc_collaboration_link_kind_ck CHECK ((link_kind = ANY (ARRAY['HANDOVER'::text, 'EVIDENCE_RETURN'::text, 'DEPENDENCY_REEVALUATION'::text]))),
    CONSTRAINT lc_collaboration_link_reference_ck CHECK (((length(btrim(evidence_reference)) >= 1) AND (length(btrim(evidence_reference)) <= 512)))
);

CREATE TABLE ops.lc_containment (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    scope_kind text NOT NULL,
    platform_listing_id uuid,
    store_id uuid,
    platform_code text,
    batch_id uuid,
    cause_class text NOT NULL,
    cause_owner_role_code text NOT NULL,
    stopped_by_user_id uuid NOT NULL,
    stopped_at timestamp with time zone NOT NULL,
    reason text NOT NULL,
    evidence_reference text NOT NULL,
    state text NOT NULL,
    reenabled_at timestamp with time zone,
    CONSTRAINT lc_containment_cause_ck CHECK ((cause_class = ANY (ARRAY['LOCAL_COST'::text, 'SHARED_VERSION'::text, 'PATH_INTEGRITY'::text, 'SAFETY_FAILURE'::text, 'PLATFORM_INCIDENT'::text]))),
    CONSTRAINT lc_containment_reason_ck CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 2000))),
    CONSTRAINT lc_containment_reenabled_ck CHECK (((state = 'REENABLED'::text) = (reenabled_at IS NOT NULL))),
    CONSTRAINT lc_containment_reference_ck CHECK (((length(btrim(evidence_reference)) >= 1) AND (length(btrim(evidence_reference)) <= 512))),
    CONSTRAINT lc_containment_scope_ck CHECK ((scope_kind = ANY (ARRAY['LISTING'::text, 'STORE'::text, 'PLATFORM'::text, 'ORGANIZATION'::text, 'BATCH'::text]))),
    CONSTRAINT lc_containment_scope_shape_ck CHECK ((((scope_kind = 'LISTING'::text) AND (platform_listing_id IS NOT NULL) AND (store_id IS NULL) AND (platform_code IS NULL) AND (batch_id IS NULL)) OR ((scope_kind = 'STORE'::text) AND (store_id IS NOT NULL) AND (platform_listing_id IS NULL) AND (platform_code IS NULL) AND (batch_id IS NULL)) OR ((scope_kind = 'PLATFORM'::text) AND (platform_code IS NOT NULL) AND (platform_listing_id IS NULL) AND (store_id IS NULL) AND (batch_id IS NULL)) OR ((scope_kind = 'ORGANIZATION'::text) AND (platform_listing_id IS NULL) AND (store_id IS NULL) AND (platform_code IS NULL) AND (batch_id IS NULL)) OR ((scope_kind = 'BATCH'::text) AND (batch_id IS NOT NULL) AND (platform_listing_id IS NULL) AND (store_id IS NULL) AND (platform_code IS NULL)))),
    CONSTRAINT lc_containment_state_ck CHECK ((state = ANY (ARRAY['ACTIVE'::text, 'REENABLED'::text])))
);

CREATE TABLE ops.lc_containment_attestation (
    id uuid NOT NULL,
    containment_id uuid NOT NULL,
    attestation_kind text NOT NULL,
    actor_user_id uuid NOT NULL,
    evidence_reference text NOT NULL,
    attested_at timestamp with time zone NOT NULL,
    CONSTRAINT lc_containment_attestation_kind_ck CHECK ((attestation_kind = ANY (ARRAY['REPAIR_ATTESTATION'::text, 'BUSINESS_CONSENT'::text]))),
    CONSTRAINT lc_containment_attestation_reference_ck CHECK (((length(btrim(evidence_reference)) >= 1) AND (length(btrim(evidence_reference)) <= 512)))
);

CREATE TABLE ops.lc_description_command (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    recommendation_id uuid NOT NULL,
    approval_decision_id uuid NOT NULL,
    action_id uuid NOT NULL,
    launch_id uuid NOT NULL,
    binding_id uuid NOT NULL,
    store_id uuid NOT NULL,
    platform_listing_id uuid NOT NULL,
    platform_code text NOT NULL,
    capability_id uuid NOT NULL,
    idempotency_key text NOT NULL,
    prior_text text,
    prior_text_digest text NOT NULL,
    target_text text NOT NULL,
    target_text_digest text NOT NULL,
    kiz_marked_declared boolean NOT NULL,
    equivalence_rule text NOT NULL,
    length_bound_min integer NOT NULL,
    length_bound_max integer NOT NULL,
    affected_set_digest text NOT NULL,
    approval_expires_at timestamp with time zone NOT NULL,
    requested_operation text,
    state text NOT NULL,
    attempt_no integer DEFAULT 0 NOT NULL,
    retry_budget_remaining integer NOT NULL,
    fence_token bigint DEFAULT 1 NOT NULL,
    retry_preflight_fence bigint,
    lease_owner text,
    lease_expires_at timestamp with time zone,
    next_attempt_at timestamp with time zone,
    failure_code text,
    terminal_at timestamp with time zone,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    provider_not_before timestamp with time zone,
    provider_retry_timing_unknown boolean DEFAULT false NOT NULL,
    native_listing_key text,
    CONSTRAINT lc_description_command_attempt_ck CHECK ((attempt_no >= 0)),
    CONSTRAINT lc_description_command_bounds_ck CHECK (((length_bound_min >= 0) AND (length_bound_max >= length_bound_min) AND (length_bound_max <= 65536))),
    CONSTRAINT lc_description_command_change_ck CHECK ((target_text_digest <> prior_text_digest)),
    CONSTRAINT lc_description_command_digests_ck CHECK (((prior_text_digest ~ '^[0-9a-f]{64}$'::text) AND (affected_set_digest ~ '^[0-9a-f]{64}$'::text) AND (target_text_digest = encode(sha256(convert_to(target_text, 'UTF8'::name)), 'hex'::text)))),
    CONSTRAINT lc_description_command_failure_ck CHECK (((state <> ALL (ARRAY['FAILED_FINAL'::text, 'COMPENSATION_FAILED'::text, 'TERMINATED_WITHOUT_PROVIDER_CALL'::text])) OR (failure_code IS NOT NULL))),
    CONSTRAINT lc_description_command_fence_ck CHECK ((fence_token > 0)),
    CONSTRAINT lc_description_command_idempotency_ck CHECK ((idempotency_key ~ '^[a-z0-9][a-z0-9._-]{15,127}$'::text)),
    CONSTRAINT lc_description_command_lease_pairing_ck CHECK ((num_nonnulls(lease_owner, lease_expires_at) <> 1)),
    CONSTRAINT lc_description_command_leased_state_ck CHECK (((state <> ALL (ARRAY['LEASED'::text, 'EXECUTING'::text, 'READBACK_PENDING'::text])) OR (lease_owner IS NOT NULL))),
    CONSTRAINT lc_description_command_prior_ck CHECK (((prior_text IS NULL) OR (length(prior_text) >= 1))),
    CONSTRAINT lc_description_command_requested_operation_check CHECK ((requested_operation = 'READBACK'::text)),
    CONSTRAINT lc_description_command_retry_budget_ck CHECK ((retry_budget_remaining >= 0)),
    CONSTRAINT lc_description_command_retry_preflight_fence_ck CHECK (((retry_preflight_fence > 0) AND (retry_preflight_fence <= fence_token))),
    CONSTRAINT lc_description_command_rule_ck CHECK ((equivalence_rule = ANY (ARRAY['EXACT'::text, 'WHITESPACE_NORMALIZED'::text]))),
    CONSTRAINT lc_description_command_state_ck CHECK ((state = ANY (ARRAY['PENDING'::text, 'LEASED'::text, 'EXECUTING'::text, 'PLATFORM_PENDING'::text, 'READBACK_PENDING'::text, 'READBACK_MATCHED'::text, 'RETRY_WAIT'::text, 'UNKNOWN_REQUIRES_READBACK'::text, 'READBACK_MISMATCH'::text, 'LATER_CHANGE_OR_MISMATCH_INVESTIGATION'::text, 'MANUAL_RESOLUTION'::text, 'FAILED_FINAL'::text, 'TERMINATED_WITHOUT_PROVIDER_CALL'::text, 'COMPENSATION_PENDING'::text, 'COMPENSATED'::text, 'COMPENSATION_FAILED'::text]))),
    CONSTRAINT lc_description_command_terminal_ck CHECK (((state = ANY (ARRAY['READBACK_MATCHED'::text, 'FAILED_FINAL'::text, 'TERMINATED_WITHOUT_PROVIDER_CALL'::text, 'COMPENSATED'::text, 'COMPENSATION_FAILED'::text])) = (terminal_at IS NOT NULL)))
);

CREATE TABLE ops.lc_description_command_attempt (
    id uuid NOT NULL,
    command_id uuid NOT NULL,
    attempt_no integer NOT NULL,
    purpose text NOT NULL,
    fence_token bigint NOT NULL,
    lease_owner text NOT NULL,
    started_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    outcome_class text NOT NULL,
    native_status text,
    native_task_key text,
    raw_observation_id uuid,
    error_code text,
    correlation_id text NOT NULL,
    request_digest text NOT NULL,
    operation_snapshot jsonb NOT NULL,
    expected_version_token text,
    query_body bytea,
    query_identity jsonb,
    query_recorded_at timestamp with time zone,
    CONSTRAINT lc_description_command_attempt_completion_ck CHECK (((outcome_class = 'IN_FLIGHT'::text) = (completed_at IS NULL))),
    CONSTRAINT lc_description_command_attempt_correlation_ck CHECK (((length(btrim(correlation_id)) >= 1) AND (length(btrim(correlation_id)) <= 128))),
    CONSTRAINT lc_description_command_attempt_digest_ck CHECK ((request_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT lc_description_command_attempt_fence_ck CHECK ((fence_token > 0)),
    CONSTRAINT lc_description_command_attempt_no_ck CHECK ((attempt_no > 0)),
    CONSTRAINT lc_description_command_attempt_outcome_ck CHECK ((outcome_class = ANY (ARRAY['IN_FLIGHT'::text, 'ACCEPTED'::text, 'REJECTED'::text, 'RETRIABLE_ERROR'::text, 'TIMEOUT'::text, 'UNKNOWN_STATE'::text]))),
    CONSTRAINT lc_description_command_attempt_purpose_ck CHECK ((purpose = ANY (ARRAY['APPLY'::text, 'STATUS_ENQUIRY'::text, 'READBACK'::text, 'RESTORE'::text]))),
    CONSTRAINT lc_description_command_attempt_snapshot_ck CHECK ((jsonb_typeof(operation_snapshot) = 'object'::text)),
    CONSTRAINT lc_query_evidence_complete_ck CHECK ((((query_body IS NULL) AND (query_identity IS NULL) AND (query_recorded_at IS NULL)) OR ((purpose = 'STATUS_ENQUIRY'::text) AND (query_body IS NOT NULL) AND ((octet_length(query_body) >= 1) AND (octet_length(query_body) <= 65536)) AND (query_identity IS NOT NULL) AND (query_recorded_at IS NOT NULL))))
);

CREATE TABLE ops.lc_description_command_readback (
    id uuid NOT NULL,
    command_id uuid NOT NULL,
    attempt_id uuid NOT NULL,
    observed_at timestamp with time zone NOT NULL,
    observed_text_digest text,
    observed_kiz_marked boolean,
    match_state text NOT NULL,
    raw_observation_id uuid NOT NULL,
    correlation_id text NOT NULL,
    CONSTRAINT lc_description_command_readback_correlation_ck CHECK (((length(btrim(correlation_id)) >= 1) AND (length(btrim(correlation_id)) <= 128))),
    CONSTRAINT lc_description_command_readback_digest_ck CHECK (((observed_text_digest IS NULL) OR (observed_text_digest ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT lc_description_command_readback_match_ck CHECK ((match_state = ANY (ARRAY['MATCHES_TARGET'::text, 'MATCHES_PRIOR'::text, 'DIFFERENT'::text, 'UNREADABLE'::text]))),
    CONSTRAINT lc_description_command_readback_value_ck CHECK (((match_state = 'UNREADABLE'::text) = (observed_text_digest IS NULL)))
);

CREATE TABLE ops.lc_description_command_transition (
    from_state text NOT NULL,
    to_state text NOT NULL,
    requires_lease boolean NOT NULL,
    releases_lease boolean NOT NULL,
    note text NOT NULL,
    CONSTRAINT lc_description_command_transition_distinct_ck CHECK ((from_state <> to_state))
);

CREATE TABLE ops.lc_evaluation_plan (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    action_id uuid NOT NULL,
    calibration_package_id uuid NOT NULL,
    calibration_version integer NOT NULL,
    version_coverage jsonb NOT NULL,
    transition_handling text NOT NULL,
    latest_boundary timestamp with time zone NOT NULL,
    formal_nodes jsonb NOT NULL,
    stop_rule jsonb NOT NULL,
    critical_groups jsonb NOT NULL,
    comparison_basis text NOT NULL,
    cross_period_window_days integer NOT NULL,
    plan_digest text NOT NULL,
    frozen_at timestamp with time zone NOT NULL,
    CONSTRAINT lc_evaluation_plan_basis_ck CHECK ((comparison_basis = ANY (ARRAY['PRIOR_VERSION_WINDOW'::text, 'MATCHED_CONTROL_GROUP'::text]))),
    CONSTRAINT lc_evaluation_plan_coverage_ck CHECK ((jsonb_typeof(version_coverage) = 'object'::text)),
    CONSTRAINT lc_evaluation_plan_digest_ck CHECK ((plan_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT lc_evaluation_plan_groups_ck CHECK ((jsonb_typeof(critical_groups) = 'array'::text)),
    CONSTRAINT lc_evaluation_plan_nodes_ck CHECK (((jsonb_typeof(formal_nodes) = 'array'::text) AND ((jsonb_array_length(formal_nodes) >= 1) AND (jsonb_array_length(formal_nodes) <= 8)))),
    CONSTRAINT lc_evaluation_plan_stop_ck CHECK ((jsonb_typeof(stop_rule) = 'object'::text)),
    CONSTRAINT lc_evaluation_plan_transition_ck CHECK ((transition_handling = 'EXCLUDE_TRANSITION_DAYS'::text)),
    CONSTRAINT lc_evaluation_plan_window_ck CHECK (((cross_period_window_days >= 0) AND (cross_period_window_days <= 3660)))
);

CREATE TABLE ops.lc_execution_receipt (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    action_id uuid NOT NULL,
    command_id uuid NOT NULL,
    readback_id uuid NOT NULL,
    execution_state text NOT NULL,
    evidence jsonb NOT NULL,
    recorded_at timestamp with time zone NOT NULL,
    task_event_id uuid,
    task_recorded_at timestamp with time zone,
    CONSTRAINT lc_execution_receipt_check CHECK (((task_event_id IS NULL) = (task_recorded_at IS NULL))),
    CONSTRAINT lc_execution_receipt_evidence_check CHECK ((jsonb_typeof(evidence) = 'object'::text)),
    CONSTRAINT lc_execution_receipt_execution_state_check CHECK ((execution_state = ANY (ARRAY['MANAGEMENT_VERIFIED'::text, 'NATIVE_COMPLETION_UNPROVEN'::text])))
);

CREATE TABLE ops.lc_experience_application (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    source_action_id uuid NOT NULL,
    source_result_id uuid NOT NULL,
    target_listing_id uuid NOT NULL,
    target_affected_set_digest text NOT NULL,
    candidate_kind text NOT NULL,
    applicability_evidence_reference text CONSTRAINT lc_experience_application_applicability_evidence_refer_not_null NOT NULL,
    recorded_by_user_id uuid NOT NULL,
    recorded_at timestamp with time zone NOT NULL,
    CONSTRAINT lc_experience_application_applicability_evidence_referenc_check CHECK (((length(btrim(applicability_evidence_reference)) >= 1) AND (length(btrim(applicability_evidence_reference)) <= 512))),
    CONSTRAINT lc_experience_application_candidate_kind_check CHECK ((candidate_kind = ANY (ARRAY['CONTENT_DESCRIPTION'::text, 'OFFICIAL_PROMOTION_PARTICIPATION'::text, 'SELLER_DIRECT_DISCOUNT'::text]))),
    CONSTRAINT lc_experience_application_target_affected_set_digest_check CHECK ((target_affected_set_digest ~ '^[0-9a-f]{64}$'::text))
);

CREATE TABLE ops.lc_exposure_occupation (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    allowance_id uuid NOT NULL,
    action_id uuid NOT NULL,
    axis_code text NOT NULL,
    requested_value numeric(18,4) NOT NULL,
    occupied_value numeric(18,4) NOT NULL,
    state text NOT NULL,
    acquired_at timestamp with time zone NOT NULL,
    actualized_at timestamp with time zone,
    released_at timestamp with time zone,
    release_basis text,
    release_evidence_reference text,
    released_by_user_id uuid,
    demand_evidence jsonb,
    release_evidence_id uuid,
    release_evidence jsonb,
    CONSTRAINT lc_exposure_occupation_axis_ck CHECK ((axis_code = ANY (ARRAY['CONCURRENT_LISTINGS'::text, 'AFFECTED_VARIANTS'::text, 'REVENUE_EXPOSURE'::text, 'CATEGORY_SHARE'::text]))),
    CONSTRAINT lc_exposure_occupation_basis_ck CHECK (((release_basis IS NULL) OR (release_basis = ANY (ARRAY['STOP_EVIDENCE'::text, 'OBLIGATION_CLEARED'::text, 'NOT_APPLIED_PROVEN'::text])))),
    CONSTRAINT lc_exposure_occupation_release_ck CHECK (((state = 'RELEASED'::text) = ((released_at IS NOT NULL) AND (release_basis IS NOT NULL) AND (release_evidence_reference IS NOT NULL) AND (released_by_user_id IS NOT NULL)))),
    CONSTRAINT lc_exposure_occupation_state_ck CHECK ((state = ANY (ARRAY['ACQUIRED'::text, 'ACTUAL'::text, 'UNKNOWN'::text, 'RELEASED'::text]))),
    CONSTRAINT lc_exposure_occupation_values_ck CHECK (((requested_value >= (0)::numeric) AND (occupied_value >= (0)::numeric)))
);

COMMENT ON COLUMN ops.lc_exposure_occupation.demand_evidence IS 'Exact acquisition projection; historical NULL is retained, never fabricated.';

CREATE TABLE ops.lc_gate_authority (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    gate_kind text NOT NULL,
    platform_code text NOT NULL,
    store_id uuid NOT NULL,
    capability_code text NOT NULL,
    platform_listing_ids uuid[] NOT NULL,
    exact_head_sha text NOT NULL,
    exact_tree_sha text NOT NULL,
    owner_user_id uuid NOT NULL,
    approved_at timestamp with time zone NOT NULL,
    valid_from timestamp with time zone NOT NULL,
    valid_until timestamp with time zone NOT NULL,
    max_commands integer NOT NULL,
    evidence_reference text NOT NULL,
    controller_verdict_reference text NOT NULL,
    security_attestation_reference text NOT NULL,
    restoration_plan_reference text NOT NULL,
    production_write_enabled boolean DEFAULT false NOT NULL,
    status text NOT NULL,
    CONSTRAINT lc_gate_authority_capability_ck CHECK ((capability_code = 'listing-description-change'::text)),
    CONSTRAINT lc_gate_authority_commands_ck CHECK ((max_commands > 0)),
    CONSTRAINT lc_gate_authority_enabled_ck CHECK (((NOT production_write_enabled) OR (status = 'ACTIVE'::text))),
    CONSTRAINT lc_gate_authority_kind_ck CHECK ((gate_kind = ANY (ARRAY['GATE_EV'::text, 'GATE_E'::text]))),
    CONSTRAINT lc_gate_authority_listings_ck CHECK ((cardinality(platform_listing_ids) > 0)),
    CONSTRAINT lc_gate_authority_sha_ck CHECK (((exact_head_sha ~ '^[0-9a-f]{40}$'::text) AND (exact_tree_sha ~ '^[0-9a-f]{40}$'::text))),
    CONSTRAINT lc_gate_authority_status_ck CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'SUSPENDED'::text, 'ENDED'::text]))),
    CONSTRAINT lc_gate_authority_window_ck CHECK ((valid_until > valid_from))
);

CREATE TABLE ops.lc_isolation_dependency (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    from_listing_id uuid NOT NULL,
    to_listing_id uuid NOT NULL,
    dependency_kind text NOT NULL,
    proof_reference text NOT NULL,
    proven_at timestamp with time zone NOT NULL,
    recorded_by_user_id uuid NOT NULL,
    CONSTRAINT lc_isolation_dependency_distinct_ck CHECK ((from_listing_id <> to_listing_id)),
    CONSTRAINT lc_isolation_dependency_kind_ck CHECK ((dependency_kind = ANY (ARRAY['SHARED_TEMPLATE'::text, 'SHARED_VARIANT_SET'::text, 'SHARED_CAMPAIGN'::text]))),
    CONSTRAINT lc_isolation_dependency_proof_ck CHECK (((length(btrim(proof_reference)) >= 1) AND (length(btrim(proof_reference)) <= 512)))
);

CREATE TABLE ops.lc_late_association (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    platform_listing_id uuid NOT NULL,
    observation_id uuid NOT NULL,
    action_id uuid,
    association_kind text NOT NULL,
    operation_time timestamp with time zone,
    report_time timestamp with time zone,
    authority_gap text,
    forward_disposition text,
    closure_verification_id uuid,
    state text NOT NULL,
    recorded_by_user_id uuid NOT NULL,
    recorded_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    closure_assessment jsonb,
    CONSTRAINT lc_late_association_closure_ck CHECK (((association_kind <> 'UNRESOLVED_CHANGE'::text) OR (state <> 'CLOSED'::text) OR (closure_verification_id IS NOT NULL))),
    CONSTRAINT lc_late_association_deviation_ck CHECK (((association_kind <> 'UNAUTHORISED_DEVIATION'::text) OR ((authority_gap IS NOT NULL) AND (forward_disposition IS NOT NULL)))),
    CONSTRAINT lc_late_association_gap_ck CHECK ((((authority_gap IS NULL) OR ((length(btrim(authority_gap)) >= 1) AND (length(btrim(authority_gap)) <= 2000))) AND ((forward_disposition IS NULL) OR ((length(btrim(forward_disposition)) >= 1) AND (length(btrim(forward_disposition)) <= 2000))))),
    CONSTRAINT lc_late_association_kind_ck CHECK ((association_kind = ANY (ARRAY['LAWFUL_LATE_REPORT'::text, 'UNAUTHORISED_DEVIATION'::text, 'UNRESOLVED_CHANGE'::text]))),
    CONSTRAINT lc_late_association_lawful_ck CHECK (((association_kind <> 'LAWFUL_LATE_REPORT'::text) OR ((action_id IS NOT NULL) AND (operation_time IS NOT NULL) AND (report_time IS NOT NULL) AND (report_time >= operation_time)))),
    CONSTRAINT lc_late_association_qualified_closure_ck CHECK ((((state = 'CLOSED'::text) AND (closure_verification_id IS NOT NULL) AND ((closure_assessment ->> 'qualification'::text) = 'QUALIFIED'::text)) OR ((state <> 'CLOSED'::text) AND (closure_verification_id IS NULL)))),
    CONSTRAINT lc_late_association_state_ck CHECK ((state = ANY (ARRAY['OPEN'::text, 'LINKED'::text, 'UNDER_VERIFICATION'::text, 'CLOSED'::text]))),
    CONSTRAINT lc_late_association_unresolved_ck CHECK (((association_kind <> 'UNRESOLVED_CHANGE'::text) OR (state = ANY (ARRAY['UNDER_VERIFICATION'::text, 'CLOSED'::text]))))
);

CREATE TABLE ops.lc_launch (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    action_id uuid NOT NULL,
    binding_id uuid NOT NULL,
    plan_id uuid,
    launched_by_user_id uuid NOT NULL,
    launched_at timestamp with time zone NOT NULL,
    proof_hash text NOT NULL,
    created_transaction_id bigint DEFAULT txid_current(),
    execution_guardrail_id uuid,
    CONSTRAINT lc_launch_proof_ck CHECK ((proof_hash ~ '^[0-9a-f]{64}$'::text))
);

CREATE TABLE ops.lc_manual_packet (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    action_id uuid NOT NULL,
    launch_id uuid NOT NULL,
    executor_user_id uuid NOT NULL,
    issued_by_user_id uuid NOT NULL,
    issued_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    native_listing_key text NOT NULL,
    affected_set_digest text NOT NULL,
    target_text text,
    execution_path text NOT NULL,
    state text NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    promotion_terms_digest text,
    CONSTRAINT lc_manual_packet_digest_ck CHECK ((affected_set_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT lc_manual_packet_expiry_ck CHECK ((expires_at > issued_at)),
    CONSTRAINT lc_manual_packet_key_ck CHECK (((length(btrim(native_listing_key)) >= 1) AND (length(btrim(native_listing_key)) <= 128))),
    CONSTRAINT lc_manual_packet_path_ck CHECK ((execution_path = 'MANUAL'::text)),
    CONSTRAINT lc_manual_packet_state_ck CHECK ((state = ANY (ARRAY['ISSUED'::text, 'REPORTED'::text, 'VERIFIED'::text, 'EXPIRED'::text, 'WITHDRAWN'::text])))
);

CREATE TABLE ops.lc_manual_report (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    packet_id uuid NOT NULL,
    reporter_user_id uuid NOT NULL,
    operation_time timestamp with time zone NOT NULL,
    reported_at timestamp with time zone NOT NULL,
    report_state text NOT NULL,
    note text NOT NULL,
    operation_qualification text DEFAULT 'HISTORICAL_UNQUALIFIED'::text NOT NULL,
    deviation_reason text,
    CONSTRAINT lc_manual_report_deviation_shape_ck CHECK (((operation_qualification = 'UNAUTHORISED_DEVIATION'::text) = (deviation_reason IS NOT NULL))),
    CONSTRAINT lc_manual_report_note_ck CHECK (((length(btrim(note)) >= 1) AND (length(btrim(note)) <= 2000))),
    CONSTRAINT lc_manual_report_operation_qualification_ck CHECK ((operation_qualification = ANY (ARRAY['HISTORICAL_UNQUALIFIED'::text, 'WITHIN_PACKET_AUTHORITY'::text, 'LAWFUL_LATE_REPORT'::text, 'UNAUTHORISED_DEVIATION'::text]))),
    CONSTRAINT lc_manual_report_state_ck CHECK ((report_state = ANY (ARRAY['APPLIED'::text, 'NOT_APPLIED'::text, 'PARTIAL'::text]))),
    CONSTRAINT lc_manual_report_times_ck CHECK ((reported_at >= operation_time))
);

CREATE TABLE ops.lc_node_result (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    plan_id uuid NOT NULL,
    node_code text NOT NULL,
    stage text NOT NULL,
    revision_no integer DEFAULT 0 NOT NULL,
    measurement_id uuid,
    calculation_run_id uuid NOT NULL,
    primary_ratio numeric(9,6),
    conservative_bound numeric(9,6),
    accepted_threshold numeric(9,6) NOT NULL,
    verdict text NOT NULL,
    protection_vector jsonb NOT NULL,
    protection_verdict text NOT NULL,
    stop_triggered boolean NOT NULL,
    maturity_reached boolean NOT NULL,
    source_time timestamp with time zone,
    evaluated_at timestamp with time zone NOT NULL,
    evaluation_evidence jsonb,
    CONSTRAINT lc_node_result_evaluation_evidence_ck CHECK (((evaluation_evidence IS NULL) OR (jsonb_typeof(evaluation_evidence) = 'object'::text))),
    CONSTRAINT lc_node_result_met_ck CHECK (((verdict <> 'MET'::text) OR (conservative_bound >= accepted_threshold))),
    CONSTRAINT lc_node_result_node_ck CHECK ((node_code ~ '^[A-Z][A-Z0-9_]{1,62}$'::text)),
    CONSTRAINT lc_node_result_not_met_ck CHECK (((verdict <> 'NOT_MET'::text) OR (conservative_bound < accepted_threshold))),
    CONSTRAINT lc_node_result_protection_ck CHECK ((protection_verdict = ANY (ARRAY['PASS'::text, 'FAIL'::text, 'UNDETERMINED'::text]))),
    CONSTRAINT lc_node_result_ratio_ck CHECK ((((primary_ratio IS NULL) OR ((primary_ratio >= (0)::numeric) AND (primary_ratio <= (1)::numeric))) AND ((conservative_bound IS NULL) OR ((conservative_bound >= ('-1'::integer)::numeric) AND (conservative_bound <= (1)::numeric))))),
    CONSTRAINT lc_node_result_revision_ck CHECK ((revision_no >= 0)),
    CONSTRAINT lc_node_result_stage_ck CHECK ((stage = ANY (ARRAY['OPERATIONAL'::text, 'SETTLED'::text]))),
    CONSTRAINT lc_node_result_vector_ck CHECK (((jsonb_typeof(protection_vector) = 'object'::text) AND (protection_vector ? 'DIRECT_CONTRIBUTION_PROFIT'::text) AND (protection_vector ? 'LINKED_SCOPE_PROFIT'::text) AND (protection_vector ? 'OVERALL_RETURN_RATE'::text) AND (protection_vector ? 'CRITICAL_VARIANT_RETURN'::text) AND (protection_vector ? 'SUPPLY_COVERAGE'::text))),
    CONSTRAINT lc_node_result_verdict_ck CHECK ((verdict = ANY (ARRAY['MET'::text, 'NOT_MET'::text, 'UNDETERMINED'::text]))),
    CONSTRAINT lc_node_result_verdict_shape_ck CHECK (((verdict = 'UNDETERMINED'::text) = ((primary_ratio IS NULL) OR (conservative_bound IS NULL) OR (NOT maturity_reached))))
);

COMMENT ON COLUMN ops.lc_node_result.primary_ratio IS 'Absolute retained-purchase visit ratio from the exact target measurement.';

COMMENT ON COLUMN ops.lc_node_result.conservative_bound IS 'Qualified lower bound for target-minus-reference improvement under the frozen method; signed.';

CREATE TABLE ops.lc_outcome_revision (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    plan_id uuid NOT NULL,
    original_result_id uuid NOT NULL,
    revised_result_id uuid NOT NULL,
    revision_reason text NOT NULL,
    late_fact_reference text NOT NULL,
    recorded_at timestamp with time zone NOT NULL,
    CONSTRAINT lc_outcome_revision_distinct_ck CHECK ((original_result_id <> revised_result_id)),
    CONSTRAINT lc_outcome_revision_reason_ck CHECK ((revision_reason = ANY (ARRAY['LATE_FACT'::text, 'CORRECTION'::text]))),
    CONSTRAINT lc_outcome_revision_reference_ck CHECK (((length(btrim(late_fact_reference)) >= 1) AND (length(btrim(late_fact_reference)) <= 512)))
);

CREATE TABLE ops.lc_promotion_engagement (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    store_id uuid NOT NULL,
    platform_listing_id uuid NOT NULL,
    action_id uuid,
    engagement_kind text NOT NULL,
    native_promotion_key text,
    terms jsonb NOT NULL,
    price_freeze boolean NOT NULL,
    auto_participation boolean NOT NULL,
    terms_evidence_reference text NOT NULL,
    adopted boolean NOT NULL,
    obligations jsonb NOT NULL,
    exit_reason_code text,
    exit_authorized_by_user_id uuid,
    exit_authorized_at timestamp with time zone,
    new_transactions_stopped_at timestamp with time zone,
    obligations_cleared_at timestamp with time zone,
    state text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    terms_digest text,
    source_context_observation_id uuid,
    original_authority_reference text,
    original_authority_valid_until timestamp with time zone,
    responsible_user_id uuid,
    adoption_qualification_state text DEFAULT 'HISTORICAL_UNQUALIFIED'::text NOT NULL,
    axis_demands jsonb,
    exit_authority_reference text,
    exit_evidence_id uuid,
    exit_evidence jsonb,
    stop_evidence_observation_id uuid,
    obligation_evidence_observation_id uuid,
    CONSTRAINT lc_promotion_engagement_adoption_material_ck CHECK ((((NOT adopted) AND (adoption_qualification_state = ANY (ARRAY['HISTORICAL_UNQUALIFIED'::text, 'ACTION_AUTHORIZED'::text])) AND (num_nonnulls(source_context_observation_id, original_authority_reference, original_authority_valid_until, responsible_user_id) = 0)) OR (adopted AND (adoption_qualification_state = ANY (ARRAY['HISTORICAL_UNQUALIFIED'::text, 'FACT_RECORDED_UNQUALIFIED'::text]))) OR (adopted AND (adoption_qualification_state = 'QUALIFIED_CURRENT_STEWARDSHIP'::text) AND (source_context_observation_id IS NOT NULL) AND (original_authority_reference IS NOT NULL) AND (original_authority_valid_until IS NOT NULL) AND (responsible_user_id IS NOT NULL) AND (axis_demands IS NOT NULL)))),
    CONSTRAINT lc_promotion_engagement_adoption_qualification_ck CHECK ((adoption_qualification_state = ANY (ARRAY['HISTORICAL_UNQUALIFIED'::text, 'FACT_RECORDED_UNQUALIFIED'::text, 'QUALIFIED_CURRENT_STEWARDSHIP'::text, 'ACTION_AUTHORIZED'::text]))),
    CONSTRAINT lc_promotion_engagement_exit_reason_ck CHECK (((exit_reason_code IS NULL) OR (exit_reason_code = ANY (ARRAY['MARGIN_BELOW_BOUND'::text, 'RETURN_RATE_ABOVE_BOUND'::text, 'SUPPLY_COVERAGE_LOST'::text, 'PLATFORM_TERMS_CHANGED'::text, 'OWNER_DECISION'::text])))),
    CONSTRAINT lc_promotion_engagement_exit_shape_ck CHECK ((((exit_reason_code IS NULL) = (exit_authorized_by_user_id IS NULL)) AND ((exit_reason_code IS NULL) = (exit_authorized_at IS NULL)))),
    CONSTRAINT lc_promotion_engagement_key_ck CHECK (((native_promotion_key IS NULL) OR ((length(btrim(native_promotion_key)) >= 1) AND (length(btrim(native_promotion_key)) <= 128)))),
    CONSTRAINT lc_promotion_engagement_kind_ck CHECK ((engagement_kind = ANY (ARRAY['OFFICIAL_PROMOTION_PARTICIPATION'::text, 'SELLER_DIRECT_DISCOUNT'::text]))),
    CONSTRAINT lc_promotion_engagement_origin_ck CHECK ((adopted = (action_id IS NULL))),
    CONSTRAINT lc_promotion_engagement_reference_ck CHECK (((length(btrim(terms_evidence_reference)) >= 1) AND (length(btrim(terms_evidence_reference)) <= 512))),
    CONSTRAINT lc_promotion_engagement_release_evidence_shape_ck CHECK ((((new_transactions_stopped_at IS NULL) = (stop_evidence_observation_id IS NULL)) AND ((obligations_cleared_at IS NULL) = (obligation_evidence_observation_id IS NULL)))),
    CONSTRAINT lc_promotion_engagement_release_order_ck CHECK ((((new_transactions_stopped_at IS NULL) OR (exit_authorized_at IS NOT NULL)) AND ((obligations_cleared_at IS NULL) OR (new_transactions_stopped_at IS NOT NULL)) AND ((obligations_cleared_at IS NULL) OR (obligations_cleared_at >= new_transactions_stopped_at)))),
    CONSTRAINT lc_promotion_engagement_state_ck CHECK ((state = ANY (ARRAY['ACTIVE'::text, 'EXITING'::text, 'STOPPED'::text, 'CLEARED'::text]))),
    CONSTRAINT lc_promotion_engagement_state_shape_ck CHECK ((((state = 'ACTIVE'::text) AND (exit_authorized_at IS NULL)) OR ((state = 'EXITING'::text) AND (exit_authorized_at IS NOT NULL) AND (new_transactions_stopped_at IS NULL)) OR ((state = 'STOPPED'::text) AND (new_transactions_stopped_at IS NOT NULL) AND (obligations_cleared_at IS NULL)) OR ((state = 'CLEARED'::text) AND (obligations_cleared_at IS NOT NULL)))),
    CONSTRAINT lc_promotion_engagement_terms_ck CHECK (((jsonb_typeof(terms) = 'object'::text) AND (jsonb_typeof(obligations) = 'object'::text))),
    CONSTRAINT lc_promotion_engagement_terms_digest_ck CHECK (((terms_digest IS NULL) OR (terms_digest = ops.lc_promotion_terms_digest(jsonb_build_object('engagementKind', engagement_kind, 'nativePromotionKey', native_promotion_key, 'terms', terms, 'priceFreeze', price_freeze, 'autoParticipation', auto_participation, 'termsEvidenceReference', terms_evidence_reference, 'obligations', obligations)))))
);

CREATE TABLE ops.lc_recalculation_queue (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    platform_listing_id uuid NOT NULL,
    trigger_class text NOT NULL,
    target_minutes integer NOT NULL,
    trigger_reference text NOT NULL,
    source_time timestamp with time zone,
    accepted_at timestamp with time zone NOT NULL,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    state text NOT NULL,
    calculation_run_id uuid,
    failure_code text,
    lease_generation bigint,
    leased_until timestamp with time zone,
    health_result_id uuid,
    consumer_contract_version integer,
    measurement_result_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    binding_assessed_count integer,
    binding_invalidated_count integer,
    outcome_assessed_count integer,
    outcome_result_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    CONSTRAINT lc_recalculation_consumer_counts_ck CHECK ((((binding_assessed_count IS NULL) OR ((binding_assessed_count >= 0) AND ((binding_invalidated_count >= 0) AND (binding_invalidated_count <= binding_assessed_count)))) AND ((outcome_assessed_count IS NULL) OR ((outcome_assessed_count >= 0) AND (cardinality(outcome_result_ids) <= outcome_assessed_count))))),
    CONSTRAINT lc_recalculation_consumer_version_ck CHECK (((consumer_contract_version IS NULL) OR (consumer_contract_version = 1))),
    CONSTRAINT lc_recalculation_lease_generation_ck CHECK (((lease_generation IS NULL) OR (lease_generation > 0))),
    CONSTRAINT lc_recalculation_queue_class_ck CHECK ((trigger_class = ANY (ARRAY['RISK'::text, 'ORDINARY'::text, 'FULL_REVIEW'::text]))),
    CONSTRAINT lc_recalculation_queue_failure_ck CHECK (((state = 'FAILED'::text) = (failure_code IS NOT NULL))),
    CONSTRAINT lc_recalculation_queue_reference_ck CHECK (((length(btrim(trigger_reference)) >= 1) AND (length(btrim(trigger_reference)) <= 512))),
    CONSTRAINT lc_recalculation_queue_state_ck CHECK ((state = ANY (ARRAY['QUEUED'::text, 'RUNNING'::text, 'FINISHED'::text, 'FAILED'::text]))),
    CONSTRAINT lc_recalculation_queue_state_shape_ck CHECK ((((state = 'QUEUED'::text) AND (started_at IS NULL) AND (finished_at IS NULL)) OR ((state = 'RUNNING'::text) AND (started_at IS NOT NULL) AND (finished_at IS NULL)) OR ((state = ANY (ARRAY['FINISHED'::text, 'FAILED'::text])) AND (finished_at IS NOT NULL)))),
    CONSTRAINT lc_recalculation_queue_target_ck CHECK ((((trigger_class = 'RISK'::text) AND (target_minutes = 5)) OR ((trigger_class = 'ORDINARY'::text) AND (target_minutes = 15)) OR ((trigger_class = 'FULL_REVIEW'::text) AND (target_minutes = 60)))),
    CONSTRAINT lc_recalculation_queue_times_ck CHECK ((((started_at IS NULL) OR (started_at >= accepted_at)) AND ((finished_at IS NULL) OR ((started_at IS NOT NULL) AND (finished_at >= started_at)))))
);

CREATE TABLE ops.lc_simulation (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    candidate_id uuid NOT NULL,
    calculation_run_id uuid,
    scenario_set jsonb NOT NULL,
    inputs_digest text NOT NULL,
    results jsonb NOT NULL,
    inverse_minimum_quantity numeric(18,4),
    inverse_state text NOT NULL,
    demand_gate_passed boolean,
    computed_at timestamp with time zone NOT NULL,
    evidence_product_variant_ids uuid[],
    model_version text DEFAULT 'LEGACY_UNQUALIFIED'::text NOT NULL,
    input_snapshot jsonb,
    conditional_scenarios_passed boolean,
    CONSTRAINT lc_simulation_basis_ck CHECK (((((model_version = 'LEGACY_UNQUALIFIED'::text) AND (calculation_run_id IS NOT NULL) AND (input_snapshot IS NULL) AND (conditional_scenarios_passed IS NULL)) OR ((model_version = 'LC_CONDITIONAL_PROFIT_2'::text) AND (calculation_run_id IS NULL) AND (demand_gate_passed IS NULL) AND (input_snapshot IS NOT NULL) AND (jsonb_typeof(input_snapshot) = 'object'::text) AND (octet_length((input_snapshot)::text) <= 524288) AND (inputs_digest = encode(sha256(convert_to((input_snapshot)::text, 'UTF8'::name)), 'hex'::text)) AND ((input_snapshot ->> 'sourceKind'::text) = ANY (ARRAY['CALLER_ASSUMPTIONS'::text, 'DECLARED_CONDITIONAL_INPUTS'::text, 'QUALIFIED_MATCHED_INPUTS'::text])) AND ((input_snapshot ->> 'qualificationState'::text) = ANY (ARRAY['UNQUALIFIED'::text, 'QUALIFIED_CONDITIONAL_ECONOMICS'::text])) AND (((input_snapshot ->> 'sourceKind'::text) = 'QUALIFIED_MATCHED_INPUTS'::text) = ((input_snapshot ->> 'qualificationState'::text) = 'QUALIFIED_CONDITIONAL_ECONOMICS'::text)) AND ((input_snapshot ->> 'modelVersion'::text) = model_version) AND ((input_snapshot ->> 'candidateId'::text) = (candidate_id)::text) AND ((input_snapshot ->> 'organizationId'::text) = (organization_id)::text) AND (jsonb_typeof((input_snapshot -> 'inputs'::text)) = 'object'::text) AND (jsonb_typeof((input_snapshot -> 'context'::text)) = 'object'::text) AND (jsonb_typeof((input_snapshot -> 'scenarios'::text)) = 'array'::text) AND (((input_snapshot ->> 'qualificationState'::text) <> 'QUALIFIED_CONDITIONAL_ECONOMICS'::text) OR ((conditional_scenarios_passed IS TRUE) AND (cardinality(evidence_product_variant_ids) > 0) AND ((input_snapshot ->> 'purposeCode'::text) = ANY (ARRAY['PROMOTION'::text, 'BOUNDED_EXPLORATION'::text])) AND ((input_snapshot ->> 'nativeUniverseQualification'::text) = 'COMPLETE_IDENTITY_SOURCE'::text) AND ((input_snapshot #>> '{knownPromotionContext,coverage}'::text[]) = 'QUALIFIED_COMPLETE'::text) AND ((input_snapshot #>> '{knownPromotionContext,digest}'::text[]) ~ '^[0-9a-f]{64}$'::text) AND ((input_snapshot #>> '{variableFeeEvidence,state}'::text[]) = 'VARIABLE_FEES_MATCH_PROFILE'::text) AND ((input_snapshot #>> '{fixedFeeEvidence,state}'::text[]) = 'ACTIVITY_FIXED_FEE_MATCH'::text) AND ((input_snapshot #>> '{revenueEvidence,state}'::text[]) = 'COMMERCIAL_REVENUE_MATCH'::text) AND ((input_snapshot #>> '{currentCostEvidence,state}'::text[]) = 'PERIOD_MEMBER_COST_BOUND'::text) AND ((input_snapshot #>> '{demandEvidence,state}'::text[]) = 'ACCEPTED_NECESSARY_SCENARIOS_MATCH'::text) AND ((input_snapshot #>> '{profitReferenceEvidence,state}'::text[]) = 'ACCEPTED_PROFIT_REFERENCE_BOUND'::text) AND ((input_snapshot #>> '{demandEvidence,packageId}'::text[]) = (input_snapshot #>> '{profitReferenceEvidence,packageId}'::text[])) AND ((input_snapshot #>> '{demandEvidence,packageVersion}'::text[]) = (input_snapshot #>> '{profitReferenceEvidence,packageVersion}'::text[])))))) IS TRUE)),
    CONSTRAINT lc_simulation_digest_ck CHECK ((inputs_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT lc_simulation_evidence_scope_ck CHECK (((evidence_product_variant_ids IS NULL) OR ((cardinality(evidence_product_variant_ids) > 0) AND (array_position(evidence_product_variant_ids, NULL::uuid) IS NULL)))),
    CONSTRAINT lc_simulation_inverse_ck CHECK ((inverse_state = ANY (ARRAY['COMPUTED'::text, 'NO_SOLUTION'::text, 'UNDETERMINED'::text]))),
    CONSTRAINT lc_simulation_inverse_shape_ck CHECK (((inverse_state = 'COMPUTED'::text) = (inverse_minimum_quantity IS NOT NULL))),
    CONSTRAINT lc_simulation_quantity_ck CHECK (((inverse_minimum_quantity IS NULL) OR (inverse_minimum_quantity >= (0)::numeric))),
    CONSTRAINT lc_simulation_results_ck CHECK ((jsonb_typeof(results) = 'array'::text)),
    CONSTRAINT lc_simulation_scenarios_ck CHECK ((jsonb_typeof(scenario_set) = 'array'::text))
);

CREATE TABLE ops.lc_task_deferral (
    id uuid NOT NULL,
    task_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    requester_user_id uuid NOT NULL,
    defer_minutes integer NOT NULL,
    reason text NOT NULL,
    requested_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    basis_digest text NOT NULL,
    state text NOT NULL,
    ended_at timestamp with time zone,
    review_health_id uuid,
    review_queue_id uuid,
    CONSTRAINT lc_task_deferral_basis_digest_check CHECK ((basis_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT lc_task_deferral_check CHECK ((isfinite(requested_at) AND isfinite(expires_at) AND (expires_at > requested_at))),
    CONSTRAINT lc_task_deferral_check1 CHECK (((state = 'ACTIVE'::text) = (ended_at IS NULL))),
    CONSTRAINT lc_task_deferral_check2 CHECK (((state <> 'INVALIDATED'::text) OR (review_health_id IS NOT NULL))),
    CONSTRAINT lc_task_deferral_check3 CHECK (((ended_at IS NULL) OR (ended_at >= requested_at))),
    CONSTRAINT lc_task_deferral_defer_minutes_check CHECK ((defer_minutes > 0)),
    CONSTRAINT lc_task_deferral_reason_check CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 512))),
    CONSTRAINT lc_task_deferral_state_check CHECK ((state = ANY (ARRAY['ACTIVE'::text, 'EXPIRED'::text, 'INVALIDATED'::text])))
);

CREATE TABLE ops.lc_task_dependency_hold (
    id uuid NOT NULL,
    task_id uuid NOT NULL,
    dependency_task_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    requester_user_id uuid NOT NULL,
    hold_minutes integer NOT NULL,
    evidence_reference text NOT NULL,
    collaboration_link_id uuid NOT NULL,
    started_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    state text NOT NULL,
    ended_at timestamp with time zone,
    end_reason text,
    review_queue_id uuid,
    CONSTRAINT lc_task_dependency_hold_check CHECK (((task_id <> dependency_task_id) AND (expires_at > started_at))),
    CONSTRAINT lc_task_dependency_hold_check1 CHECK (((state = 'ACTIVE'::text) = (ended_at IS NULL))),
    CONSTRAINT lc_task_dependency_hold_check2 CHECK (((state = 'ACTIVE'::text) = (end_reason IS NULL))),
    CONSTRAINT lc_task_dependency_hold_check3 CHECK (((state = 'ACTIVE'::text) = (review_queue_id IS NULL))),
    CONSTRAINT lc_task_dependency_hold_check4 CHECK (((ended_at IS NULL) OR ((ended_at >= started_at) AND (ended_at <= expires_at)))),
    CONSTRAINT lc_task_dependency_hold_evidence_reference_check CHECK (((length(btrim(evidence_reference)) >= 1) AND (length(btrim(evidence_reference)) <= 512))),
    CONSTRAINT lc_task_dependency_hold_hold_minutes_check CHECK ((hold_minutes > 0)),
    CONSTRAINT lc_task_dependency_hold_state_check CHECK ((state = ANY (ARRAY['ACTIVE'::text, 'RESUMED'::text, 'EXPIRED'::text, 'INVALIDATED'::text])))
);

CREATE TABLE ops.lc_task_responsibility (
    task_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    recommendation_id uuid,
    calibration_package_id uuid,
    calibration_version integer,
    first_raised_at timestamp with time zone NOT NULL,
    slo_snapshot jsonb NOT NULL,
    coverage_snapshot jsonb NOT NULL,
    basis_digest text NOT NULL,
    clock_state text NOT NULL,
    acknowledgement_due_at timestamp with time zone,
    action_due_at timestamp with time zone,
    outcome_maturity_due_at timestamp with time zone,
    recorded_at timestamp with time zone NOT NULL,
    source_health_id uuid,
    platform_listing_id uuid,
    cause_code text,
    responsibility_lane text GENERATED ALWAYS AS (
CASE
    WHEN (source_health_id IS NULL) THEN 'ACTION'::text
    WHEN (cause_code = ANY (ARRAY['AFFECTED_SET_COMPLETE'::text, 'MAPPING_RESOLVED'::text, 'DESCRIPTION_OBSERVED'::text, 'NOT_CONTAINED'::text, 'CALIBRATION_RESOLVED'::text])) THEN 'NECESSARY_RISK'::text
    ELSE 'QUALIFIED_OPPORTUNITY'::text
END) STORED,
    CONSTRAINT lc_task_diagnostic_clock_kind CHECK ((((responsibility_lane = 'ACTION'::text) AND (clock_state <> 'CONTINUOUS_RISK'::text)) OR ((responsibility_lane = 'NECESSARY_RISK'::text) AND (clock_state = ANY (ARRAY['SLO_UNRESOLVED'::text, 'CONTINUOUS_RISK'::text]))) OR ((responsibility_lane = 'QUALIFIED_OPPORTUNITY'::text) AND (clock_state = ANY (ARRAY['SLO_UNRESOLVED'::text, 'COVERAGE_UNRESOLVED'::text, 'COVERAGE_CONFIGURED'::text]))))),
    CONSTRAINT lc_task_diagnostic_identity CHECK ((((source_health_id IS NULL) AND (platform_listing_id IS NULL) AND (cause_code IS NULL) AND (recommendation_id IS NOT NULL)) OR ((source_health_id IS NOT NULL) AND (platform_listing_id IS NOT NULL) AND (recommendation_id IS NULL) AND (cause_code = ANY (ARRAY['AFFECTED_SET_COMPLETE'::text, 'MAPPING_RESOLVED'::text, 'DESCRIPTION_OBSERVED'::text, 'NOT_CONTAINED'::text, 'CALIBRATION_RESOLVED'::text, 'DESCRIPTION_NOT_RUSSIAN'::text, 'KIZ_MARKING_UNDECLARED'::text, 'SOURCE_STRATIFICATION_MISSING'::text, 'NOT_SELLABLE_AT_LAST_OBSERVATION'::text, 'FEEDBACK_THEMES_PRESENT'::text]))))),
    CONSTRAINT lc_task_responsibility_basis_digest_check CHECK ((basis_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT lc_task_responsibility_check CHECK (((calibration_package_id IS NULL) = (calibration_version IS NULL))),
    CONSTRAINT lc_task_responsibility_check1 CHECK (((jsonb_typeof(slo_snapshot) = 'object'::text) AND (jsonb_typeof(coverage_snapshot) = 'object'::text))),
    CONSTRAINT lc_task_responsibility_check3 CHECK (((clock_state <> 'SLO_UNRESOLVED'::text) OR (outcome_maturity_due_at IS NULL))),
    CONSTRAINT lc_task_responsibility_check4 CHECK (((acknowledgement_due_at IS NULL) OR (acknowledgement_due_at > first_raised_at))),
    CONSTRAINT lc_task_responsibility_check5 CHECK (((action_due_at IS NULL) OR (action_due_at > first_raised_at))),
    CONSTRAINT lc_task_responsibility_check6 CHECK (((outcome_maturity_due_at IS NULL) OR (outcome_maturity_due_at > first_raised_at))),
    CONSTRAINT lc_task_responsibility_check7 CHECK ((recorded_at >= first_raised_at)),
    CONSTRAINT lc_task_responsibility_clock_state_check CHECK ((clock_state = ANY (ARRAY['SLO_UNRESOLVED'::text, 'COVERAGE_UNRESOLVED'::text, 'COVERAGE_CONFIGURED'::text, 'CONTINUOUS_RISK'::text]))),
    CONSTRAINT lc_task_responsibility_deadline_state CHECK (((clock_state = ANY (ARRAY['COVERAGE_CONFIGURED'::text, 'CONTINUOUS_RISK'::text])) = ((acknowledgement_due_at IS NOT NULL) AND (action_due_at IS NOT NULL))))
);

CREATE TABLE ops.metadata_audit_event (
    id uuid NOT NULL,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    actor_type text NOT NULL,
    actor_id text NOT NULL,
    source_domain text NOT NULL,
    action text NOT NULL,
    entity_type text,
    entity_id uuid,
    entity_code text,
    change_summary jsonb,
    denial_code text,
    reason text,
    correlation_id text NOT NULL,
    evidence_ref text,
    CONSTRAINT metadata_audit_event_action_ck CHECK ((action = ANY (ARRAY['READ'::text, 'CREATE'::text, 'UPDATE'::text, 'STATUS_CHANGE'::text, 'GRANT'::text, 'REVOKE'::text, 'VERIFICATION_CHANGE'::text, 'DENIED'::text, 'IMPORT'::text, 'MAPPING_DECISION'::text, 'APPROVAL_DECISION'::text, 'POLICY_CHANGE'::text, 'COMMAND_TRANSITION'::text, 'KILL_SWITCH'::text, 'AI_INVOCATION'::text, 'EXPORT'::text]))),
    CONSTRAINT metadata_audit_event_actor_id_ck CHECK ((actor_id ~ '^[a-z0-9][a-z0-9._-]{0,63}$'::text)),
    CONSTRAINT metadata_audit_event_actor_type_ck CHECK ((actor_type = ANY (ARRAY['OPERATOR'::text, 'SYSTEM'::text]))),
    CONSTRAINT metadata_audit_event_denial_code_ck CHECK (((action <> 'DENIED'::text) OR (denial_code IS NOT NULL))),
    CONSTRAINT metadata_audit_event_entity_ck CHECK (((action = 'DENIED'::text) OR ((entity_type IS NOT NULL) AND (entity_id IS NOT NULL)))),
    CONSTRAINT metadata_audit_event_source_domain_ck CHECK ((source_domain = ANY (ARRAY['organizationaccount'::text, 'identityaccess'::text, 'marketplaceintegration'::text, 'adminobservability'::text, 'productlisting'::text, 'operatingfacts'::text, 'analyticsdecision'::text, 'aicopilot'::text, 'operationsworkflow'::text, 'availabilityrisk'::text, 'advertisingefficiency'::text, 'listingconversion'::text])))
);

CREATE TABLE ops.pilot_allowlist_entry (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    action_kind text CONSTRAINT pilot_allowlist_entry_capability_code_not_null NOT NULL,
    platform_code text NOT NULL,
    store_id uuid NOT NULL,
    platform_listing_variant_id uuid,
    valid_from timestamp with time zone NOT NULL,
    valid_until timestamp with time zone NOT NULL,
    status text NOT NULL,
    granted_by_user_id uuid NOT NULL,
    reason text NOT NULL,
    revoked_reason text,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    ad_native_object_id uuid,
    platform_listing_id uuid,
    CONSTRAINT pilot_allowlist_entry_action_kind_ck CHECK ((action_kind = ANY (ARRAY['PRICE_CHANGE'::text, 'AD_BID_CHANGE'::text, 'LISTING_DESCRIPTION_CHANGE'::text]))),
    CONSTRAINT pilot_allowlist_entry_entity_shape_ck CHECK ((((action_kind <> 'AD_BID_CHANGE'::text) OR ((ad_native_object_id IS NOT NULL) AND (platform_listing_variant_id IS NULL) AND (platform_listing_id IS NULL))) AND ((action_kind <> 'PRICE_CHANGE'::text) OR ((ad_native_object_id IS NULL) AND (platform_listing_id IS NULL))) AND ((action_kind <> 'LISTING_DESCRIPTION_CHANGE'::text) OR ((platform_listing_id IS NOT NULL) AND (platform_listing_variant_id IS NULL) AND (ad_native_object_id IS NULL))))),
    CONSTRAINT pilot_allowlist_entry_revoked_ck CHECK (((status <> 'REVOKED'::text) OR (revoked_reason IS NOT NULL))),
    CONSTRAINT pilot_allowlist_entry_status_ck CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'EXPIRED'::text, 'REVOKED'::text]))),
    CONSTRAINT pilot_allowlist_entry_validity_ck CHECK ((valid_from < valid_until))
);

CREATE TABLE ops.policy_authorization (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    policy_id uuid NOT NULL,
    action_kind text NOT NULL,
    scope_kind text NOT NULL,
    store_ref_id uuid,
    product_variant_ref_id uuid,
    max_change_rate numeric(9,6) NOT NULL,
    max_uses integer NOT NULL,
    used_count integer DEFAULT 0 NOT NULL,
    valid_from timestamp with time zone NOT NULL,
    valid_until timestamp with time zone NOT NULL,
    status text NOT NULL,
    granted_by_user_id uuid NOT NULL,
    reason text NOT NULL,
    revoked_reason text,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT policy_authorization_action_ck CHECK ((action_kind = ANY (ARRAY['PRICE_CHANGE'::text, 'AD_BID_CHANGE'::text]))),
    CONSTRAINT policy_authorization_rate_ck CHECK (((max_change_rate > (0)::numeric) AND (max_change_rate <= (1)::numeric))),
    CONSTRAINT policy_authorization_revoked_ck CHECK (((status <> 'REVOKED'::text) OR (revoked_reason IS NOT NULL))),
    CONSTRAINT policy_authorization_scope_ck CHECK ((scope_kind = ANY (ARRAY['STORE'::text, 'PRODUCT_VARIANT'::text]))),
    CONSTRAINT policy_authorization_scope_matrix_ck CHECK ((((scope_kind = 'STORE'::text) AND (store_ref_id IS NOT NULL) AND (product_variant_ref_id IS NULL)) OR ((scope_kind = 'PRODUCT_VARIANT'::text) AND (product_variant_ref_id IS NOT NULL) AND (store_ref_id IS NULL)))),
    CONSTRAINT policy_authorization_status_ck CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'EXHAUSTED'::text, 'EXPIRED'::text, 'REVOKED'::text]))),
    CONSTRAINT policy_authorization_uses_ck CHECK (((max_uses > 0) AND (used_count >= 0) AND (used_count <= max_uses))),
    CONSTRAINT policy_authorization_validity_ck CHECK ((valid_from < valid_until))
);

CREATE TABLE ops.policy_limit_kind (
    code text NOT NULL,
    display_name text NOT NULL,
    value_kind text NOT NULL,
    guardrail_code text NOT NULL,
    required_for_price_write boolean NOT NULL,
    ordinal integer NOT NULL,
    CONSTRAINT policy_limit_kind_code_ck CHECK ((code ~ '^[A-Z][A-Z0-9_]{1,62}$'::text)),
    CONSTRAINT policy_limit_kind_guardrail_ck CHECK ((guardrail_code ~ '^[A-Z][A-Z0-9_]{1,62}$'::text)),
    CONSTRAINT policy_limit_kind_value_ck CHECK ((value_kind = ANY (ARRAY['RATE'::text, 'AMOUNT'::text, 'COUNT'::text, 'DURATION_SECONDS'::text])))
);

CREATE TABLE ops.price_command (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    recommendation_id uuid NOT NULL,
    approval_decision_id uuid NOT NULL,
    store_id uuid NOT NULL,
    platform_listing_variant_id uuid NOT NULL,
    platform_code text NOT NULL,
    capability_id uuid NOT NULL,
    idempotency_key text NOT NULL,
    currency_code text NOT NULL,
    prior_price numeric(18,4) NOT NULL,
    target_price numeric(18,4) NOT NULL,
    prior_price_observation_id uuid NOT NULL,
    entity_version_digest text NOT NULL,
    authority_snapshot jsonb NOT NULL,
    requested_operation text,
    state text NOT NULL,
    attempt_no integer DEFAULT 0 NOT NULL,
    retry_budget_remaining integer NOT NULL,
    fence_token bigint DEFAULT 1 NOT NULL,
    lease_owner text,
    lease_expires_at timestamp with time zone,
    next_attempt_at timestamp with time zone,
    failure_code text,
    terminal_at timestamp with time zone,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    fulfillment_mode_code text,
    CONSTRAINT price_command_attempt_ck CHECK ((attempt_no >= 0)),
    CONSTRAINT price_command_change_ck CHECK ((target_price <> prior_price)),
    CONSTRAINT price_command_currency_ck CHECK ((currency_code ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT price_command_digest_ck CHECK ((entity_version_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT price_command_failure_ck CHECK (((state <> ALL (ARRAY['FAILED_FINAL'::text, 'COMPENSATION_FAILED'::text])) OR (failure_code IS NOT NULL))),
    CONSTRAINT price_command_fence_ck CHECK ((fence_token > 0)),
    CONSTRAINT price_command_idempotency_ck CHECK ((idempotency_key ~ '^[a-z0-9][a-z0-9._-]{15,127}$'::text)),
    CONSTRAINT price_command_lease_pairing_ck CHECK ((num_nonnulls(lease_owner, lease_expires_at) <> 1)),
    CONSTRAINT price_command_leased_state_ck CHECK (((state <> ALL (ARRAY['LEASED'::text, 'EXECUTING'::text, 'PLATFORM_PENDING'::text, 'READBACK_PENDING'::text])) OR (lease_owner IS NOT NULL))),
    CONSTRAINT price_command_prior_price_ck CHECK ((prior_price > (0)::numeric)),
    CONSTRAINT price_command_requested_operation_check CHECK ((requested_operation = 'READBACK'::text)),
    CONSTRAINT price_command_retry_budget_ck CHECK ((retry_budget_remaining >= 0)),
    CONSTRAINT price_command_state_ck CHECK ((state = ANY (ARRAY['PENDING'::text, 'LEASED'::text, 'EXECUTING'::text, 'PLATFORM_PENDING'::text, 'READBACK_PENDING'::text, 'SUCCEEDED'::text, 'RETRY_WAIT'::text, 'UNKNOWN_REQUIRES_READBACK'::text, 'READBACK_MISMATCH'::text, 'MANUAL_RESOLUTION'::text, 'FAILED_FINAL'::text, 'COMPENSATION_PENDING'::text, 'COMPENSATED'::text, 'COMPENSATION_FAILED'::text]))),
    CONSTRAINT price_command_target_price_ck CHECK ((target_price > (0)::numeric)),
    CONSTRAINT price_command_terminal_ck CHECK (((state = ANY (ARRAY['SUCCEEDED'::text, 'FAILED_FINAL'::text, 'COMPENSATED'::text, 'COMPENSATION_FAILED'::text])) = (terminal_at IS NOT NULL)))
);

CREATE TABLE ops.price_command_attempt (
    id uuid NOT NULL,
    command_id uuid NOT NULL,
    attempt_no integer NOT NULL,
    purpose text NOT NULL,
    fence_token bigint NOT NULL,
    lease_owner text NOT NULL,
    started_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    outcome_class text NOT NULL,
    native_status text,
    native_task_key text,
    raw_observation_id uuid,
    error_code text,
    correlation_id text NOT NULL,
    request_digest text NOT NULL,
    operation_snapshot jsonb NOT NULL,
    expected_version_token text,
    CONSTRAINT price_command_attempt_completion_ck CHECK (((outcome_class = 'IN_FLIGHT'::text) = (completed_at IS NULL))),
    CONSTRAINT price_command_attempt_fence_ck CHECK ((fence_token > 0)),
    CONSTRAINT price_command_attempt_no_ck CHECK ((attempt_no > 0)),
    CONSTRAINT price_command_attempt_outcome_ck CHECK ((outcome_class = ANY (ARRAY['IN_FLIGHT'::text, 'ACCEPTED'::text, 'REJECTED'::text, 'RETRIABLE_ERROR'::text, 'TIMEOUT'::text, 'UNKNOWN_STATE'::text]))),
    CONSTRAINT price_command_attempt_purpose_ck CHECK ((purpose = ANY (ARRAY['APPLY'::text, 'STATUS_ENQUIRY'::text, 'READBACK'::text, 'RESTORE'::text]))),
    CONSTRAINT price_command_attempt_request_digest_check CHECK ((request_digest ~ '^[0-9a-f]{64}$'::text))
);

CREATE TABLE ops.price_command_readback (
    id uuid NOT NULL,
    command_id uuid NOT NULL,
    attempt_id uuid NOT NULL,
    observed_at timestamp with time zone NOT NULL,
    observed_price numeric(18,4),
    currency_code text,
    match_state text NOT NULL,
    raw_observation_id uuid NOT NULL,
    correlation_id text NOT NULL,
    CONSTRAINT price_command_readback_currency_ck CHECK (((currency_code IS NULL) OR (currency_code ~ '^[A-Z]{3}$'::text))),
    CONSTRAINT price_command_readback_match_ck CHECK ((match_state = ANY (ARRAY['MATCHES_TARGET'::text, 'MATCHES_PRIOR'::text, 'DIFFERENT'::text, 'UNREADABLE'::text]))),
    CONSTRAINT price_command_readback_price_ck CHECK (((observed_price IS NULL) OR (observed_price > (0)::numeric))),
    CONSTRAINT price_command_readback_value_ck CHECK (((match_state = 'UNREADABLE'::text) = ((observed_price IS NULL) AND (currency_code IS NULL))))
);

CREATE TABLE ops.price_command_transition (
    from_state text NOT NULL,
    to_state text NOT NULL,
    requires_lease boolean NOT NULL,
    releases_lease boolean NOT NULL,
    note text NOT NULL,
    CONSTRAINT price_command_transition_distinct_ck CHECK ((from_state <> to_state))
);

CREATE TABLE ops.recommendation (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    store_id uuid NOT NULL,
    subject_kind text NOT NULL,
    subject_id uuid NOT NULL,
    action_kind text NOT NULL,
    origin text NOT NULL,
    ai_invocation_id uuid,
    calculation_run_id uuid NOT NULL,
    window_code text NOT NULL,
    state text NOT NULL,
    priority_score numeric(9,4) NOT NULL,
    proposed_parameters jsonb NOT NULL,
    expected_effect jsonb NOT NULL,
    risk_label text NOT NULL,
    validation_horizon_days integer NOT NULL,
    entity_version_digest text NOT NULL,
    valid_until timestamp with time zone NOT NULL,
    terminal_reason text,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT recommendation_action_ck CHECK ((action_kind = ANY (ARRAY['PRICE_CHANGE'::text, 'AD_BID_CHANGE'::text, 'RESOLVE_MAPPING'::text, 'RESTOCK_REVIEW'::text, 'LISTING_CONTENT_REVIEW'::text, 'ADVERTISING_REVIEW'::text, 'COST_DATA_REVIEW'::text, 'LISTING_DESCRIPTION_CHANGE'::text, 'LISTING_PROMOTION_ACTION'::text]))),
    CONSTRAINT recommendation_action_subject_ck CHECK ((((action_kind <> 'AD_BID_CHANGE'::text) OR (subject_kind = 'AD_NATIVE_OBJECT'::text)) AND ((action_kind <> 'PRICE_CHANGE'::text) OR (subject_kind = 'PLATFORM_LISTING_VARIANT'::text)) AND ((subject_kind <> 'AD_NATIVE_OBJECT'::text) OR (action_kind = ANY (ARRAY['AD_BID_CHANGE'::text, 'ADVERTISING_REVIEW'::text]))) AND ((action_kind <> ALL (ARRAY['LISTING_DESCRIPTION_CHANGE'::text, 'LISTING_PROMOTION_ACTION'::text])) OR (subject_kind = 'PLATFORM_LISTING'::text)) AND ((subject_kind <> 'PLATFORM_LISTING'::text) OR (action_kind = ANY (ARRAY['LISTING_DESCRIPTION_CHANGE'::text, 'LISTING_PROMOTION_ACTION'::text]))))),
    CONSTRAINT recommendation_ai_presence_ck CHECK (((origin = 'AI_ASSISTED'::text) = (ai_invocation_id IS NOT NULL))),
    CONSTRAINT recommendation_digest_ck CHECK ((entity_version_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT recommendation_effect_ck CHECK ((jsonb_typeof(expected_effect) = 'object'::text)),
    CONSTRAINT recommendation_horizon_ck CHECK (((validation_horizon_days >= 1) AND (validation_horizon_days <= 90))),
    CONSTRAINT recommendation_origin_ck CHECK ((origin = ANY (ARRAY['DETERMINISTIC'::text, 'AI_ASSISTED'::text]))),
    CONSTRAINT recommendation_parameters_ck CHECK ((jsonb_typeof(proposed_parameters) = 'object'::text)),
    CONSTRAINT recommendation_priority_ck CHECK (((priority_score >= (0)::numeric) AND (priority_score <= (1000)::numeric))),
    CONSTRAINT recommendation_risk_ck CHECK ((risk_label = ANY (ARRAY['LOW'::text, 'MEDIUM'::text, 'HIGH'::text]))),
    CONSTRAINT recommendation_state_ck CHECK ((state = ANY (ARRAY['DRAFT'::text, 'VALIDATED'::text, 'READY_FOR_REVIEW'::text, 'TASK_ONLY'::text, 'APPROVED'::text, 'POLICY_AUTHORIZED'::text, 'REJECTED'::text, 'EXPIRED'::text, 'CANCELLED'::text, 'COMMAND_CREATED'::text, 'EXECUTION_TRACKING'::text, 'OUTCOME_OBSERVATION'::text, 'CLOSED'::text]))),
    CONSTRAINT recommendation_subject_ck CHECK ((subject_kind = ANY (ARRAY['PRODUCT_VARIANT'::text, 'PLATFORM_LISTING_VARIANT'::text, 'STORE'::text, 'AD_NATIVE_OBJECT'::text, 'PLATFORM_LISTING'::text]))),
    CONSTRAINT recommendation_terminal_reason_ck CHECK (((state <> ALL (ARRAY['REJECTED'::text, 'EXPIRED'::text, 'CANCELLED'::text])) OR (terminal_reason IS NOT NULL))),
    CONSTRAINT recommendation_validity_ck CHECK ((valid_until > created_at)),
    CONSTRAINT recommendation_window_ck CHECK ((window_code = ANY (ARRAY['D7'::text, 'D14'::text, 'D30'::text])))
);

CREATE TABLE ops.recommendation_evidence (
    id uuid NOT NULL,
    recommendation_id uuid NOT NULL,
    metric_value_id uuid,
    finding_id uuid,
    ai_claim_id uuid,
    role text NOT NULL,
    CONSTRAINT recommendation_evidence_one_target_ck CHECK ((num_nonnulls(metric_value_id, finding_id, ai_claim_id) = 1)),
    CONSTRAINT recommendation_evidence_role_ck CHECK ((role = ANY (ARRAY['PRIMARY_CAUSE'::text, 'SUPPORTING'::text, 'COUNTER_EVIDENCE'::text, 'UNKNOWN_GAP'::text])))
);

CREATE TABLE ops.work_task (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    recommendation_id uuid,
    title text NOT NULL,
    state text NOT NULL,
    assignee_user_id uuid,
    due_at timestamp with time zone,
    closed_at timestamp with time zone,
    closure_reason text,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    first_raised_at timestamp with time zone NOT NULL,
    CONSTRAINT work_task_assignment_ck CHECK (((state <> ALL (ARRAY['ASSIGNED'::text, 'IN_PROGRESS'::text])) OR (assignee_user_id IS NOT NULL))),
    CONSTRAINT work_task_closure_ck CHECK (((state = ANY (ARRAY['DONE'::text, 'CANCELLED'::text])) = ((closed_at IS NOT NULL) AND (closure_reason IS NOT NULL)))),
    CONSTRAINT work_task_first_raised_ck CHECK ((first_raised_at <= created_at)),
    CONSTRAINT work_task_state_ck CHECK ((state = ANY (ARRAY['OPEN'::text, 'ASSIGNED'::text, 'IN_PROGRESS'::text, 'DONE'::text, 'CANCELLED'::text])))
);

CREATE TABLE ops.work_task_event (
    id uuid NOT NULL,
    task_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    sequence_no integer NOT NULL,
    event_kind text NOT NULL,
    lineage_key text NOT NULL,
    action_kind text,
    action_evidence jsonb,
    evidence_reference text,
    outcome_kind text,
    outcome_reference text,
    from_assignee_user_id uuid,
    to_assignee_user_id uuid,
    actor_user_id uuid,
    actor_role_code text,
    reason text NOT NULL,
    occurred_at timestamp with time zone NOT NULL,
    correlation_id text NOT NULL,
    execution_receipt_id uuid,
    CONSTRAINT work_task_event_acknowledgement_shape_ck CHECK (((event_kind <> 'ACKNOWLEDGED'::text) OR ((actor_user_id IS NOT NULL) AND (action_kind IS NULL) AND (outcome_kind IS NULL)))),
    CONSTRAINT work_task_event_action_exclusive_ck CHECK (((event_kind = 'ACTION_RECORDED'::text) OR ((action_kind IS NULL) AND (action_evidence IS NULL)))),
    CONSTRAINT work_task_event_action_kind_ck CHECK (((action_kind IS NULL) OR (action_kind = ANY (ARRAY['DECISION_SUBMITTED_FOR_APPROVAL'::text, 'DECISION_ENDORSED'::text, 'DECISION_APPROVED'::text, 'DECISION_REJECTED'::text, 'MANUAL_PACKET_ISSUED'::text, 'MANUAL_EXECUTION_VERIFIED'::text, 'DATA_OR_MAPPING_REPAIR'::text, 'EXCEPTION_REQUESTED'::text, 'COMPENSATION_REQUESTED'::text, 'ACTION_LAUNCHED'::text, 'MANUAL_EXECUTION_REPORTED'::text, 'CONTAINMENT_RECORDED'::text, 'LATE_ASSOCIATION_RECORDED'::text, 'COLLABORATION_HANDOVER'::text, 'EVIDENCE_RETURNED'::text])))),
    CONSTRAINT work_task_event_action_shape_ck CHECK (((event_kind <> 'ACTION_RECORDED'::text) OR ((action_kind IS NOT NULL) AND (action_evidence IS NOT NULL) AND (jsonb_typeof(action_evidence) = 'object'::text) AND (action_evidence ? 'reference'::text) AND (evidence_reference IS NOT NULL) AND (actor_user_id IS NOT NULL)))),
    CONSTRAINT work_task_event_assignment_shape_ck CHECK ((((event_kind <> ALL (ARRAY['ASSIGNED'::text, 'REASSIGNED'::text])) AND (from_assignee_user_id IS NULL) AND (to_assignee_user_id IS NULL)) OR ((event_kind = 'ASSIGNED'::text) AND (to_assignee_user_id IS NOT NULL) AND (from_assignee_user_id IS NULL)) OR ((event_kind = 'REASSIGNED'::text) AND (to_assignee_user_id IS NOT NULL) AND (from_assignee_user_id IS NOT NULL) AND (from_assignee_user_id <> to_assignee_user_id)))),
    CONSTRAINT work_task_event_correlation_ck CHECK (((length(btrim(correlation_id)) >= 1) AND (length(btrim(correlation_id)) <= 128))),
    CONSTRAINT work_task_event_evidence_ck CHECK (((evidence_reference IS NULL) OR ((length(btrim(evidence_reference)) >= 1) AND (length(btrim(evidence_reference)) <= 512)))),
    CONSTRAINT work_task_event_kind_ck CHECK ((event_kind = ANY (ARRAY['RAISED'::text, 'VIEWED'::text, 'ACKNOWLEDGED'::text, 'ASSIGNED'::text, 'REASSIGNED'::text, 'ACTION_RECORDED'::text, 'OUTCOME_OBSERVED'::text, 'REOPENED'::text, 'ESCALATED'::text, 'COMPLETED'::text, 'CANCELLED'::text, 'EXECUTION_OBSERVED'::text, 'DEFERRED'::text, 'REASSESSMENT_REQUIRED'::text, 'DEPENDENCY_HOLD_STARTED'::text, 'DEPENDENCY_RESUMED'::text, 'DEPENDENCY_HOLD_EXPIRED'::text, 'DEPENDENCY_INVALIDATED'::text, 'EXECUTION_PENDING'::text, 'EXECUTION_FAILED'::text, 'EXECUTION_COMPENSATED'::text, 'QUALIFICATION_INVALIDATED'::text]))),
    CONSTRAINT work_task_event_lineage_ck CHECK (((length(btrim(lineage_key)) >= 1) AND (length(btrim(lineage_key)) <= 200))),
    CONSTRAINT work_task_event_outcome_exclusive_ck CHECK (((event_kind = 'OUTCOME_OBSERVED'::text) OR ((outcome_kind IS NULL) AND (outcome_reference IS NULL)))),
    CONSTRAINT work_task_event_outcome_kind_ck CHECK (((outcome_kind IS NULL) OR (outcome_kind = ANY (ARRAY['OPERATIONAL'::text, 'SETTLED'::text, 'SETTLED_REVISED'::text, 'REGRESSION'::text, 'NO_IMPROVEMENT'::text, 'UNKNOWN'::text])))),
    CONSTRAINT work_task_event_outcome_reference_ck CHECK (((outcome_reference IS NULL) OR ((length(btrim(outcome_reference)) >= 1) AND (length(btrim(outcome_reference)) <= 512)))),
    CONSTRAINT work_task_event_outcome_shape_ck CHECK (((event_kind <> 'OUTCOME_OBSERVED'::text) OR ((outcome_kind IS NOT NULL) AND (outcome_reference IS NOT NULL) AND (action_kind IS NULL)))),
    CONSTRAINT work_task_event_reason_ck CHECK (((length(btrim(reason)) >= 1) AND (length(btrim(reason)) <= 1024))),
    CONSTRAINT work_task_event_sequence_ck CHECK ((sequence_no >= 1)),
    CONSTRAINT work_task_event_view_shape_ck CHECK (((event_kind <> 'VIEWED'::text) OR ((action_kind IS NULL) AND (action_evidence IS NULL) AND (outcome_kind IS NULL) AND (evidence_reference IS NULL)))),
    CONSTRAINT work_task_execution_shape_ck CHECK ((((event_kind = 'EXECUTION_OBSERVED'::text) AND (execution_receipt_id IS NOT NULL) AND (actor_user_id IS NULL) AND (actor_role_code IS NULL) AND (action_kind IS NULL) AND (action_evidence IS NULL) AND (outcome_kind IS NULL) AND (outcome_reference IS NULL)) OR ((event_kind <> 'EXECUTION_OBSERVED'::text) AND (execution_receipt_id IS NULL))))
);

CREATE TABLE platform.ad_provider_incident (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    platform_code text NOT NULL,
    store_id uuid,
    provenance_id uuid NOT NULL,
    incident_open boolean NOT NULL,
    observed_at timestamp with time zone NOT NULL,
    valid_until timestamp with time zone NOT NULL,
    evidence_reference text NOT NULL,
    CONSTRAINT ad_provider_incident_check CHECK ((observed_at < valid_until)),
    CONSTRAINT ad_provider_incident_evidence_reference_check CHECK (((length(btrim(evidence_reference)) >= 1) AND (length(btrim(evidence_reference)) <= 512)))
);

CREATE TABLE platform.ad_semantic_profile (
    id uuid NOT NULL,
    platform_code text NOT NULL,
    profile_version integer NOT NULL,
    native_object_kind text NOT NULL,
    control_level text NOT NULL,
    bidding_mode text NOT NULL,
    bid_field_present boolean NOT NULL,
    bid_currency_code text,
    bid_unit_code text NOT NULL,
    bid_precision integer,
    bid_step numeric(18,4),
    bid_minimum numeric(18,4),
    bid_maximum numeric(18,4),
    status_semantics jsonb DEFAULT '{}'::jsonb NOT NULL,
    error_class_semantics jsonb DEFAULT '{}'::jsonb NOT NULL,
    quota_semantics jsonb DEFAULT '{}'::jsonb NOT NULL,
    idempotency_semantics text NOT NULL,
    propagation_semantics text NOT NULL,
    readback_semantics text NOT NULL,
    correction_behaviour text NOT NULL,
    source_maturity text NOT NULL,
    verification_state text NOT NULL,
    last_verified_at timestamp with time zone,
    evidence_ref text,
    verified_source_title text,
    owner_label text NOT NULL,
    status text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    effective_to timestamp with time zone,
    CONSTRAINT ad_semantic_profile_bid_unit_ck CHECK ((bid_unit_code = ANY (ARRAY['CURRENCY_MAJOR'::text, 'CURRENCY_MINOR'::text, 'UNKNOWN'::text]))),
    CONSTRAINT ad_semantic_profile_bidding_mode_ck CHECK ((bidding_mode = ANY (ARRAY['MANUAL_BID'::text, 'AUTO_BID'::text, 'MIXED'::text, 'UNKNOWN'::text]))),
    CONSTRAINT ad_semantic_profile_bounds_ck CHECK (((bid_minimum IS NULL) OR (bid_maximum IS NULL) OR (bid_minimum <= bid_maximum))),
    CONSTRAINT ad_semantic_profile_control_level_ck CHECK ((control_level = ANY (ARRAY['CAMPAIGN'::text, 'AD_GROUP'::text, 'TARGET'::text, 'KEYWORD'::text, 'PLACEMENT'::text, 'UNKNOWN'::text]))),
    CONSTRAINT ad_semantic_profile_correction_ck CHECK ((correction_behaviour = ANY (ARRAY['APPEND_ONLY_CORRECTION'::text, 'IN_PLACE_RESTATEMENT'::text, 'UNKNOWN'::text]))),
    CONSTRAINT ad_semantic_profile_currency_ck CHECK (((bid_currency_code IS NULL) OR (bid_currency_code ~ '^[A-Z]{3}$'::text))),
    CONSTRAINT ad_semantic_profile_effective_period_ck CHECK (((effective_to IS NULL) OR (effective_to > created_at))),
    CONSTRAINT ad_semantic_profile_evidence_ck CHECK (((evidence_ref IS NULL) OR ((length(btrim(evidence_ref)) >= 1) AND (length(btrim(evidence_ref)) <= 512)))),
    CONSTRAINT ad_semantic_profile_fixture_ck CHECK (((source_maturity <> 'SYNTHETIC_FIXTURE'::text) OR (verification_state <> 'VERIFIED'::text))),
    CONSTRAINT ad_semantic_profile_idempotency_ck CHECK ((idempotency_semantics = ANY (ARRAY['VERIFIED_NATIVE_KEY'::text, 'NO_VERIFIED_IDEMPOTENCY'::text, 'EXPLICIT_NOT_APPLIED_EVIDENCE'::text, 'UNKNOWN'::text]))),
    CONSTRAINT ad_semantic_profile_maturity_ck CHECK ((source_maturity = ANY (ARRAY['OFFICIAL_VERIFIED'::text, 'OFFICIAL_UNVERIFIED'::text, 'SYNTHETIC_FIXTURE'::text]))),
    CONSTRAINT ad_semantic_profile_minimum_ck CHECK (((bid_minimum IS NULL) OR (bid_minimum >= (0)::numeric))),
    CONSTRAINT ad_semantic_profile_object_kind_ck CHECK ((native_object_kind = ANY (ARRAY['CAMPAIGN'::text, 'AD_GROUP'::text, 'TARGET'::text, 'KEYWORD'::text, 'PLACEMENT'::text, 'UNKNOWN'::text]))),
    CONSTRAINT ad_semantic_profile_owner_ck CHECK (((length(btrim(owner_label)) >= 1) AND (length(btrim(owner_label)) <= 128))),
    CONSTRAINT ad_semantic_profile_precision_ck CHECK (((bid_precision IS NULL) OR ((bid_precision >= 0) AND (bid_precision <= 4)))),
    CONSTRAINT ad_semantic_profile_propagation_ck CHECK ((propagation_semantics = ANY (ARRAY['SYNCHRONOUS'::text, 'EVENTUAL_BOUNDED'::text, 'EVENTUAL_UNBOUNDED'::text, 'UNKNOWN'::text]))),
    CONSTRAINT ad_semantic_profile_provenance_ck CHECK (((verification_state <> 'VERIFIED'::text) OR ((last_verified_at IS NOT NULL) AND (evidence_ref IS NOT NULL) AND (verified_source_title IS NOT NULL)))),
    CONSTRAINT ad_semantic_profile_readback_ck CHECK ((readback_semantics = ANY (ARRAY['EXACT_FIELD'::text, 'DERIVED_FIELD'::text, 'NOT_AVAILABLE'::text, 'UNKNOWN'::text]))),
    CONSTRAINT ad_semantic_profile_semantics_object_ck CHECK (((jsonb_typeof(status_semantics) = 'object'::text) AND (jsonb_typeof(error_class_semantics) = 'object'::text) AND (jsonb_typeof(quota_semantics) = 'object'::text))),
    CONSTRAINT ad_semantic_profile_status_ck CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'RETIRED'::text]))),
    CONSTRAINT ad_semantic_profile_step_ck CHECK (((bid_step IS NULL) OR (bid_step > (0)::numeric))),
    CONSTRAINT ad_semantic_profile_verification_ck CHECK ((verification_state = ANY (ARRAY['UNKNOWN'::text, 'UNVERIFIED'::text, 'VERIFIED'::text]))),
    CONSTRAINT ad_semantic_profile_verified_bid_ck CHECK (((verification_state <> 'VERIFIED'::text) OR (NOT bid_field_present) OR ((bid_currency_code IS NOT NULL) AND (bid_unit_code <> 'UNKNOWN'::text) AND (bid_precision IS NOT NULL) AND (bid_step IS NOT NULL) AND (bid_minimum IS NOT NULL) AND (bid_maximum IS NOT NULL) AND (bidding_mode <> 'UNKNOWN'::text) AND (readback_semantics <> ALL (ARRAY['NOT_AVAILABLE'::text, 'UNKNOWN'::text]))))),
    CONSTRAINT ad_semantic_profile_version_ck CHECK ((profile_version >= 1))
);

CREATE TABLE platform.ad_write_credential_attestation (
    id uuid NOT NULL,
    credential_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    marketplace_account_id uuid NOT NULL,
    store_ids uuid[] NOT NULL,
    verifier_user_id uuid NOT NULL,
    evidence_reference text NOT NULL,
    verified_at timestamp with time zone NOT NULL,
    valid_until timestamp with time zone NOT NULL,
    status text DEFAULT 'DRAFT'::text NOT NULL,
    CONSTRAINT ad_write_credential_attestation_check CHECK ((valid_until > verified_at)),
    CONSTRAINT ad_write_credential_attestation_evidence_reference_check CHECK ((length(btrim(evidence_reference)) > 0)),
    CONSTRAINT ad_write_credential_attestation_status_check CHECK ((status = ANY (ARRAY['DRAFT'::text, 'VERIFIED'::text, 'REVOKED'::text]))),
    CONSTRAINT ad_write_credential_attestation_store_ids_check CHECK ((cardinality(store_ids) > 0))
);

CREATE TABLE platform.capability_operation (
    id uuid NOT NULL,
    capability_id uuid NOT NULL,
    platform_code text NOT NULL,
    operation text NOT NULL,
    endpoint_id uuid NOT NULL,
    request_template text NOT NULL,
    accepted_pointer text,
    accepted_value jsonb,
    task_key_pointer text,
    task_status_pointer text,
    task_success_value text,
    task_failure_value text,
    task_pending_values text[] DEFAULT '{}'::text[] NOT NULL,
    observed_price_pointer text,
    observed_currency_pointer text,
    conditional_write_header text,
    version_token_header text,
    verification_state text NOT NULL,
    last_verified_at timestamp with time zone,
    evidence_ref text,
    verified_source_title text,
    owner_label text NOT NULL,
    status text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    ad_observed_unit_pointer text,
    ad_not_applied_pointer text,
    ad_not_applied_value jsonb,
    description_observed_text_pointer text,
    description_kiz_marked_pointer text,
    description_attribute_key text,
    description_response_binding jsonb,
    description_request_guard jsonb,
    CONSTRAINT ad_operation_pointer_shape_ck CHECK ((((ad_observed_unit_pointer IS NULL) OR (ad_observed_unit_pointer ~~ '/%'::text)) AND (((ad_not_applied_pointer IS NULL) AND (ad_not_applied_value IS NULL)) OR ((ad_not_applied_pointer ~~ '/%'::text) AND (ad_not_applied_value IS NOT NULL))))),
    CONSTRAINT capability_operation_acceptance_ck CHECK ((((accepted_value IS NULL) OR (jsonb_typeof(accepted_value) = ANY (ARRAY['string'::text, 'boolean'::text, 'number'::text]))) AND ((verification_state <> 'VERIFIED'::text) OR (operation <> ALL (ARRAY['APPLY'::text, 'RESTORE'::text])) OR ((accepted_pointer IS NOT NULL) AND (accepted_value IS NOT NULL))))),
    CONSTRAINT capability_operation_active_ck CHECK (((status <> 'ACTIVE'::text) OR (verification_state = 'VERIFIED'::text))),
    CONSTRAINT capability_operation_conditional_header_ck CHECK ((((conditional_write_header IS NULL) OR ((operation = 'RESTORE'::text) AND (conditional_write_header ~ '^[A-Za-z][A-Za-z0-9-]{0,63}$'::text))) AND ((version_token_header IS NULL) OR ((operation = 'READBACK'::text) AND (version_token_header = ANY (ARRAY['etag'::text, 'x-version-id'::text])))))),
    CONSTRAINT capability_operation_description_request_guard_check CHECK (((description_request_guard IS NULL) OR (jsonb_typeof(description_request_guard) = 'object'::text))),
    CONSTRAINT capability_operation_description_response_binding_check CHECK (((description_response_binding IS NULL) OR (jsonb_typeof(description_response_binding) = 'object'::text))),
    CONSTRAINT capability_operation_evidence_ck CHECK (((verification_state <> 'VERIFIED'::text) OR ((last_verified_at IS NOT NULL) AND (evidence_ref IS NOT NULL) AND (verified_source_title IS NOT NULL)))),
    CONSTRAINT capability_operation_operation_ck CHECK ((operation = ANY (ARRAY['APPLY'::text, 'STATUS_ENQUIRY'::text, 'READBACK'::text, 'RESTORE'::text]))),
    CONSTRAINT capability_operation_pointer_ck CHECK ((((accepted_pointer IS NULL) OR (accepted_pointer ~ '^(/[^/~]*(~[01][^/~]*)*)+$'::text)) AND ((task_key_pointer IS NULL) OR (task_key_pointer ~ '^(/[^/~]*(~[01][^/~]*)*)+$'::text)) AND ((task_status_pointer IS NULL) OR (task_status_pointer ~ '^(/[^/~]*(~[01][^/~]*)*)+$'::text)) AND ((observed_price_pointer IS NULL) OR (observed_price_pointer ~ '^(/[^/~]*(~[01][^/~]*)*)+$'::text)) AND ((observed_currency_pointer IS NULL) OR (observed_currency_pointer ~ '^(/[^/~]*(~[01][^/~]*)*)+$'::text)))),
    CONSTRAINT capability_operation_readback_shape_ck CHECK (((operation <> 'READBACK'::text) OR ((observed_price_pointer IS NOT NULL) AND (observed_currency_pointer IS NOT NULL)) OR (description_observed_text_pointer IS NOT NULL))),
    CONSTRAINT capability_operation_status_ck CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'RETIRED'::text]))),
    CONSTRAINT capability_operation_status_shape_ck CHECK (((operation <> 'STATUS_ENQUIRY'::text) OR ((task_status_pointer IS NOT NULL) AND (task_success_value IS NOT NULL) AND (task_failure_value IS NOT NULL) AND (task_success_value <> task_failure_value) AND (NOT (task_success_value = ANY (task_pending_values))) AND (NOT (task_failure_value = ANY (task_pending_values))) AND (cardinality(task_pending_values) <= 16) AND (array_position(task_pending_values, NULL::text) IS NULL)))),
    CONSTRAINT capability_operation_verification_ck CHECK ((verification_state = ANY (ARRAY['UNVERIFIED'::text, 'PARTIAL'::text, 'VERIFIED'::text, 'REJECTED'::text]))),
    CONSTRAINT description_operation_pointer_shape_ck CHECK ((((description_observed_text_pointer IS NULL) OR (description_observed_text_pointer ~~ '/%'::text)) AND ((description_kiz_marked_pointer IS NULL) OR (description_kiz_marked_pointer ~~ '/%'::text)) AND ((description_attribute_key IS NULL) OR (((length(btrim(description_attribute_key)) >= 1) AND (length(btrim(description_attribute_key)) <= 128)) AND (description_attribute_key !~ '[[:cntrl:]{}]'::text)))))
);

CREATE TABLE platform.capability_subject_status (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    platform_code text NOT NULL,
    capability_id uuid NOT NULL,
    marketplace_account_id uuid,
    store_id uuid,
    availability text NOT NULL,
    last_verified_at timestamp with time zone,
    evidence_ref text,
    verified_source_title text,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT capability_subject_status_availability_ck CHECK ((availability = ANY (ARRAY['UNKNOWN'::text, 'UNAVAILABLE'::text, 'AVAILABLE'::text]))),
    CONSTRAINT capability_subject_status_one_subject_ck CHECK ((num_nonnulls(marketplace_account_id, store_id) = 1)),
    CONSTRAINT capability_subject_status_provenance_ck CHECK (((availability = 'UNKNOWN'::text) OR ((last_verified_at IS NOT NULL) AND (evidence_ref IS NOT NULL) AND (verified_source_title IS NOT NULL))))
);

CREATE TABLE platform.capability_verification_event (
    id uuid NOT NULL,
    capability_id uuid,
    endpoint_id uuid,
    capability_subject_status_id uuid,
