CREATE TABLE platform.control_boundary_kind (
    kind text NOT NULL,
    ordinal integer NOT NULL,
    applicability text NOT NULL,
    source_note text NOT NULL,
    CONSTRAINT control_boundary_kind_applicability_ck CHECK ((applicability = ANY (ARRAY['APPLICABLE'::text, 'NOT_APPLICABLE'::text]))),
    CONSTRAINT control_boundary_kind_kind_ck CHECK ((kind ~ '^[A-Z][A-Z0-9_]{1,62}$'::text)),
    CONSTRAINT control_boundary_kind_ordinal_ck CHECK ((ordinal > 0))
);

CREATE TABLE platform.control_epoch (
    scope_kind text NOT NULL,
    scope_id uuid NOT NULL,
    epoch bigint NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT control_epoch_epoch_ck CHECK ((epoch > 0)),
    CONSTRAINT control_epoch_scope_kind_ck CHECK ((scope_kind = ANY (ARRAY['ORGANIZATION'::text, 'MARKETPLACE_ACCOUNT'::text, 'SERVICE_ACCOUNT'::text, 'JOB'::text])))
);

CREATE TABLE platform.control_epoch_membership_guard (
    guard_kind text NOT NULL,
    platform_code text NOT NULL,
