CREATE TABLE platform.control_route_inventory (
    schema_name text NOT NULL,
    table_name text NOT NULL,
    route_kind text NOT NULL,
    scope_kind text,
    routing_note text NOT NULL,
    CONSTRAINT control_route_inventory_route_kind_ck CHECK ((route_kind = ANY (ARRAY['SCOPE'::text, 'PLATFORM_FANOUT'::text, 'GLOBAL_FANOUT'::text, 'NO_ROUTE'::text]))),
    CONSTRAINT control_route_inventory_scope_ck CHECK ((((route_kind = 'SCOPE'::text) AND (scope_kind IS NOT NULL)) OR ((route_kind = ANY (ARRAY['PLATFORM_FANOUT'::text, 'GLOBAL_FANOUT'::text])) AND (scope_kind = 'JOB'::text)) OR ((route_kind = 'NO_ROUTE'::text) AND (scope_kind IS NULL)))),
    CONSTRAINT control_route_inventory_scope_kind_ck CHECK (((scope_kind IS NULL) OR (scope_kind = ANY (ARRAY['ORGANIZATION'::text, 'MARKETPLACE_ACCOUNT'::text, 'SERVICE_ACCOUNT'::text, 'JOB'::text]))))
);

CREATE TABLE platform.credential_metadata (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    marketplace_account_id uuid NOT NULL,
    code text NOT NULL,
    display_name text NOT NULL,
    purpose_code text NOT NULL,
    scope_mode text NOT NULL,
    secret_reference text NOT NULL,
    effective_from timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    replaces_credential_id uuid,
    status text NOT NULL,
    custodian_label text NOT NULL,
    last_used_at timestamp with time zone,
    verification_state text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT credential_metadata_code_ck CHECK ((code ~ '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$'::text)),
    CONSTRAINT credential_metadata_scope_mode_ck CHECK ((scope_mode = ANY (ARRAY['ACCOUNT'::text, 'STORE_SET'::text]))),
    CONSTRAINT credential_metadata_secret_reference_ck CHECK ((secret_reference ~ '^secret-ref://[a-z0-9][a-z0-9-]{0,62}(/[a-z0-9][a-z0-9._-]{0,62}){1,4}$'::text)),
    CONSTRAINT credential_metadata_status_ck CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'DISABLED'::text, 'REVOKED'::text]))),
    CONSTRAINT credential_metadata_verification_ck CHECK ((verification_state = 'UNVERIFIED'::text)),
    CONSTRAINT credential_metadata_window_ck CHECK ((effective_from < expires_at))
);

CREATE TABLE platform.credential_purpose (
    code text NOT NULL,
    display_name text NOT NULL,
    CONSTRAINT credential_purpose_code_ck CHECK ((code ~ '^[A-Z][A-Z0-9_]{1,62}$'::text))
);

CREATE TABLE platform.credential_store_scope (
