    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT credential_store_scope_reason_ck CHECK (((status = 'ACTIVE'::text) OR (reason IS NOT NULL))),
    CONSTRAINT credential_store_scope_status_ck CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'WITHDRAWN'::text])))
);

CREATE TABLE platform.feature_flag (
    id uuid NOT NULL,
    flag_code text NOT NULL,
    flag_kind text NOT NULL,
    scope_kind text NOT NULL,
    platform_code text,
    marketplace_account_id uuid,
    store_id uuid,
    capability_id uuid,
    scope_key text GENERATED ALWAYS AS (((((((((scope_kind || ':'::text) || COALESCE(platform_code, ''::text)) || ':'::text) || COALESCE((marketplace_account_id)::text, ''::text)) || ':'::text) || COALESCE((store_id)::text, ''::text)) || ':'::text) || COALESCE((capability_id)::text, ''::text))) STORED,
    state text NOT NULL,
    description text,
    reason text,
    status text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT feature_flag_code_ck CHECK ((flag_code ~ '^[a-z0-9]([a-z0-9._-]{0,61}[a-z0-9])?$'::text)),
    CONSTRAINT feature_flag_kind_ck CHECK ((flag_kind = ANY (ARRAY['OPERATIONAL'::text, 'WRITE_CAPABILITY'::text]))),
    CONSTRAINT feature_flag_retired_disabled_ck CHECK (((status = 'ACTIVE'::text) OR (state = 'DISABLED'::text))),
    CONSTRAINT feature_flag_scope_kind_ck CHECK ((scope_kind = ANY (ARRAY['GLOBAL'::text, 'PLATFORM'::text, 'MARKETPLACE_ACCOUNT'::text, 'STORE'::text, 'CAPABILITY'::text]))),
    CONSTRAINT feature_flag_scope_matrix_ck CHECK ((((scope_kind = 'GLOBAL'::text) AND (num_nonnulls(platform_code, marketplace_account_id, store_id, capability_id) = 0)) OR ((scope_kind = 'PLATFORM'::text) AND (platform_code IS NOT NULL) AND (num_nonnulls(marketplace_account_id, store_id, capability_id) = 0)) OR ((scope_kind = 'MARKETPLACE_ACCOUNT'::text) AND (marketplace_account_id IS NOT NULL) AND (platform_code IS NULL) AND (num_nonnulls(store_id, capability_id) = 0)) OR ((scope_kind = 'STORE'::text) AND (store_id IS NOT NULL) AND (platform_code IS NULL) AND (num_nonnulls(marketplace_account_id, capability_id) = 0)) OR ((scope_kind = 'CAPABILITY'::text) AND (capability_id IS NOT NULL) AND (platform_code IS NULL) AND (num_nonnulls(marketplace_account_id, store_id) = 0)))),
    CONSTRAINT feature_flag_state_ck CHECK ((state = ANY (ARRAY['DISABLED'::text, 'ENABLED'::text]))),
    CONSTRAINT feature_flag_status_ck CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'RETIRED'::text])))
);

CREATE TABLE platform.ingestion_job (
