    dataset_kind text DEFAULT 'UNKNOWN'::text NOT NULL,
    store_id uuid,
    CONSTRAINT ingestion_job_code_ck CHECK ((job_code ~ '^[a-z0-9]([a-z0-9._-]{0,61}[a-z0-9])?$'::text)),
    CONSTRAINT ingestion_job_dataset_kind_ck CHECK ((dataset_kind = ANY (ARRAY['LISTING'::text, 'LISTING_HEALTH'::text, 'PRICE'::text, 'STOCK'::text, 'TRAFFIC'::text, 'SALES'::text, 'RETURNS'::text, 'FINANCE'::text, 'ADVERTISING'::text, 'UNKNOWN'::text]))),
    CONSTRAINT ingestion_job_status_ck CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'PAUSED'::text, 'RETIRED'::text])))
);

CREATE TABLE platform.platform_api_profile (
    platform_code text NOT NULL,
    base_url text NOT NULL,
    request_timeout_ms integer NOT NULL,
    max_response_bytes bigint NOT NULL,
    verification_state text NOT NULL,
    last_verified_at timestamp with time zone,
    evidence_ref text,
    verified_source_title text,
    owner_label text NOT NULL,
    status text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT platform_api_profile_active_readiness_ck CHECK (((status <> 'ACTIVE'::text) OR (verification_state = 'VERIFIED'::text))),
    CONSTRAINT platform_api_profile_base_url_ck CHECK ((base_url ~ '^https://[a-z0-9][a-z0-9.-]{0,252}(:[0-9]{2,5})?$'::text)),
    CONSTRAINT platform_api_profile_provenance_ck CHECK (((verification_state <> 'VERIFIED'::text) OR ((last_verified_at IS NOT NULL) AND (evidence_ref IS NOT NULL) AND (verified_source_title IS NOT NULL)))),
    CONSTRAINT platform_api_profile_response_bytes_ck CHECK (((max_response_bytes >= 1024) AND (max_response_bytes <= 268435456))),
    CONSTRAINT platform_api_profile_status_ck CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'RETIRED'::text]))),
    CONSTRAINT platform_api_profile_timeout_ck CHECK (((request_timeout_ms >= 1000) AND (request_timeout_ms <= 120000))),
    CONSTRAINT platform_api_profile_verification_ck CHECK ((verification_state = ANY (ARRAY['UNKNOWN'::text, 'UNVERIFIED'::text, 'VERIFIED'::text])))
);

CREATE TABLE platform.platform_auth_header (
    id uuid NOT NULL,
    platform_code text NOT NULL,
    header_name text NOT NULL,
    value_source text NOT NULL,
    value_template text NOT NULL,
    credential_purpose text NOT NULL,
    ordinal integer NOT NULL,
    verification_state text NOT NULL,
    last_verified_at timestamp with time zone,
    evidence_ref text,
    verified_source_title text,
    owner_label text NOT NULL,
    status text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT platform_auth_header_active_readiness_ck CHECK (((status <> 'ACTIVE'::text) OR (verification_state = 'VERIFIED'::text))),
    CONSTRAINT platform_auth_header_name_ck CHECK ((header_name ~ '^[A-Za-z][A-Za-z0-9-]{0,63}$'::text)),
    CONSTRAINT platform_auth_header_ordinal_ck CHECK ((ordinal > 0)),
    CONSTRAINT platform_auth_header_provenance_ck CHECK (((verification_state <> 'VERIFIED'::text) OR ((last_verified_at IS NOT NULL) AND (evidence_ref IS NOT NULL) AND (verified_source_title IS NOT NULL)))),
    CONSTRAINT platform_auth_header_source_ck CHECK ((value_source = ANY (ARRAY['RESOLVED_SECRET'::text, 'ACCOUNT_NATIVE_KEY'::text, 'LITERAL'::text]))),
    CONSTRAINT platform_auth_header_status_ck CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'RETIRED'::text]))),
    CONSTRAINT platform_auth_header_template_ck CHECK (
CASE value_source
    WHEN 'LITERAL'::text THEN (value_template !~ '\{'::text)
    ELSE (value_template ~ '^[!-~ ]{0,32}\{value\}[!-~ ]{0,32}$'::text)
END),
    CONSTRAINT platform_auth_header_verification_ck CHECK ((verification_state = ANY (ARRAY['UNKNOWN'::text, 'UNVERIFIED'::text, 'VERIFIED'::text])))
);

CREATE TABLE platform.platform_capability (
    id uuid NOT NULL,
    platform_code text NOT NULL,
    capability_code text NOT NULL,
    display_name text NOT NULL,
    description text,
    applies_to text NOT NULL,
    read_write_class text NOT NULL,
    subscription_required text NOT NULL,
    verification_state text NOT NULL,
    last_verified_at timestamp with time zone,
    evidence_ref text,
    verified_source_title text,
    owner_label text NOT NULL,
    contract_test_status text NOT NULL,
    deprecated_at timestamp with time zone,
    replacement_capability_id uuid,
    status text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    write_result_model text DEFAULT 'UNKNOWN'::text NOT NULL,
    CONSTRAINT platform_capability_applies_to_ck CHECK ((applies_to = ANY (ARRAY['MARKETPLACE_ACCOUNT'::text, 'STORE'::text, 'UNKNOWN'::text]))),
    CONSTRAINT platform_capability_capability_code_ck CHECK ((capability_code ~ '^[a-z0-9]([a-z0-9._-]{0,61}[a-z0-9])?$'::text)),
    CONSTRAINT platform_capability_contract_test_ck CHECK ((contract_test_status = ANY (ARRAY['NOT_IMPLEMENTED'::text, 'FAILING'::text, 'PASSING'::text]))),
    CONSTRAINT platform_capability_provenance_ck CHECK (((verification_state <> 'VERIFIED'::text) OR ((last_verified_at IS NOT NULL) AND (evidence_ref IS NOT NULL) AND (verified_source_title IS NOT NULL)))),
    CONSTRAINT platform_capability_read_model_ck CHECK (((read_write_class <> 'READ'::text) OR (write_result_model = 'UNKNOWN'::text))),
    CONSTRAINT platform_capability_read_write_ck CHECK ((read_write_class = ANY (ARRAY['READ'::text, 'WRITE'::text]))),
    CONSTRAINT platform_capability_status_ck CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'RETIRED'::text]))),
    CONSTRAINT platform_capability_subscription_ck CHECK ((subscription_required = ANY (ARRAY['YES'::text, 'NO'::text, 'UNKNOWN'::text]))),
    CONSTRAINT platform_capability_verification_ck CHECK ((verification_state = ANY (ARRAY['UNKNOWN'::text, 'UNVERIFIED'::text, 'VERIFIED'::text]))),
    CONSTRAINT platform_capability_write_model_required_ck CHECK (((read_write_class <> 'WRITE'::text) OR (verification_state <> 'VERIFIED'::text) OR (write_result_model <> 'UNKNOWN'::text))),
    CONSTRAINT platform_capability_write_result_model_ck CHECK ((write_result_model = ANY (ARRAY['SYNCHRONOUS'::text, 'ASYNCHRONOUS_TASK'::text, 'UNKNOWN'::text])))
);

CREATE TABLE platform.platform_endpoint (
    id uuid NOT NULL,
    platform_code text NOT NULL,
    endpoint_code text NOT NULL,
    api_version text NOT NULL,
    http_method text,
    path_template text,
    capability_id uuid,
    read_write_class text NOT NULL,
    pagination_model text NOT NULL,
    rate_limit_per_minute integer,
    rate_limit_note text,
    quota_note text,
    idempotency_support text NOT NULL,
    late_data_behavior text,
    freshness_expectation text,
    business_key_note text,
    schema_version text,
    deprecated_at timestamp with time zone,
    replacement_endpoint_id uuid,
    verification_state text NOT NULL,
    last_verified_at timestamp with time zone,
    evidence_ref text,
    verified_source_title text,
    owner_label text NOT NULL,
    contract_test_status text NOT NULL,
    status text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    operation_function text DEFAULT 'UNDECLARED'::text NOT NULL,
    query_template text,
    body_template text,
    response_content_type text,
    continuation_pointer text,
    CONSTRAINT platform_endpoint_body_method_ck CHECK (((body_template IS NULL) OR (http_method = ANY (ARRAY['POST'::text, 'PUT'::text, 'PATCH'::text])))),
    CONSTRAINT platform_endpoint_body_template_ck CHECK (((body_template IS NULL) OR (length(body_template) <= 4096))),
    CONSTRAINT platform_endpoint_continuation_pointer_ck CHECK (((continuation_pointer IS NULL) OR (continuation_pointer ~ '^(/[^/~]*(~[01][^/~]*)*)+$'::text))),
    CONSTRAINT platform_endpoint_contract_test_ck CHECK ((contract_test_status = ANY (ARRAY['NOT_IMPLEMENTED'::text, 'FAILING'::text, 'PASSING'::text]))),
    CONSTRAINT platform_endpoint_endpoint_code_ck CHECK ((endpoint_code ~ '^[a-z0-9]([a-z0-9._-]{0,61}[a-z0-9])?$'::text)),
    CONSTRAINT platform_endpoint_function_ck CHECK ((operation_function = ANY (ARRAY['UNDECLARED'::text, 'READ_DATA'::text, 'PRICE_APPLY'::text, 'PRICE_STATUS'::text, 'PRICE_READBACK'::text, 'PRICE_RESTORE'::text, 'AD_BID_APPLY'::text, 'AD_BID_STATUS'::text, 'AD_BID_READBACK'::text, 'AD_BID_RESTORE'::text, 'DESCRIPTION_APPLY'::text, 'DESCRIPTION_STATUS'::text, 'DESCRIPTION_READBACK'::text, 'DESCRIPTION_RESTORE'::text]))),
    CONSTRAINT platform_endpoint_http_method_ck CHECK (((http_method IS NULL) OR (http_method = ANY (ARRAY['GET'::text, 'POST'::text, 'PUT'::text, 'PATCH'::text, 'DELETE'::text])))),
    CONSTRAINT platform_endpoint_idempotency_ck CHECK ((idempotency_support = ANY (ARRAY['YES'::text, 'NO'::text, 'UNKNOWN'::text]))),
    CONSTRAINT platform_endpoint_pagination_ck CHECK ((pagination_model = ANY (ARRAY['CURSOR'::text, 'OFFSET'::text, 'PAGE'::text, 'DATE_WINDOW'::text, 'NONE'::text, 'UNKNOWN'::text]))),
    CONSTRAINT platform_endpoint_provenance_ck CHECK (((verification_state <> 'VERIFIED'::text) OR ((last_verified_at IS NOT NULL) AND (evidence_ref IS NOT NULL) AND (verified_source_title IS NOT NULL)))),
    CONSTRAINT platform_endpoint_query_template_ck CHECK (((query_template IS NULL) OR (length(query_template) <= 1024))),
    CONSTRAINT platform_endpoint_rate_limit_ck CHECK (((rate_limit_per_minute IS NULL) OR (rate_limit_per_minute > 0))),
    CONSTRAINT platform_endpoint_read_write_ck CHECK ((read_write_class = ANY (ARRAY['READ'::text, 'WRITE'::text]))),
    CONSTRAINT platform_endpoint_response_content_type_ck CHECK (((response_content_type IS NULL) OR (response_content_type ~ '^[a-z]+/[a-z0-9.+-]+$'::text))),
    CONSTRAINT platform_endpoint_status_ck CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'RETIRED'::text]))),
    CONSTRAINT platform_endpoint_verification_ck CHECK ((verification_state = ANY (ARRAY['UNKNOWN'::text, 'UNVERIFIED'::text, 'VERIFIED'::text])))
);

CREATE TABLE platform.platform_permission_requirement (
    id uuid NOT NULL,
    platform_code text NOT NULL,
    capability_id uuid,
    endpoint_id uuid,
    requirement_kind text NOT NULL,
    external_code text NOT NULL,
    description text,
    verification_state text NOT NULL,
    last_verified_at timestamp with time zone,
    evidence_ref text,
    verified_source_title text,
    status text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT platform_permission_requirement_kind_ck CHECK ((requirement_kind = ANY (ARRAY['API_ROLE'::text, 'OAUTH_SCOPE'::text, 'SUBSCRIPTION'::text, 'PLAN'::text, 'OTHER'::text, 'UNKNOWN'::text]))),
    CONSTRAINT platform_permission_requirement_one_target_ck CHECK ((num_nonnulls(capability_id, endpoint_id) = 1)),
    CONSTRAINT platform_permission_requirement_provenance_ck CHECK (((verification_state <> 'VERIFIED'::text) OR ((last_verified_at IS NOT NULL) AND (evidence_ref IS NOT NULL) AND (verified_source_title IS NOT NULL)))),
    CONSTRAINT platform_permission_requirement_status_ck CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'RETIRED'::text]))),
    CONSTRAINT platform_permission_requirement_verification_ck CHECK ((verification_state = ANY (ARRAY['UNKNOWN'::text, 'UNVERIFIED'::text, 'VERIFIED'::text])))
);

CREATE TABLE platform.registry_verification_case (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    marketplace_account_id uuid NOT NULL,
    capability_id uuid NOT NULL,
    endpoint_ids uuid[] NOT NULL,
    auth_header_ids uuid[] NOT NULL,
    official_source_url text NOT NULL,
    official_source_sha256 text NOT NULL,
    account_evidence_ref text NOT NULL,
    account_evidence_sha256 text NOT NULL,
    evidence_class text NOT NULL,
    tested_at timestamp with time zone NOT NULL,
    valid_until timestamp with time zone NOT NULL,
    submitted_by_user_id uuid NOT NULL,
    reviewed_by_user_id uuid,
    submitted_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    reviewed_at timestamp with time zone,
    state text DEFAULT 'SUBMITTED'::text NOT NULL,
    configuration_snapshot jsonb NOT NULL,
    submitted_configuration_snapshot jsonb CONSTRAINT registry_verification_case_submitted_configuration_sna_not_null NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT registry_verification_case_account_evidence_ref_check CHECK ((((length(account_evidence_ref) >= 13) AND (length(account_evidence_ref) <= 412)) AND (account_evidence_ref ~ '^evidence://[a-z0-9][a-z0-9./_-]+$'::text))),
    CONSTRAINT registry_verification_case_auth_header_ids_check CHECK ((((cardinality(auth_header_ids) >= 1) AND (cardinality(auth_header_ids) <= 16)) AND (array_position(auth_header_ids, NULL::uuid) IS NULL))),
    CONSTRAINT registry_verification_case_check CHECK (((official_source_sha256 ~ '^[0-9a-f]{64}$'::text) AND (account_evidence_sha256 ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT registry_verification_case_check1 CHECK (((tested_at < valid_until) AND (valid_until <= (tested_at + '30 days'::interval)))),
    CONSTRAINT registry_verification_case_check2 CHECK (((reviewed_by_user_id IS NULL) OR (reviewed_by_user_id <> submitted_by_user_id))),
    CONSTRAINT registry_verification_case_check3 CHECK (((state <> 'APPROVED'::text) OR ((evidence_class = 'REAL_ACCOUNT'::text) AND (reviewed_by_user_id IS NOT NULL) AND (reviewed_at IS NOT NULL)))),
    CONSTRAINT registry_verification_case_endpoint_ids_check CHECK ((((cardinality(endpoint_ids) >= 1) AND (cardinality(endpoint_ids) <= 32)) AND (array_position(endpoint_ids, NULL::uuid) IS NULL))),
    CONSTRAINT registry_verification_case_evidence_class_check CHECK ((evidence_class = ANY (ARRAY['REAL_ACCOUNT'::text, 'PROTOCOL_FIXTURE'::text]))),
    CONSTRAINT registry_verification_case_official_source_url_check CHECK (((length(official_source_url) <= 2048) AND (official_source_url ~ '^https://[a-z0-9.-]+(/[A-Za-z0-9._~%/-]*)?$'::text))),
    CONSTRAINT registry_verification_case_state_check CHECK ((state = ANY (ARRAY['SUBMITTED'::text, 'APPROVED'::text, 'REJECTED'::text, 'REVOKED'::text])))
);

CREATE TABLE raw.ad_bid_response_observation (
    id uuid NOT NULL,
    command_id uuid NOT NULL,
    attempt_id uuid NOT NULL,
    raw_content_id uuid NOT NULL,
    request_digest text NOT NULL,
    http_status integer NOT NULL,
    response_headers jsonb NOT NULL,
    evidence_class text NOT NULL,
    response_complete boolean NOT NULL,
    operation_id uuid,
    operation_version bigint,
    observed_bid numeric(18,4),
    observed_currency text,
    observed_unit text,
    version_token text,
    observed_at timestamp with time zone NOT NULL,
    correlation_id text NOT NULL,
    CONSTRAINT ad_bid_response_observation_evidence_class_check CHECK ((evidence_class = ANY (ARRAY['PROTOCOL_FIXTURE'::text, 'PROVIDER_RESPONSE'::text]))),
    CONSTRAINT ad_bid_response_observation_http_status_check CHECK (((http_status >= 100) AND (http_status <= 599))),
    CONSTRAINT ad_bid_response_observation_request_digest_check CHECK ((request_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT ad_bid_response_observation_response_headers_check CHECK ((jsonb_typeof(response_headers) = 'object'::text))
);

CREATE TABLE raw.lc_description_response_observation (
    id uuid NOT NULL,
    command_id uuid NOT NULL,
    attempt_id uuid NOT NULL,
    raw_content_id uuid NOT NULL,
