    operation_version bigint,
    observed_text_digest text,
    observed_kiz_marked boolean,
    version_token text,
    observed_at timestamp with time zone NOT NULL,
    correlation_id text NOT NULL,
    retry_timing jsonb,
    identity_binding jsonb,
    CONSTRAINT lc_description_response_observation_evidence_class_check CHECK ((evidence_class = ANY (ARRAY['PROTOCOL_FIXTURE'::text, 'PROVIDER_RESPONSE'::text]))),
    CONSTRAINT lc_description_response_observation_http_status_check CHECK (((http_status >= 100) AND (http_status <= 599))),
    CONSTRAINT lc_description_response_observation_request_digest_check CHECK ((request_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT lc_description_response_observation_response_headers_check CHECK ((jsonb_typeof(response_headers) = 'object'::text))
);

CREATE TABLE raw.price_response_observation (
    id uuid NOT NULL,
    command_id uuid NOT NULL,
    attempt_id uuid NOT NULL,
    raw_content_id uuid NOT NULL,
    request_digest text NOT NULL,
    http_status integer NOT NULL,
