    observed_currency text,
    version_token text,
    observed_at timestamp with time zone NOT NULL,
    correlation_id text NOT NULL,
    CONSTRAINT price_response_observation_evidence_class_check CHECK ((evidence_class = ANY (ARRAY['PROTOCOL_FIXTURE'::text, 'PROVIDER_RESPONSE'::text]))),
    CONSTRAINT price_response_observation_http_status_check CHECK (((http_status >= 100) AND (http_status <= 599))),
    CONSTRAINT price_response_observation_request_digest_check CHECK ((request_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT price_response_observation_response_headers_check CHECK ((jsonb_typeof(response_headers) = 'object'::text))
);

CREATE TABLE raw.raw_acquisition_observation (
    id uuid NOT NULL,
    run_id uuid NOT NULL,
    logical_unit_id uuid NOT NULL,
    content_id uuid NOT NULL,
    call_seq integer NOT NULL,
    native_status text NOT NULL,
    outcome_class text NOT NULL,
    ingestion_time timestamp with time zone DEFAULT now() NOT NULL,
    response_complete boolean DEFAULT true NOT NULL,
    transport_failure_code text,
    authority_decision_id uuid,
    response_headers jsonb DEFAULT '{}'::jsonb NOT NULL,
    pagination_outcome text DEFAULT 'UNASSESSED'::text NOT NULL,
    CONSTRAINT raw_acquisition_observation_call_seq_ck CHECK ((call_seq > 0)),
    CONSTRAINT raw_acquisition_observation_outcome_ck CHECK ((outcome_class = ANY (ARRAY['SUCCESS_BYTES'::text, 'BUSINESS_FAILURE_BYTES'::text, 'UNKNOWN_STATE'::text]))),
    CONSTRAINT raw_acquisition_observation_pagination_outcome_check CHECK ((pagination_outcome = ANY (ARRAY['UNASSESSED'::text, 'END'::text, 'NEXT'::text, 'UNKNOWN_RESULT'::text, 'SCHEMA_DRIFT'::text, 'UNREADABLE'::text, 'CONFIG_INVALID'::text, 'RETRY_LATER'::text]))),
    CONSTRAINT raw_acquisition_observation_response_headers_check CHECK ((jsonb_typeof(response_headers) = 'object'::text))
);

CREATE TABLE raw.raw_content (
    id uuid NOT NULL,
    hash_algorithm text NOT NULL,
    hash_value text NOT NULL,
    byte_length bigint NOT NULL,
    object_ref text NOT NULL,
    first_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT raw_content_byte_length_ck CHECK ((byte_length >= 0)),
    CONSTRAINT raw_content_hash_algorithm_ck CHECK ((hash_algorithm = 'SHA256'::text)),
    CONSTRAINT raw_content_hash_value_ck CHECK ((hash_value ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT raw_content_object_ref_ck CHECK ((object_ref ~ '^object-ref://[a-z0-9][a-z0-9-]{0,62}(/[a-z0-9][a-z0-9._-]{0,62}){1,6}$'::text))
);

CREATE TABLE raw.raw_logical_unit (
    id uuid NOT NULL,
    job_id uuid NOT NULL,
    marketplace_account_id uuid NOT NULL,
    unit_kind text NOT NULL,
    source_unit_key text NOT NULL,
    source_time timestamp with time zone,
    first_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT raw_logical_unit_kind_ck CHECK ((unit_kind ~ '^[A-Z][A-Z0-9_]{1,62}$'::text))
);

CREATE TABLE staging.canonical_field (
    dataset_kind text NOT NULL,
    field_name text NOT NULL,
    value_kind text NOT NULL,
    requirement text NOT NULL,
    description text NOT NULL,
    ordinal integer NOT NULL,
    CONSTRAINT canonical_field_dataset_ck CHECK ((dataset_kind = ANY (ARRAY['LISTING'::text, 'LISTING_HEALTH'::text, 'PRICE'::text, 'STOCK'::text, 'TRAFFIC'::text, 'SALES'::text, 'RETURNS'::text, 'FINANCE'::text, 'ADVERTISING'::text]))),
    CONSTRAINT canonical_field_name_ck CHECK ((field_name ~ '^[a-z][a-zA-Z0-9]{0,63}$'::text)),
    CONSTRAINT canonical_field_requirement_ck CHECK ((requirement = ANY (ARRAY['REQUIRED'::text, 'OPTIONAL'::text]))),
    CONSTRAINT canonical_field_value_kind_ck CHECK ((value_kind = ANY (ARRAY['TEXT'::text, 'INTEGER'::text, 'DECIMAL'::text, 'INSTANT'::text, 'BOOLEAN'::text])))
);

CREATE TABLE staging.import_batch (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    dataset_kind text NOT NULL,
    schema_profile_id uuid NOT NULL,
    content_id uuid NOT NULL,
    declared_file_name text NOT NULL,
    declared_media_type text NOT NULL,
    state text NOT NULL,
    rejection_code text,
    total_row_count integer,
    accepted_row_count integer,
    rejected_row_count integer,
    source_time timestamp with time zone,
    effective_from timestamp with time zone,
    submitted_by_user_id uuid NOT NULL,
    submitted_at timestamp with time zone NOT NULL,
    approved_by_user_id uuid,
    approved_at timestamp with time zone,
    applied_at timestamp with time zone,
    applied_row_count integer,
    supersedes_batch_id uuid,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT import_batch_applied_ck CHECK (((state = ANY (ARRAY['APPLIED'::text, 'SUPERSEDED'::text])) = (applied_at IS NOT NULL))),
    CONSTRAINT import_batch_applied_count_ck CHECK ((((state = ANY (ARRAY['APPLIED'::text, 'SUPERSEDED'::text])) = (applied_row_count IS NOT NULL)) AND ((applied_row_count IS NULL) OR (applied_row_count = accepted_row_count)))),
    CONSTRAINT import_batch_approval_ck CHECK (((state <> ALL (ARRAY['APPROVED'::text, 'APPLIED'::text])) OR ((approved_by_user_id IS NOT NULL) AND (approved_at IS NOT NULL)))),
    CONSTRAINT import_batch_counts_ck CHECK (((total_row_count IS NULL) OR ((total_row_count >= 0) AND (accepted_row_count IS NOT NULL) AND (accepted_row_count >= 0) AND (rejected_row_count IS NOT NULL) AND (rejected_row_count >= 0) AND ((accepted_row_count + rejected_row_count) = total_row_count)))),
    CONSTRAINT import_batch_dataset_ck CHECK ((dataset_kind = ANY (ARRAY['PURCHASE_COST'::text, 'INTERNAL_STOCK'::text, 'FINANCE_INPUT'::text]))),
    CONSTRAINT import_batch_effective_ck CHECK (((state <> ALL (ARRAY['APPROVED'::text, 'APPLIED'::text])) OR (effective_from IS NOT NULL))),
    CONSTRAINT import_batch_file_name_ck CHECK ((declared_file_name ~ '^[A-Za-z0-9][A-Za-z0-9 ._-]{0,127}\.(csv|xlsx)$'::text)),
    CONSTRAINT import_batch_media_type_ck CHECK ((declared_media_type = ANY (ARRAY['text/csv'::text, 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'::text]))),
    CONSTRAINT import_batch_rejection_ck CHECK (((state = 'REJECTED'::text) = (rejection_code IS NOT NULL))),
    CONSTRAINT import_batch_state_ck CHECK ((state = ANY (ARRAY['RECEIVED'::text, 'VALIDATED'::text, 'REJECTED'::text, 'APPROVED'::text, 'APPLIED'::text, 'SUPERSEDED'::text])))
);

CREATE TABLE staging.import_row (
    id uuid NOT NULL,
    batch_id uuid NOT NULL,
    row_number integer NOT NULL,
    parsed_values jsonb NOT NULL,
    validation_state text NOT NULL,
    rejection_code text,
    rejection_detail text,
    target_key text,
    CONSTRAINT import_row_number_ck CHECK ((row_number > 0)),
    CONSTRAINT import_row_rejection_ck CHECK (((validation_state = 'REJECTED'::text) = (rejection_code IS NOT NULL))),
    CONSTRAINT import_row_state_ck CHECK ((validation_state = ANY (ARRAY['ACCEPTED'::text, 'REJECTED'::text]))),
    CONSTRAINT import_row_values_ck CHECK ((jsonb_typeof(parsed_values) = 'object'::text))
);

CREATE TABLE staging.import_schema_profile (
    id uuid NOT NULL,
    organization_id uuid NOT NULL,
    dataset_kind text NOT NULL,
    profile_code text NOT NULL,
    profile_version integer NOT NULL,
    display_name text NOT NULL,
    column_contract jsonb NOT NULL,
    owner_label text NOT NULL,
    status text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT import_schema_profile_code_ck CHECK ((profile_code ~ '^[a-z0-9]([a-z0-9._-]{0,61}[a-z0-9])?$'::text)),
    CONSTRAINT import_schema_profile_contract_ck CHECK (((jsonb_typeof(column_contract) = 'array'::text) AND (jsonb_array_length(column_contract) > 0))),
    CONSTRAINT import_schema_profile_dataset_ck CHECK ((dataset_kind = ANY (ARRAY['PURCHASE_COST'::text, 'INTERNAL_STOCK'::text, 'FINANCE_INPUT'::text]))),
    CONSTRAINT import_schema_profile_status_ck CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'RETIRED'::text]))),
    CONSTRAINT import_schema_profile_version_ck CHECK ((profile_version > 0))
);

CREATE TABLE staging.normalization_checkpoint (
    job_id uuid NOT NULL,
    last_ingestion_time timestamp with time zone,
    last_observation_id uuid,
    processed_count bigint DEFAULT 0 NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT normalization_checkpoint_count_ck CHECK ((processed_count >= 0)),
    CONSTRAINT normalization_checkpoint_pairing_ck CHECK ((num_nonnulls(last_ingestion_time, last_observation_id) <> 1))
);

CREATE TABLE staging.normalization_field (
    mapping_id uuid NOT NULL,
    dataset_kind text NOT NULL,
    field_name text NOT NULL,
    source_pointer text NOT NULL,
    CONSTRAINT normalization_field_source_pointer_ck CHECK ((source_pointer ~ '^(/[^/~]*(~[01][^/~]*)*)+$'::text))
);

CREATE TABLE staging.normalization_mapping (
    id uuid NOT NULL,
    platform_code text NOT NULL,
    dataset_kind text NOT NULL,
    mapping_version integer NOT NULL,
    record_pointer text NOT NULL,
    verification_state text NOT NULL,
    last_verified_at timestamp with time zone,
    evidence_ref text,
    verified_source_title text,
    owner_label text NOT NULL,
    status text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT normalization_mapping_active_readiness_ck CHECK (((status <> 'ACTIVE'::text) OR (verification_state = 'VERIFIED'::text))),
    CONSTRAINT normalization_mapping_dataset_ck CHECK ((dataset_kind = ANY (ARRAY['LISTING'::text, 'LISTING_HEALTH'::text, 'PRICE'::text, 'STOCK'::text, 'TRAFFIC'::text, 'SALES'::text, 'RETURNS'::text, 'FINANCE'::text, 'ADVERTISING'::text]))),
    CONSTRAINT normalization_mapping_provenance_ck CHECK (((verification_state <> 'VERIFIED'::text) OR ((last_verified_at IS NOT NULL) AND (evidence_ref IS NOT NULL) AND (verified_source_title IS NOT NULL)))),
    CONSTRAINT normalization_mapping_record_pointer_ck CHECK ((record_pointer ~ '^(/[^/~]*(~[01][^/~]*)*)*$'::text)),
    CONSTRAINT normalization_mapping_status_ck CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'RETIRED'::text]))),
    CONSTRAINT normalization_mapping_verification_ck CHECK ((verification_state = ANY (ARRAY['UNKNOWN'::text, 'UNVERIFIED'::text, 'VERIFIED'::text]))),
    CONSTRAINT normalization_mapping_version_ck CHECK ((mapping_version > 0))
);

CREATE TABLE staging.schema_drift_observation (
    id uuid NOT NULL,
    job_id uuid NOT NULL,
    mapping_id uuid NOT NULL,
    unmapped_pointer text NOT NULL,
    first_observation_id uuid NOT NULL,
    first_seen_at timestamp with time zone NOT NULL,
    last_seen_at timestamp with time zone NOT NULL,
    occurrence_count bigint NOT NULL,
    state text NOT NULL,
    acknowledged_by_user_id uuid,
    acknowledged_at timestamp with time zone,
    acknowledgement_note text,
    version bigint DEFAULT 0 NOT NULL,
    CONSTRAINT schema_drift_observation_acknowledgement_ck CHECK (((state = 'ACKNOWLEDGED'::text) = ((acknowledged_by_user_id IS NOT NULL) AND (acknowledged_at IS NOT NULL) AND (acknowledgement_note IS NOT NULL)))),
    CONSTRAINT schema_drift_observation_count_ck CHECK ((occurrence_count > 0)),
    CONSTRAINT schema_drift_observation_state_ck CHECK ((state = ANY (ARRAY['OPEN'::text, 'ACKNOWLEDGED'::text])))
);
